/** 
 * Determines whether a given delta is a major edit. A "major edit" is defined as something that adds more than 9 words.
 * @param delta the delta to check
 * @return whether this is a major edit
 */
public static boolean analyzeDelta(String delta){
  if (delta.contains("please do not remove or change this afd message until the issue is settled"))   return false;
  if (delta.contains("end of afd message, feel free to edit beyond this point"))   return false;
  if (delta.contains("{{afdm|"))   return false;
  if (delta.contains("{{proposed deletion/dated|"))   return false;
  if (delta.contains("{{prod blp/dated|"))   return false;
  if (delta.contains("{{infobox "))   return false;
  StringBuilder temp=new StringBuilder(delta);
  for (int i=temp.indexOf("[["); i >= 0; i=temp.indexOf("[[")) {
    int j=temp.indexOf("]]",i);
    if (j < 0)     break;
    List<String> parsedlink=WikitextUtils.parseWikilink(temp.substring(i,j + 2));
    if (parsedlink.get(0).length() > 100)     break;
 else     if (enWiki.namespace(parsedlink.get(0)) == Wiki.CATEGORY_NAMESPACE)     temp.delete(i,j + 2);
 else     temp.replace(i,j + 2,parsedlink.get(1));
  }
  String delta2=temp.toString().replace("&lt;","<");
  delta2=delta2.replace("&gt;",">");
  StringTokenizer tk=new StringTokenizer(delta2,"<>{}|=");
  while (tk.hasMoreTokens()) {
    String token=tk.nextToken();
    if (token.split("\\s").length > 9)     return true;
  }
  return false;
}

