    }
 else {
      call=c.prepareStatement(sql);
    }
    if (params != null && params.length > 0) {
      for (int i=0; i < params.length; i++) {
        if (params[i] != null) {
          call.setObject(i + 1,params[i]);
        }
 else {
          call.setNull(i + 1,types[i]);
        }
      }
    }
    return call;
  }
 catch (  SQLException e) {
