@SuppressLint("WrongThread") @WorkerThread @Nullable public static String getDefaultUserAgentStringSafe(final Context context){
  if (Looper.myLooper() == Looper.getMainLooper()) {
    return getDefaultUserAgentString(context);
  }
  final Handler handler=new Handler(Looper.getMainLooper());
  FutureTask<String> task=new FutureTask<>(() -> getDefaultUserAgentString(context));
  try {
    handler.post(task);
    return task.get(1,TimeUnit.SECONDS);
  }
 catch (  InterruptedException e) {
    throw new RuntimeException(e);
  }
catch (  ExecutionException e) {
    throw new RuntimeException(e);
  }
catch (  TimeoutException e) {
    throw new RuntimeException(e);
  }
 finally {
    handler.removeCallbacksAndMessages(null);
  }
}

