  }
  List<String> profiles=asList(element.getAnnotation(Profile.class).value());
  for (  String profile : profiles) {
    if (profile != null && profile.length() > 0 && profile.charAt(0) == '!') {
      if (!activeProfiles.contains(profile.substring(1))) {
