@Override public final AnnotationVisitor visitTypeAnnotation(int typeRef,TypePath typePath,final String desc,final boolean visible){
  ByteVector bv=new ByteVector();
  AnnotationWriter.putTarget(typeRef,typePath,bv);
  bv.putShort(this.newUTF8(desc)).putShort(0);
  AnnotationWriter aw=new AnnotationWriter(this,true,bv,bv,bv.length - 2);
  if (visible) {
    aw.next=this.tanns;
    this.tanns=aw;
  }
 else {
    aw.next=this.itanns;
    this.itanns=aw;
  }
  return aw;
}

