@Test public void testKnn() throws DaoException {
  int numNeighbors=100;
  Point query=makePoint();
  Scoreboard<Point> actual=new Scoreboard<Point>(numNeighbors,Scoreboard.Order.INCREASING);
  ClosestPointIndex index=new ClosestPointIndex();
  for (int i=0; i < 100000; i++) {
    Point p=makePoint();
    actual.add(p,WikiBrainSpatialUtils.haversine(query,p));
    index.insert(i * 3,p);
  }
  System.out.println("Closest points to " + query + " are: ");
  long before=System.currentTimeMillis();
  List<ClosestPointIndex.Result> neighbors=index.query(query,numNeighbors);
  long after=System.currentTimeMillis();
  System.err.println("elapsed millis is " + (after - before));
  for (int i=0; i < neighbors.size(); i++) {
    ClosestPointIndex.Result n=neighbors.get(i);
    Point p=actual.getElement(i);
    assertSame(p,n.point);
    System.out.println("\t" + n.point + " with distance "+ n.distance);
  }
}

boolean _parseIndirectMemberAccess(boolean bParseTypeLiteralOnly){
  Expression peekRootExpression=peekExpression();
  Token token=getTokenizer().getCurrentToken();
  int operatorLineNumber=token.getLine();
  String value=token.getStringValue();
  if ('.' == token.getType() || (token.getType() == SourceCodeTokenizer.TT_OPERATOR && value != null && ("?.".equals(value) || "*.".equals(value)))) {
    getTokenizer().nextToken();
    MemberAccessKind kind=MemberAccessKind.getForOperator(value);
    Expression expression=popExpression();
    verify(expression,kind != MemberAccessKind.EXPANSION || TypeLord.getExpandableComponentType(expression.getType()) != null,Res.MSG_TYPE_IS_NOT_ITERABLE,expression.getType().getName());
    Token T=new Token();
    verify(expression,match(T,SourceCodeTokenizer.TT_WORD) || match(T,SourceCodeTokenizer.TT_KEYWORD),Res.MSG_EXPECTING_MEMBER_ACCESS_PATH);
    parseMemberAccess(expression,kind,T.getTokenStart(),T._strValue == null ? "" : T._strValue,makeLazyLightweightParserState(),bParseTypeLiteralOnly);
    verifyNonVoidExpression(peekExpression());
  }
 else   if (!bParseTypeLiteralOnly && parseFeatureLiteral(token,peekRootExpression)) {
  }
 else   if (!bParseTypeLiteralOnly && ('[' == token.getType() || (token.getType() == SourceCodeTokenizer.TT_OPERATOR && "?[".equals(value)))) {
    getTokenizer().nextToken();
    Expression rootExpression=popExpression();
    IType rootType=rootExpression.getType();
    IType indexType=ArrayAccess.supportsArrayAccess(rootType) ? JavaTypes.pINT() : MapAccess.supportsMapAccess(rootType) ? MapAccess.getKeyType(rootType) : null;
    boolean bDynamicRoot=rootType.isDynamic();
    if (bDynamicRoot) {
      parseExpression();
    }
 else {
      parseExpression(new ContextType(indexType));
    }
    Expression indexExpression=popExpression();
    Expression arrayAccess;
    boolean bNullSafe=!ILanguageLevel.Util.STANDARD_GOSU() || value != null && "?[".equals(value);
    if (ArrayAccess.supportsArrayAccess(rootType)) {
      ArrayAccess aa=new ArrayAccess();
      aa.setRootExpression(rootExpression);
      if (verify(indexExpression,indexExpression.getType() == JavaTypes.pINT() || indexExpression.getType() == JavaTypes.INTEGER() || bDynamicRoot,Res.MSG_ARRAY_INDEX_MUST_BE_INT)) {
        aa.setMemberExpression(indexExpression);
      }
      aa.setNullSafe(bNullSafe);
      pushExpression(aa);
      arrayAccess=aa;
    }
 else     if (MapAccess.supportsMapAccess(rootType)) {
      MapAccess ma=new MapAccess();
      ma.setRootExpression(rootExpression);
      ma.setKeyExpression(indexExpression);
      ma.setNullSafe(bNullSafe);
      pushExpression(ma);
      arrayAccess=ma;
    }
 else     if (isSuperCall(rootExpression,indexExpression)) {
      SuperAccess ma=new SuperAccess();
      ma.setRootExpression((Identifier)rootExpression);
      ma.setKeyExpression((TypeLiteral)indexExpression);
      IType superType=verifySuperTypeIsDeclaredInCompilingClass((TypeLiteral)indexExpression);
      ma.setType(superType);
      pushExpression(ma);
      arrayAccess=ma;
    }
 else {
      verify(rootExpression,BeanAccess.isBeanType(rootExpression.getType()) || (rootExpression.getType() instanceof MetaType),Res.MSG_EXPECTING_BEAN_TYPE_WITH_REFLECTION_OPERATOR);
      verify(indexExpression,JavaTypes.CHAR_SEQUENCE().isAssignableFrom(indexExpression.getType()),Res.MSG_PROPERTY_REFLECTION_ONLY_WITH_STRINGS);
      MemberAccess ma=new MemberAccess();
      ma.setRootExpression(rootExpression);
      ma.setMemberExpression(indexExpression);
      ma.setType(JavaTypes.OBJECT());
      ma.setMemberAccessKind(bNullSafe ? MemberAccessKind.NULL_SAFE : MemberAccessKind.NORMAL);
      pushExpression(ma);
      arrayAccess=ma;
    }
    verify(arrayAccess,match(null,']'),Res.MSG_EXPECTING_BRACKET_TO_CLOSE_DYNAMIC_MEMBER_ACCESS);
  }
 else   if (peekExpression().getType() instanceof IBlockType && match(null,'(')) {
    IBlockType iBlockType=(IBlockType)peekExpression().getType();
    BlockInvocation bi=new BlockInvocation(popExpression());
    boolean bNoArgsProvided;
    if (!(bNoArgsProvided=match(null,')')) || iBlockType.hasOptionalParams()) {
      MethodScore score=parseArgumentList(peekRootExpression.getType(),bi,Collections.singletonList(iBlockType),IType.EMPTY_ARRAY,true,bNoArgsProvided);
      bi.setNamedArgOrder(score.getNamedArgOrder());
      bi.setArgs(score.getArguments());
      verify(bi,bNoArgsProvided || match(null,')'),Res.MSG_EXPECTING_FUNCTION_CLOSE);
    }
    verify(bi,bi.getArgs().size() == iBlockType.getParameterTypes().length,Res.MSG_WRONG_NUM_OF_ARGS,iBlockType.getParameterTypes().length);
    bi.setType(iBlockType.getReturnType());
    verifyNonVoidExpression(bi);
    pushExpression(bi);
  }
 else {
    return false;
  }
  if (peekRootExpression != null && !peekRootExpression.hasParseExceptions()) {
    ParseTree rootLocation=peekRootExpression.getLocation();
    if (rootLocation != null) {
      getLocationsList().remove(peekRootExpression.getLocation());
      setLocation(rootLocation.getOffset(),rootLocation.getLineNum(),rootLocation.getColumn());
      peekExpression().getLocation().addChild(peekRootExpression.getLocation());
    }
  }
  setOperatorLineNumber(peekExpression(),operatorLineNumber);
  return true;
}

/** 
 * Dispatches to the given location. Does its forward via a RequestDispatcher. If the dispatch fails a 404 error will be sent back in the http response.
 * @param finalLocation the location to dispatch to.
 * @param invocation    the execution state of the action
 * @throws Exception if an error occurs. If the dispatch fails the error will go back via theHTTP request.
 */
public void doExecute(String finalLocation,ActionInvocation invocation) throws Exception {
  LOG.debug("Forwarding to location: {}",finalLocation);
  PageContext pageContext=ServletActionContext.getPageContext();
  if (pageContext != null) {
    pageContext.include(finalLocation);
  }
 else {
    HttpServletRequest request=ServletActionContext.getRequest();
    HttpServletResponse response=ServletActionContext.getResponse();
    RequestDispatcher dispatcher=request.getRequestDispatcher(finalLocation);
    if (StringUtils.isNotEmpty(finalLocation) && finalLocation.indexOf('?') > 0) {
      String queryString=finalLocation.substring(finalLocation.indexOf('?') + 1);
      HttpParameters parameters=getParameters(invocation);
      Map<String,Object> queryParams=urlHelper.parseQueryString(queryString,true);
      if (queryParams != null && !queryParams.isEmpty()) {
        parameters=HttpParameters.create(queryParams).withParent(parameters).build();
        invocation.getInvocationContext().setParameters(parameters);
        invocation.getInvocationContext().getContextMap().put("parameters",parameters);
      }
    }
    if (dispatcher == null) {
      LOG.warn("Location {} not found!",finalLocation);
      response.sendError(404,"result '" + finalLocation + "' not found");
      return;
    }
    Boolean insideActionTag=(Boolean)ObjectUtils.defaultIfNull(request.getAttribute(StrutsStatics.STRUTS_ACTION_TAG_INVOCATION),Boolean.FALSE);
    if (!insideActionTag && !response.isCommitted() && (request.getAttribute("javax.servlet.include.servlet_path") == null)) {
      request.setAttribute("struts.view_uri",finalLocation);
      request.setAttribute("struts.request_uri",request.getRequestURI());
      dispatcher.forward(request,response);
    }
 else {
      dispatcher.include(request,response);
    }
  }
}

