/** 
 * Constructs HttpServiceSpecifications for each of the handlers in the  {@param handlers} list.Also performs verifications on these handlers (that a NettyHttpService can be constructed from them).
 */
private Map<String,HttpServiceHandlerSpecification> createHandlerSpecs(List<? extends HttpServiceHandler> handlers){
  verifyHandlers(handlers);
  Map<String,HttpServiceHandlerSpecification> handleSpecs=Maps.newHashMap();
  for (  HttpServiceHandler handler : handlers) {
    DefaultHttpServiceHandlerConfigurer configurer=new DefaultHttpServiceHandlerConfigurer(handler,deployNamespace,artifactId,artifactRepository,pluginInstantiator,systemTableConfigurer);
    handler.configure(configurer);
    HttpServiceHandlerSpecification spec=configurer.createSpecification();
    Preconditions.checkArgument(!handleSpecs.containsKey(spec.getName()),"Handler with name %s already existed.",spec.getName());
    handleSpecs.put(spec.getName(),spec);
    addDatasetModules(configurer.getDatasetModules());
    addDatasetSpecs(configurer.getDatasetSpecs());
    addPlugins(configurer.getPlugins());
  }
  return handleSpecs;
}

/** 
 * Look for a node/project/framework config property of the given key, and if not found fallback to a framework property, return parsed long or the default
 * @param key           key for node attribute/project/framework property
 * @param frameworkProp fallback framework property
 * @param defval        default value
 * @return parsed value or default
 */
private long resolveLongFwk(final String key,final String frameworkProp,final long defval){
  long timeout=defval;
  String opt=resolve(key);
  if (opt == null && frameworkProp != null && framework.getPropertyLookup().hasProperty(frameworkProp)) {
    opt=framework.getProperty(frameworkProp);
  }
  if (opt != null) {
    try {
      timeout=Long.parseLong(opt);
    }
 catch (    NumberFormatException ignored) {
    }
  }
  return timeout;
}

