static protected void replaceFiles(Path srcf,Path destf,FileSystem fs,Path tmppath) throws HiveException {
  if (!checkPathDomain(srcf,fs)) {
    throw new HiveException("Invalid path: srcf=" + srcf + ", fs="+ (fs == null ? null : fs.getUri()));
  }
  FileStatus[] srcs;
  try {
    srcs=fs.globStatus(srcf);
  }
 catch (  IOException e) {
    throw new HiveException("addFiles: filesystem error in check phase",e);
  }
  if (srcs == null) {
    LOG.info("No sources specified to move: " + srcf);
    if (SessionState.get() != null)     SessionState.get().ssLog("No sources specified to move: " + srcf);
    return;
  }
  checkPaths(fs,srcs,destf,true);
  try {
    fs.mkdirs(tmppath);
    for (int i=0; i < srcs.length; i++) {
      FileStatus[] items=fs.listStatus(srcs[i].getPath());
      for (int j=0; j < items.length; j++) {
        if (!fs.rename(items[j].getPath(),new Path(tmppath,items[j].getPath().getName()))) {
          throw new HiveException("Error moving: " + items[j].getPath() + " into: "+ tmppath);
        }
      }
    }
    boolean b=fs.delete(destf,true);
    LOG.info("Deleting:" + destf.toString() + ",Status:"+ b);
    if (SessionState.get() != null)     SessionState.get().ssLog("Deleting:" + destf.toString() + ",Status:"+ b);
    if (!fs.mkdirs(destf.getParent())) {
      throw new HiveException("Unable to create destination directory: " + destf.getParent().toString());
    }
    b=fs.rename(tmppath,destf);
    if (!b) {
      throw new HiveException("Unable to move results to destination directory: " + destf.getParent().toString());
    }
    LOG.info("Renaming:" + tmppath.toString() + ",Status:"+ b);
    if (SessionState.get() != null)     SessionState.get().ssLog("Renaming:" + tmppath.toString() + ",Status:"+ b);
    Connection cc=null;
    SessionState ss=SessionState.get();
    try {
      if (ss != null && ss.getBIStore() != null && ss.getTdw_query_info() != null) {
        cc=ss.getBIStore().openConnect();
        if (cc != null) {
          ss.getBIStore().insertMoveInfo(cc,ss.getTdw_query_info().getQueryId(),tmppath.toString(),destf.toString(),ss.getTbName(),ss.getDbName(),ss.getTdw_query_info().getTaskid());
          ss.getBIStore().closeConnect(cc);
        }
 else {
          LOG.error("record move operation into BI failed: " + ss.getTdw_query_info().getQueryId());
        }
      }
    }
 catch (    Exception e) {
      ss.getBIStore().closeConnect(cc);
      LOG.error("record move operation into BI failed: " + ss.getCurrnetQueryId());
      e.printStackTrace();
    }
  }
 catch (  IOException e) {
    throw new HiveException("replaceFiles: error while moving files!!!",e);
  }
 finally {
    try {
      fs.delete(tmppath,true);
    }
 catch (    IOException e) {
      if (SessionState.get() != null)       SessionState.get().ssLog("Unable delete path " + tmppath + e.toString());
      LOG.warn("Unable delete path " + tmppath,e);
    }
  }
}

