final public List<InsuranceTransaction> readAllNonReimbursedInsuranceTransactionsByExecutionYear(ExecutionYear executionYear){
  List<InsuranceTransaction> nonReimbursedInsuranceTransactions=new ArrayList<InsuranceTransaction>();
  for (  InsuranceTransaction insuranceTransaction : this.getInsuranceTransactionsSet()) {
    if (insuranceTransaction.getExecutionYear().equals(executionYear)) {
      GuideEntry guideEntry=insuranceTransaction.getGuideEntry();
      if (guideEntry == null || guideEntry.getReimbursementGuideEntriesSet().isEmpty()) {
        nonReimbursedInsuranceTransactions.add(insuranceTransaction);
      }
 else {
        boolean isReimbursed=false;
        for (        ReimbursementGuideEntry reimbursementGuideEntry : guideEntry.getReimbursementGuideEntriesSet()) {
          if (reimbursementGuideEntry.getReimbursementGuide().getActiveReimbursementGuideSituation().getReimbursementGuideState().equals(ReimbursementGuideState.PAYED)) {
            isReimbursed=true;
            break;
          }
        }
        if (!isReimbursed) {
          nonReimbursedInsuranceTransactions.add(insuranceTransaction);
        }
      }
    }
  }
  return nonReimbursedInsuranceTransactions;
}

/** 
 * Decrypt and authenticate packet. Then feed it to USM.checkFilters. Packets generated should have a PeerNode on them. Note that the buffer can be modified by this method.
 */
public DECODED process(byte[] buf,int offset,int length,Peer peer,PeerNode opn,long now){
  if (opn != null && opn.getOutgoingMangler() != this) {
    Logger.error(this,"Apparently contacted by " + opn + ") on "+ this,new Exception("error"));
    opn=null;
  }
  boolean wantAnonAuth=crypto.wantAnonAuth();
  if (opn != null) {
    if (logMINOR)     Logger.minor(this,"Trying exact match");
    if (length > Node.SYMMETRIC_KEY_LENGTH + HASH_LENGTH + 2 && !node.isStopping()) {
      if (tryProcessAuth(buf,offset,length,opn,peer,false,now)) {
        return DECODED.DECODED;
      }
      if (tryProcessAuthAnonReply(buf,offset,length,opn,peer,now)) {
        return DECODED.DECODED;
      }
    }
  }
  PeerNode[] peers=crypto.getPeerNodes();
  if (node.isStopping())   return DECODED.SHUTTING_DOWN;
  if (length > Node.SYMMETRIC_KEY_LENGTH + HASH_LENGTH + 2) {
    for (    PeerNode pn : peers) {
      if (pn == opn)       continue;
      if (logDEBUG)       Logger.debug(this,"Trying auth with " + pn);
      if (tryProcessAuth(buf,offset,length,pn,peer,false,now)) {
        return DECODED.DECODED;
      }
      if (pn.handshakeUnknownInitiator()) {
        if (tryProcessAuthAnonReply(buf,offset,length,pn,peer,now)) {
          return DECODED.DECODED;
        }
      }
    }
  }
  boolean wantAnonAuthChangeIP=wantAnonAuth && crypto.wantAnonAuthChangeIP();
  if (wantAnonAuth && wantAnonAuthChangeIP) {
    if (checkAnonAuthChangeIP(opn,buf,offset,length,peer,now))     return DECODED.DECODED;
  }
  boolean didntTryOldOpennetPeers;
  OpennetManager opennet=node.getOpennet();
  if (opennet != null) {
    if (opennet.wantPeer(null,false,true,true,ConnectionType.RECONNECT)) {
      for (      PeerNode oldPeer : opennet.getOldPeers()) {
        if (tryProcessAuth(buf,offset,length,oldPeer,peer,true,now))         return DECODED.DECODED;
      }
      didntTryOldOpennetPeers=false;
    }
 else     didntTryOldOpennetPeers=true;
  }
 else   didntTryOldOpennetPeers=false;
  if (wantAnonAuth) {
    if (tryProcessAuthAnon(buf,offset,length,peer))     return DECODED.DECODED;
  }
  if (wantAnonAuth && !wantAnonAuthChangeIP) {
    if (checkAnonAuthChangeIP(opn,buf,offset,length,peer,now)) {
      return DECODED.DECODED;
    }
  }
  if (logMINOR && crypto.isOpennet && wantAnonAuth) {
    if (!didntTryOldOpennetPeers)     Logger.minor(this,"Unmatchable packet from " + peer);
  }
 else   Logger.normal(this,"Unmatchable packet from " + peer);
  if (!didntTryOldOpennetPeers)   return DECODED.NOT_DECODED;
 else   return DECODED.DIDNT_WANT_OPENNET;
}

