public static Map zip(List keys,List values,boolean includeNull){
  Iterator k=keys.iterator();
  Iterator v=values.iterator();
  HashMap hm=new HashMap();
  while (k.hasNext() && v.hasNext()) {
    Object o=k.next();
    Object p=v.next();
