private Object uncheckedGetField(){
  Text nullSequence=oi.getNullSequence();
  int fieldLength=start + length - startPosition;
  if (fieldLength != 0 && fieldLength == nullSequence.getLength() && LazyUtils.compare(bytes.getData(),startPosition,fieldLength,nullSequence.getBytes(),0,nullSequence.getLength()) == 0) {
    return null;
  }
  if (!fieldInited) {
    fieldInited=true;
    field.init(bytes,startPosition,fieldLength);
  }
  return field.getObject();
}

