/** 
 * Returns a moving average of the last N ping/pong cycles. If  {@link Peer#ping()} has neverbeen called or we did not hear back the "pong" message yet, returns  {@link Long#MAX_VALUE}. The moving average window is 5 buckets.
 */
public long getPingTime(){
  lastPingTimesLock.lock();
  try {
    if (lastPingTimes == null)     return Long.MAX_VALUE;
    long sum=0;
    for (    long i : lastPingTimes)     sum+=i;
    return (long)((double)sum / lastPingTimes.length);
  }
  finally {
    lastPingTimesLock.unlock();
  }
}

