private void initialize(Map props){
  try {
    String prop_pool_ping_query=null;
    if (props == null) {
      throw new RuntimeException("SimpleDataSource: The properties map passed to the initializer was null.");
    }
    if (!(props.containsKey(PROP_JDBC_DRIVER) && props.containsKey(PROP_JDBC_URL) && props.containsKey(PROP_JDBC_USERNAME)&& props.containsKey(PROP_JDBC_PASSWORD))) {
      throw new RuntimeException("SimpleDataSource: Some properties were not set.");
    }
 else {
      jdbcDriver=(String)props.get(PROP_JDBC_DRIVER);
      jdbcUrl=(String)props.get(PROP_JDBC_URL);
      jdbcUsername=(String)props.get(PROP_JDBC_USERNAME);
      jdbcPassword=(String)props.get(PROP_JDBC_PASSWORD);
      poolMaximumActiveConnections=props.containsKey(PROP_POOL_MAX_ACTIVE_CONN) ? Integer.parseInt((String)props.get(PROP_POOL_MAX_ACTIVE_CONN)) : 10;
      poolMaximumIdleConnections=props.containsKey(PROP_POOL_MAX_IDLE_CONN) ? Integer.parseInt((String)props.get(PROP_POOL_MAX_IDLE_CONN)) : 5;
      poolMaximumCheckoutTime=props.containsKey(PROP_POOL_MAX_CHECKOUT_TIME) ? Integer.parseInt((String)props.get(PROP_POOL_MAX_CHECKOUT_TIME)) : 20000;
      poolTimeToWait=props.containsKey(PROP_POOL_TIME_TO_WAIT) ? Integer.parseInt((String)props.get(PROP_POOL_TIME_TO_WAIT)) : 20000;
      poolPingEnabled=props.containsKey(PROP_POOL_PING_ENABLED) && Boolean.valueOf((String)props.get(PROP_POOL_PING_ENABLED)).booleanValue();
      prop_pool_ping_query=(String)props.get(PROP_POOL_PING_QUERY);
      poolPingQuery=props.containsKey(PROP_POOL_PING_QUERY) ? prop_pool_ping_query : "NO PING QUERY SET";
      poolPingConnectionsOlderThan=props.containsKey(PROP_POOL_PING_CONN_OLDER_THAN) ? Integer.parseInt((String)props.get(PROP_POOL_PING_CONN_OLDER_THAN)) : 0;
      poolPingConnectionsNotUsedFor=props.containsKey(PROP_POOL_PING_CONN_NOT_USED_FOR) ? Integer.parseInt((String)props.get(PROP_POOL_PING_CONN_NOT_USED_FOR)) : 0;
      jdbcDefaultAutoCommit=props.containsKey(PROP_JDBC_DEFAULT_AUTOCOMMIT) && Boolean.valueOf((String)props.get(PROP_JDBC_DEFAULT_AUTOCOMMIT)).booleanValue();
      useDriverProps=false;
      Iterator propIter=props.keySet().iterator();
      driverProps=new Properties();
      driverProps.put("user",jdbcUsername);
      driverProps.put("password",jdbcPassword);
      while (propIter.hasNext()) {
        String name=(String)propIter.next();
        String value=(String)props.get(name);
        if (name.startsWith(ADD_DRIVER_PROPS_PREFIX)) {
          driverProps.put(name.substring(ADD_DRIVER_PROPS_PREFIX_LENGTH),value);
          useDriverProps=true;
        }
      }
      expectedConnectionTypeCode=assembleConnectionTypeCode(jdbcUrl,jdbcUsername,jdbcPassword);
      Resources.instantiate(jdbcDriver);
      if (poolPingEnabled && (!props.containsKey(PROP_POOL_PING_QUERY) || prop_pool_ping_query.trim().length() == 0)) {
        throw new RuntimeException("SimpleDataSource: property '" + PROP_POOL_PING_ENABLED + "' is true, but property '"+ PROP_POOL_PING_QUERY+ "' is not set correctly.");
      }
    }
  }
 catch (  Exception e) {
    log.error("SimpleDataSource: Error while loading properties. Cause: " + e.toString(),e);
    throw new RuntimeException("SimpleDataSource: Error while loading properties. Cause: " + e,e);
  }
}

@Override public boolean onTouchEvent(MotionEvent ev){
  if (mTouchInterceptionListener != null) {
switch (ev.getActionMasked()) {
case MotionEvent.ACTION_DOWN:
      if (mIntercepting) {
        mTouchInterceptionListener.onDownMotionEvent(ev);
        duplicateTouchEventForChildren(ev);
        return true;
      }
    break;
case MotionEvent.ACTION_MOVE:
  if (mInitialPoint == null) {
    mInitialPoint=new PointF(ev.getX(),ev.getY());
  }
float diffX=ev.getX() - mInitialPoint.x;
float diffY=ev.getY() - mInitialPoint.y;
mIntercepting=mTouchInterceptionListener.shouldInterceptTouchEvent(ev,true,diffX,diffY);
if (mIntercepting) {
if (!mBeganFromDownMotionEvent) {
mBeganFromDownMotionEvent=true;
MotionEvent event=MotionEvent.obtainNoHistory(mPendingDownMotionEvent);
event.setLocation(ev.getX(),ev.getY());
mTouchInterceptionListener.onDownMotionEvent(event);
mInitialPoint=new PointF(ev.getX(),ev.getY());
diffX=diffY=0;
}
if (!mChildrenEventsCanceled) {
mChildrenEventsCanceled=true;
duplicateTouchEventForChildren(obtainMotionEvent(ev,MotionEvent.ACTION_CANCEL));
}
mTouchInterceptionListener.onMoveMotionEvent(ev,diffX,diffY);
mDownMotionEventPended=true;
return true;
}
 else {
if (mDownMotionEventPended) {
mDownMotionEventPended=false;
MotionEvent event=MotionEvent.obtainNoHistory(mPendingDownMotionEvent);
event.setLocation(ev.getX(),ev.getY());
duplicateTouchEventForChildren(ev,event);
}
 else {
duplicateTouchEventForChildren(ev);
}
mBeganFromDownMotionEvent=false;
mChildrenEventsCanceled=false;
}
break;
case MotionEvent.ACTION_UP:
case MotionEvent.ACTION_CANCEL:
mBeganFromDownMotionEvent=false;
if (mIntercepting) {
mTouchInterceptionListener.onUpOrCancelMotionEvent(ev);
}
if (!mChildrenEventsCanceled) {
mChildrenEventsCanceled=true;
if (mDownMotionEventPended) {
mDownMotionEventPended=false;
MotionEvent event=MotionEvent.obtainNoHistory(mPendingDownMotionEvent);
event.setLocation(ev.getX(),ev.getY());
duplicateTouchEventForChildren(ev,event);
}
 else {
duplicateTouchEventForChildren(ev);
}
}
return true;
}
}
return super.onTouchEvent(ev);
}

