@SuppressWarnings("unchecked") private Operator genNewGroupByPlanReduceSinkOperator(QB qb,String dest,Operator inputOperatorInfo,int numReducers,boolean mapAggrDone,boolean partitionByGbkeyanddistinctkey,boolean isFirstReduce,ArrayList<ArrayList<Integer>> tag2AggrPos,ArrayList<ArrayList<ASTNode>> tag2AggrParamAst) throws SemanticException {
  RowResolver reduceSinkInputRowResolver=opParseCtx.get(inputOperatorInfo).getRR();
  QBParseInfo parseInfo=qb.getParseInfo();
  RowResolver reduceSinkOutputRowResolver=new RowResolver();
  reduceSinkOutputRowResolver.setIsExprResolver(true);
  Map<String,exprNodeDesc> colExprMap=new HashMap<String,exprNodeDesc>();
  ArrayList<exprNodeDesc> reduceKeys=new ArrayList<exprNodeDesc>();
  ArrayList<exprNodeDesc> reduceValues=new ArrayList<exprNodeDesc>();
  List<String> outputKeyColumnNames=new ArrayList<String>();
  List<String> outputValueColumnNames=new ArrayList<String>();
  List<ASTNode> grpByExprs=SemanticAnalyzer.getGroupByForClause(parseInfo,dest);
  int colid=0;
  if (qb.getParseInfo().getDestContainsGroupbyCubeOrRollupClause(dest)) {
    String colName=getColumnInternalName(colid++);
    outputKeyColumnNames.add(colName);
    ColumnInfo info=reduceSinkInputRowResolver.get("",NewGroupByUtils1._CUBE_ROLLUP_GROUPINGSETS_TAG_);
    exprNodeDesc grpByExprNode=new exprNodeColumnDesc(info.getType(),info.getInternalName(),info.getAlias(),info.getIsPartitionCol());
    reduceKeys.add(grpByExprNode);
    String field=Utilities.ReduceField.KEY.toString() + "." + colName;
    reduceSinkOutputRowResolver.put("",NewGroupByUtils1._CUBE_ROLLUP_GROUPINGSETS_TAG_,new ColumnInfo(field,grpByExprNode.getTypeInfo(),"",false));
    colExprMap.put(colName,grpByExprNode);
  }
  for (int i=0; i < grpByExprs.size(); i++) {
    ASTNode grpbyExpr=grpByExprs.get(i);
    exprNodeDesc grpByExprNode=SemanticAnalyzer.genExprNodeDesc(grpbyExpr,reduceSinkInputRowResolver,qb,-1,conf);
    reduceKeys.add(grpByExprNode);
    String colName=getColumnInternalName(colid++);
    outputKeyColumnNames.add(colName);
    String field=Utilities.ReduceField.KEY.toString() + "." + colName;
    reduceSinkOutputRowResolver.putExpression(grpbyExpr,new ColumnInfo(field,grpByExprNode.getTypeInfo(),"",false));
    colExprMap.put(field,grpByExprNode);
  }
  boolean containsfunctions=tag2AggrPos != null && tag2AggrPos.size() > 0;
  exprNodeDesc aggrPartExpr=null;
  ArrayList<ArrayList<exprNodeDesc>> tag2AggrParamORValueExpr=null;
  TypeInfo aggrPartTypeInfo=null;
  if (containsfunctions) {
    String colNameAggrPart=getColumnInternalName(colid++);
    if (isFirstReduce) {
      outputKeyColumnNames.add(colNameAggrPart);
    }
 else {
      outputValueColumnNames.add(colNameAggrPart);
    }
    if (mapAggrDone) {
      ColumnInfo aggrPartInfo=reduceSinkInputRowResolver.get("",_GBY_AGGRPART_OUTPUT_COLNAME_);
      aggrPartExpr=new exprNodeColumnDesc(aggrPartInfo.getType(),aggrPartInfo.getInternalName(),"",false);
    }
 else {
      tag2AggrParamORValueExpr=new ArrayList<ArrayList<exprNodeDesc>>();
      for (int tag=0; tag < tag2AggrParamAst.size(); tag++) {
        tag2AggrParamORValueExpr.add(new ArrayList<exprNodeDesc>());
        for (int j=0; j < tag2AggrParamAst.get(tag).size(); j++) {
          ASTNode paraExpr=(ASTNode)tag2AggrParamAst.get(tag).get(j);
          exprNodeDesc exprNode=SemanticAnalyzer.genExprNodeDesc(paraExpr,reduceSinkInputRowResolver,qb,-1,conf);
          tag2AggrParamORValueExpr.get(tag).add(exprNode);
        }
      }
    }
    List<TypeInfo> unionTypes=new ArrayList<TypeInfo>();
    for (int tag=0; tag < tag2AggrPos.size(); tag++) {
      ArrayList<String> names=new ArrayList<String>();
      ArrayList<TypeInfo> typeInfos=new ArrayList<TypeInfo>();
      int paramLen=(tag == 0 && mapAggrDone) ? tag2AggrPos.get(tag).size() : (isFirstReduce ? tag2AggrParamAst.get(tag).size() : tag2AggrPos.get(tag).size());
      for (int j=0; j < paramLen; j++) {
        TypeInfo inputTypeInfo=null;
        if (mapAggrDone) {
          inputTypeInfo=reduceSinkInputRowResolver.get("",_AGGRPARTTAG_ + tag + "_"+ j).getType();
        }
 else {
          ASTNode paraExpr=(ASTNode)tag2AggrParamAst.get(tag).get(j);
          exprNodeDesc exprNode=SemanticAnalyzer.genExprNodeDesc(paraExpr,reduceSinkInputRowResolver,qb,-1,conf);
          inputTypeInfo=exprNode.getTypeInfo();
        }
        String field1=(isFirstReduce ? Utilities.ReduceField.KEY.toString() : Utilities.ReduceField.VALUE.toString()) + "." + colNameAggrPart+ ":"+ tag+ "."+ getColumnInternalName(j);
        ColumnInfo outColInfo=new ColumnInfo(field1,inputTypeInfo,"",false);
        reduceSinkOutputRowResolver.put("",_AGGRPARTTAG_ + tag + "_"+ j,outColInfo);
        names.add(getColumnInternalName(j));
        typeInfos.add(inputTypeInfo);
      }
      if (names.size() == 0) {
        names.add("nondistnull");
        typeInfos.add(TypeInfoFactory.voidTypeInfo);
      }
      unionTypes.add(TypeInfoFactory.getStructTypeInfo(names,typeInfos));
    }
    aggrPartTypeInfo=TypeInfoFactory.getUnionTypeInfo(unionTypes);
    ColumnInfo outColInfo=new ColumnInfo((isFirstReduce ? Utilities.ReduceField.KEY.toString() : Utilities.ReduceField.VALUE.toString()) + "." + colNameAggrPart,aggrPartTypeInfo,"",false);
    reduceSinkOutputRowResolver.put("",_GBY_AGGRPART_OUTPUT_COLNAME_,outColInfo);
  }
  ReduceSinkOperator rsOp=(ReduceSinkOperator)putOpInsertMap(OperatorFactory.getAndMakeChild(PlanUtils.getReduceSinkDesc2(reduceKeys,reduceValues,outputKeyColumnNames,outputValueColumnNames,-1,numReducers,mapAggrDone,isFirstReduce,partitionByGbkeyanddistinctkey,tag2AggrPos,aggrPartExpr,tag2AggrParamORValueExpr,aggrPartTypeInfo),new RowSchema(reduceSinkOutputRowResolver.getColumnInfos()),inputOperatorInfo),reduceSinkOutputRowResolver);
  rsOp.setColumnExprMap(colExprMap);
  return rsOp;
}

