public static double svm_predict(svm_model model,svm_node[] x){
  if (model.param.svm_type == svm_parameter.ONE_CLASS || model.param.svm_type == svm_parameter.EPSILON_SVR || model.param.svm_type == svm_parameter.NU_SVR) {
    double[] res=new double[1];
    svm_predict_values(model,x,res);
    if (model.param.svm_type == svm_parameter.ONE_CLASS)     return (res[0] > 0) ? 1 : -1;
 else     return res[0];
  }
 else {
    int i;
    int nr_class=model.nr_class;
    double[] dec_values=new double[nr_class * (nr_class - 1) / 2];
    svm_predict_values(model,x,dec_values);
    int[] vote=new int[nr_class];
    for (i=0; i < nr_class; i++)     vote[i]=0;
    int pos=0;
    for (i=0; i < nr_class; i++)     for (int j=i + 1; j < nr_class; j++) {
      if (dec_values[pos++] > 0)       ++vote[i];
 else       ++vote[j];
    }
    int vote_max_idx=0;
    for (i=1; i < nr_class; i++)     if (vote[i] > vote[vote_max_idx])     vote_max_idx=i;
    return model.label[vote_max_idx];
  }
}

