@Override public void train(ClassificationDataSet dataSet,boolean parallel){
  predicting=dataSet.getPredicting();
  hypWeights=new DoubleList(maxIterations);
  hypoths=new ArrayList<Classifier>(maxIterations);
  final int N=dataSet.size();
  double[] D_inv=new double[N];
  double[] D=new double[N];
  ClassificationDataSet cds=dataSet.shallowClone();
  Arrays.fill(D,1.0 / N);
  for (int i=0; i < N; i++)   cds.setWeight(i,D[0]);
  double weightSum=1;
  double[] H_cur=new double[N];
  for (int t=0; t < maxIterations; t++) {
    Classifier weak=weakLearner.clone();
    weak.train(cds,parallel);
    double invSum=0;
    for (int i=0; i < N; i++)     invSum+=(D_inv[i]=1 - D[i]);
    for (int i=0; i < N; i++)     D_inv[i]/=invSum;
    double p_d=0, p_id=0, n_d=0, n_id=0;
    for (int i=0; i < N; i++) {
      H_cur[i]=(weak.classify(cds.getDataPoint(i)).getProb(1) * 2 - 1);
      double outPut=Math.signum(H_cur[i]);
      int c=cds.getDataPointCategory(i);
      if (c == 1) {
        p_d+=outPut * D[i];
        p_id+=outPut * D_inv[i];
      }
 else {
        n_d+=outPut * D[i];
        n_id+=outPut * D_inv[i];
      }
    }
    double alpha_m=p_d * (1 - p_id) - n_d * (1 - n_id);
    if (Math.signum(alpha_m) != Math.signum(p_d - n_d) || Math.abs((p_d - n_d)) < 1e-6 || alpha_m <= 0)     return;
    weightSum=0;
    for (int i=0; i < N; i++) {
      double w_i=cds.getWeight(i);
      int y_i=cds.getDataPointCategory(i) * 2 - 1;
      w_i*=Math.exp(-y_i * alpha_m * H_cur[i]);
      if (Double.isInfinite(w_i))       w_i=1;
 else       if (w_i <= 0)       w_i=1e-3 / N;
      weightSum+=w_i;
      cds.setWeight(i,w_i);
    }
    for (int i=0; i < N; i++)     cds.setWeight(i,Math.max(cds.getWeight(i) / weightSum,1e-10));
    hypWeights.add(alpha_m);
    hypoths.add(weak);
  }
}

