public static Connection getHiveJdbcConnection(final String jdbcUrl,final String user,final String password,final String hivePrincipal) throws ClassNotFoundException, SQLException, IOException, InterruptedException {
  final String transportMode=new HiveConf().get("hive.server2.transport.mode","binary");
