/** 
 * Defines any special cases that are exceptions to what would otherwise be illegal message assignments. <p>These exceptions are generally due to the pass being designed before new syntax was introduced.
 * @param msgNode Node representing the value assigned to the message variable or property
 */
private static boolean isLegalMessageVarAlias(Node msgNode){
  if (msgNode.isGetProp() && msgNode.isQualifiedName() && msgNode.getLastChild().getString().startsWith("MSG_")) {
    return true;
  }
  if (!msgNode.isName()) {
    return false;
  }
  String originalName=(msgNode.getOriginalName() != null) ? msgNode.getOriginalName() : msgNode.getString();
  if (originalName.startsWith("MSG_")) {
    return true;
  }
  return false;
}

/** 
 * Parse XML document which is assumed to be in RSS format. RSS 2.0 example: <?xml version="1.0"?> <rss version="2.0"> <channel> <title>Lift Off News</title> <link>http://liftoff.msfc.nasa.gov/</link> <description>Liftoff to Space Exploration.</description> <language>en-us</language> <pubDate>Tue, 10 Jun 2003 04:00:00 GMT</pubDate> <lastBuildDate>Tue, 10 Jun 2003 09:41:01 GMT</lastBuildDate> <docs>http://blogs.law.harvard.edu/tech/rss</docs> <generator>Weblog Editor 2.0</generator> <managingEditor>editor@example.com</managingEditor> <webMaster>webmaster@example.com</webMaster> <ttl>5</ttl> <item> <title>Star City</title> <link>http://liftoff.msfc.nasa.gov/news/2003/news-starcity.asp</link> <description>How do Americans get ready to work with Russians aboard the International Space Station? They take a crash course in culture, language and protocol at Russia's Star City.</description> <pubDate>Tue, 03 Jun 2003 09:39:21 GMT</pubDate> <guid>http://liftoff.msfc.nasa.gov/2003/06/03.html#item573</guid> </item> <item> <title>Space Exploration</title> <link>http://liftoff.msfc.nasa.gov/</link> <description>Sky watchers in Europe, Asia, and parts of Alaska and Canada will experience a partial eclipse of the Sun on Saturday, May 31.</description> <pubDate>Fri, 30 May 2003 11:06:42 GMT</pubDate> <guid>http://liftoff.msfc.nasa.gov/2003/05/30.html#item572</guid> </item> </channel> </rss>
 * @param sitemap
 * @param doc
 */
private void parseRSS(SiteMap sitemap,Document doc){
  logger.debug("Parsing RSS doc");
  sitemap.setType(SitemapType.RSS);
  NodeList list=doc.getElementsByTagName("channel");
  Element elem=(Element)list.item(0);
  String lastMod=getElementValue(elem,"pubDate");
  logger.debug("lastMod=" + lastMod);
  list=doc.getElementsByTagName("item");
  for (int i=0; i < list.getLength() && i < MAX_URLS; i++) {
    Node n=list.item(i);
    if (n.getNodeType() == Node.ELEMENT_NODE) {
      elem=(Element)n;
      String link=getElementValue(elem,"link");
      logger.debug("link=" + link);
      try {
        URL url=new URL(link);
        boolean valid=urlIsLegal(sitemap.getBaseUrl(),url.toString());
        if (valid || !strict) {
          SiteMapURL sUrl=new SiteMapURL(url.toString(),lastMod,null,null,valid);
          sitemap.addSiteMapUrl(sUrl);
          if (logger.isDebugEnabled()) {
            StringBuffer sb=new StringBuffer("  ");
            sb.append(i + 1).append(". ").append(sUrl);
            logger.debug(sb.toString());
          }
        }
      }
 catch (      MalformedURLException e) {
        logger.debug("Bad url: [" + link + "]");
      }
    }
  }
}

