@Override public ReturnCode filterKeyValue(Cell cell) throws IOException {
  int rowKeyOffset=cell.getRowOffset() + prefixLength;
  int sizeOfRowKey=cell.getRowLength() - prefixLength;
  long publishTimestamp=MessagingUtils.getPublishTimestamp(cell.getRowArray(),rowKeyOffset,sizeOfRowKey);
  int topicIdLength=MessagingUtils.getTopicLengthMessageEntry(sizeOfRowKey) - Bytes.SIZEOF_INT;
  int generationId=Bytes.toInt(cell.getRowArray(),rowKeyOffset + topicIdLength);
  if (prevTopicIdBytes == null || currentTTL == null || currentGen == null || (!Bytes.equals(prevTopicIdBytes,0,prevTopicIdBytes.length,cell.getRowArray(),rowKeyOffset,topicIdLength))) {
    prevTopicIdBytes=Arrays.copyOfRange(cell.getRowArray(),rowKeyOffset,rowKeyOffset + topicIdLength);
    Map<String,String> properties=metadataCache.getTopicMetadata(ByteBuffer.wrap(prevTopicIdBytes));
    if (properties == null) {
      LOG.debug("Region " + env.getRegion().getRegionNameAsString() + ", could not get properties of topicId "+ MessagingUtils.toTopicId(prevTopicIdBytes));
      return ReturnCode.INCLUDE;
    }
    currentTTL=Long.parseLong(properties.get(MessagingUtils.Constants.TTL_KEY));
    currentGen=Integer.parseInt(properties.get(MessagingUtils.Constants.GENERATION_KEY));
  }
  if (MessagingUtils.isOlderGeneration(generationId,currentGen)) {
    return ReturnCode.SKIP;
  }
  if ((generationId == currentGen) && ((timestamp - publishTimestamp) > currentTTL)) {
    return ReturnCode.SKIP;
  }
  return ReturnCode.INCLUDE;
}

/** 
 * Finds the visibility of a given type.
 * @param typeRepository the repository where types should be loaded from
 * @param typeName       the fully qualified type name
 * @return               a TypeVisibility object representing the visibility (e.g. public, package, etc)
 */
public static TypeVisibility getVisibility(TypeRepository typeRepository,String typeName){
  try {
    Class<?> type=typeRepository.loadClass(typeName);
    int modifiers=type.getModifiers();
    if (Modifier.isPrivate(modifiers)) {
      return TypeVisibility.PRIVATE;
    }
 else     if (Modifier.isPublic(modifiers)) {
      return TypeVisibility.PUBLIC;
    }
 else     if (Modifier.isProtected(modifiers)) {
      return TypeVisibility.PROTECTED;
    }
 else {
      return TypeVisibility.PACKAGE;
    }
  }
 catch (  ClassNotFoundException e) {
    log.warn("Visibility for type " + typeName + " could not be found.");
    return null;
  }
}

@Override protected int[] filterPixels(int width,int height,int[] inPixels,Rectangle transformedSpace){
  int[] outPixels=new int[width * height];
  for (int i=0; i < iterations; i++) {
    int index=0;
    if (i > 0) {
      int[] t=inPixels;
      inPixels=outPixels;
      outPixels=t;
    }
    for (int y=0; y < height; y++) {
      for (int x=0; x < width; x++) {
        int pixel=inPixels[y * width + x];
        if (!blackFunction.isBlack(pixel)) {
          int neighbours=0;
          for (int dy=-1; dy <= 1; dy++) {
            int iy=y + dy;
            int ioffset;
            if (0 <= iy && iy < height) {
              ioffset=iy * width;
              for (int dx=-1; dx <= 1; dx++) {
                int ix=x + dx;
                if (!(dy == 0 && dx == 0) && 0 <= ix && ix < width) {
                  int rgb=inPixels[ioffset + ix];
                  if (blackFunction.isBlack(rgb))                   neighbours++;
                }
              }
            }
          }
          if (neighbours >= threshold) {
            if (colormap != null)             pixel=colormap.getColor((float)i / iterations);
 else             pixel=newColor;
          }
        }
        outPixels[index++]=pixel;
      }
    }
  }
  return outPixels;
}

