@Nullable <ACS extends Appendable & CharSequence>CharSequence textTo0(@NotNull ACS a){
  consumePadding();
  int ch=peekCode();
  @Nullable CharSequence ret=a;
switch (ch) {
case '{':
{
      final long len=readLength();
      try {
        a.append(Bytes.toString(bytes,bytes.readPosition(),len));
      }
 catch (      IOException e) {
        throw new AssertionError(e);
      }
      bytes.readSkip(len);
      bytes.skipTo(StopCharTesters.COMMA_STOP);
      return a;
    }
case '"':
  readText(a,getEscapingQuotes());
break;
case '\'':
readText(a,getEscapingSingleQuotes());
break;
case '!':
{
bytes.readSkip(1);
@NotNull StringBuilder sb=acquireStringBuilder();
parseWord(sb);
if (StringUtils.isEqual(sb,"!null")) {
textTo(sb);
ret=null;
}
 else {
if (a instanceof StringBuilder) {
textTo((StringBuilder)a);
}
 else {
textTo(sb);
ret=sb;
}
}
break;
}
case -1:
return "";
default :
{
final long rem=bytes.readRemaining();
if (rem > 0) {
if (a instanceof Bytes) {
bytes.parse8bit((Bytes)a,getStrictEscapingEndOfText());
}
 else if (use8bit) {
bytes.parse8bit((StringBuilder)a,getStrictEscapingEndOfText());
}
 else {
bytes.parseUtf8(a,getStrictEscapingEndOfText());
}
if (rem == bytes.readRemaining()) throw new IORuntimeException("Nothing to read at " + bytes.toDebugString(32));
}
 else {
AppendableUtil.setLength(a,0);
}
while (a.length() > 0) {
if (Character.isWhitespace(a.charAt(a.length() - 1))) AppendableUtil.setLength(a,a.length() - 1);
 else break;
}
break;
}
}
int prev=peekBack();
if (prev == ':' || prev == '#' || prev == '}' || prev == ']') bytes.readSkip(-1);
return ret;
}

