public int decode_cabac_mb_skip(H264Context h,int mb_x,int mb_y){
  int mba_xy, mbb_xy;
  int ctx=0;
  if (h.mb_aff_frame != 0) {
    int mb_xy=mb_x + (mb_y & ~1) * h.s.mb_stride;
    mba_xy=mb_xy - 1;
    if ((mb_y & 1) != 0 && h.slice_table_base[h.slice_table_offset + mba_xy] == h.slice_num && h.mb_field_decoding_flag == ((h.s.current_picture.mb_type_base[h.s.current_picture.mb_type_offset + mba_xy] & H264Context.MB_TYPE_INTERLACED) != 0 ? 1 : 0))     mba_xy+=h.s.mb_stride;
    if (h.mb_field_decoding_flag != 0) {
      mbb_xy=mb_xy - h.s.mb_stride;
      if (0 == (mb_y & 1) && h.slice_table_base[h.slice_table_offset + mbb_xy] == h.slice_num && (h.s.current_picture.mb_type_base[h.s.current_picture.mb_type_offset + mbb_xy] & H264Context.MB_TYPE_INTERLACED) != 0)       mbb_xy-=h.s.mb_stride;
    }
 else     mbb_xy=mb_x + (mb_y - 1) * h.s.mb_stride;
  }
 else {
    int mb_xy=h.mb_xy;
    mba_xy=mb_xy - 1;
    mbb_xy=mb_xy - (h.s.mb_stride << (h.s.picture_structure != MpegEncContext.PICT_FRAME ? 1 : 0));
  }
  if (h.slice_table_base[h.slice_table_offset + mba_xy] == h.slice_num && ((h.s.current_picture.mb_type_base[h.s.current_picture.mb_type_offset + mba_xy] & H264Context.MB_TYPE_SKIP) == 0))   ctx++;
  if (h.slice_table_base[h.slice_table_offset + mbb_xy] == h.slice_num && ((h.s.current_picture.mb_type_base[h.s.current_picture.mb_type_offset + mbb_xy] & H264Context.MB_TYPE_SKIP) == 0))   ctx++;
  if (h.slice_type_nos == H264Context.FF_B_TYPE)   ctx+=13;
  int ret=this.get_cabac_noinline(h.cabac_state,11 + ctx);
  return ret;
}

private List<CompilerInput> parsePotentialModules(Iterable<CompilerInput> inputsToProcess){
