private static short getBandCompat(short numBands,int[][] range,int frequency){
  final int MIN=0;
  final int MAX=1;
  if (frequency < range[0][MIN])   return (short)(-1);
  if (frequency > range[numBands - 1][MAX])   return (short)(-1);
  for (short band=0; band < numBands; band++) {
    if ((frequency >= range[band][MIN]) && (frequency <= range[band][MAX])) {
      return band;
    }
  }
  return (short)(-1);
}

