/** 
 * Writes all the contents of a Reader to a Writer.
 * @param reader the reader to read from
 * @param writer the writer to write to
 */
public static void copy(Reader reader,Writer writer) throws IOException {
  copy(reader,writer,false);
}
/** 
 * Writes all the contents of a Reader to a Writer.
 * @param reader the reader to read from
 * @param writer the writer to write to
 * @param closeStreams the flag indicating if the stream must be close at the end, even if an exception occurs
 */
public static void copy(Reader reader,Writer writer,boolean closeStreams) throws IOException {
  char[] buf=new char[BUFFER_SIZE];
  int num=0;
  try {
    while ((num=reader.read(buf,0,buf.length)) != -1) {
      writer.write(buf,0,num);
    }
  }
  finally {
    if (closeStreams) {
      close(reader);
      close(writer);
    }
  }
}
/** 
 * Writes all the contents of a Reader to a Writer.
 * @param reader the reader to read from
 * @param writer the writer to write to
 */
public static void copy(InputStream input,OutputStream output) throws IOException {
  byte[] buf=new byte[BUFFER_SIZE];
  int num=0;
  while ((num=input.read(buf,0,buf.length)) != -1) {
    output.write(buf,0,num);
  }
}
/** 
 * Writes all the contents of an InputStream to a Writer.
 * @param input the input stream to read from
 * @param writer the writer to write to
 */
public static void copy(InputStream input,Writer writer) throws IOException {
  copy(new InputStreamReader(input),writer);
}
/** 
 * Writes all the contents of an InputStream to an OutputStream.
 * @param input the input stream to read from
 * @param output the output stream to write to
 * @param closeStreams the flag indicating if the stream must be close at the end, even if an exception occurs
 */
public static void copy(InputStream input,OutputStream output,boolean closeStreams) throws IOException {
  try {
    copy(input,output);
  }
  finally {
    if (closeStreams) {
      close(input);
      close(output);
    }
  }
}
/** 
 * Copy the readable byte channel to the writable byte channel
 * @param inChannel the readable byte channel
 * @param outChannel the writable byte channel
 * @throws IOException if an IOException occurs.
 */
public static void copy(ReadableByteChannel inChannel,WritableByteChannel outChannel) throws IOException {
  if (inChannel instanceof FileChannel) {
    ((FileChannel)inChannel).transferTo(0,((FileChannel)inChannel).size(),outChannel);
  }
 else {
    final ByteBuffer buffer=ByteBuffer.allocateDirect(16 * 1024);
    try {
      while (inChannel.read(buffer) != -1) {
        buffer.flip();
        outChannel.write(buffer);
        buffer.compact();
      }
      buffer.flip();
      while (buffer.hasRemaining()) {
        outChannel.write(buffer);
      }
    }
  finally {
      IOUtils.close(inChannel);
      IOUtils.close(outChannel);
    }
  }
}

private void getElementsContainingPointUpwards(Array<T> result,Point point,boolean firstInvocation){
  if (elements != null) {
    addElementsContainingPoint(result,point);
  }
  if (firstInvocation && topLeft != null) {
    if (topLeft.contains(point)) {
      topLeft.getElementsContainingPoint(result,point);
    }
    if (topRight.contains(point)) {
      topRight.getElementsContainingPoint(result,point);
    }
    if (bottomLeft.contains(point)) {
      bottomLeft.getElementsContainingPoint(result,point);
    }
    if (bottomRight.contains(point)) {
      bottomRight.getElementsContainingPoint(result,point);
    }
  }
  if (parent != null) {
    if (parent.topLeft != this && (parent.topLeft.contains(point) || parent.topLeft.contains(point))) {
      parent.topLeft.getElementsContainingPoint(result,point);
    }
    if (parent.topRight != this && (parent.topRight.contains(point) || parent.topRight.contains(point))) {
      parent.topRight.getElementsContainingPoint(result,point);
    }
    if (parent.bottomLeft != this && (parent.bottomLeft.contains(point) || parent.bottomLeft.contains(point))) {
      parent.bottomLeft.getElementsContainingPoint(result,point);
    }
    if (parent.bottomRight != this && (parent.bottomRight.contains(point) || parent.bottomRight.contains(point))) {
      parent.bottomRight.getElementsContainingPoint(result,point);
    }
    ((RegionQuadTree<T>)parent).getElementsContainingPointUpwards(result,point,false);
  }
}

