/** 
 * Writes a geospatial value following the GeoJSON specification defined in RFC 7946. 
 */
protected void writeGeoValue(final String name,final EdmPrimitiveType type,final Geospatial geoValue,final Boolean isNullable,JsonGenerator json,SRID parentSrid) throws EdmPrimitiveTypeException, IOException, SerializerException {
  if (geoValue == null) {
    if (isNullable == null || isNullable) {
      json.writeNull();
    }
 else {
      throw new EdmPrimitiveTypeException("The literal 'null' is not allowed.");
    }
  }
 else {
    if (!type.getDefaultType().isAssignableFrom(geoValue.getClass())) {
      throw new EdmPrimitiveTypeException("The value type " + geoValue.getClass() + " is not supported.");
    }
    json.writeStartObject();
    json.writeStringField(Constants.ATTR_TYPE,geoValueTypeToJsonName.get(geoValue.getGeoType()));
    json.writeFieldName(geoValue.getGeoType() == Geospatial.Type.GEOSPATIALCOLLECTION ? Constants.JSON_GEOMETRIES : Constants.JSON_COORDINATES);
    json.writeStartArray();
switch (geoValue.getGeoType()) {
case POINT:
      writeGeoPoint(json,(Point)geoValue);
    break;
case MULTIPOINT:
  writeGeoPoints(json,(MultiPoint)geoValue);
break;
case LINESTRING:
writeGeoPoints(json,(LineString)geoValue);
break;
case MULTILINESTRING:
for (final LineString lineString : (MultiLineString)geoValue) {
json.writeStartArray();
writeGeoPoints(json,lineString);
json.writeEndArray();
}
break;
case POLYGON:
writeGeoPolygon(json,(Polygon)geoValue);
break;
case MULTIPOLYGON:
for (final Polygon polygon : (MultiPolygon)geoValue) {
json.writeStartArray();
writeGeoPolygon(json,polygon);
json.writeEndArray();
}
break;
case GEOSPATIALCOLLECTION:
for (final Geospatial element : (GeospatialCollection)geoValue) {
writeGeoValue(name,EdmPrimitiveTypeFactory.getInstance(element.getEdmPrimitiveTypeKind()),element,isNullable,json,geoValue.getSrid());
}
break;
}
json.writeEndArray();
if (geoValue.getSrid() != null && geoValue.getSrid().isNotDefault() && (parentSrid == null || !parentSrid.equals(geoValue.getSrid()))) {
srid(json,geoValue.getSrid());
}
json.writeEndObject();
}
}

/** 
 * Get the boolean value associated with a key.
 * @param key A key string.
 * @return The truth.
 * @throws JSONException if the value is not a Boolean or the String "true" or "false".
 */
public boolean getBoolean(String key) throws JSONException {
  Object object=this.get(key);
  if (object.equals(Boolean.FALSE) || (object instanceof String && ((String)object).equalsIgnoreCase("false"))) {
    return false;
  }
 else   if (object.equals(Boolean.TRUE) || (object instanceof String && ((String)object).equalsIgnoreCase("true"))) {
    return true;
  }
  throw new JSONException("JSONObject[" + quote(key) + "] is not a Boolean.");
}

