/** 
 * Returns the  {@link com.google.gson.stream.JsonToken#NUMBER double} value of the next token,consuming it. If the next token is a string, this method will attempt to parse it as a double using  {@link Double#parseDouble(String)}.
 * @throws IllegalStateException if the next token is not a literal value.
 * @throws NumberFormatException if the next literal value cannot be parsedas a double, or is non-finite.
 */
public double nextDouble() throws IOException {
  int p=peeked;
  if (p == PEEKED_NONE) {
    p=doPeek();
  }
  if (p == PEEKED_LONG) {
    peeked=PEEKED_NONE;
    return (double)peekedLong;
  }
  if (p == PEEKED_NUMBER) {
    peekedString=new String(buffer,pos,peekedNumberLength);
    pos+=peekedNumberLength;
  }
 else   if (p == PEEKED_SINGLE_QUOTED || p == PEEKED_DOUBLE_QUOTED) {
    peekedString=nextQuotedValue(p == PEEKED_SINGLE_QUOTED ? '\'' : '"');
  }
 else   if (p == PEEKED_UNQUOTED) {
    peekedString=nextUnquotedValue();
  }
 else   if (p != PEEKED_BUFFERED) {
    throw new IllegalStateException("Expected a double but was " + peek() + " at line "+ getLineNumber()+ " column "+ getColumnNumber());
  }
  peeked=PEEKED_BUFFERED;
  double result=Double.parseDouble(peekedString);
  if (!lenient && (Double.isNaN(result) || Double.isInfinite(result))) {
    throw new MalformedJsonException("JSON forbids NaN and infinities: " + result + " at line "+ getLineNumber()+ " column "+ getColumnNumber());
  }
  peekedString=null;
  peeked=PEEKED_NONE;
  return result;
}

/** 
 * Builds a Soy string literal for this string value (including the surrounding single quotes). Note that Soy string syntax is a subset of JS string syntax, so the result should also be a valid JS string. <p>Adapted from StringUtil.javaScriptEscape().
 * @param value The string value to escape.
 * @param shouldEscapeToAscii Whether to escape non-ASCII characters as Unicode hex escapes(backslash + 'u' + 4 hex digits).
 * @param quoteStyle whether or not to use double quotes
 * @return A Soy string literal for this string value (including the surrounding quotes).
 */
public static String escapeToSoyString(String value,boolean shouldEscapeToAscii,QuoteStyle quoteStyle){
  int len=value.length();
  StringBuilder out=new StringBuilder(len * 9 / 8);
  out.append(quoteStyle.getQuoteChar());
  int codePoint;
  for (int i=0; i < len; i+=Character.charCount(codePoint)) {
    codePoint=value.codePointAt(i);
switch (codePoint) {
case '\n':
      out.append("\\n");
    break;
case '\r':
  out.append("\\r");
break;
case '\t':
out.append("\\t");
break;
case '\b':
out.append("\\b");
break;
case '\f':
out.append("\\f");
break;
case '\\':
out.append("\\\\");
break;
case '\'':
out.append(quoteStyle == QuoteStyle.DOUBLE ? "'" : "\\'");
break;
case '"':
out.append(quoteStyle == QuoteStyle.DOUBLE ? "\\\"" : '"');
break;
default :
if (shouldEscapeToAscii && (codePoint < 0x20 || codePoint >= 0x7F)) {
appendHexEscape(out,codePoint);
}
 else {
out.appendCodePoint(codePoint);
}
break;
}
}
out.append(quoteStyle.getQuoteChar());
return out.toString();
}

