@Override public Object check(final Object value) throws UWSException {
  if (value == null)   return getDefault();
  long defaultDuration=(Long)getDefault(), maxDuration=getMaxDuration();
  Long duration;
  if (value instanceof Long)   duration=(Long)value;
 else   if (value instanceof Integer)   duration=(long)((Integer)value).intValue();
 else   if (value instanceof String) {
    try {
      duration=Long.parseLong((String)value);
    }
 catch (    NumberFormatException nfe) {
      throw new UWSException(UWSException.BAD_REQUEST,"Wrong format for the parameter \"executionduration\": \"" + value.toString() + "\"! It should be a long numeric value between "+ TAPJob.UNLIMITED_DURATION+ " and "+ maxDuration+ " (Default value: "+ defaultDuration+ ").");
    }
  }
 else   throw new UWSException(UWSException.INTERNAL_SERVER_ERROR,"Wrong type for the parameter \"executionduration\": class \"" + value.getClass().getName() + "\"! It should be long or a string containing only a long value.");
  if (duration <= 0)   duration=TAPJob.UNLIMITED_DURATION;
  if (maxDuration > 0 && (duration > maxDuration || duration <= 0))   duration=maxDuration;
  return duration;
}

