/** 
 * Get the array of lines in which all the columns are aligned <p><strong>IMPORTANT:</strong> The array must have as many columns as the table has. Each column can contain either  {@link AsciiTable#LEFT},  {@link AsciiTable#CENTER} or{@link AsciiTable#RIGHT}. If the array contains ONE item, it will be used for every column. </p>
 * @param pos		Array of flags, indicating how each column should bejustified.
 * @param newsep	Separator to use, replacing the original one.
 * @param thread	Thread to watch. If it is interrupted, this task shouldbe as well.
 * @return	An array of the table lines, aligned and justified.
 * @throws InterruptedException	If the current thread has been interrupted.<em>This interruption is useful when this alignment operation becomes time and memory consuming.</em>
 */
private String[] align(int[] pos,char newsep,final Thread thread) throws InterruptedException {
  int nblines=lines.size();
  String[] result=new String[nblines];
  StringBuffer buf=new StringBuffer();
  int p0, p1, col, fldsize, colsize, n1, inserted;
  boolean inHeader=header;
  int uniqueJustif=pos.length == 1 ? pos[0] : -1;
  for (int i=0; i < nblines; i++) {
    if (Thread.currentThread().isInterrupted() || (thread != null && thread.isInterrupted()))     throw new InterruptedException();
    buf.delete(0,buf.length());
    String line=lines.get(i);
    p0=0;
    col=0;
    if (inHeader && line == null) {
      for (int k=0; k < sizes.length; k++) {
        if (k > 0)         buf.append(csep);
        addHsep(buf,sizes[k]);
      }
      if (headerPostfix != null)       buf.append(headerPostfix);
      inHeader=false;
    }
 else {
      for (col=0; col < sizes.length; col++) {
        if (col > 0)         buf.append(sep);
        p1=line.indexOf(sep,p0);
        if (p1 < 0)         p1=line.length();
        fldsize=p1 - p0;
        if (fldsize < 0)         break;
        colsize=sizes[col];
        inserted=colsize - fldsize;
        if (inserted < 0)         inserted=0;
        int justif=inHeader ? CENTER : (uniqueJustif >= 0 ? uniqueJustif : pos[col]);
switch (justif) {
case LEFT:
default :
          buf.append(line.substring(p0,p1));
        addspaces(buf,inserted);
      break;
case CENTER:
    n1=(inserted) / 2;
  addspaces(buf,n1);
buf.append(line.substring(p0,p1));
addspaces(buf,inserted - n1);
break;
case RIGHT:
addspaces(buf,inserted);
buf.append(line.substring(p0,p1));
break;
}
p0=p1 + 1;
}
}
result[i]=newsep != '\0' ? buf.toString().replace(csep,newsep) : buf.toString();
}
return result;
}

