/** 
 * Returns the regularized gamma function Q(a, x) = 1 - P(a, x). <p> The implementation of this method is based on: <ul> <li> <a href="http://mathworld.wolfram.com/RegularizedGammaFunction.html"> Regularized Gamma Function</a>, equation (1). </li> <li> <a href="http://functions.wolfram.com/GammaBetaErf/GammaRegularized/10/0003/"> Regularized incomplete gamma function: Continued fraction representations (formula 06.08.10.0003)</a> </li> </ul>
 * @param a             the a parameter.
 * @param x             the value.
 * @param epsilon       When the absolute value of the nth item in theseries is less than epsilon the approximation ceases to calculate further elements in the series.
 * @param maxIterations Maximum number of "iterations" to complete.
 * @return the regularized gamma function P(a, x)
 * @throws IllegalStateException if the algorithm fails to converge.
 */
public static double regularizedGammaQ(final double a,double x,double epsilon,int maxIterations){
  double ret;
  if (Double.isNaN(a) || Double.isNaN(x) || (a <= 0.0)|| (x < 0.0)) {
    ret=Double.NaN;
  }
 else   if (x == 0.0) {
    ret=1.0;
  }
 else   if (x < a + 1.0) {
    ret=1.0 - regularizedGammaP(a,x,epsilon,maxIterations);
  }
 else {
    ContinuedFraction cf=new ContinuedFraction(){
      @Override protected double getA(      int n,      double x){
        return ((2.0 * n) + 1.0) - a + x;
      }
      @Override protected double getB(      int n,      double x){
        return n * (a - n);
      }
    }
;
    ret=1.0 / cf.evaluate(x,epsilon,maxIterations);
    ret=Math.exp(-x + (a * Math.log(x)) - logGamma(a)) * ret;
  }
  return ret;
}

