/** 
 * An operator for overriding EncryptionContext's table name for a specific DynamoDBEncryptor. If any table names or the encryption context itself is null, then it returns the original EncryptionContext.
 * @param originalTableName the name of the table that should be overridden in the Encryption Context
 * @param newTableName the table name that should be used in the Encryption Context
 * @return A UnaryOperator that produces a new EncryptionContext with the supplied table name
 */
public static UnaryOperator<EncryptionContext> overrideEncryptionContextTableName(String originalTableName,String newTableName){
  return encryptionContext -> {
    if (encryptionContext == null || encryptionContext.getTableName() == null || originalTableName == null || newTableName == null) {
      return encryptionContext;
    }
    if (originalTableName.equals(encryptionContext.getTableName())) {
      return new EncryptionContext.Builder(encryptionContext).withTableName(newTableName).build();
    }
 else {
      return encryptionContext;
    }
  }
;
}

