@Override protected int[] filterPixels(int width,int height,int[] inPixels,Rectangle transformedSpace){
  int index=0;
  short[][] r=new short[3][width];
  int[] outPixels=new int[width * height];
  short[] table=new short[256];
  int offsetl=(int)(offset * 256 / levels);
  for (int i=0; i < 256; i++)   table[i]=(short)PixelUtils.clamp((int)(255 * Math.floor(levels * (i + offsetl) / 256) / (levels - 1) - offsetl));
  for (int x=0; x < width; x++) {
    int rgb=inPixels[x];
    r[1][x]=(short)PixelUtils.brightness(rgb);
  }
  for (int y=0; y < height; y++) {
    boolean yIn=y > 0 && y < height - 1;
    int nextRowIndex=index + width;
    if (y < height - 1) {
      for (int x=0; x < width; x++) {
        int rgb=inPixels[nextRowIndex++];
        r[2][x]=(short)PixelUtils.brightness(rgb);
      }
    }
    for (int x=0; x < width; x++) {
      boolean xIn=x > 0 && x < width - 1;
      int w=x - 1;
      int e=x + 1;
      int v=0;
      if (yIn && xIn) {
        short nwb=r[0][w];
        short neb=r[0][x];
        short swb=r[1][w];
        short seb=r[1][x];
        short nw=table[nwb];
        short ne=table[neb];
        short sw=table[swb];
        short se=table[seb];
        if (nw != ne || nw != sw || ne != se || sw != se) {
          v=(int)(scale * (Math.abs(nwb - neb) + Math.abs(nwb - swb) + Math.abs(neb - seb)+ Math.abs(swb - seb)));
          if (v > 255)           v=255;
        }
      }
      if (v != 0)       outPixels[index]=PixelUtils.combinePixels(inPixels[index],contourColor,PixelUtils.NORMAL,v);
 else       outPixels[index]=inPixels[index];
      index++;
    }
    short[] t;
    t=r[0];
    r[0]=r[1];
    r[1]=r[2];
    r[2]=t;
  }
  return outPixels;
}

/** 
 * Read inner class definitions for the class and locate any synthetic inner classes so that we can add them to the passthrough set in our parent config.
 */
void readInnerClasses(){
  for (  InnerClassNode inner : this.validationClassNode.innerClasses) {
    ClassInfo innerClass=ClassInfo.forName(inner.name);
    if ((inner.outerName != null && inner.outerName.equals(this.classInfo.getName())) || inner.name.startsWith(this.validationClassNode.name + "$")) {
      if (innerClass.isProbablyStatic() && innerClass.isSynthetic()) {
        this.syntheticInnerClasses.add(inner.name);
      }
 else {
        this.innerClasses.add(inner.name);
      }
    }
  }
}

