@Override public ValidationResult validate(BlockHeader header){
  if (header.isGenesis())   return Success;
  if (ethashHelper == null)   return powRule.validate(header);
  if (chain.isSide())   ethashHelper.preCache(header.getNumber());
  if (mode == mixed && !syncDone && rnd.nextInt(100) % MIX_DENOMINATOR > 0)   return powRule.validate(header);
  try {
    Pair<byte[],byte[]> res=ethashHelper.ethashWorkFor(header,header.getNonce(),true);
    if (res == null) {
      return powRule.validate(header);
    }
    if (!FastByteComparisons.equal(res.getLeft(),header.getMixHash())) {
      return fault(String.format("#%d: mixHash doesn't match",header.getNumber()));
    }
    if (FastByteComparisons.compareTo(res.getRight(),0,32,header.getPowBoundary(),0,32) > 0) {
      return fault(String.format("#%d: proofValue > header.getPowBoundary()",header.getNumber()));
    }
    return Success;
  }
 catch (  Exception e) {
    logger.error("Failed to verify ethash work for block {}",header.getShortDescr(),e);
    return fault("Failed to verify ethash work for block " + header.getShortDescr());
  }
}

/** 
 * Escape special chars form String including /
 * @param s - Must not be null.
 * @param sb
 */
public void escape(String s,Appendable sb){
  try {
    int len=s.length();
    for (int i=0; i < len; i++) {
      char ch=s.charAt(i);
switch (ch) {
case '"':
        sb.append("\\\"");
      break;
case '\\':
    sb.append("\\\\");
  break;
case '\b':
sb.append("\\b");
break;
case '\f':
sb.append("\\f");
break;
case '\n':
sb.append("\\n");
break;
case '\r':
sb.append("\\r");
break;
case '\t':
sb.append("\\t");
break;
case '/':
sb.append("\\/");
break;
default :
if ((ch >= '\u0000' && ch <= '\u001F') || (ch >= '\u007F' && ch <= '\u009F') || (ch >= '\u2000' && ch <= '\u20FF')) {
sb.append("\\u");
String hex="0123456789ABCDEF";
sb.append(hex.charAt(ch >> 12 & 0x0F));
sb.append(hex.charAt(ch >> 8 & 0x0F));
sb.append(hex.charAt(ch >> 4 & 0x0F));
sb.append(hex.charAt(ch >> 0 & 0x0F));
}
 else {
sb.append(ch);
}
}
}
}
 catch (IOException e) {
throw new RuntimeException("Impossible Error");
}
}

