private final Object[] resize(NonBlockingIdentityHashMap topmap,Object[] kvs){
  assert chm(kvs) == this;
  Object[] newkvs=_newkvs;
  if (newkvs != null)   return newkvs;
  int oldlen=len(kvs);
  int sz=size();
  int newsz=sz;
  if (sz >= (oldlen >> 2)) {
    newsz=oldlen << 1;
    if (sz >= (oldlen >> 1))     newsz=oldlen << 2;
  }
  long tm=System.currentTimeMillis();
  long q=0;
  if (newsz <= oldlen && tm <= topmap._last_resize_milli + 10000 && (q=_slots.estimate_get()) >= (sz << 1))   newsz=oldlen << 1;
  if (newsz < oldlen)   newsz=oldlen;
  int log2;
  for (log2=MIN_SIZE_LOG; (1 << log2) < newsz; log2++)   ;
  long r=_resizers;
  while (!_resizerUpdater.compareAndSet(this,r,r + 1))   r=_resizers;
  int megs=((((1 << log2) << 1) + 4) << 3) >> 20;
  if (r >= 2 && megs > 0) {
    newkvs=_newkvs;
    if (newkvs != null)     return newkvs;
    try {
      Thread.sleep(8 * megs);
    }
 catch (    Exception e) {
    }
  }
  newkvs=_newkvs;
  if (newkvs != null)   return newkvs;
  newkvs=new Object[((1 << log2) << 1) + 2];
  newkvs[0]=new CHM(_size);
  newkvs[1]=new int[1 << log2];
  if (_newkvs != null)   return _newkvs;
  if (CAS_newkvs(newkvs)) {
    topmap.rehash();
  }
 else   newkvs=_newkvs;
  return newkvs;
}

