/** 
 * Returns all Ignore files in given  {@link Project} that can match current passed file.
 * @param project current project
 * @param file    current file
 * @return collection of suitable Ignore files
 */
public static List<VirtualFile> getSuitableIgnoreFiles(@NotNull Project project,@NotNull IgnoreFileType fileType,@NotNull VirtualFile file) throws ExternalFileException {
  VirtualFile baseDir=getModuleRootForFile(file,project);
  List<VirtualFile> files=ContainerUtil.newArrayList();
  if (file.getCanonicalPath() == null || baseDir == null || !VfsUtilCore.isAncestor(baseDir,file,true)) {
    throw new ExternalFileException();
  }
  if (!baseDir.equals(file)) {
    do {
      file=file.getParent();
      VirtualFile ignoreFile=file.findChild(fileType.getIgnoreLanguage().getFilename());
      ContainerUtil.addIfNotNull(files,ignoreFile);
    }
 while (!file.equals(baseDir));
  }
  return files;
}

@SuppressFBWarnings(value={"RV_RETURN_VALUE_IGNORED_BAD_PRACTICE"},justification="move to java.nio for file stuff") public boolean publishReport(Run<?,?> build,FilePath workspace,Launcher launcher,TaskListener listener) throws InterruptedException, IOException {
  CucumberTestResultAction action;
  final String _testResults=build.getEnvironment(listener).expand(this.testResults);
  CucumberJSONParser parser=new CucumberJSONParser(ignoreBadSteps);
  CucumberTestResult result=parser.parseResult(_testResults,build,workspace,launcher,listener);
  String remoteTempDir=workspace.act(new TmpDirCallable());
  for (  FeatureResult f : result.getFeatures()) {
    for (    ScenarioResult s : f.getScenarioResults()) {
      for (      EmbeddedItem item : s.getEmbeddedItems()) {
        FilePath srcFilePath=new FilePath(workspace,remoteTempDir + '/' + item.getFilename());
        File destRoot=new File(build.getRootDir(),"/cucumber/embed/" + f.getSafeName() + '/'+ s.getSafeName()+ '/');
        destRoot.mkdirs();
        File destFile=new File(destRoot,item.getFilename());
        if (!destFile.getAbsolutePath().startsWith(destRoot.getAbsolutePath())) {
          throw new IOException("Exploit attempt detected - Build attempted to write to " + destFile.getAbsolutePath());
        }
        FilePath destFilePath=new FilePath(destFile);
        srcFilePath.copyTo(destFilePath);
        srcFilePath.delete();
      }
    }
  }
  action=build.getAction(CucumberTestResultAction.class);
  if (action == null) {
    action=new CucumberTestResultAction(build,result,listener);
    CHECKPOINT.block();
    CHECKPOINT.report();
  }
 else {
    CHECKPOINT.block();
    action.mergeResult(result,listener);
    build.save();
    CHECKPOINT.report();
  }
  if (result.getPassCount() == 0 && result.getFailCount() == 0 && result.getSkipCount() == 0)   throw new AbortException("No cucumber scenarios appear to have been run.");
  if (action.getResult().getTotalCount() == action.getResult().getFailCount()) {
    build.setResult(Result.FAILURE);
  }
 else   if (action.getResult().getFailCount() > 0) {
    build.setResult(Result.UNSTABLE);
  }
  return true;
}

