public AEADCryptBucket(DataInputStream dis,FilenameGenerator fg,PersistentFileTracker persistentFileTracker,MasterSecret masterKey) throws IOException, StorageFormatException, ResumeFailedException {
  int version=dis.readInt();
  if (version != VERSION)   throw new StorageFormatException("Unknown version " + version);
  int keyLength=dis.readByte();
  if (keyLength < 0 || !(keyLength == 16 || keyLength == 24 || keyLength == 32))   throw new StorageFormatException("Unknown key length " + keyLength);
