private String parseScriptText(String tx){
  CharArrayWriter cw=new CharArrayWriter();
  int size=tx.length();
  int i=0;
  while (i < size) {
    char ch=tx.charAt(i);
    if (i + 2 < size && ch == '%' && tx.charAt(i + 1) == '\\' && tx.charAt(i + 2) == '>') {
      cw.write('%');
      cw.write('>');
      i+=3;
    }
 else {
      cw.write(ch);
      ++i;
    }
  }
  cw.close();
  return cw.toString();
}

private ClosableIterator<Map.Entry<byte[],byte[]>> iterator(final byte[] start,final boolean mustInclude,final boolean keyonly){
  return new ClosableIterator<Map.Entry<byte[],byte[]>>(){
    private final DatabaseEntry dk=new DatabaseEntry(start);
    private final DatabaseEntry dv=new DatabaseEntry();
    private final DatabaseEntry dvs=new DatabaseEntry();
    private Map.Entry<byte[],byte[]> next;
    private Cursor cursor;
    @Override public String toString(){
      return "CI:" + LessBytes.toString(dk.getData()) + ","+ next+ ","+ cursor;
    }
{
      dvs.setPartial(0,0,true);
      try {
        cursor=bdb.openCursor(null,CursorConfig.READ_UNCOMMITTED);
        OperationStatus status=null;
        boolean useAltKey=false;
        if (start == null || start.length == 0) {
          status=cursor.getFirst(dk,dvs,lockMode);
        }
 else {
          status=cursor.getSearchKeyRange(dk,dvs,lockMode);
        }
        if (status == opSuccess) {
          if (log.isDebugEnabled()) {
            log.debug("--> floor --> key=" + LessBytes.toString(start) + " vs found="+ LessBytes.toString(dk.getData()));
          }
          if (!LessBytes.equals(start,dk.getData())) {
            useAltKey=true;
            status=cursor.getPrev(dk,dvs,lockMode);
            if (log.isDebugEnabled())             log.debug("<-- prev -- " + status);
          }
        }
 else {
          status=cursor.getLast(dk,dvs,lockMode);
          if (log.isDebugEnabled()) {
            log.debug("--> floor --> tolast key=" + LessBytes.toString(start) + " vs last="+ LessBytes.toString(dk.getData()));
          }
        }
        if (status == opSuccess || (useAltKey && !mustInclude)) {
          if (!keyonly) {
            cursor.getCurrent(dvs,dv,lockMode);
          }
          next=current();
          if (log.isDebugEnabled())           log.debug("--> next key=" + LessBytes.toString(next.getKey()));
synchronized (openIterators) {
            openIterators.add(this);
          }
        }
 else {
          close();
        }
      }
 catch (      EnvironmentFailureException e) {
        if (cursor != null) {
          log.warn("Closing cursor");
          cursor.close();
        }
        throw (e);
      }
    }
    @Override protected void finalize(){
      close();
    }
    @Override public void close(){
      if (cursor != null) {
        cursor.close();
        cursor=null;
synchronized (openIterators) {
          openIterators.remove(this);
        }
      }
    }
    private Map.Entry<byte[],byte[]> current(){
      if (keyonly) {
        return new BytePageEntry(dk.getData());
      }
 else {
        return new BytePageEntry(dk.getData(),dv.getData());
      }
    }
    @Override public boolean hasNext(){
      if (next == null && cursor != null) {
        OperationStatus status;
        if (keyonly) {
          status=cursor.getNext(dk,dvs,lockMode);
        }
 else {
          status=cursor.getNext(dk,dv,lockMode);
        }
        if (status == opSuccess) {
          next=current();
          if (log.isDebugEnabled())           log.debug("--  hasNext key=" + LessBytes.toString(next.getKey()));
        }
 else {
          close();
        }
      }
      return next != null;
    }
    @Override public Map.Entry<byte[],byte[]> next(){
      if (hasNext()) {
        Map.Entry<byte[],byte[]> ret=next;
        if (log.isDebugEnabled())         log.debug("<-- next key=" + LessBytes.toString(next.getKey()));
        next=null;
        return ret;
      }
      throw new NoSuchElementException();
    }
    @Override public void remove(){
      if (cursor.delete() != opSuccess) {
        throw new RuntimeException("unable to delete");
      }
    }
  }
;
}

