/** 
 * Apply explicit overrides to a set of dependencies from a project. The explicit overrides come from dependencyExclusion. However they have to be separated out from standard overrides so we can easily ignore any property references (and overwrite them).
 * @param project the current Project
 * @param dependencies dependencies to check
 * @param explicitOverrides a custom map to handle wildcard overrides
 * @param state the CommonState, to retrieve Common Properties
 * @param versionPropertyUpdateMap properties to update
 * @throws ManipulationException if an error occurs
 */
private void applyExplicitOverrides(final Project project,final Map<ArtifactRef,Dependency> dependencies,final WildcardMap<String> explicitOverrides,final CommonState state,final Map<Project,Map<String,PropertyMapper>> versionPropertyUpdateMap) throws ManipulationException {
  for (  final ArtifactRef dependency : dependencies.keySet()) {
    final ProjectRef groupIdArtifactId=new SimpleProjectRef(dependency.getGroupId(),dependency.getArtifactId());
    if (explicitOverrides.containsKey(groupIdArtifactId)) {
      final String overrideVersion=explicitOverrides.get(groupIdArtifactId);
      final String oldVersion=dependencies.get(dependency).getVersion();
      if (isEmpty(overrideVersion) || isEmpty(oldVersion)) {
        if (isEmpty(oldVersion)) {
          logger.debug("Unable to force align as no existing version field to update for " + groupIdArtifactId + "; ignoring");
        }
 else {
          logger.warn("Unable to force align as override version is empty for " + groupIdArtifactId + "; ignoring");
        }
      }
 else {
        for (        String target : overrideVersion.split(",")) {
          if (target.startsWith("+")) {
            logger.info("Adding dependency exclusion {} to dependency {} ",target.substring(1),dependency);
            Exclusion e=new Exclusion();
            e.setGroupId(target.substring(1).split(":")[0]);
            e.setArtifactId(target.split(":")[1]);
            dependencies.get(dependency).addExclusion(e);
          }
 else {
            logger.info("Explicit overrides : force aligning {} to {}.",groupIdArtifactId,target);
            if (!PropertiesUtils.cacheProperty(project,state,versionPropertyUpdateMap,oldVersion,target,dependency,true)) {
              if (oldVersion.contains("${")) {
                logger.warn("Overriding version with {} when old version contained a property {} ",target,oldVersion);
              }
              dependencies.get(dependency).setVersion(target);
            }
          }
        }
      }
    }
  }
}

public Acronym getAcronym(){
  String sf="";
  String lf="";
  String preSF="";
  String preLF="";
  boolean started=false;
  int latestWordStart=-1;
  int numDeletions=0;
  int score=0;
  for (int i=0; i < _sAlign.size(); i++) {
    String sPart=_sAlign.get(i);
    String lPart=_lAlign.get(i);
    T emission=_emissionsPath.get(i);
    if (!started && emission.name().contains("none")) {
      if (Character.isDigit(lPart.charAt(0))) {
        latestWordStart=i;
      }
 else       if (Character.isWhitespace(lPart.charAt(0)) || Character.isLetter(lPart.charAt(0))) {
        latestWordStart=-1;
        preSF="";
        preLF="";
        numDeletions=0;
        score=0;
      }
      if (latestWordStart != -1) {
        preSF+=sPart;
        preLF+=lPart;
        if (emission.name().startsWith("e_D_") || emission.name().startsWith("e_DL_")) {
          numDeletions++;
          score--;
        }
 else         if (emission.name().startsWith("e_M_") || emission.name().contains("word")) {
          score++;
        }
      }
      continue;
    }
    started=true;
    if (emission.name().startsWith("e_D_") || emission.name().startsWith("e_DL_")) {
      numDeletions++;
      score--;
    }
 else     if (emission.name().startsWith("e_M_") && (emission.name().contains("word") || emission.name().contains("Word"))) {
      score++;
    }
    sf+=sPart;
    lf+=lPart;
  }
  if (sf.isEmpty() || lf.isEmpty())   return null;
  if (sf.equalsIgnoreCase(lf))   return null;
  String finalSF=preSF + sf;
  String finalLF=preLF + lf;
  if (finalSF.length() == 1 && finalLF.indexOf(" ") != -1)   return null;
  _numDeletionsInAcronym=numDeletions;
  _acronymScore=score;
  if (_acronymScore < 0)   return null;
  return new Acronym(finalSF,finalLF);
}

public List<AnswerType> classify(Instance instance){
