@Override public <T>T suggest(Class<T> as,SuggestDefinition suggestionDef){
  RequestParameters params=new RequestParameters();
  String suggestCriteria=suggestionDef.getStringCriteria();
  String[] queries=suggestionDef.getQueryStrings();
  String optionsName=suggestionDef.getOptionsName();
  Integer limit=suggestionDef.getLimit();
  Integer cursorPosition=suggestionDef.getCursorPosition();
  if (suggestCriteria != null) {
    params.add("partial-q",suggestCriteria);
  }
  if (optionsName != null) {
    params.add("options",optionsName);
  }
  if (limit != null) {
    params.add("limit",Long.toString(limit));
  }
  if (cursorPosition != null) {
    params.add("cursor-position",Long.toString(cursorPosition));
  }
  if (queries != null) {
    for (    String stringQuery : queries) {
      params.add("q",stringQuery);
    }
  }
  Request.Builder requestBldr=null;
  requestBldr=setupRequest("suggest",params,null,MIMETYPE_APPLICATION_XML);
  requestBldr=addTelemetryAgentId(requestBldr);
  Function<Request.Builder,Response> doGetFunction=new Function<Request.Builder,Response>(){
    public Response apply(    Request.Builder funcBuilder){
      return sendRequestOnce(funcBuilder.get().build());
    }
  }
;
  Response response=sendRequestWithRetry(requestBldr,doGetFunction,null);
  int status=response.code();
  if (status == STATUS_FORBIDDEN) {
    throw new ForbiddenUserException("User is not allowed to get suggestions",extractErrorFields(response));
  }
  if (status != STATUS_OK) {
    throw new FailedRequestException("Suggest call failed: " + getReasonPhrase(response),extractErrorFields(response));
  }
  ResponseBody body=response.body();
  T entity=body.contentLength() != 0 ? getEntity(body,as) : null;
  if (entity == null || (as != InputStream.class && as != Reader.class)) {
    response.close();
  }
  return entity;
}

private void containsNone(String excludedPrefix,Iterable<? extends E> excluded){
  Collection<A> actual=iterableToCollection(getCastActual());
  ListMultimap<E,A> present=LinkedListMultimap.create();
  Correspondence.ExceptionStore exceptions=Correspondence.ExceptionStore.forIterable();
  for (  E excludedItem : Sets.newLinkedHashSet(excluded)) {
    for (    A actualItem : actual) {
      if (correspondence.safeCompare(actualItem,excludedItem,exceptions)) {
        present.put(excludedItem,actualItem);
      }
    }
  }
  if (!present.isEmpty()) {
    StringBuilder presentDescription=new StringBuilder();
    for (    E excludedItem : present.keySet()) {
      if (presentDescription.length() > 0) {
        presentDescription.append(", ");
      }
      List<A> actualItems=present.get(excludedItem);
      if (actualItems.size() == 1) {
        presentDescription.append(actualItems.get(0)).append(" which corresponds to ").append(excludedItem);
      }
 else {
        presentDescription.append(actualItems).append(" which all correspond to ").append(excludedItem);
      }
    }
    subject.failWithoutActual(facts(simpleFact(lenientFormat("Not true that <%s> contains no element that %s %s <%s>. " + "It contains <[%s]>",subject.actualCustomStringRepresentationForPackageMembersToCall(),correspondence,excludedPrefix,excluded,presentDescription))).and(exceptions.describeAsAdditionalInfo()));
    return;
  }
  if (exceptions.hasCompareException()) {
    subject.failWithActual(exceptions.describeAsMainCause().and(simpleFact("comparing contents by testing that no element " + correspondence + " any forbidden value"),fact("expected not to contain any of",excluded)));
  }
}

