 * @return # of entries written to Rtable 
 */
private long singleCheckWriteDegrees(Collection<String> questionNodes,String Rtable,Authorizations Sauthorizations,byte[] degColumn,String edgeSepStr,ScalarType degSumType,ColumnVisibility newVisibility){
  if (newVisibility == null)   newVisibility=new ColumnVisibility();
  Scanner scan;
  BatchWriter bw;
  try {
    scan=connector.createScanner(Rtable,Sauthorizations);
    bw=connector.createBatchWriter(Rtable,new BatchWriterConfig());
  }
 catch (  TableNotFoundException e) {
    log.error("crazy",e);
    throw new RuntimeException(e);
  }
  MathTwoScalar summer=null;
  if (degSumType != null) {
    summer=new MathTwoScalar();
    summer.init(MathTwoScalar.optionMap(ScalarOp.PLUS,degSumType,null,true),null);
  }
  List<Range> rangeList;
{
    Collection<Range> rs=new TreeSet<>();
    for (    String node : questionNodes) {
      rs.add(Range.prefix(node));
    }
    rangeList=Range.mergeOverlapping(rs);
  }
  long totalWritten=0;
  try {
    Text row=new Text();
    RANGELOOP:     for (    Range range : rangeList) {
      boolean first=true;
      int cnt=0, pos=-1;
      if (summer != null)       summer.reset();
      scan.setRange(range);
      for (      Map.Entry<Key,Value> entry : scan) {
        if (first) {
          pos=entry.getKey().getRow(row).find(edgeSepStr);
          if (pos == -1)           continue RANGELOOP;
          first=false;
        }
        if (summer == null)         cnt++;
 else         summer.update(entry.getKey(),entry.getValue());
      }
      Mutation m=new Mutation(row.getBytes(),0,pos);
      m.put(GraphuloUtil.EMPTY_BYTES,degColumn,newVisibility,summer == null ? String.valueOf(cnt).getBytes(StandardCharsets.UTF_8) : summer.getForClient());
      bw.addMutation(m);
      totalWritten++;
    }
  }
 catch (  MutationsRejectedException e) {
    log.error("canceling in-degree ingest because in-degree mutations rejected sending to Rtable " + Rtable,e);
    throw new RuntimeException(e);
  }
 finally {
    scan.close();
    try {
      bw.close();
    }
 catch (    MutationsRejectedException e) {
      log.error("in-degree mutations rejected sending to Rtable " + Rtable,e);
    }
  }
  return totalWritten;
}

