/** 
 * 12.2 Specification of Mappings In the Web application deployment descriptor, the following syntax is used to define mappings: A string beginning with a â€˜/â€™ character and ending with a â€˜/*â€™ suffix is used for path mapping. A string beginning with a â€˜*.â€™ prefix is used as an extension mapping. The empty string ("") is a special URL pattern that exactly maps to the application's context root, i.e., requests of the form  http://host:port/<contextroot>/. In this case the path info is â€™/â€™ and the servlet path and context path is empty string (â€œâ€œ). A string containing only the â€™/â€™ character indicates the "default" servlet of the application. In this case the servlet path is the request URI minus the context path and the path info is null. All other strings are used for exact matches only
 * @param httpServletRequest
 * @return
 */
public static String getBestRelativeURI(HttpServletRequest httpServletRequest){
  String requestURI=httpServletRequest.getRequestURI();
  if (null == requestURI)   return null;
  int bestBaseURILength=httpServletRequest.getContextPath().length();
  String servletPath=httpServletRequest.getServletPath();
  if (null != servletPath) {
    String pathInfo=httpServletRequest.getPathInfo();
    if (null != pathInfo && !pathInfo.isEmpty()) {
      bestBaseURILength+=servletPath.length();
      if (servletPath.endsWith("/"))       bestBaseURILength--;
    }
 else {
      ServletContext servletContext=httpServletRequest.getServletContext();
      for (      String mapping : ServletRegistrationUtil.getServletMappings(servletContext)) {
        if (mapping.equals(servletPath) || (mapping.endsWith("/*") && mapping.substring(0,mapping.length() - 2).equals(servletPath))) {
          bestBaseURILength+=servletPath.length();
          if (servletPath.endsWith("/"))           bestBaseURILength--;
          break;
        }
      }
    }
  }
  return requestURI.substring(bestBaseURILength);
}

public void hl_decode_mb_internal(int simple){
  int mb_x=s.mb_x;
  int mb_y=s.mb_y;
  int mb_xy=this.mb_xy;
  int mb_type=(int)s.current_picture.mb_type_base[s.current_picture.mb_type_offset + mb_xy];
  int[] dest_y_base, dest_cb_base, dest_cr_base;
  int dest_y_offset, dest_cb_offset, dest_cr_offset;
  int linesize, uvlinesize;
  int i;
  int[] block_offset_base=this.block_offset;
  int block_offset_offset=0;
  boolean transform_bypass=((0 == simple) && (s.qscale == 0 && this.sps.transform_bypass != 0));
  int is_h264=1;
  dest_y_base=s.current_picture.data_base[0];
  dest_cb_base=s.current_picture.data_base[1];
  dest_cr_base=s.current_picture.data_base[2];
  dest_y_offset=s.current_picture.data_offset[0] + (mb_x + mb_y * s.linesize) * 16;
  dest_cb_offset=s.current_picture.data_offset[1] + (mb_x + mb_y * s.uvlinesize) * 8;
  dest_cr_offset=s.current_picture.data_offset[2] + (mb_x + mb_y * s.uvlinesize) * 8;
  this.list_counts[mb_xy]=(int)this.list_count;
  if (0 == simple && 0 != mb_field_decoding_flag) {
    linesize=this.mb_linesize=s.linesize * 2;
    uvlinesize=this.mb_uvlinesize=s.uvlinesize * 2;
    block_offset_base=this.block_offset;
    block_offset_offset=24;
    if ((mb_y & 1) != 0) {
      dest_y_offset-=s.linesize * 15;
      dest_cb_offset-=s.uvlinesize * 7;
      dest_cr_offset-=s.uvlinesize * 7;
    }
    if (0 != mb_aff_frame) {
      int list;
      for (list=0; list < this.list_count; list++) {
        if (0 == ((mb_type) & ((MB_TYPE_P0L0 | MB_TYPE_P1L0) << (2 * (list)))))         continue;
        if (0 != (mb_type & MB_TYPE_16x16)) {
          int[] ref_base=this.ref_cache[list];
          int ref_offset=scan8[0];
          Rectangle.fill_rectangle_sign(ref_base,ref_offset,4,4,8,(16 + ref_base[ref_offset]) ^ (s.mb_y & 1),1);
        }
 else {
          for (i=0; i < 16; i+=4) {
            int ref=this.ref_cache[list][scan8[i]];
            if (ref >= 0)             Rectangle.fill_rectangle_sign(this.ref_cache[list],scan8[i],2,2,8,(16 + ref) ^ (s.mb_y & 1),1);
          }
        }
      }
    }
  }
 else {
    linesize=this.mb_linesize=s.linesize;
    uvlinesize=this.mb_uvlinesize=s.uvlinesize;
  }
  if (0 == simple && 0 != (mb_type & MB_TYPE_INTRA_PCM)) {
    for (i=0; i < 16; i++) {
      for (int j=0; j < 8; j++) {
        short val=this.mb[i * 8];
        dest_y_base[dest_y_offset + i * linesize + j * 2]=val & 0x0ff;
        dest_y_base[dest_y_offset + i * linesize + j * 2 + 1]=(val & 0x0ff00) >> 8;
      }
    }
    for (i=0; i < 8; i++) {
      for (int j=0; j < 4; j++) {
        short val1=this.mb[128 + i * 4];
        short val2=this.mb[160 + i * 4];
        dest_cb_base[dest_cb_offset + i * uvlinesize + j * 2]=val1 & 0x0ff;
        dest_cb_base[dest_cb_offset + i * uvlinesize + j * 2 + 1]=(val1 & 0x0ff00) >> 8;
        dest_cr_base[dest_cr_offset + i * uvlinesize + j * 2]=val2 & 0x0ff;
        dest_cr_base[dest_cr_offset + i * uvlinesize + j * 2 + 1]=(val2 & 0x0ff00) >> 8;
      }
    }
  }
 else {
    if (0 != (mb_type & 7)) {
      if (0 != this.deblocking_filter)       xchg_mb_border(dest_y_base,dest_y_offset,dest_cb_base,dest_cb_offset,dest_cr_base,dest_cr_offset,linesize,uvlinesize,1,simple);
      this.hpc.pred8x8[this.chroma_pred_mode].pred8x8(dest_cb_base,dest_cb_offset,uvlinesize);
      this.hpc.pred8x8[this.chroma_pred_mode].pred8x8(dest_cr_base,dest_cr_offset,uvlinesize);
      if (0 != (mb_type & MB_TYPE_INTRA4x4)) {
        if (0 != simple || true) {
          if (0 != (mb_type & MB_TYPE_8x8DCT)) {
            for (i=0; i < 16; i+=4) {
              int[] ptr_base=dest_y_base;
              int ptr_offset=dest_y_offset + block_offset_base[block_offset_offset + i];
              int dir=this.intra4x4_pred_mode_cache[scan8[i]];
              if (transform_bypass && this.sps.profile_idc == 244 && dir <= 1) {
                this.hpc.pred8x8l_add[dir].pred8x8l_add(ptr_base,ptr_offset,this.mb,i * 16,linesize);
              }
 else {
                int nnz=this.non_zero_count_cache[scan8[i]];
                this.hpc.pred8x8l[dir].pred8x8l(ptr_base,ptr_offset,(int)(this.topleft_samples_available << i) & 0x08000,(int)(this.topright_samples_available << i) & 0x04000,linesize);
                if (0 != nnz) {
                  if (nnz == 1 && this.mb[i * 16] != 0) {
                    if (transform_bypass)                     s.dsp.add_pixels8(ptr_base,ptr_offset,this.mb,i * 16,linesize);
 else                     this.h264dsp.h264_idct8_dc_add(ptr_base,ptr_offset,this.mb,i * 16,linesize);
                  }
 else {
                    if (transform_bypass)                     s.dsp.add_pixels8(ptr_base,ptr_offset,this.mb,i * 16,linesize);
 else                     this.h264dsp.h264_idct8_add(ptr_base,ptr_offset,this.mb,i * 16,linesize);
                  }
                }
              }
            }
          }
 else {
            for (i=0; i < 16; i++) {
              int[] ptr_base=dest_y_base;
              int ptr_offset=dest_y_offset + block_offset_base[block_offset_offset + i];
              int dir=this.intra4x4_pred_mode_cache[scan8[i]];
              if (transform_bypass && this.sps.profile_idc == 244 && dir <= 1) {
                this.hpc.pred4x4_add[dir].pred4x4_add(ptr_base,ptr_offset,this.mb,i * 16,linesize);
              }
 else {
                int[] topright_base=null;
                int topright_offset=0;
                int nnz, tr;
                if (dir == H264PredictionContext.DIAG_DOWN_LEFT_PRED || dir == H264PredictionContext.VERT_LEFT_PRED) {
                  int topright_avail=((int)this.topright_samples_available << i) & 0x08000;
                  if (0 == topright_avail) {
                    tr=ptr_base[ptr_offset + 3 - linesize];
                    topright_base=new int[]{tr,tr,tr,tr};
                    topright_offset=0;
                  }
 else {
                    topright_base=ptr_base;
                    topright_offset=ptr_offset + 4 - linesize;
                  }
                }
 else                 topright_base=null;
                this.hpc.pred4x4[dir].pred4x4(ptr_base,ptr_offset,topright_base,topright_offset,linesize);
                nnz=this.non_zero_count_cache[scan8[i]];
                if (0 != nnz) {
                  if (0 != is_h264) {
                    if (nnz == 1 && 0 != this.mb[i * 16]) {
                      if (transform_bypass)                       s.dsp.add_pixels4(ptr_base,ptr_offset,this.mb,i * 16,linesize);
 else                       this.h264dsp.h264_idct_dc_add(ptr_base,ptr_offset,this.mb,i * 16,linesize);
                    }
 else {
                      if (transform_bypass)                       s.dsp.add_pixels4(ptr_base,ptr_offset,this.mb,i * 16,linesize);
 else                       this.h264dsp.h264_idct_add(ptr_base,ptr_offset,this.mb,i * 16,linesize);
                    }
                  }
 else {
                  }
                }
              }
            }
          }
        }
      }
 else {
        this.hpc.pred16x16[this.intra16x16_pred_mode].pred16x16(dest_y_base,dest_y_offset,linesize);
        if (0 != is_h264) {
          if (0 != this.non_zero_count_cache[scan8[LUMA_DC_BLOCK_INDEX]]) {
            if (!transform_bypass)             this.h264dsp.h264_luma_dc_dequant_idct(this.mb,0,this.mb_luma_dc,0,(int)this.dequant4_coeff[0][s.qscale][0]);
 else {
              final int[] dc_mapping={0 * 16,1 * 16,4 * 16,5 * 16,2 * 16,3 * 16,6 * 16,7 * 16,8 * 16,9 * 16,12 * 16,13 * 16,10 * 16,11 * 16,14 * 16,15 * 16};
              for (i=0; i < 16; i++)               this.mb[dc_mapping[i]]=this.mb_luma_dc[i];
            }
          }
        }
 else {
        }
      }
      if (0 != this.deblocking_filter)       xchg_mb_border(dest_y_base,dest_y_offset,dest_cb_base,dest_cb_offset,dest_cr_base,dest_cr_offset,linesize,uvlinesize,0,simple);
    }
 else     if (0 != is_h264) {
      hl_motion(dest_y_base,dest_y_offset,dest_cb_base,dest_cb_offset,dest_cr_base,dest_cr_offset,s.me.qpel_put,s.dsp.put_h264_chroma_pixels_tab,s.me.qpel_avg,s.dsp.avg_h264_chroma_pixels_tab,this.h264dsp.weight_h264_pixels_tab,this.h264dsp.biweight_h264_pixels_tab);
    }
    if (0 == (mb_type & MB_TYPE_INTRA4x4)) {
      if (0 != is_h264) {
        if (0 != (mb_type & MB_TYPE_INTRA16x16)) {
          if (transform_bypass) {
            if (this.sps.profile_idc == 244 && (this.intra16x16_pred_mode == H264PredictionContext.VERT_PRED8x8 || this.intra16x16_pred_mode == H264PredictionContext.HOR_PRED8x8)) {
              this.hpc.pred16x16_add[this.intra16x16_pred_mode].pred16x16_add(dest_y_base,dest_y_offset,block_offset_base,block_offset_offset,this.mb,0,linesize);
            }
 else {
              for (i=0; i < 16; i++) {
                if (0 != this.non_zero_count_cache[scan8[i]] || 0 != this.mb[i * 16])                 s.dsp.add_pixels4(dest_y_base,dest_y_offset + block_offset_base[block_offset_offset + i],this.mb,i * 16,linesize);
              }
            }
          }
 else {
            this.h264dsp.h264_idct_add16intra(dest_y_base,dest_y_offset,block_offset_base,block_offset_offset,this.mb,0,linesize,this.non_zero_count_cache);
          }
        }
 else         if (0 != (this.cbp & 15)) {
          if (transform_bypass) {
            int di=(mb_type & MB_TYPE_8x8DCT) != 0 ? 4 : 1;
            for (i=0; i < 16; i+=di) {
              if (0 != this.non_zero_count_cache[scan8[i]]) {
                if ((mb_type & MB_TYPE_8x8DCT) != 0)                 s.dsp.add_pixels8(dest_y_base,dest_y_offset + block_offset_base[block_offset_offset + i],this.mb,i * 16,linesize);
 else                 s.dsp.add_pixels4(dest_y_base,dest_y_offset + block_offset_base[block_offset_offset + i],this.mb,i * 16,linesize);
              }
