private StringBuffer getTextFromPDF(byte[] doc) throws GenericSearchException {
  if (logger.isDebugEnabled())   logger.debug("getTextFromPDF");
  StringBuffer docText=new StringBuffer();
  ByteArrayInputStream bais=null;
  try {
    bais=new ByteArrayInputStream(doc);
  }
 catch (  Exception e) {
    closeBAIS(bais);
    if (logger.isDebugEnabled())     logger.debug("getTextFromPDF new ByteArrayInputStream: ",e);
    throw new GenericSearchException("getTextFromPDF new ByteArrayInputStream: ",e);
  }
  if (logger.isDebugEnabled())   logger.debug("getTextFromPDF new ByteArrayInputStream");
  PDFParser parser;
  try {
    parser=new PDFParser(bais);
  }
 catch (  Exception e) {
    closeBAIS(bais);
    if (logger.isDebugEnabled())     logger.debug("getTextFromPDF new PDFParser: ",e);
    throw new GenericSearchException("getTextFromPDF new PDFParser: ",e);
  }
  if (logger.isDebugEnabled())   logger.debug("getTextFromPDF new PDFParser");
  try {
    parser.parse();
  }
 catch (  Exception e) {
    closeBAIS(bais);
    if (logger.isDebugEnabled())     logger.debug("getTextFromPDF parser.parse: ",e);
    throw new GenericSearchException("getTextFromPDF parser.parse: ",e);
  }
  if (logger.isDebugEnabled())   logger.debug("getTextFromPDF parser.parse");
  COSDocument cosDoc=null;
  try {
    cosDoc=parser.getDocument();
  }
 catch (  Exception e) {
    closeBAIS(bais);
    closeCOSDocument(cosDoc);
    if (logger.isDebugEnabled())     logger.debug("getTextFromPDF parser.getDocument: ",e);
    throw new GenericSearchException("getTextFromPDF parser.getDocument: ",e);
  }
  if (logger.isDebugEnabled())   logger.debug("getTextFromPDF parser.getDocument");
  PDDocument pdDoc=null;
  try {
    pdDoc=new PDDocument(cosDoc);
  }
 catch (  Exception e) {
    closeBAIS(bais);
    closeCOSDocument(cosDoc);
    closePDDocument(pdDoc);
    if (logger.isDebugEnabled())     logger.debug("getTextFromPDF new PDDocument: ",e);
    throw new GenericSearchException("getTextFromPDF new PDDocument: ",e);
  }
  if (logger.isDebugEnabled())   logger.debug("getTextFromPDF new PDDocument isEncrypted=" + pdDoc.isEncrypted() + " getNumberOfPages="+ pdDoc.getNumberOfPages());
  PDFTextStripper stripper;
  try {
    stripper=new PDFTextStripper();
  }
 catch (  Exception e) {
    closeBAIS(bais);
    closeCOSDocument(cosDoc);
    closePDDocument(pdDoc);
    if (logger.isDebugEnabled())     logger.debug("getTextFromPDF new PDFTextStripper: ",e);
    throw new GenericSearchException("getTextFromPDF new PDFTextStripper: ",e);
  }
  if (logger.isDebugEnabled())   logger.debug("getTextFromPDF new PDFTextStripper getStartPage=" + stripper.getStartPage() + " getEndPage="+ stripper.getEndPage());
  String docString="";
  try {
    docString=stripper.getText(pdDoc);
  }
 catch (  Exception e) {
    if (logger.isDebugEnabled())     logger.debug("getTextFromPDF stripper.getText: ",e);
    throw new GenericSearchException("getTextFromPDF stripper.getText: ",e);
  }
 finally {
    if (logger.isDebugEnabled())     logger.debug("getTextFromPDF stripper.getText finally");
    closeBAIS(bais);
    closeCOSDocument(cosDoc);
    closePDDocument(pdDoc);
  }
  if (logger.isDebugEnabled())   logger.debug("getTextFromPDF stripper.getText");
  docText=new StringBuffer(docString);
  char c;
  for (int i=0; i < docText.length(); i++) {
    c=docText.charAt(i);
    if (c < 32 && c != 9 && c != 10 && c != 13) {
      if (logger.isDebugEnabled())       logger.debug("getTextFromPDF index=" + i + " char="+ c+ " set to 32");
      docText.replace(i,i + 1," ");
    }
  }
  return docText;
}

public SignatureResult addMethod(MethodEntity method,String realName){
  String name=realName == null ? method.getLowerName() : realName;
  SignatureResult addResult=new SignatureResult();
  if (method.isAbstract && method.isFinal) {
    addResult.add(InvalidMethod.error(InvalidMethod.Kind.FINAL_ABSTRACT,method));
  }
 else   if (method.isAbstractable() && !(method.isAbstract || type == Type.INTERFACE)) {
    addResult.add(InvalidMethod.error(InvalidMethod.Kind.NON_ABSTRACT,method));
  }
 else   if (method.isAbstract && !method.isAbstractable()) {
    addResult.add(InvalidMethod.error(InvalidMethod.Kind.NON_ABSTRACTABLE,method));
  }
 else   if (method.isAbstract && !(this.isAbstract || isTrait())) {
    addResult.add(InvalidMethod.error(InvalidMethod.Kind.NON_EXISTS,method));
  }
 else   if (type == Type.INTERFACE && (method.modifier != Modifier.PUBLIC || method.isFinal)) {
    addResult.add(InvalidMethod.error(InvalidMethod.Kind.INVALID_ACCESS_FOR_INTERFACE,method));
  }
  if (magicSignatureClass != null) {
    MethodEntity systemMethod=magicSignatureClass.findMethod(name.toLowerCase());
    if (systemMethod != null && method.clazz.getId() == getId()) {
      if (method.prototype == null)       method.setPrototype(systemMethod);
      if (systemMethod.getModifier() == Modifier.PUBLIC && method.getModifier() != Modifier.PUBLIC) {
        addResult.add(InvalidMethod.warning(InvalidMethod.Kind.MAGIC_MUST_BE_PUBLIC,method));
      }
      if (!systemMethod.equalsBySignature(method,false)) {
        addResult.add(InvalidMethod.error(InvalidMethod.Kind.INVALID_SIGNATURE,method));
      }
 else       if (systemMethod.isStatic && !method.isStatic)       addResult.add(InvalidMethod.warning(InvalidMethod.Kind.MUST_STATIC,method));
 else       if (!systemMethod.isStatic && method.isStatic) {
        addResult.add(InvalidMethod.warning(InvalidMethod.Kind.MUST_NON_STATIC,method));
      }
    }
  }
  if (parent == null || (!name.equals(parent.lowerName) || !methods.containsKey(name))) {
    this.methods.put(name,method);
  }
  if (name.equals(lowerName) && !isTrait()) {
    methods.put("__construct",method);
  }
  return addResult;
}

