public static SelectExprProcessor getInsertUnderlyingNonJoin(EventAdapterService eventAdapterService,EventType eventType,boolean isUsingWildcard,StreamTypeService typeService,ExprEvaluator[] expressionNodes,String[] columnNames,Object[] expressionReturnTypes,EngineImportService engineImportService,InsertIntoDesc insertIntoDesc,String[] columnNamesAsProvided) throws ExprValidationException {
  if (expressionReturnTypes.length == 1 && expressionReturnTypes[0] instanceof Class && eventType instanceof BaseNestableEventType && JavaClassHelper.isSubclassOrImplementsInterface((Class)expressionReturnTypes[0],eventType.getUnderlyingType()) && insertIntoDesc.getColumnNames().isEmpty() && columnNamesAsProvided[0] == null) {
    if (eventType instanceof MapEventType) {
      return new SelectExprInsertNativeExpressionCoerceMap(eventType,expressionNodes[0],eventAdapterService);
    }
    return new SelectExprInsertNativeExpressionCoerceObjectArray(eventType,expressionNodes[0],eventAdapterService);
  }
  Set<WriteablePropertyDescriptor> writableProps=eventAdapterService.getWriteableProperties(eventType);
  boolean isEligible=checkEligible(eventType,writableProps);
  if (!isEligible) {
    return null;
  }
  try {
    return initializeSetterManufactor(eventType,writableProps,isUsingWildcard,typeService,expressionNodes,columnNames,expressionReturnTypes,engineImportService,eventAdapterService);
  }
 catch (  ExprValidationException ex) {
    if (!(eventType instanceof BeanEventType)) {
      throw ex;
    }
    try {
      return initializeCtorInjection(eventType,expressionNodes,typeService,expressionReturnTypes,engineImportService,eventAdapterService);
    }
 catch (    ExprValidationException ctorEx) {
      if (writableProps.isEmpty()) {
        throw ctorEx;
      }
      throw ex;
    }
  }
}

