/** 
 * Parse the given <code>text</code> and produce an array of {@link SearchTerm} objects that describe text to match as well asmetadata about the way it should be used.
 * @param text the raw text entered by a user
 * @return SearchTerm an object encapsulating a single raw search term aswell as metadata related to the use of the SearchTerm
 */
public static <E>SearchTerm<E>[] parse(String text){
  return parse(text,Collections.<SearchEngineTextMatcherEditor.Field<E>>emptySet());
}
/** 
 * Parse the given <code>text</code> and produce an array of {@link SearchTerm} objects that describe text to match as well asmetadata about the way it should be used. When parsing the text, the given Set of  {@link SearchEngineTextMatcherEditor.Field} objectsshould be considered to detect when the user has entered a field-specific SearchTerm.
 * @param text the raw text entered by a user
 * @param fields a Set of objects describing each field that can be independently matched
 * @return SearchTerm an object encapsulating a single raw search term aswell as metadata related to the use of the SearchTerm
 */
public static <E>SearchTerm<E>[] parse(String text,Set<SearchEngineTextMatcherEditor.Field<E>> fields){
  final List<SearchTerm<E>> searchTerms=new ArrayList<>();
  final Map<String,SearchEngineTextMatcherEditor.Field<E>> fieldMap=new HashMap<>();
  for (Iterator<SearchEngineTextMatcherEditor.Field<E>> f=fields.iterator(); f.hasNext(); ) {
    SearchEngineTextMatcherEditor.Field<E> field=f.next();
    fieldMap.put(field.getName(),field);
  }
  StringBuffer searchTermText=new StringBuffer();
  SearchEngineTextMatcherEditor.Field<E> field=null;
  boolean negated=false, required=false, insideTerm=false, insideQuotedTerm=false;
  for (int i=0, n=text.length(); i < n; i++) {
    final char c=text.charAt(i);
    if (insideTerm) {
      final boolean endOfTerm=c == '"' || (!insideQuotedTerm && Character.isWhitespace(c));
      if (endOfTerm) {
        if (searchTermText.length() > 0) {
          searchTerms.add(new SearchTerm<>(searchTermText.toString(),negated,required,field));
        }
        searchTermText=new StringBuffer();
        field=null;
        negated=required=insideTerm=insideQuotedTerm=false;
      }
 else {
        if (c == ':' && field == null && !insideQuotedTerm) {
          field=fieldMap.get(searchTermText.toString());
          if (field != null) {
            searchTermText=new StringBuffer();
            negated=required=insideTerm=insideQuotedTerm=false;
            continue;
          }
        }
        searchTermText.append(c);
      }
    }
 else {
      if (Character.isWhitespace(c)) {
        field=null;
        negated=required=insideTerm=insideQuotedTerm=false;
        continue;
      }
switch (c) {
case '"':
        insideTerm=true;
      insideQuotedTerm=true;
    break;
case '+':
  required=true;
break;
case '-':
negated=true;
break;
default :
searchTermText.append(c);
insideTerm=true;
break;
}
}
}
if (searchTermText.length() > 0) searchTerms.add(new SearchTerm<>(searchTermText.toString(),negated,required,field));
return searchTerms.toArray(new SearchTerm[searchTerms.size()]);
}

