@Override public QueryExecution query(RequestContext context,List<FunnelStep> steps,Optional<String> dimension,Optional<String> segment,LocalDate startDate,LocalDate endDate,Optional<FunnelWindow> window,ZoneId zoneId,Optional<List<String>> connectors,FunnelType funnelType){
  if (dimension.isPresent()) {
    String val=dimension.get();
    if (val.equals(projectConfig.getTimeColumn())) {
      if (!segment.isPresent() || !timeStampMapping.containsKey(FunnelTimestampSegments.valueOf(segment.get().toUpperCase()))) {
        throw new RakamException("When dimension is time, segmenting should be done on timestamp field.",BAD_REQUEST);
      }
    }
    Optional<SchemaField> fieldType=metastore.getCollections(context.project).entrySet().stream().filter(c -> !c.getValue().contains(val)).findAny().get().getValue().stream().filter(d -> d.getName().equals(val)).findAny();
    if (!fieldType.isPresent()) {
      throw new RakamException("Dimension does not exist.",BAD_REQUEST);
    }
    if (fieldType.get().getType().getPrettyName().equals(TIMESTAMP.getPrettyName())) {
      if (!segment.isPresent() || !timeStampMapping.containsKey(FunnelTimestampSegments.valueOf(segment.get().toUpperCase()))) {
        throw new RakamException("When dimension is of type TIMESTAMP, segmenting should be done on timestamp field.",BAD_REQUEST);
      }
    }
  }
 else   if (segment.isPresent()) {
    throw new RakamException("Dimension can't be null when segment is not.",BAD_REQUEST);
  }
  String startDateStr=TIMESTAMP_FORMATTER.format(startDate.atStartOfDay(zoneId));
  String endDateStr=TIMESTAMP_FORMATTER.format(endDate.plusDays(1).atStartOfDay(zoneId));
  if (funnelType == FunnelType.ORDERED) {
    throw new RakamException("Ordered funnel query is not supported when approximation is enabled.",BAD_REQUEST);
  }
  if (window.isPresent()) {
    throw new RakamException("Windowed funnel query is not supported when approximation is enabled.",BAD_REQUEST);
  }
  String query;
  if (dimension.isPresent()) {
    String queries=IntStream.range(0,steps.size()).mapToObj(step -> String.format("(select %s as dimension, %s as _user, %d as step from %s where %s between timestamp '%s' and timestamp '%s' and %s)",dimension.map(ValidationUtil::checkTableColumn).map(v -> segment.isPresent() ? applySegment(v,segment) : v).orElse(""),checkTableColumn(projectConfig.getUserColumn()),step,checkCollection(steps.get(step).getCollection()),checkTableColumn(projectConfig.getTimeColumn()),startDateStr,endDateStr,getFilterExp(steps.get(step)))).collect(Collectors.joining(" union all "));
    query=format("select step, dimension, cast(approx_funnel(user_sets) OVER (PARTITION BY dimension ORDER BY step) as bigint) as count from (select dimension, step, approx_set(_user) user_sets from (%s) where dimension is not null group by 1, 2)",queries);
  }
 else {
    String queries=steps.stream().map(step -> String.format("(select approx_set(%s) from %s where %s between timestamp '%s' and timestamp '%s' and %s )",checkTableColumn(projectConfig.getUserColumn()),checkCollection(step.getCollection()),checkTableColumn(projectConfig.getTimeColumn()),startDateStr,endDateStr,getFilterExp(step))).collect(Collectors.joining(", "));
    query=String.format("select funnel_steps(array[%s])",queries);
  }
  QueryExecution queryExecution=executor.executeQuery(context,query,Optional.empty(),null,zoneId,10000);
  return new DelegateQueryExecution(queryExecution,result -> {
    if (result.isFailed()) {
      return result;
    }
    List<List<Object>> newResult=new ArrayList<>();
    List<SchemaField> metadata;
    if (dimension.isPresent()) {
      metadata=result.getMetadata();
      newResult=result.getResult();
      for (      List<Object> objects : result.getResult()) {
        objects.set(0,"Step " + ((int)objects.get(0) + 1));
      }
    }
 else {
      metadata=ImmutableList.of(new SchemaField("step",STRING),new SchemaField("count",LONG));
      ArrayList<Long> step=(ArrayList<Long>)result.getResult().get(0).get(0);
      for (int i=0; i < step.size(); i++) {
        Object value=step.get(i);
        newResult.add(ImmutableList.of("Step " + (i + 1),value == null ? 0 : value));
      }
    }
    return new QueryResult(metadata,newResult,result.getProperties());
  }
);
}

public void testIsValidFileUpload() throws IOException {
  System.out.println("isValidFileUpload");
  String filepath=new File(System.getProperty("user.dir")).getCanonicalPath();
  String filename="aspect.txt";
  File parent=new File("/").getCanonicalFile();
  ValidationErrorList errors=new ValidationErrorList();
  byte[] content=null;
  try {
    content="This is some file content".getBytes(PREFERRED_ENCODING);
  }
 catch (  UnsupportedEncodingException e) {
    fail(PREFERRED_ENCODING + " not a supported encoding?!?!!!");
  }
  Validator instance=ESAPI.validator();
  assertTrue(instance.isValidFileUpload("test",filepath,filename,parent,content,100,false));
  assertTrue(instance.isValidFileUpload("test",filepath,filename,parent,content,100,false,errors));
  assertTrue(errors.size() == 0);
  filepath="/ridiculous";
  filename="aspect.txt";
  try {
    content="This is some file content".getBytes(PREFERRED_ENCODING);
  }
 catch (  UnsupportedEncodingException e) {
    fail(PREFERRED_ENCODING + " not a supported encoding?!?!!!");
  }
  assertFalse(instance.isValidFileUpload("test",filepath,filename,parent,content,100,false));
  assertFalse(instance.isValidFileUpload("test",filepath,filename,parent,content,100,false,errors));
  assertTrue(errors.size() == 1);
}

