/** 
 * Determines whether a string is a valid JS identifier. 
 */
public static boolean isJSIdentifier(String s){
  return JS_IDENTIFIER_REGEX.test(s);
}
static boolean isJSIdentifier(String s){
  int length=s.length();
  if (length == 0 || Character.isIdentifierIgnorable(s.charAt(0)) || !Character.isJavaIdentifierStart(s.charAt(0))) {
    return false;
  }
  for (int i=1; i < length; i++) {
    if (Character.isIdentifierIgnorable(s.charAt(i)) || !Character.isJavaIdentifierPart(s.charAt(i))) {
      return false;
    }
  }
  return true;
}

void commit(AnnotationBoundaryMap map){
  for (int i=0; i < map.endSize(); ++i) {
    String key=map.getEndKey(i);
    if (!propagating.containsKey(key)) {
      propagating.put(key,active.get(key));
    }
    active.remove(key);
  }
  for (int i=0; i < map.changeSize(); ++i) {
    String key=map.getChangeKey(i);
    ValueUpdate oldActive=active.get(key);
    if (oldActive == null || !ValueUtils.equal(oldActive.oldValue,map.getOldValue(i)) || !ValueUtils.equal(oldActive.newValue,map.getNewValue(i))) {
      if (!propagating.containsKey(key)) {
        propagating.put(key,active.get(key));
      }
      active.put(key,new ValueUpdate(map.getOldValue(i),map.getNewValue(i)));
    }
  }
  output.annotationBoundary(map);
}

