public List<ProviderMethod<?>> getProviderMethods(Binder binder){
  List<ProviderMethod<?>> result=null;
  List<MethodAndAnnotation> methodsAndAnnotations=null;
  Class<?> superMostClass=getDelegateModuleClass();
  for (Class<?> c=superMostClass; c != Object.class && c != null; c=c.getSuperclass()) {
    for (    Method method : DeclaredMembers.getDeclaredMethods(c)) {
      Annotation annotation=getAnnotation(binder,method);
      if (annotation != null) {
        if (isStaticModule() && !Modifier.isStatic(method.getModifiers()) && !Modifier.isAbstract(method.getModifiers())) {
          binder.skipSources(ProviderMethodsModule.class).addError("%s is an instance method, but a class literal was passed. Make this method" + " static or pass an instance of the module instead.",method);
          continue;
        }
        if (result == null) {
          result=new ArrayList<>();
          methodsAndAnnotations=new ArrayList<>();
        }
        ProviderMethod<Object> providerMethod=createProviderMethod(binder,method,annotation);
        if (providerMethod != null) {
          result.add(providerMethod);
        }
        methodsAndAnnotations.add(new MethodAndAnnotation(method,annotation));
        superMostClass=c;
      }
    }
  }
  if (result == null) {
    return ImmutableList.of();
  }
  Multimap<Signature,Method> methodsBySignature=null;
  for (Class<?> c=getDelegateModuleClass(); c != superMostClass; c=c.getSuperclass()) {
    for (    Method method : c.getDeclaredMethods()) {
      if (((method.getModifiers() & (Modifier.PRIVATE | Modifier.STATIC)) == 0) && !method.isBridge() && !method.isSynthetic()) {
        if (methodsBySignature == null) {
          methodsBySignature=HashMultimap.create();
        }
        methodsBySignature.put(new Signature(typeLiteral,method),method);
      }
    }
  }
  if (methodsBySignature != null) {
    for (    MethodAndAnnotation methodAndAnnotation : methodsAndAnnotations) {
      Method method=methodAndAnnotation.method;
      Annotation annotation=methodAndAnnotation.annotation;
      for (      Method matchingSignature : methodsBySignature.get(new Signature(typeLiteral,method))) {
        if (matchingSignature.getDeclaringClass().isAssignableFrom(method.getDeclaringClass())) {
          continue;
        }
        if (overrides(matchingSignature,method)) {
          String annotationString=annotation.annotationType() == Provides.class ? "@Provides" : "@" + annotation.annotationType().getCanonicalName();
          binder.addError("Overriding " + annotationString + " methods is not allowed."+ "\n\t"+ annotationString+ " method: %s\n\toverridden by: %s",method,matchingSignature);
          break;
        }
      }
    }
  }
  return result;
}

public boolean parse(BashPsiBuilder builder){
  final PsiBuilder.Marker selectCommand=builder.mark();
  builder.advanceLexer();
  if (ParserUtil.isIdentifier(builder.getTokenType())) {
    ParserUtil.markTokenAndAdvance(builder,VAR_DEF_ELEMENT);
  }
 else {
    ParserUtil.error(selectCommand,"parser.unexpected.token");
    return false;
  }
  builder.readOptionalNewlines();
  if ((builder.getTokenType() == WORD || builder.getTokenType() == IN_KEYWORD_REMAPPED) && "in".equals(builder.getTokenText())) {
    builder.remapCurrentToken(IN_KEYWORD_REMAPPED);
    builder.advanceLexer();
    if (ParserUtil.isEmptyListFollowedBy(builder,DO_KEYWORD)) {
      ParserUtil.error(builder,"parser.unexpected.token");
      ParserUtil.readEmptyListFollowedBy(builder,DO_KEYWORD);
    }
 else {
      OptionalParseResult result=Parsing.word.parseWordListIfValid(builder,true,false);
      if (result.isValid() && !result.isParsedSuccessfully()) {
        selectCommand.drop();
        return false;
      }
    }
  }
  builder.readOptionalNewlines();
  if (!LoopParserUtil.parseLoopBody(builder,false,false)) {
    selectCommand.drop();
    return false;
  }
  selectCommand.done(SELECT_COMMAND);
  return true;
}

