/** 
 * Return the next envelope height. Switch to the next curve if required.
 * @return     the next envelope height in the range [0..0x40000000]
 */
public int getNextEnvelopeHeight(){
  long currentEnvelopeHeight=envelopeHeight;
switch (curveState) {
case ATTACK_CURVE_STATE:
    stepCurve(envelope.AttackCurveType,envelope.AttackRate);
  if (envelopeHeight >= PSP_SAS_ENVELOPE_HEIGHT_MAX || envelopeHeight < 0) {
    if (envelopeHeight >= PSP_SAS_ENVELOPE_HEIGHT_MAX) {
      envelopeHeight=PSP_SAS_ENVELOPE_HEIGHT_MAX;
    }
    setCurve(DECAY_CURVE_STATE);
  }
break;
case DECAY_CURVE_STATE:
stepCurve(envelope.DecayCurveType,envelope.DecayRate);
if (envelopeHeight < envelope.SustainLevel) {
setCurve(SUSTAIN_CURVE_STATE);
}
break;
case SUSTAIN_CURVE_STATE:
stepCurve(envelope.SustainCurveType,envelope.SustainRate);
break;
case RELEASE_CURVE_STATE:
stepCurve(envelope.ReleaseCurveType,envelope.ReleaseRate);
break;
}
if (tracing) {
sceSasCore.log.trace(String.format("getNextEnvelopeHeight curve=%d, current=0x%08X, next=0x%08X",curveState,currentEnvelopeHeight,envelopeHeight));
}
return getIntEnvelopeHeight(currentEnvelopeHeight);
}

/** 
 * Writes the next line to the file.
 * @param nextLine a string array with each comma-separated element as a separate entry.
 * @throws java.io.IOException if I/O error occurs
 */
public void writeNext(String[] nextLine,boolean quoteall) throws IOException {
  final int colCount=nextLine.length;
  for (int i=0; i < colCount; i++) {
    if (i != 0) {
      writer.append(separator);
    }
    String nextElement=nextLine[i];
    if (nextElement == null) {
      continue;
    }
    final boolean hasSpecialCharacters=nextElement.indexOf(quotechar) != -1 || nextElement.indexOf(escapechar) != -1 || nextElement.indexOf(separator) != -1 || nextElement.contains(lineEnd) || nextElement.contains("\r");
    if ((quoteall || hasSpecialCharacters) && (quotechar != NO_QUOTE_CHARACTER)) {
      writer.append(quotechar);
    }
    if (!hasSpecialCharacters) {
      writer.append(nextElement);
    }
 else {
      final int length=nextElement.length();
      for (int j=0; j < length; j++) {
        char nextChar=nextElement.charAt(j);
        if (escapechar != NO_ESCAPE_CHARACTER && (nextChar == quotechar || nextChar == escapechar)) {
          writer.append(escapechar).append(nextChar);
        }
 else {
          writer.append(nextChar);
        }
      }
    }
    if ((quoteall || hasSpecialCharacters) && (quotechar != NO_QUOTE_CHARACTER)) {
      writer.append(quotechar);
    }
  }
  writer.append(lineEnd);
}

/** 
 * Parses the primary. First look for a literal (e.g. "text"), then an identifier(e.g. variable) In the next step, call a function, if executing a function, on the literal or the identifier found.
 */
protected void processPrimary(){
  if (lexer.parseString("DISTINCT ") || lexer.parseString("distinct")) {
    Node distinctNode=new Node(NodeType.OPERATOR,"DISTINCT");
    processExpression();
    Node identifierNode=stack.pop();
    distinctNode.appendChildNode(identifierNode);
    stack.push(distinctNode);
    return;
  }
  Node castNode=null;
  if (processCast()) {
    castNode=stack.pop();
  }
  if (lexer.peekString("IF(") || lexer.peekString("if(") || lexer.peekString("IF (")|| lexer.peekString("if (")) {
    processIfElseExpression();
    return;
  }
  if (processCreator()) {
    boolean endOfChain=false;
    while (!endOfChain) {
      if (lexer.parseChar('.')) {
        if (processMethod()) {
          Node invokeNode=stack.pop();
          Node invokedNode=stack.peek();
          invokedNode.appendChildNode(invokeNode);
        }
      }
 else {
        endOfChain=true;
      }
    }
    if (castNode != null) {
      throw new NucleusException("Dont currently support compile of cast of creator expression");
    }
    return;
  }
 else   if (processLiteral()) {
    boolean endOfChain=false;
    while (!endOfChain) {
      if (lexer.parseChar('.')) {
        if (processMethod()) {
          Node invokeNode=stack.pop();
          Node invokedNode=stack.peek();
          invokedNode.appendChildNode(invokeNode);
        }
      }
 else {
        endOfChain=true;
      }
    }
    if (castNode != null) {
      throw new NucleusException("Dont currently support compile of cast of literal expression");
    }
    return;
  }
 else   if (processMethod()) {
    if (castNode != null) {
      throw new NucleusException("Dont currently support compile of cast of static method call");
    }
    return;
  }
 else   if (processArray()) {
    boolean endOfChain=false;
    while (!endOfChain) {
      if (lexer.parseChar('.')) {
        if (processMethod()) {
          Node invokeNode=stack.pop();
          Node invokedNode=stack.peek();
          invokedNode.appendChildNode(invokeNode);
        }
      }
 else {
        endOfChain=true;
      }
    }
    if (castNode != null) {
      throw new NucleusException("Dont currently support compile of cast of array expression");
    }
    return;
  }
  int sizeBeforeBraceProcessing=stack.size();
  boolean braceProcessing=false;
  if (lexer.parseChar('(')) {
    processExpression();
    if (!lexer.parseChar(')')) {
      throw new QueryCompilerSyntaxException("expected ')'",lexer.getIndex(),lexer.getInput());
    }
    if (!lexer.parseChar('.')) {
      return;
    }
    braceProcessing=true;
  }
  if (processMethod()) {
  }
 else   if (processIdentifier()) {
  }
 else {
    throw new QueryCompilerSyntaxException("Method/Identifier expected",lexer.getIndex(),lexer.getInput());
  }
  int size=stack.size();
  if (braceProcessing) {
    size=sizeBeforeBraceProcessing + 1;
  }
  while (lexer.parseChar('.')) {
    if (processMethod()) {
    }
 else     if (processIdentifier()) {
    }
 else {
      throw new QueryCompilerSyntaxException("Identifier expected",lexer.getIndex(),lexer.getInput());
    }
  }
  if (castNode != null) {
    stack.peek().appendChildNode(castNode);
  }
  while (stack.size() > size) {
    Node top=stack.pop();
    Node peek=stack.peek();
    Node lastDescendant=getLastDescendantNodeForNode(peek);
    if (lastDescendant != null) {
      lastDescendant.appendChildNode(top);
    }
 else {
      Node primNode=new Node(NodeType.PRIMARY);
      primNode.appendChildNode(peek);
      primNode.appendChildNode(top);
      stack.pop();
      stack.push(primNode);
    }
  }
}

