/** 
 * Method called when a method of the class is visited.
 * @param access Access for the method
 * @param name Name of the method
 * @param desc Descriptor
 * @param signature Signature
 * @param exceptions Exceptions that this method is declared to throw
 * @return Visitor to visit this (or null if not wanting to visit it)
 */
public MethodVisitor visitMethod(int access,String name,String desc,String signature,String[] exceptions){
  if (name.equals("<init>") && desc != null && desc.equals("()V")) {
    hasDefaultConstructor=true;
  }
  if (name.equals("writeObject") && desc != null && desc.equals("(Ljava/io/ObjectOutputStream;)V")) {
    hasWriteObject=true;
  }
  if (name.equals("<clinit>") && desc != null && desc.equals("()V")) {
    hasStaticInitialisation=true;
  }
  MethodVisitor mv=cv.visitMethod(access,name,desc,signature,exceptions);
  if (mv == null) {
    return null;
  }
  if (name.equals("jdoPreClear") || name.equals("jdoPostLoad")) {
    return mv;
  }
 else   if (name.equals("readObject") && desc != null && (desc.equals("(Ljava/io/ObjectOutputStream;)V") || desc.equals("(Ljava/io/ObjectInputStream;)V"))) {
    return mv;
  }
 else   if (name.equals("clone") && desc != null && (desc.equals("()Ljava/lang/Object;"))) {
    needsClone=false;
    return new EnhancerCloneAdapter(mv,enhancer,cv);
  }
  String propGetterName=ClassUtils.getFieldNameForJavaBeanGetter(name);
  String propSetterName=ClassUtils.getFieldNameForJavaBeanSetter(name);
  if ((access & Opcodes.ACC_BRIDGE) != Opcodes.ACC_BRIDGE) {
    if (propGetterName != null) {
      AbstractMemberMetaData mmd=enhancer.getClassMetaData().getMetaDataForMember(propGetterName);
      if (mmd != null && mmd instanceof PropertyMetaData && mmd.getPersistenceModifier() != FieldPersistenceModifier.NONE) {
        return new EnhancerPropertyGetterAdapter(mv,enhancer,name,desc,mmd,cv);
      }
    }
 else     if (propSetterName != null) {
      AbstractMemberMetaData mmd=enhancer.getClassMetaData().getMetaDataForMember(propSetterName);
      if (mmd != null && mmd instanceof PropertyMetaData && mmd.getPersistenceModifier() != FieldPersistenceModifier.NONE) {
        return new EnhancerPropertySetterAdapter(mv,enhancer,name,desc,mmd,cv);
      }
    }
  }
  return new EnhancerMethodAdapter(mv,enhancer,name,desc);
}

/** 
 * Handle CreateOwnIdentity command. Format of request: Message=CreateOwnIdentity Nickname=name PublishTrustList=true|false            (optional, default is true) PublishIntroductionPuzzles=true|false  (optional, default is true) AutoSubscribe=true|false				(optional, default is false) DisplayImages=true|false				(optional, default is false) RequestURI=...                         (optional) InsertURI=...                          (optional) Format of reply: Message=CreateOwnIdentityReply OwnIdentityCreated=true|false ID=id FreetalkAddress=addr InsertURI=... RequestURI=... ErrorDescription=abc             (set if OwnIdentityCreated=false)
 */
private void handleCreateOwnIdentity(final PluginReplySender replysender,final SimpleFieldSet params) throws PluginNotFoundException {
  try {
    final String nickName=getMandatoryParameter(params,"Nickname");
    WoTIdentity.validateNickname(nickName);
    boolean publishTrustList=params.getBoolean("PublishTrustList",true);
    boolean publishIntroductionPuzzles=params.getBoolean("PublishIntroductionPuzzles",true);
    boolean autoSubscribe=params.getBoolean("AutoSubscribe",false);
    boolean displayImages=params.getBoolean("DisplayImages",false);
    final String requestUriString=params.get("RequestURI");
    final String insertUriString=params.get("InsertURI");
    if ((requestUriString == null || insertUriString == null) && requestUriString != insertUriString) {
      throw new InvalidParameterException("RequestURI and InsertURI must be set together");
    }
    final WoTOwnIdentity id;
    if (requestUriString != null) {
      final FreenetURI requestUri=new FreenetURI(requestUriString);
      final FreenetURI insertUri=new FreenetURI(insertUriString);
      id=(WoTOwnIdentity)mFreetalk.getIdentityManager().createOwnIdentity(nickName,publishTrustList,publishIntroductionPuzzles,autoSubscribe,displayImages,requestUri,insertUri);
    }
 else {
      id=(WoTOwnIdentity)mFreetalk.getIdentityManager().createOwnIdentity(nickName,publishTrustList,publishIntroductionPuzzles,autoSubscribe,displayImages);
    }
    final SimpleFieldSet sfs=new SimpleFieldSet(true);
    sfs.putOverwrite("Message","CreateOwnIdentityReply");
    sfs.putOverwrite("OwnIdentityCreated","true");
    sfs.putOverwrite("ID",id.getID());
    sfs.putOverwrite("FreetalkAddress",id.getFreetalkAddress());
    sfs.putOverwrite("InsertURI",id.getInsertURI().toString());
    sfs.putOverwrite("RequestURI",id.getRequestURI().toString());
    replysender.send(sfs);
