/** 
 * <p>Cancel (and rollback when possible) the currently running query of this  {@link JDBCConnection} instance.</p><p><b>Important note:</b> This function tries canceling the current JDBC statement. This can work only if the JDBC driver and the DBMS both support this operation. If the statement cancellation fails, the flag  {@link #supportsCancel}is set to <code>false</code> so that any subsequent call of this function for this instance of {@link JDBCConnection} does not try any other cancellation attempt. <b>HOWEVER</b> the rollback willstill continue to be performed if the parameter <code>rollback</code> is set to <code>true</code>. </p> <p> In any case, this function sets anyway the flag  {@link #isCancelled()} to <code>true</code> so that aftera DB processing this  {@link DBConnection} can interrupt immediately any potentially long running functions(i.e.  {@link #addUploadedTable(TAPTable,TableIterator)},  {@link #executeQuery(ADQLQuery)} and{@link #setTAPSchema(TAPMetadata)}). When these functions realize this flag is set, they immediately stop by throwing a  {@link DBCancelledException}. </p> <p><i>Note 1: A failure of a rollback is not considered as a not supported cancellation feature by the JDBC driver or the DBMS. So if the cancellation succeeds but a rollback fails, a next call of this function will still try canceling the given statement. In case of a rollback failure, only a WARNING is written in the log file ; no exception is thrown. </i></p> <p><i>Note 2: This function is synchronized on the  {@link #cancelled} flag.Thus, it may block until another synchronized block on this same flag is finished. </i></p>
 * @param rollback	<code>true</code> to cancel the statement AND rollback the current connection transaction,<code>false</code> to just cancel the statement.
 * @see DBConnection#cancel(boolean)
 * @see #cancel(Statement,boolean)
 * @since 2.1
 */
@Override public final void cancel(final boolean rollback){
synchronized (cancelled) {
    cancelled=true;
    boolean effectivelyCancelled=cancel(stmt,rollback);
    if (effectivelyCancelled && logger != null)     logger.logDB(LogLevel.INFO,this,"CANCEL","Query execution successfully stopped!",null);
  }
}
/** 
 * <p>Cancel (and rollback when asked and if possible) the given statement.</p> <p><b>Important note:</b> This function tries canceling the current JDBC statement. This can work only if the JDBC driver and the DBMS both support this operation. If the statement cancellation fails, the flag  {@link #supportsCancel}is set to <code>false</code> so that any subsequent call of this function for this instance of {@link JDBCConnection} does not try any other cancellation attempt. <b>HOWEVER</b> the rollback willstill continue to be performed if the parameter <code>rollback</code> is set to <code>true</code>. </p> <p><i>Note: A failure of a rollback is not considered as a not supported cancellation feature by the JDBC driver or the DBMS. So if the cancellation succeeds but a rollback fails, a next call of this function will still try canceling the given statement. In case of a rollback failure, only a WARNING is written in the log file ; no exception is thrown. </i></p>
 * @param stmt		The statement to cancel. <i>Note: if closed or NULL, no exception will be thrown and only a rollback will be attempted if asked in parameter.</i>
 * @param rollback	<code>true</code> to cancel the statement AND rollback the current connection transaction,<code>false</code> to just cancel the statement.
 * @return	<code>true</code> if the cancellation succeeded (or none was running),<code>false</code> otherwise (and especially if the "cancel" operation is not supported).
 * @since 2.1
 */
protected boolean cancel(final Statement stmt,final boolean rollback){
  try {
    if (supportsCancel && stmt != null && !stmt.isClosed()) {
      stmt.cancel();
      return true;
    }
 else     return false;
  }
 catch (  SQLFeatureNotSupportedException sfnse) {
    supportsCancel=false;
    if (logger != null)     logger.logDB(LogLevel.WARNING,this,"CANCEL","This JDBC driver does not support Statement.cancel(). No further cancel attempt will be performed with this JDBCConnection instance.",sfnse);
    return false;
  }
catch (  SQLException se) {
    if (logger != null)     logger.logDB(LogLevel.ERROR,this,"CANCEL","Abortion of the current query apparently fails! The query may still run on the database server.",se);
    return false;
  }
 finally {
    if (rollback && supportsTransaction)     rollback((stmt != null && stmt == this.stmt));
  }
}

