private String parsebnode(){
  int start=pos;
  pos++;
  if (line.charAt(pos++) != ':')   throw new DukeException("Incorrect start of blank node");
  char ch=line.charAt(pos++);
  while ((ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z') || (ch >= '0' && ch <= '9'))   ch=line.charAt(pos++);
  return line.substring(start,pos - 1);
}

