      mScrollingHeaderByHelper=false;
      return current;
    }
  }
  final int min=mDrawer.getHeaderTopMinimum(), max=mDrawer.getHeaderTopMaximum();
  if (top < min && mDrawer.isTouchingScrollableContent() && mDrawer.isUsingDragHelper()) {
