public static int checkSignUpResponse(HttpResponse response,String email){
  int statusCode=response.getStatusLine().getStatusCode();
  Log.d(TAG,"status: " + statusCode);
  String message=getPLFStream(response);
  if (statusCode == ExoConstants.UNKNOWN) {
    if (response.getLastHeader("Location").getValue().contains("tryagain.jsp"))     return ExoConnectionUtils.SIGNUP_WRONG_DOMAIN;
 else     return ExoConnectionUtils.SIGNUP_ACCOUNT_EXISTS;
  }
 else   if (statusCode == HttpStatus.SC_ACCEPTED || (statusCode == HttpStatus.SC_INTERNAL_SERVER_ERROR && message != null && message.startsWith(SIGNUP_MAX_USERS_MSG + email)))   return ExoConnectionUtils.SIGNUP_MAX_USERS;
  if (statusCode != HttpStatus.SC_OK)   return ExoConnectionUtils.SIGNUP_SERVER_NAV;
  return ExoConnectionUtils.SIGNUP_OK;
}

private void renameBleedingFunctionName(NodeTraversal t,final Node fnName){
  final String name=fnName.getString();
  final String suffix=compiler.getUniqueNameIdSupplier().get();
  Callback cb=new AbstractPostOrderCallback(){
    @Override public void visit(    NodeTraversal t,    Node n,    Node parent){
      if (n.isName() && n.getString().equals(name) && t.getScope().getVar(name).getNode() == fnName) {
        n.setString(name + "$jscomp$scopedAliases$" + suffix);
        compiler.reportChangeToEnclosingScope(n);
      }
    }
  }
;
  (new NodeTraversal(compiler,cb,t.getScopeCreator())).traverseAtScope(t.getScope());
  fnName.setString(name + "$jscomp$scopedAliases$" + suffix);
}

@Override public void subscribe(Subscriber<? super T> child){
  for (; ; ) {
    ReplaySubscriber<T> r=curr.get();
    if (r == null) {
      ReplayBuffer<T> buf;
      try {
        buf=bufferFactory.get();
      }
 catch (      Throwable ex) {
        Exceptions.throwIfFatal(ex);
        EmptySubscription.error(ex,child);
        return;
      }
      ReplaySubscriber<T> u=new ReplaySubscriber<T>(buf);
      if (!curr.compareAndSet(null,u)) {
        continue;
      }
      r=u;
    }
    InnerSubscription<T> inner=new InnerSubscription<T>(r,child);
    child.onSubscribe(inner);
    r.add(inner);
    if (inner.isDisposed()) {
      r.remove(inner);
      return;
    }
    r.manageRequests();
    r.buffer.replay(inner);
    break;
  }
}

