/** 
 * @return true if requests should be accepted from nodes brandishing thisversion string, given an arbitrary lastGoodVersion
 */
public static boolean checkArbitraryGoodVersion(String version,String lastGoodVersion){
  if (version == null) {
    Logger.error(Version.class,"version == null!",new Exception("error"));
    return false;
  }
  if (lastGoodVersion == null) {
    Logger.error(Version.class,"lastGoodVersion == null!",new Exception("error"));
    return false;
  }
  String[] v=Fields.commaList(version);
  String[] lgv=Fields.commaList(lastGoodVersion);
  if ((v == null || v.length < 3) || !goodProtocol(v[2])) {
    return false;
  }
  if ((lgv == null || lgv.length < 3) || !goodProtocol(lgv[2])) {
    return false;
  }
  if (sameArbitraryVersion(v,lgv)) {
    try {
      int build=Integer.parseInt(v[3]);
      int min_build=Integer.parseInt(lgv[3]);
      if (build < min_build) {
        if (logDEBUG)         Logger.debug(Version.class,"Not accepting unstable from version: " + version + "(lastGoodVersion="+ lastGoodVersion+ ')');
        return false;
      }
    }
 catch (    NumberFormatException e) {
      if (logMINOR)       Logger.minor(Version.class,"Not accepting (" + e + ") from "+ version+ " and/or "+ lastGoodVersion);
      return false;
    }
  }
  if (stableVersion(v)) {
    try {
      int build=Integer.parseInt(v[3]);
      if (build < lastGoodStableBuild) {
        if (logDEBUG)         Logger.debug(Version.class,"Not accepting stable from version" + version + "(lastGoodStableBuild="+ lastGoodStableBuild+ ')');
        return false;
      }
    }
 catch (    NumberFormatException e) {
      Logger.minor(Version.class,"Not accepting (" + e + ") from "+ version);
      return false;
    }
  }
  if (logDEBUG)   Logger.minor(Version.class,"Accepting: " + version);
  return true;
}

