private void handleShortcut(Cursor c,int key){
  if (mActivity.isFinishing()) {
    return;
  }
  c.moveToPosition(-1);
  while (c.moveToNext()) {
    long shortcut=c.getLong(mShortcutColumn);
    if (shortcut >= 0 && shortcut < 10 && key == (shortcut + '0')) {
      select(c,c.getPosition());
      break;
    }
  }
}
