@Override protected boolean onIncoming(final IncomingMessage res,boolean shouldKeepAlive) throws Exception {
  AbstractSocket socket=this.socket;
  final ClientRequest req=(ClientRequest)socket.get_httpMessage();
  debug(TAG,"AGENT incoming response!");
  if (req.res != null) {
    socket.destroy(null);
    return false;
  }
  req.res=res;
  if (req.method == "CONNECT") {
    res.setUpgrade(true);
    return true;
  }
  boolean isHeadResponse=req.method == "HEAD";
  debug(TAG,"AGENT isHeadResponse " + isHeadResponse);
  if (res.statusCode() == 100) {
    req.res=null;
    req.emit("continue");
    return true;
  }
  if (req.shouldKeepAlive && !shouldKeepAlive && !req.upgradeOrConnect) {
    req.shouldKeepAlive=false;
  }
  req.res=res;
  res.setReq(req);
  Listener responseOnEnd=new Listener(){
    @Override public void onEvent(    Object data) throws Exception {
      ClientRequest req=res.getReq();
      final AbstractSocket socket=req.socket;
      if (!req.shouldKeepAlive) {
        if (socket.writable()) {
          debug(TAG,"AGENT socket.destroySoon()");
          socket.destroySoon();
        }
        assert (!socket.writable());
      }
 else {
        debug(TAG,"AGENT socket keep-alive");
        socket.removeListener("close",socketCloseListener);
        socket.removeListener("error",socketErrorListener);
        context.nextTick(new nextTickListener(){
          @Override public void onNextTick() throws Exception {
            socket.emit("free");
          }
        }
);
      }
    }
  }
;
  res.on("end",responseOnEnd);
  boolean handled=req.emit("response",res);
  if (!handled)   res._dump();
  return isHeadResponse;
}

