/** 
 * Gets the location that is "~ ~ ~" for a command sender.
 * @param sender a command sender
 * @return the sender's location if the sender is a block or entity, or the default world'scoordinate origin otherwise.
 */
public static Location getLocation(CommandSender sender){
  if (sender instanceof Entity) {
    return ((Entity)sender).getLocation();
  }
 else   if (sender instanceof BlockCommandSender) {
    return ((BlockCommandSender)sender).getBlock().getLocation();
  }
  return new Location(getDefaultWorld(),0,0,0);
}
/** 
 * Parses coordinates that may be absolute or relative.
 * @param sender the command sender
 * @param x the x coordinate specifier
 * @param y the y coordinate specifier
 * @param z the z coordinate specifier
 * @return the coordinates
 */
public static Location getLocation(CommandSender sender,String x,String y,String z){
  Location currentLocation;
  if (x.startsWith("~") || y.startsWith("~") || z.startsWith("~")) {
    currentLocation=getLocation(sender);
  }
 else {
    currentLocation=new Location(getWorld(sender),0,0,0);
  }
  return getLocation(currentLocation,x,y,z);
}
/** 
 * <p>Gets the relative location based on the given axis values (x/y/z) based on tilde notation.</p> <p>For instance, using axis values of ~10 ~ ~15 will return the location with the offset of the given rotation values.
 * @param location the initial location
 * @param relativeX the relative x-axis (if there is no tilde [~], then the literalvalue is used)
 * @param relativeY the relative y-axis (if there is no tilde [~], then the literalvalue is used)
 * @param relativeZ the relative z-axis (if there is no tilde [~], then the literalvalue is used)
 * @return the relative location
 */
public static Location getLocation(Location location,String relativeX,String relativeY,String relativeZ){
  double x;
  double y;
  double z;
  if (relativeX.startsWith("~")) {
    double diff=0;
    if (relativeX.length() > 1) {
      diff=getDouble(relativeX.substring(1),true);
    }
    x=location.getX() + diff;
  }
 else {
    x=getDouble(relativeX,true);
  }
  if (relativeY.startsWith("~")) {
    double diff=0;
    if (relativeY.length() > 1) {
      diff=getDouble(relativeY.substring(1),false);
    }
    y=location.getY() + diff;
  }
 else {
    y=getDouble(relativeY,false);
  }
  if (relativeZ.startsWith("~")) {
    double diff=0;
    if (relativeZ.length() > 1) {
      diff=getDouble(relativeZ.substring(1),true);
    }
    z=location.getZ() + diff;
  }
 else {
    z=getDouble(relativeZ,true);
  }
  return new Location(location.getWorld(),x,y,z);
}

private boolean hasJspRoot(JspReader reader) throws JasperException {
  Mark start=null;
  while ((start=reader.skipUntil("<")) != null) {
    int c=reader.nextChar();
    if (c != '!' && c != '?')     break;
  }
  if (start == null) {
    return false;
  }
  Mark stop=reader.skipUntil(":root");
  if (stop == null) {
    return false;
  }
  String prefix=reader.getText(start,stop).substring(1);
  start=stop;
  stop=reader.skipUntil(">");
  if (stop == null) {
    return false;
  }
  String root=reader.getText(start,stop);
  String xmlnsDecl="xmlns:" + prefix;
  int index=root.indexOf(xmlnsDecl);
  if (index == -1) {
    return false;
  }
  index+=xmlnsDecl.length();
  while (index < root.length() && Character.isWhitespace(root.charAt(index))) {
    index++;
  }
  if (index < root.length() && root.charAt(index) == '=') {
    index++;
    while (index < root.length() && Character.isWhitespace(root.charAt(index))) {
      index++;
    }
    if (index < root.length() && root.charAt(index++) == '"' && root.regionMatches(index,JSP_URI,0,JSP_URI.length())) {
      return true;
    }
  }
  return false;
}

