/** 
 * Apply a fixed delay before emitting elements to the next phase of the Stream. Note this doesn't neccessarily imply a fixed delay between element creation (although it may do). e.g. <pre> {@code FutureStream.of(1,2,3,4) .fixedDelay(1,TimeUnit.hours);}</pre> Will emit 1 on skip, applyHKT 2 after an hour, 3 after 2 hours and so on. However all 4 numbers will be populated in the Stream immediately. <pre> {@code FutureStream.of(1,2,3,4) .withQueueFactories(QueueFactories.boundedQueue(1)) .fixedDelay(1,TimeUnit.hours);}</pre> Will populate each number in the Stream an hour apart.
 * @param time amount of time between emissions
 * @param unit TimeUnit for emissions
 * @return Next Stage of the Stream
 */
@Override default FutureStream<U> fixedDelay(final long time,final TimeUnit unit){
  return fromStream(Streams.fixedDelay(stream(),time,unit));
}

@SuppressWarnings("unchecked") private UriInfo mockURIInfoForEntitySetCount(EdmMapping mapping) throws EdmException {
  UriInfo uriInfo=EasyMock.createMock(UriInfo.class);
  List<NavigationSegment> navSegments=new ArrayList<NavigationSegment>();
  EasyMock.expect(uriInfo.getNavigationSegments()).andStubReturn(navSegments);
  EdmEntityType edmEntityType=EasyMock.createMock(EdmEntityType.class);
  EasyMock.expect(edmEntityType.getMapping()).andStubReturn(mapping);
  EdmEntitySet edmEntitySet=EasyMock.createMock(EdmEntitySet.class);
  EasyMock.expect(edmEntitySet.getEntityType()).andStubReturn(edmEntityType);
  EasyMock.expect(uriInfo.getTargetEntitySet()).andStubReturn(edmEntitySet);
  List<KeyPredicate> keyPreds=EasyMock.createMock(ArrayList.class);
  EasyMock.expect(uriInfo.getKeyPredicates()).andStubReturn(keyPreds);
  OrderByExpression orderbyExpression=mockOrderByExpressions(uriInfo);
  EasyMock.expect(uriInfo.getTop()).andStubReturn(null);
  EasyMock.expect(uriInfo.getSkip()).andStubReturn(null);
  EasyMock.replay(edmEntityType,edmEntitySet,uriInfo,keyPreds,orderbyExpression);
  return uriInfo;
}

