/** 
 * Writes very wide records and gets the latest row every time.. Flushes and compacts the region aggressivly to catch issues.
 * @throws IOException by flush / scan / compaction
 * @throws InterruptedException when joining threads
 */
@Test public void testWritesWhileGetting() throws Exception {
  int testCount=100;
  int numRows=1;
  int numFamilies=10;
  int numQualifiers=100;
  int compactInterval=100;
  byte[][] families=new byte[numFamilies][];
  for (int i=0; i < numFamilies; i++) {
    families[i]=Bytes.toBytes("family" + i);
  }
  byte[][] qualifiers=new byte[numQualifiers][];
  for (int i=0; i < numQualifiers; i++) {
    qualifiers[i]=Bytes.toBytes("qual" + i);
  }
  String method="testWritesWhileGetting";
  conf.setInt("hbase.hstore.compaction.min",1);
  conf.setInt("hbase.hstore.compaction.max",1000);
  this.region=initHRegion(tableName,method,conf,families);
  PutThread putThread=null;
  MultithreadedTestUtil.TestContext ctx=new MultithreadedTestUtil.TestContext(conf);
  try {
    putThread=new PutThread(numRows,families,qualifiers);
    putThread.start();
    putThread.waitForFirstPut();
    ctx.addThread(new RepeatingTestThread(ctx){
      private int flushesSinceCompact=0;
      private final int maxFlushesSinceCompact=20;
      @Override public void doAnAction() throws Exception {
        if (region.flushcache()) {
          ++flushesSinceCompact;
        }
        if (flushesSinceCompact == maxFlushesSinceCompact) {
          region.compactStores(false);
          flushesSinceCompact=0;
        }
      }
    }
);
    ctx.startThreads();
    Get get=new Get(Bytes.toBytes("row0"));
    Result result=null;
    int expectedCount=numFamilies * numQualifiers;
    long prevTimestamp=0L;
    for (int i=0; i < testCount; i++) {
      boolean previousEmpty=result == null || result.isEmpty();
      result=region.get(get);
      if (!result.isEmpty() || !previousEmpty || i > compactInterval) {
        assertEquals("i=" + i,expectedCount,result.size());
        long timestamp=0;
        for (        Cell kv : result.rawCells()) {
          if (CellUtil.matchingFamily(kv,families[0]) && CellUtil.matchingQualifier(kv,qualifiers[0])) {
            timestamp=kv.getTimestamp();
          }
        }
        assertTrue(timestamp >= prevTimestamp);
        prevTimestamp=timestamp;
        Cell previousKV=null;
        for (        Cell kv : result.rawCells()) {
          byte[] thisValue=CellUtil.cloneValue(kv);
          if (previousKV != null) {
            if (Bytes.compareTo(CellUtil.cloneValue(previousKV),thisValue) != 0) {
              LOG.warn("These two KV should have the same value." + " Previous KV:" + previousKV + "(memStoreTS:"+ previousKV.getMvccVersion()+ ")"+ ", New KV: "+ kv+ "(memStoreTS:"+ kv.getMvccVersion()+ ")");
              assertEquals(0,Bytes.compareTo(CellUtil.cloneValue(previousKV),thisValue));
            }
          }
          previousKV=kv;
        }
      }
    }
  }
  finally {
    if (putThread != null)     putThread.done();
    region.flushcache();
    if (putThread != null) {
      putThread.join();
      putThread.checkNoError();
    }
    ctx.stop();
    HRegion.closeHRegion(this.region);
    this.region=null;
  }
}

private UpdateContainer deleteLinks(WorksheetCommandHistoryExecutor histExecutor,Workspace workspace,Worksheet worksheet,Alignment alignment) throws JSONException {
  UpdateContainer uc=new UpdateContainer();
  boolean saveToHistory=!this.isExecutedInBatch();
  for (int i=0; i < initialEdges.length(); i++) {
    JSONObject initialEdge=initialEdges.getJSONObject(i);
    int newEdgeIdx=-1;
    for (int j=0; j < newEdges.length(); j++) {
      JSONObject newEdge=newEdges.getJSONObject(j);
      if (initialEdge.has(LinkJsonKeys.edgeId.name()) && newEdge.has(LinkJsonKeys.edgeId.name()) && initialEdge.getString(LinkJsonKeys.edgeId.name()).equals(newEdge.getString(LinkJsonKeys.edgeId.name()))&& initialEdge.has(LinkJsonKeys.edgeSourceId.name())&& newEdge.has(LinkJsonKeys.edgeSourceId.name())&& initialEdge.getString(LinkJsonKeys.edgeSourceId.name()).equals(newEdge.getString(LinkJsonKeys.edgeSourceId.name()))&& initialEdge.has(LinkJsonKeys.edgeTargetId.name())&& (newEdge.has(LinkJsonKeys.edgeTargetId.name()) && initialEdge.getString(LinkJsonKeys.edgeTargetId.name()).equals(newEdge.getString(LinkJsonKeys.edgeTargetId.name()))))       newEdgeIdx=j;
    }
    if (newEdgeIdx != -1) {
      JSONObject newEdge=newEdges.getJSONObject(newEdgeIdx);
      boolean newEdgeProv=(newEdge.has(LinkJsonKeys.isProvenance.name())) ? newEdge.getBoolean(LinkJsonKeys.isProvenance.name()) : false;
      boolean initialEdgeProv=(initialEdge.has(LinkJsonKeys.isProvenance.name())) ? initialEdge.getBoolean(LinkJsonKeys.isProvenance.name()) : false;
      if (initialEdgeProv && !newEdgeProv) {
        String linkId=LinkIdFactory.getLinkId(newEdge.getString(LinkJsonKeys.edgeId.name()),newEdge.getString(LinkJsonKeys.edgeSourceId.name()),newEdge.getString(LinkJsonKeys.edgeTargetId.name()));
        LabeledLink link=alignment.getLinkById(linkId);
        if (!link.isMainProvenanceLink()) {
          link=getMainProvenanceLink(alignment,link);
          if (link != null) {
            initialEdge.put(LinkJsonKeys.edgeSourceId.name(),link.getSource().getId());
            initialEdge.put(LinkJsonKeys.edgeSourceUri.name(),link.getSource().getUri());
            newEdge.put(LinkJsonKeys.edgeSourceId.name(),link.getSource().getId());
            newEdge.put(LinkJsonKeys.edgeSourceUri.name(),link.getSource().getUri());
          }
        }
      }
    }
    try {
      Command cmd=(new DeleteLinkCommandFactory()).createCommand(worksheetId,alignmentId,initialEdge,model,workspace);
      cmd.setExecutedInBatch(this.isExecutedInBatch());
      uc.append(workspace.getCommandHistory().doCommand(cmd,workspace,saveToHistory && i == initialEdges.length() - 1));
    }
 catch (    Exception e) {
      logger.error("Error removing a link: " + initialEdge.toString(),e);
    }
  }
  return uc;
}

