/** 
 * Creates a matcher that matches all  {@link Text}s that are underlined (that is, they should be drawn with a line below them).
 * @param underlined whether or not the matched Texts should be underlined
 */
public static Matcher<Text> isUnderlined(boolean underlined){
  String descriptionText=(underlined ? "is " : "is not ") + "underlined";
  return typeSafeMatcher(Text.class,descriptionText,textNode -> textNode.getClass().getSimpleName() + (textNode.isUnderline() ? " with " : " without ") + "underline",textNode -> textNode.isUnderline() == underlined);
