/** 
 * Processes calls containing spreads. <p>Examples: <pre><code> f(...arr) => f.apply(null, $jscomp.arrayFromIterable(arr)) f(a, ...arr) => f.apply(null, [a].concat($jscomp.arrayFromIterable(arr))) f(...arr, b) => f.apply(null, [].concat($jscomp.arrayFromIterable(arr), [b])) </code></pre>
 */
private void visitCallContainingSpread(Node spreadParent){
  checkArgument(spreadParent.isCall());
  Node callee=spreadParent.getFirstChild();
  boolean calleeMayHaveSideEffects=compiler.getAstAnalyzer().mayHaveSideEffects(callee);
  spreadParent.removeChild(callee);
  final Node joinedGroups;
  if (spreadParent.hasOneChild() && isSpreadOfArguments(spreadParent.getOnlyChild())) {
    joinedGroups=spreadParent.removeFirstChild().removeFirstChild();
  }
 else {
    List<Node> groups=extractSpreadGroups(spreadParent);
    checkState(!groups.isEmpty());
    if (groups.size() == 1) {
      joinedGroups=groups.remove(0);
    }
 else {
      Node baseArrayLit=groups.get(0).isArrayLit() ? groups.remove(0) : arrayLitWithJSType();
      Node concat=IR.getprop(baseArrayLit,IR.string("concat")).setJSType(concatFnType);
      joinedGroups=IR.call(concat,groups.toArray(new Node[0])).setJSType(arrayType);
    }
    joinedGroups.setJSType(arrayType);
  }
  boolean isFreeCall=spreadParent.getBooleanProp(Node.FREE_CALL);
  final Node callToApply;
  if (calleeMayHaveSideEffects && callee.isGetProp() && !isFreeCall) {
    JSType receiverType=callee.getFirstChild().getJSType();
    Node freshVar=IR.name(FRESH_SPREAD_VAR + compiler.getUniqueNameIdSupplier().get()).setJSType(receiverType);
    Node freshVarDeclaration=IR.var(freshVar.cloneTree());
    Node statementContainingSpread=NodeUtil.getEnclosingStatement(spreadParent);
    freshVarDeclaration.useSourceInfoIfMissingFromForTree(statementContainingSpread);
    statementContainingSpread.getParent().addChildBefore(freshVarDeclaration,statementContainingSpread);
    callee.addChildToFront(IR.assign(freshVar.cloneTree(),callee.removeFirstChild()).setJSType(receiverType));
    callToApply=IR.call(getpropInferringJSType(callee,"apply"),freshVar.cloneTree(),joinedGroups);
  }
 else {
    Node context=(callee.isGetProp() || callee.isGetElem()) && !isFreeCall ? callee.getFirstChild().cloneTree() : nullWithJSType();
    callToApply=IR.call(getpropInferringJSType(callee,"apply"),context,joinedGroups);
  }
  callToApply.setJSType(spreadParent.getJSType());
  callToApply.useSourceInfoIfMissingFromForTree(spreadParent);
  spreadParent.replaceWith(callToApply);
  compiler.reportChangeToEnclosingScope(callToApply);
}

private void checkForUnusedLocalVar(Var v,Reference unusedAssignment){
  if (!v.isLocal()) {
    return;
  }
  JSDocInfo jsDoc=NodeUtil.getBestJSDocInfo(unusedAssignment.getNode());
  if (jsDoc != null && jsDoc.hasTypedefType()) {
    return;
  }
  boolean inGoogScope=false;
  Scope s=v.getScope();
  if (s.isFunctionBlockScope()) {
    Node function=s.getRootNode().getParent();
    Node callee=function.getPrevious();
    inGoogScope=callee != null && callee.matchesQualifiedName("goog.scope");
  }
  if (inGoogScope) {
    return;
  }
  if (s.isModuleScope()) {
    Node statement=NodeUtil.getEnclosingStatement(v.getNode());
    if (NodeUtil.isNameDeclaration(statement)) {
      Node lhs=statement.getFirstChild();
      Node rhs=lhs.getFirstChild();
      if (rhs != null && (NodeUtil.isCallTo(rhs,"goog.forwardDeclare") || NodeUtil.isCallTo(rhs,"goog.requireType") || NodeUtil.isCallTo(rhs,"goog.require")|| rhs.isQualifiedName())) {
        return;
      }
    }
  }
  compiler.report(JSError.make(unusedAssignment.getNode(),UNUSED_LOCAL_ASSIGNMENT,v.name));
}

