/** 
 * Draw bar from the specified point to the y axis. If the specified point is below the y axis or outside the x range, do nothing.  If the <i>clip</i> argument is true, then do not draw above the y range. Note that paintComponent() should be called before calling this method so that _xscale and _yscale are properly set. This method should be called only from the event dispatch thread. It is not synchronized, so its caller should be.
 * @param graphics The graphics context.
 * @param dataset The index of the dataset.
 * @param xpos The x position.
 * @param ypos The y position.
 * @param clip If true, then do not draw outside the range.
 */
protected void _drawBar(Graphics graphics,int dataset,long xpos,long ypos,boolean clip){
  if (clip) {
    if (ypos < _uly) {
      ypos=_uly;
    }
    if (ypos > _lry) {
      ypos=_lry;
    }
  }
  if ((ypos <= _lry) && (xpos <= _lrx) && (xpos >= _ulx)) {
    int barlx=(int)(xpos - ((_barWidth * _xscale) / 2) + (dataset * _barOffset * _xscale));
    int barrx=(int)(barlx + (_barWidth * _xscale));
    if (barlx < _ulx) {
      barlx=_ulx;
    }
    if (barrx > _lrx) {
      barrx=_lrx;
    }
    if (barlx >= barrx) {
      barrx=barlx + 1;
    }
    long zeroypos=_lry - (long)((0 - _yMin) * _yscale);
    if (_lry < zeroypos) {
      zeroypos=_lry;
    }
    if (_uly > zeroypos) {
      zeroypos=_uly;
    }
    if ((_yMin >= 0) || (ypos <= zeroypos)) {
      graphics.fillRect(barlx,(int)ypos,barrx - barlx,(int)(zeroypos - ypos));
    }
 else {
      graphics.fillRect(barlx,(int)zeroypos,barrx - barlx,(int)(ypos - zeroypos));
    }
  }
}

