@SuppressWarnings("unchecked") private <T>Response<T> deserializeSingleResponse(Request request,RawResponse response,Class<T> deserializationType){
  final ResponseType responseType=response.getResponseType();
  Response<T> r;
  if (Payload.class == deserializationType) {
    r=(Response<T>)new ResponseImpl<Payload>(response.getStatus(),response.getHeaders(),responseType,response.getPayload());
  }
 else   if (Response.class == deserializationType || RawResponse.class == deserializationType || SerializedResponse.class == deserializationType) {
    r=(Response<T>)new ResponseImpl<Response>(response.getStatus(),response.getHeaders(),responseType,response);
  }
 else   if (Headers.class == deserializationType) {
    r=(Response<T>)new ResponseImpl<Headers>(response.getStatus(),response.getHeaders(),responseType,response.getHeaders());
  }
 else   if (responseType == ResponseType.DEFAULT || responseType == ResponseType.TEXT) {
    r=serializationEngine.deserializeResponse(request,response,deserializationType);
  }
 else {
    logger.log(Level.SEVERE,"Could not process response of type '" + responseType + "' to class '"+ deserializationType.getName()+ "'. A null payload will be returned.");
    r=new ResponseImpl<T>(response.getStatus(),response.getHeaders(),responseType,null);
  }
  return r;
}

