/** 
 * If the given correspondence implementation is "simple enough," returns one or more possible replacements for its definition and instantiation sites.
 */
private static ImmutableList<CorrespondenceCode> computePossibleReplacements(ClassTree classTree,VisitorState state){
  ImmutableSetMultimap<MemberType,Tree> members=classTree.getMembers().stream().collect(toImmutableSetMultimap(m -> MemberType.from(m,state),m -> m));
  if (members.containsKey(MemberType.OTHER) || members.get(CONSTRUCTOR).size() != 1 || members.get(COMPARE_METHOD).size() != 1 || members.get(TO_STRING_METHOD).size() != 1) {
    return ImmutableList.of();
  }
  MethodTree constructor=(MethodTree)getOnlyElement(members.get(CONSTRUCTOR));
  MethodTree compareMethod=(MethodTree)getOnlyElement(members.get(COMPARE_METHOD));
  MethodTree toStringMethod=(MethodTree)getOnlyElement(members.get(TO_STRING_METHOD));
  if (!constructorCallsOnlySuper(constructor)) {
    return ImmutableList.of();
  }
  ImmutableList<BinaryPredicateCode> binaryPredicates=makeBinaryPredicates(classTree,compareMethod,state);
  ExpressionTree toStringReturns=returnExpression(toStringMethod);
  if (toStringReturns == null) {
    return ImmutableList.of();
  }
  String description=toStringReturns.getKind() == NULL_LITERAL ? "\"corresponds to\"" : state.getSourceForNode(toStringReturns);
  return binaryPredicates.stream().map(p -> CorrespondenceCode.create(p,description)).collect(toImmutableList());
}

