/** 
 * Finds the set of common editors for a given set of <var>articles</var> between  {@link #getEarliestDateTime()} and {@link #getLatestDateTime()}. Includes deleted edits if  {@link #isUsingAdminPrivileges()} is {@code true} and ignores minor edits if {@link #isIgnoringMinorEdits()}is  {@code true}.
 * @param articles a list of at least two unique pages to analyze for common editors
 * @param noadmin exclude admins from the analysis
 * @param nobot exclude flagged bots from the analysis
 * @param noanon exclude IPs from the analysis
 * @return a map with user &#8594; list of revisions made. If the totalnumber of pages does not exceed one after applying all exclusions and  removing revisions with deleted/suppressed usernames and pages with no (deleted) history or there is no intersection, return an empty map.
 * @throws IOException if a network error occurs
 * @throws IllegalArgumentException if {@code articles.length < 2} afterduplicates (as in  {@code String.equals}) and Special/Media pages are removed
 */
public Map<String,List<Wiki.Revision>> intersectArticles(Iterable<String> articles,boolean noadmin,boolean nobot,boolean noanon) throws IOException {
  Wiki.RequestHelper rh=wiki.new RequestHelper().withinDateRange(earliestdate,latestdate);
  Set<String> pageset=new HashSet<>();
  for (  String article : articles)   if (wiki.namespace(article) >= 0)   pageset.add(article);
  if (pageset.size() < 2)   throw new IllegalArgumentException("At least two articles are needed to derive a meaningful intersection.");
  Stream<Wiki.Revision> revstream=pageset.stream().flatMap(article -> {
    Stream<Wiki.Revision> str=Stream.empty();
    try {
      str=wiki.getPageHistory(article,rh).stream();
      if (adminmode)       str=Stream.concat(str,wiki.getDeletedHistory(article,rh).stream());
    }
 catch (    IOException|SecurityException ignored) {
    }
    return str;
  }
).filter(rev -> rev.getUser() != null);
  if (nominor)   revstream=revstream.filter(rev -> !rev.isMinor());
  if (noreverts)   revstream=Revisions.removeReverts(revstream.collect(Collectors.toList())).stream();
  Map<String,List<Wiki.Revision>> results=revstream.collect(Collectors.groupingBy(Wiki.Revision::getUser));
  Iterator<Map.Entry<String,List<Wiki.Revision>>> iter=results.entrySet().iterator();
  while (iter.hasNext()) {
    Map.Entry<String,List<Wiki.Revision>> item=iter.next();
    List<Wiki.Revision> list=item.getValue();
    if (list.size() < 2) {
      iter.remove();
      continue;
    }
    Set<String> allpages=list.stream().map(Wiki.Revision::getTitle).collect(Collectors.toCollection(HashSet::new));
    if (allpages.size() < 2)     iter.remove();
  }
  if (results.isEmpty())   return results;
  Set<String> keyset=results.keySet();
  if (noadmin || nobot || noanon) {
    List<String> usernames=new ArrayList<>(keyset);
    List<Wiki.User> userinfo=wiki.getUsers(usernames);
    for (int i=0; i < userinfo.size(); i++) {
      Wiki.User user=userinfo.get(i);
      if (user == null) {
        if (noanon)         keyset.remove(usernames.get(i));
        continue;
      }
      for (      String group : user.getGroups()) {
        if (group.equals("sysop") && noadmin) {
          keyset.remove(usernames.get(i));
          continue;
        }
        if (group.equals("bot") && nobot) {
          keyset.remove(usernames.get(i));
          continue;
        }
      }
    }
  }
  return results;
}

