/** 
 * Prunes counts down. Returns the pruned counts (i.e. with some keys removed, sorted by count, and total unchanged) or null if the entry should not appear in the database at all. The resulting hashmap is in decreasing order by size.
 * @param allCounts All counts.
 * @return
 */
@Override public PrunedCounts<K> prune(final Map<K,Integer> allCounts){
  List<K> keys=new ArrayList<K>(allCounts.keySet());
  Collections.sort(keys,new Comparator<K>(){
    @Override public int compare(    K key1,    K key2){
      return -1 * (allCounts.get(key1) - allCounts.get(key2));
    }
  }
);
  int sum=0;
  for (  Integer c : allCounts.values()) {
    sum+=c;
  }
  PrunedCounts<K> pruned=new PrunedCounts<K>(sum);
  for (  K key : keys) {
    int c=allCounts.get(key);
    if (pruned.size() >= maxRank || c < minCount || 1.0 * c / sum < minFrac)     break;
    pruned.put(key,c);
  }
  if (pruned.isEmpty()) {
    return null;
  }
 else {
    return pruned;
  }
}

