    Assert.assertEquals(ImmutableSet.of(new Relation(datasetInstance2,program2,AccessType.WRITE,runId2),new Relation(datasetInstance2,program2,AccessType.WRITE,runId3),new Relation(datasetInstance2,program3,AccessType.READ_WRITE,runId4)),lineageTable.getRelations(datasetInstance2,0,100000,x -> true));
    Assert.assertEquals(ImmutableSet.of(new Relation(datasetInstance2,program2,AccessType.WRITE,runId2),new Relation(datasetInstance2,program2,AccessType.WRITE,runId3)),lineageTable.getRelations(program2,0,100000,x -> true));
    Assert.assertEquals(ImmutableSet.of(new Relation(datasetInstance2,program2,AccessType.WRITE,runId2),new Relation(datasetInstance2,program2,AccessType.WRITE,runId3)),lineageTable.getRelations(datasetInstance2,0,35000,x -> true));
    Assert.assertEquals(toSet(program1,datasetInstance1),lineageTable.getEntitiesForRun(run11));
    Assert.assertEquals(ImmutableList.of(run11Data1AccessTime),lineageTable.getAccessTimesForRun(run11));
  }
);
