/** 
 * Returns whether a given  {@link StructureBuilder} can place this dungeon in its chosenlocation.
 * @param builder a StructureBuilder for this and for the world and {@link BlockStateDelegate}that would be used to generate this
 * @return true if this dungeon can be placed; false otherwise
 */
public boolean canPlace(StructureBuilder builder){
  if (boundingBox.getMin().getBlockY() < 1) {
    return false;
  }
  int i=0;
  for (int x=0; x < sizeX; x++) {
    for (int z=0; z < sizeZ; z++) {
      for (int y=0; y < HEIGHT; y++) {
        Material type=builder.getBlockState(new Vector(x,y,z)).getType();
        if ((y == 0 || y == HEIGHT - 1) && !type.isSolid()) {
          return false;
        }
        if ((x == 0 || x == sizeX - 1 || z == 0 || z == sizeZ - 1) && y == 1 && type == Material.AIR && builder.getBlockState(new Vector(x,y + 1,z)).getType() == Material.AIR) {
          i++;
          if (i < 0 || i > 5) {
            return false;
          }
        }
      }
    }
  }
  return true;
}

