/** 
 * Add a tree node at the specified index relative to the specified index colors. The inserted nodes' color, value and size are specified. <p><strong>Note that nodes with <code>null</code> values will never be merged together to allow those nodes to be assigned other values later.
 * @param size the size of the node to insert.
 * @param index the location into this tree to insert at
 * @param indexColors the colors that index is relative to. This should beall colors in the tree ORed together for the entire tree.
 * @param value the node value. If non-<code>null</code>, the node may becombined with other nodes of the same color and value. <code>null</code> valued nodes will never be combined with each other.
 * @return the element the specified value was inserted into. This is non-nullunless the size parameter is 0, in which case the result is always <code>null</code>.
 */
public Element<T0> add(int index,byte indexColors,byte color,T0 value,int size){
  assert (index >= 0);
  assert (index <= size(indexColors));
  assert (size >= 0);
  if (this.root == null) {
    if (index != 0)     throw new IndexOutOfBoundsException();
    this.root=new FourColorNode<T0>(color,size,value,null);
    assert (valid());
    return this.root;
  }
 else {
    FourColorNode<T0> inserted=insertIntoSubtree(root,index,indexColors,color,value,size);
    assert (valid());
    return inserted;
  }
}

