  long time=this.time;
  long c=count;
  boolean unbounded=c == Long.MAX_VALUE;
  while (!q.isEmpty()) {
    long ts=(Long)q.peek();
    if (ts < now - time || (!unbounded && (q.size() >> 1) > c)) {
      q.poll();
      q.poll();
    }
 else {
      break;
    }
  }
}

