public static byte[] decode(byte[] source,int off,int len) throws Base64DecoderException {
  return decode(source,off,len,DECODABET);
}
/** 
 * Decodes Base64 content using the supplied decodabet and returns the decoded byte array.
 * @param source    the Base64 encoded data
 * @param off       the offset of where to begin decoding
 * @param len       the length of characters to decode
 * @param decodabet the decodabet for decoding Base64 content
 * @return decoded data
 */
public static byte[] decode(byte[] source,int off,int len,byte[] decodabet) throws Base64DecoderException {
  int len34=len * 3 / 4;
  byte[] outBuff=new byte[2 + len34];
  int outBuffPosn=0;
  byte[] b4=new byte[4];
  int b4Posn=0;
  int i=0;
  byte sbiCrop=0;
  byte sbiDecode=0;
  for (i=0; i < len; i++) {
    sbiCrop=(byte)(source[i + off] & 0x7f);
    sbiDecode=decodabet[sbiCrop];
    if (sbiDecode >= WHITE_SPACE_ENC) {
      if (sbiDecode >= EQUALS_SIGN_ENC) {
        if (sbiCrop == EQUALS_SIGN) {
          int bytesLeft=len - i;
          byte lastByte=(byte)(source[len - 1 + off] & 0x7f);
          if (b4Posn == 0 || b4Posn == 1) {
            throw new Base64DecoderException("invalid padding byte '=' at byte offset " + i);
          }
 else           if ((b4Posn == 3 && bytesLeft > 2) || (b4Posn == 4 && bytesLeft > 1)) {
            throw new Base64DecoderException("padding byte '=' falsely signals end of encoded value " + "at offset " + i);
          }
 else           if (lastByte != EQUALS_SIGN && lastByte != NEW_LINE) {
            throw new Base64DecoderException("encoded value has invalid trailing byte");
          }
          break;
        }
        b4[b4Posn++]=sbiCrop;
        if (b4Posn == 4) {
          outBuffPosn+=decode4to3(b4,0,outBuff,outBuffPosn,decodabet);
          b4Posn=0;
        }
      }
    }
 else {
      throw new Base64DecoderException("Bad Base64 input character at " + i + ": "+ source[i + off]+ "(decimal)");
    }
  }
  if (b4Posn != 0) {
    if (b4Posn == 1) {
      throw new Base64DecoderException("single trailing character at offset " + (len - 1));
    }
    b4[b4Posn++]=EQUALS_SIGN;
    outBuffPosn+=decode4to3(b4,0,outBuff,outBuffPosn,decodabet);
  }
  byte[] out=new byte[outBuffPosn];
  System.arraycopy(outBuff,0,out,0,outBuffPosn);
  return out;
}

private void setupDatatype(Identifier datatype){
  if (datatype.equals(XACML3.ID_DATATYPE_INTEGER) || datatype.equals(XACML3.ID_DATATYPE_DOUBLE)) {
    ((XacmlAdminUI)UI.getCurrent()).getConstraintTypes().removeAllContainerFilters();
    this.constraintTypes.setEnabled(true);
    this.constraintValues.resetDatatype(datatype);
    return;
  }
  if (datatype.equals(XACML3.ID_DATATYPE_STRING)) {
    ((XacmlAdminUI)UI.getCurrent()).getConstraintTypes().addContainerFilter(new Not(new Compare.Equal("constraintType",ConstraintType.RANGE_TYPE)));
    if (this.attribute.getConstraintType() != null && this.attribute.getConstraintType().getConstraintType() != null && this.attribute.getConstraintType().getConstraintType().equals(ConstraintType.RANGE_TYPE)) {
      this.attribute.setConstraintType(null);
    }
    this.constraintValues.resetDatatype(datatype);
    return;
  }
  this.attribute.setConstraintType(null);
  this.constraintTypes.select(null);
  this.constraintTypes.setEnabled(false);
}

