/** 
 * Creates the ChannelType of the Homie property.
 * @param attributes Attributes of the property.
 * @param channelState ChannelState of the property.
 * @return Returns the ChannelType to be used to build the Channel.
 */
private ChannelType createChannelType(PropertyAttributes attributes,ChannelState channelState){
  if (attributes.retained) {
    return ChannelTypeBuilder.state(channelTypeUID,attributes.name,channelState.getItemType()).withConfigDescriptionURI(URI.create(MqttBindingConstants.CONFIG_HOMIE_CHANNEL)).withStateDescription(channelState.getCache().createStateDescription(attributes.unit,!attributes.settable)).build();
  }
 else {
    if (attributes.datatype.equals(DataTypeEnum.enum_)) {
      if (attributes.format.contains("PRESSED") && attributes.format.contains("RELEASED")) {
        return DefaultSystemChannelTypeProvider.SYSTEM_RAWBUTTON;
      }
 else       if (attributes.format.contains("SHORT_PRESSED") && attributes.format.contains("LONG_PRESSED") && attributes.format.contains("DOUBLE_PRESSED")) {
        return DefaultSystemChannelTypeProvider.SYSTEM_BUTTON;
      }
 else       if (attributes.format.contains("DIR1_PRESSED") && attributes.format.contains("DIR1_RELEASED") && attributes.format.contains("DIR2_PRESSED")&& attributes.format.contains("DIR2_RELEASED")) {
        return DefaultSystemChannelTypeProvider.SYSTEM_RAWROCKER;
      }
    }
    return ChannelTypeBuilder.trigger(channelTypeUID,attributes.name).withConfigDescriptionURI(URI.create(MqttBindingConstants.CONFIG_HOMIE_CHANNEL)).build();
  }
}

