@SuppressWarnings("checkstyle:npathcomplexity") private void executeRun(){
  if (test.isStopRequested()) {
    log(format("Skipping %s, test stopped.",RUN));
    return;
  }
  test.setTestPhase(RUN);
  Map<WorkerData,Future> futures=startRun();
  long startMs=currentTimeMillis();
  long durationSeconds=testSuite.getDurationSeconds();
  long durationMs;
  long timeoutMs;
  if (durationSeconds == 0) {
    log("Test will run until it stops");
    timeoutMs=Long.MAX_VALUE;
    durationMs=Long.MAX_VALUE;
  }
 else {
    durationMs=SECONDS.toMillis(durationSeconds);
    log(format("Test will run for %s",secondsToHuman(durationSeconds)));
    timeoutMs=startMs + durationMs;
  }
  long nextSleepUntilMs=startMs;
  int iteration=0;
  for (; ; ) {
    nextSleepUntilMs+=SECONDS.toMillis(1);
    sleepUntilMs(nextSleepUntilMs);
    if (hasFailure()) {
      log("Critical failure detected, aborting RUN phase");
      break;
    }
    long nowMs=currentTimeMillis();
    if (nowMs > timeoutMs || isAllDone(futures) || test.isStopRequested()) {
      log("Test finished run");
      break;
    }
    iteration++;
    if (iteration % logRunPhaseIntervalSeconds == 0) {
      logProgress(nowMs - startMs,durationMs);
    }
  }
  stopRun();
  waitForPhaseCompletion(RUN,futures);
  logFinalPerformanceInfo(startMs);
  waitForGlobalTestPhaseCompletion(RUN);
}

/** 
 * Move the captured settling view by the appropriate amount for the current time. If <code>continueSettling</code> returns true, the caller should call it again on the next frame to continue.
 * @param deferCallbacks true if state callbacks should be deferred via posted message.Set this to true if you are calling this method from {@link android.view.View#computeScroll()} or similar methodsinvoked as part of layout or drawing.
 * @return true if settle is still in progress
 */
public boolean continueSettling(boolean deferCallbacks){
  if (mDragState == STATE_SETTLING) {
    boolean keepGoing=mScroller.computeScrollOffset();
    final int x=mScroller.getCurrX();
    final int y=mScroller.getCurrY();
    final int dx=x - mCapturedView.getLeft();
    final int dy=y - mCapturedView.getTop();
    if (dx != 0) {
      mCapturedView.offsetLeftAndRight(dx);
    }
    if (dy != 0) {
      mCapturedView.offsetTopAndBottom(dy);
    }
    if (dx != 0 || dy != 0) {
      mCallback.onViewPositionChanged(mCapturedView,x,y,dx,dy);
    }
    if (keepGoing && x == mScroller.getFinalX() && y == mScroller.getFinalY()) {
      mScroller.abortAnimation();
      keepGoing=mScroller.isFinished();
    }
    if (!keepGoing) {
      if (deferCallbacks) {
        mParentView.post(mSetIdleRunnable);
      }
 else {
        setDragState(STATE_IDLE);
      }
    }
  }
  return mDragState == STATE_SETTLING;
}

