@Override public void exceptionCaught(IoSession session,Throwable cause) throws Exception {
  Log.warn("Closing connection due to exception in session: " + session,cause);
  try {
    final StreamError error;
    if (cause != null && (cause instanceof XMLNotWellFormedException || (cause.getCause() != null && cause.getCause() instanceof XMLNotWellFormedException))) {
      error=new StreamError(StreamError.Condition.not_well_formed);
    }
 else {
      error=new StreamError(StreamError.Condition.internal_server_error);
    }
    final Connection connection=(Connection)session.getAttribute(CONNECTION);
    if (JiveGlobals.getBooleanProperty("xmpp.skip-error-delivery-on-write-error.disable",false) || !(cause instanceof WriteException)) {
      connection.deliverRawText(error.toXML());
    }
  }
  finally {
    final Connection connection=(Connection)session.getAttribute(CONNECTION);
    if (connection != null) {
      connection.close();
    }
  }
}

/** 
 * Inits MIDlet suite runtime environment and start a MIDlet suite with it
 */
protected void runMIDletSuite(){
  init();
  try {
    createSuiteEnvironment();
    if (foregroundController == null || displayContainer == null || midletStateHandler == null) {
      throw new RuntimeException("Suite environment not complete.");
    }
    midletSuite=createMIDletSuite();
    if (midletSuite == null) {
      reportError(Constants.MIDLET_SUITE_NOT_FOUND);
      return;
    }
    initSuiteEnvironment();
    setSuiteProperties();
    if (Logging.REPORT_LEVEL <= Logging.WARNING) {
      Logging.report(Logging.WARNING,LogChannels.LC_CORE,"MIDlet suite task starting a suite");
    }
    startSuite();
    checkForShutdown();
    if (Logging.REPORT_LEVEL <= Logging.WARNING) {
      Logging.report(Logging.INFORMATION,LogChannels.LC_CORE,"MIDlet suite loader exiting");
    }
  }
 catch (  Throwable t) {
    handleException(t);
  }
 finally {
    closeSuite();
    done();
    exitLoader();
  }
}

public Map<String,Object> serialize(){
  final Map<String,Object> ctx=newMap();
  if (this.get("@base") != null && !this.get("@base").equals(options.getBase())) {
    ctx.put("@base",this.get("@base"));
  }
  if (this.get("@language") != null) {
    ctx.put("@language",this.get("@language"));
  }
  if (this.get("@vocab") != null) {
    ctx.put("@vocab",this.get("@vocab"));
  }
  for (  final Map.Entry<String,Object> stringObjectEntry : termDefinitions.entrySet()) {
    final Map<String,Object> definition=(Map<String,Object>)stringObjectEntry.getValue();
    if (definition.get("@language") == null && definition.get("@container") == null && definition.get("@type") == null && (definition.get("@reverse") == null || Boolean.FALSE.equals(definition.get("@reverse")))) {
      final String cid=this.compactIri((String)definition.get("@id"));
      ctx.put(stringObjectEntry.getKey(),stringObjectEntry.getKey().equals(cid) ? definition.get("@id") : cid);
    }
 else {
      final Map<String,Object> defn=newMap();
      final String cid=this.compactIri((String)definition.get("@id"));
      final Boolean reverseProperty=Boolean.TRUE.equals(definition.get("@reverse"));
      if (!(stringObjectEntry.getKey().equals(cid) && !reverseProperty)) {
        defn.put(reverseProperty ? "@reverse" : "@id",cid);
      }
      final String typeMapping=(String)definition.get("@type");
      if (typeMapping != null) {
        defn.put("@type",JsonLdUtils.isKeyword(typeMapping) ? typeMapping : compactIri(typeMapping,true));
      }
      if (definition.get("@container") != null) {
        defn.put("@container",definition.get("@container"));
      }
      final Object lang=definition.get("@language");
      if (definition.get("@language") != null) {
        defn.put("@language",Boolean.FALSE.equals(lang) ? null : lang);
      }
      ctx.put(stringObjectEntry.getKey(),defn);
    }
  }
  final Map<String,Object> rval=newMap();
  if (!(ctx == null || ctx.isEmpty())) {
    rval.put("@context",ctx);
  }
  return rval;
}

