  if (random.nextInt(odd) != 0) {
    return;
  }
  final World world=chunk.getWorld();
  final int amount=getAmount(random);
  for (byte count=0; count < amount; count++) {
    final int x=chunk.getBlockX(random);
    final int y=random.nextInt(NetherGenerator.HEIGHT);
    final int z=chunk.getBlockZ(random);
    final Mushroom mushroom=random.nextInt(4) == 0 ? VanillaMaterials.RED_MUSHROOM : VanillaMaterials.BROWN_MUSHROOM;
    for (byte size=6; size > 0; size--) {
      final int xx=x - 7 + random.nextInt(15);
      final int zz=z - 7 + random.nextInt(15);
      final int yy=getHighestWorkableBlock(world,xx,y,zz);
      if (yy != -1 && world.getBlockMaterial(xx,yy,zz) == VanillaMaterials.AIR && mushroom.isValidPosition(world.getBlock(xx,yy,zz),BlockFace.BOTTOM,false)) {
        world.setBlockMaterial(xx,yy,zz,mushroom,(short)0,null);
      }
    }
  }
}

private void addEventListeners(){
  instanceStatusEventReceiver.addEventListener(new InstanceStartedEventListener(){
    @Override protected void onEvent(    Event event){
      InstanceStartedEvent instanceStartedEvent=(InstanceStartedEvent)event;
      if (log.isInfoEnabled()) {
        log.info(String.format("Instance started event received: [application-id] %s [cartridge-type] %s " + "[member-id] %s",instanceStartedEvent.getApplicationId(),instanceStartedEvent.getServiceName(),instanceStartedEvent.getMemberId()));
      }
      try {
        String applicationId=instanceStartedEvent.getApplicationId();
        String serviceName=instanceStartedEvent.getServiceName();
        String clusterId=instanceStartedEvent.getClusterId();
        if (StringUtils.isBlank(applicationId)) {
          throw new RuntimeException("Application id not found in instance started event: " + instanceStartedEvent);
        }
        if (StringUtils.isBlank(serviceName)) {
          throw new RuntimeException("Service name not found in instance started event: " + instanceStartedEvent);
        }
        if (StringUtils.isBlank(clusterId)) {
          throw new RuntimeException("Cluster id not found in instance started event: " + instanceStartedEvent);
        }
        ApplicationSignUp[] applicationSignUps=signUpManager.getApplicationSignUps(applicationId);
        if ((applicationSignUps == null) || (applicationSignUps.length == 0) || ((applicationSignUps.length == 1) && (applicationSignUps[0] == null))) {
          log.warn(String.format("Application signups not found for application, artifact updated event" + "not sent: [application-id] %s [cartridge-type] %s",applicationId,serviceName));
          return;
        }
        for (        ApplicationSignUp applicationSignUp : applicationSignUps) {
          artifactDistributionCoordinator.notifyArtifactUpdatedEventForSignUp(applicationSignUp.getApplicationId(),applicationSignUp.getTenantId(),clusterId);
        }
      }
 catch (      Exception e) {
        String message="Could not send artifact updated event";
        log.error(message,e);
      }
    }
  }
);
}

