public static void exportSemanticModelsToGraphviz(Map<String,SemanticModel> models,String label,String filename,GraphVizLabelType nodeLabelType,GraphVizLabelType linkLabelType,boolean showNodeMetaData,boolean showLinkMetaData) throws IOException {
  org.kohsuke.graphviz.Graph graphViz=new org.kohsuke.graphviz.Graph();
  graphViz.attr("fontcolor","blue");
  graphViz.attr("remincross","true");
  graphViz.attr("label",label == null ? "" : label);
  org.kohsuke.graphviz.Graph cluster=null;
  int counter=0;
  if (models != null) {
    for (    Entry<String,SemanticModel> entry : models.entrySet()) {
      if (entry.getKey() == "1-correct model") {
        cluster=GraphVizUtil.convertToGraphviz(GraphUtil.asDefaultGraph(entry.getValue().getGraph()),entry.getValue().getMappingToSourceColumns(),false,nodeLabelType,linkLabelType,false,false);
      }
 else {
        cluster=GraphVizUtil.convertToGraphviz(GraphUtil.asDefaultGraph(entry.getValue().getGraph()),entry.getValue().getMappingToSourceColumns(),false,nodeLabelType,linkLabelType,showNodeMetaData,showLinkMetaData);
      }
      cluster.id("cluster_" + counter);
      cluster.attr("label",entry.getKey());
      graphViz.subGraph(cluster);
      counter++;
    }
  }
  OutputStream out=new FileOutputStream(filename);
  graphViz.writeTo(out);
}

