/** 
 * This nearest neighbor search is implemented in the abstract VectorSearcher class itself: this enables all subclasses to reuse the search whatever scoring method they implement.  Since query expressions are built into the VectorSearcher, getNearestNeighbors no longer takes a query vector as an argument.
 * @param numResults the number of results / length of the result list.
 */
public LinkedList<SearchResult> getNearestNeighbors(int numResults){
  final double unsetScore=-Math.PI;
  final int bufferSize=1000;
  final int indexSize=numResults + bufferSize;
  LinkedList<SearchResult> results=new LinkedList<SearchResult>();
  List<SearchResult> tmpResults=new ArrayList<SearchResult>(indexSize);
  double score=-1;
  double threshold=flagConfig.searchresultsminscore();
  if (flagConfig.stdev())   threshold=0;
  double sum=0, sumsquared=0;
  int count=0;
  int pos=0;
  for (int i=0; i < indexSize; i++) {
    tmpResults.add(new SearchResult(unsetScore,null));
  }
  Enumeration<ObjectVector> vecEnum=searchVecStore.getAllVectors();
  while (vecEnum.hasMoreElements()) {
    ObjectVector testElement=vecEnum.nextElement();
    score=getScore(testElement.getVector());
    if (this.luceneUtils != null && flagConfig.usetermweightsintermsearch()) {
      score=score * luceneUtils.getGlobalTermWeightFromString((String)testElement.getObject());
    }
    if (flagConfig.stdev()) {
      double susq=Math.pow(score,2);
      if (!Double.isNaN(susq)) {
        count++;
        sum+=score;
        sumsquared+=Math.pow(score,2);
      }
    }
    if (score > threshold) {
      tmpResults.get(numResults + pos++).set(score,testElement);
    }
    if (pos == bufferSize) {
      pos=0;
      Collections.sort(tmpResults);
      threshold=tmpResults.get(indexSize - 1).getScore();
    }
  }
  Collections.sort(tmpResults);
  for (int i=0; i < numResults; i++) {
    SearchResult sr=tmpResults.get(i);
    if (sr.getScore() == unsetScore) {
      break;
    }
    results.add(sr);
  }
  if (flagConfig.stdev())   results=transformToStats(results,count,sum,sumsquared);
  return results;
}
/** 
 * This overrides the nearest neighbor class implemented in the abstract {@code VectorSearcher} class.WARNING: This implementation fails to respect flags used by the {@code VectorSearcher.getNearestNeighbors} method.
 * @param numResults the number of results / length of the result list.
 */
@Override public LinkedList<SearchResult> getNearestNeighbors(int numResults){
  LinkedList<SearchResult> results=new LinkedList<SearchResult>();
  double score, score1, score2=-1;
  double threshold=specialFlagConfig.searchresultsminscore();
  if (specialFlagConfig.stdev())   threshold=0;
  double sum=0, sumsquared=0;
  int count=0;
  Enumeration<ObjectVector> vecEnum=searchVecStore.getAllVectors();
  Enumeration<ObjectVector> vecEnum2=queryVecStore.getAllVectors();
  while (vecEnum.hasMoreElements()) {
    ObjectVector testElement=vecEnum.nextElement();
    ObjectVector testElement2=vecEnum2.nextElement();
    score1=getScore(testElement.getVector());
    score2=getScore2(testElement2.getVector());
    score=Math.max(score1,score2);
    if ((specialLuceneUtils != null) && specialFlagConfig.usetermweightsintermsearch()) {
      score=score * specialLuceneUtils.getGlobalTermWeightFromString((String)testElement.getObject());
    }
    if (specialFlagConfig.stdev()) {
      System.out.println("STDEV");
      count++;
      sum+=score;
      sumsquared+=Math.pow(score,2);
    }
    if (score > threshold) {
      boolean added=false;
      for (int i=0; i < results.size(); ++i) {
        if (score > results.get(i).getScore() && added == false) {
          results.add(i,new SearchResult(score,testElement));
          added=true;
        }
      }
      if (results.size() > numResults) {
        results.removeLast();
        threshold=results.getLast().getScore();
      }
 else {
        if (added == false) {
          results.add(new SearchResult(score,testElement));
        }
      }
    }
  }
  if (specialFlagConfig.stdev())   results=transformToStats(results,count,sum,sumsquared);
  return results;
}
/** 
 * This overrides the nearest neighbor class implemented in the abstract {@code VectorSearcher} class.WARNING: This implementation fails to respect flags used by the {@code VectorSearcher.getNearestNeighbors} method.
 * @param numResults the number of results / length of the result list.
 */
@Override public LinkedList<SearchResult> getNearestNeighbors(int numResults){
  LinkedList<SearchResult> results=new LinkedList<SearchResult>();
  BooleanQuery.Builder mtq=new BooleanQuery.Builder();
  for (int q=0; q < queryTerms.length; q++) {
    String term=queryTerms[q];
    if (acceptableTerms != null && !acceptableTerms.containsVector(term))     continue;
    for (    String field : this.specialFlagConfig.contentsfields())     mtq.add(new TermQuery(new org.apache.lucene.index.Term(field,term)),org.apache.lucene.search.BooleanClause.Occur.SHOULD);
  }
  TopDocs docs;
  try {
    docs=iSearcher.search(mtq.build(),specialFlagConfig.numsearchresults());
    ScoreDoc[] hits2=docs.scoreDocs;
    for (int i=0; i < hits2.length; i++) {
      int docId=hits2[i].doc;
      if (specialFlagConfig.hybridvectors())       if (i < specialFlagConfig.numsearchresults()) {
        Explanation explain=iSearcher.explain(mtq.build(),docId);
        System.out.println(explain);
      }
      Document d=iSearcher.doc(docId);
      float dscore=hits2[i].score;
      results.add(new SearchResult(dscore,new ObjectVector(d.get(specialFlagConfig.docidfield()),null)));
    }
  }
 catch (  IOException e) {
    logger.info("Lucene search failed: " + e.getMessage());
  }
  return results;
}

