/** 
 * Extracts the key (or key prefix depending on  {@code path}) from the S3 path. <p/> An "S3 path" is of the form  {@code s3://bucket-name/path/or/path/prefix} or{@code s3n://bucket-name/path/or/path/prefix}. In either of these examples, this function would return {@code path/or/path/prefix}.
 * @param path the S3 path.
 * @return the S3 key portion of the path (or key prefix depending on {@code path}), or null if  {@code path} is notan S3 path.
 */
public static String getKeyFromPath(final String path){
  if (Strings.isNullOrEmpty(path) || !path.startsWith("s3:") && !path.startsWith("s3n:")) {
    return null;
  }
  final String res=path.replaceFirst("(s3://|s3n://)","");
  final int i=res.indexOf('/');
  return i != -1 ? res.substring(i + 1) : null;
}

@Override public void visit(NodeTraversal t,Node n,Node parent){
switch (n.getToken()) {
case CALL:
    Node left=n.getFirstChild();
  if (left.isGetProp()) {
    Node name=left.getFirstChild();
    if (name.isName() && GOOG.equals(name.getString())) {
      String methodName=name.getNext().getString();
switch (methodName) {
case "base":
        processBaseClassCall(t,n);
      break;
case "define":
    processDefineCall(t,n,parent);
  break;
case "inherits":
processInheritsCall(n);
break;
case "exportSymbol":
Node arg=left.getNext();
if (arg.isString()) {
String argString=arg.getString();
int dot=argString.indexOf('.');
if (dot == -1) {
exportedVariables.add(argString);
}
 else {
exportedVariables.add(argString.substring(0,dot));
}
}
break;
case "addDependency":
if (validateUnaliasablePrimitiveCall(t,n,methodName)) {
processAddDependency(n,parent);
}
break;
case "setCssNameMapping":
processSetCssNameMapping(n,parent);
break;
case "forwardDeclare":
if (validatePrimitiveCallWithMessage(t,n,methodName,ProcessClosurePrimitives.CLOSURE_CALL_CANNOT_BE_ALIASED_OUTSIDE_MODULE_ERROR)) {
processForwardDeclare(n);
}
break;
default :
}
}
 else if (left.getLastChild().getString().equals("base")) {
maybeProcessClassBaseCall(n);
}
}
break;
case ASSIGN:
case NAME:
if (n.isName() && n.getString().equals("CLOSURE_DEFINES")) {
handleClosureDefinesValues(n);
}
break;
case GETPROP:
