protected LinkedList<Integer> getNeighbours(ExampleSet exampleSet,Example centroid,int centroidIndex,final int[] assignments,SVClusteringAlgorithm clustering) throws UndefinedParameterError {
  LinkedList<Integer> neighbors=new LinkedList<Integer>();
  double paramR=getParameterAsDouble(PARAMETER_R);
  double maxRadius=paramR < 0 ? clustering.getR() : paramR;
  int numSamplePoints=getParameterAsInt(PARAMETER_NUMBER_SAMPLE_POINTS);
  int i=0;
  for (  Example example : exampleSet) {
    if (i != centroidIndex && assignments[i] == UNASSIGNED) {
      double[] directions=new double[centroid.getAttributes().size()];
      int x=0;
      for (      Attribute attribute : centroid.getAttributes()) {
        directions[x++]=example.getValue(attribute) - centroid.getValue(attribute);
      }
      boolean addAsNeighbor=true;
      for (int j=0; j < numSamplePoints; j++) {
        if (addAsNeighbor) {
          double[] virtualExample=new double[directions.length];
          x=0;
          for (          Attribute attribute : centroid.getAttributes()) {
            virtualExample[x]=centroid.getValue(attribute) + (j + 1) * directions[x] / (numSamplePoints + 1);
            x++;
          }
          SVMExample svmExample=new SVMExample(virtualExample);
          double currentRadius=clustering.predict(svmExample);
          if (currentRadius > maxRadius) {
            addAsNeighbor=false;
            break;
          }
        }
 else {
          break;
        }
      }
      if (addAsNeighbor)       neighbors.add(i);
    }
    i++;
  }
  return neighbors;
}

