@SuppressWarnings("unchecked") protected void waitForConsumedServicesActivate(ProcessState state,Service service){
  List<Integer> consumedServicesIds=DataAccessor.fromMap(state.getData()).withKey(ServiceConstants.FIELD_WAIT_FOR_CONSUMED_SERVICES_IDS).withDefault(Collections.EMPTY_LIST).as(List.class);
  if (consumedServicesIds.isEmpty()) {
    List<Long> servicesViaLinkIds=(List<Long>)CollectionUtils.collect(consumeMapDao.findConsumedServices(service.getId()),TransformerUtils.invokerTransformer("getConsumedServiceId"));
    for (    Long serviceViaLinkId : servicesViaLinkIds) {
      Service consumedService=objectManager.loadResource(Service.class,serviceViaLinkId);
      if (consumedService == null) {
        continue;
      }
      resourceMonitor.waitForNotTransitioning(consumedService);
    }
  }
 else {
    for (    Integer consumedServiceId : consumedServicesIds) {
      Service consumedService=objectManager.loadResource(Service.class,consumedServiceId.longValue());
      if (consumedService == null) {
        continue;
      }
      resourceMonitor.waitForState(consumedService,CommonStatesConstants.ACTIVE);
    }
  }
}

