@Override public SoaContext invoke(SoaContext context){
  Status status=beginTX(context);
  SoaContext result=null;
  try {
    Object service=SpringContextHolder.getBean(context.getService());
    Method method=service.getClass().getMethod(context.getMethod(),SoaContext.class);
    result=(SoaContext)method.invoke(service,context);
    if (result != null && !result.isSuccess())     throw new InvokerFailException();
  }
 catch (  InvokerFailException ex) {
    if (status != null)     status.needRollback=true;
  }
catch (  Throwable e) {
    e.printStackTrace();
    if (status != null) {
      status.needRollback=true;
    }
    if ((e.getCause() instanceof AppException)) {
      throw (AppException)e.getCause();
    }
    throw new SysException("service invoke error",e);
  }
 finally {
    endTX(status);
  }
  return result;
}

