/** 
 * Calls  {@link Syncable#sync()} on all appenders in this context. It will always try to call sync on allappenders event some might failed in between.
 * @throws IOException if any appender failed to perform sync. If more than one appender sync failed,the exception from the first appender failure will be thrown, with the subsequent failures added as suppressed exception
 */
@Override public void sync() throws IOException {
  IOException failure=null;
  for (  Appender<ILoggingEvent> appender : appenders) {
    if (appender instanceof Syncable) {
      try {
        ((Syncable)appender).sync();
      }
 catch (      IOException e) {
        failure=addException(failure,e);
      }
    }
  }
  if (failure != null) {
    throw failure;
  }
}

