@SuppressWarnings("unchecked") @Override public boolean find(String desc,InsnList insns,Collection<AbstractInsnNode> nodes){
  boolean found=false;
  int ordinal=0;
  Collection<TypeInsnNode> newNodes=new ArrayList<TypeInsnNode>();
  Collection<AbstractInsnNode> candidates=(Collection<AbstractInsnNode>)(this.desc != null ? newNodes : nodes);
  ListIterator<AbstractInsnNode> iter=insns.iterator();
  while (iter.hasNext()) {
    AbstractInsnNode insn=iter.next();
    if (insn instanceof TypeInsnNode && insn.getOpcode() == Opcodes.NEW && this.matchesOwner((TypeInsnNode)insn)) {
      if (this.ordinal == -1 || this.ordinal == ordinal) {
        candidates.add(insn);
        found=this.desc == null;
      }
      ordinal++;
    }
  }
  if (this.desc != null) {
    for (    TypeInsnNode newNode : newNodes) {
      if (this.findCtor(insns,newNode)) {
        nodes.add(newNode);
        found=true;
      }
    }
  }
  return found;
}

@Override public void addCols(String dbName,String tblName,String modifyUser,List<FieldSchema> newCols) throws InvalidOperationException, MetaException, InvalidObjectException {
  if (!MetaStoreUtils.validateColNames(newCols)) {
    throw new InvalidObjectException("new add columns name is not valid object");
  }
  Connection con=null;
  PreparedStatement ps=null;
  boolean success=false;
  dbName=dbName.toLowerCase();
  tblName=tblName.toLowerCase();
  try {
    con=getSegmentConnection(dbName);
  }
 catch (  MetaStoreConnectException e1) {
    LOG.error("add column error, db=" + dbName + ", tbl="+ tblName+ ", msg="+ e1.getMessage());
    throw new MetaException(e1.getMessage());
  }
catch (  SQLException e1) {
    LOG.error("add column error, db=" + dbName + ", tbl="+ tblName+ ", msg="+ e1.getMessage());
    throw new MetaException(e1.getMessage());
  }
  try {
    con.setAutoCommit(false);
    con.setTransactionIsolation(Connection.TRANSACTION_REPEATABLE_READ);
    ps=con.prepareStatement("select tbl_id, tbl_type, tbl_format, serde_lib" + "  from tbls where tbls.db_name=? and tbls.tbl_name=? ");
    ps.setString(1,dbName);
    ps.setString(2,tblName);
    String tblType=null;
    String serdeLib=null;
    String tblFormat=null;
    boolean isTblFind=false;
    long tblID=0;
    ResultSet tblSet=ps.executeQuery();
    while (tblSet.next()) {
      isTblFind=true;
      tblID=tblSet.getLong(1);
      tblType=tblSet.getString(2);
      tblFormat=tblSet.getString(3);
      serdeLib=tblSet.getString(4);
    }
    tblSet.close();
    ps.close();
    if (!isTblFind) {
      LOG.error("add column error, db=" + dbName + ", tbl="+ tblName);
      throw new MetaException("can not find table " + dbName + ":"+ tblName);
    }
    if (tblFormat == null || tblFormat.isEmpty()) {
      tblFormat="text";
    }
    if (tblType.equalsIgnoreCase("VITURAL_VIEW")) {
      LOG.error("add column error, db=" + dbName + ", tbl="+ tblName);
      throw new InvalidOperationException("view can not add cloumns");
    }
    if (tblType.equalsIgnoreCase("EXTERNAL_TABLE") && !HiveConf.getBoolVar(hiveConf,ConfVars.ALTERSCHEMAACTIVATEEXTTABLE)) {
      LOG.error("add column error, db=" + dbName + ", tbl="+ tblName);
      throw new InvalidOperationException("can not add columns for a extenal table ");
    }
    if (!tblType.equalsIgnoreCase("EXTERNAL_TABLE") && tblFormat.equalsIgnoreCase("text") && (!HiveConf.getBoolVar(hiveConf,ConfVars.ALTERSCHEMAACTIVATETXTTABLE))) {
      LOG.error("add column error, db=" + dbName + ", tbl="+ tblName);
      throw new InvalidOperationException("can not add columns for a text format table ");
    }
    if (serdeLib != null && serdeLib.equals(ProtobufSerDe.class.getName())) {
      LOG.error("add column error, db=" + dbName + ", tbl="+ tblName);
      throw new InvalidOperationException("can not add columns for a pb table ");
    }
    if (tblFormat != null && (tblFormat.equalsIgnoreCase("column") || tblFormat.equalsIgnoreCase("format"))) {
      for (      FieldSchema field : newCols) {
        if (field.getType().equals(Constants.BOOLEAN_TYPE_NAME)) {
          LOG.error("add column error, db=" + dbName + ", tbl="+ tblName);
          throw new InvalidOperationException("format file or column file not support boolean type rightnow");
        }
      }
    }
    Map<String,String> tblParamMap=new HashMap<String,String>();
    ps=con.prepareStatement("select param_key, param_value from table_params where tbl_id=? and param_type='TBL'");
    ps.setLong(1,tblID);
    ResultSet paramSet=ps.executeQuery();
    while (paramSet.next()) {
      tblParamMap.put(paramSet.getString(1),paramSet.getString(2));
    }
    paramSet.close();
    ps.close();
    boolean containTime=false;
    boolean contailUser=false;
    if (tblParamMap.containsKey("last_modified_time"))     containTime=true;
    if (tblParamMap.containsKey("last_modified_by"))     contailUser=true;
    if (containTime && contailUser) {
      ps=con.prepareStatement("update table_params set param_value=? where tbl_id=? and param_type='TBL' and param_key=?");
      ps.setString(1,String.valueOf(System.currentTimeMillis() / 1000));
      ps.setLong(2,tblID);
      ps.setString(3,"last_modified_time");
      ps.addBatch();
      ps.setString(1,modifyUser);
      ps.setLong(2,tblID);
