/** 
 * <p>Replaces all occurrences of a String within another String.</p> <p>A <code>null</code> reference passed to this method is a no-op.</p> <pre> GosuStringUtil.replace(null, *, *)        = null GosuStringUtil.replace("", *, *)          = "" GosuStringUtil.replace("any", null, *)    = "any" GosuStringUtil.replace("any", *, null)    = "any" GosuStringUtil.replace("any", "", *)      = "any" GosuStringUtil.replace("aba", "a", null)  = "aba" GosuStringUtil.replace("aba", "a", "")    = "b" GosuStringUtil.replace("aba", "a", "z")   = "zbz" </pre>
 * @see #replace(String text,String searchString,String replacement,int max)
 * @param text  text to search and replace in, may be null
 * @param searchString  the String to search for, may be null
 * @param replacement  the String to replace it with, may be null
 * @return the text with any replacements processed,<code>null</code> if null String input
 */
public static String replace(String text,String searchString,String replacement){
  return replace(text,searchString,replacement,-1);
}
/** 
 * <p>Replaces a String with another String inside a larger String, for the first <code>max</code> values of the search String.</p> <p>A <code>null</code> reference passed to this method is a no-op.</p> <pre> GosuStringUtil.replace(null, *, *, *)         = null GosuStringUtil.replace("", *, *, *)           = "" GosuStringUtil.replace("any", null, *, *)     = "any" GosuStringUtil.replace("any", *, null, *)     = "any" GosuStringUtil.replace("any", "", *, *)       = "any" GosuStringUtil.replace("any", *, *, 0)        = "any" GosuStringUtil.replace("abaa", "a", null, -1) = "abaa" GosuStringUtil.replace("abaa", "a", "", -1)   = "b" GosuStringUtil.replace("abaa", "a", "z", 0)   = "abaa" GosuStringUtil.replace("abaa", "a", "z", 1)   = "zbaa" GosuStringUtil.replace("abaa", "a", "z", 2)   = "zbza" GosuStringUtil.replace("abaa", "a", "z", -1)  = "zbzz" </pre>
 * @param text  text to search and replace in, may be null
 * @param searchString  the String to search for, may be null
 * @param replacement  the String to replace it with, may be null
 * @param max  maximum number of values to replace, or <code>-1</code> if no maximum
 * @return the text with any replacements processed,<code>null</code> if null String input
 */
public static String replace(String text,String searchString,String replacement,int max){
  if (isEmpty(text) || isEmpty(searchString) || replacement == null || max == 0) {
    return text;
  }
  int start=0;
  int end=text.indexOf(searchString,start);
  if (end == -1) {
    return text;
  }
  int replLength=searchString.length();
  int increase=replacement.length() - replLength;
  increase=(increase < 0 ? 0 : increase);
  increase*=(max < 0 ? 16 : (max > 64 ? 64 : max));
  StringBuilder buf=new StringBuilder(text.length() + increase);
  while (end != -1) {
    buf.append(text.substring(start,end)).append(replacement);
    start=end + replLength;
    if (--max == 0) {
      break;
    }
    end=text.indexOf(searchString,start);
  }
  buf.append(text.substring(start));
  return buf.toString();
}

