 catch (    InterruptedException e2) {
      break;
    }
    long discardCount=ElasticSearchDruidDataSource.this.discardCount;
    boolean discardChanged=discardCount - lastDiscardCount > 0;
    lastDiscardCount=discardCount;
    try {
      boolean emptyWait=true;
      if (createError != null && poolingCount == 0 && !discardChanged) {
        emptyWait=false;
      }
      if (emptyWait && asyncInit && createCount < initialSize) {
        emptyWait=false;
      }
      if (emptyWait) {
        if (poolingCount >= notEmptyWaitThreadCount && (!(keepAlive && activeCount + poolingCount < minIdle)) && !isFailContinuous()) {
          empty.await();
        }
        if (activeCount + poolingCount >= maxActive) {
          empty.await();
          continue;
        }
      }
    }
 catch (    InterruptedException e) {
      lastCreateError=e;
      lastErrorTimeMillis=System.currentTimeMillis();
      if (!closing) {
        LOG.error("create connection Thread Interrupted, url: " + jdbcUrl,e);
      }
      break;
    }
 finally {
      lock.unlock();
    }
    PhysicalConnectionInfo connection=null;
    try {
      connection=createPhysicalConnection();
    }
 catch (    SQLException e) {
      LOG.error("create connection SQLException, url: " + jdbcUrl + ", errorCode "+ e.getErrorCode()+ ", state "+ e.getSQLState(),e);
      errorCount++;
      if (errorCount > connectionErrorRetryAttempts && timeBetweenConnectErrorMillis > 0) {
        setFailContinuous(true);
        if (failFast) {
          lock.lock();
          try {
            notEmpty.signalAll();
          }
  finally {
            lock.unlock();
          }
        }
        if (breakAfterAcquireFailure) {
          break;
        }
        try {
          Thread.sleep(timeBetweenConnectErrorMillis);
        }
 catch (        InterruptedException interruptEx) {
          break;
        }
      }
    }
catch (    RuntimeException e) {
      LOG.error("create connection RuntimeException",e);
      setFailContinuous(true);
      continue;
    }
catch (    Error e) {
      LOG.error("create connection Error",e);
      setFailContinuous(true);
      break;
    }
    if (connection == null) {
      continue;
    }
    boolean result=put(connection);
    if (!result) {
      JdbcUtils.close(connection.getPhysicalConnection());
      LOG.info("put physical connection to pool failed.");
    }
    errorCount=0;
  }
