/** 
 * Installs a Linux PRNG-backed  {@code SecureRandom} implementation as thedefault. Does nothing if the implementation is already the default or if there is not need to install the implementation.
 * @throws SecurityException if the fix is needed but could not be applied.
 */
private static void installLinuxPRNGSecureRandom() throws SecurityException {
  final String methodName=":installLinuxPRNGSecureRandom";
  if (Build.VERSION.SDK_INT > VERSION_CODE_JELLY_BEAN_MR2) {
    Logger.v(TAG + methodName,"No need to apply the fix.");
    return;
  }
  Provider[] secureRandomProviders=Security.getProviders("SecureRandom.SHA1PRNG");
  if (secureRandomProviders == null || secureRandomProviders.length < 1 || !LinuxPRNGSecureRandomProvider.class.equals(secureRandomProviders[0].getClass())) {
    Logger.v(TAG + methodName,"Insert provider as LinuxPRNGSecureRandomProvider.");
    Security.insertProviderAt(new LinuxPRNGSecureRandomProvider(),1);
  }
  SecureRandom rng1=new SecureRandom();
  Logger.i(TAG + methodName,"LinuxPRNGSecureRandomProvider for SecureRandom. ","Provider: " + rng1.getProvider().getClass().getName());
  SecureRandom rng2;
  try {
    rng2=SecureRandom.getInstance("SHA1PRNG");
    Logger.i(TAG + methodName,"LinuxPRNGSecureRandomProvider for SecureRandom with alg SHA1PRNG. ","Provider: " + rng2.getProvider().getClass().getName());
  }
 catch (  NoSuchAlgorithmException e) {
    Logger.v(TAG + methodName,"SHA1PRNG not available.");
    throw new SecurityException("SHA1PRNG not available",e);
  }
}

