/** 
 * Assigns queries that refer to only one entity to the query plan nodes. These are fixed assignments, and don't change from one query plan to the other
 */
private void assignQueriesToPlanNodesAndEdges(List<Conjunct> queries,List<Conjunct> unassigned,boolean relationQuery){
  Error.push("assignQueriesToPlanNodesAndEdges");
  LOGGER.debug("Assigning queries to query plan nodes and edges");
  try {
    for (    Conjunct c : queries) {
      Set<CompositeMetadata> entities=c.getEntities();
      Conjunct.ConjunctType t=c.getConjunctType();
      LOGGER.debug("Conjunct {}:{}",c,t);
      if (t == Conjunct.ConjunctType.value) {
        LOGGER.debug("Conjunct has one entity");
        QueryPlanNode node=qplan.getNode(entities.iterator().next());
        RewriteQuery rw=new RewriteQuery(compositeMetadata,node.getMetadata());
        QueryExpression q=rw.rewriteQuery(c.getClause(),c.getFieldInfo()).query;
        AnalyzeQuery analyzer=new AnalyzeQuery(node.getMetadata(),c.getReference());
        analyzer.iterate(q);
        node.getData().getConjuncts().add(new Conjunct(q,analyzer.getFieldInfo(),c.getReference()));
      }
 else {
        boolean assigned=false;
        if (t == Conjunct.ConjunctType.relation || (relationQuery && entities.size() <= 2)) {
          Iterator<CompositeMetadata> itr=entities.iterator();
          QueryPlanNode node1=qplan.getNode(itr.next());
          QueryPlanNode node2=qplan.getNode(itr.next());
          if (qplan.isUndirectedConnected(node1,node2)) {
            LOGGER.debug("Conjunct is assigned to an edge");
            QueryPlanData qd=qplan.getEdgeData(node1,node2);
            if (qd == null) {
              qplan.setEdgeData(node1,node2,qd=qplan.newData());
            }
            qd.getConjuncts().add(c);
            assigned=true;
          }
        }
        if (!assigned) {
          LOGGER.debug("Conjunct is unassigned");
          unassigned.add(c);
        }
      }
    }
  }
 catch (  Error e) {
    throw e;
  }
catch (  Exception e) {
    LOGGER.error(e.getMessage(),e);
    throw Error.get(AssocConstants.ERR_REWRITE,e.getMessage());
  }
 finally {
    Error.pop();
  }
}

/** 
 * @see com.kixeye.kixmpp.server.KixmppStanzaHandler#handle(io.netty.channel.Channel,org.jdom2.Element)
 */
public void handle(final Channel channel,final Element stanza){
  Element query=stanza.getChild("query",Namespace.getNamespace("jabber:iq:roster"));
  if (query != null) {
    Promise<List<RosterItem>> promise=rosterProvider.getRoster(channel.attr(BindKixmppServerModule.JID).get());
    promise.addListener(new GenericFutureListener<Future<List<RosterItem>>>(){
      @Override public void operationComplete(      final Future<List<RosterItem>> future) throws Exception {
        Element iq=new Element("iq");
        iq.setAttribute("type","result");
        String id=stanza.getAttributeValue("id");
        if (id != null) {
          iq.setAttribute("id",id);
        }
        Element queryResult=new Element("query",Namespace.getNamespace("jabber:iq:roster"));
        if (future.isSuccess()) {
          final List<RosterItem> roster=future.getNow();
          if (roster != null && !roster.isEmpty()) {
            for (            RosterItem rosterItem : roster) {
              Element item=new Element("item",queryResult.getNamespace());
              if (rosterItem.getJid() != null) {
                item.setAttribute("jid",rosterItem.getJid().getFullJid());
              }
              if (rosterItem.getName() != null) {
                item.setAttribute("name",rosterItem.getName());
              }
              if (rosterItem.getSubscription() != null) {
                item.setAttribute("subscription",rosterItem.getSubscription().name());
              }
              if (rosterItem.getGroup() != null) {
                Element group=new Element("group",item.getNamespace());
                group.setText(rosterItem.getGroup());
                item.addContent(group);
              }
              queryResult.addContent(item);
            }
          }
        }
        iq.addContent(queryResult);
        channel.writeAndFlush(iq);
      }
    }
);
  }
}

