public static CorrelationStruct makeStruct(Question q1,Question q2,Map<java.lang.String,IQuestionResponse> q1responses,Map<java.lang.String,IQuestionResponse> q2responses) throws SurveyException {
  if (QCMetrics.isAnalyzable(q1) && QCMetrics.isAnalyzable(q2) && q1.exclusive&& q2.exclusive) {
    if (q1.ordered && q2.ordered) {
      return new CorrelationStruct(CoefficentsAndTests.RHO,QCMetrics.spearmansRho(q1responses,q2responses),-1.,q1,q2,q1responses.size(),q2responses.size());
    }
 else {
      List<Tuple<SurveyDatum,SurveyDatum>> tuples=new ArrayList<>();
      List<Tuple<SurveyDatum,SurveyDatum>> dummy=new ArrayList<>();
      for (      Map.Entry<String,IQuestionResponse> e : q1responses.entrySet()) {
        String srid=e.getKey();
        SurveyDatum fst=e.getValue().getAnswer();
        if (q2responses.containsKey(srid)) {
          SurveyDatum snd=q2responses.get(srid).getAnswer();
          tuples.add(new Tuple<>(fst,snd));
        }
      }
      Tuple<Double,Double> test=QCMetrics.cramersV(q1.options.values(),q2.options.values(),tuples,dummy);
      return new CorrelationStruct(CoefficentsAndTests.V,test.fst,test.snd,q1,q2,q1responses.size(),q2responses.size());
    }
  }
 else   return null;
}

