@Override boolean parse(final FastDateParser parser,final Calendar calendar,final String source,final ParsePosition pos,final int maxWidth){
  int idx=pos.getIndex();
  int last=source.length();
  if (maxWidth == 0) {
    for (; idx < last; ++idx) {
      final char c=source.charAt(idx);
      if (!Character.isWhitespace(c)) {
        break;
      }
    }
    pos.setIndex(idx);
  }
 else {
    final int end=idx + maxWidth;
    if (last > end) {
      last=end;
    }
  }
  for (; idx < last; ++idx) {
    final char c=source.charAt(idx);
    if (!Character.isDigit(c)) {
      break;
    }
  }
  if (pos.getIndex() == idx) {
    pos.setErrorIndex(idx);
    return false;
  }
  final int value=Integer.parseInt(source.substring(pos.getIndex(),idx));
  pos.setIndex(idx);
  calendar.set(field,modify(parser,value));
  return true;
}

