  for (  Map.Entry<Integer,MessageWatcher> entry : watchers.entrySet()) {
    if (entry.getValue() == f) {
      filterId=entry.getKey();
      break;
    }
  }
  if (filterId == -1)   return;
  sendJson(new JsonRpcRequest("shh_uninstallFilter",add0X(Integer.toHexString(filterId))),SimpleResponse.class);
}

/** 
 * A statement-list needs to push a new scope on the symbol table to provide a for local variable scoping. Since this is a relatively expensive operation we avoid pushing the scope if we know none of the statements declare variables.
 */
private void tryToEliminateTheScope(){
  for (int i=0; i < _statements.length; i++) {
    Statement statement=_statements[i];
    if (statement instanceof VarStatement || (!(statement instanceof StatementList) && statement.getContainedParsedElementsByType(EvalExpression.class,null))) {
      return;
    }
  }
  setNoScope();
}

