private static void loadCompressed(byte[] header,State tga,InputStream in,boolean acceptAlpha,boolean flipVertically) throws IOException {
  int orgWidth=getUnsignedShort(header,12);
  int orgHeight=getUnsignedShort(header,14);
  int pixelDepth=getUnsignedByte(header,16);
  tga.width=orgWidth;
  tga.height=orgHeight;
  tga.pixelDepth=pixelDepth;
  boolean isOriginBottom=(header[17] & 0x20) == 0;
  if (!isOriginBottom) {
    flipVertically=!flipVertically;
  }
  if ((orgWidth <= 0) || (orgHeight <= 0) || ((pixelDepth != 24) && (pixelDepth != 32))) {
    throw new IOException("Invalid texture information !");
  }
  int bytesPerPixel=(pixelDepth / 8);
  int pixelCount=orgHeight * orgWidth;
  int currentPixel=0;
  byte[] colorBuffer=new byte[bytesPerPixel];
  int width=orgWidth;
  int height=orgHeight;
  final int dstBytesPerPixel=(acceptAlpha && (bytesPerPixel == 4) ? 4 : 3);
  final int trgLineSize=orgWidth * dstBytesPerPixel;
  int[] pixels=new int[width * height];
  int dstByteOffset=0;
  do {
    int chunkHeader=0;
    try {
      chunkHeader=(byte)in.read() & 0xFF;
    }
 catch (    IOException e) {
      throw new IOException("Could not read RLE imageData header !");
    }
    boolean repeatColor;
    if (chunkHeader < 128) {
      chunkHeader++;
      repeatColor=false;
    }
 else {
      chunkHeader-=127;
      readBuffer(in,colorBuffer);
      repeatColor=true;
    }
    for (int counter=0; counter < chunkHeader; counter++) {
      if (!repeatColor) {
        readBuffer(in,colorBuffer);
      }
      int x=currentPixel % orgWidth;
      int y=currentPixel / orgWidth;
      int actualByteOffset=dstByteOffset;
      if (!flipVertically) {
        actualByteOffset=((height - y - 1) * trgLineSize) + (x * dstBytesPerPixel);
      }
      if (dstBytesPerPixel == 4) {
        writePixel(pixels,colorBuffer[2],colorBuffer[1],colorBuffer[0],colorBuffer[3],true,actualByteOffset);
      }
 else {
        writePixel(pixels,colorBuffer[2],colorBuffer[1],colorBuffer[0],(byte)0,false,actualByteOffset);
      }
      dstByteOffset+=dstBytesPerPixel;
      currentPixel++;
      if (currentPixel > pixelCount) {
        throw new IOException("Too many pixels read !");
      }
    }
  }
 while (currentPixel < pixelCount);
  tga.pixels=pixels;
  tga.type=dstBytesPerPixel;
}

