 * Changes the current phase to  {@link ExecutionPhase#SUSPENDED SUSPENDED}.
 * @param force	<i>true</i> to ignore the phases order,<i>false</i> otherwise.
 * @throws UWSException	If this phase transition is forbidden<i>(by default: IF force=false AND currentPhase != SUSPENDED, EXECUTING and UNKNOWN)</i>.
 */
protected void setSuspendedPhase(boolean force) throws UWSException {
  if (!force && phase != ExecutionPhase.SUSPENDED && phase != ExecutionPhase.EXECUTING && phase != ExecutionPhase.UNKNOWN)   throw new UWSException(UWSException.BAD_REQUEST,UWSExceptionFactory.incorrectPhaseTransition(job.getJobId(),phase,ExecutionPhase.SUSPENDED));
  phase=ExecutionPhase.SUSPENDED;
}

