private Map<String,PostCondition> getPreconditions(String[] inputNames,JsonNode json){
  Map<String,PostCondition> preConditions=new HashMap<String,PostCondition>();
  for (  String inputName : inputNames) {
    Node parent=operatorMap.get(inputName);
    if (parent == null) {
      error(json,"input block %s not found",inputName);
      continue;
    }
    if (parent.child != null) {
      boolean isException=false;
      if (json.has("operator") && getText(json,"operator").equals("LOAD_BLOCK"))       isException=true;
      if (parent.child.json.has("operator") && getText(parent.child.json,"operator").equals("LOAD_BLOCK"))       isException=true;
      if (parent.json.has("operator") && getText(parent.json,"operator").equals("PIVOT_BLOCK") && parent.json.has("inMemory")&& parent.json.get("inMemory").getBooleanValue())       isException=true;
      if ((json.has("operator") && getText(json,"operator").equals("USER_DEFINED_BLOCK_OPERATOR")) || (parent.child.json.has("operator") && getText(parent.child.json,"operator").equals("USER_DEFINED_BLOCK_OPERATOR")))       isException=true;
      if (!isException) {
        error(json,"parent operator [%s] has a child assigned already.\n\tChild: %s",parent.json.get("line"),parent.child.json.get("line"));
        continue;
      }
    }
    preConditions.put(inputName,parent.condition);
  }
  if (preConditions.size() != inputNames.length)   return null;
  return preConditions;
}

