/** 
 * Generates a value tag based on the type of the value.
 */
private void generateValue(Object value){
  if (value == null) {
    tag("string","void");
  }
 else {
    Class<?> clazz=value.getClass();
    if (clazz == String.class || clazz == Character.class) {
      sb.append(StringEscapeUtils.escapeXml(value.toString()));
    }
 else     if (clazz == Long.class || clazz == Integer.class || clazz == Short.class || clazz == Byte.class) {
      tag("int",value.toString());
    }
 else     if (clazz == Double.class) {
      tag("double",String.valueOf(((Double)value).doubleValue()));
    }
 else     if (clazz == Float.class) {
      BigDecimal bd=new BigDecimal((Float)value);
      generateValue(bd.setScale(6,RoundingMode.HALF_DOWN).doubleValue());
    }
 else     if (clazz == BigDecimal.class) {
      generateValue(((BigDecimal)value).setScale(6,RoundingMode.HALF_DOWN).doubleValue());
    }
 else     if (clazz == Boolean.class) {
      tag("boolean",((Boolean)value).booleanValue() ? "1" : "0");
    }
 else     if (clazz == Date.class) {
      tag("dateTime.iso8601",xmlRpcDateFormat.format(((Date)value)));
    }
 else     if (value instanceof Calendar) {
      generateValue(((Calendar)value).getTime());
    }
 else     if (value instanceof byte[]) {
      tag("base64",Base64.getEncoder().encodeToString((byte[])value));
    }
 else     if (clazz.isArray() || value instanceof List) {
      sb.append("<array><data>");
      Object[] array=null;
      if (value instanceof List) {
        array=((List<?>)value).toArray();
      }
 else {
        array=(Object[])value;
      }
      for (      Object arrayObject : array) {
        sb.append("<value>");
        generateValue(arrayObject);
        sb.append("</value>");
      }
      sb.append("</data></array>");
    }
 else     if (value instanceof Map) {
      sb.append("<struct>");
      for (      Entry<?,?> entry : ((Map<?,?>)value).entrySet()) {
        sb.append("<member>");
        sb.append("<name>").append(entry.getKey()).append("</name>");
        sb.append("<value>");
        generateValue(entry.getValue());
        sb.append("</value>");
        sb.append("</member>");
      }
      sb.append("</struct>");
    }
 else {
      throw new RuntimeException("Unsupported XML-RPC Type: " + value.getClass());
    }
  }
}

/** 
 * Writes a Node that should be placed at the beginning of finally block. 
 */
void enterFinallyBlock(@Nullable Case catchCase,@Nullable Case finallyCase,Node sourceNode){
  removeCatchFinallyCases(catchCase,finallyCase);
  Case nextCatchCase=getNextCatchCase();
  Case nextFinallyCase=getNextFinallyCase();
  ArrayList<Node> args=new ArrayList<>();
  if (nestedFinallyBlockCount == 0) {
    if (nextCatchCase != null || nextFinallyCase != null) {
      args.add(nextCatchCase == null ? withType(IR.number(0),numberType).useSourceInfoFrom(sourceNode) : nextCatchCase.getNumber(sourceNode));
      if (nextFinallyCase != null) {
        args.add(nextFinallyCase.getNumber(sourceNode));
      }
    }
  }
 else {
    args.add(nextCatchCase == null ? withType(IR.number(0),numberType).useSourceInfoFrom(sourceNode) : nextCatchCase.getNumber(sourceNode));
    args.add(nextFinallyCase == null ? withType(IR.number(0),numberType).useSourceInfoFrom(sourceNode) : nextFinallyCase.getNumber(sourceNode));
    args.add(IR.number(nestedFinallyBlockCount).useSourceInfoFrom(sourceNode));
  }
  writeGeneratedNode(callContextMethodResult(sourceNode,"enterFinallyBlock",args.toArray(new Node[0])));
  ++nestedFinallyBlockCount;
}

