  if (!autoCommit && uncommitedDeletes != null && uncommitedDeletes.contains(bbKey))   return null;
  byte[] value=null;
  if (!autoCommit && uncommited != null) {
    value=uncommited.get(bbKey);
    if (value != null)     return value;
  }
  try {
    value=db.get(key);
  }
 catch (  DBException e) {
    log.error("Caught error opening file",e);
    try {
      Thread.sleep(1000);
    }
 catch (    InterruptedException e1) {
    }
    value=db.get(key);
  }
  return value;
}

