    Notification<T1> n1=jo1.queue().peek();
    Notification<T2> n2=jo2.queue().peek();
    Notification<T3> n3=jo3.queue().peek();
    Notification<T4> n4=jo4.queue().peek();
    Notification<T5> n5=jo5.queue().peek();
    Notification<T6> n6=jo6.queue().peek();
    Notification<T7> n7=jo7.queue().peek();
    if (n1.isOnCompleted() || n2.isOnCompleted() || n3.isOnCompleted()|| n4.isOnCompleted()|| n5.isOnCompleted()|| n6.isOnCompleted()|| n7.isOnCompleted()) {
      onCompleted.call();
    }
 else {
      dequeue();
      onNext.call(n1.getValue(),n2.getValue(),n3.getValue(),n4.getValue(),n5.getValue(),n6.getValue(),n7.getValue());
    }
  }
}

private void safeInit() throws Exception {
  int count=0;
  long startTime=System.currentTimeMillis();
  while (true) {
    try {
      initialize();
      break;
    }
 catch (    Exception e) {
      count++;
      DocumentClientException dce=ExceptionUtils.getThrottelingException(e);
      long now=System.currentTimeMillis();
      if (count < retryOptions.getMaxRetryAttemptsOnThrottledRequests() && now - startTime < (retryOptions.getMaxRetryWaitTimeInSeconds() * 1000) && dce != null && dce.getStatusCode() == HttpConstants.StatusCodes.TOO_MANY_REQUESTS) {
        Thread.sleep(count * dce.getRetryAfterInMilliseconds() + INITIALIZATION_SLEEP_TIME_ON_THROTTLING);
        continue;
      }
 else {
        throw e;
      }
    }
  }
}

