/** 
 * Send event to player
 * @param evt      event type
 * @param evtData  event data
 */
public void sendEvent(String evt,Object evtData){
  if (listeners.size() == 0 && !evt.equals(PlayerListener.END_OF_MEDIA) && !evt.equals(PlayerListener.CLOSED) && !evt.equals(PlayerListener.ERROR)) {
    return;
  }
  if (closedDelivered) {
    return;
  }
synchronized (evtLock) {
    if (evtQ == null) {
      evtQ=new EvtQ(this);
    }
    evtQ.sendEvent(evt,evtData);
    Thread.currentThread().yield();
  }
  if (evt == PlayerListener.CLOSED || evt == PlayerListener.ERROR) {
    closedDelivered=true;
  }
}

