public boolean visit(IResource resource) throws CoreException {
  if (resource.isAccessible() && resource instanceof IFile && "java".equals(((IFile)resource).getFileExtension())) {
    IFile iFile=(IFile)resource;
    ICompilationUnit compilationUnit=JavaCore.createCompilationUnitFrom(iFile);
    String contents=compilationUnit.getBuffer().getContents();
    final TextEdit edit=codeFormatter.format(CodeFormatter.K_COMPILATION_UNIT,contents,0,contents.length(),0,System.getProperty(LINE_SEPARATOR));
    IDocument document=new Document(contents);
    try {
      if (edit != null) {
        edit.apply(document);
      }
    }
 catch (    MalformedTreeException e) {
      e.printStackTrace();
    }
catch (    BadLocationException e) {
      e.printStackTrace();
    }
    iFile.setContents(new ByteArrayInputStream(document.get().getBytes()),IResource.FORCE,new NullProgressMonitor());
    return true;
  }
  return true;
}

