static private Entry getNextLogLine(Reader in,Path path,boolean skipErrors) throws CorruptedLogFileException, IOException {
  try {
    return in.next();
  }
 catch (  EOFException eof) {
    LOG.info("EOF from hlog " + path + ".  continuing");
    return null;
  }
catch (  IOException e) {
    if (e.getCause() != null && (e.getCause() instanceof ParseException || e.getCause() instanceof org.apache.hadoop.fs.ChecksumException)) {
      LOG.warn("Parse exception " + e.getCause().toString() + " from hlog "+ path+ ".  continuing");
      return null;
    }
    if (!skipErrors) {
      throw e;
    }
    CorruptedLogFileException t=new CorruptedLogFileException("skipErrors=true Ignoring exception" + " while parsing hlog " + path + ". Marking as corrupted");
    t.initCause(e);
    throw t;
  }
}

