private <T,C extends Collection>Response<C> deserializeCollectionResponse(Request request,RawResponse response,Class<T> deserializationType,Class<C> containerType){
  final ResponseType responseType=response.getResponseType();
  Response<C> r;
  if (Payload.class == deserializationType) {
    logger.log(Level.SEVERE,"It's not allowed to ask a collection of '" + Payload.class.getName() + "'. A null payload will be returned.");
    r=new ResponseImpl<C>(response.getStatus(),response.getHeaders(),responseType,null);
  }
 else   if (Response.class == deserializationType || RawResponse.class == deserializationType || SerializedResponse.class == deserializationType) {
    logger.log(Level.SEVERE,"It's not allowed to ask a collection of '" + Response.class.getName() + "'. A null payload will be returned.");
    r=new ResponseImpl<C>(response.getStatus(),response.getHeaders(),responseType,null);
  }
 else   if (Headers.class == deserializationType) {
    logger.log(Level.SEVERE,"It's not allowed to ask a collection of '" + Headers.class.getName() + "'. A null payload will be returned.");
    r=new ResponseImpl<C>(response.getStatus(),response.getHeaders(),responseType,null);
  }
 else   if (responseType == ResponseType.DEFAULT || responseType == ResponseType.TEXT) {
    r=serializationEngine.deserializeResponse(request,response,deserializationType,containerType);
  }
 else {
    logger.log(Level.SEVERE,"Could not process response of type '" + responseType + "' to class '"+ deserializationType.getName()+ "'. A null payload will be returned.");
    r=new ResponseImpl<C>(response.getStatus(),response.getHeaders(),responseType,null);
  }
  return r;
}

