      break;
    }
case ZenConsts.ZEN_MODE_NO_INTERRUPTIONS:
  return false;
}
String packageName=n.getPackageName();
Blacklist blacklist=Blacklist.getInstance();
return !blacklist.getAppConfig(packageName).isRestricted();
}

