  if (timeStarted <= runtimeMeasurement.getTimeStarted() && timeStopped != 0 && timeStopped > runtimeMeasurement.getTimeStarted() && timeStopped >= runtimeMeasurement.getTimeStopped()) {
    for (    RuntimeNode candidate : children) {
