/** 
 * Method submitBrokerRequest.
 * @param tradestrategy Tradestrategy
 * @param totalSumbitted int
 * @return int
 * @throws InterruptedException
 * @throws BrokerModelException
 */
private int submitBrokerRequest(Tradestrategy tradestrategy,ZonedDateTime endDate,int totalSumbitted) throws InterruptedException, BrokerModelException {
  if (this.brokerModel.isHistoricalDataRunning(tradestrategy.getContract()) || this.isCancelled()) {
    _log.error("submitBrokerRequest contract already running: " + tradestrategy.getContract().getSymbol() + " endDate: "+ endDate+ " barSize: "+ tradestrategy.getBarSize()+ " chartDays: "+ tradestrategy.getChartDays());
    return totalSumbitted;
  }
  _log.debug("submitBrokerRequest: " + tradestrategy.getContract().getSymbol() + " endDate: "+ endDate+ " barSize: "+ tradestrategy.getBarSize()+ " chartDays:"+ tradestrategy.getChartDays());
  if (contractRequests.containsKey(tradestrategy.getContract().getSymbol())) {
    this.brokerModel.onContractDetails(tradestrategy.getContract());
    contractRequests.remove(tradestrategy.getContract().getSymbol());
  }
  this.brokerModel.onBrokerData(tradestrategy,endDate);
  totalSumbitted++;
  hasSubmittedInSeconds();
  if (totalSumbitted > getGrandTotal())   incrementGrandTotal();
  int percent=(int)(((double)(totalSumbitted - this.brokerModel.getHistoricalData().size()) / getGrandTotal()) * 100d);
  setProgress(percent);
  if (((Math.floor(totalSumbitted / 58d) == (totalSumbitted / 58d)) && (totalSumbitted > 0)) && this.brokerModel.isConnected()) {
    timerRunning=new AtomicInteger(0);
    timer.start();
synchronized (lockCoreUtilsTest) {
      while (timerRunning.get() / 1000 < 601 && !this.isCancelled()) {
        if ((timerRunning.get() % 60000) == 0) {
          String message="Please wait " + (10 - (timerRunning.get() / 1000 / 60)) + " minutes as there are more than 60 data requests.";
          publish(message);
        }
        lockCoreUtilsTest.wait();
      }
    }
    timer.stop();
    _log.debug("Finished wait 10min wait");
  }
  if (!this.isCancelled()) {
synchronized (this.brokerModel.getHistoricalData()) {
      while (this.brokerModel.getHistoricalData().size() > 8) {
        this.brokerModel.getHistoricalData().wait();
      }
    }
  }
  return totalSumbitted;
}

