/** 
 * Try to fold .substring() or .slice() calls on strings
 */
private Node tryFoldStringSubstringOrSlice(Node n,Node stringNode,Node arg1){
  checkArgument(n.isCall());
  checkArgument(stringNode.isString());
  checkArgument(arg1 != null);
  int start;
  int end;
  String stringAsString=stringNode.getString();
  Double maybeStart=getSideEffectFreeNumberValue(arg1);
  if (maybeStart != null) {
    start=maybeStart.intValue();
  }
 else {
    return n;
  }
  Node arg2=arg1.getNext();
  if (arg2 != null) {
    Double maybeEnd=getSideEffectFreeNumberValue(arg2);
    if (maybeEnd != null) {
      end=maybeEnd.intValue();
    }
 else {
      return n;
    }
    if (arg2.getNext() != null) {
      return n;
    }
  }
 else {
    end=stringAsString.length();
  }
  if ((end > stringAsString.length()) || (start > stringAsString.length()) || (start < 0)|| (end < 0)|| (start > end)) {
    return n;
  }
  String result=stringAsString.substring(start,end);
  Node resultNode=IR.string(result);
  Node parent=n.getParent();
  parent.replaceChild(n,resultNode);
  reportChangeToEnclosingScope(parent);
  return resultNode;
}

@Override public LogicalNode visitRelation(LogicalPlanner.PlanContext ctx,Stack<Expr> stack,Relation relation) throws TajoException {
  String actualRelationName;
  if (IdentifierUtil.isFQTableName(relation.getName())) {
    actualRelationName=relation.getName();
  }
 else {
    actualRelationName=IdentifierUtil.buildFQName(ctx.getQueryContext().get(SessionVars.CURRENT_DATABASE),relation.getName());
  }
  TableDesc desc=catalog.getTableDesc(actualRelationName);
  ScanNode scanNode=ctx.getPlan().createNode(ScanNode.class);
  if (relation.hasAlias()) {
    scanNode.init(desc,relation.getAlias());
  }
 else {
    scanNode.init(desc);
  }
  TablePropertyUtil.setTableProperty(ctx.getQueryContext(),scanNode);
  ctx.getQueryBlock().addRelation(scanNode);
  return scanNode;
}
@Override public LogicalNode visitRelation(ProcessorContext ctx,Stack<Expr> stack,Relation expr) throws TajoException {
  LogicalPlan plan=ctx.planContext.getPlan();
  QueryBlock queryBlock=plan.getBlockByExpr(expr);
  ScanNode scan=queryBlock.getNodeFromExpr(expr);
  TableDesc desc=scan.getTableDesc();
  if (desc.hasEmptySchema()) {
    Set<Column> columns=new HashSet<>();
    if (ctx.projectColumns.containsKey(getQualifiedName(ctx.planContext,expr.getName()))) {
      for (      ColumnReferenceExpr col : ctx.projectColumns.get(getQualifiedName(ctx.planContext,expr.getName()))) {
        columns.add(NameResolver.resolve(plan,queryBlock,col,NameResolvingMode.RELS_ONLY,true));
      }
    }
    if (expr.hasAlias()) {
      if (ctx.projectColumns.containsKey(getQualifiedName(ctx.planContext,expr.getAlias()))) {
        for (        ColumnReferenceExpr col : ctx.projectColumns.get(getQualifiedName(ctx.planContext,expr.getAlias()))) {
          columns.add(NameResolver.resolve(plan,queryBlock,col,NameResolvingMode.RELS_ONLY,true));
        }
      }
    }
    if (columns.isEmpty()) {
      throw new TajoInternalError("Columns projected from " + getQualifiedName(ctx.planContext,expr.getName()) + " is not found.");
    }
    desc.setSchema(buildSchemaFromColumnSet(columns));
    scan.init(desc);
  }
  return scan;
}

@Override public void writeMethod(MethodCall _methodCall,MethodEntry _methodEntry) throws CodeGenException {
  final int argc=_methodEntry.getStackConsumeCount();
  final String methodName=_methodEntry.getNameAndTypeEntry().getNameUTF8Entry().getUTF8();
  final String methodSignature=_methodEntry.getNameAndTypeEntry().getDescriptorUTF8Entry().getUTF8();
  final String barrierAndGetterMappings=javaToCLIdentifierMap.get(methodName + methodSignature);
  if (barrierAndGetterMappings != null) {
    if (argc > 0) {
      write(barrierAndGetterMappings);
      write("(");
      for (int arg=0; arg < argc; arg++) {
        if ((arg != 0)) {
          write(", ");
        }
        writeInstruction(_methodCall.getArg(arg));
      }
      write(")");
    }
 else {
      write(barrierAndGetterMappings);
    }
  }
 else {
    final boolean isSpecial=_methodCall instanceof I_INVOKESPECIAL;
    MethodModel m=entryPoint.getCallTarget(_methodEntry,isSpecial);
    FieldEntry getterField=null;
    if (m != null && m.isGetter()) {
      getterField=m.getAccessorVariableFieldEntry();
    }
    if (getterField != null && isThis(_methodCall.getArg(0))) {
      String fieldName=getterField.getNameAndTypeEntry().getNameUTF8Entry().getUTF8();
      write("this->");
      write(fieldName);
      return;
    }
    boolean noCL=_methodEntry.getOwnerClassModel().getNoCLMethods().contains(_methodEntry.getNameAndTypeEntry().getNameUTF8Entry().getUTF8());
    if (noCL) {
      return;
    }
    final String intrinsicMapping=Kernel.getMappedMethodName(_methodEntry);
    boolean isIntrinsic=false;
    if (intrinsicMapping == null) {
      assert entryPoint != null : "entryPoint should not be null";
      boolean isMapped=Kernel.isMappedMethod(_methodEntry);
      if (m != null) {
        write(m.getName());
      }
 else {
        assert isMapped : _methodEntry + " should be mapped method!";
        write(methodName);
        isIntrinsic=true;
      }
    }
 else {
      write(intrinsicMapping);
    }
    write("(");
    if ((intrinsicMapping == null) && (_methodCall instanceof VirtualMethodCall) && (!isIntrinsic)) {
      final Instruction i=((VirtualMethodCall)_methodCall).getInstanceReference();
      if (i instanceof I_ALOAD_0) {
        write("this");
      }
 else       if (i instanceof AccessArrayElement) {
        final AccessArrayElement arrayAccess=(AccessArrayElement)((VirtualMethodCall)_methodCall).getInstanceReference();
        final Instruction refAccess=arrayAccess.getArrayRef();
        final String fieldName=((AccessField)refAccess).getConstantPoolFieldEntry().getNameAndTypeEntry().getNameUTF8Entry().getUTF8();
        write(" &(this->" + fieldName);
        write("[");
        writeInstruction(arrayAccess.getArrayIndex());
        write("])");
      }
 else {
        assert false : "unhandled call from: " + i;
      }
    }
    for (int arg=0; arg < argc; arg++) {
      if (((intrinsicMapping == null) && (_methodCall instanceof VirtualMethodCall) && (!isIntrinsic)) || (arg != 0)) {
        write(", ");
      }
      writeInstruction(_methodCall.getArg(arg));
    }
    write(")");
  }
}

