@Override public int hashCode(){
  int hashCode=0;
  for (  Method member : getMembers()) {
    int memberNameHashCode=127 * member.getName().hashCode();
    Object value=invoke(member,this);
    int memberValueHashCode;
    if (value instanceof boolean[]) {
      memberValueHashCode=Arrays.hashCode((boolean[])value);
    }
 else     if (value instanceof short[]) {
      memberValueHashCode=Arrays.hashCode((short[])value);
    }
 else     if (value instanceof int[]) {
      memberValueHashCode=Arrays.hashCode((int[])value);
    }
 else     if (value instanceof long[]) {
      memberValueHashCode=Arrays.hashCode((long[])value);
    }
 else     if (value instanceof float[]) {
      memberValueHashCode=Arrays.hashCode((float[])value);
    }
 else     if (value instanceof double[]) {
      memberValueHashCode=Arrays.hashCode((double[])value);
    }
 else     if (value instanceof byte[]) {
      memberValueHashCode=Arrays.hashCode((byte[])value);
    }
 else     if (value instanceof char[]) {
      memberValueHashCode=Arrays.hashCode((char[])value);
    }
 else     if (value instanceof Object[]) {
      memberValueHashCode=Arrays.hashCode((Object[])value);
    }
 else {
      memberValueHashCode=value.hashCode();
    }
    hashCode+=memberNameHashCode ^ memberValueHashCode;
  }
  return hashCode;
}

public void benchmark(int epoch,int transactionSize,int numTransactions,int batchSize) throws Exception {
  LOG.info("Starting the test for {}",this.logClass.getName());
  LOG.info("epoch       = {}",epoch);
  LOG.info("txn size    = {}",transactionSize);
  LOG.info("num_ops     = {}",numTransactions);
  LOG.info("batch_size  = {}",batchSize);
  final String leader=getUniqueHostPort();
  int count=numTransactions;
  final Zxid expectedZxid=new Zxid(epoch,count - 1);
  final CountDownLatch latch=new CountDownLatch(1);
  final int ackCount=0;
class TestReceiver implements Transport.Receiver {
    int ackCount=0;
    @Override public void onReceived(    String source,    Message msg){
      try {
        Zxid zxid=MessageBuilder.fromProtoZxid(msg.getAck().getZxid());
        ackCount++;
        if (zxid.equals(expectedZxid)) {
          latch.countDown();
        }
 else {
          LOG.debug("received {} {}",zxid,expectedZxid);
        }
      }
 catch (      Exception ex) {
        Assert.fail("Unexpected exception: " + ex.getMessage());
      }
    }
    @Override public void onDisconnected(    String source){
    }
  }
  Log log=getLog(String.format("%d_%d_%d_%d",epoch,transactionSize,numTransactions,batchSize));
  PersistentState persistence=new PersistentState(getDirectory(),log);
  TestReceiver receiver=new TestReceiver();
  Transport transport=new NettyTransport(leader,receiver,getDirectory());
  ClusterConfiguration cnf=new ClusterConfiguration(new Zxid(0,0),new ArrayList<String>(),"");
  persistence.setLastSeenConfig(cnf);
  SyncProposalProcessor processor=new SyncProposalProcessor(persistence,transport,batchSize);
  long startTime=System.nanoTime();
  String message=new String(new char[transactionSize]).replace('\0','a');
  for (int i=0; i < count; i++) {
    Transaction txn=new Transaction(new Zxid(epoch,i),ByteBuffer.wrap(message.getBytes()));
    Message proposal=MessageBuilder.buildProposal(txn);
    MessageTuple request=new MessageTuple(leader,proposal);
    processor.processRequest(request);
  }
  latch.await();
  double endTimeSec=(double)(System.nanoTime() - startTime) / (1000 * 1000 * 1000);
  LOG.info("runtime     = {} seconds",endTimeSec);
  LOG.info("throughput  = {} ops/sec",(int)(numTransactions / endTimeSec));
  LOG.info("throughput  = {} MB/sec",numTransactions * transactionSize / endTimeSec / 1024 / 1024);
  LOG.info("ack count   = {}",receiver.ackCount);
  processor.shutdown();
  transport.shutdown();
}

public final static boolean findCoinAddress(byte[] dst,byte[] src){
  if (useLoonNative) {
    return findByteAddress(dst,src);
  }
 else {
    int patternOffset=0;
    int len=dst.length;
    int index=0;
    byte b=src[index++];
    int size=src.length;
    int mark=0;
    for (; index < size; ) {
      if (dst[patternOffset] == b) {
        patternOffset++;
        if (patternOffset == len) {
          return true;
        }
      }
 else {
        if (b == _tag) {
          mark=index;
        }
 else {
          int skip=index - mark;
          int go=34 - skip;
          if (go + index < size && src[go + index] == _tag) {
            index=index + go;
          }
 else           if ((go + index - 1) < size && src[(go + index - 1)] == _tag) {
            index=(index + go - 1);
          }
        }
        patternOffset=0;
      }
      b=src[index++];
    }
    return false;
  }
}

