private void validateAndParseWriteParameters() throws ModbusConfigurationException {
  boolean writeTypeMissing=StringUtils.isBlank(config.getWriteType());
  boolean writeStartMissing=StringUtils.isBlank(config.getWriteStart());
  boolean writeValueTypeMissing=StringUtils.isBlank(config.getWriteValueType());
  boolean writeTransformationMissing=StringUtils.isBlank(config.getWriteTransform());
  writeTransformation=new Transformation(config.getWriteTransform());
  boolean writingCoil=WRITE_TYPE_COIL.equals(config.getWriteType());
  transformationOnlyInWrite=(writeTypeMissing && writeStartMissing && writeValueTypeMissing&& !writeTransformationMissing);
  boolean allMissingOrAllPresentOrOnlyTransform=(writeTypeMissing && writeStartMissing && writeValueTypeMissing) || (!writeTypeMissing && !writeStartMissing && (!writeValueTypeMissing || writingCoil)) || transformationOnlyInWrite;
  if (!allMissingOrAllPresentOrOnlyTransform) {
    String errmsg=String.format("writeType=%s, writeStart=%s, and writeValueType=%s should be all present, or all missing! Alternatively, you can provide just writeTransformation, and use transformation returning JSON.",config.getWriteType(),config.getWriteStart(),config.getWriteValueType());
    throw new ModbusConfigurationException(errmsg);
  }
 else   if (!writeTypeMissing || transformationOnlyInWrite) {
    isWriteEnabled=true;
    if (!transformationOnlyInWrite && !WRITE_TYPE_HOLDING.equals(config.getWriteType()) && !WRITE_TYPE_COIL.equals(config.getWriteType())) {
      String errmsg=String.format("Invalid writeType=%s. Expecting %s or %s!",config.getWriteType(),WRITE_TYPE_HOLDING,WRITE_TYPE_COIL);
      throw new ModbusConfigurationException(errmsg);
    }
    if (transformationOnlyInWrite) {
      writeValueType=ModbusConstants.ValueType.INT16;
    }
 else     if (writingCoil && writeValueTypeMissing) {
      writeValueType=ModbusConstants.ValueType.BIT;
    }
 else {
      try {
        writeValueType=ValueType.fromConfigValue(config.getWriteValueType());
      }
 catch (      IllegalArgumentException e) {
        String errmsg=String.format("Invalid writeValueType=%s!",config.getWriteValueType());
        throw new ModbusConfigurationException(errmsg);
      }
    }
    if (writingCoil && !ModbusConstants.ValueType.BIT.equals(writeValueType)) {
      String errmsg=String.format("Invalid writeValueType: Only writeValueType='%s' (or undefined) supported with coils. Value type was: %s",ModbusConstants.ValueType.BIT,config.getWriteValueType());
      throw new ModbusConfigurationException(errmsg);
    }
 else     if (!writingCoil && writeValueType.getBits() < 16) {
      String errmsg=String.format("Invalid writeValueType: Only writeValueType with larger or equal to 16 bits are supported holding registers. Value type was: %s",config.getWriteValueType());
      throw new ModbusConfigurationException(errmsg);
    }
    try {
      if (!transformationOnlyInWrite) {
        writeStart=Integer.parseInt(config.getWriteStart().trim());
      }
    }
 catch (    IllegalArgumentException e) {
      String errmsg=String.format("Thing %s invalid writeStart: %s",getThing().getUID(),config.getWriteStart());
      throw new ModbusConfigurationException(errmsg);
    }
  }
 else {
    isWriteEnabled=false;
  }
}

