void drain(){
  if (getAndIncrement() != 0) {
    return;
  }
  int missed=1;
  Observer<? super R> downstream=this.downstream;
  ErrorMode errorMode=this.errorMode;
  SimplePlainQueue<T> queue=this.queue;
  AtomicThrowable errors=this.errors;
  for (; ; ) {
    for (; ; ) {
      if (cancelled) {
        queue.clear();
        item=null;
        break;
      }
      int s=state;
      if (errors.get() != null) {
        if (errorMode == ErrorMode.IMMEDIATE || (errorMode == ErrorMode.BOUNDARY && s == STATE_INACTIVE)) {
          queue.clear();
          item=null;
          errors.tryTerminateConsumer(downstream);
          return;
        }
      }
      if (s == STATE_INACTIVE) {
        boolean d=done;
        T v=queue.poll();
        boolean empty=v == null;
        if (d && empty) {
          errors.tryTerminateConsumer(downstream);
          return;
        }
        if (empty) {
          break;
        }
        SingleSource<? extends R> ss;
        try {
          ss=ObjectHelper.requireNonNull(mapper.apply(v),"The mapper returned a null SingleSource");
        }
 catch (        Throwable ex) {
          Exceptions.throwIfFatal(ex);
          upstream.dispose();
          queue.clear();
          errors.tryAddThrowableOrReport(ex);
          errors.tryTerminateConsumer(downstream);
          return;
        }
        state=STATE_ACTIVE;
        ss.subscribe(inner);
        break;
      }
 else       if (s == STATE_RESULT_VALUE) {
        R w=item;
        item=null;
        downstream.onNext(w);
        state=STATE_INACTIVE;
      }
 else {
        break;
      }
    }
    missed=addAndGet(-missed);
    if (missed == 0) {
      break;
    }
  }
}

