 * Tests what we assume about  {@link Class#isPrimitive()} assume at {@link #testClone(Class,Object,Object)} because its documentation is a bit ambiguous:isPrimitive() should only return true for types such as int, not for their wrapper classes such as Integer. 
 */
@Test public void testIsPrimitive(){
@SuppressWarnings("unused") class Primitives {
    boolean a;
    byte b;
    char c;
    short d;
    int f;
    long g;
    float h;
    double i;
  }
  ;
@SuppressWarnings("unused") class NonPrimitives {
