/** 
 * @param image - The image name of the process
 * @return - <code>true</code> if the image name matches one of the below conditions when compared to the list ofimage names that are part of  {@link ProcessNames} enum.<ul> <li>Begins with <li>Ends with <li>contains </ul>
 */
@Override protected boolean matches(String image){
  LOGGER.entering(image);
  if (StringUtils.isEmpty(image)) {
    LOGGER.exiting(false);
    return false;
  }
  for (  ProcessNames process : ProcessNames.values()) {
    String img=process.getUnixImageName();
    if (image.startsWith(img) || image.contains(img) || image.endsWith(img)) {
      LOGGER.exiting(true);
      return true;
    }
  }
  LOGGER.exiting(false);
  return false;
}

public void load(World world,int x,int y,int z){
  for (  AtomicBoolean bool : this.mainDirection) {
    if (bool.get()) {
      x+=this.dX;
      z+=this.dZ;
      int fullState=world.getBlockFullState(x,y,z);
      BlockMaterial mat=BlockFullState.getMaterial(fullState);
      if (Liquid.isLiquidObstacle(mat) || (VanillaMaterials.WATER.isMaterial(mat) && VanillaMaterials.WATER.isSource(BlockFullState.getData(fullState)))) {
        this.state=State.BLOCKED;
        this.holeDistance=Integer.MAX_VALUE;
      }
 else       if (!Liquid.isLiquidObstacle(world.getBlockMaterial(x,y - 1,z))) {
        this.state=State.HOLE;
        this.holeDistance=0;
      }
 else {
        this.state=State.OPEN;
        this.holeDistance=Integer.MAX_VALUE;
      }
      return;
    }
  }
  this.state=State.BLOCKED;
  this.holeDistance=Integer.MAX_VALUE;
}

