/** 
 * Method guessContentType.
 * @param is InputStream
 * @return String
 * @throws IOException
 */
protected String guessContentType(InputStream is) throws IOException {
  String type=URLConnection.guessContentTypeFromStream(is);
  if (type == null) {
    is.mark(10);
    int c1=is.read();
    int c2=is.read();
    int c3=is.read();
    int c4=is.read();
    int c5=is.read();
    is.reset();
    if ((c1 == '{') && (c2 == '\\') && (c3 == 'r')&& (c4 == 't')&& (c5 == 'f')) {
      type="text/rtf";
    }
  }
  return type;
}

