public String saveSpMetadataFile(String spMetadataFileName,InputStream input){
  if (appConfiguration.getShibboleth3IdpRootDir() == null) {
    String errorMessage="Failed to save SP meta-data file due to undefined IDP root folder";
    log.error(errorMessage);
    throw new InvalidConfigurationException(errorMessage);
  }
  String idpMetadataTempFolder=getIdpMetadataTempDir();
  String tempFileName=getTempMetadataFilename(idpMetadataTempFolder,spMetadataFileName);
  File spMetadataFile=new File(idpMetadataTempFolder + tempFileName);
  try (FileOutputStream os=FileUtils.openOutputStream(spMetadataFile)){
    IOUtils.copy(input,os);
    os.flush();
  }
 catch (  IOException ex) {
    log.error("Failed to write SP meta-data file '{}'",spMetadataFile,ex);
    ex.printStackTrace();
    return null;
  }
  return tempFileName;
}
public String saveSpMetadataFile(String uri,String spMetadataFileName){
  if (StringHelper.isEmpty(uri)) {
    return null;
  }
  HTTPFileDownloader.setEasyhttps(new Protocol("https",new EasyCASSLProtocolSocketFactory(),443));
  String spMetadataFileContent=HTTPFileDownloader.getResource(uri,"application/xml, text/xml",null,null);
  if (StringHelper.isEmpty(spMetadataFileContent)) {
    return null;
  }
  ByteArrayInputStream is;
  try {
    byte[] spMetadataFileContentBytes=spMetadataFileContent.getBytes("UTF-8");
    is=new ByteArrayInputStream(spMetadataFileContentBytes);
  }
 catch (  UnsupportedEncodingException ex) {
    log.error("saveSpMetadataFile exception",ex);
    ex.printStackTrace();
    return null;
  }
  FileUploadWrapper tmpfileWrapper=new FileUploadWrapper();
  tmpfileWrapper.setStream(is);
  return saveSpMetadataFile(spMetadataFileName,tmpfileWrapper.getStream());
}

@Override public Component getTreeCellRendererComponent(JTree tree,Object value,boolean sel,boolean expanded,boolean leaf,int row,boolean hasFocus){
  JLabel label=(JLabel)super.getTreeCellRendererComponent(tree,value,sel,expanded,leaf,row,hasFocus);
  if (value instanceof Entry) {
    Entry entry=(Entry)value;
    StringBuilder labelText=new StringBuilder();
    labelText.append("<html>").append(entry.getName());
    StringBuilder state=new StringBuilder();
    if (entry instanceof Repository) {
      String reposState=((Repository)entry).getState();
      if (reposState != null) {
        state.append(reposState).append(" &ndash; ");
      }
    }
    if (entry.getOwner() != null) {
      state.append(entry.getOwner());
    }
    if (entry instanceof DataEntry) {
      state.append("  &ndash; v").append(((DataEntry)entry).getRevision());
      long date=((DataEntry)entry).getDate();
      if (date >= 0) {
        state.append(", ").append(DATE_FORMAT.format(new Date(date)));
      }
      long size=((DataEntry)entry).getSize();
      if (size > 0) {
        state.append(" &ndash; ").append(Tools.formatBytes(size));
      }
    }
    if (state.length() > 0) {
      labelText.append(" <small style=\"color:gray\">(").append(state).append(")</small>");
    }
    labelText.append("</html>");
    label.setText(labelText.toString());
    if (entry instanceof Repository) {
      Repository repo=(Repository)entry;
      if (ICON_REPOSITORY_MAP.get(repo.getIconName()) == null) {
        ICON_REPOSITORY_MAP.put(repo.getIconName(),SwingTools.createIcon("16/" + repo.getIconName()));
      }
      label.setIcon(ICON_REPOSITORY_MAP.get(repo.getIconName()));
    }
 else     if (entry.getType().equals(Folder.TYPE_NAME)) {
      if (entry.isReadOnly()) {
        label.setIcon(ICON_FOLDER_LOCKED);
      }
 else       if (expanded) {
        label.setIcon(ICON_FOLDER_OPEN);
      }
 else {
        label.setIcon(ICON_FOLDER_CLOSED);
      }
    }
 else     if (entry.getType().equals(IOObjectEntry.TYPE_NAME)) {
      if (entry instanceof IOObjectEntry) {
        IOObjectEntry dataEntry=(IOObjectEntry)entry;
        label.setIcon(RendererService.getIcon(dataEntry.getObjectClass()));
      }
 else {
        label.setIcon(ICON_DATA);
      }
    }
 else     if (entry.getType().equals(ProcessEntry.TYPE_NAME)) {
      label.setIcon(ICON_PROCESS);
    }
 else     if (entry.getType().equals(BlobEntry.TYPE_NAME)) {
      String mimeType=((BlobEntry)entry).getMimeType();
      if (mimeType != null) {
        if (mimeType.startsWith("text/") || "application/pdf".equals(mimeType) || "application/rtf".equals(mimeType)) {
          label.setIcon(ICON_TEXT);
        }
 else         if (mimeType.equals("application/msexcel")) {
          label.setIcon(ICON_TABLE);
        }
 else         if (mimeType.startsWith("image/")) {
          label.setIcon(ICON_IMAGE);
        }
 else {
          label.setIcon(ICON_BLOB);
        }
      }
 else {
        label.setIcon(ICON_BLOB);
      }
    }
 else {
      label.setIcon(null);
    }
  }
  label.setBorder(ENTRY_BORDER);
  return label;
}

