@Override @Nullable <ACS extends Appendable & CharSequence>ACS textTo0(@NotNull ACS a){
  consumePadding();
  int ch=peekCode();
switch (ch) {
case '"':
{
      bytes.readSkip(1);
      if (use8bit)       bytes.parse8bit(a,getEscapingQuotes());
 else       bytes.parseUtf8(a,getEscapingQuotes());
      unescape(a);
      int code=peekCode();
      if (code == '"')       readCode();
      code=peekCode();
      if (code == ',')       readCode();
      break;
    }
case '\'':
{
    bytes.readSkip(1);
    if (use8bit)     bytes.parse8bit(a,TextWire.getEscapingSingleQuotes());
 else     bytes.parseUtf8(a,TextWire.getEscapingSingleQuotes());
    unescape(a);
    int code=peekCode();
    if (code == '\'')     readCode();
    break;
  }
default :
{
  if (bytes.readRemaining() > 0) {
    if (a instanceof Bytes || use8bit)     bytes.parse8bit(a,getEscapingCSVEndOfText());
 else     bytes.parseUtf8(a,getEscapingCSVEndOfText());
  }
 else {
    AppendableUtil.setLength(a,0);
  }
  while (a.length() > 0)   if (Character.isWhitespace(a.charAt(a.length() - 1)))   AppendableUtil.setLength(a,a.length() - 1);
 else   break;
  break;
}
}
int prev=peekBack();
if (prev == ':' || prev == '#' || prev == '}') bytes.readSkip(-1);
return a;
}

