public Double makeDoubleFrom(Object obj){
  if (obj == null) {
    return null;
  }
  if (obj instanceof IDimension) {
    obj=((IDimension)obj).toNumber();
  }
  if (obj instanceof Double) {
    return (Double)obj;
  }
  double d;
  if (obj instanceof Number) {
    d=((Number)obj).doubleValue();
  }
 else   if (obj instanceof Boolean) {
    return (Boolean)obj ? IGosuParser.ONE : IGosuParser.ZERO;
  }
 else   if (obj instanceof Date) {
    return (double)((Date)obj).getTime();
  }
 else   if (obj instanceof Character) {
    return (double)((Character)obj).charValue();
  }
 else   if (CommonServices.getCoercionManager().canCoerce(JavaTypes.NUMBER(),TypeSystem.getFromObject(obj))) {
    Number num=(Number)CommonServices.getCoercionManager().convertValue(obj,JavaTypes.NUMBER());
    return num.doubleValue();
  }
 else {
    String strValue=obj.toString();
    return makeDoubleFrom(parseNumber(strValue));
  }
  if (d >= 0D && d <= 9D) {
    int i=(int)d;
    if (((double)i == d) && (i >= 0 && i <= 9)) {
      return IGosuParser.DOUBLE_DIGITS[i];
    }
  }
  return d;
}

/** 
 * get an available connection and set the boolean flag to  true (unavailable) in the connection pool. Also removes any stale connections, since this method gets called more than add or remove.
 * @param callerSecurityToken   The security token of the caller
 * @param p_protocol            The protocol for the connection
 * @param p_host                The Hostname for the connection
 * @param p_port                The port number for the connection
 * @return                      A stream connection element ornull if not found
 */
public synchronized StreamConnectionElement get(SecurityToken callerSecurityToken,String p_protocol,String p_host,int p_port){
  StreamConnectionElement result=null;
  long c_time=System.currentTimeMillis();
  Enumeration cons=m_connections.elements();
  callerSecurityToken.checkIfPermissionAllowed(Permissions.MIDP);
  while (cons.hasMoreElements()) {
    StreamConnectionElement sce=(StreamConnectionElement)cons.nextElement();
    if ((c_time - sce.m_time) > m_connectionLingerTime) {
      if (!sce.m_in_use) {
        sce.close();
      }
 else {
        sce.m_removed=true;
      }
      m_connections.removeElement(sce);
      continue;
    }
    if (p_host.equals(sce.m_host) && p_port == sce.m_port && p_protocol.equals(sce.m_protocol) && !sce.m_in_use) {
      result=sce;
      continue;
    }
  }
  if (result != null) {
    result.m_in_use=true;
  }
  return result;
}

