private static List<PsiFieldMember> collectFieldsInClass(final PsiElement element,final PsiClass accessObjectClass,final PsiClass clazz){
  final List<PsiFieldMember> classFieldMembers=new ArrayList<PsiFieldMember>();
  final PsiResolveHelper helper=JavaPsiFacade.getInstance(clazz.getProject()).getResolveHelper();
  for (  final PsiField field : clazz.getFields()) {
    if ((helper.isAccessible(field,clazz,accessObjectClass) || hasSetter(clazz,field.getName())) && !PsiTreeUtil.isAncestor(field,element,false)) {
      if (field.hasModifierProperty(PsiModifier.STATIC)) {
        continue;
      }
      if (!hasLowerCaseChar(field.getName())) {
        continue;
      }
      final String fieldType=field.getType().getCanonicalText();
      if ("org.apache.log4j.Logger".equals(fieldType) || "org.apache.logging.log4j.Logger".equals(fieldType) || "java.util.logging.Logger".equals(fieldType)|| "org.slf4j.Logger".equals(fieldType)|| "ch.qos.logback.classic.Logger".equals(fieldType)|| "net.sf.microlog.core.Logger".equals(fieldType)|| "org.apache.commons.logging.Log".equals(fieldType)|| "org.pmw.tinylog.Logger".equals(fieldType)|| "org.jboss.logging.Logger".equals(fieldType)|| "jodd.log.Logger".equals(fieldType)) {
        continue;
      }
      if (field.hasModifierProperty(PsiModifier.FINAL)) {
        if (field.getInitializer() != null) {
          continue;
        }
        if (!accessObjectClass.isEquivalentTo(clazz)) {
          continue;
        }
      }
      final PsiClass containingClass=field.getContainingClass();
      if (containingClass != null) {
        classFieldMembers.add(buildFieldMember(field,containingClass,clazz));
      }
    }
  }
  return classFieldMembers;
}

