/** 
 * Checks the last server reply code and throws an IOException if the code doesn't correspond to a positive FTP reply: <ul> <li>If the reply is a credentials error (lack of permissions or not logged in), an  {@link AuthException}is thrown. For all other error codes, an IOException is thrown with the server reply message. <li>If the reply code is FTPReply.SERVICE_NOT_AVAILABLE (connection dropped prematurely), the connection will be closed before an IOException with the server reply message is thrown. </ul> <p>If the reply is a positive one (not an error error), this method does nothing.
 */
private void checkServerReply() throws IOException, AuthException {
  int replyCode=ftpClient.getReplyCode();
  LOGGER.trace("server reply=" + ftpClient.getReplyString());
  if (replyCode == FTPReply.SERVICE_NOT_AVAILABLE)   closeConnection();
  if (!FTPReply.isPositiveCompletion(replyCode)) {
    if (replyCode == FTPReply.BAD_COMMAND_SEQUENCE || replyCode == FTPReply.NEED_PASSWORD || replyCode == FTPReply.NOT_LOGGED_IN)     throwAuthException(ftpClient.getReplyString());
 else     throw new IOException(ftpClient.getReplyString());
  }
}

