/** 
 * Start a drag of item at <code>position</code> using the registered FloatViewManager. Calls through to  {@link #startDrag(int,View,int,int,int)} after obtainingthe floating View from the FloatViewManager.
 * @param position Item to drag.
 * @param dragFlags Flags that restrict some movements of thefloating View. For example, set <code>dragFlags |=  ~ {@link #DRAG_NEG_X}</code> to allow dragging the floating View in all directions except off the screen to the left.
 * @param deltaX Offset in x of the touch coordinate from theleft edge of the floating View (i.e. touch-x minus float View left).
 * @param deltaY Offset in y of the touch coordinate from thetop edge of the floating View (i.e. touch-y minus float View top).
 * @return True if the drag was started, false otherwise. This<code>startDrag</code> will fail if we are not currently in a touch event, there is no registered FloatViewManager, or the FloatViewManager returns a null View.
 */
public boolean startDrag(int position,int dragFlags,int deltaX,int deltaY){
  if (!mInTouchEvent || mFloatViewManager == null) {
    return false;
  }
  View v=mFloatViewManager.onCreateFloatView(position);
  return v != null && startDrag(position,v,dragFlags,deltaX,deltaY);
}
/** 
 * Start a drag of item at <code>position</code> without using a FloatViewManager.
 * @param position Item to drag.
 * @param floatView Floating View.
 * @param dragFlags Flags that restrict some movements of thefloating View. For example, set <code>dragFlags |=  ~ {@link #DRAG_NEG_X}</code> to allow dragging the floating View in all directions except off the screen to the left.
 * @param deltaX Offset in x of the touch coordinate from theleft edge of the floating View (i.e. touch-x minus float View left).
 * @param deltaY Offset in y of the touch coordinate from thetop edge of the floating View (i.e. touch-y minus float View top).
 * @return True if the drag was started, false otherwise. This<code>startDrag</code> will fail if we are not currently in a touch event, <code>floatView</code> is null, or there is a drag in progress.
 */
public boolean startDrag(int position,@Nullable View floatView,int dragFlags,int deltaX,int deltaY){
  if (mDragState != IDLE || !mInTouchEvent || mFloatView != null || floatView == null || !mDragEnabled) {
    return false;
  }
  if (getParent() != null) {
    getParent().requestDisallowInterceptTouchEvent(true);
  }
  int pos=position + getHeaderViewsCount();
  mFirstExpPos=pos;
  mSecondExpPos=pos;
  mSrcPos=pos;
  mFloatPos=pos;
  mDragState=DRAGGING;
  mDragFlags=0;
  mDragFlags|=dragFlags;
  mFloatView=floatView;
  measureFloatView();
  mDragDeltaX=deltaX;
  mDragDeltaY=deltaY;
  int mDragStartY=mY;
  mFloatLoc.x=mX - mDragDeltaX;
  mFloatLoc.y=mY - mDragDeltaY;
  final View srcItem=getChildAt(mSrcPos - getFirstVisiblePosition());
  if (srcItem != null) {
    srcItem.setVisibility(View.INVISIBLE);
  }
  if (mTrackDragSort) {
    mDragSortTracker.startTracking();
  }
switch (mCancelMethod) {
case ON_TOUCH_EVENT:
    super.onTouchEvent(mCancelEvent);
  break;
case ON_INTERCEPT_TOUCH_EVENT:
super.onInterceptTouchEvent(mCancelEvent);
break;
}
requestLayout();
if (mLiftAnimator != null) {
mLiftAnimator.start();
}
return true;
}

/** 
 * Add urgent messages, then non-urgent messages. Add a load message if need to.
 * @param size
 * @param now
 * @param messages
 * @param addPeerLoadStatsRT Will be set if the caller needs to include a load stats message forrealtime (i.e. a realtime request completes etc).
 * @param addPeerLoadStatsBulk Will be set if the caller needs to include a load stats message forbulk (i.e. a bulk request completes etc).
 * @param incomplete Will be set if there were more messages but they did not fit. If this isnot set, we can try another priority.
 * @return
 */
MessageItem addPriorityMessages(long now,MutableBoolean addPeerLoadStatsRT,MutableBoolean addPeerLoadStatsBulk){
  if (logMINOR) {
    int nonEmpty=nonEmptyItemsWithID == null ? 0 : nonEmptyItemsWithID.size();
    int empty=emptyItemsWithID == null ? 0 : emptyItemsWithID.size();
    int byID=itemsByID == null ? 0 : itemsByID.size();
    if (nonEmpty + empty < byID) {
      Logger.error(this,"Leaking itemsByID? non empty = " + nonEmpty + " empty = "+ empty+ " by ID = "+ byID+ " on "+ this);
    }
 else     if (logDEBUG)     Logger.debug(this,"Items: non empty " + nonEmpty + " empty "+ empty+ " by ID "+ byID+ " on "+ this);
  }
  if (roundRobinBetweenUIDs)   moveToUrgent(now);
  clearOldNonUrgent(now);
  if (roundRobinBetweenUIDs) {
    MessageItem item=addUrgentMessages(now,addPeerLoadStatsRT,addPeerLoadStatsBulk);
    if (item != null)     return item;
  }
 else {
    assert (itemsByID == null);
  }
  return addNonUrgentMessages(now,addPeerLoadStatsRT,addPeerLoadStatsBulk);
}

