private String escapeCDATA(String text){
  if (text == null)   return "";
  int len=text.length();
  CharArrayWriter result=new CharArrayWriter(len);
  for (int i=0; i < len; i++) {
    if (((i + 2) < len) && (text.charAt(i) == ']') && (text.charAt(i + 1) == ']')&& (text.charAt(i + 2) == '>')) {
      result.write(']');
      result.write(']');
      result.write('&');
      result.write('g');
      result.write('t');
      result.write(';');
      i+=2;
    }
 else {
      result.write(text.charAt(i));
    }
  }
  return result.toString();
}

private List<MemberId> processClusterMembers(String[] collection,String processing,ClusterConnectOptionsType connectOptions,int clusterPort){
  List<MemberId> memberIds=new ArrayList<>();
  if (collection != null) {
    for (    String member : collection) {
      String uri;
      try {
        uri=getCanonicalURI(member,true);
      }
 catch (      IllegalArgumentException ex) {
        GL.error("ha","Unrecognized {} url {} resulted in exception {}",processing,member,ex);
        throw new IllegalArgumentException("Invalid URL in the cluster configuration:" + member,ex);
      }
      String scheme=getScheme(uri);
      if ((scheme.equals("tcp")) || scheme.equals("udp") || scheme.equals("aws")) {
        int port=getPort(uri);
        if (port == -1) {
          GL.error("ha","Port number is missing while processing {} for {}",processing,member);
          throw new IllegalArgumentException("Invalid port number specified for " + processing + ": "+ member);
        }
        String host=getHost(uri);
        if (scheme.equals("aws")) {
          validateAwsClusterDiscovery(uri,connectOptions,processing,clusterPort,collection.length);
        }
        memberIds.add(new MemberId(scheme,host,port,getPath(uri)));
      }
 else {
        GL.error("ha","Unrecognized scheme {} for {} in {}",getScheme(uri),processing,member);
        throw new IllegalArgumentException("Invalid scheme " + getScheme(uri) + " in the URL for "+ processing+ " in "+ member);
      }
    }
  }
  return memberIds;
}

private static void internalIntrospecthelper(Object bean,String prop,String value,ServletRequest request,String param,boolean ignoreMethodNF) throws JasperException {
  Method method=null;
  Class type=null;
  Class propertyEditorClass=null;
  try {
    java.beans.BeanInfo info=java.beans.Introspector.getBeanInfo(bean.getClass());
    if (info != null) {
      java.beans.PropertyDescriptor pd[]=info.getPropertyDescriptors();
      for (int i=0; i < pd.length; i++) {
        if (pd[i].getName().equals(prop)) {
          method=pd[i].getWriteMethod();
          type=pd[i].getPropertyType();
          propertyEditorClass=pd[i].getPropertyEditorClass();
          break;
        }
      }
    }
    if (method != null) {
      if (type.isArray()) {
        if (request == null) {
          throw new JasperException(Localizer.getMessage("jsp.error.beans.setproperty.noindexset"));
        }
        Class t=type.getComponentType();
        String[] values=request.getParameterValues(param);
        if (values == null)         return;
        if (t.equals(String.class)) {
          method.invoke(bean,new Object[]{values});
        }
 else {
          Object tmpval=null;
          createTypedArray(prop,bean,method,values,t,propertyEditorClass);
        }
      }
 else {
        if (value == null || (param != null && value.equals("")))         return;
        Object oval=convert(prop,value,type,propertyEditorClass);
        if (oval != null)         method.invoke(bean,new Object[]{oval});
      }
    }
  }
 catch (  Exception ex) {
    throw new JasperException(ex);
  }
  if (!ignoreMethodNF && (method == null)) {
    if (type == null) {
      throw new JasperException(Localizer.getMessage("jsp.error.beans.noproperty",prop,bean.getClass().getName()));
    }
 else {
      throw new JasperException(Localizer.getMessage("jsp.error.beans.nomethod.setproperty",prop,type.getName(),bean.getClass().getName()));
    }
  }
}

