public static byte[] readAllOrNothing(int length,InputStream input) throws IOException {
  if (length < 1) {
    return EMPTY_BYTES;
  }
  byte[] buf=new byte[length];
  int read=Streams.readFully(input,buf);
  if (read == 0) {
    return null;
  }
  if (read != length) {
    throw new EOFException();
  }
  return buf;
}

