static List<DeterministicKeyChain> fromProtobuf(List<Protos.Key> keys,@Nullable KeyCrypter crypter) throws UnreadableWalletException {
  return fromProtobuf(keys,crypter,new DefaultKeyChainFactory());
}
/** 
 * Returns all the key chains found in the given list of keys. Typically there will only be one, but in the case of key rotation it can happen that there are multiple chains found.
 */
public static List<DeterministicKeyChain> fromProtobuf(List<Protos.Key> keys,@Nullable KeyCrypter crypter,KeyChainFactory factory) throws UnreadableWalletException {
  List<DeterministicKeyChain> chains=new LinkedList<>();
  DeterministicSeed seed=null;
  DeterministicKeyChain chain=null;
  int lookaheadSize=-1;
  int sigsRequiredToSpend=1;
  List<ChildNumber> accountPath=new ArrayList<>();
  Script.ScriptType outputScriptType=Script.ScriptType.P2PKH;
  PeekingIterator<Protos.Key> iter=Iterators.peekingIterator(keys.iterator());
  while (iter.hasNext()) {
    Protos.Key key=iter.next();
    final Protos.Key.Type t=key.getType();
    if (t == Protos.Key.Type.DETERMINISTIC_MNEMONIC) {
      accountPath=new ArrayList<>();
      for (      int i : key.getAccountPathList()) {
        accountPath.add(new ChildNumber(i));
      }
      if (accountPath.isEmpty())       accountPath=ACCOUNT_ZERO_PATH;
      if (chain != null) {
        checkState(lookaheadSize >= 0);
        chain.setLookaheadSize(lookaheadSize);
        chain.setSigsRequiredToSpend(sigsRequiredToSpend);
        chain.maybeLookAhead();
        chains.add(chain);
        chain=null;
      }
      long timestamp=key.getCreationTimestamp() / 1000;
      String passphrase=DEFAULT_PASSPHRASE_FOR_MNEMONIC;
      if (key.hasSecretBytes()) {
        if (key.hasEncryptedDeterministicSeed())         throw new UnreadableWalletException("Malformed key proto: " + key.toString());
        byte[] seedBytes=null;
        if (key.hasDeterministicSeed()) {
          seedBytes=key.getDeterministicSeed().toByteArray();
        }
        seed=new DeterministicSeed(key.getSecretBytes().toStringUtf8(),seedBytes,passphrase,timestamp);
      }
 else       if (key.hasEncryptedData()) {
        if (key.hasDeterministicSeed())         throw new UnreadableWalletException("Malformed key proto: " + key.toString());
        EncryptedData data=new EncryptedData(key.getEncryptedData().getInitialisationVector().toByteArray(),key.getEncryptedData().getEncryptedPrivateKey().toByteArray());
        EncryptedData encryptedSeedBytes=null;
        if (key.hasEncryptedDeterministicSeed()) {
          Protos.EncryptedData encryptedSeed=key.getEncryptedDeterministicSeed();
          encryptedSeedBytes=new EncryptedData(encryptedSeed.getInitialisationVector().toByteArray(),encryptedSeed.getEncryptedPrivateKey().toByteArray());
        }
        seed=new DeterministicSeed(data,encryptedSeedBytes,timestamp);
      }
 else {
        throw new UnreadableWalletException("Malformed key proto: " + key.toString());
      }
      if (log.isDebugEnabled())       log.debug("Deserializing: DETERMINISTIC_MNEMONIC: {}",seed);
    }
 else     if (t == Protos.Key.Type.DETERMINISTIC_KEY) {
      if (!key.hasDeterministicKey())       throw new UnreadableWalletException("Deterministic key missing extra data: " + key.toString());
      byte[] chainCode=key.getDeterministicKey().getChainCode().toByteArray();
      LinkedList<ChildNumber> path=new LinkedList<>();
      for (      int i : key.getDeterministicKey().getPathList())       path.add(new ChildNumber(i));
      LazyECPoint pubkey=new LazyECPoint(ECKey.CURVE.getCurve(),key.getPublicKey().toByteArray());
      final HDPath immutablePath=HDPath.M(path);
      if (key.hasOutputScriptType())       outputScriptType=Script.ScriptType.valueOf(key.getOutputScriptType().name());
      boolean isWatchingAccountKey=false;
      boolean isFollowingKey=false;
      boolean isSpendingKey=false;
      if (key.getDeterministicKey().getIsFollowing()) {
        if (chain != null) {
          checkState(lookaheadSize >= 0);
          chain.setLookaheadSize(lookaheadSize);
          chain.setSigsRequiredToSpend(sigsRequiredToSpend);
          chain.maybeLookAhead();
          chains.add(chain);
          chain=null;
          seed=null;
        }
        isFollowingKey=true;
      }
      if (chain == null) {
        boolean isMarried=!isFollowingKey && !chains.isEmpty() && chains.get(chains.size() - 1).isFollowing();
        if (seed == null && key.hasSecretBytes()) {
          DeterministicKey accountKey=new DeterministicKey(immutablePath,chainCode,pubkey,new BigInteger(1,key.getSecretBytes().toByteArray()),null);
          accountKey.setCreationTimeSeconds(key.getCreationTimestamp() / 1000);
          chain=factory.makeSpendingKeyChain(accountKey,isMarried,outputScriptType);
          isSpendingKey=true;
        }
 else         if (seed == null) {
          DeterministicKey accountKey=new DeterministicKey(immutablePath,chainCode,pubkey,null,null);
          accountKey.setCreationTimeSeconds(key.getCreationTimestamp() / 1000);
          chain=factory.makeWatchingKeyChain(accountKey,isFollowingKey,isMarried,outputScriptType);
          isWatchingAccountKey=true;
        }
 else {
          chain=factory.makeKeyChain(seed,crypter,isMarried,outputScriptType,HDPath.M(accountPath));
          chain.lookaheadSize=LAZY_CALCULATE_LOOKAHEAD;
        }
      }
      DeterministicKey parent=null;
      if (!path.isEmpty() && !isWatchingAccountKey && !isSpendingKey) {
        ChildNumber index=path.removeLast();
        parent=chain.hierarchy.get(path,false,false);
        path.add(index);
      }
      DeterministicKey detkey;
      if (key.hasSecretBytes()) {
        final BigInteger priv=new BigInteger(1,key.getSecretBytes().toByteArray());
        detkey=new DeterministicKey(immutablePath,chainCode,pubkey,priv,parent);
      }
 else {
        if (key.hasEncryptedData()) {
          Protos.EncryptedData proto=key.getEncryptedData();
          EncryptedData data=new EncryptedData(proto.getInitialisationVector().toByteArray(),proto.getEncryptedPrivateKey().toByteArray());
          checkNotNull(crypter,"Encountered an encrypted key but no key crypter provided");
          detkey=new DeterministicKey(immutablePath,chainCode,crypter,pubkey,data,parent);
        }
 else {
