  try {
    if (header != null) {
      final int space=header.indexOf(' ');
      if (space > 0) {
        final String method=header.substring(0,space);
        if (prefix.equalsIgnoreCase(method)) {
          final String decoded=new String(BaseEncoding.base64().decode(header.substring(space + 1)),StandardCharsets.UTF_8);
          final int i=decoded.indexOf(':');
          if (i > 0) {
            final String username=decoded.substring(0,i);
            final String password=decoded.substring(i + 1);
            final BasicCredentials credentials=new BasicCredentials(username,password);
            try {
              final Optional<P> principal=authenticator.authenticate(credentials);
              if (principal.isPresent()) {
                requestContext.setSecurityContext(new SecurityContext(){
                  @Override public Principal getUserPrincipal(){
                    return principal.get();
                  }
                  @Override public boolean isUserInRole(                  String role){
                    return authorizer.authorize(principal.get(),role);
                  }
                  @Override public boolean isSecure(){
                    return requestContext.getSecurityContext().isSecure();
                  }
                  @Override public String getAuthenticationScheme(){
                    return SecurityContext.BASIC_AUTH;
                  }
                }
);
                return;
              }
            }
 catch (            AuthenticationException e) {
              LOGGER.warn("Error authenticating credentials",e);
              throw new InternalServerErrorException();
            }
          }
        }
      }
    }
  }
 catch (  IllegalArgumentException e) {
    LOGGER.warn("Error decoding credentials",e);
  }
  throw new WebApplicationException(unauthorizedHandler.buildResponse(prefix,realm));
}

