  cp0.setCause(cause);
  cp0.setEpc(epc);
  int status=cp0.getStatus();
  status=setFlag(status,Cp0State.STATUS_EXL);
  cp0.setStatus(status);
  int ebase;
  if (notHasFlag(status,Cp0State.STATUS_BEV)) {
    ebase=cp0.getEbase();
  }
 else {
    ebase=0xBFC00000;
  }
  halt=false;
  return ebase;
}

