/** 
 * Split a var (or let or const) node such as: var a, b; into individual statements: var a; var b;
 * @param n The whose children we should inspect.
 */
private void splitVarDeclarations(Node n){
  for (Node next, c=n.getFirstChild(); c != null; c=next) {
    next=c.getNext();
    if (NodeUtil.isNameDeclaration(c)) {
      if (assertOnChange && !c.hasChildren()) {
        throw new IllegalStateException("Empty VAR node.");
      }
      while (c.getFirstChild() != c.getLastChild()) {
        Node name=c.getFirstChild();
        c.removeChild(name);
        Node newVar=new Node(c.getToken(),name).srcref(n);
        n.addChildBefore(newVar,c);
        reportCodeChange("VAR with multiple children",n);
      }
    }
  }
}

private int ScramblePRX(byte[] buf,int offset,int size,int code){
  writeUnaligned32(buf,offset + 0,PSP_KIRK_CMD_MODE_DECRYPT_CBC);
  writeUnaligned32(buf,offset + 4,0);
  writeUnaligned32(buf,offset + 8,0);
  writeUnaligned32(buf,offset + 12,code & 0xFF);
  writeUnaligned32(buf,offset + 16,size);
  int result=semaphoreModule.hleUtilsBufferCopyWithRange(buf,offset,size,buf,offset,size + 0x14,KIRK.PSP_KIRK_CMD_DECRYPT);
  if (result != 0) {
    log.error(String.format("ScramblePRX returning 0x%X",result));
  }
  return result;
}

