/** 
 * Converts a JSON array or a JSON object to a XML document.
 * @param json                     - The JSON array or object (in the form of a String).
 * @param prettyPrint              - The flag for formatting the resulted XML. If it is true the result will contain tabs and newline ('\n') chars.Default value: true Valid values: true, false
 * @param showXmlDeclaration       - The flag for showing the xml declaration (<?xml version="1.0" encoding="UTF-8" standalone="yes"?>).If this is true then rootTagName can't be empty. Default value: false Valid values: true, false
 * @param rootTagName              - The XML tag name. If this input is empty you will get a list of XML elements.
 * @param defaultJsonArrayItemName - Default XML tag name for items in a JSON array if there isn't a pair (array name, array item name) defined in jsonArraysNames and jsonArraysItemNames.Default value: 'item'
 * @param jsonArraysNames          - The list of array names separated by delimiter.
 * @param jsonArraysItemNames      - The coresponding list of array item names separated by delimiter.
 * @param namespacesPrefixes       - The list of tag prefixes separated by delimiter.
 * @param namespacesUris           - The coresponding list of namespaces uris separated by delimiter.
 * @param delimiter                - The list separatorDefault value: ','
 * @return The converted JSON array or object as an XML document
 */
@Action(name="Convert JSON to XML",outputs={@Output(RETURN_RESULT),@Output(RETURN_CODE)},responses={@Response(text=ResponseNames.SUCCESS,field=RETURN_CODE,value=SUCCESS),@Response(text=ResponseNames.FAILURE,field=RETURN_CODE,value=FAILURE)}) public Map<String,String> execute(@Param(value=JSON,required=true) String json,@Param(value=PRETTY_PRINT) String prettyPrint,@Param(value=SHOW_XML_DECLARATION) String showXmlDeclaration,@Param(value=ROOT_TAG_NAME) String rootTagName,@Param(value=DEFAULT_JSON_ARRAY_ITEM_NAME) String defaultJsonArrayItemName,@Param(value=NAMESPACES_PREFIXES) String namespacesPrefixes,@Param(value=NAMESPACES_URIS) String namespacesUris,@Param(value=JSON_ARRAYS_NAMES) String jsonArraysNames,@Param(value=JSON_ARRAYS_ITEM_NAMES) String jsonArraysItemNames,@Param(value=DELIMITER) String delimiter){
  try {
    showXmlDeclaration=StringUtils.defaultIfEmpty(showXmlDeclaration,TRUE);
    prettyPrint=StringUtils.defaultIfEmpty(prettyPrint,TRUE);
    ValidateUtils.validateInputs(prettyPrint,showXmlDeclaration);
    final ConvertJsonToXmlInputs inputs=new ConvertJsonToXmlInputs.ConvertJsonToXmlInputsBuilder().withJson(json).withPrettyPrint(Boolean.parseBoolean(prettyPrint)).withShowXmlDeclaration(Boolean.parseBoolean(showXmlDeclaration)).withRootTagName(rootTagName).withDefaultJsonArrayItemName(defaultJsonArrayItemName).withNamespaces(namespacesUris,namespacesPrefixes,delimiter).withJsonArraysNames(jsonArraysNames,jsonArraysItemNames,delimiter).build();
    final ConvertJsonToXmlService converter=new ConvertJsonToXmlService();
    converter.setNamespaces(inputs.getNamespaces());
    converter.setJsonArrayItemNames(inputs.getArraysItemNames());
    converter.setJsonArrayItemName(inputs.getDefaultJsonArrayItemName());
    final String xml=converter.convertToXmlString(inputs);
    return getSuccessResultsMap(xml);
  }
 catch (  Exception e) {
    return getFailureResultsMap(e);
  }
}

private void initWord2Vec(String name) throws ConfigurationException, IOException, DaoException, InterruptedException {
  Config config=getMetricConfig(name).getConfig("generator");
  File model=Word2VecGenerator.getModelFile(config.getString("modelDir"),language);
  if (skipBuiltMetrics && model.isFile()) {
    return;
  }
  if (config.hasPath("prebuilt") && config.getBoolean("prebuilt")) {
    if (model.isFile()) {
      return;
    }
    File downloadPath=new File(localize(config.getString("binfile")));
    if (!downloadPath.isFile()) {
      FileDownloader downloader=new FileDownloader();
      downloader.download(new URL(localize(config.getString("url"))),downloadPath);
    }
    if (config.hasPath("languages") && !config.getStringList("languages").contains(language.getLangCode())) {
      throw new ConfigurationException("word2vec model " + downloadPath + " does not support language"+ language);
    }
    if (downloadPath.toString().toLowerCase().endsWith("gz")) {
      LOG.info("decompressing " + downloadPath + " to "+ model);
      File tmp=File.createTempFile("word2vec","bin");
      try {
        FileUtils.deleteQuietly(tmp);
        GZIPInputStream gz=new GZIPInputStream(new FileInputStream(downloadPath));
        FileUtils.copyInputStreamToFile(gz,tmp);
        gz.close();
        model.getParentFile().mkdirs();
        FileUtils.moveFile(tmp,model);
      }
  finally {
        FileUtils.deleteQuietly(tmp);
      }
    }
 else {
      FileUtils.copyFile(downloadPath,model);
    }
    return;
  }
  LinkProbabilityDao lpd=env.getComponent(LinkProbabilityDao.class,language);
  lpd.useCache(true);
  lpd.buildIfNecessary();
  String corpusName=config.getString("corpus");
  Corpus corpus=null;
  if (!corpusName.equals("NONE")) {
    corpus=env.getConfigurator().get(Corpus.class,config.getString("corpus"),"language",language.getLangCode());
    if (!corpus.exists()) {
      corpus.create();
    }
  }
  if (model.isFile() && (corpus == null || model.lastModified() > corpus.getCorpusFile().lastModified())) {
    return;
  }
  if (corpus == null) {
    throw new ConfigurationException("word2vec metric " + name + " cannot build or find model!"+ "configuration has no corpus, but model not found at "+ model+ ".");
  }
  Word2VecTrainer trainer=new Word2VecTrainer(env.getConfigurator().get(LocalPageDao.class),language);
  if (config.hasPath("dimensions")) {
    LOG.info("set number of dimensions to " + config.getInt("dimensions"));
    trainer.setLayer1Size(config.getInt("dimensions"));
  }
  if (config.hasPath("maxWords")) {
    LOG.info("set maxWords to " + config.getInt("maxWords"));
    trainer.setMaxWords(config.getInt("maxWords"));
  }
  if (config.hasPath("window")) {
    LOG.info("set window to " + config.getInt("maxWords"));
    trainer.setWindow(config.getInt("window"));
  }
  trainer.setKeepAllArticles(true);
  trainer.train(corpus.getDirectory());
  trainer.save(model);
}

@Override public DataTypeExpr visitData_type(Data_typeContext ctx){
  Predefined_typeContext predefined_type=ctx.predefined_type();
  DataTypeExpr typeDefinition=null;
  if (checkIfExist(predefined_type.character_string_type())) {
    Character_string_typeContext character_string_type=predefined_type.character_string_type();
    if ((checkIfExist(character_string_type.CHARACTER()) || checkIfExist(character_string_type.CHAR())) && !checkIfExist(character_string_type.VARYING())) {
      typeDefinition=new DataTypeExpr(Type.CHAR.name());
      if (character_string_type.type_length() != null) {
        typeDefinition.setLengthOrPrecision(Integer.parseInt(character_string_type.type_length().NUMBER().getText()));
      }
    }
 else     if (checkIfExist(character_string_type.VARCHAR()) || checkIfExist(character_string_type.VARYING())) {
      typeDefinition=new DataTypeExpr(Type.VARCHAR.name());
      if (character_string_type.type_length() != null) {
        typeDefinition.setLengthOrPrecision(Integer.parseInt(character_string_type.type_length().NUMBER().getText()));
      }
    }
 else     if (checkIfExist(character_string_type.TEXT())) {
      typeDefinition=new DataTypeExpr(Type.TEXT.name());
    }
  }
 else   if (checkIfExist(predefined_type.national_character_string_type())) {
    National_character_string_typeContext nchar_type=predefined_type.national_character_string_type();
    if ((checkIfExist(nchar_type.CHAR()) || checkIfExist(nchar_type.CHARACTER()) || checkIfExist(nchar_type.NCHAR()) && !checkIfExist(nchar_type.VARYING()))) {
      typeDefinition=new DataTypeExpr(Type.NCHAR.name());
    }
 else     if (checkIfExist(nchar_type.NVARCHAR()) || checkIfExist(nchar_type.VARYING())) {
      typeDefinition=new DataTypeExpr(Type.NVARCHAR.name());
    }
    if (checkIfExist(nchar_type.type_length())) {
      typeDefinition.setLengthOrPrecision(Integer.parseInt(nchar_type.type_length().NUMBER().getText()));
    }
  }
 else   if (checkIfExist(predefined_type.binary_large_object_string_type())) {
    Binary_large_object_string_typeContext blob_type=predefined_type.binary_large_object_string_type();
    typeDefinition=new DataTypeExpr(Type.BLOB.name());
    if (checkIfExist(blob_type.type_length())) {
      typeDefinition.setLengthOrPrecision(Integer.parseInt(blob_type.type_length().NUMBER().getText()));
    }
  }
 else   if (checkIfExist(predefined_type.numeric_type())) {
    if (checkIfExist(predefined_type.numeric_type().exact_numeric_type())) {
      Exact_numeric_typeContext exactType=predefined_type.numeric_type().exact_numeric_type();
      if (checkIfExist(exactType.TINYINT()) || checkIfExist(exactType.INT1())) {
        typeDefinition=new DataTypeExpr(Type.INT1.name());
      }
 else       if (checkIfExist(exactType.INT2()) || checkIfExist(exactType.SMALLINT())) {
        typeDefinition=new DataTypeExpr(Type.INT2.name());
      }
 else       if (checkIfExist(exactType.INT4()) || checkIfExist(exactType.INTEGER()) || checkIfExist(exactType.INT())) {
        typeDefinition=new DataTypeExpr(Type.INT4.name());
      }
 else       if (checkIfExist(exactType.INT8()) || checkIfExist(exactType.BIGINT())) {
        typeDefinition=new DataTypeExpr(Type.INT8.name());
      }
 else       if (checkIfExist(exactType.NUMERIC()) || checkIfExist(exactType.DECIMAL()) || checkIfExist(exactType.DEC())) {
        typeDefinition=new DataTypeExpr(Type.NUMERIC.name());
        if (checkIfExist(exactType.precision_param())) {
          typeDefinition.setLengthOrPrecision(Integer.parseInt(exactType.precision_param().precision.getText()));
          if (checkIfExist(exactType.precision_param().scale)) {
            typeDefinition.setScale(Integer.parseInt(exactType.precision_param().scale.getText()));
          }
        }
      }
    }
 else {
      Approximate_numeric_typeContext approximateType=predefined_type.numeric_type().approximate_numeric_type();
      if (checkIfExist(approximateType.FLOAT()) || checkIfExist(approximateType.FLOAT4()) || checkIfExist(approximateType.REAL())) {
        typeDefinition=new DataTypeExpr(Type.FLOAT4.name());
      }
 else       if (checkIfExist(approximateType.FLOAT8()) || checkIfExist(approximateType.DOUBLE())) {
        typeDefinition=new DataTypeExpr(Type.FLOAT8.name());
      }
    }
  }
 else   if (checkIfExist(predefined_type.boolean_type())) {
    typeDefinition=new DataTypeExpr(Type.BOOLEAN.name());
  }
 else   if (checkIfExist(predefined_type.datetime_type())) {
    Datetime_typeContext dateTimeType=predefined_type.datetime_type();
    if (checkIfExist(dateTimeType.DATE())) {
      typeDefinition=new DataTypeExpr(Type.DATE.name());
    }
 else     if (checkIfExist(dateTimeType.TIME(0))) {
      if (checkIfExist(dateTimeType.ZONE())) {
        typeDefinition=new DataTypeExpr(Type.TIMEZ.name());
      }
 else {
        typeDefinition=new DataTypeExpr(Type.TIME.name());
      }
    }
 else     if (checkIfExist(dateTimeType.TIMETZ())) {
      typeDefinition=new DataTypeExpr(Type.TIMEZ.name());
    }
 else     if (checkIfExist(dateTimeType.TIMESTAMP())) {
      if (checkIfExist(dateTimeType.ZONE())) {
        typeDefinition=new DataTypeExpr(Type.TIMESTAMPZ.name());
      }
 else {
        typeDefinition=new DataTypeExpr(Type.TIMESTAMP.name());
      }
    }
 else     if (checkIfExist(dateTimeType.TIMESTAMPTZ())) {
      typeDefinition=new DataTypeExpr(Type.TIMESTAMPZ.name());
    }
  }
 else   if (predefined_type.bit_type() != null) {
    Bit_typeContext bitType=predefined_type.bit_type();
    if (checkIfExist(bitType.VARBIT()) || checkIfExist(bitType.VARYING())) {
      typeDefinition=new DataTypeExpr(Type.VARBIT.name());
    }
 else {
      typeDefinition=new DataTypeExpr(Type.BIT.name());
    }
    if (checkIfExist(bitType.type_length())) {
      typeDefinition.setLengthOrPrecision(Integer.parseInt(bitType.type_length().NUMBER().getText()));
    }
  }
 else   if (checkIfExist(predefined_type.binary_type())) {
    Binary_typeContext binaryType=predefined_type.binary_type();
    if (checkIfExist(binaryType.VARBINARY()) || checkIfExist(binaryType.VARYING())) {
      typeDefinition=new DataTypeExpr(Type.VARBINARY.name());
    }
 else {
      typeDefinition=new DataTypeExpr(Type.BINARY.name());
    }
    if (checkIfExist(binaryType.type_length())) {
      typeDefinition.setLengthOrPrecision(Integer.parseInt(binaryType.type_length().NUMBER().getText()));
    }
  }
 else   if (checkIfExist(predefined_type.complex_type())) {
    Complex_typeContext complexType=predefined_type.complex_type();
    if (checkIfExist(complexType.array_type())) {
      DataTypeExpr elementType=visitData_type(complexType.array_type().data_type());
      typeDefinition=new DataTypeExpr(new DataTypeExpr.ArrayType(elementType));
    }
 else     if (checkIfExist(complexType.record_type())) {
      ColumnDefinition[] nestedRecordDefine=getDefinitions(complexType.record_type().table_elements());
      typeDefinition=new DataTypeExpr(new DataTypeExpr.RecordType(nestedRecordDefine));
    }
 else     if (checkIfExist(complexType.map_type())) {
      Map_typeContext mapTypeContext=complexType.map_type();
      typeDefinition=new DataTypeExpr(new MapType(visitData_type(mapTypeContext.key_type),visitData_type(mapTypeContext.value_type)));
    }
  }
 else {
    throw new TajoInternalError("Reached code points that shouldn't be reached");
  }
  return typeDefinition;
}

/** 
 * True bi-directional streaming. Processes requests as they come in. Begins streaming results immediately.
 */
@Override public StreamObserver<Messages.StreamingOutputCallRequest> fullDuplexCall(final StreamObserver<Messages.StreamingOutputCallResponse> responseObserver){
  final ResponseDispatcher dispatcher=new ResponseDispatcher(responseObserver);
  return new StreamObserver<StreamingOutputCallRequest>(){
    @Override public void onNext(    StreamingOutputCallRequest request){
      if (request.hasResponseStatus()) {
        dispatcher.cancel();
        dispatcher.onError(Status.fromCodeValue(request.getResponseStatus().getCode()).withDescription(request.getResponseStatus().getMessage()).asRuntimeException());
        return;
      }
      dispatcher.enqueue(toChunkQueue(request));
    }
    @Override public void onCompleted(){
      if (!dispatcher.isCancelled()) {
        dispatcher.completeInput();
      }
    }
    @Override public void onError(    Throwable cause){
      dispatcher.onError(cause);
    }
  }
;
}

