/** 
 * Gets all the edges of the graph.
 */
private static List<DiGraphEdge<Node,Branch>> getAllEdges(ControlFlowGraph<Node> cfg){
  List<DiGraphEdge<Node,Branch>> edges=new ArrayList<>();
  for (  DiGraphNode<Node,Branch> n : cfg.getDirectedGraphNodes()) {
    edges.addAll(cfg.getOutEdges(n.getValue()));
  }
  return edges;
}
/** 
 * Gets all the control flow edges from some node with the first token to some node with the second token.
 */
private static List<DiGraphEdge<Node,Branch>> getAllEdges(ControlFlowGraph<Node> cfg,Token startToken,Token endToken){
  List<DiGraphEdge<Node,Branch>> edges=getAllEdges(cfg);
  Iterator<DiGraphEdge<Node,Branch>> it=edges.iterator();
  while (it.hasNext()) {
    DiGraphEdge<Node,Branch> edge=it.next();
    Node startNode=edge.getSource().getValue();
    Node endNode=edge.getDestination().getValue();
    if (startNode == null || endNode == null || startNode.getToken() != startToken || endNode.getToken() != endToken) {
      it.remove();
    }
  }
  return edges;
}
/** 
 * Gets all the control flow edges of the given type from some node with the first token to some node with the second token.
 */
private static List<DiGraphEdge<Node,Branch>> getAllEdges(ControlFlowGraph<Node> cfg,Token startToken,Token endToken,Branch type){
  List<DiGraphEdge<Node,Branch>> edges=getAllEdges(cfg,startToken,endToken);
  edges.removeIf(elem -> type != elem.getValue());
  return edges;
}

