/** 
 * Save a project.
 * @param p the project
 * @param undo true if we are executing an undo
 * @throws Exception the exception
 */
public void saveProject(Project p,boolean undo) throws Exception {
  Integer pi=p.getParent();
  while (pi != null) {
    if (pi.intValue() == p.getKey())     throw new Warning(Resource.getResourceString("project_cycle"));
    Project par=TaskModel.getReference().getProject(pi);
    pi=par.getParent();
  }
  if (p.getKey() != -1) {
    for (    Task t : TaskModel.getReference().getTasks(p.getKey())) {
      if (p.getDueDate() != null && t.getDueDate() != null && !TaskModel.isClosed(t) && DateUtil.isAfter(t.getDueDate(),p.getDueDate())) {
        throw new Warning(Resource.getResourceString("projdd_warning") + ": " + t.getKey());
      }
    }
    for (    Project child : TaskModel.getReference().getSubProjects(p.getKey())) {
      if (p.getDueDate() != null && child.getDueDate() != null && !TaskModel.isClosed(child) && DateUtil.isAfter(child.getDueDate(),p.getDueDate())) {
        throw new Warning(Resource.getResourceString("projchild_warning") + ": " + child.getKey());
      }
    }
  }
  if (p.getParent() != null) {
    Project par=TaskModel.getReference().getProject(p.getParent().intValue());
    if (par != null) {
      if (p.getDueDate() != null && par.getDueDate() != null && DateUtil.isAfter(p.getDueDate(),par.getDueDate())) {
        throw new Warning(Resource.getResourceString("projpar_warning"));
      }
    }
  }
  if (p.getStatus().equals(Resource.getResourceString("CLOSED"))) {
    for (    Task pt : TaskModel.getReference().getTasks(p.getKey())) {
      if (!isClosed(pt)) {
        throw new Warning(Resource.getResourceString("close_proj_warn"));
      }
    }
    for (    Project pt : TaskModel.getReference().getProjects()) {
      if (!isClosed(pt) && pt.getParent() != null && pt.getParent().intValue() == p.getKey()) {
        throw new Warning(Resource.getResourceString("close_proj_warn"));
      }
    }
  }
  ChangeAction action=ChangeAction.ADD;
  if (p.getKey() <= 0) {
    if (!undo)     p.setKey(db_.nextProjectKey());
    db_.addProject(p);
    if (!undo) {
      Project t=getProject(p.getKey());
      UndoLog.getReference().addItem(ProjectUndoItem.recordAdd(t));
    }
  }
 else {
    if (!undo) {
      Project t=getProject(p.getKey());
      UndoLog.getReference().addItem(ProjectUndoItem.recordUpdate(t));
    }
    db_.updateProject(p);
    action=ChangeAction.CHANGE;
  }
  load_map();
  refreshListeners(new ChangeEvent(p,action));
}

