/** 
 * Deletes a node and its contents from the source file. If the node is a child of a block or top level statement, this will also delete the whitespace before the node.
 */
public Builder delete(Node n){
  return delete(n,true);
}
/** 
 * Deletes a node and its contents from the source file. 
 */
private Builder delete(Node n,boolean deleteWhitespaceBefore){
  int startPosition=getStartPositionForNodeConsideringComments(n);
  int startOffsetWithoutComments=n.getSourceOffset();
  int length=(startOffsetWithoutComments - startPosition) + n.getLength();
  if (n.getNext() != null && NodeUtil.getBestJSDocInfo(n.getNext()) == null && n.getNext().getNonJSDocComment() == null) {
    length=n.getNext().getSourceOffset() - startPosition;
  }
  if ((n.isName() && NodeUtil.isNameDeclaration(n.getParent())) || n.isStringKey()) {
    if (n.getNext() != null) {
      length=getStartPositionForNodeConsideringComments(n.getNext()) - startPosition;
    }
 else     if (n.hasChildren()) {
      Node child=n.getFirstChild();
      length=(child.getSourceOffset() + child.getLength()) - startPosition;
    }
    if (n.getParent().getLastChild() == n && n != n.getParent().getFirstChild()) {
      Node previousSibling=n.getPrevious();
      if (previousSibling.hasChildren()) {
        Node child=previousSibling.getFirstChild();
        int startPositionDiff=startPosition - (child.getSourceOffset() + child.getLength());
        startPosition-=startPositionDiff;
        length+=startPositionDiff;
      }
 else {
        int startPositionDiff=startPosition - (previousSibling.getSourceOffset() + previousSibling.getLength());
        startPosition-=startPositionDiff;
        length+=startPositionDiff;
      }
    }
  }
  Node parent=n.getParent();
  if (deleteWhitespaceBefore && parent != null && (parent.isScript() || parent.isBlock())) {
    Node previousSibling=n.getPrevious();
    if (previousSibling != null) {
      int previousSiblingEndPosition=previousSibling.getSourceOffset() + previousSibling.getLength();
      length+=(startPosition - previousSiblingEndPosition);
      startPosition=previousSiblingEndPosition;
    }
  }
  replacements.put(n.getSourceFileName(),CodeReplacement.create(startPosition,length,""));
  return this;
}

/** 
 * Produce a string in double quotes with backslash sequences in all the right places. A backslash will be inserted within </, producing <\/, allowing JSON text to be delivered in HTML. In JSON text, a string cannot contain a control character or an unescaped quote or backslash.
 * @param string A String
 * @return A String correctly formatted for insertion in a JSON text.
 */
public static String quote(String string){
  StringWriter sw=new StringWriter();
synchronized (sw.getBuffer()) {
    try {
      return quote(string,sw).toString();
    }
 catch (    IOException ignored) {
      return "";
    }
  }
}
public static Writer quote(String string,Writer w) throws IOException {
  if (string == null || string.length() == 0) {
    w.write("\"\"");
    return w;
  }
  char b;
  char c=0;
  String hhhh;
  int i;
  int len=string.length();
  w.write('"');
  for (i=0; i < len; i+=1) {
    b=c;
    c=string.charAt(i);
switch (c) {
case '\\':
case '"':
      w.write('\\');
    w.write(c);
  break;
case '/':
if (b == '<') {
  w.write('\\');
}
w.write(c);
break;
case '\b':
w.write("\\b");
break;
case '\t':
w.write("\\t");
break;
case '\n':
w.write("\\n");
break;
case '\f':
w.write("\\f");
break;
case '\r':
w.write("\\r");
break;
default :
if (c < ' ' || (c >= '\u0080' && c < '\u00a0') || (c >= '\u2000' && c < '\u2100')) {
w.write("\\u");
hhhh=Integer.toHexString(c);
w.write("0000",0,4 - hhhh.length());
w.write(hhhh);
}
 else {
w.write(c);
}
}
}
w.write('"');
return w;
}

