/** 
 * Walks up this class's hierarchy to find the first class targetted by the specified mixin. This is used during mixin application to translate a mixin reference to a "real class" reference <em>in the context of <b>this </b> class</em>.
 * @param mixin Mixin class to search for
 * @return corresponding (target) class for the specified mixin or null ifno corresponding mixin was found
 */
ClassInfo findCorrespondingType(ClassInfo mixin){
  if (mixin == null || !mixin.isMixin || this.isMixin) {
    return null;
  }
  ClassInfo correspondingType=this.correspondingTypes.get(mixin);
  if (correspondingType == null) {
    correspondingType=this.findSuperTypeForMixin(mixin);
    this.correspondingTypes.put(mixin,correspondingType);
  }
  return correspondingType;
}

protected void copySchemaInfo(StoreObject sourceStore){
  if (sourceStore.getSchema().getSchemaName() != null && !sourceStore.getSchema().getSchemaName().isEmpty()) {
    if (targetStore.getSchema().getSchemaName() != null && !targetStore.getSchema().getSchemaName().isEmpty() && !targetStore.getSchema().getSchemaName().equalsIgnoreCase(sourceStore.getSchema().getSchemaName())) {
      throw new TajoInternalError("different schema names are specified. One is " + sourceStore.getSchema().getSchemaName() + " and other is "+ targetStore.getSchema().getSchemaName());
    }
    if (targetStore.getSchema().getSchemaName() == null || targetStore.getSchema().getSchemaName().isEmpty()) {
      targetStore.getSchema().setSchemaName(sourceStore.getSchema().getSchemaName());
    }
  }
  if (sourceStore.getSchema().getVersion() > -1 && targetStore.getSchema().getVersion() < sourceStore.getSchema().getVersion()) {
    targetStore.getSchema().setVersion(sourceStore.getSchema().getVersion());
  }
}

