public ContainerBuilder addRestart(String restart){
  RestartPolicy restartPolicy=new RestartPolicy();
  if (restart.startsWith("on-failure")) {
    String[] element=restart.split(":");
    if (element.length == 1) {
      restartPolicy.setName(restart);
      restartPolicy.setMaximumRetryCount(0);
    }
 else {
      if (element.length == 2) {
        restartPolicy.setName(element[0]);
        restartPolicy.setMaximumRetryCount(Integer.parseInt(element[1]));
      }
 else {
        throw new IllegalArgumentException("on-failure restart should be on-failure or with optional retries on-failure:retries");
      }
    }
  }
 else {
    restartPolicy.setName(restart);
  }
  configuration.setRestartPolicy(restartPolicy);
  return this;
}

/** 
 * Calls TrainedModel.evaluateModel method within a Thread on implementing subclasses to generate a prediction for the provided snapshot. When a prediction becomes available, transmits the prediction through the rest of the data processing pipeline.
 * @see edu.northwestern.cbits.purple_robot_manager.models.Model#predict(android.content.Context,java.util.Map)
 */
@Override public void predict(final Context context,final Map<String,Object> snapshot){
  if (this._inited == false || this.enabled(context) == false)   return;
  long now=System.currentTimeMillis();
  if (now - this._lastCheck < 1000) {
    return;
  }
  this._lastCheck=now;
  for (  String key : this._featureMap.keySet()) {
    String newKey=this._featureMap.get(key);
    if (snapshot.get(key) == null) {
    }
 else {
      snapshot.put(newKey,snapshot.get(key));
    }
  }
  final TrainedModel me=this;
  Runnable r=new Runnable(){
    @Override @SuppressWarnings("unchecked") public void run(){
      Object value=me.evaluateModel(context,snapshot);
      if (value == null) {
      }
 else       if (value instanceof Map<?,?>) {
        Map<String,Object> map=(Map<String,Object>)value;
        if (map.get(LeafNode.PREDICTION) != null)         me.transmitPrediction(context,map.get(LeafNode.PREDICTION).toString(),(Double)map.get(LeafNode.ACCURACY),map);
      }
 else       if (value instanceof Double) {
        Double doubleValue=(Double)value;
        me.transmitPrediction(context,doubleValue,me._accuracy);
      }
 else       me.transmitPrediction(context,value.toString(),me._accuracy);
    }
  }
;
  Thread t=new Thread(r);
  t.start();
}

