/** 
 * Returns the redirection URL with the appended SAML2 Request message
 * @param request SAML 2 request
 * @return redirectionUrl
 */
public String buildRedirectRequest(HttpServletRequest request,boolean isLogout) throws SSOAgentException {
  RequestAbstractType requestMessage=null;
  if (!isLogout) {
    requestMessage=buildAuthnRequest(request);
  }
 else {
    LoggedInSessionBean sessionBean=(LoggedInSessionBean)request.getSession(false).getAttribute(SSOAgentConstants.SESSION_BEAN_NAME);
    if (sessionBean != null) {
      requestMessage=buildLogoutRequest(sessionBean.getSAML2SSO().getSubjectId(),sessionBean.getSAML2SSO().getSessionIndex());
    }
 else {
      throw new SSOAgentException("SLO Request can not be built. SSO Session is NULL");
    }
  }
  String idpUrl=null;
  String encodedRequestMessage=encodeRequestMessage(requestMessage,SAMLConstants.SAML2_REDIRECT_BINDING_URI);
  StringBuilder httpQueryString=new StringBuilder(SSOAgentConstants.SAML2SSO.HTTP_POST_PARAM_SAML2_AUTH_REQ + "=" + encodedRequestMessage);
  String relayState=ssoAgentConfig.getSAML2().getRelayState();
  if (relayState != null) {
    try {
      httpQueryString.append("&" + RelayState.DEFAULT_ELEMENT_LOCAL_NAME + "="+ URLEncoder.encode(relayState,"UTF-8").trim());
    }
 catch (    UnsupportedEncodingException e) {
      throw new SSOAgentException("Error occurred while URLEncoding " + RelayState.DEFAULT_ELEMENT_LOCAL_NAME,e);
    }
  }
  if (ssoAgentConfig.getSAML2().isRequestSigned()) {
    SSOAgentUtils.addDeflateSignatureToHTTPQueryString(httpQueryString,new X509CredentialImpl(ssoAgentConfig.getSAML2().getSSOAgentX509Credential()));
  }
  if (ssoAgentConfig.getQueryParams() != null && !ssoAgentConfig.getQueryParams().isEmpty()) {
    StringBuilder builder=new StringBuilder();
    for (    Map.Entry<String,String[]> entry : ssoAgentConfig.getQueryParams().entrySet()) {
      if (entry.getKey() != null && entry.getValue() != null && entry.getValue().length > 0) {
        for (        String param : entry.getValue()) {
          builder.append("&").append(entry.getKey()).append("=").append(param);
        }
      }
    }
    httpQueryString.append(builder);
  }
  if (ssoAgentConfig.getSAML2().getIdPURL().indexOf("?") > -1) {
    idpUrl=ssoAgentConfig.getSAML2().getIdPURL().concat("&").concat(httpQueryString.toString());
  }
 else {
    idpUrl=ssoAgentConfig.getSAML2().getIdPURL().concat("?").concat(httpQueryString.toString());
  }
  return idpUrl;
}

