 */
void executeVAR(int opcode,@Nonnegative int varIndex){
switch (opcode) {
case ILOAD:
    push(INTEGER);
  break;
case LLOAD:
push(LONG);
push(TOP);
break;
case FLOAD:
push(FLOAT);
break;
case DLOAD:
push(DOUBLE);
push(TOP);
break;
case ALOAD:
push(get(varIndex));
break;
case ISTORE:
case FSTORE:
case ASTORE:
executeSingleWordStore(varIndex);
break;
case LSTORE:
case DSTORE:
executeDoubleWordStore(varIndex);
}
}

