private static String checkTypeConsistency(String attribute,Type attrType,CompValueType type){
  boolean pass;
  String error=null;
  if (Type.STRING.equals(attrType) || Type.REFERENCE.equals(attrType) || Type.DATETIME.equals(attrType))   pass=type.equals(CompValueType.STRING);
 else   if (Type.INTEGER.equals(attrType) || Type.DECIMAL.equals(attrType))   pass=type.equals(CompValueType.NUMBER);
 else   if (Type.BOOLEAN.equals(attrType))   pass=type.equals(CompValueType.BOOLEAN);
 else {
    error=String.format("Filtering over attributes of type '%s' is not supported",attrType);
    log.error("checkTypeConsistency. {}",error);
    return error;
  }
  if (!pass) {
    error=getTypeInconsistencyError(attribute,attrType.toString(),type.toString());
    log.error("checkTypeConsistency. {}",error);
  }
  return error;
}

