private void positionAtFirstRecord(FSDataInputStream stream) throws IOException {
  if (start > 0) {
    stream.seek(start);
    LineReader reader=new LineReader(stream);
    int bytesRead=0;
    do {
      bytesRead=reader.readLine(buffer,(int)Math.min(MAX_LINE_LENGTH,end - start));
      if (bytesRead > 0 && (buffer.getLength() <= 0 || buffer.getBytes()[0] != '@'))       start+=bytesRead;
 else {
        long backtrackPosition=start + bytesRead;
        bytesRead=reader.readLine(buffer,(int)Math.min(MAX_LINE_LENGTH,end - start));
        bytesRead=reader.readLine(buffer,(int)Math.min(MAX_LINE_LENGTH,end - start));
        if (bytesRead > 0 && buffer.getLength() > 0 && buffer.getBytes()[0] == '+')         break;
 else {
          start=backtrackPosition;
          stream.seek(start);
          reader=new LineReader(stream);
        }
      }
    }
 while (bytesRead > 0);
    stream.seek(start);
  }
  pos=start;
}

