private int peekNumber() throws IOException {
  char[] buffer=this.buffer;
  int p=pos;
  int l=limit;
  long value=0;
  boolean negative=false;
  boolean fitsInLong=true;
  int last=NUMBER_CHAR_NONE;
  int i=0;
  charactersOfNumber:   for (; true; i++) {
    if (p + i == l) {
      if (i == buffer.length) {
        return PEEKED_NONE;
      }
      if (!fillBuffer(i + 1)) {
        break;
      }
      p=pos;
      l=limit;
    }
    char c=buffer[p + i];
switch (c) {
case '-':
      if (last == NUMBER_CHAR_NONE) {
        negative=true;
        last=NUMBER_CHAR_SIGN;
        continue;
      }
 else       if (last == NUMBER_CHAR_EXP_E) {
        last=NUMBER_CHAR_EXP_SIGN;
        continue;
      }
    return PEEKED_NONE;
case '+':
  if (last == NUMBER_CHAR_EXP_E) {
    last=NUMBER_CHAR_EXP_SIGN;
    continue;
  }
return PEEKED_NONE;
case 'e':
case 'E':
if (last == NUMBER_CHAR_DIGIT || last == NUMBER_CHAR_FRACTION_DIGIT) {
last=NUMBER_CHAR_EXP_E;
continue;
}
return PEEKED_NONE;
case '.':
if (last == NUMBER_CHAR_DIGIT) {
last=NUMBER_CHAR_DECIMAL;
continue;
}
return PEEKED_NONE;
default :
if (c < '0' || c > '9') {
if (!isLiteral(c)) {
break charactersOfNumber;
}
return PEEKED_NONE;
}
if (last == NUMBER_CHAR_SIGN || last == NUMBER_CHAR_NONE) {
value=-(c - '0');
last=NUMBER_CHAR_DIGIT;
}
 else if (last == NUMBER_CHAR_DIGIT) {
if (value == 0) {
return PEEKED_NONE;
}
long newValue=value * 10 - (c - '0');
fitsInLong&=value > MIN_INCOMPLETE_INTEGER || (value == MIN_INCOMPLETE_INTEGER && newValue < value);
value=newValue;
}
 else if (last == NUMBER_CHAR_DECIMAL) {
last=NUMBER_CHAR_FRACTION_DIGIT;
}
 else if (last == NUMBER_CHAR_EXP_E || last == NUMBER_CHAR_EXP_SIGN) {
last=NUMBER_CHAR_EXP_DIGIT;
}
}
}
if (last == NUMBER_CHAR_DIGIT && fitsInLong && (value != Long.MIN_VALUE || negative)) {
peekedLong=negative ? value : -value;
pos+=i;
return peeked=PEEKED_LONG;
}
 else if (last == NUMBER_CHAR_DIGIT || last == NUMBER_CHAR_FRACTION_DIGIT || last == NUMBER_CHAR_EXP_DIGIT) {
peekedNumberLength=i;
return peeked=PEEKED_NUMBER;
}
 else {
return PEEKED_NONE;
}
}

/** 
 * Computes 1D forward DFT of real data leaving the result in <code>a</code> . This method computes the full real forward transform, i.e. you will get the same result as from <code>complexForward</code> called with all imaginary parts equal 0. Because the result is stored in <code>a</code>, the size of the input array must greater or equal 2*n, with only the first n elements filled with real data. To get back the original data, use <code>complexInverse</code> on the output of this method.
 * @param a data to transform
 */
public void realForwardFull(float[] a){
  realForwardFull(a,0);
}
/** 
