/** 
 * Computes 1D forward DFT of real data leaving the result in <code>a</code> . This method computes the full real forward transform, i.e. you will get the same result as from <code>complexForward</code> called with all imaginary part equal 0. Because the result is stored in <code>a</code>, the size of the input array must greater or equal 2*n, with only the first n elements filled with real data. To get back the original data, use <code>complexInverse</code> on the output of this method.
 * @param a    data to transform
 * @param offa index of the first element in array <code>a</code>
 */
public void realForwardFull(final float[] a,final int offa){
  if (useLargeArrays) {
    realForwardFull(new FloatLargeArray(a),offa);
  }
 else {
    final int twon=2 * n;
switch (plan) {
case SPLIT_RADIX:
      realForward(a,offa);
    int nthreads=ConcurrencyUtils.getNumberOfThreads();
  if ((nthreads > 1) && (n / 2 > CommonUtils.getThreadsBeginN_1D_FFT_2Threads())) {
    Future<?>[] futures=new Future[nthreads];
    int k=n / 2 / nthreads;
    for (int i=0; i < nthreads; i++) {
      final int firstIdx=i * k;
      final int lastIdx=(i == (nthreads - 1)) ? n / 2 : firstIdx + k;
      futures[i]=ConcurrencyUtils.submit(new Runnable(){
        public void run(){
          int idx1, idx2;
          for (int k=firstIdx; k < lastIdx; k++) {
            idx1=2 * k;
            idx2=offa + ((twon - idx1) % twon);
            a[idx2]=a[offa + idx1];
            a[idx2 + 1]=-a[offa + idx1 + 1];
          }
        }
      }
);
    }
    try {
      ConcurrencyUtils.waitForCompletion(futures);
    }
 catch (    InterruptedException ex) {
      Logger.getLogger(FloatFFT_1D.class.getName()).log(Level.SEVERE,null,ex);
    }
catch (    ExecutionException ex) {
      Logger.getLogger(FloatFFT_1D.class.getName()).log(Level.SEVERE,null,ex);
    }
  }
 else {
    int idx1, idx2;
    for (int k=0; k < n / 2; k++) {
      idx1=2 * k;
      idx2=offa + ((twon - idx1) % twon);
      a[idx2]=a[offa + idx1];
      a[idx2 + 1]=-a[offa + idx1 + 1];
    }
  }
a[offa + n]=-a[offa + 1];
a[offa + 1]=0;
break;
case MIXED_RADIX:
rfftf(a,offa);
int m;
if (n % 2 == 0) {
m=n / 2;
}
 else {
m=(n + 1) / 2;
}
for (int k=1; k < m; k++) {
int idx1=offa + twon - 2 * k;
int idx2=offa + 2 * k;
a[idx1 + 1]=-a[idx2];
a[idx1]=a[idx2 - 1];
}
for (int k=1; k < n; k++) {
int idx=offa + n - k;
float tmp=a[idx + 1];
a[idx + 1]=a[idx];
a[idx]=tmp;
}
a[offa + 1]=0;
break;
case BLUESTEIN:
bluestein_real_full(a,offa,-1);
break;
}
}
}
/** 
 * Computes 1D forward DFT of real data leaving the result in <code>a</code> . This method computes the full real forward transform, i.e. you will get the same result as from <code>complexForward</code> called with all imaginary part equal 0. Because the result is stored in <code>a</code>, the size of the input array must greater or equal 2*n, with only the first n elements filled with real data. To get back the original data, use <code>complexInverse</code> on the output of this method.
 * @param a    data to transform
 * @param offa index of the first element in array <code>a</code>
 */
public void realForwardFull(final FloatLargeArray a,final long offa){
  if (!useLargeArrays) {
    if (!a.isLarge() && !a.isConstant() && offa < Integer.MAX_VALUE) {
      realForwardFull(a.getData(),(int)offa);
    }
 else {
      throw new IllegalArgumentException("The data array is too big.");
    }
  }
 else {
    final long twon=2 * nl;
switch (plan) {
case SPLIT_RADIX:
      realForward(a,offa);
    int nthreads=ConcurrencyUtils.getNumberOfThreads();
  if ((nthreads > 1) && (nl / 2 > CommonUtils.getThreadsBeginN_1D_FFT_2Threads())) {
    Future<?>[] futures=new Future[nthreads];
    long k=nl / 2 / nthreads;
    for (int i=0; i < nthreads; i++) {
      final long firstIdx=i * k;
      final long lastIdx=(i == (nthreads - 1)) ? nl / 2 : firstIdx + k;
      futures[i]=ConcurrencyUtils.submit(new Runnable(){
        public void run(){
          long idx1, idx2;
          for (long k=firstIdx; k < lastIdx; k++) {
            idx1=2 * k;
            idx2=offa + ((twon - idx1) % twon);
            a.setFloat(idx2,a.getFloat(offa + idx1));
            a.setFloat(idx2 + 1,-a.getFloat(offa + idx1 + 1));
          }
        }
      }
);
    }
    try {
      ConcurrencyUtils.waitForCompletion(futures);
    }
 catch (    InterruptedException ex) {
      Logger.getLogger(FloatFFT_1D.class.getName()).log(Level.SEVERE,null,ex);
    }
catch (    ExecutionException ex) {
      Logger.getLogger(FloatFFT_1D.class.getName()).log(Level.SEVERE,null,ex);
    }
  }
 else {
    long idx1, idx2;
    for (long k=0; k < nl / 2; k++) {
      idx1=2 * k;
      idx2=offa + ((twon - idx1) % twon);
      a.setFloat(idx2,a.getFloat(offa + idx1));
      a.setFloat(idx2 + 1,-a.getFloat(offa + idx1 + 1));
    }
  }
a.setFloat(offa + nl,-a.getFloat(offa + 1));
a.setFloat(offa + 1,0);
break;
case MIXED_RADIX:
rfftf(a,offa);
long m;
if (nl % 2 == 0) {
m=nl / 2;
}
 else {
m=(nl + 1) / 2;
}
for (long k=1; k < m; k++) {
long idx1=offa + twon - 2 * k;
long idx2=offa + 2 * k;
a.setFloat(idx1 + 1,-a.getFloat(idx2));
a.setFloat(idx1,a.getFloat(idx2 - 1));
}
for (long k=1; k < nl; k++) {
long idx=offa + nl - k;
float tmp=a.getFloat(idx + 1);
a.setFloat(idx + 1,a.getFloat(idx));
a.setFloat(idx,tmp);
}
a.setFloat(offa + 1,0);
break;
case BLUESTEIN:
bluestein_real_full(a,offa,-1);
break;
}
}
