private void nextElement(){
  for (; ; ) {
    if (nextOverlayEntry == null && overlayIterator.hasNext())     nextOverlayEntry=overlayIterator.next();
    if (nextDiskIndexEntry == null && diskIndexIterator != null && diskIndexIterator.hasNext())     nextDiskIndexEntry=diskIndexIterator.next();
    if (nextOverlayEntry != null && nextDiskIndexEntry != null && comp.compare(nextDiskIndexEntry.getKey(),nextOverlayEntry.getKey()) == 0) {
      if (nextDiskIndexEntry.getValue().getReusableBuf() != null)       BufferPool.free(nextDiskIndexEntry.getValue().getReusableBuf());
      if (diskIndexIterator.hasNext())       nextDiskIndexEntry=diskIndexIterator.next();
 else       nextDiskIndexEntry=null;
    }
    if (nextDiskIndexEntry == null && nextOverlayEntry == null) {
      nextEntry=null;
      return;
    }
    if (ascending) {
      if (nextDiskIndexEntry == null) {
        nextEntry=InternalBufferUtil.cast(nextOverlayEntry);
        nextOverlayEntry=null;
      }
 else       if (nextOverlayEntry == null) {
        nextEntry=InternalBufferUtil.cast(nextDiskIndexEntry);
        nextDiskIndexEntry=null;
      }
 else       if (comp.compare(nextDiskIndexEntry.getKey(),nextOverlayEntry.getKey()) < 0) {
        nextEntry=InternalBufferUtil.cast(nextDiskIndexEntry);
        nextDiskIndexEntry=null;
      }
 else {
        nextEntry=InternalBufferUtil.cast(nextOverlayEntry);
        nextOverlayEntry=null;
      }
    }
 else {
      if (nextDiskIndexEntry == null) {
        nextEntry=InternalBufferUtil.cast(nextOverlayEntry);
        nextOverlayEntry=null;
      }
 else       if (nextOverlayEntry == null) {
        nextEntry=InternalBufferUtil.cast(nextDiskIndexEntry);
        nextDiskIndexEntry=null;
      }
 else       if (comp.compare(nextDiskIndexEntry.getKey(),nextOverlayEntry.getKey()) > 0) {
        nextEntry=InternalBufferUtil.cast(nextDiskIndexEntry);
        nextDiskIndexEntry=null;
      }
 else {
        InternalBufferUtil.cast(nextOverlayEntry);
        nextOverlayEntry=null;
      }
    }
    assert (nextEntry != null);
    if (nullValue == null || nextEntry.getValue() != nullValue)     return;
  }
}

private TraceId populateTraceIdFromHeaders(TraceContext traceContext,org.apache.kafka.common.header.Headers headers){
  String transactionId=null;
  String spanID=null;
  String parentSpanID=null;
  String flags=null;
  for (  org.apache.kafka.common.header.Header header : headers.toArray()) {
    if (header.key().equals(Header.HTTP_TRACE_ID.toString())) {
      transactionId=new String(header.value(),KafkaConstants.DEFAULT_PINPOINT_HEADER_CHARSET);
    }
 else     if (header.key().equals(Header.HTTP_PARENT_SPAN_ID.toString())) {
      parentSpanID=new String(header.value(),KafkaConstants.DEFAULT_PINPOINT_HEADER_CHARSET);
    }
 else     if (header.key().equals(Header.HTTP_SPAN_ID.toString())) {
      spanID=new String(header.value(),KafkaConstants.DEFAULT_PINPOINT_HEADER_CHARSET);
    }
 else     if (header.key().equals(Header.HTTP_FLAGS.toString())) {
      flags=new String(header.value(),KafkaConstants.DEFAULT_PINPOINT_HEADER_CHARSET);
    }
  }
  if (transactionId == null || spanID == null || parentSpanID == null || flags == null) {
    return null;
  }
  TraceId traceId=traceContext.createTraceId(transactionId,Long.parseLong(parentSpanID),Long.parseLong(spanID),Short.parseShort(flags));
  return traceId;
}

