@HLEFunction(nid=0x8B7B220F,version=150) public int sceNetInetSocket(int domain,int type,int protocol){
  if (log.isDebugEnabled()) {
    log.debug(String.format("sceNetInetSocket domain=0x%X, type=0x%X(%s), protocol=0x%X",domain,type,getSocketTypeNameString(type),protocol));
  }
  if (domain != AF_INET) {
    log.warn(String.format("sceNetInetSocket unsupported domain=0x%X, type=0x%X(%s), protocol=0x%X",domain,type,getSocketTypeNameString(type),protocol));
    return -1;
  }
  if (type != SOCK_DGRAM && type != SOCK_STREAM && type != SOCK_RAW && type != SOCK_DGRAM_UNKNOWN_6 && type != SOCK_STREAM_UNKNOWN_10) {
    log.warn(String.format("sceNetInetSocket unsupported type=0x%X(%s), domain=0x%X, protocol=0x%X",type,getSocketTypeNameString(type),domain,protocol));
    return -1;
  }
  pspInetSocket inetSocket=createSocket(type,protocol);
  if (log.isDebugEnabled()) {
    log.debug(String.format("sceNetInetSocket created socket=0x%X",inetSocket.getUid()));
  }
  return inetSocket.getUid();
}

public static String decode(String s){
  return new String(decode(s.getBytes()));
}
public static byte[] decode(byte[] bytes){
  int paddingCount=0;
  int realLength=0;
  for (int i=bytes.length - 1; i >= 0; i--) {
    if (bytes[i] > ' ') {
      realLength++;
    }
    if (bytes[i] == '=') {
      paddingCount++;
    }
  }
  if (realLength % 4 != 0) {
    throw new IllegalArgumentException("Incorrect length " + realLength + ". Must be a multiple of 4");
  }
  final byte[] out=new byte[realLength / 4 * 3 - paddingCount];
  final byte[] t=new byte[4];
  int outIndex=0;
  int index=0;
  t[0]=t[1]=t[2]=t[3]='=';
  for (  byte c : bytes) {
    if (c > ' ') {
      t[index++]=c;
    }
    if (index == 4) {
      outIndex+=decode(out,outIndex,t[0],t[1],t[2],t[3]);
      index=0;
      t[0]=t[1]=t[2]=t[3]='=';
    }
  }
  if (index > 0) {
    decode(out,outIndex,t[0],t[1],t[2],t[3]);
  }
  return out;
}
private static int decode(byte[] output,int outIndex,byte a,byte b,byte c,byte d){
  byte da=decodeTable[a];
  byte db=decodeTable[b];
  byte dc=decodeTable[c];
  byte dd=decodeTable[d];
  if ((da == -1) || (db == -1) || ((dc == -1) && (c != '='))|| ((dd == -1) && (d != '='))) {
    throw new IllegalArgumentException("Invalid character [" + (a & 0xFF) + ", "+ (b & 0xFF)+ ", "+ (c & 0xFF)+ ", "+ (d & 0xFF)+ "]");
  }
  output[outIndex++]=(byte)((da << 2) | db >>> 4);
  if (c == '=') {
    return 1;
  }
  output[outIndex++]=(byte)((db << 4) | dc >>> 2);
  if (d == '=') {
    return 2;
  }
  output[outIndex]=(byte)((dc << 6) | dd);
  return 3;
}

