 */
@SuppressWarnings("null") private static Object parse(final Class<?> type,final Object obj){
  final String str=obj == null ? null : obj.toString();
  if (type.isInstance(obj)) {
    return obj;
  }
 else   if (!type.isPrimitive() && !type.equals(String.class) && (obj == null || "NULL".equalsIgnoreCase(str))) {
    return null;
  }
 else   if (type.equals(String.class)) {
    return str;
  }
 else   if ((type.equals(Byte.class) || type.equals(Byte.TYPE) || type.equals(Short.class)|| type.equals(Short.TYPE)|| type.equals(Integer.class)|| type.equals(Integer.TYPE)|| type.equals(Long.class)|| type.equals(Long.TYPE)|| type.equals(Float.class)|| type.equals(Float.TYPE)|| type.equals(Double.class)|| type.equals(Double.TYPE)) && (obj instanceof Number || obj != null && Type.isLongString(str) || obj != null && Type.isDoubleString(str))) {
    Number num=null;
    if (obj instanceof Number) {
      num=(Number)obj;
    }
 else {
      try {
        if (Type.isLongString(str)) {
          num=new Long(Long.parseLong(str));
        }
 else {
          num=new Double(str);
        }
      }
 catch (      final NumberFormatException exception) {
        num=Type.parseHexadecimal(str.substring(2));
      }
    }
    if (type.equals(Byte.class) || type.equals(Byte.TYPE)) {
      return new Byte(num.byteValue());
    }
 else     if (type.equals(Short.class) || type.equals(Short.TYPE)) {
      return new Short(num.shortValue());
    }
 else     if (type.equals(Integer.class) || type.equals(Integer.TYPE)) {
      return new Integer(num.intValue());
    }
 else     if (type.equals(Long.class) || type.equals(Long.TYPE)) {
      return new Long(num.longValue());
    }
 else     if (type.equals(Float.class) || type.equals(Float.TYPE)) {
      return new Float(num.floatValue());
    }
 else {
      return new Double(num.doubleValue());
    }
  }
 else   if (type.equals(Boolean.class) || type.equals(Boolean.TYPE)) {
    if ("TRUE".equalsIgnoreCase(str)) {
      return new Boolean(true);
    }
 else     if ("FALSE".equalsIgnoreCase(str)) {
      return new Boolean(false);
    }
  }
 else   if ((type.equals(Character.class) || type.equals(Character.TYPE)) && obj != null) {
    if (str.length() == 1) {
      return new Character(str.charAt(0));
    }
 else     if (Type.isUnicodeEscape(str)) {
      return new Character((char)Type.parseHexadecimal(str.substring(2)).intValue());
    }
  }
  throw new IllegalArgumentException();
}

/** 
 * Computes the 3D forward DST (DST-II) leaving the result in <code>a</code> . The data is stored in 1D array addressed in slice-major, then row-major, then column-major, in order of significance, i.e. the element (i,j,k) of 3D array x[slices][rows][columns] is stored in a[i*sliceStride + j*rowStride + k], where sliceStride = rows * columns and rowStride = columns.
 * @param a     data to transform
 * @param scale if true then scaling is performed
 */
public void forward(final float[] a,final boolean scale){
  int nthreads=ConcurrencyUtils.getNumberOfThreads();
  if (isPowerOfTwo) {
    if ((nthreads > 1) && useThreads) {
      ddxt3da_subth(-1,a,scale);
      ddxt3db_subth(-1,a,scale);
    }
 else {
      ddxt3da_sub(-1,a,scale);
      ddxt3db_sub(-1,a,scale);
    }
  }
 else   if ((nthreads > 1) && useThreads && (slices >= nthreads)&& (rows >= nthreads)&& (columns >= nthreads)) {
    Future<?>[] futures=new Future[nthreads];
    int p=slices / nthreads;
    for (int l=0; l < nthreads; l++) {
      final int firstSlice=l * p;
      final int lastSlice=(l == (nthreads - 1)) ? slices : firstSlice + p;
      futures[l]=ConcurrencyUtils.submit(new Runnable(){
        public void run(){
          for (int s=firstSlice; s < lastSlice; s++) {
            int idx1=s * sliceStride;
            for (int r=0; r < rows; r++) {
              dstColumns.forward(a,idx1 + r * rowStride,scale);
            }
          }
        }
      }
);
    }
    try {
      ConcurrencyUtils.waitForCompletion(futures);
    }
 catch (    InterruptedException ex) {
      Logger.getLogger(FloatDST_3D.class.getName()).log(Level.SEVERE,null,ex);
    }
catch (    ExecutionException ex) {
      Logger.getLogger(FloatDST_3D.class.getName()).log(Level.SEVERE,null,ex);
    }
    for (int l=0; l < nthreads; l++) {
      final int firstSlice=l * p;
      final int lastSlice=(l == (nthreads - 1)) ? slices : firstSlice + p;
      futures[l]=ConcurrencyUtils.submit(new Runnable(){
        public void run(){
          float[] temp=new float[rows];
          for (int s=firstSlice; s < lastSlice; s++) {
            int idx1=s * sliceStride;
            for (int c=0; c < columns; c++) {
