private Future<Void> submitAsyncUpdateImpl(Repository repository,String ref,int delayMs,boolean reindex){
  RepositorySettings repositorySettings=settingsManager.getRepositorySettings(repository);
  String refRegex=repositorySettings.getRefRegex();
  try {
    String defaultBranch=null;
    try {
      defaultBranch=repositoryServiceManager.getRepositoryMetadataService().getDefaultBranch(repository).getId();
    }
 catch (    Exception e) {
    }
    if (!ref.matches(refRegex) && (defaultBranch == null || !ref.equals(defaultBranch) || !"HEAD".matches(refRegex))) {
      log.debug("Skipping {}/{}:{} (doesn't match {})",repository.getProject().getKey(),repository.getSlug(),ref,refRegex);
      return getFinishedFuture();
    }
  }
 catch (  PatternSyntaxException e) {
    log.error("Ref matcher {} is invalid",refRegex,e);
    return getFinishedFuture();
  }
  if (jobPoolBlocked.get() > 0) {
    log.warn("Job pool is currently blocked: not executing update job on {}/{}:{}",repository.getProject().getKey(),repository.getSlug(),ref);
    return getFinishedFuture();
  }
  SearchUpdateJob job=jobFactory.newDefaultJob(sfu,plf,repository,ref);
  Callable<Void> jobCallable=getJobRunnable(job,reindex);
  Future<Void> ret=jobPool.schedule(jobCallable,delayMs,TimeUnit.MILLISECONDS);
  return ret;
}

