/** 
 * Skips a character appearing immediately on the input. <p> <strong>Note:</strong> The character is consumed only if it matches the specified character.
 * @param c The character to skip.
 * @return Returns true if the character was skipped.
 * @throws IOException  Thrown if i/o error occurs.
 * @throws EOFException Thrown on end of file.
 */
public boolean skipChar(int c) throws IOException {
  if (fCurrentEntity.position == fCurrentEntity.count) {
    load(0,true);
  }
  int cc=fCurrentEntity.ch[fCurrentEntity.position];
  if (cc == c) {
    fCurrentEntity.position++;
    if (c == '\n') {
      fCurrentEntity.lineNumber++;
      fCurrentEntity.columnNumber=1;
    }
 else {
      fCurrentEntity.columnNumber++;
    }
    return true;
  }
 else   if (c == '\n' && cc == '\r' && fCurrentEntity.isExternal()) {
    if (fCurrentEntity.position == fCurrentEntity.count) {
      fCurrentEntity.ch[0]=(char)cc;
      load(1,false);
    }
    fCurrentEntity.position++;
    if (fCurrentEntity.ch[fCurrentEntity.position] == '\n') {
      fCurrentEntity.position++;
    }
    fCurrentEntity.lineNumber++;
    fCurrentEntity.columnNumber=1;
    return true;
  }
  return false;
}

/** 
 * Transform output.
 * @param element the element
 * @param code the code
 * @param supportedCodeSystems the supported code systems
 * @param request the request
 * @return the code
 */
public Code transformOutput(CodedContextElement element,Code code,List<String> supportedCodeSystems,KnowledgeRequest request){
  if (element.getOutputDisplayNameTransformation() != null) {
    final String id=element.getOutputDisplayNameTransformation().getId();
    final TerminologyInference inference=getTerminologyInference(id);
    final Code newCode=NamedCodeInferences.valueOf(inference.getCallInferenceByName()).getCodeFromDisplayName(code);
    return newCode;
  }
  if (supportedCodeSystems.size() > 0) {
    if (supportedCodeSystems.contains(code.getCodeSystem())) {
      return code;
    }
 else     if (request.getSearchCodes().size() > 0) {
      final ArrayList<Code> searchCodes=request.getSearchCodes();
      for (      final Code c : searchCodes) {
        if (supportedCodeSystems.contains(c.getCodeSystem())) {
          return c;
        }
      }
    }
 else {
      validMappings=terminologyMappings.getValidMappings();
      for (int i=0; i < validMappings.size(); i++) {
        final Mapping m=validMappings.get(i);
        if ((m.getSourceValue().equals(code.getCodeSystem())) && (supportedCodeSystems.contains(m.getTargetValue()))) {
          code.setCodeSystemName(m.getSourceName());
          if ((request.getTaskContext().getCode().getCode().equals("MLREV") || request.getTaskContext().getCode().getCode().equals("MEDOE")) && m.getTargetName().equals("RxNorm")) {
            try {
              return RxNormService.getTransformedCode(code);
            }
 catch (            IOException e) {
              e.printStackTrace();
            }
          }
          final Code transformedCode=ESHandler.transformCode(code,m.getTargetValue());
          if (transformedCode != null) {
            return transformedCode;
          }
        }
      }
    }
  }
  return code;
}

private void visitGoogCall(NodeTraversal t,Node n){
  if (!n.hasChildren() || !n.getFirstChild().isGetProp() || !n.getFirstChild().isQualifiedName()) {
    return;
  }
  Node getprop=n.getFirstChild();
  Node firstProp=n.getFirstChild();
  while (firstProp.isGetProp()) {
    firstProp=firstProp.getFirstChild();
  }
  if (!firstProp.isName() || !firstProp.getString().equals("goog")) {
    return;
  }
  Var root=t.getScope().getVar("goog");
  if (root != null && root.isLocal() && !root.getScope().isModuleScope()) {
    return;
  }
  if (root != null && root.getScope().isModuleScope() && !isFromGoogImport(root)) {
    return;
  }
  if (root == null || NodeUtil.getEnclosingScript(root.getNameNode()) != NodeUtil.getEnclosingScript(n)) {
    currentModule.metadataBuilder.usesClosure(true);
  }
  if (getprop.matchesQualifiedName(GOOG_PROVIDE)) {
    currentModule.moduleType(ModuleType.GOOG_PROVIDE,t,n);
    if (n.hasTwoChildren() && n.getLastChild().isString()) {
      String namespace=n.getLastChild().getString();
      addNamespace(currentModule,namespace,t,n);
    }
 else {
      t.report(n,ClosureRewriteModule.INVALID_PROVIDE_NAMESPACE);
    }
  }
 else   if (getprop.matchesQualifiedName(GOOG_MODULE)) {
    currentModule.moduleType(ModuleType.GOOG_MODULE,t,n);
    if (n.hasTwoChildren() && n.getLastChild().isString()) {
      String namespace=n.getLastChild().getString();
      addNamespace(currentModule,namespace,t,n);
    }
 else {
      t.report(n,ClosureRewriteModule.INVALID_MODULE_NAMESPACE);
    }
  }
 else   if (getprop.matchesQualifiedName(GOOG_MODULE_DECLARELEGACYNAMESPACE)) {
    currentModule.recordDeclareLegacyNamespace(n);
  }
 else   if (getprop.matchesQualifiedName(GOOG_DECLARE_MODULE_ID) || getprop.matchesQualifiedName(GOOG_MODULE_DECLARNAMESPACE)) {
    if (currentModule.declaredModuleId != null) {
      t.report(n,MULTIPLE_DECLARE_MODULE_NAMESPACE);
    }
    if (n.hasTwoChildren() && n.getLastChild().isString()) {
      currentModule.recordDeclareModuleId(n);
      String namespace=n.getLastChild().getString();
      addNamespace(currentModule,namespace,t,n);
    }
 else {
      t.report(n,INVALID_DECLARE_MODULE_ID_CALL);
    }
  }
 else   if (getprop.matchesQualifiedName(GOOG_REQUIRE)) {
    if (n.hasTwoChildren() && n.getLastChild().isString()) {
      currentModule.metadataBuilder.requiredGoogNamespacesBuilder().add(n.getLastChild().getString());
    }
 else {
      t.report(n,INVALID_REQUIRE_NAMESPACE);
    }
  }
 else   if (getprop.matchesQualifiedName(GOOG_REQUIRE_TYPE)) {
    if (n.hasTwoChildren() && n.getLastChild().isString()) {
      currentModule.metadataBuilder.requiredTypesBuilder().add(n.getLastChild().getString());
    }
 else {
      t.report(n,INVALID_REQUIRE_TYPE);
    }
  }
 else   if (getprop.matchesQualifiedName(GOOG_SET_TEST_ONLY)) {
    if (n.hasOneChild() || (n.hasTwoChildren() && n.getLastChild().isString())) {
      currentModule.metadataBuilder.isTestOnly(true);
    }
 else {
      t.report(n,INVALID_SET_TEST_ONLY);
    }
  }
}

/** 
 * Encodes a bean property value as a String. If the object type is not supported, null will be returned.
 * @param value an Object to encode in a String representation.
 * @return the encoded bean.
 */
private static String encode(Object value){
  if (value instanceof String) {
    return (String)value;
  }
  if (value instanceof Boolean || value instanceof Integer || value instanceof Long|| value instanceof Float|| value instanceof Double) {
    return value.toString();
  }
  if (value instanceof Date) {
    try {
      return dateFormatter.format((Date)value);
    }
 catch (    Exception ignored) {
    }
  }
  if (value instanceof Color) {
    Color color=(Color)value;
    return color.getRed() + "," + color.getGreen()+ ","+ color.getBlue();
  }
  if (value instanceof Class) {
    return ((Class)value).getName();
  }
  return null;
}

