/** 
 * Parse a floating point number from the current position.
 * @return The floating point number parsed (null if not valid).
 */
public BigDecimal parseFloatingPointLiteral(){
  int savedIdx=skipWS();
  StringBuilder val=new StringBuilder();
  boolean dotSeen=false;
  boolean expSeen=false;
  boolean sfxSeen=false;
  char c=ci.current();
  boolean negate=false;
  if (c == '-') {
    negate=true;
    c=ci.next();
  }
  while (isDecDigit(c)) {
    val.append(c);
    c=ci.next();
  }
  if (c == '.') {
    dotSeen=true;
    val.append(c);
    c=ci.next();
    while (isDecDigit(c)) {
      val.append(c);
      c=ci.next();
    }
  }
  if (val.length() < (dotSeen ? 2 : 1)) {
    ci.setIndex(savedIdx);
    return null;
  }
  if (c == 'e' || c == 'E') {
    expSeen=true;
    val.append(c);
    c=ci.next();
    if (c != '+' && c != '-' && !isDecDigit(c)) {
      ci.setIndex(savedIdx);
      return null;
    }
    do {
      val.append(c);
      c=ci.next();
    }
 while (isDecDigit(c));
  }
  if (c == 'f' || c == 'F' || c == 'd' || c == 'D') {
    sfxSeen=true;
    ci.next();
  }
  if (!dotSeen && !expSeen && !sfxSeen) {
    ci.setIndex(savedIdx);
    return null;
  }
  if (negate) {
    return new BigDecimal(val.toString()).negate();
  }
  return new BigDecimal(val.toString());
}

