/** 
 * Run PWM analysis for one chromosome
 */
void splicePwmAnalysis(String chrName,String chrSeq){
  int countEx=0, countTr=0;
  HashSet<String> done=new HashSet<String>();
  for (  Transcript tr : transcriptSet.getByChromo(chrName)) {
    Exon exPrev=null;
    for (    Exon ex : tr.sortedStrand()) {
      countEx++;
      if (exPrev != null) {
        int start, end;
        if (tr.isStrandPlus()) {
          start=exPrev.getEnd();
          end=ex.getStart();
        }
 else {
          start=ex.getEnd();
          end=exPrev.getStart();
        }
        String exPrevType=exPrev != null ? exPrev.getSpliceType().toString() : "";
        String exType=ex != null ? ex.getSpliceType().toString() : "";
        String intronTypes=exPrevType + "-" + exType;
        String key=chrName + ":" + start+ "-"+ end;
        if (!done.contains(key)) {
          updatePwm(tr,chrSeq,start,end,intronTypes);
          done.add(key);
          Intron intron=new Intron(tr,start,end,false,intronTypes,exPrev,ex);
          intronsByStr.put(intron.toString(),intron);
        }
      }
      exPrev=ex;
    }
    countTr++;
  }
  if (verbose)   Timer.showStdErr("\tChromosome: " + chrName + "\tTranscripts: "+ countTr+ "\tExons: "+ countEx);
}

@Override public int extractEnergy(ItemStack container,int maxExtract,boolean simulate){
  InventoryItem inv=getInventory(container);
  int extracted=0;
  if (inv != null) {
    for (int i=0; i < inv.getSizeInventory() && maxExtract - extracted > 0; i++) {
      ItemStack stack=inv.getStackInSlot(i);
      if (stack != null && stack.getItem() != null && stack.getItem() instanceof IEnergyContainerItem) {
        IEnergyContainerItem item=(IEnergyContainerItem)stack.getItem();
        extracted+=item.extractEnergy(stack,maxExtract - extracted,simulate);
      }
    }
    inv.closeInventory();
  }
  return extracted;
}

