@NotNull @Override protected RExecutionResult doExecute(@NotNull final String command) throws RDebuggerException {
  if (getCounter() == 1) {
    final String output="[1] \"a\" \"b\" \"c\"\n" + "[4] \"" + SERVICE_FUNCTION_PREFIX + "d"+ "\"";
    return new RExecutionResult(output,RESPONSE,TextRange.allOf(output),LS_FUNCTIONS_ERROR);
  }
  if (getCounter() == 2) {
    final String output="[1] \"integer\"";
    return new RExecutionResult(output,RESPONSE,TextRange.allOf(output),"error_ta");
  }
  if (getCounter() == 3) {
    final String output="[1] 1 2 3";
    return new RExecutionResult(output,RESPONSE,TextRange.allOf(output),"error_va");
  }
  if (getCounter() == 4 || getCounter() == 6 || getCounter() == 8 || getCounter() == 9) {
    final String output=FUNCTION_TYPE;
    return new RExecutionResult(output,RESPONSE,TextRange.allOf(output),"error_t" + getCounter());
  }
  if (getCounter() == 5) {
    final String output="function(x) {\n" + "    x ^ 2\n" + "}";
    return new RExecutionResult(output,RESPONSE,TextRange.allOf(output),"error_vb");
  }
  if (getCounter() == 7) {
    final String output="function(x) {\n" + "    x ^ 2\n" + "}\n" + ENVIRONMENT_PREFIX + "0xfffffff>";
    return new RExecutionResult(output,RESPONSE,TextRange.allOf(output),"error_vc");
  }
  throw new IllegalStateException("Unexpected command");
}
