/** 
 * Internal API of ADAL to provide the deserialization to the TokenCacheItem <p> The method will take the serializedBlob string as input and deserialize the string into a tokenCacheItem. The deserialized tokenCacheItem will be stored into the cache. Exceptions will be thrown for invalid input or the broker is enabled.
 * @param serializedBlob The blob to be deserialized.
 * @throws AuthenticationException
 */
void deserialize(final String serializedBlob) throws AuthenticationException {
  if (StringExtensions.isNullOrBlank(serializedBlob)) {
    throw new IllegalArgumentException("serializedBlob");
  }
  if (mBrokerProxy.canSwitchToBroker(mAuthority) != BrokerProxy.SwitchToBroker.CANNOT_SWITCH_TO_BROKER) {
    throw new UsageAuthenticationException(ADALError.FAIL_TO_IMPORT,"Failed to import the serialized blob " + "because broker is enabled.");
  }
  final TokenCacheItem tokenCacheItem=SSOStateSerializer.deserialize(serializedBlob);
  if (StringExtensions.isNullOrBlank(tokenCacheItem.getAuthority()) || (StringExtensions.isNullOrBlank(tokenCacheItem.getClientId()) && StringExtensions.isNullOrBlank(tokenCacheItem.getFamilyClientId()))) {
    throw new DeserializationAuthenticationException("Failed to deserialize the blob because authority or client id is null/empty.");
  }
  final String cacheKey=CacheKey.createCacheKey(tokenCacheItem);
  this.getCache().setItem(cacheKey,tokenCacheItem);
}

