public String report(){
  long deltaHeapSize=Runtime.getRuntime().totalMemory() - thenHeapSize;
  long deltaHeapMaxSize=Runtime.getRuntime().maxMemory() - thenHeapMaxSize;
  long deltaHeapFreeSize=Runtime.getRuntime().freeMemory() - thenHeapFreeSize;
  long deltaMsec=System.currentTimeMillis() - thenMsec;
  long deltaNano=System.nanoTime() - thenNano;
  return "Delta: Sec " + deltaMsec / 1000d + "  SecHres " + deltaNano / 1000000000d + "  MaxMB " + deltaHeapMaxSize / 1024d / 1024d + "  FreeMB " + deltaHeapFreeSize / 1024d / 1024d + "  SizeMB " + deltaHeapSize + "  (heap max " + thenHeapMaxSize / 1024d / 1024d + ")";
}

/** 
 * @param strictCheck Whether this is a check that is only performed when "strict missingproperties" checks are enabled.
 */
private void checkPropertyAccessHelper(JSType objectType,Node propNode,@Nullable Node objNode,Node getProp,boolean strictCheck){
  if (!reportMissingProperties || objectType.isEmptyType() || (getProp != null && allowStrictPropertyAccessOnNode(getProp))) {
    return;
  }
  String propName=propNode.getString();
  PropDefinitionKind kind=typeRegistry.canPropertyBeDefined(objectType,propName);
  if (kind.equals(PropDefinitionKind.KNOWN)) {
    return;
  }
  boolean isLooselyAssociated=kind.equals(PropDefinitionKind.LOOSE) || kind.equals(PropDefinitionKind.LOOSE_UNION);
  boolean isUnknownType=objectType.isUnknownType();
  if (isLooselyAssociated && isUnknownType) {
    return;
  }
  boolean isStruct=objectType.isStruct();
  boolean loosePropertyDeclaration=getProp != null && isQNameAssignmentTarget(getProp) && !isStruct;
  boolean maybePropExistenceCheck=!isStruct && getProp != null && allowLoosePropertyAccessOnNode(getProp);
  boolean strictReport=strictCheck || isLooselyAssociated || loosePropertyDeclaration|| maybePropExistenceCheck;
  reportMissingProperty(objNode,objectType,propNode,kind,strictReport);
}

