/** 
 * Allocates enough memory for the array and copies it.
 * @param array the array to copy
 * @see #put(double[])
 */
public DoublePointer(double... array){
  this(array.length);
  put(array);
}
/** 
 * For direct buffers, calls  {@link Pointer#Pointer(Buffer)}, while for buffers backed with an array, allocates enough memory for the array and copies it.
 * @param buffer the Buffer to reference or copy
 * @see #put(double[])
 */
public DoublePointer(DoubleBuffer buffer){
  super(buffer);
  if (buffer != null && !buffer.isDirect() && buffer.hasArray()) {
    double[] array=buffer.array();
    allocateArray(array.length - buffer.arrayOffset());
    put(array,buffer.arrayOffset(),array.length - buffer.arrayOffset());
    position(buffer.position());
    limit(buffer.limit());
  }
}
/** 
 * Allocates a native  {@code double} array of the given size.
 * @param size the number of {@code double} elements to allocate
 */
public DoublePointer(long size){
  try {
    allocateArray(size);
    if (size > 0 && address == 0) {
      throw new OutOfMemoryError("Native allocator returned address == 0");
    }
  }
 catch (  UnsatisfiedLinkError e) {
    throw new RuntimeException("No native JavaCPP library in memory. (Has Loader.load() been called?)",e);
  }
catch (  OutOfMemoryError e) {
    OutOfMemoryError e2=new OutOfMemoryError("Cannot allocate new DoublePointer(" + size + "): "+ "totalBytes = "+ formatBytes(totalBytes())+ ", physicalBytes = "+ formatBytes(physicalBytes()));
    e2.initCause(e);
    throw e2;
  }
}
