/** 
 * Counts the number of Unicode code points in the subsequence of the specified character sequence, as delineated by  {@code beginIndex} and{@code endIndex}. Any surrogate values with missing pair values will be counted as one code point.
 * @param seq the  {@code CharSequence} to look through.
 * @param beginIndex the inclusive index to begin counting at.
 * @param endIndex the exclusive index to stop counting at.
 * @return the number of Unicode code points.
 * @throws NullPointerException if  {@code seq} is {@code null}.
 * @throws IndexOutOfBoundsException if  {@code beginIndex < 0},  {@code beginIndex > endIndex} orif  {@code endIndex} is greater than the length of {@code seq}.
 * @since 1.5
 */
public static int codePointCount(CharSequence seq,int beginIndex,int endIndex){
  if (seq == null) {
    throw new NullPointerException();
  }
  int len=seq.length();
  if (beginIndex < 0 || endIndex > len || beginIndex > endIndex) {
    throw new IndexOutOfBoundsException();
  }
  int result=0;
  for (int i=beginIndex; i < endIndex; i++) {
    char c=seq.charAt(i);
    if (isHighSurrogate(c)) {
      if (++i < endIndex) {
        c=seq.charAt(i);
        if (!isLowSurrogate(c)) {
          result++;
        }
      }
    }
    result++;
  }
  return result;
}
/** 
 * Counts the number of Unicode code points in the subsequence of the specified char array, as delineated by  {@code offset} and {@code count}. Any surrogate values with missing pair values will be counted as one code point.
 * @param seq the char array to look through
 * @param offset the inclusive index to begin counting at.
 * @param count the number of  {@code char} values to look through in{@code seq}.
 * @return the number of Unicode code points.
 * @throws NullPointerException if  {@code seq} is {@code null}.
 * @throws IndexOutOfBoundsException if  {@code offset < 0},  {@code count < 0} or if{@code offset + count} is greater than the length of{@code seq}.
 * @since 1.5
 */
public static int codePointCount(char[] seq,int offset,int count){
  if (seq == null) {
    throw new NullPointerException();
  }
  int len=seq.length;
  int endIndex=offset + count;
  if (offset < 0 || count < 0 || endIndex > len) {
    throw new IndexOutOfBoundsException();
  }
  int result=0;
  for (int i=offset; i < endIndex; i++) {
    char c=seq[i];
    if (isHighSurrogate(c)) {
      if (++i < endIndex) {
        c=seq[i];
        if (!isLowSurrogate(c)) {
          result++;
        }
      }
    }
    result++;
  }
  return result;
}

