private SSLEngineResult.Status unwrapHandshake(NextFilter nextFilter) throws SSLException {
  if (inNetBuffer != null) {
    inNetBuffer.flip();
  }
  if (inNetBuffer == null || !inNetBuffer.hasRemaining()) {
    return SSLEngineResult.Status.BUFFER_UNDERFLOW;
  }
  SSLEngineResult res=unwrap0();
  handshakeStatus=res.getHandshakeStatus();
  checkStatus(res);
  if (handshakeStatus == SSLEngineResult.HandshakeStatus.FINISHED && res.getStatus() == SSLEngineResult.Status.OK && inNetBuffer.hasRemaining()) {
    res=unwrap0();
    if (inNetBuffer.hasRemaining()) {
      inNetBuffer.compact();
    }
 else {
      inNetBuffer=null;
    }
    renegotiateIfNeeded(nextFilter,res);
  }
 else {
    if (inNetBuffer.hasRemaining()) {
      inNetBuffer.compact();
    }
 else {
      inNetBuffer=null;
    }
  }
  return res.getStatus();
}

