  if (_expr().getLHS().getType() != _expr().getRHS().getType()) {
    throw new IllegalStateException("Bitwise operands are not the same type:" + " lhs=" + _expr().getLHS().getType().getName() + " rhs="+ _expr().getRHS().getType().getName());
  }
  if (_expr().getLHS().getType() != JavaTypes.pINT() && _expr().getLHS().getType() != JavaTypes.pLONG() && _expr().getLHS().getType() != JavaTypes.pBOOLEAN()) {
    throw new IllegalStateException("Operands must be int or long, found: " + _expr().getLHS().getType().getName());
  }
}

@Override public int compareTo(Node o){
  if (o == null) {
    return 1;
  }
  if (o.isIRI()) {
    return -1;
  }
  if (o.isBlankNode()) {
    return -1;
  }
  if (this.getLanguage() == null && ((Literal)o).getLanguage() != null) {
    return -1;
  }
 else   if (this.getLanguage() != null && ((Literal)o).getLanguage() == null) {
    return 1;
  }
  if (this.getDatatype() != null) {
    return this.getDatatype().compareTo(((Literal)o).getDatatype());
  }
 else   if (((Literal)o).getDatatype() != null) {
    return -1;
  }
  return 0;
}

