  if ((decision != DECISION_PERMIT) && (decision != DECISION_DENY) && (decision != DECISION_INDETERMINATE)&& (decision != DECISION_NOT_APPLICABLE)&& (decision != DECISION_INDETERMINATE_DENY)&& (decision != DECISION_INDETERMINATE_PERMIT)&& (decision != DECISION_INDETERMINATE_DENY_OR_PERMIT)) {
