/** 
 * Get the reason phrase for a particular status code. This method always returns the English text as specified in the relevent RFCs and is not internationalized.
 * @param statusCode the numeric status code
 * @return the reason phrase associated with the given status code or nullif the status code is not recognized. TODO: getStatusText should be called getReasonPhrase to match RFC
 */
public static String getStatusText(int statusCode){
  if (statusCode < 0) {
    throw new IllegalArgumentException("status code may not be negative");
  }
  int classIndex=statusCode / 100;
  int codeIndex=statusCode - classIndex * 100;
  if (classIndex < 1 || classIndex > (REASON_PHRASES.length - 1) || codeIndex < 0 || codeIndex > (REASON_PHRASES[classIndex].length - 1)) {
    return null;
  }
  return REASON_PHRASES[classIndex][codeIndex];
}

