public static int bytesToInt(byte[] bs){
  if (bs.length > 4)   throw new IllegalArgumentException("too many bytes: " + bs.length);
  int res=0;
  for (int i=0; i < bs.length; i++) {
    byte b=bs[i];
    res|=(b & 0b11111111) << (24 - 8 * i);
  }
  return res;
}

@Override public void encode(ByteBuf buf){
  int startWriterIndex=buf.writerIndex();
  buf.ensureWritable(BasicHeaderSegment.SIZE + data.estimateSize());
  buf.writerIndex(startWriterIndex + BasicHeaderSegment.SIZE);
  data.write(buf);
  int dataSegmentLength=buf.writerIndex() - startWriterIndex - 48;
{
    int pad=4 - (dataSegmentLength % 4);
    if (pad != 4) {
      buf.writeZero(pad);
    }
  }
  int endWriterIndex=buf.writerIndex();
  buf.writerIndex(startWriterIndex);
  buf.writeByte(0x23);
{
    int b=0x80;
    b|=currentStage.code << 2;
    b|=nextStage.code;
    buf.writeByte(b);
  }
  buf.writeByte(versionMax);
  buf.writeByte(versionActive);
  int ahsLength=0 >> 2;
  buf.writeByte(ahsLength);
  buf.writeByte(dataSegmentLength >> 16);
  buf.writeByte(dataSegmentLength >> 8);
  buf.writeByte(dataSegmentLength >> 0);
  assert isid.size() == 6;
  buf.writeBytes(isid.asReadOnlyByteBuffer());
  assert targetSessionIdentifier != 0;
  buf.writeShort(targetSessionIdentifier);
  buf.writeInt(initiatorTaskTag);
  buf.writeInt(0);
  buf.writeInt(statSN);
  buf.writeInt(expectedCommandSN);
  buf.writeInt(maxCommandSN);
  buf.writeByte(statusClass);
  buf.writeByte(statusDetail);
  buf.writeZero(10);
  buf.writerIndex(endWriterIndex);
}

/** 
 * Same as  {@link #getConnection(UUID)} with the only difference of returning a{@link WeakReference} to the connection instead of the connection itself.<br><b>Please do read its JavaDoc to understand when to use this!</b>
 */
ConnectionWeakReference getConnectionWeakReference(UUID connectionID) throws IOException {
  connectionsByIDLock.readLock().lock();
  try {
    ConnectionWeakReference ref=connectionsByID.get(connectionID);
    if (ref != null)     return ref;
  }
  finally {
    connectionsByIDLock.readLock().unlock();
  }
  throw new IOException("FCPPluginConnection not found, maybe client has disconnected." + " Connection ID: " + connectionID);
}

