@Override protected DecodingState finishDecode(IoBuffer buffer,ProtocolDecoderOutput out) throws Exception {
  if (!buffer.hasRemaining()) {
    return this;
  }
  String httpMethod=buffer.getString(asciiDecoder);
  HttpMethod method;
  try {
    method=HttpMethod.valueOf(httpMethod);
  }
 catch (  IllegalArgumentException e) {
    throw new HttpProtocolDecoderException(HttpStatus.SERVER_NOT_IMPLEMENTED);
  }
  out.write(method);
