      return;
    }
    for (; ; ) {
      long r=get();
      long u=r + n;
      if (u < 0L) {
        u=Long.MAX_VALUE;
      }
      if (compareAndSet(r,u)) {
        if (r == 0) {
          break;
        }
        return;
      }
    }
    long idx=index;
    long f=end;
    for (; ; ) {
      long e=0;
      while (e != n && idx != f) {
        if (cancelled) {
          return;
        }
        actual.onNext((int)idx);
        idx++;
        e++;
      }
      if (idx == f) {
        if (!cancelled) {
          states.put(ids,true);
          actual.onComplete();
        }
