public StudyResult retrieveStudyResult(Worker worker,Study study,Long studyResultId) throws ForbiddenPublixException, BadRequestPublixException {
  if (studyResultId == null) {
    throw new ForbiddenPublixException("error retrieving study result ID");
  }
  StudyResult studyResult=studyResultDao.findById(studyResultId);
  if (studyResult == null) {
    throw new BadRequestPublixException(PublixErrorMessages.STUDY_RESULT_DOESN_T_EXIST);
  }
  if (!worker.getStudyResultList().contains(studyResult)) {
    throw new ForbiddenPublixException(PublixErrorMessages.workerNeverDidStudy(worker,study.getId()));
  }
  if (!studyResult.getStudy().getId().equals(study.getId())) {
    throw new ForbiddenPublixException(PublixErrorMessages.STUDY_RESULT_DOESN_T_BELONG_TO_THIS_STUDY);
  }
  if (PublixHelpers.studyDone(studyResult)) {
    throw new ForbiddenPublixException(PublixErrorMessages.workerFinishedStudyAlready(worker,study.getId()));
  }
  return studyResult;
}

/** 
 * pipe services
 * @param conf
 * @param pathHandler
 */
private static void pipeServices(final Configuration conf,final PathHandler pathHandler){
  PluginsRegistry.getInstance().getServices().stream().forEach(srv -> {
    var srvConfArgs=srv.getConfArgs();
    String uri;
    if (srvConfArgs == null || !srvConfArgs.containsKey("uri") || srvConfArgs.get("uri") == null) {
      uri=srv.getInstance().defaultUri();
    }
 else {
      if (!(srvConfArgs.get("uri") instanceof String)) {
        LOGGER.error("Cannot start service {}:" + " the configuration property 'uri' must be a string",srv.getName());
        return;
      }
 else {
        uri=(String)srvConfArgs.get("uri");
      }
    }
    if (uri == null) {
      LOGGER.error("Cannot start service {}:" + " the configuration property 'uri' is not defined" + " and the service does not have a default value",srv.getName());
      return;
    }
    if (!uri.startsWith("/")) {
      LOGGER.error("Cannot start service {}:" + " the configuration property 'uri' must start with /",srv.getName(),uri);
      return;
    }
    PipedHttpHandler handler=new RequestContextInjectorHandler("/","*",conf.getAggregationCheckOperators(),new BodyInjectorHandler(srv.getInstance()));
    pathHandler.addPrefixPath(uri,new TracingInstrumentationHandler(new RequestLoggerHandler(new CORSHandler(handler))));
    LOGGER.info("Service {} bound to {}",srv.getName(),uri);
  }
);
}

