@Override public float[] toRGB(float[] cmyk){
  float[] rgb=new float[3];
  if (cmyk.length >= 4) {
    float r=1f - cmyk[0];
    float g=1f - cmyk[1];
    float b=1f - cmyk[2];
    float s=1f - cmyk[3];
    rgb[0]=r * s;
    rgb[1]=g * s;
    rgb[2]=b * s;
  }
  clamp(rgb);
  return rgb;
}

