/** 
 * Pretend we have done a seek but don't do it yet, if possible. The hope is that we find requested columns in more recent files and won't have to seek in older files. Creates a fake key/value with the given row/column and the highest (most recent) possible timestamp we might get from this file. When users of such "lazy scanner" need to know the next KV precisely (e.g. when this scanner is at the top of the heap), they run  {@link #enforceSeek()}. <p> Note that this function does guarantee that the current KV of this scanner will be advanced to at least the given KV. Because of this, it does have to do a real seek in cases when the seek timestamp is older than the highest timestamp of the file, e.g. when we are trying to seek to the next row/column and use OLDEST_TIMESTAMP in the seek key.
 */
@Override public boolean requestSeek(KeyValue kv,boolean forward,boolean useBloom) throws IOException {
  if (kv.getFamilyLength() == 0) {
    useBloom=false;
  }
  boolean haveToSeek=true;
  if (useBloom) {
    if (reader.getBloomFilterType() == BloomType.ROWCOL) {
      haveToSeek=reader.passesGeneralBloomFilter(kv.getBuffer(),kv.getRowOffset(),kv.getRowLength(),kv.getBuffer(),kv.getQualifierOffset(),kv.getQualifierLength());
    }
 else     if (this.matcher != null && !matcher.hasNullColumnInQuery() && (kv.isDeleteFamily() || kv.isDeleteFamilyVersion())) {
      haveToSeek=reader.passesDeleteFamilyBloomFilter(kv.getBuffer(),kv.getRowOffset(),kv.getRowLength());
    }
  }
  delayedReseek=forward;
  delayedSeekKV=kv;
  if (haveToSeek) {
    realSeekDone=false;
    long maxTimestampInFile=reader.getMaxTimestamp();
    long seekTimestamp=kv.getTimestamp();
    if (seekTimestamp > maxTimestampInFile) {
      cur=kv.createFirstOnRowColTS(maxTimestampInFile);
    }
 else {
      enforceSeek();
    }
    return cur != null;
  }
  cur=kv.createLastOnRowCol();
  realSeekDone=true;
  return true;
}

