/** 
 * Returns a QR Code symbol representing the specified data segments at the specified error correction level or higher. The smallest possible QR Code version is automatically chosen for the output. <p>This function allows the user to create a custom sequence of segments that switches between modes (such as alphanumeric and binary) to encode text more efficiently. This function is considered to be lower level than simply encoding text or binary data.</p>
 * @param segs the segments to encode
 * @param ecl the error correction level to use (will be boosted)
 * @return a QR Code representing the segments
 * @throws NullPointerException if the list of segments, a segment, or the error correction level is {@code null}
 * @throws IllegalArgumentException if the data is too long to fit in the largest version QR Code at the ECL
 */
public static QrCode encodeSegments(List<QrSegment> segs,Ecc ecl){
  return encodeSegments(segs,ecl,1,40,-1,true);
}
/** 
 * Returns a QR Code symbol representing the specified data segments with the specified encoding parameters. The smallest possible QR Code version within the specified range is automatically chosen for the output. <p>This function allows the user to create a custom sequence of segments that switches between modes (such as alphanumeric and binary) to encode text more efficiently. This function is considered to be lower level than simply encoding text or binary data.</p>
 * @param segs the segments to encode
 * @param ecl the error correction level to use (may be boosted)
 * @param minVersion the minimum allowed version of the QR symbol (at least 1)
 * @param maxVersion the maximum allowed version of the QR symbol (at most 40)
 * @param mask the mask pattern to use, which is either -1 for automatic choice or from 0 to 7 for fixed choice
 * @param boostEcl increases the error correction level if it can be done without increasing the version number
 * @return a QR Code representing the segments
 * @throws NullPointerException if the list of segments, a segment, or the error correction level is {@code null}
 * @throws IllegalArgumentException if 1 &le; minVersion &le; maxVersion &le; 40 is violated, or if mask&lt; &minus;1 or mask > 7, or if the data is too long to fit in a QR Code at maxVersion at the ECL
 */
public static QrCode encodeSegments(@NonNull List<QrSegment> segs,@NonNull Ecc ecl,int minVersion,int maxVersion,int mask,boolean boostEcl){
  if (!(1 <= minVersion && minVersion <= maxVersion && maxVersion <= 40) || mask < -1 || mask > 7)   throw new IllegalArgumentException("Invalid value");
  int version, dataUsedBits;
  for (version=minVersion; ; version++) {
    int dataCapacityBits=getNumDataCodewords(version,ecl) * 8;
    dataUsedBits=QrSegment.getTotalBits(segs,version);
    if (dataUsedBits != -1 && dataUsedBits <= dataCapacityBits)     break;
    if (version >= maxVersion)     throw new IllegalArgumentException("Data too long");
  }
  if (dataUsedBits == -1)   throw new AssertionError();
  for (  Ecc newEcl : Ecc.values()) {
    if (boostEcl && dataUsedBits <= getNumDataCodewords(version,newEcl) * 8)     ecl=newEcl;
  }
  int dataCapacityBits=getNumDataCodewords(version,ecl) * 8;
  BitBuffer bb=new BitBuffer();
  for (  QrSegment seg : segs) {
    bb.appendBits(seg.mode.modeBits,4);
    bb.appendBits(seg.numChars,seg.mode.numCharCountBits(version));
    bb.appendData(seg);
  }
  bb.appendBits(0,Math.min(4,dataCapacityBits - bb.bitLength()));
  bb.appendBits(0,(8 - bb.bitLength() % 8) % 8);
  for (int padByte=0xEC; bb.bitLength() < dataCapacityBits; padByte^=0xEC ^ 0x11)   bb.appendBits(padByte,8);
  if (bb.bitLength() % 8 != 0)   throw new AssertionError();
  return new QrCode(version,ecl,bb.getBytes(),mask);
}

