@Override public void log(Request request,Response response,long time){
  if (!getState().isAvailable() || logElements == null || condition != null && null != request.getRequest().getAttribute(condition) || conditionIf != null && null == request.getRequest().getAttribute(conditionIf)) {
    return;
  }
  String uri=request.getRequestURI();
  if (uri != null) {
    for (    String pattern : this.excludePatterns) {
      if (uri.indexOf(pattern) != -1) {
        return;
      }
    }
  }
  long start=request.getCoyoteRequest().getStartTime();
  Date date=getDate(start + time);
  StringBuilder buf=new StringBuilder();
  DBObject result=new BasicDBObject(10);
  for (int i=0; i < logElements.length; i++) {
    logElements[i].addElement(buf,result,date,request,response,time);
  }
  log(result);
}
