/** 
 * Process failover of new master for region <code>encodedRegionName</code> up in zookeeper.
 * @param encodedRegionName Region to process failover for.
 * @param regionInfo If null we'll go get it from meta table.
 * @return True if we processed <code>regionInfo</code> as a RIT.
 * @throws KeeperException
 * @throws IOException
 */
boolean processRegionInTransition(final String encodedRegionName,final HRegionInfo regionInfo) throws KeeperException, IOException {
  Lock lock=locker.acquireLock(encodedRegionName);
  try {
    Stat stat=new Stat();
    byte[] data=ZKAssign.getDataAndWatch(watcher,encodedRegionName,stat);
    if (data == null)     return false;
    RegionTransition rt;
    try {
      rt=RegionTransition.parseFrom(data);
    }
 catch (    DeserializationException e) {
      LOG.warn("Failed parse znode data",e);
      return false;
    }
    HRegionInfo hri=regionInfo;
    if (hri == null) {
      hri=regionStates.getRegionInfo(rt.getRegionName());
      EventType et=rt.getEventType();
      if (hri == null && et != EventType.RS_ZK_REGION_MERGING && et != EventType.RS_ZK_REQUEST_REGION_MERGE) {
        LOG.warn("Couldn't find the region in recovering " + rt);
        return false;
      }
    }
    return processRegionsInTransition(rt,hri,stat.getVersion());
  }
  finally {
    lock.unlock();
  }
}

/** 
 * All observables will be running in different threads so subscribe() is unblocked. CountDownLatch is only used in order to call unsubscribe() in a predictable manner.
 */
@Test public void concatUnsubscribeConcurrent(){
  final CountDownLatch callOnce=new CountDownLatch(1);
  final CountDownLatch okToContinue=new CountDownLatch(1);
  final TestObservable<String> w1=new TestObservable<String>("one","two","three");
  final TestObservable<String> w2=new TestObservable<String>(callOnce,okToContinue,"four","five","six");
  Observer<String> observer=TestHelper.mockObserver();
  TestObserver<String> to=new TestObserver<String>(observer);
  @SuppressWarnings("unchecked") TestObservable<Observable<String>> observableOfObservables=new TestObservable<Observable<String>>(Observable.unsafeCreate(w1),Observable.unsafeCreate(w2));
  Observable<String> concatF=Observable.concat(Observable.unsafeCreate(observableOfObservables));
  concatF.subscribe(to);
  try {
    callOnce.await();
    to.dispose();
    okToContinue.countDown();
    w1.t.join();
    w2.t.join();
  }
 catch (  Throwable e) {
    e.printStackTrace();
    fail(e.getMessage());
  }
  InOrder inOrder=inOrder(observer);
  inOrder.verify(observer,times(1)).onNext("one");
  inOrder.verify(observer,times(1)).onNext("two");
  inOrder.verify(observer,times(1)).onNext("three");
  inOrder.verify(observer,times(1)).onNext("four");
  inOrder.verify(observer,never()).onNext("five");
  inOrder.verify(observer,never()).onNext("six");
  verify(observer,never()).onComplete();
  verify(observer,never()).onError(any(Throwable.class));
}

