/** 
 * @param drawSpeed FPS used for internal animation sync (1 = 60 FPS; 2 = 30 FPS; 3 = 15 FPS)
 * @return
 */
public final int executeUpdate(int drawSpeed){
  this.drawSpeed=drawSpeed;
  if (Modules.sceUtilityModule.startedDialogState == null || Modules.sceUtilityModule.startedDialogState != this) {
    if (log.isDebugEnabled()) {
      log.debug(String.format("%sUpdate returning ERROR_UTILITY_WRONG_TYPE",name));
    }
    return SceKernelErrors.ERROR_UTILITY_WRONG_TYPE;
  }
  int result=SceKernelErrors.ERROR_UTILITY_INVALID_STATUS;
  if (status == PSP_UTILITY_DIALOG_STATUS_INIT && isReadyForVisible()) {
    status=PSP_UTILITY_DIALOG_STATUS_VISIBLE;
    startVisibleTimeMillis=Emulator.getClock().currentTimeMillis();
  }
 else   if (status == PSP_UTILITY_DIALOG_STATUS_VISIBLE || status == PSP_UTILITY_DIALOG_STATUS_SCREENSHOT_UNKNOWN) {
    result=0;
    params.read(paramsAddr);
    if (guDialog != null) {
      guDialog.update(drawSpeed);
    }
    boolean keepVisible=executeUpdateVisible();
    if (status == PSP_UTILITY_DIALOG_STATUS_VISIBLE && isDialogOpen()) {
      if (dialog != null) {
        dialog.checkController();
      }
      if (guDialog != null) {
        guDialog.checkController();
      }
    }
    if (status == PSP_UTILITY_DIALOG_STATUS_VISIBLE && !isDialogOpen() && !keepVisible && dialogState == DialogState.quit) {
      long now=Emulator.getClock().currentTimeMillis();
      if (now - startVisibleTimeMillis >= getMinimumVisibleDurationMillis()) {
        status=PSP_UTILITY_DIALOG_STATUS_QUIT;
      }
    }
  }
  if (log.isDebugEnabled()) {
    log.debug(String.format("%sUpdate returning 0x%08X",name,result));
  }
  return result;
}

/** 
 * Subset the supplied payments and sort by date, descending (Sorting by amount coin is also done to make the order unique, within same date. This is to stop the order 'flicking' on sync)
 * @param subsettingPaymentType if PaymentType.SENDING return all sending payments for the last 24 hoursif PaymentType.RECEIVING return all requesting and receiving payments for the last 24 hours
 */
public List<PaymentData> subsetPaymentsAndSort(Set<PaymentData> paymentDataSet,PaymentType subsettingPaymentType){
  List<PaymentData> subsetPaymentDataList=Lists.newArrayList();
  if (subsettingPaymentType != null) {
    DateTime aDayAgo=DateTime.now().minusHours(24);
    for (    PaymentData paymentData : paymentDataSet) {
      if (subsettingPaymentType == PaymentType.SENDING && (paymentData.getType() == PaymentType.THEY_REQUESTED || paymentData.getType() == PaymentType.SENDING) && paymentData.getDate().isAfter(aDayAgo)) {
        subsetPaymentDataList.add(paymentData);
      }
 else       if (subsettingPaymentType == PaymentType.RECEIVING) {
        if (paymentData.getType() == PaymentType.YOU_REQUESTED || paymentData.getType() == PaymentType.RECEIVING || paymentData.getType() == PaymentType.PART_PAID) {
          if (paymentData.getDate().isAfter(aDayAgo)) {
            subsetPaymentDataList.add(paymentData);
          }
        }
      }
    }
  }
  Collections.sort(subsetPaymentDataList,new PaymentComparator());
  return subsetPaymentDataList;
}

