public Shape getPrimitive(int x,int xThreshold,int y,int yThreshold){
  Shape result=null;
  for (int i=0; i < myRectangles.size(); i++) {
    Rectangle next=myRectangles.get(i);
    if (next.getLeftX() <= x + xThreshold && next.getRightX() >= x - xThreshold && next.getTopY() <= y + yThreshold && next.getBottomY() >= y - yThreshold) {
      result=next;
      break;
    }
  }
  if (result != null) {
    return result;
  }
  result=myPolygonIndex.get(x,xThreshold,y,yThreshold);
  if (result != null) {
    return result;
  }
  return myTextIndex.get(x + myDeltaX,y + myDeltaY);
}

