protected T createProviderInstanceFromType(final Class<? extends T> execClass,final String providerName) throws ProviderCreationException {
  boolean ctrfound=true;
  try {
    final Constructor<? extends T> method=execClass.getDeclaredConstructor(new Class[]{Framework.class});
    final T executor=method.newInstance(framework);
    return executor;
  }
 catch (  NoSuchMethodException e) {
    ctrfound=false;
  }
catch (  Exception e) {
    throw new ProviderCreationException("Unable to create provider instance: " + e.getMessage(),e,getName(),providerName);
  }
  try {
    final Constructor<? extends T> method=execClass.getDeclaredConstructor(new Class[0]);
    final T executor=method.newInstance();
    return executor;
  }
 catch (  NoSuchMethodException e) {
    throw new ProviderCreationException("No constructor found with signature (Framework) or (): " + e.getMessage(),e,getName(),providerName);
  }
catch (  Exception e) {
    throw new ProviderCreationException("Unable to create provider instance: " + e.getMessage(),e,getName(),providerName);
