private void waitForReplication(FileSystem fileSystem,Path p,int replicas) throws IOException, InterruptedException {
  FileStatus fileStatus=fileSystem.getFileStatus(p);
  boolean fail=true;
  while (fail) {
    fail=false;
    BlockLocation[] blockLocations=fileSystem.getFileBlockLocations(p,0,fileStatus.getLen());
    for (    BlockLocation blockLocation : blockLocations) {
      System.out.println(blockLocation);
      String[] hosts=blockLocation.getHosts();
      if (hosts.length != replicas) {
        fail=true;
      }
    }
    Thread.sleep(1000);
  }
}

private Collection<Class<?>> resolveClassNames(List<QName> names) throws SchemaException {
  Collection<Class<?>> rv=new HashSet<>();
  for (  QName name : names) {
    if (ALL_TYPES_MARKER.equals(name.getLocalPart())) {
      for (      ObjectTypes objectType : ObjectTypes.values()) {
        rv.add(objectType.getClassDefinition());
      }
    }
 else {
      Class<?> objectClass=prismContext.getSchemaRegistry().determineCompileTimeClass(name);
      if (objectClass == null) {
        throw new SchemaException("Unknown class: " + name);
      }
      rv.add(objectClass);
    }
  }
  return rv;
}

