public static Map<String,Pair<Type,Object>> setChoosenOption(int combinaisonIndex){
  int ci=combinaisonIndex;
  int totalCombinaisons=1;
  for (  Pair<Type,Object[]> v : optionsDefinitions.values()) {
    totalCombinaisons*=v.getValue().length;
  }
  if (ci > totalCombinaisons)   throw new IllegalArgumentException("combinaisonIndex too large, max is " + (totalCombinaisons - 1));
  for (  Entry<String,Pair<Type,Object[]>> optionEntry : optionsDefinitions.entrySet()) {
    String name=optionEntry.getKey();
    Type type=optionEntry.getValue().getKey();
    Object[] options=optionEntry.getValue().getValue();
    int l=totalCombinaisons / options.length;
    int whichBin=ci / l;
    ci=ci % l;
    totalCombinaisons=totalCombinaisons / options.length;
    choosenOption.put(name,new Pair<Type,Object>(type,options[whichBin]));
  }
  return choosenOption;
}

