/** 
 * Pings the server and suppresses all exceptions. Returns a future that can be used to determine if a response has been received. The future will update the  {@link Server} latency and tags if found.
 * @param type The type of cluster to ping.
 * @param server The server to update with the results of the ping. If <code>false</code> is returned then the state will not have been updated. Passing <code>null</code> for the state is allowed.
 * @param conn The connection to ping.
 * @return A {@link Future} that will be updated once the reply isreceived.
 */
public Future<Reply> pingAsync(final ClusterType type,final Server server,final Connection conn){
  try {
    final ServerUpdateCallback future=new ServerUpdateCallback(server);
