/** 
 * Split a text into a list of strings. Reduce the texts to a string of hashes where each Unicode character represents one line.
 * @param text String to encode.
 * @param lineArray List of unique strings.
 * @param lineHash Map of strings to indices.
 * @return Encoded string.
 */
private String diff_linesToCharsMunge(String text,List<String> lineArray,Map<String,Integer> lineHash){
  int lineStart=0;
  int lineEnd=-1;
  String line;
  StringBuilder chars=new StringBuilder();
  while (lineEnd < text.length() - 1) {
    lineEnd=text.indexOf('\n',lineStart);
    if (lineEnd == -1) {
      lineEnd=text.length() - 1;
    }
    line=text.substring(lineStart,lineEnd + 1);
    lineStart=lineEnd + 1;
    if (lineHash.containsKey(line)) {
      chars.append(String.valueOf((char)(int)lineHash.get(line)));
    }
 else {
      lineArray.add(line);
      lineHash.put(line,lineArray.size() - 1);
      chars.append(String.valueOf((char)(lineArray.size() - 1)));
    }
  }
  return chars.toString();
}

