 * Sets this controller's UDP port. If the controller is currently receiving messages and the new port is different, the controller releases the old port and binds to the new port.
 * @param port 
 */
public void setPort(int port){
synchronized (inboundLock) {
    boolean changed=this.port != port;
    this.port=port;
    outboundPacket.setPort(port);
    if (changed && null != inboundThread && inboundThread.isAlive()) {
      new Thread(){
        @Override public void run(){
          stopReceiving();
          startReceiving();
        }
      }
.start();
    }
  }
}

