@Override public void adjustShortTargetPrices(Amount price,Amount amount,double orderGroup){
  log.debug(this.getClass().getSimpleName() + " : adjustShortTargetPrices to called from stack " + Thread.currentThread().getStackTrace()[2]);
  for (Iterator<Tradeable> itm=triggerOrders.keySet().iterator(); itm.hasNext(); ) {
    Tradeable market=itm.next();
    for (Iterator<Double> itd=triggerOrders.get(market).keySet().iterator(); itd.hasNext(); ) {
      Double triggerInterval=itd.next();
      if (triggerOrders.get(market).get(triggerInterval).get(TransactionType.BUY) == null || triggerOrders.get(market).get(triggerInterval).get(TransactionType.BUY).get(FillType.TARGET_LIMIT) == null || triggerOrders.get(market).get(triggerInterval).get(TransactionType.BUY).get(FillType.TARGET_LIMIT).isEmpty())       continue;
synchronized (triggerOrders.get(market).get(triggerInterval).get(TransactionType.BUY).get(FillType.TARGET_LIMIT)) {
        for (Iterator<Order> it=triggerOrders.get(market).get(triggerInterval).get(TransactionType.BUY).get(FillType.TARGET_LIMIT).iterator(); it.hasNext(); ) {
          Order triggerOrder=it.next();
          if (triggerOrder.isBid() && (orderGroup == 0 || triggerOrder.getOrderGroup() == 0 || orderGroup == triggerOrder.getOrderGroup())) {
            long targetPrice=Math.min((triggerOrder.getTargetPrice().toBasis(triggerOrder.getMarket().getPriceBasis(),Remainder.ROUND_EVEN)).getCount(),(price.minus(amount.abs()).toBasis(triggerOrder.getMarket().getPriceBasis(),Remainder.ROUND_EVEN)).getCount());
            DecimalAmount TargetDiscrete=DecimalAmount.of(new DiscreteAmount(targetPrice,triggerOrder.getMarket().getPriceBasis()));
            triggerOrder.setTargetPrice(TargetDiscrete);
            if (triggerOrder.getParentFill() != null)             triggerOrder.getParentFill().setTargetPriceCount(targetPrice);
          }
        }
      }
    }
    sortShortTargetOrders(market);
  }
}

