/** 
 * Whether this node's JSDoc may apply to a function <p>This has some false positive cases, to allow for patterns like goog.abstractMethod.
 */
private boolean isJSDocOnFunctionNode(Node n,JSDocInfo info){
switch (n.getToken()) {
case FUNCTION:
case GETTER_DEF:
case SETTER_DEF:
case MEMBER_FUNCTION_DEF:
case STRING_KEY:
case COMPUTED_PROP:
case EXPORT:
    return true;
case GETELEM:
case GETPROP:
  if (n.getFirstChild().isQualifiedName()) {
    return true;
  }
return false;
case VAR:
case LET:
case CONST:
case ASSIGN:
{
Node lhs=n.getFirstChild();
Node rhs=NodeUtil.getRValueOfLValue(lhs);
if (rhs != null && isClass(rhs) && !info.isConstructor()) {
  return false;
}
return true;
}
default :
return false;
}
}

