/** 
 * Gets the current location for <code>hbase:meta</code> if available and waits for up to the specified timeout if not immediately available.  Returns null if the timeout elapses before root is available.
 * @param timeout maximum time to wait for root availability, in milliseconds
 * @return {@link ServerName} for server hosting <code>hbase:meta</code> or nullif none available
 * @throws InterruptedException if interrupted while waiting
 * @throws NotAllMetaRegionsOnlineException if meta not available beforetimeout
 */
public ServerName waitForMeta(final long timeout) throws InterruptedException, NotAllMetaRegionsOnlineException {
  ServerName sn=metaRegionTracker.waitMetaRegionLocation(timeout);
  if (sn == null) {
    throw new NotAllMetaRegionsOnlineException("Timed out; " + timeout + "ms");
  }
  return sn;
}
/** 
 * Waits indefinitely for availability of <code>hbase:meta</code>.  Used during cluster startup.  Does not verify meta, just that something has been set up in zk.
 * @see #waitForMeta(long)
 * @throws InterruptedException if interrupted while waiting
 */
public void waitForMeta() throws InterruptedException {
  while (!this.stopped) {
    try {
      if (waitForMeta(100) != null)       break;
    }
 catch (    NotAllMetaRegionsOnlineException e) {
      if (LOG.isTraceEnabled()) {
        LOG.trace("hbase:meta still not available, sleeping and retrying." + " Reason: " + e.getMessage());
      }
    }
  }
}

