private String getNextPrefix(String prefix){
  if (prefix == null)   return null;
  byte[] bytes=prefix.getBytes();
  for (int i=bytes.length - 1; i >= 0; i--) {
    bytes[i]++;
    if (bytes[i] != Byte.MIN_VALUE)     break;
  }
  return new String(bytes);
}

