/** 
 * Converts properties that refer to a private data context value
 * @param data config data
 * @param privateDataContext private data
 * @param name property name
 * @param propValue value to convert
 */
private void convertPrivateDataValue(final Map<String,String> data,final DataContext privateDataContext,final String name,final String propValue,final Map<String,Object> renderingOptions) throws ConfigurationException {
  boolean clearValue=isValueConversionFailureRemove(renderingOptions);
  String[] prop=propValue.split("\\.",2);
  if (prop.length < 2 || prop[0].length() < 1 || prop[1].length() < 1) {
    throw new ConfigurationException("Unable to load '" + name + "' configuration value: Expected 'option.name' format, but saw: "+ propValue);
  }
  String newvalue=privateDataContext.resolve(prop[0],prop[1]);
  if (null == newvalue) {
    if (clearValue) {
      data.remove(name);
