private void parseCompoundTypeLiteralExpression(String[] T,boolean bInterface,int iOffset,int iLineNum,int iColumn){
  parseNamespaceStartOrRelativeType(T,bInterface);
  Expression expr=peekExpression();
  if (expr.hasParseExceptions()) {
    List<IParseIssue> exceptions=expr.getParseExceptions();
    if (exceptions.size() != 1 || (exceptions.get(0).getMessageKey() != Res.MSG_CANNOT_REFERENCE_CLASS_TYPE_VAR_IN_STATIC_CONTEXT && exceptions.get(0).getMessageKey() != Res.MSG_TYPE_PARAM_NOT_ASSIGNABLE_TO && exceptions.get(0).getMessageKey() != Res.MSG_EXPECTING_CLOSING_ANGLE_BRACKET_FOR_TYPE)) {
      ParseException pe=expr.removeParseException(null);
      pe.setMessage(Res.MSG_INVALID_TYPE,T[0]);
      expr.addParseException(pe);
    }
  }
  setLocation(iOffset,iLineNum,iColumn);
  parseIndirectMemberAccess(iOffset,iLineNum,iColumn,true);
}

private TagFileInfo createTagFileInfo(TreeNode elem,String uri,URL jarFileUrl) throws JasperException {
  String name=null;
  String path=null;
  Iterator list=elem.findChildren();
  while (list.hasNext()) {
    TreeNode child=(TreeNode)list.next();
    String tname=child.getName();
    if ("name".equals(tname)) {
      name=child.getBody();
    }
 else     if ("path".equals(tname)) {
      path=child.getBody();
    }
 else     if ("example".equals(tname)) {
    }
 else     if ("tag-extension".equals(tname)) {
    }
 else     if ("icon".equals(tname) || "display-name".equals(tname) || "description".equals(tname)) {
    }
 else {
      if (log.isWarnEnabled()) {
        log.warn(Localizer.getMessage("jsp.warning.unknown.element.in.tagfile",tname));
      }
    }
  }
  if (path.startsWith("/META-INF/tags")) {
    ctxt.setTagFileJarUrl(path,jarFileUrl);
  }
 else   if (!path.startsWith("/WEB-INF/tags")) {
    err.jspError("jsp.error.tagfile.illegalPath",path);
  }
  TagInfo tagInfo=TagFileProcessor.parseTagFileDirectives(parserController,name,path,jarFileUrl,this);
  return new TagFileInfo(name,path,tagInfo);
}

