@Override public IMatchable findObject(MatchNode matchNode,int index){
  int node_type=matchNode.getType();
  if (node_type == MatchNode.MATCHNODE_STATEMENT && !this.stats.isEmpty()) {
    String position=(String)matchNode.getRuleValue(MatchProperties.STATEMENT_POSITION);
    if (position != null) {
      if (position.matches("-?\\d+")) {
        return this.stats.get((this.stats.size() + Integer.parseInt(position)) % this.stats.size());
      }
    }
 else     if (index < this.stats.size()) {
      return this.stats.get(index);
    }
  }
 else   if (node_type == MatchNode.MATCHNODE_EXPRENT && this.exprents != null && !this.exprents.isEmpty()) {
    String position=(String)matchNode.getRuleValue(MatchProperties.EXPRENT_POSITION);
    if (position != null) {
      if (position.matches("-?\\d+")) {
        return this.exprents.get((this.exprents.size() + Integer.parseInt(position)) % this.exprents.size());
      }
    }
 else     if (index < this.exprents.size()) {
      return this.exprents.get(index);
    }
  }
  return null;
}

