/** 
 * Adds a usage for the given type expression (unless it references a variable that is defined in the externs, in which case no goog.require() is needed). When a usage is added, it means that there should be a goog.require for that type.
 */
private void maybeAddUsage(NodeTraversal t,Node n,final JSTypeExpression expr){
  Predicate<Node> pred=new Predicate<Node>(){
    @Override public boolean apply(    Node n){
      return n == expr.getRoot();
    }
  }
;
  maybeAddUsage(t,n,expr.getRoot(),true,pred);
}
private void maybeAddUsage(final NodeTraversal t,final Node n,Node rootTypeNode,final boolean markStrongUsages,Predicate<Node> pred){
  Visitor visitor=new Visitor(){
    @Override public void visit(    Node typeNode){
      if (typeNode.isString()) {
        String typeString=typeNode.getString();
        if (mode == Mode.SINGLE_FILE && !typeString.contains(".")) {
          weakUsages.add(typeString);
          return;
        }
        String rootName=Splitter.on('.').split(typeString).iterator().next();
        Var var=t.getScope().getVar(rootName);
        if (var == null || (var.isGlobal() && !var.isExtern())) {
          if (markStrongUsages) {
            usages.put(typeString,n);
          }
 else {
            addWeakUsagesOfAllPrefixes(typeString);
          }
        }
 else {
          addWeakUsagesOfAllPrefixes(typeString);
        }
      }
    }
  }
;
  NodeUtil.visitPreOrder(rootTypeNode,visitor,pred);
}

