public WriteResult remove(DBObject o,com.mongodb.WriteConcern concern) throws MongoException {
  if (willTrace())   trace("remove: " + _fullNameSpace + " "+ JSON.serialize(o));
  OutMessage om=new OutMessage(_mongo,2006);
  om.writeInt(0);
  om.writeCString(_fullNameSpace);
  Collection<String> keys=o.keySet();
  if (keys.size() == 1 && keys.iterator().next().equals("_id") && o.get(keys.iterator().next()) instanceof ObjectId)   om.writeInt(1);
 else   om.writeInt(0);
  om.putObject(o);
  return _connector.say(_db,om,concern);
}

