public static List<GenericUserSimilarity.UserUserSimilarity> getTopUserUserSimilarities(final int howMany,final Iterator<GenericUserSimilarity.UserUserSimilarity> allSimilarities){
  final Queue<GenericUserSimilarity.UserUserSimilarity> topSimilarities=new PriorityQueue<>(howMany + 1,Collections.reverseOrder());
  boolean full=false;
  double lowestTopValue=Double.NEGATIVE_INFINITY;
  while (allSimilarities.hasNext()) {
    final GenericUserSimilarity.UserUserSimilarity similarity=allSimilarities.next();
    final double value=similarity.getValue();
    if (!Double.isNaN(value) && (!full || value > lowestTopValue)) {
      topSimilarities.add(similarity);
      if (full) {
        topSimilarities.poll();
      }
 else       if (topSimilarities.size() > howMany) {
        full=true;
        topSimilarities.poll();
      }
      lowestTopValue=topSimilarities.peek().getValue();
    }
  }
  final int size=topSimilarities.size();
  if (size == 0) {
    return Collections.emptyList();
  }
  final List<GenericUserSimilarity.UserUserSimilarity> result=Lists.newArrayListWithCapacity(size);
  result.addAll(topSimilarities);
  Collections.sort(result);
  return result;
}

