public Set<RelationshipTuple> getRelationships(SubjectNode subject,PredicateNode predicate,ObjectNode object){
  if (m_rels == null) {
    readRels();
  }
  boolean basicExplicit=false;
  Set<RelationshipTuple> foundRels=new HashSet<RelationshipTuple>(m_rels.size());
  for (  RelationshipTuple t : m_rels) {
    if (Constants.MODEL.HAS_MODEL.uri.equals(t.predicate) && Models.isBasicModel(t.object)) {
      basicExplicit=true;
    }
    if (subject != null) {
      if (!JRDF.sameSubject(subject,t.subject)) {
        continue;
      }
    }
    if (predicate != null) {
      if (!JRDF.samePredicate(predicate,t.predicate)) {
        continue;
      }
    }
    if (object != null) {
      if (!JRDF.sameObject(object,t.object,t.isLiteral,t.datatype,t.language)) {
        continue;
      }
    }
    foundRels.add(t);
  }
  if (!basicExplicit && (subject == null || JRDF.sameSubject(subject,PID.toURI(m_pid))) && (predicate == null || JRDF.samePredicate(predicate,Constants.MODEL.HAS_MODEL))&& (object == null || JRDF.sameObject(object,Models.FEDORA_OBJECT_CURRENT))) {
    foundRels.add(new RelationshipTuple(Constants.FEDORA.uri.concat(m_pid),Constants.MODEL.HAS_MODEL.uri,Models.FEDORA_OBJECT_CURRENT.uri,false,null));
  }
  return foundRels;
}

