/** 
 * Responsible for posting Forge events to Sponge.
 * @param eventData The event data from Forge
 * @return true if cancelled, false if not
 */
public boolean post(ForgeToSpongeEventData eventData){
  final boolean hasForgeListeners=eventData.getForgeListeners().length > 0;
  if (hasForgeListeners) {
    eventData.setBeforeModifications(true);
    try (CauseStackManager.StackFrame frame=Sponge.getCauseStackManager().pushCauseFrame()){
      ForgeToSpongeEventFactory.createAndPostSpongeEvent(frame,eventData);
    }
     if (eventData.getSpongeEvent() == null) {
      ((EventBusBridge_Forge)MinecraftForge.EVENT_BUS).forgeBridge$post(eventData.getForgeEvent(),true);
      return eventData.getForgeEvent().isCancelable() && eventData.getForgeEvent().isCanceled();
    }
    if (eventData.getForgeEvent().isCancelable() && eventData.getForgeEvent().isCanceled()) {
      return true;
    }
    final SpongeToForgeEventData spongeEventData=new SpongeToForgeEventData(eventData);
    SpongeToForgeEventFactory.createAndPostForgeEvent(spongeEventData);
  }
  eventData.setBeforeModifications(false);
  eventData.setForced(!hasForgeListeners);
  try (CauseStackManager.StackFrame frame=Sponge.getCauseStackManager().pushCauseFrame()){
    ForgeToSpongeEventFactory.createAndPostSpongeEvent(frame,eventData);
  }
   ForgeToSpongeEventFactory.onPostEnd(eventData);
  return eventData.getForgeEvent().isCancelable() && eventData.getForgeEvent().isCanceled();
}
/** 
 * Responsible for posting Sponge events to Forge.
 * @param eventData The event data from Sponge
 * @return true if cancelled, false if not
 */
private SpongeToForgeEventData post(SpongeToForgeEventData eventData){
  final Event spongeEvent=eventData.getSpongeEvent();
  final boolean hasSpongeListeners=!eventData.getSpongeListenerCache().getListeners().isEmpty();
  if (hasSpongeListeners) {
    for (    Order order : Order.values()) {
      post(spongeEvent,eventData.getSpongeListenerCache().getListenersByOrder(order),true,false,eventData.useCauseStackManager());
    }
  }
  SpongeToForgeEventFactory.createAndPostForgeEvent(eventData);
  if (hasSpongeListeners) {
    SpongeToForgeEventFactory.handlePrefireLogic(spongeEvent);
    for (    Order order : Order.values()) {
      post(spongeEvent,eventData.getSpongeListenerCache().getListenersByOrder(order),false,false,eventData.useCauseStackManager());
    }
  }
  return eventData;
}
@SuppressWarnings("unchecked") public boolean post(Event event,List<RegisteredListener<?>> listeners,boolean beforeModifications,boolean forced,boolean useCauseStackManager){
  ModContainer oldContainer=((LoadControllerBridge_Forge)SpongeMod.instance.getController()).forgeBridge$getActiveModContainer();
  for (  @SuppressWarnings("rawtypes") RegisteredListener listener : listeners) {
    ((LoadControllerBridge_Forge)SpongeMod.instance.getController()).forgeBridge$setActiveModContainer((ModContainer)listener.getPlugin());
    try {
      if (forced || (!listener.isBeforeModifications() && !beforeModifications) || (listener.isBeforeModifications() && beforeModifications)) {
        listener.getTimingsHandler().startTimingIfSync();
        if (event instanceof AbstractEvent) {
          ((AbstractEvent)event).currentOrder=listener.getOrder();
        }
        if (useCauseStackManager) {
          try (CauseStackManager.StackFrame frame=Sponge.getCauseStackManager().pushCauseFrame()){
            frame.pushCause(listener.getPlugin());
            listener.handle(event);
          }
         }
 else {
          listener.handle(event);
        }
      }
    }
 catch (    Throwable e) {
      new PrettyPrinter(60).add("%s %s","Could not pass ",event.getClass().getSimpleName()).centre().hr().add("Could not pass the event %s to an Event Listener!",event.getClass().getSimpleName()).add().add("Since the event can be modified during the event's listener,\n" + " there could be adverse side effects of the exception occuring\n" + "such that duplications or other game breaking issues could exist.\n"+ "Due to the nature of the exception, this is not likely an exception\n"+ "that is covered by SpongeForge or Forge itself, and therefor should\n"+ "be reported to the mod/plugin author first prior to reporting to\n"+ "Sponge or Forge.").add("%s: %s","Owning Mod/Plugin",listener.getPlugin().getId()).add("Exception:").add(e).log(SpongeImpl.getLogger(),Level.WARN);
    }
 finally {
      listener.getTimingsHandler().stopTimingIfSync();
    }
  }
  if (event instanceof AbstractEvent) {
    ((AbstractEvent)event).currentOrder=null;
  }
  ((LoadControllerBridge_Forge)SpongeMod.instance.getController()).forgeBridge$setActiveModContainer(oldContainer);
  return event instanceof Cancellable && ((Cancellable)event).isCancelled();
}
