/** 
 * Returns the true/false if the date falls within a period.
 * @param date the date for which we want a period.
 * @return exists
 */
public int indexOf(ZonedDateTime date){
  for (int i=this.data.size(); i > 0; i--) {
    CandleItem item=(CandleItem)this.data.get(i - 1);
    if (date.isAfter(item.getPeriod().getEnd())) {
      return -1;
    }
    if ((date.isAfter(item.getPeriod().getStart()) || date.equals(item.getPeriod().getStart())) && (date.isBefore(item.getPeriod().getEnd()) || date.equals(item.getPeriod().getEnd()))) {
      return i - 1;
    }
  }
  return -1;
}

