private UriResource functionCall(final EdmFunctionImport edmFunctionImport,final FullQualifiedName boundFunctionName,final FullQualifiedName bindingParameterTypeName,final boolean isBindingParameterCollection) throws UriParserException, UriValidationException {
  final List<UriParameter> parameters=ParserHelper.parseFunctionParameters(tokenizer,edm,null,false,aliases);
  final List<String> names=ParserHelper.getParameterNames(parameters);
  EdmFunction function=null;
  if (edmFunctionImport != null) {
    function=edmFunctionImport.getUnboundFunction(names);
    if (function == null) {
      throw new UriParserSemanticException("Function of function import '" + edmFunctionImport.getName() + "' "+ "with parameters "+ names.toString()+ " not found.",UriParserSemanticException.MessageKeys.FUNCTION_NOT_FOUND,edmFunctionImport.getName(),names.toString());
    }
  }
 else {
    function=edm.getBoundFunction(boundFunctionName,bindingParameterTypeName,isBindingParameterCollection,names);
    if (function == null) {
      throw new UriParserSemanticException("Function " + boundFunctionName + " not found.",UriParserSemanticException.MessageKeys.UNKNOWN_PART,boundFunctionName.getFullQualifiedNameAsString());
    }
  }
  ParserHelper.validateFunctionParameters(function,parameters,edm,null,aliases);
  ParserHelper.validateFunctionParameterFacets(function,parameters,edm,aliases);
  UriResourceFunctionImpl resource=new UriResourceFunctionImpl(edmFunctionImport,function,parameters);
  if (tokenizer.next(TokenKind.OPEN)) {
    if (function.getReturnType() != null && function.getReturnType().getType().getKind() == EdmTypeKind.ENTITY && function.getReturnType().isCollection()) {
      resource.setKeyPredicates(ParserHelper.parseKeyPredicate(tokenizer,(EdmEntityType)function.getReturnType().getType(),null,edm,null,aliases));
    }
 else {
      throw new UriParserSemanticException("A key is not allowed.",UriParserSemanticException.MessageKeys.KEY_NOT_ALLOWED);
    }
  }
  ParserHelper.requireTokenEnd(tokenizer);
  return resource;
}

public EventBean copy(EventBean theEvent){
  ObjectArrayBackedEventBean arrayBacked=(ObjectArrayBackedEventBean)theEvent;
  Object[] props=arrayBacked.getProperties();
  Object[] shallowCopy=new Object[props.length];
  System.arraycopy(props,0,shallowCopy,0,props.length);
  for (  int index : mapIndexesToCopy) {
    Map<String,Object> innerMap=(Map<String,Object>)shallowCopy[index];
    if (innerMap != null) {
      Map copy=new HashMap<String,Object>(innerMap);
      shallowCopy[index]=copy;
    }
  }
  for (  int index : arrayIndexesToCopy) {
    Object array=shallowCopy[index];
    if (array != null && array.getClass().isArray() && Array.getLength(array) != 0) {
      Object copied=Array.newInstance(array.getClass().getComponentType(),Array.getLength(array));
      System.arraycopy(array,0,copied,0,Array.getLength(array));
      shallowCopy[index]=copied;
    }
  }
  return eventAdapterService.adapterForTypedObjectArray(shallowCopy,eventType);
}

@HLEFunction(nid=HLESyscallNid,version=150) public void hlePsmfPlayerMCThread(int args,TPointer argp){
  TPointer psmfPlayer=argp.getPointer();
  TPointer data=psmfPlayer.getPointer();
  TPointer playerStatusAddr=data.getPointer(24);
  TPointer decodeControlAddr=data.getPointer(36);
  TPointer avSyncControlAddr=data.getPointer(32);
  TPointer videoBufferAddr=avSyncControlAddr.getPointer(24);
  TPointer audioBufferAddr=avSyncControlAddr.getPointer(28);
  while (true) {
    while (true) {
      hleSyscall(Modules.ThreadManForUserModule.sceKernelWaitEventFlag(playerStatusAddr.getValue32(24),1,PSP_EVENT_WAITCLEAR | PSP_EVENT_WAITOR,TPointer32.NULL,TPointer32.NULL));
      if (data.getValue32(20) == 1) {
        Modules.ThreadManForUserModule.sceKernelExitThread(0);
        return;
      }
      int decodeStatus=AtomicValue.get(decodeControlAddr.getPointer(72));
      if (decodeStatus == PSMF_PLAYER_DECODE_STATUS_END) {
        if (avSyncControlAddr.getValue32(20) == 1) {
          if (videoBufferAddr.getValue32(16) == 0) {
            if (audioBufferAddr.getValue32(12) == 0) {
              if (getVblankSyncCount(avSyncControlAddr) == 0) {
                break;
              }
            }
          }
        }
 else {
          if (videoBufferAddr.getValue32(16) == 0) {
            if (getVblankSyncCount(avSyncControlAddr) == 0) {
              break;
            }
          }
        }
      }
    }
    int playMode=playerStatusAddr.getValue32(4);
    int loopingMode=playerStatusAddr.getValue32(12);
    if (getPlayerVersion(playerStatusAddr) == PSMF_PLAYER_VERSION_NET || (playMode != PSMF_PLAYER_MODE_REWIND && loopingMode == PSMF_PLAYER_NOT_LOOPING)) {
      if (getPlayerStatus(playerStatusAddr) == PSMF_PLAYER_STATUS_PLAYING) {
        setPlayerStatus(playerStatusAddr,PSMF_PLAYER_STATUS_PLAYING_FINISHED);
      }
    }
 else {
      final int newPlayMode=PSMF_PLAYER_MODE_PLAY;
      final int newPlaySpeed=PSMF_PLAYER_SPEED_SLOW;
      playerStatusAddr.setValue32(0,0);
      playerStatusAddr.setValue32(4,newPlayMode);
      playerStatusAddr.setValue32(16,newPlaySpeed);
      int result=updatePlayModeAndSpeed(avSyncControlAddr,newPlayMode,newPlaySpeed,0);
      if (result != 0) {
        setPlayerStatusError(playerStatusAddr);
      }
    }
  }
}

