 else   if (inJoin && expr instanceof RelationalFunctionCall && templates.isFunctionJoinsWrapped()) {
    append("table(");
    super.visit(expr,context);
    append(")");
  }
 else {
    super.visit(expr,context);
  }
  return null;
}

