static Set findInstallNameToolCandidates(File[] files,final Log log) throws MojoExecutionException, MojoFailureException {
  HashSet candidates=new HashSet();
  for (int i=0; i < files.length; i++) {
    File file=files[i];
    if (!file.exists()) {
      continue;
    }
    if (file.isDirectory()) {
      candidates.addAll(findInstallNameToolCandidates(file.listFiles(),log));
    }
    String fileName=file.getName();
    if (file.isFile() && file.canWrite() && (fileName.endsWith(".so") || fileName.endsWith(".dylib") || (fileName.endsWith(".jnilib")))) {
      candidates.add(file);
    }
  }
  return candidates;
}

