/** 
 * Returns the value of boolean attribute.
 * @param attribute attribute name.
 * @param defaultValue default value to use if attribute value unspecified.
 * @see #getAttribute(String)
 */
protected boolean getBooleanAttribute(final String attribute,final boolean defaultValue){
  final String a=getAttribute(attribute);
  if (a == null) {
    return defaultValue;
  }
  if ("true".equalsIgnoreCase(a) || "1".equalsIgnoreCase(a) || "on".equalsIgnoreCase(a)|| "yes".equalsIgnoreCase(a)) {
    return true;
  }
  if ("false".equalsIgnoreCase(a) || "0".equalsIgnoreCase(a) || "off".equalsIgnoreCase(a)|| "no".equalsIgnoreCase(a)) {
    return false;
  }
  throw new ConfigurationException("Unrecognized value '" + a + "' of boolean attribute "+ attribute+ ". Valid values: yes/no, true/false, 1/0, on/off",this);
}

