@Override public SerializerResult entityCollection(final ServiceMetadata metadata,final EdmEntityType entityType,final AbstractEntityCollection entitySet,final EntityCollectionSerializerOptions options) throws SerializerException {
  final ContextURL contextURL=checkContextURL(options == null ? null : options.getContextURL());
  final String name=contextURL == null ? null : contextURL.getEntitySetOrSingletonOrType();
  if (options != null && options.getWriteOnlyReferences()) {
    ReferenceCollectionSerializerOptions rso=ReferenceCollectionSerializerOptions.with().contextURL(contextURL).build();
    return entityReferenceCollection(entitySet,rso);
  }
  OutputStream outputStream=null;
  SerializerException cachedException=null;
  try {
    CircleStreamBuffer buffer=new CircleStreamBuffer();
    outputStream=buffer.getOutputStream();
    XMLStreamWriter writer=XMLOutputFactory.newInstance().createXMLStreamWriter(outputStream,DEFAULT_CHARSET);
    writer.writeStartDocument(DEFAULT_CHARSET,"1.0");
    writer.writeStartElement(ATOM,Constants.ATOM_ELEM_FEED,NS_ATOM);
    writer.writeNamespace(ATOM,NS_ATOM);
    writer.writeNamespace(METADATA,NS_METADATA);
    writer.writeNamespace(DATA,NS_DATA);
    writer.writeAttribute(METADATA,NS_METADATA,Constants.CONTEXT,ContextURLBuilder.create(contextURL).toASCIIString());
    writeMetadataETag(metadata,writer);
    writeOperations(entitySet.getOperations(),writer);
    if (options != null && options.getId() != null) {
      writer.writeStartElement(ATOM,Constants.ATOM_ELEM_ID,NS_ATOM);
      writer.writeCharacters(options.getId());
      writer.writeEndElement();
    }
    if (options != null && options.getCount() != null && options.getCount().getValue() && entitySet.getCount() != null) {
      writeCount(entitySet,writer);
    }
    if (entitySet.getNext() != null) {
      writeNextLink(entitySet,writer);
    }
    boolean writeOnlyRef=(options != null && options.getWriteOnlyReferences());
    if (options == null) {
      writeEntitySet(metadata,entityType,entitySet,null,null,null,null,writer,writeOnlyRef,name,null);
    }
 else {
      writeEntitySet(metadata,entityType,entitySet,options.getExpand(),null,options.getSelect(),options.xml10InvalidCharReplacement(),writer,writeOnlyRef,name,null);
    }
    writer.writeEndElement();
    writer.writeEndDocument();
    writer.flush();
    writer.close();
    outputStream.close();
    return SerializerResultImpl.with().content(buffer.getInputStream()).build();
  }
 catch (  final XMLStreamException e) {
    cachedException=new SerializerException(IO_EXCEPTION_TEXT,e,SerializerException.MessageKeys.IO_EXCEPTION);
    throw cachedException;
  }
catch (  IOException e) {
    cachedException=new SerializerException(IO_EXCEPTION_TEXT,e,SerializerException.MessageKeys.IO_EXCEPTION);
    throw cachedException;
  }
 finally {
    closeCircleStreamBufferOutput(outputStream,cachedException);
  }
}

