/** 
 * <strong>Problem 45 Triangular, pentagonal, and hexagonal</strong> <p>Triangle, pentagonal, and hexagonal numbers are generated by the following formulae:</p> <p>Triangle      Tn=n(n+1)/2     1, 3,  6, 10, 15, ...</p> <p>Pentagonal    Pn=n(3nâˆ’1)/2    1, 5, 12, 22, 35, ...</p> <p>Hexagonal     Hn=n(2nâˆ’1)      1, 6, 15, 28, 45, ...</p> <p> It can be verified that T285 = P165 = H143 = 40755. Find the next triangle number that is also pentagonal and hexagonal. </p> See also <a href="https://projecteuler.net/problem=45">projecteuler.net problem 45</a>.
 */
@Test public void shouldSolveProblem45(){
  assertThat(List.of(5,12,22,35)).allMatch(Euler45Test::isPentagonal);
  assertThat(List.of(3,11,21,36)).allMatch(i -> !isPentagonal(i));
  Assertions.assertThat(HEXAGONAL.take(5)).containsExactly(6L,15L,28L,45L,66L);
  assertThat(HEXAGONAL.filter(Euler45Test::isPentagonal).head()).isEqualTo(40755);
  assertThat(HEXAGONAL.filter(Euler45Test::isPentagonal).tail().head()).isEqualTo(1533776805L);
}

