public int read(byte[] b,int offset,int len) throws IOException {
  if (DEBUG) {
  }
synchronized (lock) {
    if (!inputStreamOpened) {
      throw new IOException("operation finished");
    }
    if (len < 0 || offset < 0 || offset + len > b.length) {
      throw new ArrayIndexOutOfBoundsException();
    }
    if (len == 0) {
      return 0;
    }
    if (inputStreamEof) {
      return -1;
    }
    int result=0;
    while (true) {
      int rd=stream.parsePacketData(recvHeaders,b,offset,len);
      if (rd != 0) {
        offset+=rd;
        len-=rd;
        result+=rd;
        if (len == 0) {
          if (stream.dataOffset != stream.packetOffset) {
            return result;
          }
        }
      }
 else {
        if ((len == 0) && !stream.isEof) {
          return result;
        }
      }
      if (stream.isEof) {
        inputStreamEof=true;
        if (stream.dataOffset == stream.packetOffset) {
          requestEnd=stream.packetType == (opcode | ObexPacketStream.OPCODE_FINAL);
          return (result == 0) ? -1 : result;
        }
 else {
          return result;
        }
      }
      packetExchange();
    }
  }
}

