@Override public final ListenableFuture<ProgramController> stop(){
  LOG.trace("Stop program {}",programId);
  if (!state.compareAndSet(State.STARTING,State.STOPPING) && !state.compareAndSet(State.ALIVE,State.STOPPING) && !state.compareAndSet(State.SUSPENDED,State.STOPPING)) {
    return Futures.immediateFailedFuture(new IllegalStateException("Stopping not allowed for " + name + " in "+ state.get()));
  }
  final SettableFuture<ProgramController> result=SettableFuture.create();
  executor.execute(() -> {
    try {
      caller.stopping();
      doStop();
      state.set(State.KILLED);
      result.set(AbstractProgramController.this);
      caller.killed();
    }
 catch (    Throwable t) {
      error(t,result);
    }
  }
);
  return result;
}

