void visitSubtree(Node n,Node parent){
switch (n.getToken()) {
case CALL:
    if (n.hasTwoChildren() && n.getFirstChild().isGetProp() && n.getFirstFirstChild().matchesName("goog")) {
      if (!requires.contains(Require.BASE)) {
        requires.add(Require.BASE);
      }
      Node callee=n.getFirstChild();
      Node argument=n.getLastChild();
switch (callee.getLastChild().getString()) {
case "module":
        loadFlags.put("module","goog");
case "provide":
      if (!argument.isString()) {
        return;
      }
    provides.add(argument.getString());
  return;
case "require":
if (!argument.isString()) {
  return;
}
requires.add(Require.googRequireSymbol(argument.getString()));
return;
case "requireType":
if (!argument.isString()) {
return;
}
typeRequires.add(argument.getString());
return;
case "loadModule":
n=argument.getLastChild();
break;
default :
return;
}
}
 else if (parent.isGetProp() && parent.matchesQualifiedName("goog.declareModuleId") && parent.getParent().isCall()) {
Node argument=parent.getParent().getSecondChild();
if (!argument.isString()) {
return;
}
provides.add(argument.getString());
}
break;
case MODULE_BODY:
if (!parent.getBooleanProp(Node.GOOG_MODULE)) {
provides.add(modulePath.toModuleName());
loadFlags.put("module","es6");
}
break;
case IMPORT:
visitEs6ModuleName(n.getLastChild(),n);
return;
case EXPORT:
if (NodeUtil.isExportFrom(n)) {
visitEs6ModuleName(n.getLastChild(),n);
}
return;
case VAR:
if (n.getFirstChild().matchesName("goog") && NodeUtil.isNamespaceDecl(n.getFirstChild())) {
provides.add("goog");
}
break;
case EXPR_RESULT:
case CONST:
case BLOCK:
case SCRIPT:
case NAME:
case DESTRUCTURING_LHS:
case LET:
break;
default :
return;
}
for (Node child=n.getFirstChild(); child != null; child=child.getNext()) {
visitSubtree(child,n);
}
}

