/** 
 * Replace the previous object id for a persistable object with a new one. This is used where we have already added the object to the cache(s) and/or enlisted it in the txn before its real identity was fixed (attributed in the datastore).
 * @param pc The Persistable object
 * @param oldID the old id it was known by
 * @param newID the new id
 */
public void replaceObjectId(Object pc,Object oldID,Object newID){
  if (pc == null || newID == null) {
    NucleusLogger.CACHE.warn(Localiser.msg("003006"));
    return;
  }
  ObjectProvider op=findObjectProvider(pc);
  if (cache != null) {
    if (oldID != null) {
      Object o=cache.get(oldID);
      if (o != null) {
        if (NucleusLogger.CACHE.isDebugEnabled()) {
          NucleusLogger.CACHE.debug(Localiser.msg("003012",StringUtils.toJVMIDString(pc),IdentityUtils.getPersistableIdentityForId(oldID),IdentityUtils.getPersistableIdentityForId(newID)));
        }
        cache.remove(oldID);
      }
    }
    if (op != null) {
      putObjectIntoLevel1Cache(op);
    }
  }
  if (oldID != null && enlistedOPCache.get(oldID) != null) {
    if (op != null) {
      enlistedOPCache.remove(oldID);
      enlistedOPCache.put(newID,op);
      if (NucleusLogger.TRANSACTION.isDebugEnabled()) {
        NucleusLogger.TRANSACTION.debug(Localiser.msg("015018",StringUtils.toJVMIDString(pc),IdentityUtils.getPersistableIdentityForId(oldID),IdentityUtils.getPersistableIdentityForId(newID)));
      }
    }
  }
  if (oldID != null && l2CacheTxIds != null) {
    if (l2CacheTxIds.contains(oldID)) {
      l2CacheTxIds.remove(oldID);
      l2CacheTxIds.add(newID);
    }
  }
  if (oldID != null && pbrAtCommitHandler != null && tx.isActive()) {
    pbrAtCommitHandler.swapObjectId(oldID,newID);
  }
}

private void loadAlgorithms(String packageName,String[] names){
  for (int i=0; i != names.length; i++) {
    Class clazz=null;
    try {
      ClassLoader loader=this.getClass().getClassLoader();
      if (loader != null) {
        clazz=loader.loadClass(packageName + names[i] + "$Mappings");
      }
 else {
        clazz=Class.forName(packageName + names[i] + "$Mappings");
      }
    }
 catch (    ClassNotFoundException e) {
    }
    if (clazz != null) {
      try {
        ((AlgorithmProvider)clazz.newInstance()).configure(this);
      }
 catch (      Exception e) {
        throw new InternalError("cannot create instance of " + packageName + names[i]+ "$Mappings : "+ e);
      }
    }
  }
}

