protected void onWrapGetterSetterProperty(MethodEntity entity,Method method){
  if (method.isAnnotationPresent(Reflection.Getter.class)) {
    Reflection.Getter getter=method.getAnnotation(Reflection.Getter.class);
    String name=getter.value();
    if (name.isEmpty()) {
      name=method.getName();
      if (name.startsWith("__get")) {
        name=name.substring(5);
      }
 else       if (name.startsWith("get")) {
        name=name.substring(3);
      }
 else       if (name.startsWith("is") && (method.getReturnType() == Boolean.TYPE || method.getReturnType() == Boolean.class)) {
        name=name.substring(2);
      }
      name=name.substring(0,1).toLowerCase() + name.substring(1);
    }
    PropertyEntity propertyEntity=getPropertyOfMethod(entity,name);
    method.setAccessible(true);
    propertyEntity.setGetter(entity);
    propertyEntity.setHiddenInDebugInfo(getter.hiddenInDebugInfo());
    if (entity.isPublic()) {
      entity.setModifier(php.runtime.common.Modifier.PROTECTED);
    }
  }
  if (method.isAnnotationPresent(Reflection.Setter.class)) {
    String name=method.getAnnotation(Reflection.Setter.class).value();
    if (name.isEmpty()) {
      name=method.getName();
      if (name.startsWith("__set")) {
        name=name.substring(5);
      }
 else       if (name.startsWith("set")) {
        name=name.substring(3);
      }
      name=name.substring(0,1).toLowerCase() + name.substring(1);
    }
    PropertyEntity propertyEntity=getPropertyOfMethod(entity,name);
    method.setAccessible(true);
    propertyEntity.setSetter(entity);
    if (entity.isPublic()) {
      entity.setModifier(php.runtime.common.Modifier.PROTECTED);
    }
  }
}

private int measureHeightOfChildren(int widthMeasureSpec,int startPosition,int endPosition,final int maxHeight,int disallowPartialChildPosition){
  final ListAdapter adapter=mAdapter;
  if (adapter == null) {
    return mDropDownList.getListPaddingTop() + mDropDownList.getListPaddingBottom();
  }
  int returnedHeight=mDropDownList.getListPaddingTop() + mDropDownList.getListPaddingBottom();
  final int dividerHeight=((mDropDownList.getDividerHeight() > 0) && mDropDownList.getDivider() != null) ? mDropDownList.getDividerHeight() : 0;
  int prevHeightWithoutPartialChild=0;
  int i;
  View child;
  endPosition=(endPosition == -1) ? adapter.getCount() - 1 : endPosition;
  for (i=startPosition; i <= endPosition; ++i) {
    child=mAdapter.getView(i,null,mDropDownList);
    if (mDropDownList.getCacheColorHint() != 0) {
      child.setDrawingCacheBackgroundColor(mDropDownList.getCacheColorHint());
    }
    measureScrapChild(child,i,widthMeasureSpec);
    if (i > 0) {
      returnedHeight+=dividerHeight;
    }
    returnedHeight+=child.getMeasuredHeight();
    if (returnedHeight >= maxHeight) {
      return (disallowPartialChildPosition >= 0) && (i > disallowPartialChildPosition) && (prevHeightWithoutPartialChild > 0)&& (returnedHeight != maxHeight) ? prevHeightWithoutPartialChild : maxHeight;
    }
    if ((disallowPartialChildPosition >= 0) && (i >= disallowPartialChildPosition)) {
      prevHeightWithoutPartialChild=returnedHeight;
    }
  }
  return returnedHeight;
}

