/** 
 * Combines runtime measurements with identical class names and method names into one measurement, assuming that they originate from a loop or a similar construct where a summary measurement has been intended.
 */
protected void combineRuntimeMeasurements(){
  RuntimeNode preceding=null;
  for (Iterator<RuntimeNode> iterator=children.iterator(); iterator.hasNext(); ) {
    final RuntimeNode child=iterator.next();
    if (preceding != null && preceding.timeStopped != 0 && child.timeStopped != 0 && preceding.timeStopped <= child.timeStarted && preceding.children.isEmpty() && child.children.isEmpty() && preceding.methodName.equals(child.methodName) && preceding.className.equals(child.className)) {
      preceding.timeStarted=child.timeStarted - (preceding.timeStopped - preceding.timeStarted);
      preceding.timeStopped=child.timeStopped;
      preceding.memoryStarted=child.memoryStarted - (preceding.memoryStopped - preceding.memoryStarted);
      preceding.memoryStopped=child.memoryStopped;
      iterator.remove();
    }
 else {
      preceding=child;
      child.combineRuntimeMeasurements();
    }
  }
}

