private static Object getAvroValue(Object value,FieldType type){
  if (value == null) {
    return null;
  }
switch (type) {
case STRING:
    return (String)value;
case INTEGER:
  return value instanceof Integer ? value : ((Number)value).intValue();
case LONG:
return value instanceof Long ? value : ((Number)value).longValue();
case BOOLEAN:
return (Boolean)value;
case DOUBLE:
return value instanceof Double ? value : ((Number)value).doubleValue();
case DATE:
return ((LocalDate)value).toEpochDay();
case TIMESTAMP:
return ((Instant)value).toEpochMilli();
case TIME:
return ((LocalTime)value).toSecondOfDay();
case BINARY:
return (byte[])value;
default :
if (type.isArray()) {
return ((List)value).stream().map(e -> getAvroValue(e,type.getArrayElementType())).collect(Collectors.toList());
}
if (type.isMap()) {
return ((Map)value).entrySet().stream().collect(Collectors.toMap(new Function<Map.Entry,String>(){
@Override public String apply(Map.Entry entry){
return (String)entry.getKey();
}
}
,e -> getAvroValue(e,type.getMapValueType())));
}
throw new IllegalStateException("unsupported type");
}
}

public void initialise(java.util.HashMap newValue,Object oldValue){
  if (newValue != null) {
    if (SCOUtils.mapHasSerialisedKeysAndValues(ownerMmd) && (ownerMmd.getMap().keyIsPersistent() || ownerMmd.getMap().valueIsPersistent())) {
      ExecutionContext ec=ownerOP.getExecutionContext();
      Iterator iter=newValue.entrySet().iterator();
      while (iter.hasNext()) {
        Map.Entry entry=(Map.Entry)iter.next();
        Object key=entry.getKey();
        Object value=entry.getValue();
        if (ownerMmd.getMap().keyIsPersistent()) {
          ObjectProvider keyOP=ec.findObjectProvider(key);
          if (keyOP == null) {
            keyOP=ec.getNucleusContext().getObjectProviderFactory().newForEmbedded(ec,key,false,ownerOP,ownerMmd.getAbsoluteFieldNumber());
          }
        }
        if (ownerMmd.getMap().valueIsPersistent()) {
          ObjectProvider valOP=ec.findObjectProvider(value);
          if (valOP == null) {
            valOP=ec.getNucleusContext().getObjectProviderFactory().newForEmbedded(ec,value,false,ownerOP,ownerMmd.getAbsoluteFieldNumber());
          }
        }
      }
    }
    if (NucleusLogger.PERSISTENCE.isDebugEnabled()) {
      NucleusLogger.PERSISTENCE.debug(Localiser.msg("023008",ownerOP.getObjectAsPrintable(),ownerMmd.getName(),"" + newValue.size()));
    }
    if (useCache) {
      java.util.Map oldMap=(java.util.Map)oldValue;
      if (oldMap != null) {
        delegate.putAll(oldMap);
      }
      isCacheLoaded=true;
      SCOUtils.updateMapWithMapKeysValues(ownerOP.getExecutionContext().getApiAdapter(),this,newValue);
    }
 else {
      if (backingStore != null) {
        if (SCOUtils.useQueuedUpdate(ownerOP)) {
          if (ownerOP.isFlushedToDatastore() || !ownerOP.getLifecycleState().isNew()) {
            ownerOP.getExecutionContext().addOperationToQueue(new MapClearOperation(ownerOP,backingStore));
            Iterator iter=newValue.entrySet().iterator();
            while (iter.hasNext()) {
              java.util.Map.Entry entry=(java.util.Map.Entry)iter.next();
              ownerOP.getExecutionContext().addOperationToQueue(new MapPutOperation(ownerOP,backingStore,entry.getKey(),entry.getValue()));
            }
          }
        }
 else {
          backingStore.clear(ownerOP);
          backingStore.putAll(ownerOP,newValue);
        }
      }
      delegate.putAll(newValue);
      isCacheLoaded=true;
      makeDirty();
    }
  }
}
