/** 
 * Deserialize payload only.  You must provide a header, typically obtained by calling {@link BitcoinSerializer#deserializeHeader}.
 */
public Message deserializePayload(BitcoinPacketHeader header,ByteBuffer in) throws ProtocolException, BufferUnderflowException {
  byte[] payloadBytes=new byte[header.size];
  in.get(payloadBytes,0,header.size);
  byte[] hash;
  hash=doubleDigest(payloadBytes);
  if (header.checksum[0] != hash[0] || header.checksum[1] != hash[1] || header.checksum[2] != hash[2] || header.checksum[3] != hash[3]) {
    throw new ProtocolException("Checksum failed to verify, actual " + bytesToHexString(hash) + " vs "+ bytesToHexString(header.checksum));
  }
  if (log.isDebugEnabled()) {
    log.debug("Received {} byte '{}' message: {}",header.size,header.command,Utils.bytesToHexString(payloadBytes));
  }
  try {
    return makeMessage(header.command,header.size,payloadBytes,hash,header.checksum);
  }
 catch (  Exception e) {
    throw new ProtocolException("Error deserializing message " + Utils.bytesToHexString(payloadBytes) + "\n",e);
  }
}

