public void process(Object row,int tag) throws HiveException {
  try {
    alias=(byte)tag;
    if ((lastAlias == null) || (!lastAlias.equals(alias)))     nextSz=joinEmitInterval;
    ArrayList<Object> nr=computeValues(row,joinValues.get(alias),joinValuesObjectInspectors.get(alias),joinFilters.get(alias),joinFilterObjectInspectors.get(alias),noOuterJoin);
    if (this.handleSkewJoin)     skewJoinKeyContext.handleSkew(tag);
    int sz=storage.get(alias).size();
    StructObjectInspector soi=(StructObjectInspector)inputObjInspectors[tag];
    StructField sf=soi.getStructFieldRef(Utilities.ReduceField.KEY.toString());
    Object keyObject=soi.getStructFieldData(row,sf);
    if (alias == numAliases - 1 && !(handleSkewJoin && skewJoinKeyContext.currBigKeyTag >= 0)) {
      if (sz == joinEmitInterval) {
        checkAndGenObject();
        storage.get(alias).clear();
      }
    }
 else {
      if (sz == nextSz) {
        LOG.warn("table " + alias + " has "+ sz+ " rows for join key "+ keyObject);
        nextSz=getNextSize(nextSz);
      }
    }
    storage.get(alias).add(nr);
    if (SerDeUtils.isNullObject(keyObject,sf.getFieldObjectInspector(),this.hconf)) {
      endGroup();
      startGroup();
    }
    reporter.incrCounter(Counter.JOIN_ACCEPT_ROW_COUNTER,1);
  }
 catch (  Exception e) {
    e.printStackTrace();
    throw new HiveException(e);
  }
}

