 * @param stack The stack being used
 * @param access The world access
 * @param pos The position
 * @param sameStack The very same stack, required by mixins
 * @return True if the stack is empty, or the change block event pre was cancelled.
 */
@Redirect(method="canToolHarvestBlock",at=@At(value="INVOKE",target="Lnet/minecraft/item/ItemStack;isEmpty()Z",remap=true),remap=false) private static boolean forgeImpl$UpdateItemStackWithPre(final ItemStack stack,final IBlockAccess access,final BlockPos pos,final ItemStack sameStack){
  if (stack.isEmpty()) {
    return true;
  }
  if (SpongeImplHooks.isMainThread() && access instanceof WorldBridge && !((WorldBridge)access).bridge$isFake()) {
    try (final CauseStackManager.StackFrame frame=Sponge.getCauseStackManager().pushCauseFrame()){
      frame.addContext(EventContextKeys.USED_ITEM,ItemStackUtil.snapshotOf(stack));
      return SpongeCommonEventFactory.callChangeBlockEventPre(((WorldServerBridge)access),pos).isCancelled();
    }
   }
  return false;
}

