private static void setIndexedProperty(Entity entity,String key,Object value){
  if (entity == null) {
    throw new RuntimeException("entity can't be null");
  }
  if (key == null) {
    throw new RuntimeException("entity property key can't be null");
  }
  if (key.isEmpty()) {
    throw new IllegalArgumentException("entity property key can't be empty");
  }
  if (value == null) {
    entity.setProperty(key,null);
    return;
  }
  if (!GAE_SUPPORTED_TYPES.contains(value.getClass()) && !(value instanceof Blob) && !(value instanceof EmbeddedEntity)&& !(value instanceof List)) {
    throw new RuntimeException("Unsupported type[class=" + value.getClass().getName() + "] in GAE repository");
  }
  if (value instanceof String) {
    final String valueString=(String)value;
    if (valueString.length() > DataTypeUtils.MAX_STRING_PROPERTY_LENGTH) {
      final Text text=new Text(valueString);
      entity.setProperty(key,text);
    }
 else {
      entity.setProperty(key,value);
    }
  }
 else   if (value instanceof Number || value instanceof Date || value instanceof Boolean|| GAE_SUPPORTED_TYPES.contains(value.getClass())) {
    entity.setProperty(key,value);
  }
 else   if (value instanceof EmbeddedEntity) {
    entity.setProperty(key,value);
  }
 else   if (value instanceof Blob) {
    final Blob blob=(Blob)value;
    entity.setProperty(key,new com.google.appengine.api.datastore.Blob(blob.getBytes()));
  }
 else   if (value instanceof List) {
    entity.setProperty(key,value);
  }
}

