/** 
 * Adds a CONSTANT_Integer_info or CONSTANT_Float_info to the constant pool of this symbol table. Does nothing if the constant pool already contains a similar item.
 * @param tag one of {@link Symbol#CONSTANT_INTEGER_TAG} or {@link Symbol#CONSTANT_FLOAT_TAG}.
 * @param value an int or float.
 * @return a constant pool constant with the given tag and primitive values.
 */
private Symbol addConstantIntegerOrFloat(final int tag,final int value){
  int hashCode=hash(tag,value);
  Entry entry=get(hashCode);
  while (entry != null) {
    if (entry.tag == tag && entry.hashCode == hashCode && entry.data == value) {
      return entry;
    }
    entry=entry.next;
  }
  constantPool.putByte(tag).putInt(value);
  return put(new Entry(constantPoolCount++,tag,value,hashCode));
}
/** 
 * Adds a new CONSTANT_Integer_info or CONSTANT_Float_info to the constant pool of this symbol table.
 * @param index the constant pool index of the new Symbol.
 * @param tag one of {@link Symbol#CONSTANT_INTEGER_TAG} or {@link Symbol#CONSTANT_FLOAT_TAG}.
 * @param value an int or float.
 */
private void addConstantIntegerOrFloat(final int index,final int tag,final int value){
  add(new Entry(index,tag,value,hash(tag,value)));
}

/** 
 * Tests that when there are several tasks with interval 0 running at the same time, all of them are executed once before the first one is executed again.
 */
public void testTasksRepeatedlyRunningAtSameTimeAreScheduledFairly(){
  int taskCount=10;
  final IncrementalTask[] tasks=new IncrementalTask[taskCount];
  for (int i=0; i < taskCount; i++) {
    tasks[i]=mock(IncrementalTask.class,"repeating_" + i);
    if (i == 0) {
      when(tasks[i].execute()).thenReturn(true,false);
    }
 else {
      when(tasks[i].execute()).thenReturn(false);
    }
    timer.scheduleRepeating(tasks[i],1,0);
  }
  InOrder inOrder=inOrder((Object[])tasks);
  timer.tick(1);
  for (int i=0; i < taskCount; i++) {
    inOrder.verify(tasks[i]).execute();
  }
  inOrder.verify(tasks[0]).execute();
  verify(tasks[0],times(2)).execute();
}

