    if (presets[0] && (oreName.contains("ingot") || itemStack.getItem() == Items.iron_ingot || itemStack.getItem() == Items.gold_ingot))     return true;
    if (presets[1] && oreName.contains("ore"))     return true;
    if (presets[2] && oreName.contains("log"))     return true;
    if (presets[3] && oreName.contains("plank"))     return true;
    if (presets[4] && oreName.contains("dust"))     return true;
    if (presets[5] && oreName.contains("crushed") && !oreName.contains("purified"))     return true;
    if (presets[6] && oreName.contains("purified"))     return true;
    if (presets[7] && oreName.contains("plate"))     return true;
    if (presets[8] && oreName.contains("gem"))     return true;
    if (presets[10] && oreName.contains("dye"))     return true;
    if (presets[11] && oreName.contains("nugget"))     return true;
