public void endElement(String uri,String localName,String qName){
  if (localName.equals("threshold"))   config.setThreshold(Double.parseDouble(content.toString()));
 else   if (localName.equals("maybe-threshold"))   config.setMaybeThreshold(Double.parseDouble(content.toString()));
 else   if (localName.equals("name"))   name=content.toString();
 else   if (localName.equals("property")) {
    if (idprop)     properties.add(new PropertyImpl(name));
 else {
      Property p=new PropertyImpl(name,comparator,low,high);
      if (ignore_prop)       p.setIgnoreProperty(true);
      p.setLookupBehaviour(lookup);
      properties.add(p);
    }
  }
 else   if (localName.equals("low"))   low=Double.parseDouble(content.toString());
 else   if (localName.equals("high"))   high=Double.parseDouble(content.toString());
 else   if (localName.equals("comparator")) {
    comparator=(Comparator)objects.get(content.toString());
    if (comparator == null)     comparator=(Comparator)instantiate(content.toString());
  }
 else   if (localName.equals("csv") || localName.equals("jdbc") || localName.equals("jndi")|| localName.equals("ntriples")|| localName.equals("sparql")|| localName.equals("data-source")) {
    config.addDataSource(groupno,datasource);
    datasource=null;
    currentobj=null;
  }
 else   if (localName.equals("object")) {
    if (currentobj instanceof Comparator)     config.addCustomComparator((Comparator)currentobj);
    currentobj=null;
  }
 else   if (localName.equals("database"))   config.addDatabase(database);
  if (keepers.contains(localName))   keep=false;
 else   if (localName.equals("duke")) {
    if (groupno > 0 && groupno != 2)     throw new DukeConfigException("Record linkage mode requires exactly 2 groups; should you be using deduplication mode?");
  }
}

