/** 
 * Gets a specific number of bytes from reader input stream
 * @param buf byte buffer to store bytes
 * @param start starting index to store bytes
 * @param n number of bytes to read
 * @return number of bytes read
 * @throws EOBException
 * @throws IOException
 */
private int getBytes(byte[] buf,int start,int n) throws EOBException, IOException {
  int i;
  int c;
  for (i=0; i < n; i++) {
    c=reader.read();
    if (c == -1) {
      throw new EOBException();
    }
    buf[start + i]=(byte)c;
  }
  return i;
}

/** 
 * Appends an entry to the write queue. Is maxQ is set an reached this method blocks until queue space becomes available. The entry will be freed by the logger.
 * @param entry to write.
 * @throws InterruptedException if the entry could not be appended.
 */
public synchronized void append(LogEntry entry) throws InterruptedException, IllegalStateException {
  assert (entry != null);
  if (!quit && maxQ > 0 && entries.size() >= maxQ) {
    wait();
  }
  if (!quit) {
    assert (maxQ == 0 || entries.size() < maxQ);
    entries.add(entry);
    notifyAll();
  }
 else {
    throw new InterruptedException("Appending the LogEntry to the DiskLogger's " + "queue was interrupted, due DiskLogger shutdown.");
  }
}

