/** 
 * Handle partial-drop-deletes. As we match keys in order, when we have a range from which we can drop deletes, we can set retainDeletesInOutput to false for the duration of this range only, and maintain consistency. 
 */
private void checkPartialDropDeleteRange(byte[] row,int offset,short length){
  if ((dropDeletesFromRow != null) && ((dropDeletesFromRow == HConstants.EMPTY_START_ROW) || (Bytes.compareTo(row,offset,length,dropDeletesFromRow,0,dropDeletesFromRow.length) >= 0))) {
    retainDeletesInOutput=false;
    dropDeletesFromRow=null;
  }
  if ((dropDeletesFromRow == null) && (dropDeletesToRow != null) && (dropDeletesToRow != HConstants.EMPTY_END_ROW)&& (Bytes.compareTo(row,offset,length,dropDeletesToRow,0,dropDeletesToRow.length) >= 0)) {
    retainDeletesInOutput=true;
    dropDeletesToRow=null;
  }
}

