 * This function accepts a string containing a CSS selector which is then used to match a set of elements, or it accepts raw HTML creating a GQuery element containing those elements. The second parameter is is a class reference to a plugin to be used. Xpath selector is supported in browsers with native xpath engine.
 */
public static <T extends GQuery>T $(String selector,Class<T> plugin){
  return $(selector,document,plugin);
}
/** 
 * This function accepts a string containing a CSS selector which is then used to match a set of elements, or it accepts raw HTML creating a GQuery element containing those elements. The second parameter is the context to use for the selector, or the document where the new elements will be created. Xpath selector is supported in browsers with native xpath engine.
 */
public static GQuery $(String selectorOrHtml,Node ctx){
  String selector=null;
  if (selectorOrHtml == null || (selector=selectorOrHtml.trim()).length() == 0) {
