  value=setLeafValue(value);
  int[] ids=this.charMap.toIdList(key + UNUSED_CHAR);
  int fromState=1;
  int toState=1;
  int index=0;
  while (index < ids.length) {
    int c=ids[index];
    toState=getBase(fromState) + c;
    expandArray(toState);
    if (isEmpty(toState)) {
      deleteFreeLink(toState);
      setCheck(toState,fromState);
      if (index == ids.length - 1) {
        ++this.size;
        setBase(toState,value);
      }
 else {
        int nextChar=ids[(index + 1)];
        setBase(toState,getNextFreeBase(nextChar));
      }
    }
 else     if (getCheck(toState) != fromState) {
      solveConflict(fromState,c);
      continue;
    }
    fromState=toState;
    ++index;
  }
  if (overwrite) {
    setBase(toState,value);
  }
  return true;
}
