/** 
 * Centralized logic to discover and validate the sanity of the Hadoop  home directory. Returns either NULL or a directory that exists and  was specified via either -Dhadoop.home.dir or the HADOOP_HOME ENV  variable.  This does a lot of work so it should only be called  privately for initialization once per process.
 */
private static String checkHadoopHome(){
  String home=System.getProperty("hadoop.home.dir");
  if (home == null) {
    home=System.getenv("HADOOP_HOME");
  }
  try {
    if (home == null) {
      throw new IOException("HADOOP_HOME or hadoop.home.dir are not set.");
    }
    if (home.startsWith("\"") && home.endsWith("\"")) {
      home=home.substring(1,home.length() - 1);
    }
    File homedir=new File(home);
    if (!homedir.isAbsolute() || !homedir.exists() || !homedir.isDirectory()) {
      throw new IOException("Hadoop home directory " + homedir + " does not exist, is not a directory, or is not an absolute path.");
    }
    home=homedir.getCanonicalPath();
  }
 catch (  IOException ioe) {
    if (LOG.isDebugEnabled()) {
      LOG.debug("Failed to detect a valid hadoop home directory",ioe);
    }
    home=null;
  }
  return home;
}

