/** 
 * In a completion like "$abc<caret> def" the element is a word psi lead element, in this case to not expand the autocompletion after the whitespace character https://code.google.com/p/bashsupport/issues/detail?id=51 a completion at the end of a line with an open string is parsed as string until the first quote in the next line(s) in the case of a newline character in the string the end offset is set to the end of the string to avoid aggressive string replacements
 */
private boolean fixReplacementOffsetInString(PsiElement element,OffsetMap offsetMap){
  int endCharIndex=StringUtils.indexOfAny(element.getText(),new char[]{'\n',' '});
  if (endCharIndex > 0) {
    offsetMap.addOffset(IDENTIFIER_END_OFFSET,element.getTextOffset() + endCharIndex);
    return true;
  }
  return false;
}

