private void purgeTombstones(){
  long currentSafeTombstonePurgeTime=peersSupplier.get().stream().map(id -> antiEntropyTimes.getOrDefault(id,0L)).reduce(Math::min).orElse(0L);
  if (currentSafeTombstonePurgeTime == previousTombstonePurgeTime) {
    return;
  }
  List<Map.Entry<String,MapValue>> tombStonesToDelete=items.entrySet().stream().filter(e -> e.getValue().isTombstone()).filter(e -> e.getValue().creationTime() <= currentSafeTombstonePurgeTime).collect(Collectors.toList());
  previousTombstonePurgeTime=currentSafeTombstonePurgeTime;
  tombStonesToDelete.forEach(entry -> items.remove(entry.getKey(),entry.getValue()));
}

