private void onWrapConstants(ClassEntity classEntity){
  Class<?> cls=nativeClass;
  while (cls != null && cls != Object.class) {
    List<Field> declaredFields=new ArrayList<>(Arrays.asList(cls.getDeclaredFields()));
    Arrays.stream(cls.getInterfaces()).filter(clazz -> !clazz.isAnnotationPresent(Ignore.class)).map(Class::getDeclaredFields).flatMap(Arrays::stream).forEach(declaredFields::add);
    for (    Field field : declaredFields) {
      if (field.isAnnotationPresent(Ignore.class)) {
        continue;
      }
      int mod=field.getModifiers();
      if (Modifier.isFinal(mod) && Modifier.isStatic(mod) && !Modifier.isPrivate(mod)) {
        try {
          field.setAccessible(true);
          classEntity.addConstant(new ConstantEntity(field.getName(),MemoryUtils.valueOf(field.get(null)),true));
        }
 catch (        IllegalAccessException e) {
          throw new RuntimeException(e);
        }
      }
    }
    cls=cls.getSuperclass();
  }
}

