public static boolean sortDictionary(String path){
  try {
    BufferedReader br=new BufferedReader(new InputStreamReader(IOUtil.newInputStream(path),"UTF-8"));
    TreeMap<String,String> map=new TreeMap<String,String>();
    String line;
    while ((line=br.readLine()) != null) {
      String[] param=line.split("\\s");
      map.put(param[0],line);
    }
    br.close();
    BufferedWriter bw=new BufferedWriter(new OutputStreamWriter(IOUtil.newOutputStream(path)));
    for (    Map.Entry<String,String> entry : map.entrySet()) {
      bw.write(entry.getValue());
      bw.newLine();
    }
    bw.close();
  }
 catch (  Exception e) {
    e.printStackTrace();
    return false;
  }
  return true;
}

private GlowBlock searchSourceBlockForHugeTree(GlowBlock block){
  GlowWorld world=block.getWorld();
  int sourceX=block.getX();
  int sourceY=block.getY();
  int sourceZ=block.getZ();
  int data=block.getData();
  for (int x=-1; x <= 0; x++) {
    for (int z=-1; z <= 0; z++) {
      GlowBlock b=world.getBlockAt(sourceX + x,sourceY,sourceZ + z);
      if (isMatchingSapling(b,data) && isMatchingSapling(b.getRelative(BlockFace.SOUTH),data) && isMatchingSapling(b.getRelative(BlockFace.EAST),data)&& isMatchingSapling(b.getRelative(BlockFace.SOUTH_EAST),data)) {
        return b;
      }
    }
  }
  return null;
}

