private static PyExpr convertIterableToPyExpr(Iterable<?> iterable,boolean asArray){
  List<String> values=new ArrayList<>();
  String leftDelimiter="[";
  String rightDelimiter="]";
  if (!asArray) {
    leftDelimiter="(";
    rightDelimiter=")";
  }
  for (  Object elem : iterable) {
    if (!(elem instanceof Number || elem instanceof String || elem instanceof PyExpr)) {
      throw new UnsupportedOperationException("Only Number, String and PyExpr is allowed");
    }
 else     if (elem instanceof Number) {
      values.add(String.valueOf(elem));
    }
 else     if (elem instanceof PyExpr) {
      values.add(((PyExpr)elem).getText());
    }
 else     if (elem instanceof String) {
      values.add("'" + elem + "'");
    }
  }
  String contents=Joiner.on(", ").join(values);
  if (values.size() == 1 && !asArray) {
    contents+=",";
  }
  return new PyListExpr(leftDelimiter + contents + rightDelimiter,Integer.MAX_VALUE);
}

@Override public void exportAsDrag(JComponent comp,InputEvent e,int action){
  int srcActions=getSourceActions(comp);
  if (!(e instanceof MouseEvent) || !(action == COPY || action == MOVE || action == LINK) || (srcActions & action) == 0) {
    action=NONE;
  }
  if (action != NONE && !GraphicsEnvironment.isHeadless()) {
    if (recognizer == null) {
      recognizer=new SwingDragGestureRecognizer();
    }
    DragHandler dgl=new DragHandler();
    try {
      recognizer.addDragGestureListener(dgl);
    }
 catch (    TooManyListenersException e1) {
      e1.printStackTrace();
    }
    recognizer.gestured(comp,(MouseEvent)e,srcActions,action);
    recognizer.removeDragGestureListener(dgl);
  }
 else {
    exportDone(comp,null,NONE);
  }
}

