@Override public RecordWriter getHiveRecordWriter(JobConf jc,Path finalOutPath,Class<? extends Writable> valueClass,boolean isCompressed,Properties tbl,Progressable progress) throws IOException {
  boolean usenewformat=jc.getBoolean("fdf.newformat",false);
  IHead head=new IHead(usenewformat ? ConstVar.NewFormatFile : ConstVar.OldFormatFile);
  boolean flag=true;
  if (flag) {
    String columnTypeProperty=tbl.getProperty(Constants.LIST_COLUMN_TYPES);
    ArrayList<TypeInfo> types;
    if (columnTypeProperty == null)     types=new ArrayList<TypeInfo>();
 else     types=TypeInfoUtils.getTypeInfosFromTypeString(columnTypeProperty);
    String compress=tbl.getProperty(ConstVar.Compress);
    String ifdfCompressionOn=jc.get(ConstVar.CompressionConfName);
    if ((ifdfCompressionOn != null && ifdfCompressionOn.equalsIgnoreCase("true")) || (compress != null && compress.equalsIgnoreCase("true"))) {
      head.setCompress((byte)1);
      String strCompressionMethod=jc.get(ConstVar.CompressionMethodConfName);
      if (strCompressionMethod != null) {
        try {
          byte compressionMethod=Byte.valueOf(strCompressionMethod).byteValue();
          head.setCompressStyle(compressionMethod);
        }
 catch (        NumberFormatException e) {
        }
      }
      String compressionLevel=jc.get(ConstVar.ZlibCompressionLevelConfName);
      if (compressionLevel != null) {
        if (compressionLevel.equalsIgnoreCase("bestSpeed")) {
          jc.set("zlib.compress.level",ZlibCompressor.CompressionLevel.BEST_SPEED.toString());
        }
 else         if (compressionLevel.equalsIgnoreCase("bestCompression")) {
          jc.set("zlib.compress.level",ZlibCompressor.CompressionLevel.BEST_COMPRESSION.toString());
        }
      }
    }
    IFieldMap map=new IFieldMap();
    int i=0;
    for (    TypeInfo type : types) {
      byte fdftype=0;
      String name=type.getTypeName();
      if (name.equals(Constants.TINYINT_TYPE_NAME))       fdftype=ConstVar.FieldType_Byte;
 else       if (name.equals(Constants.SMALLINT_TYPE_NAME))       fdftype=ConstVar.FieldType_Short;
 else       if (name.equals(Constants.INT_TYPE_NAME))       fdftype=ConstVar.FieldType_Int;
 else       if (name.equals(Constants.BIGINT_TYPE_NAME))       fdftype=ConstVar.FieldType_Long;
 else       if (name.equals(Constants.FLOAT_TYPE_NAME))       fdftype=ConstVar.FieldType_Float;
 else       if (name.equals(Constants.DOUBLE_TYPE_NAME))       fdftype=ConstVar.FieldType_Double;
 else       if (name.equals(Constants.STRING_TYPE_NAME))       fdftype=ConstVar.FieldType_String;
 else       if (name.equals(Constants.TIMESTAMP_TYPE_NAME))       fdftype=ConstVar.FieldType_String;
      map.addFieldType(new IRecord.IFType(fdftype,i++));
    }
    head.setFieldMap(map);
  }
  final IFormatDataFile ifdf=new IFormatDataFile(jc);
  ifdf.create(finalOutPath.toString(),head);
  return new RecordWriter(){
    @Override public void write(    Writable w) throws IOException {
      ifdf.addRecord((IRecord)w);
    }
    @Override public void close(    boolean abort) throws IOException {
      ifdf.close();
    }
  }
;
}

