/** 
 * Reads a sequence of bytes from a  {@link IoSession} into the given {@link IoBuffer}.  Is called when the session was found ready for reading.
 * @param session the session to read
 * @param buf the buffer to fill
 * @return the number of bytes read
 * @throws Exception any exception thrown by the underlying system calls
 */
protected abstract int read(T session,IoBuffer buf) throws Exception ;
private void read(T session){
  IoSessionConfig config=session.getConfig();
  IoBuffer buf=newReadBuffer(config.getReadBufferSize());
  final boolean hasFragmentation=session.getTransportMetadata().hasFragmentation();
  try {
    int readBytes=0;
    int ret;
    try {
      if (hasFragmentation) {
        while ((ret=read(session,buf)) > 0) {
          readBytes+=ret;
          if (!buf.hasRemaining()) {
            break;
          }
        }
      }
 else {
        ret=read(session,buf);
        if (ret > 0) {
          readBytes=ret;
        }
      }
    }
  finally {
      buf.flip();
    }
    if (readBytes > 0) {
      IoFilterChain filterChain=session.getFilterChain();
      filterChain.fireMessageReceived(buf);
      buf=null;
      if (hasFragmentation) {
        if (readBytes << 1 < config.getReadBufferSize()) {
          session.decreaseReadBufferSize();
        }
 else         if (readBytes == config.getReadBufferSize()) {
          session.increaseReadBufferSize();
        }
      }
    }
    if (ret < 0) {
      scheduleRemove(session);
    }
  }
 catch (  Throwable e) {
    if (e instanceof IOException) {
      if (!(e instanceof PortUnreachableException) || !AbstractDatagramSessionConfig.class.isAssignableFrom(config.getClass()) || ((AbstractDatagramSessionConfig)config).isCloseOnPortUnreachable())       scheduleRemove(session);
    }
    IoFilterChain filterChain=session.getFilterChain();
    filterChain.fireExceptionCaught(e);
  }
}

/** 
 * Appends a string representation of the given access modifiers to {@link #buf buf}.
 * @param access some access modifiers.
 */
void appendAccess(final int access){
  boolean first=true;
  if ((access & Opcodes.ACC_PUBLIC) != 0) {
    buf.append("ACC_PUBLIC");
    first=false;
  }
  if ((access & Opcodes.ACC_PRIVATE) != 0) {
    buf.append("ACC_PRIVATE");
    first=false;
  }
  if ((access & Opcodes.ACC_PROTECTED) != 0) {
    buf.append("ACC_PROTECTED");
    first=false;
  }
  if ((access & Opcodes.ACC_FINAL) != 0) {
    if (!first) {
      buf.append(" + ");
    }
    buf.append("ACC_FINAL");
    first=false;
  }
  if ((access & Opcodes.ACC_STATIC) != 0) {
    if (!first) {
      buf.append(" + ");
    }
    buf.append("ACC_STATIC");
    first=false;
  }
  if ((access & Opcodes.ACC_SYNCHRONIZED) != 0) {
    if (!first) {
      buf.append(" + ");
    }
    if ((access & ACCESS_CLASS) == 0) {
      buf.append("ACC_SYNCHRONIZED");
    }
 else {
      buf.append("ACC_SUPER");
    }
    first=false;
  }
  if ((access & Opcodes.ACC_VOLATILE) != 0 && (access & ACCESS_FIELD) != 0) {
    if (!first) {
      buf.append(" + ");
    }
    buf.append("ACC_VOLATILE");
    first=false;
  }
  if ((access & Opcodes.ACC_BRIDGE) != 0 && (access & ACCESS_CLASS) == 0 && (access & ACCESS_FIELD) == 0) {
    if (!first) {
      buf.append(" + ");
    }
    buf.append("ACC_BRIDGE");
    first=false;
  }
  if ((access & Opcodes.ACC_VARARGS) != 0 && (access & ACCESS_CLASS) == 0 && (access & ACCESS_FIELD) == 0) {
    if (!first) {
      buf.append(" + ");
    }
    buf.append("ACC_VARARGS");
    first=false;
  }
  if ((access & Opcodes.ACC_TRANSIENT) != 0 && (access & ACCESS_FIELD) != 0) {
    if (!first) {
      buf.append(" + ");
    }
    buf.append("ACC_TRANSIENT");
    first=false;
  }
  if ((access & Opcodes.ACC_NATIVE) != 0 && (access & ACCESS_CLASS) == 0 && (access & ACCESS_FIELD) == 0) {
    if (!first) {
      buf.append(" + ");
    }
    buf.append("ACC_NATIVE");
    first=false;
  }
  if ((access & Opcodes.ACC_ENUM) != 0 && ((access & ACCESS_CLASS) != 0 || (access & ACCESS_FIELD) != 0 || (access & ACCESS_INNER) != 0)) {
    if (!first) {
      buf.append(" + ");
    }
    buf.append("ACC_ENUM");
    first=false;
  }
  if ((access & Opcodes.ACC_ANNOTATION) != 0 && ((access & ACCESS_CLASS) != 0 || (access & ACCESS_INNER) != 0)) {
    if (!first) {
      buf.append(" + ");
    }
    buf.append("ACC_ANNOTATION");
    first=false;
  }
  if ((access & Opcodes.ACC_ABSTRACT) != 0) {
    if (!first) {
      buf.append(" + ");
    }
    buf.append("ACC_ABSTRACT");
    first=false;
  }
  if ((access & Opcodes.ACC_INTERFACE) != 0) {
    if (!first) {
      buf.append(" + ");
    }
    buf.append("ACC_INTERFACE");
    first=false;
  }
  if ((access & Opcodes.ACC_STRICT) != 0) {
    if (!first) {
      buf.append(" + ");
    }
    buf.append("ACC_STRICT");
    first=false;
  }
  if ((access & Opcodes.ACC_SYNTHETIC) != 0) {
    if (!first) {
      buf.append(" + ");
    }
    buf.append("ACC_SYNTHETIC");
    first=false;
  }
  if ((access & Opcodes.ACC_DEPRECATED) != 0) {
    if (!first) {
      buf.append(" + ");
    }
    buf.append("ACC_DEPRECATED");
    first=false;
  }
  if (first) {
    buf.append('0');
  }
}

public final void mLPAREN(boolean _createToken) throws RecognitionException, CharStreamException, TokenStreamException {
  int _ttype;
  Token _token=null;
  int _begin=text.length();
  _ttype=LPAREN;
  int _saveIndex;
  match('{');
  if (_createToken && _token == null && _ttype != Token.SKIP) {
    _token=makeToken(_ttype);
    _token.setText(new String(text.getBuffer(),_begin,text.length() - _begin));
  }
  _returnToken=_token;
}

