@Override public void onPreviewDrop(DragContext context) throws VetoDragException {
  Widget w=context.selectedWidgets.iterator().next();
  if (!(w instanceof WorkflowitemWidget)) {
    return;
  }
  Dtos.WorkflowitemDto droppedItem=((WorkflowitemWidget)w).getWorkflowitem();
  if (droppedItem.getId() != null && currentItem != null && currentItem.getId() != null) {
    if (droppedItem.getId().equals(currentItem.getId())) {
      throw new VetoDragException();
    }
    Dtos.WorkflowitemDto nextItem=findNextItem();
    if (nextItem != null && nextItem.getId() != null && droppedItem.getId().equals(nextItem.getId())) {
      throw new VetoDragException();
    }
  }
  super.onPreviewDrop(context);
}

public void search(IndexQuery query,String name,BTreeCallback callback) throws IOException, BTreeException {
  BTreeCallback cb=new SearchCallback(listDB,callback);
  if (query != null) {
    int op=query.getOperator();
    if (op == IndexQuery.EW || op == IndexQuery.NEW || op == IndexQuery.BWX) {
      query=new IndexQuery(IndexQuery.ANY,query.getValues());
      cb=new EndsWithCallback(op,new SearchCallback(listDB,callback),query.getValue(0));
    }
  }
  if (name == null) {
    if (indices != null) {
      Iterator<NameIndexer> i=indices.values().iterator();
      Logging.logCheckedDebug(LOG,"Searching all indexes");
      while (i.hasNext()) {
        NameIndexer index=i.next();
        index.query(query,new SearchCallback(listDB,callback));
      }
    }
  }
 else {
    NameIndexer indexer=indices.get(name);
    if (indexer == null)     return;
    Logging.logCheckedDebug(LOG,"Searching Index : ",name);
    indexer.query(query,cb);
  }
}

