/** 
 * Handles MIDlet foreground requests. <p> If proxy being updated belongs last MIDlet created in the proxy list, then put the MIDlet in the foreground. <p> If there is no foreground MIDlet or the foreground MIDlet does not want the foreground or the foreground MIDlet is paused, then put the MIDlet in the foreground.
 * @param midlet The proxy of the MIDlet that was updated
 * @return Proxy of the next foreground MIDlet, may be the foregroundMIDlet if the foreground should not change
 */
MIDletProxy foregroundRequest(MIDletProxy midlet){
  MIDletProxy foreground;
  if (midlet == lastMidletCreated) {
    return midlet;
  }
  foreground=midletProxyList.getForegroundMIDlet();
  if (foreground == null || !foreground.wantsForeground() || foreground.getMidletState() == MIDletProxy.MIDLET_PAUSED) {
    return midlet;
  }
  return foreground;
}

