public static void reduce23(int[] z){
  int z16=z[16];
  int c=Nat.addWordTo(16,z16 >>> 9,z) + (z16 & P16);
  if (c > P16 || (c == P16 && Nat.eq(16,z,P))) {
    c+=Nat.inc(16,z);
    c&=P16;
  }
  z[16]=c;
}

