private void sendPublicKey(XMPPResourceConnection session,Packet packet,Queue<Packet> results) throws PacketErrorTypeException, TigaseDBException {
  BareJID user=packet.getStanzaTo().getBareJID();
  String fingerprint;
  try {
    fingerprint=KontalkAuth.getUserFingerprint(session,user);
  }
 catch (  UserNotFoundException e) {
    fingerprint=null;
  }
  if (fingerprint != null) {
    try {
      byte[] publicKeyData=KontalkKeyring.getInstance(session.getDomainAsJID().toString()).exportKey(fingerprint);
      if (publicKeyData != null) {
        Element pubkey=new Element("pubkey");
        pubkey.setXMLNS(XMLNS);
        pubkey.setCData(Base64.encode(publicKeyData));
        results.offer(packet.okResult(pubkey,0));
      }
 else {
        throw new IOException("Public key not found");
      }
    }
 catch (    IOException|PGPException e) {
      log.log(Level.WARNING,"Unable to export key for user {0} (fingerprint: {1})",new Object[]{user,fingerprint});
      results.offer(Authorization.INTERNAL_SERVER_ERROR.getResponseMessage(packet,"Unable to process public key.",true));
    }
  }
 else {
    results.offer(Authorization.ITEM_NOT_FOUND.getResponseMessage(packet,"Public key not found.",true));
  }
}

