private boolean handleFile(File tempFile){
  File appendedFile=null;
  File actualFile=new File(tempFile.getPath().substring(0,tempFile.getPath().lastIndexOf(".")));
  Timber.d("ACTUAL FILE: " + actualFile.getAbsolutePath());
  long fileSize=0;
  if (tempFile.getName().contains(scal.io.liger.Constants.MAIN)) {
    fileSize=indexItem.getExpansionFileSize();
  }
 else   if (tempFile.getName().contains(scal.io.liger.Constants.PATCH)) {
    fileSize=indexItem.getPatchFileSize();
  }
 else {
    Timber.e("CAN'T DETERMINE FILE SIZE FOR " + tempFile.getName() + " (NOT A MAIN OR PATCH FILE)");
    return false;
  }
  if (tempFile.exists()) {
    if (tempFile.length() == 0) {
      Timber.e("FINISHED DOWNLOAD OF " + tempFile.getPath() + " BUT IT IS A ZERO BYTE FILE");
      return false;
    }
 else     if (tempFile.length() < fileSize) {
      Timber.e("FINISHED DOWNLOAD OF " + tempFile.getPath() + " BUT IT IS TOO SMALL: "+ Long.toString(tempFile.length())+ "/"+ Long.toString(fileSize));
      appendedFile=managePartialFile(tempFile);
      if (appendedFile == null) {
        Timber.e("ERROR WHILE APPENDING TO PARTIAL FILE FOR " + tempFile.getPath());
        return false;
      }
 else       if (appendedFile.length() < fileSize) {
        Timber.e("APPENDED FILE " + appendedFile.getPath() + " IS STILL TOO SMALL: "+ Long.toString(appendedFile.length())+ "/"+ Long.toString(fileSize));
        return false;
      }
 else {
        Timber.d("APPENDED FILE " + appendedFile.getPath() + " IS COMPLETE!");
        Utils.toastOnUiThread((Activity)context,context.getString(R.string.finished_downloading) + " " + indexItem.getTitle()+ ".",false);
        sendDownloadCompleteMessage(indexItem.getExpansionId());
      }
    }
 else {
      Timber.d("FINISHED DOWNLOAD OF " + tempFile.getPath() + " AND FILE LOOKS OK");
      Utils.toastOnUiThread((Activity)context,context.getString(R.string.finished_downloading) + " " + indexItem.getTitle()+ ".",false);
      sendDownloadCompleteMessage(indexItem.getExpansionId());
    }
  }
 else {
    Timber.e("FINISHED DOWNLOAD OF " + tempFile.getPath() + " BUT IT DOES NOT EXIST");
    return false;
  }
  try {
    File directory=new File(actualFile.getParent());
    String nameFilter="";
    if (actualFile.getName().contains(indexItem.getExpansionFileVersion())) {
      nameFilter=actualFile.getName().replace(indexItem.getExpansionFileVersion(),"*");
    }
 else {
      nameFilter=actualFile.getName();
    }
    Timber.d("CLEANUP: DELETING " + nameFilter + " FROM "+ directory.getPath());
    WildcardFileFilter oldFileFilter=new WildcardFileFilter(nameFilter);
    for (    File oldFile : FileUtils.listFiles(directory,oldFileFilter,null)) {
      Timber.d("CLEANUP: FOUND " + oldFile.getPath() + ", DELETING");
      FileUtils.deleteQuietly(oldFile);
    }
    if ((appendedFile != null) && appendedFile.exists()) {
      FileUtils.moveFile(appendedFile,actualFile);
      FileUtils.deleteQuietly(appendedFile);
      FileUtils.deleteQuietly(tempFile);
      Timber.d("MOVED PART FILE " + appendedFile.getPath() + " TO "+ actualFile.getPath());
    }
 else     if (tempFile.exists()) {
      FileUtils.moveFile(tempFile,actualFile);
      FileUtils.deleteQuietly(tempFile);
      Timber.d("MOVED TEMP FILE " + tempFile.getPath() + " TO "+ actualFile.getPath());
    }
 else {
      Timber.e(".TMP AND .PART FILES DO NOT EXIST FOR " + tempFile.getPath());
      return false;
    }
  }
 catch (  IOException ioe) {
    Timber.e("ERROR DURING CLEANUP/MOVING TEMP FILE: " + ioe.getMessage());
    return false;
  }
  ZipHelper.clearCache();
  return true;
}

/** 
 * Service an incoming request to reset the sequencer.
 */
@ServerHandler(type=CorfuMsgType.BOOTSTRAP_SEQUENCER) public void resetServer(CorfuPayloadMsg<SequencerRecoveryMsg> msg,ChannelHandlerContext ctx,IServerRouter r){
  log.info("Reset sequencer server.");
  long initialToken=msg.getPayload().getGlobalTail();
  final Map<UUID,StreamAddressSpace> addressSpaceMap=msg.getPayload().getStreamsAddressMap();
  final long bootstrapMsgEpoch=msg.getPayload().getSequencerEpoch();
  final boolean bootstrapWithoutTailsUpdate=msg.getPayload().getBootstrapWithoutTailsUpdate();
  if (bootstrapWithoutTailsUpdate && (sequencerEpoch == Layout.INVALID_EPOCH || bootstrapMsgEpoch != sequencerEpoch + 1)) {
    log.warn("Cannot update existing sequencer. Require full bootstrap. SequencerEpoch : {}, MsgEpoch : {}",sequencerEpoch,bootstrapMsgEpoch);
    r.sendResponse(ctx,msg,CorfuMsgType.NACK.msg());
    return;
  }
  if (serverContext.getSequencerEpoch() >= bootstrapMsgEpoch) {
    log.info("Sequencer already bootstrapped at epoch {}. Discarding bootstrap request with epoch {}",sequencerEpoch,bootstrapMsgEpoch);
    r.sendResponse(ctx,msg,CorfuMsgType.NACK.msg());
    return;
  }
  if (!bootstrapWithoutTailsUpdate) {
    cache.invalidateAll();
    globalLogTail=initialToken;
    cache.updateMaxConflictAddress(initialToken - 1);
    streamTailToGlobalTailMap=new HashMap<>();
    for (    Map.Entry<UUID,StreamAddressSpace> streamAddressSpace : addressSpaceMap.entrySet()) {
      Long streamTail=streamAddressSpace.getValue().getTail();
      log.trace("On Sequencer reset, tail for stream {} set to {}",streamAddressSpace.getKey(),streamTail);
      streamTailToGlobalTailMap.put(streamAddressSpace.getKey(),streamTail);
    }
    this.streamsAddressMap=new HashMap<>();
    this.streamsAddressMap.putAll(addressSpaceMap);
    for (    Map.Entry<UUID,StreamAddressSpace> streamAddressSpace : this.streamsAddressMap.entrySet()) {
      log.info("Stream[{}] set to last trimmed address {} and {} addresses in the range [{}-{}], " + "on sequencer reset.",Utils.toReadableId(streamAddressSpace.getKey()),streamAddressSpace.getValue().getTrimMark(),streamAddressSpace.getValue().getAddressMap().getLongCardinality(),streamAddressSpace.getValue().getLowestAddress(),streamAddressSpace.getValue().getHighestAddress());
      if (log.isTraceEnabled()) {
        log.trace("Stream[{}] address map on sequencer reset: {}",Utils.toReadableId(streamAddressSpace.getKey()),streamAddressSpace.getValue().getAddressMap());
      }
    }
  }
  if (epochRangeLowerBound == Layout.INVALID_EPOCH || bootstrapMsgEpoch != sequencerEpoch + 1) {
    epochRangeLowerBound=bootstrapMsgEpoch;
  }
  sequencerEpoch=bootstrapMsgEpoch;
  serverContext.setSequencerEpoch(bootstrapMsgEpoch);
  log.info("Sequencer reset with token = {}, size {} streamTailToGlobalTailMap = {}, sequencerEpoch = {}",globalLogTail,streamTailToGlobalTailMap.size(),streamTailToGlobalTailMap,sequencerEpoch);
  r.sendResponse(ctx,msg,CorfuMsgType.ACK.msg());
}

