boolean isInvalidating(JSType type){
  if (type == null || type.isUnknownType() || type.isEmptyType()) {
    return true;
  }
  if (type.isUnionType()) {
    type=type.restrictByNotNullOrUndefined();
    if (type.isUnionType()) {
      for (      JSType alt : type.getUnionMembers()) {
        if (isInvalidating(alt)) {
          return true;
        }
      }
      return false;
    }
  }
  ObjectType objType=type.toMaybeObjectType();
  if (objType == null) {
    return !allowScalars;
  }
  return types.contains(objType) || objType.isAmbiguousObject() || (!allowEnums && objType.isEnumType())|| (!allowScalars && objType.isBoxableScalar());
}

