        pss.setString(9,forWho);
        pss.setString(10,db);
        pss.setString(11,tblName);
        pss.addBatch();
        needInsertCount++;
      }
    }
    if (needInsertCount > 0) {
      pss.executeBatch();
    }
    con.commit();
    success=true;
  }
 catch (  SQLException ex) {
    ex.printStackTrace();
    LOG.error("grant auth on db error, forWho=" + forWho + ", db="+ db+ ", tbl="+ tbl+ ", msg="+ ex.getMessage());
    LOG.error(ex.getMessage());
  }
 finally {
    if (!success) {
      try {
        con.rollback();
      }
 catch (      SQLException e) {
      }
    }
    closeStatement(ps);
    closeStatement(pss);
    closeConnection(con);
  }
