protected SchemaBasedEdmProvider addToEdmProvider(SchemaBasedEdmProvider provider,XMLEventReader reader,ReferenceResolver resolver,boolean loadCore,boolean useLocal,boolean loadReferenceSchemas,String namespace) throws XMLStreamException {
  final StringBuilder xmlBase=new StringBuilder();
  new ElementReader<SchemaBasedEdmProvider>(){
    @Override void build(    XMLEventReader reader,    StartElement element,    SchemaBasedEdmProvider provider,    String name) throws XMLStreamException {
      if (attrNS(element,XML_LINK_NS,"base") != null) {
        xmlBase.append(attrNS(element,XML_LINK_NS,"base"));
      }
      String version=attr(element,"Version");
      if ("4.0".equals(version)) {
        readDataServicesAndReference(reader,element,provider);
      }
 else {
        throw new XMLStreamException("Currently only V4 is supported.");
      }
    }
  }
.read(reader,null,provider,"Edmx");
  if (reader.hasNext()) {
    XMLEvent event=reader.peek();
    throw new XMLStreamException("Failed to read complete metadata file. Failed at " + (event.isStartElement() ? event.asStartElement().getName().getLocalPart() : event.asEndElement().getName().getLocalPart()));
  }
  if (loadCore) {
    loadCoreVocabulary(provider,"Org.OData.Core.V1");
    loadCoreVocabulary(provider,"Org.OData.Capabilities.V1");
    loadCoreVocabulary(provider,"Org.OData.Measures.V1");
  }
  if (namespace != null && !namespace.equals("") && !globalReferenceMap.containsKey(namespace)) {
    globalReferenceMap.put(namespace,provider);
  }
  if (resolver != null && loadReferenceSchemas) {
    loadReferencesSchemas(provider,xmlBase.length() == 0 ? null : fixXmlBase(xmlBase.toString()),resolver,loadCore,useLocal);
  }
  return provider;
}

