@Override public void run(){
  while (true) {
    try {
      if (socketChannel == null) {
        previousConnectionState=false;
        onConnectionLost();
      }
 else {
        if (!previousConnectionState && socketChannel.isConnected()) {
          previousConnectionState=true;
          onConnectionResumed();
        }
        if (previousConnectionState && !socketChannel.isConnected() && !socketChannel.isConnectionPending()) {
          previousConnectionState=false;
          onConnectionLost();
        }
        if (!socketChannel.isConnectionPending() && !socketChannel.isConnected()) {
          previousConnectionState=false;
          logger.debug("Disconnecting '{}' because of a network error",getThing().getUID());
          socketChannel.close();
          Thread.sleep(1000 * ((BigDecimal)getConfig().get(RECONNECT_INTERVAL)).intValue());
          establishConnection();
        }
        long stamp=System.currentTimeMillis();
        if (!InetAddress.getByName(((String)getConfig().get(IP_ADDRESS))).isReachable(((BigDecimal)getConfig().get(PING_TIME_OUT)).intValue())) {
          logger.debug("Ping timed out after '{}' milliseconds. Disconnecting '{}' because of a ping timeout",System.currentTimeMillis() - stamp,getThing().getUID());
          socketChannel.close();
        }
        onConnectable();
        ByteBuffer buffer=onReadable(((BigDecimal)getConfig().get(BUFFER_SIZE)).intValue(),false);
        if (buffer != null && buffer.remaining() > 0) {
          onRead(buffer);
        }
      }
      onAcceptable();
      if (!Thread.currentThread().isInterrupted()) {
        Thread.sleep(LISTENING_INTERVAL);
      }
 else {
        return;
      }
    }
 catch (    IOException e) {
      logger.trace("An exception occurred while polling the transceiver : '{}'",e.getMessage(),e);
    }
catch (    InterruptedException e) {
      Thread.currentThread().interrupt();
      return;
    }
  }
