      Iterator<IConstructorType> iter=listConstructorTypes.iterator();
      while (iter.hasNext()) {
        IConstructorType next=iter.next();
        IConstructorInfo constructor=next.getConstructor();
        if (!(constructor instanceof ConstructorInfoBuilder.IBuilt && ((ConstructorInfoBuilder.IBuilt)constructor).getUserData() == AnnotationConstructorGenerator.STANDARD_CTOR_WITH_DEFAULT_PARAM_VALUES)) {
          iter.remove();
        }
      }
    }
 else {
      Iterator<IConstructorType> iter=listConstructorTypes.iterator();
