    for (    Map.Entry<?,?> entry : m.entrySet()) {
      Object k, v;
      if (entry == null || (k=entry.getKey()) == null || (v=entry.getValue()) == null) {
        npe=true;
        break;
      }
      int h=spread(k.hashCode());
      for (Node[] tab=table; ; ) {
        int i;
        Node f;
        int fh;
        Object fk;
        if (tab == null)         tab=initTable();
 else         if ((f=tabAt(tab,i=(tab.length - 1) & h)) == null) {
          if (casTabAt(tab,i,null,new Node(h,k,v,null))) {
            ++delta;
            break;
          }
        }
 else         if ((fh=f.hash) == MOVED) {
          if ((fk=f.key) instanceof TreeBin) {
            TreeBin t=(TreeBin)fk;
            boolean validated=false;
            t.acquire(0);
            try {
              if (tabAt(tab,i) == f) {
                validated=true;
                TreeNode p=t.getTreeNode(h,k,t.root);
                if (p != null)                 p.val=v;
 else {
                  t.putTreeNode(h,k,v);
                  ++delta;
                }
              }
            }
  finally {
              t.release(0);
            }
            if (validated)             break;
          }
 else           tab=(Node[])fk;
        }
 else         if ((fh & LOCKED) != 0) {
          counter.add(delta);
          delta=0L;
          checkForResize();
          f.tryAwaitLock(tab,i);
        }
 else         if (f.casHash(fh,fh | LOCKED)) {
          int count=0;
          try {
            if (tabAt(tab,i) == f) {
              count=1;
              for (Node e=f; ; ++count) {
                Object ek, ev;
                if ((e.hash & HASH_BITS) == h && (ev=e.val) != null && ((ek=e.key) == k || k.equals(ek))) {
                  e.val=v;
                  break;
                }
                Node last=e;
                if ((e=e.next) == null) {
                  ++delta;
                  last.next=new Node(h,k,v,null);
                  if (count >= TREE_THRESHOLD)                   replaceWithTreeBin(tab,i,k);
                  break;
                }
              }
            }
          }
  finally {
            if (!f.casHash(fh | LOCKED,fh)) {
              f.hash=fh;
synchronized (f) {
                f.notifyAll();
              }
              ;
            }
          }
          if (count != 0) {
            if (count > 1) {
              counter.add(delta);
              delta=0L;
              checkForResize();
            }
            break;
          }
        }
      }
    }
  }
  finally {
    if (delta != 0)     counter.add(delta);
  }
  if (npe)   throw new NullPointerException();
}

