private Token expect(String item){
  return expect(item,null);
}
private Token expect(String item,String alternative){
  if (iToken >= typeInfoTokens.size()) {
    throw new IllegalArgumentException("Error: " + item + " expected at the end of '"+ typeInfoString+ "'");
  }
  Token t=typeInfoTokens.get(iToken);
  if (item.equals("type")) {
    if (!Constants.LIST_TYPE_NAME.equals(t.text) && !Constants.MAP_TYPE_NAME.equals(t.text) && !Constants.STRUCT_TYPE_NAME.equals(t.text)&& !Constants.UNION_TYPE_NAME.equals(t.text)&& !Constants.BYTEARRAY_NAME.equals(t.text)&& null == PrimitiveObjectInspectorUtils.getTypeEntryFromTypeName(t.text) && !t.text.equals(alternative)) {
      throw new IllegalArgumentException("Error: " + item + " expected at the position "+ t.position+ " of '"+ typeInfoString+ "' but '"+ t.text+ "' is found.");
    }
  }
 else   if (item.equals("name")) {
    if (!t.isType && !t.text.equals(alternative)) {
      throw new IllegalArgumentException("Error: " + item + " expected at the position "+ t.position+ " of '"+ typeInfoString+ "' but '"+ t.text+ "' is found.");
    }
  }
 else {
    if (!item.equals(t.text) && !t.text.equals(alternative)) {
      throw new IllegalArgumentException("Error: " + item + " expected at the position "+ t.position+ " of '"+ typeInfoString+ "' but '"+ t.text+ "' is found.");
    }
  }
  iToken++;
  return t;
}

