/** 
 * Reformats a string where lines that are longer than <tt>width</tt> <p/> are split apart at the earliest wordbreak or at maxLength, whichever is <p/> sooner. If the width specified is less than 5 or greater than the input <p/> Strings length the string will be returned as is. <p/> <p/> <p/> Please note that this method can be lossy - trailing spaces on wrapped <p/> lines may be trimmed.
 * @param input the String to reformat.
 * @param width the maximum length of any one line.
 * @param locale of the string to be wrapped.
 * @return a new String with reformatted as needed.
 */
public static String wordWrap(String input,int width,Locale locale){
  if (input == null) {
    return "";
  }
 else   if (width < 5) {
    return input;
  }
 else   if (width >= input.length()) {
    return input;
  }
  StringBuilder buf=new StringBuilder(input);
  boolean endOfLine=false;
  int lineStart=0;
  for (int i=0; i < buf.length(); i++) {
    if (buf.charAt(i) == '\n') {
      lineStart=i + 1;
      endOfLine=true;
    }
    if (i > lineStart + width - 1) {
      if (!endOfLine) {
        int limit=i - lineStart - 1;
        BreakIterator breaks=BreakIterator.getLineInstance(locale);
        breaks.setText(buf.substring(lineStart,i));
        int end=breaks.last();
        if (end == limit + 1) {
          if (!Character.isWhitespace(buf.charAt(lineStart + end))) {
            end=breaks.preceding(end - 1);
          }
        }
        if (end != BreakIterator.DONE && end == limit + 1) {
          buf.replace(lineStart + end,lineStart + end + 1,"\n");
          lineStart=lineStart + end;
        }
 else         if (end != BreakIterator.DONE && end != 0) {
          buf.insert(lineStart + end,'\n');
          lineStart=lineStart + end + 1;
        }
 else {
          buf.insert(i,'\n');
          lineStart=i + 1;
        }
      }
 else {
        buf.insert(i,'\n');
        lineStart=i + 1;
        endOfLine=false;
      }
    }
  }
  return buf.toString();
}

