/** 
 * Check the key usage, extended key usage and validity of a certificate.
 * @param cert certificate to check
 * @param keyUsage -1 to not check the key usage extension, ora key usage bit mask to check for if the extension is present
 * @param extKeyUsage -1 to not check the extended key usage extension, ora extended key usage bit mask to check for if the extension is present
 * @exception CertificateException if there is an error
 */
private static void checkKeyUsageAndValidity(X509Certificate cert,int keyUsage,int extKeyUsage) throws CertificateException {
  int certKeyUsage;
  cert.checkExtensions();
  certKeyUsage=cert.getKeyUsage();
  if (keyUsage != -1 && certKeyUsage != -1 && (certKeyUsage & keyUsage) != keyUsage) {
    throw new CertificateException(cert,CertificateException.INAPPROPRIATE_KEY_USAGE);
  }
  certKeyUsage=cert.getExtKeyUsage();
  if (extKeyUsage != -1 && certKeyUsage != -1 && (certKeyUsage & extKeyUsage) != extKeyUsage) {
    throw new CertificateException(cert,CertificateException.INAPPROPRIATE_KEY_USAGE);
  }
  cert.checkValidity();
}

