      editor1.removeContentAndUnrender();
    }
 else {
      editor1.removeContent();
    }
    doc1.replaceOutgoingSink(editor1Sink);
  }
  if (newLevel == Level.SHELVED) {
    doc1.setShelved();
  }
 else   if (newLevel == Level.EDITING) {
