  }
 else {
    assert newLevel == Level.RENDERED || newLevel == Level.INTERACTIVE;
    if (newLevel == Level.RENDERED) {
      doc1.setRendering();
    }
 else {
      doc1.setInteractive(displayDoc1);
    }
  }
