 else   if (doc1.getLevel() == Level.SHELVED) {
    for (    ContentNode n : DocIterate.deep(doc1.getFullContentView(),doc1.getFullContentView().getDocumentElement(),null)) {
      assert n.getImplNodelet() == null;
    }
  }
}

