/** 
 * Since this pass reports errors only when a global  {@code this} keywordis encountered, there is no reason to traverse non global contexts.
 */
@Override public boolean shouldTraverse(NodeTraversal t,Node n,Node parent){
  if (n.isFunction()) {
    if (n.isArrowFunction()) {
      return true;
    }
    JSDocInfo jsDoc=NodeUtil.getBestJSDocInfo(n);
    if (jsDoc != null && (jsDoc.isConstructor() || jsDoc.isInterface() || jsDoc.hasThisType()|| jsDoc.isOverride())) {
      return false;
    }
    if (jsDoc != null) {
      JSTypeExpression functionType=jsDoc.getType();
      if (functionType != null) {
        Node functionNode=functionType.getRoot();
        if (functionNode != null && functionNode.isFunction()) {
          Node thisNode=functionNode.getFirstChild();
          if (thisNode != null && thisNode.isThis()) {
            return false;
          }
        }
      }
    }
    Token pType=parent.getToken();
    if (!(pType == Token.BLOCK || pType == Token.SCRIPT || pType == Token.NAME || pType == Token.ASSIGN || pType == Token.STRING_KEY)) {
      return false;
    }
    Node grandparent=parent.getParent();
    if (NodeUtil.mayBeObjectLitKey(parent)) {
      JSDocInfo maybeLends=grandparent.getJSDocInfo();
      if (maybeLends != null && maybeLends.hasLendsName() && maybeLends.getLendsName().getRoot().getString().endsWith(".prototype")) {
        return false;
      }
    }
  }
  if (parent != null && parent.isAssign()) {
    Node lhs=parent.getFirstChild();
    if (n == lhs) {
      if (assignLhsChild == null) {
        assignLhsChild=lhs;
      }
    }
 else {
      if (NodeUtil.isGet(lhs)) {
        if (lhs.isGetProp() && lhs.getLastChild().getString().equals("prototype")) {
          return false;
        }
        Node llhs=lhs.getFirstChild();
        if (llhs.isGetProp() && llhs.getLastChild().getString().equals("prototype")) {
          return false;
        }
      }
    }
  }
  return true;
}

