 * Give to the given  {@link LineProcessor} all lines in which all columnsare aligned. <p><strong>IMPORTANT:</strong> The array - pos - should have as many columns as the table has. Each column can contain either  {@link LargeAsciiTable#LEFT LEFT}, {@link LargeAsciiTable#CENTER CENTER} or{@link LargeAsciiTable#RIGHT RIGHT}. </p> <ul> <li> If the array contains only ONE item, it will be used for every column. </li> <li> If the array contains less items than columns to align, the last item will be used for all the non-specified alignment. </li> <li> If no alignment at all is specified, the {@link LargeAsciiTable#LEFT LEFT} alignment will be used.</li> </ul> <p><em><strong>Note:</strong> This function does nothing and returns <code>-1</code> if no {@link LineProcessor} is provided.</em></p>
 * @param lineProc	The action to perform on each line.
 * @param pos		Array of flags, indicating how each column should bejustified.
 * @param newsep	Separator to use, replacing the original one.
 * @return	Number of <em>successfully</em> processed lines.<em>This number could be compared to the value returned by {@link #size()} in order to know whether all lines weresuccessfully aligned and processed.</em>
 * @throws IllegalStateException	If this {@link LargeAsciiTable} is notcomplete (i.e. if  {@link #endTable()}has not been called before this function).
 * @throws InterruptedException		If the current thread has beeninterrupted. <em>This interruption is useful to stop this alignment operation whenever it becomes time and memory consuming.</em>
 * @throws LineProcessorException	If there was an error while processinga line. <em>A such exception is generally thrown by the given  {@link LineProcessor}.</em>
 * @throws IOException				If there is any error while accessingthe buffer file, or while processing a line (if this processing implies I/O).
 */
public final long streamAligned(final LineProcessor lineProc,final int[] pos,final char newsep) throws IllegalStateException, LineProcessorException, IOException, InterruptedException {
  return streamAligned(lineProc,pos,newsep,null);
}
/** 
 * Give to the given  {@link LineProcessor} all lines in which all columnsare aligned. <p><strong>IMPORTANT:</strong> The array - pos - should have as many columns as the table has. Each column can contain either  {@link LargeAsciiTable#LEFT LEFT}, {@link LargeAsciiTable#CENTER CENTER} or{@link LargeAsciiTable#RIGHT RIGHT}. </p> <ul> <li> If the array contains only ONE item, it will be used for every column. </li> <li> If the array contains less items than columns to align, the last item will be used for all the non-specified alignment. </li> <li> If no alignment at all is specified, the {@link LargeAsciiTable#LEFT LEFT} alignment will be used.</li> </ul> <p><em><strong>Note:</strong> This function does nothing and returns <code>-1</code> if no {@link LineProcessor} is provided.</em></p>
 * @param lineProc	The action to perform on each line.
 * @param pos		Array of flags, indicating how each column should bejustified.
 * @param newsep	Separator to use, replacing the original one.
 * @param thread	Thread to watch. If it is interrupted, this task shouldbe as well.
 * @return	Number of <em>successfully</em> processed lines.<em>This number could be compared to the value returned by {@link #size()} in order to know whether all lines weresuccessfully aligned and processed.</em>
 * @throws IllegalStateException	If this {@link LargeAsciiTable} is notcomplete (i.e. if  {@link #endTable()}has not been called before this function).
 * @throws InterruptedException		If the current thread has beeninterrupted. <em>This interruption is useful to stop this alignment operation whenever it becomes time and memory consuming.</em>
 * @throws LineProcessorException	If there was an error while processinga line. <em>A such exception is generally thrown by the given  {@link LineProcessor}.</em>
 * @throws IOException				If there is any error while accessingthe buffer file, or while processing a line (if this processing implies I/O).
 */
public long streamAligned(final LineProcessor lineProc,final int[] pos,char newsep,final Thread thread) throws IllegalStateException, LineProcessorException, IOException, InterruptedException {
  if (lineProc == null)   return -1;
  if (newsep == csep)   newsep='\0';
  long nbTotalLines=0;
  try (AsciiTableIterator itLines=getIterator()){
    StringBuffer buf=new StringBuffer();
    String line;
    int p0, p1, col, fldsize, colsize, n1, inserted;
    int uniqueJustif;
    long numLine=0;
    if (pos == null || pos.length == 0)     uniqueJustif=LEFT;
 else     uniqueJustif=(pos.length == 1) ? pos[0] : -1;
    while (itLines.hasNext()) {
      if (Thread.currentThread().isInterrupted() || (thread != null && thread.isInterrupted()))       throw new InterruptedException();
      buf.delete(0,buf.length());
      line=itLines.next();
      p0=0;
      col=0;
      for (col=0; col < sizes.length; col++) {
        if (col > 0)         buf.append(sep);
        if (col == sizes.length - 1)         p1=line.length();
 else {
          p1=line.indexOf(sep,p0);
          if (p1 < 0)           p1=line.length();
        }
        fldsize=p1 - p0;
        if (fldsize < 0)         break;
        colsize=sizes[col];
        inserted=colsize - fldsize;
        if (inserted < 0)         inserted=0;
        int justif;
        if (numLine < headerSize)         justif=CENTER;
 else         if (uniqueJustif >= 0)         justif=uniqueJustif;
 else         if (col >= pos.length)         justif=pos[pos.length - 1];
 else         justif=pos[col];
switch (justif) {
case LEFT:
default :
          buf.append(line.substring(p0,p1));
        addspaces(buf,inserted);
      break;
case CENTER:
    n1=(inserted) / 2;
  addspaces(buf,n1);
buf.append(line.substring(p0,p1));
addspaces(buf,inserted - n1);
break;
case RIGHT:
addspaces(buf,inserted);
buf.append(line.substring(p0,p1));
break;
}
p0=p1 + 1;
}
if (lineProc.process((newsep != '\0') ? buf.toString().replace(csep,newsep) : buf.toString())) nbTotalLines++;
numLine++;
if (numLine > 0 && numLine == headerSize) {
buf.delete(0,buf.length());
for (int k=0; k < sizes.length; k++) {
if (k > 0) buf.append((newsep != '\0') ? newsep : csep);
addHsep(buf,sizes[k]);
}
if (headerPostfix != null) buf.append(headerPostfix);
if (lineProc.process(buf.toString())) nbTotalLines++;
}
}
}
 return nbTotalLines;
}

