@Override public void visit(NodeTraversal t,Node node,Node parent){
switch (node.getToken()) {
case LET:
case CONST:
case VAR:
    for (Node child=node.getFirstChild(); child != null; child=child.getNext()) {
      identifyEnumOrTypedefDeclaration(t,child,child.getFirstChild(),NodeUtil.getBestJSDocInfo(child));
    }
  break;
case EXPR_RESULT:
Node firstChild=node.getFirstChild();
if (firstChild.isAssign()) {
Node assign=firstChild;
identifyEnumOrTypedefDeclaration(t,assign.getFirstChild(),assign.getSecondChild(),assign.getJSDocInfo());
}
 else if (firstChild.isGetProp()) {
identifyEnumOrTypedefDeclaration(t,firstChild,null,firstChild.getJSDocInfo());
}
break;
default :
break;
}
}
@Override public final void visit(NodeTraversal t,Node n,Node parent){
  inputId=t.getInputId();
  if (parent != null) {
    attachLiteralTypes(n);
    visitPostorder(t,n,parent);
    if (deferredActions.containsKey(n)) {
      deferredActions.removeAll(n).stream().forEach(Runnable::run);
    }
  }
 else   if (!deferredActions.isEmpty()) {
    deferredActions.values().stream().forEach(Runnable::run);
  }
}
@Override public void visit(NodeTraversal t,Node n,Node parent){
  if (t.inGlobalScope()) {
    return;
  }
  Scope containerScope=(Scope)t.getClosestContainerScope();
  if ((n.isReturn() && n.hasChildren()) || (NodeUtil.isBlocklessArrowFunctionResult(n))) {
    functionsWithNonEmptyReturns.add(containerScope.getRootNode());
  }
  if (n.isName() && NodeUtil.isLValue(n) && !NodeUtil.isBleedingFunctionName(n)) {
    String name=n.getString();
    Scope scope=t.getScope();
    Var var=scope.getVar(name);
    if (var != null) {
      Scope ownerScope=var.getScope();
      if (ownerScope.isLocal()) {
        ScopedName scopedName=ScopedName.of(name,ownerScope.getRootNode());
        assignedVarNames.add(scopedName);
        if (!containerScope.hasSameContainerScope(ownerScope)) {
          escapedVarNames.add(scopedName);
        }
      }
    }
  }
 else   if (n.isGetProp() && n.isUnscopedQualifiedName() && NodeUtil.isLValue(n)) {
    String name=NodeUtil.getRootOfQualifiedName(n).getString();
    Scope scope=t.getScope();
    Var var=scope.getVar(name);
    if (var != null) {
      Scope ownerScope=var.getScope();
      if (ownerScope.isLocal() && !containerScope.hasSameContainerScope(ownerScope)) {
        escapedVarNames.add(ScopedName.of(n.getQualifiedName(),ownerScope.getRootNode()));
      }
    }
  }
}

public void forward(String relativeUrlPath) throws ServletException, IOException {
  try {
    out.clear();
  }
 catch (  IOException ex) {
    IllegalStateException ise=new IllegalStateException(Localizer.getMessage("jsp.error.attempt_to_clear_flushed_buffer"));
    ise.initCause(ex);
    throw ise;
  }
  while (response instanceof ServletResponseWrapperInclude) {
    response=((ServletResponseWrapperInclude)response).getResponse();
  }
  final String path=getAbsolutePathRelativeToContext(relativeUrlPath);
  String includeUri=(String)request.getAttribute(Constants.INC_SERVLET_PATH);
  final ServletResponse fresponse=response;
  final ServletRequest frequest=request;
  if (includeUri != null)   request.removeAttribute(Constants.INC_SERVLET_PATH);
  try {
    context.getRequestDispatcher(path).forward(request,response);
  }
  finally {
    if (includeUri != null)     request.setAttribute(Constants.INC_SERVLET_PATH,includeUri);
    request.setAttribute(Constants.FORWARD_SEEN,"true");
  }
}

