/** 
 * Is the peer droppable?  SIDE EFFECT: If we are now outside the grace period, we reset peerAddedTime and opennetPeerAddedReason.  Note that the caller must check separately whether the node is TOO OLD and connected. 
 */
public NOT_DROP_REASON isDroppableWithReason(boolean ignoreDisconnect){
  long now=System.currentTimeMillis();
  int status=getPeerNodeStatus();
  long age=now - getPeerAddedTime();
  if (age < OpennetManager.DROP_MIN_AGE) {
    if (status == PeerManager.PEER_NODE_STATUS_NEVER_CONNECTED) {
      if (age < OpennetManager.DROP_MIN_AGE_DISCONNECTED)       return NOT_DROP_REASON.TOO_NEW_PEER;
    }
 else     if (status != PeerManager.PEER_NODE_STATUS_DISCONNECTED) {
      return NOT_DROP_REASON.TOO_NEW_PEER;
    }
  }
 else {
synchronized (this) {
      peerAddedTime=0;
      opennetNodeAddedReason=null;
    }
  }
  if (now - node.usm.getStartedTime() < OpennetManager.DROP_STARTUP_DELAY)   return NOT_DROP_REASON.TOO_LOW_UPTIME;
  if (!ignoreDisconnect) {
synchronized (this) {
      if ((status == PeerManager.PEER_NODE_STATUS_DISCONNECTED) && (!super.neverConnected()) && now - timeLastDisconnect < OpennetManager.DROP_DISCONNECT_DELAY && now - timePrevDisconnect > OpennetManager.DROP_DISCONNECT_DELAY_COOLDOWN) {
        return NOT_DROP_REASON.RECONNECT_GRACE_PERIOD;
      }
    }
  }
  return NOT_DROP_REASON.DROPPABLE;
}

@Override @SuppressLint("InlinedApi") public boolean isEnabled(Context context){
  if (Build.VERSION.SDK_INT < 9)   return false;
  SharedPreferences prefs=ContinuousProbe.getPreferences(context);
  this._context=context.getApplicationContext();
  final SensorManager sensors=(SensorManager)context.getSystemService(Context.SENSOR_SERVICE);
  final Sensor sensor=sensors.getDefaultSensor(Sensor.TYPE_LINEAR_ACCELERATION);
  if (super.isEnabled(context)) {
    if (prefs.getBoolean(LinearAccelerationProbe.ENABLED,ContinuousProbe.DEFAULT_ENABLED)) {
      int frequency=Integer.parseInt(prefs.getString(LinearAccelerationProbe.FREQUENCY,ContinuousProbe.DEFAULT_FREQUENCY));
      if (this._lastFrequency != frequency) {
        sensors.unregisterListener(this,sensor);
        if (LinearAccelerationProbe._handler != null) {
          Looper loop=LinearAccelerationProbe._handler.getLooper();
          loop.quit();
          LinearAccelerationProbe._handler=null;
        }
        if (frequency != SensorManager.SENSOR_DELAY_FASTEST && frequency != SensorManager.SENSOR_DELAY_UI && frequency != SensorManager.SENSOR_DELAY_NORMAL) {
          frequency=SensorManager.SENSOR_DELAY_GAME;
        }
        if (prefs.getBoolean(LinearAccelerationProbe.USE_HANDLER,ContinuousProbe.DEFAULT_USE_HANDLER)) {
          final LinearAccelerationProbe me=this;
          final int finalFrequency=frequency;
          Runnable r=new Runnable(){
            public void run(){
              Looper.prepare();
              LinearAccelerationProbe._handler=new Handler();
              if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.KITKAT)               sensors.registerListener(me,sensor,finalFrequency,0,LinearAccelerationProbe._handler);
 else               sensors.registerListener(me,sensor,finalFrequency,LinearAccelerationProbe._handler);
              Looper.loop();
            }
          }
;
          Thread t=new Thread(r,"linear_acceleration");
          t.start();
        }
 else {
          if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.KITKAT)           sensors.registerListener(this,sensor,frequency,0);
 else           sensors.registerListener(this,sensor,frequency,null);
        }
        this._lastFrequency=frequency;
      }
      return true;
    }
 else {
      sensors.unregisterListener(this,sensor);
      this._lastFrequency=-1;
      if (LinearAccelerationProbe._handler != null) {
        Looper loop=LinearAccelerationProbe._handler.getLooper();
        loop.quit();
        LinearAccelerationProbe._handler=null;
      }
    }
  }
 else {
    sensors.unregisterListener(this,sensor);
    this._lastFrequency=-1;
    if (LinearAccelerationProbe._handler != null) {
      Looper loop=LinearAccelerationProbe._handler.getLooper();
      loop.quit();
      LinearAccelerationProbe._handler=null;
    }
  }
  return false;
}

protected void engineInit(int opmode,Key key,AlgorithmParameterSpec params,SecureRandom random) throws InvalidKeyException, InvalidAlgorithmParameterException {
  if (!(key instanceof IESKey)) {
    throw new InvalidKeyException("must be passed IES key");
  }
  if (params == null && (opmode == Cipher.ENCRYPT_MODE || opmode == Cipher.WRAP_MODE)) {
    byte[] d=new byte[16];
    byte[] e=new byte[16];
    if (random == null) {
      random=new SecureRandom();
    }
    random.nextBytes(d);
    random.nextBytes(e);
    params=new IESParameterSpec(d,e,128);
  }
 else   if (!(params instanceof IESParameterSpec)) {
    throw new InvalidAlgorithmParameterException("must be passed IES parameters");
  }
  IESKey ieKey=(IESKey)key;
  CipherParameters pubKey;
  CipherParameters privKey;
  if (ieKey.getPublic() instanceof DHPublicKey) {
    pubKey=DHUtil.generatePublicKeyParameter(ieKey.getPublic());
    privKey=DHUtil.generatePrivateKeyParameter(ieKey.getPrivate());
  }
 else {
    pubKey=ECUtil.generatePublicKeyParameter(ieKey.getPublic());
    privKey=ECUtil.generatePrivateKeyParameter(ieKey.getPrivate());
  }
  this.engineParams=(IESParameterSpec)params;
  IESParameters p=new IESParameters(engineParams.getDerivationV(),engineParams.getEncodingV(),engineParams.getMacKeySize());
  this.state=opmode;
  buffer.reset();
switch (opmode) {
case Cipher.ENCRYPT_MODE:
case Cipher.WRAP_MODE:
    cipher.init(true,privKey,pubKey,p);
  break;
case Cipher.DECRYPT_MODE:
case Cipher.UNWRAP_MODE:
cipher.init(false,privKey,pubKey,p);
break;
default :
System.out.println("eeek!");
}
