/** 
 * Parses an escape that appears outside a charset.
 */
private RegExpTree parseEscape(){
  checkState(pattern.charAt(pos) == '\\');
  int start=pos;
  ++pos;
  char ch=pattern.charAt(pos);
  if (ch == 'b' || ch == 'B') {
    ++pos;
    return new WordBoundary(ch);
  }
 else   if ((ch == 'p' || ch == 'P') && flags.contains("u")) {
    boolean negated=ch == 'P';
    ++pos;
    if (pos < limit && pattern.charAt(pos) == '{') {
      StringBuilder lhs=new StringBuilder();
      while (++pos < limit && ((ch=pattern.charAt(pos)) == '_' || ('a' <= ch && ch <= 'z') || ('A' <= ch && ch <= 'Z') || ('0' <= ch && ch <= '9'))) {
        lhs.append(ch);
      }
      if (pos < limit && ch == '}') {
        ++pos;
        return new UnicodePropertyEscape(null,lhs.toString(),negated);
      }
 else       if (pos < limit && ch == '=') {
        StringBuilder rhs=new StringBuilder();
        while (++pos < limit && ((ch=pattern.charAt(pos)) == '_' || ('a' <= ch && ch <= 'z') || ('A' <= ch && ch <= 'Z') || ('0' <= ch && ch <= '9'))) {
          rhs.append(ch);
        }
        if (pos < limit && ch == '}') {
          ++pos;
          return new UnicodePropertyEscape(lhs.toString(),rhs.toString(),negated);
        }
 else {
          throw new IllegalArgumentException("Malformed Unicode Property Escape: expected '}' after " + pattern.substring(start,pos));
        }
      }
 else {
        throw new IllegalArgumentException("Malformed Unicode Property Escape: expected '=' or '}' after " + pattern.substring(start,pos));
      }
    }
 else {
      throw new IllegalArgumentException("Malformed Unicode Property Escape: expected '{' after " + pattern.substring(start,pos));
    }
  }
 else   if ('1' <= ch && ch <= '9') {
    ++pos;
    int possibleGroupIndex=ch - '0';
    if (numCapturingGroups >= possibleGroupIndex) {
      if (pos < limit) {
        char next=pattern.charAt(pos);
        if ('0' <= next && next <= '9') {
          int twoDigitGroupIndex=possibleGroupIndex * 10 + (next - '0');
          if (numCapturingGroups >= twoDigitGroupIndex) {
            ++pos;
            possibleGroupIndex=twoDigitGroupIndex;
          }
        }
      }
      return new BackReference(possibleGroupIndex);
    }
 else {
      return new Text(Character.toString(possibleGroupIndex <= 7 ? (char)possibleGroupIndex : ch));
    }
  }
 else   if (lookForNamedCaptureBackreferences && ch == 'k' && pos + 1 < limit && pattern.charAt(pos + 1) == '<' && !capturingGroupNames.isEmpty()) {
    pos+=2;
    String potentialName=scanNamedGroupName();
    if (!capturingGroupNames.contains(potentialName)) {
      throw new IllegalArgumentException("Invalid named capture referenced: " + pattern.substring(start));
    }
    return new NamedBackReference(potentialName);
  }
 else {
    CharRanges charGroup=NAMED_CHAR_GROUPS.get(ch);
    if (charGroup != null) {
      ++pos;
      return new Charset(charGroup,CharRanges.EMPTY);
    }
    return new Text("" + parseEscapeChar());
  }
}

public Object handleCall(Object gsClassInstance,Object... args){
  ReducedDynamicFunctionSymbol dfs=getDfs();
  try {
    boolean isEnhancement=AbstractElementTransformer.requiresImplicitEnhancementArg(dfs);
    IGosuClassInternal dfsClass=dfs.getGosuClass();
    if (isEnhancement || dfs.hasTypeVariables() || dfs.getGosuClass() instanceof IGosuProgram) {
      List<Object> argList=new ArrayList<Object>();
      if (isEnhancement) {
        argList.add(gsClassInstance);
        if (!dfs.isStatic() && dfs.isReified()) {
          if (dfsClass.isParameterizedType()) {
            for (int i=0; i < dfsClass.getTypeParameters().length; i++) {
              IType paramType=dfsClass.getTypeParameters()[i];
              argList.add(new NotLazyTypeResolver(paramType));
            }
          }
 else {
            for (int i=0; i < dfsClass.getGenericTypeVariables().length; i++) {
              IGenericTypeVariable tv=dfsClass.getGenericTypeVariables()[i];
              argList.add(new NotLazyTypeResolver(tv.getBoundingType()));
            }
          }
        }
      }
      if (dfs.isReified()) {
        for (        IGenericTypeVariable typeVar : dfs.getType().getGenericTypeVariables()) {
          argList.add(new NotLazyTypeResolver(typeVar.getBoundingType()));
        }
      }
      if (args != null) {
        argList.addAll(Arrays.asList(args));
      }
      args=argList.toArray();
    }
    Class clazz=dfsClass.getBackingClass();
    IRMethodFromMethodInfo irMethod=IRMethodFactory.createIRMethod(GosuMethodInfo.this,(IFunctionType)dfs.getType());
    List<IRType> allParameterTypes=irMethod.getAllParameterTypes();
    Class[] paramClasses=new Class[allParameterTypes.size()];
    for (int i=0; i < allParameterTypes.size(); i++) {
      paramClasses[i]=IRElement.maybeEraseStructuralType(allParameterTypes.get(i)).getJavaClass();
    }
    Method method=getMethod(clazz,NameResolver.getFunctionName(dfs),paramClasses);
    return method.invoke(gsClassInstance,args);
  }
 catch (  IllegalAccessException e) {
    throw GosuExceptionUtil.forceThrow(e);
  }
catch (  InvocationTargetException e) {
    throw GosuExceptionUtil.forceThrow(e.getTargetException());
  }
}

