    @SuppressWarnings("ConstantConditions") TypeElement newType=((JavaTypeElement)els.newElement).getDeclaringElement();
    long oldUid=oldSerialVersionUid == null ? computeSerialVersionUID(oldType,getOldTypeEnvironment()) : oldSerialVersionUid;
    long newUid=computeSerialVersionUID(newType,getNewTypeEnvironment());
    if (oldUid != newUid) {
      diffs=singletonList(createDifference(Code.CLASS_DEFAULT_SERIALIZATION_CHANGED,attachmentsFor(els.oldElement,els.newElement,"oldSerialVersionUID",Long.toString(oldUid),"newSerialVersionUID",Long.toString(newUid))));
    }
  }
  return diffs;
}

