/** 
 * Maybe record that given lvalue is an alias of the qualified name on its rhs. Note that since we are doing a post-order traversal, any previous aliases contained in the rhs will have already been substituted by the time we record the new alias.
 */
private void visitAliasDefinition(Node lhs,JSDocInfo info){
  if (isDeclaredConst(lhs,info) && (info == null || !info.hasTypeInformation()) && lhs.isQualifiedName()) {
    Node rhs=NodeUtil.getRValueOfLValue(lhs);
    if (rhs != null && rhs.isQualifiedName()) {
      GlobalNamespace.Name lhsName=namespace.getOwnSlot(lhs.getQualifiedName());
      GlobalNamespace.Name rhsName=namespace.getOwnSlot(rhs.getQualifiedName());
      if (lhsName != null && lhsName.calculateInlinability().shouldInlineUsages() && rhsName != null && rhsName.calculateInlinability().shouldInlineUsages() && !isPrivate(rhsName.getDeclaration().getNode())) {
        aliases.put(lhs.getQualifiedName(),rhs.getQualifiedName());
      }
    }
  }
}

