private Dimension paintOrGetSize(Graphics2D g,int width){
  Insets insets=getInsets();
  width-=insets.left + insets.right + margin.left+ margin.right;
  float w=insets.left + insets.right + margin.left+ margin.right;
  float x=insets.left + margin.left, y=insets.top + margin.top;
  if (width > 0 && text != null && text.length() > 0) {
    AttributedString as=new AttributedString(getText());
    as.addAttribute(TextAttribute.FONT,getFont());
    AttributedCharacterIterator aci=as.getIterator();
    LineBreakMeasurer lbm=new LineBreakMeasurer(aci,frc);
    float max=0;
    while (lbm.getPosition() < aci.getEndIndex()) {
      TextLayout textLayout=lbm.nextLayout(width);
      if (g != null && isJustified() && textLayout.getVisibleAdvance() > 0.80 * width)       textLayout=textLayout.getJustifiedLayout(width);
      if (g != null)       textLayout.draw(g,x,y + textLayout.getAscent());
      y+=textLayout.getDescent() + textLayout.getLeading() + textLayout.getAscent();
      max=Math.max(max,textLayout.getVisibleAdvance());
    }
    w+=max;
  }
  return new Dimension((int)Math.ceil(w),(int)Math.ceil(y) + insets.bottom + margin.bottom);
}

/** 
 * Convert to an Iterable of Character if the value is a String
 * @param value the object, which may be a String, String[], Collection of String
 * @return List of Character if the value is a String, or the value unchanged
 */
private static Object stringToCharacterIterable(Object value,Class parameterType,Class elementType){
  boolean convertCharacters=false;
  if (value instanceof String) {
    char[] chars=((String)value).toCharArray();
    List<Character> characters=new ArrayList<>(chars.length);
    for (    char c : chars) {
      characters.add(c);
    }
    return characters;
  }
  if (parameterType.getComponentType() != null) {
    if (parameterType.getComponentType().equals(Character.class)) {
      convertCharacters=true;
    }
  }
 else {
    if (elementType == Character.class || elementType == char.class) {
      convertCharacters=true;
    }
  }
  if (value.getClass().isArray() && convertCharacters && value.getClass().getComponentType().equals(String.class)) {
    String[] strings=(String[])value;
    List<Character> characters=new ArrayList<>(strings.length);
    for (    String s : strings) {
      characters.add(s.toCharArray()[0]);
    }
    return characters;
  }
  if (value.getClass().isArray() && (elementType == String.class || isEnum(elementType))) {
    String[] strings=(String[])value;
    return Arrays.asList(strings);
  }
  return value;
}

