/** 
 * Convert D4M string representation of rows to Ranges. Last character in the string is an arbitrary separator char that must not appear in the rows. The ':' cannot appear in rows either. See UtilTest for more test cases. Does not merge overlapping ranges.
 * @param rowStr Ex: ':,r1,r3,r5,:,r7,r9,:,'
 * @return Ex: (-Inf,r1] [r3,r3) [r5,r7] [r9,+Inf)
 */
public static SortedSet<Range> d4mRowToRanges(String rowStr){
  return d4mRowToRanges(rowStr,false);
}
/** 
 * @see #d4mRowToRanges(String)
 * @param singletonsArePrefix If true, then singleton entries in the D4M string aremade into prefix ranges instead of single row ranges.
 */
public static SortedSet<Range> d4mRowToRanges(String rowStr,boolean singletonsArePrefix){
  if (rowStr == null || rowStr.isEmpty())   return new TreeSet<>();
  String[] rowStrSplit=splitD4mString(rowStr);
  List<String> rowStrList=Arrays.asList(rowStrSplit);
  PeekingIterator3<String> pi=new PeekingIterator3<>(rowStrList.iterator());
  SortedSet<Range> rngset=new TreeSet<>();
  if (pi.peekFirst().equals(":")) {
    if (pi.peekSecond() == null) {
      return SETINFRNG;
    }
 else {
      if (pi.peekSecond().equals(":") || (pi.peekThird() != null && pi.peekThird().equals(":")))       throw new IllegalArgumentException("Bad D4M rowStr: " + rowStr);
      rngset.add(new Range(null,false,pi.peekSecond(),true));
      pi.next();
      pi.next();
    }
  }
  while (pi.hasNext()) {
    if (pi.peekSecond() == null) {
      if (singletonsArePrefix)       rngset.add(Range.prefix(pi.peekFirst()));
 else       rngset.add(Range.exact(pi.peekFirst()));
      return rngset;
    }
 else     if (pi.peekSecond().equals(":")) {
      if (pi.peekThird() == null) {
        rngset.add(new Range(pi.peekFirst(),true,null,false));
        return rngset;
      }
 else {
        if (pi.peekThird().equals(":"))         throw new IllegalArgumentException("Bad D4M rowStr: " + rowStr);
        rngset.add(new Range(pi.peekFirst(),true,pi.peekThird(),true));
        pi.next();
        pi.next();
        pi.next();
      }
    }
 else {
      if (singletonsArePrefix)       rngset.add(Range.prefix(pi.peekFirst()));
 else       rngset.add(Range.exact(pi.peekFirst()));
      pi.next();
    }
  }
  return rngset;
}

