/** 
 * Interpret plain numeric field as a date value in context.
 * @param flen
 * @param str
 * @param haveTextMonth
 * @param fmask
 * @param tmaskValue
 * @param tm
 * @param fsec
 * @param is2digits
 */
private static void decodeNumber(int flen,String str,boolean haveTextMonth,int fmask,AtomicInteger tmaskValue,TimeMeta tm,AtomicLong fsec,AtomicBoolean is2digits){
  int val;
  StringBuilder cp=new StringBuilder();
  int tmask=0;
  tmaskValue.set(tmask);
  val=strtoi(str,0,cp);
  if (cp.toString().equals(str)) {
    throw new IllegalArgumentException("BAD Format: " + str);
  }
  if (cp.length() > 0 && cp.charAt(0) == '.') {
    if (cp.length() - str.length() > 2) {
      decodeNumberField(flen,str,(fmask | DateTimeConstants.DTK_DATE_M),tmaskValue,tm,fsec,is2digits);
      return;
    }
    parseFractionalSecond(cp,fsec);
  }
  if (flen == 3 && (fmask & DateTimeConstants.DTK_DATE_M) == DateTimeConstants.DTK_M(TokenField.YEAR) && val >= 1 && val <= 366) {
    tmaskValue.set((DateTimeConstants.DTK_M(TokenField.DOY) | DateTimeConstants.DTK_M(TokenField.MONTH) | DateTimeConstants.DTK_M(TokenField.DAY)));
    tm.dayOfYear=val;
    return;
  }
  int checkValue=fmask & DateTimeConstants.DTK_DATE_M;
  if (checkValue == 0) {
    if (flen >= 3 || TajoConf.getDateOrder() == DateTimeConstants.DATEORDER_YMD) {
      tmaskValue.set(DateTimeConstants.DTK_M(TokenField.YEAR));
      tm.years=val;
    }
 else     if (TajoConf.getDateOrder() == DateTimeConstants.DATEORDER_DMY) {
      tmaskValue.set(DateTimeConstants.DTK_M(TokenField.DAY));
      tm.dayOfMonth=val;
    }
 else {
      tmaskValue.set(DateTimeConstants.DTK_M(TokenField.MONTH));
      tm.monthOfYear=val;
    }
  }
 else   if (checkValue == (DateTimeConstants.DTK_M(TokenField.YEAR))) {
    tmaskValue.set(DateTimeConstants.DTK_M(TokenField.MONTH));
    tm.monthOfYear=val;
  }
 else   if (checkValue == (DateTimeConstants.DTK_M(TokenField.MONTH))) {
    if (haveTextMonth) {
      if (flen >= 3 || TajoConf.getDateOrder() == DateTimeConstants.DATEORDER_YMD) {
        tmaskValue.set(DateTimeConstants.DTK_M(TokenField.YEAR));
        tm.years=val;
      }
 else {
        tmaskValue.set(DateTimeConstants.DTK_M(TokenField.DAY));
        tm.dayOfMonth=val;
      }
    }
 else {
      tmaskValue.set(DateTimeConstants.DTK_M(TokenField.DAY));
      tm.dayOfMonth=val;
    }
  }
 else   if (checkValue == (DateTimeConstants.DTK_M(TokenField.YEAR) | DateTimeConstants.DTK_M(TokenField.MONTH))) {
    if (haveTextMonth) {
      if (flen >= 3 && is2digits.get()) {
        tmaskValue.set(DateTimeConstants.DTK_M(TokenField.DAY));
        tm.dayOfMonth=tm.years;
        tm.years=val;
        is2digits.set(false);
      }
 else {
        tmaskValue.set(DateTimeConstants.DTK_M(TokenField.DAY));
        tm.dayOfMonth=val;
      }
    }
 else {
      tmaskValue.set(DateTimeConstants.DTK_M(TokenField.DAY));
      tm.dayOfMonth=val;
    }
  }
 else   if (checkValue == DateTimeConstants.DTK_M(TokenField.DAY)) {
    tmaskValue.set(DateTimeConstants.DTK_M(TokenField.MONTH));
    tm.monthOfYear=val;
  }
 else   if (checkValue == (DateTimeConstants.DTK_M(TokenField.MONTH) | DateTimeConstants.DTK_M(TokenField.DAY))) {
    tmaskValue.set(DateTimeConstants.DTK_M(TokenField.YEAR));
    tm.years=val;
  }
 else   if (checkValue == (DateTimeConstants.DTK_M(TokenField.YEAR) | DateTimeConstants.DTK_M(TokenField.MONTH) | DateTimeConstants.DTK_M(TokenField.DAY))) {
    decodeNumberField(flen,str,fmask,tmaskValue,tm,fsec,is2digits);
    return;
  }
 else {
    throw new IllegalArgumentException("BAD Format: " + str);
  }
  if (tmaskValue.get() == DateTimeConstants.DTK_M(TokenField.YEAR)) {
    is2digits.set(flen <= 2);
  }
}

/** 
 * Returns the LDAP User Distinguished Name (DN) to use when acquiring an {@link javax.naming.ldap.LdapContext LdapContext} from the {@link LdapContextFactory}. If the the  {@link #getUserDnTemplate() userDnTemplate} property has been set, this implementation will constructthe User DN by substituting the specified  {@code principal} into the configured template.  If the{@link #getUserDnTemplate() userDnTemplate} has not been set, the method argument will be returned directly(indicating that the submitted authentication token principal <em>is</em> the User DN).
 * @param principal the principal to substitute into the configured {@link #getUserDnTemplate() userDnTemplate}.
 * @return the constructed User DN to use at runtime when acquiring an {@link javax.naming.ldap.LdapContext}.
 * @throws IllegalArgumentException if the method argument is null or empty
 * @throws IllegalStateException    if the {@link #getUserDnTemplate userDnTemplate} has not been set.
 * @see LdapContextFactory#getLdapContext(Object,Object)
 */
@Override protected String getUserDn(final String principal) throws IllegalArgumentException, IllegalStateException {
  String userDn;
  Matcher matchedPrincipal=matchPrincipal(principal);
  String userSearchBase=getUserSearchBase();
  String userSearchAttributeName=getUserSearchAttributeName();
  if ((userSearchBase == null || userSearchBase.isEmpty()) || (userSearchAttributeName == null && userSearchFilter == null && !"object".equalsIgnoreCase(userSearchScope))) {
    userDn=expandTemplate(userDnTemplate,matchedPrincipal);
    LOG.computedUserDn(userDn,principal);
    return userDn;
  }
  String searchBase=expandTemplate(getUserSearchBase(),matchedPrincipal);
  String searchFilter;
  if (userSearchFilter == null) {
    if (userSearchAttributeName == null) {
      searchFilter=String.format(Locale.ROOT,"(objectclass=%1$s)",getUserObjectClass());
    }
 else {
      searchFilter=String.format(Locale.ROOT,"(&(objectclass=%1$s)(%2$s=%3$s))",getUserObjectClass(),userSearchAttributeName,expandTemplate(getUserSearchAttributeTemplate(),matchedPrincipal));
    }
  }
 else {
    searchFilter=expandTemplate(userSearchFilter,matchedPrincipal);
  }
  SearchControls searchControls=getUserSearchControls();
  LdapContext systemLdapCtx=null;
  NamingEnumeration<SearchResult> searchResultEnum=null;
  try {
    systemLdapCtx=getContextFactory().getSystemLdapContext();
    LOG.searchBaseFilterScope(searchBase,searchFilter,userSearchScope);
    searchResultEnum=systemLdapCtx.search(searchBase,searchFilter,searchControls);
    if (searchResultEnum.hasMore()) {
      SearchResult searchResult=searchResultEnum.next();
      userDn=searchResult.getNameInNamespace();
      LOG.searchedAndFoundUserDn(userDn,principal);
      return userDn;
    }
 else {
      throw new IllegalArgumentException("Illegal principal name: " + principal);
    }
  }
 catch (  AuthenticationException e) {
    LOG.failedToGetSystemLdapConnection(e);
    throw new IllegalArgumentException("Illegal principal name: " + principal,e);
  }
catch (  NamingException e) {
    throw new IllegalArgumentException("Hit NamingException",e);
  }
 finally {
    try {
      if (searchResultEnum != null) {
        searchResultEnum.close();
      }
    }
 catch (    NamingException e) {
    }
 finally {
      LdapUtils.closeContext(systemLdapCtx);
    }
  }
}

