void nextKey(int nextKeyIndex) throws Result {
  if (nextKeyIndex >= keys.size()) {
    tryThisOption();
    return;
  }
  String key=keys.get(nextKeyIndex);
  boolean take=r.nextBoolean();
  if (take) {
    take(nextKeyIndex + 1,key);
    nextKey(nextKeyIndex + 1);
  }
 else {
    nextKey(nextKeyIndex + 1);
    take(nextKeyIndex + 1,key);
  }
}

