public static List<Date> getInstancesInBetween(Date startTime,Date endTime,Frequency frequency,TimeZone timeZone,Date startRange,Date endRange){
  List<Date> result=new LinkedList<>();
  if (endRange.before(startRange)) {
    return result;
  }
  if (timeZone == null) {
    timeZone=TimeZone.getTimeZone("UTC");
  }
  Date current=getPreviousInstanceTime(startTime,frequency,timeZone,startRange);
  while (true) {
    if (!current.before(startRange) && !current.after(endRange) && current.before(endTime)&& !current.before(startTime)) {
      result.add(current);
    }
    current=getNextInstanceTime(current,frequency,timeZone,1);
    if (current.after(endRange)) {
      break;
    }
  }
  return result;
}

