@Override public void accept(CommandResponse response,Throwable error){
  if (error == null) {
    if (response.status() == RaftResponse.Status.OK) {
      complete(response);
    }
 else     if (response.error().type() == RaftError.Type.COMMAND_FAILURE) {
      resubmit(response.lastSequenceNumber(),this);
    }
 else     if (response.error().type() == RaftError.Type.PROTOCOL_ERROR || response.error().type() == RaftError.Type.APPLICATION_ERROR) {
      complete(response.error().createException());
    }
 else     if (response.error().type() == RaftError.Type.UNKNOWN_CLIENT || response.error().type() == RaftError.Type.UNKNOWN_SESSION) {
      complete(response.error().createException());
      state.setState(PrimitiveState.EXPIRED);
    }
 else     if (response.error().type() == RaftError.Type.UNKNOWN_SERVICE || response.error().type() == RaftError.Type.CLOSED_SESSION) {
      complete(response.error().createException());
      state.setState(PrimitiveState.CLOSED);
    }
 else {
      retry(Duration.ofSeconds(FIBONACCI[Math.min(attempt - 1,FIBONACCI.length - 1)]));
    }
  }
 else   if (EXCEPTION_PREDICATE.test(error) || (error instanceof CompletionException && EXCEPTION_PREDICATE.test(error.getCause()))) {
    if (error instanceof ConnectException || error.getCause() instanceof ConnectException) {
      leaderConnection.reset(null,leaderConnection.members());
    }
    retry(Duration.ofSeconds(FIBONACCI[Math.min(attempt - 1,FIBONACCI.length - 1)]));
  }
 else {
    fail(error);
  }
}

