/** 
 * Add a new message. For a normal priority level, we just add it to the end of the list. It will be sent after the messages that are already queued, and its deadline is effectively the time it was submitted plus the timeout. For a priority level using round robin between peers, it is the same unless we have recently sent a message with the same UID. If we have, the timeout is relative to the last send. 
 */
public void addLast(MessageItem item){
  item.clearDeadline();
  if (logMINOR)   checkOrder();
  if (roundRobinBetweenUIDs) {
    long id=item.getID();
    if (itemsByID != null) {
      Items it=itemsByID.get(id);
      if (it != null && it.timeLastSent > 0 && it.timeLastSent + timeout <= System.currentTimeMillis()) {
        it.addLast(item);
        if (it.getParent() == emptyItemsWithID)         moveFromEmptyToNonEmptyBackward(it);
 else         assert (it.getParent() == nonEmptyItemsWithID);
        if (logMINOR)         checkOrder();
        return;
      }
    }
  }
  addToNonUrgent(item);
}

