/** 
 * The Method expects a PluginException and adds the corresponding Faces Error Message into the FacesContext. If the PluginException was thrown from the RulePLugin then the method test this exception for ErrorParams and generate separate Faces Error Messages for each param.
 */
public static void handlePluginException(PluginException pe){
  if (RulePlugin.class.getName().equals(pe.getErrorContext()) && (RulePlugin.VALIDATION_ERROR.equals(pe.getErrorCode())) && pe.getErrorParameters() != null && pe.getErrorParameters().length > 0) {
    String errorCode=pe.getErrorCode();
    try {
      Locale browserLocale=FacesContext.getCurrentInstance().getViewRoot().getLocale();
      ResourceBundle rb=ResourceBundle.getBundle("bundle.app",browserLocale);
      errorCode=rb.getString(pe.getErrorCode());
    }
 catch (    MissingResourceException mre) {
      logger.warning("ErrorHandler: " + mre.getMessage());
    }
    Object[] messages=pe.getErrorParameters();
    for (    Object aMessage : messages) {
      FacesContext.getCurrentInstance().addMessage(null,new FacesMessage(FacesMessage.SEVERITY_INFO,errorCode,aMessage.toString()));
    }
  }
 else {
    addErrorMessage(pe);
  }
  logger.warning("ErrorHandler cauth PluginException - error code=" + pe.getErrorCode() + " - "+ pe.getMessage());
  if (logger.isLoggable(Level.FINE)) {
    pe.printStackTrace();
  }
}

