private void handleObjectTextInfoChanges(Class<? extends ObjectType> type,Collection<? extends ItemDelta> modifications,PrismObject prismObject,RObject<?> object){
  if (!isObjectTextInfoRecomputationNeeded(type,modifications)) {
    return;
  }
  Set<RObjectTextInfo> newInfos=RObjectTextInfo.createItemsSet((ObjectType)prismObject.asObjectable(),object,new RepositoryContext(repositoryService,prismContext,relationRegistry,extItemDictionary,baseHelper.getConfiguration()));
  if (newInfos == null || newInfos.isEmpty()) {
    object.getTextInfoItems().clear();
  }
 else {
    Set<String> existingTexts=object.getTextInfoItems().stream().map(info -> info.getText()).collect(Collectors.toSet());
    Set<String> newTexts=newInfos.stream().map(info -> info.getText()).collect(Collectors.toSet());
    object.getTextInfoItems().removeIf(existingInfo -> !newTexts.contains(existingInfo.getText()));
    for (    RObjectTextInfo newInfo : newInfos) {
      if (!existingTexts.contains(newInfo.getText())) {
        object.getTextInfoItems().add(newInfo);
      }
    }
  }
}

@Test public void testWatchFireOnceWhenLargeFileFinishes() throws Exception {
  File tempDir=TestFileUtil.createTempDirectoryInSystemTemp();
  final AtomicLong watcherEventOccurredTime=new AtomicLong(0L);
  final AtomicInteger watcherEventOccurredCount=new AtomicInteger(0);
  final AtomicLong fileWrittenTime=new AtomicLong(0L);
  DefaultRecursiveWatcher watcher=new DefaultRecursiveWatcher(Paths.get(tempDir.getAbsolutePath()),new ArrayList<Path>(),300,new WatchListener(){
    @Override public void watchEventsOccurred(){
      watcherEventOccurredCount.addAndGet(1);
      watcherEventOccurredTime.set(System.currentTimeMillis());
    }
  }
);
  watcher.start();
  Thread.sleep(400);
  File largeFile=new File(tempDir + "/largefile");
  TestFileUtil.createRandomFile(largeFile,50 * 1024 * 1024);
  fileWrittenTime.set(System.currentTimeMillis());
  Thread.sleep(800);
  watcher.stop();
  assertNotSame(0L,watcherEventOccurredTime.get());
  assertEquals(1,watcherEventOccurredCount.get());
  assertNotSame(0L,fileWrittenTime.get());
  assertTrue(watcherEventOccurredTime.get() >= fileWrittenTime.get());
  TestFileUtil.deleteDirectory(tempDir);
}

