public IntervalDatum(String intervalStr){
  super(Interval);
  intervalStr=intervalStr.trim();
  if (intervalStr.isEmpty()) {
    throw new InvalidOperationException("interval expression is empty");
  }
  try {
    int year=0;
    int month=0;
    int day=0;
    int hour=0;
    int minute=0;
    int second=0;
    int microsecond=0;
    int millisecond=0;
    long time=0;
    int length=intervalStr.getBytes().length;
    StringBuilder digitChars=new StringBuilder();
    StringBuilder unitChars=new StringBuilder();
    for (int i=0; i < length; i++) {
      char c=intervalStr.charAt(i);
      if (Character.isDigit(c) || c == ':' || c == '.' || c == '-') {
        digitChars.append(c);
      }
 else       if (c == ' ') {
        if (digitChars.length() > 0) {
          if (unitChars.length() > 0) {
            String unitName=unitChars.toString();
            DATE_UNIT foundUnit=DATE_FORMAT_LITERAL.get(unitName);
            if (foundUnit == null) {
              throw new InvalidOperationException("invalid input syntax for type interval: " + intervalStr);
            }
            int digit=Integer.parseInt(digitChars.toString());
switch (foundUnit) {
case YEAR:
              year=digit;
            break;
case MONTH:
          month=digit;
        break;
case DAY:
      day=digit;
    break;
case HOUR:
  hour=digit;
break;
case MINUTE:
minute=digit;
break;
case SECOND:
second=digit;
break;
case MICROSEC:
microsecond=digit;
break;
case MILLISEC:
millisecond=digit;
break;
default :
throw new InvalidOperationException("Unknown datetime unit: " + foundUnit);
}
digitChars.setLength(0);
unitChars.setLength(0);
}
 else if (digitChars.indexOf(":") >= 0) {
time=parseTime(digitChars.toString());
digitChars.setLength(0);
}
}
}
 else {
unitChars.append(c);
}
}
if (digitChars.length() > 0) {
if (unitChars.length() > 0) {
String unitName=unitChars.toString();
DATE_UNIT foundUnit=DATE_FORMAT_LITERAL.get(unitName);
if (foundUnit == null) {
throw new InvalidOperationException("invalid input syntax for type interval: " + intervalStr);
}
int digit=Integer.parseInt(digitChars.toString());
switch (foundUnit) {
case YEAR:
year=digit;
break;
case MONTH:
month=digit;
break;
case DAY:
day=digit;
break;
case HOUR:
hour=digit;
break;
case MINUTE:
minute=digit;
break;
case SECOND:
second=digit;
break;
case MICROSEC:
microsecond=digit;
break;
case MILLISEC:
millisecond=digit;
break;
default :
throw new InvalidOperationException("Unknown datetime unit: " + foundUnit);
}
}
 else if (digitChars.indexOf(":") >= 0) {
time=parseTime(digitChars.toString());
digitChars.setLength(0);
}
}
if (time > 0 && (hour != 0 || minute != 0 || second != 0 || microsecond != 0 || millisecond != 0)) {
throw new InvalidOperationException("invalid input syntax for type interval: " + intervalStr);
}
this.milliseconds=time + day * DAY_MILLIS + hour * HOUR_MILLIS + minute * 60 * 1000L + second * 1000L + microsecond * 100L + millisecond;
this.months=year * 12 + month;
}
 catch (InvalidOperationException e) {
throw e;
}
catch (Throwable t) {
throw new InvalidOperationException(t.getMessage() + ": " + intervalStr);
}
}

