/** 
 * Escapes the given string to a double quoted (") JavaScript/JSON string
 */
static String escapeString(String s){
  return escapeString(s,'"',"\\\"","\'","\\\\");
}
/** 
 * Helper to escape JavaScript string as well as regular expression 
 */
private static String escapeString(String s,char quote,String doublequoteEscape,String singlequoteEscape,String backslashEscape){
  StringBuilder sb=new StringBuilder(s.length() + 2);
  sb.append(quote);
  for (int i=0; i < s.length(); i++) {
    char c=s.charAt(i);
switch (c) {
case '\n':
      sb.append("\\n");
    break;
case '\r':
  sb.append("\\r");
break;
case '\t':
sb.append("\\t");
break;
case '\\':
sb.append(backslashEscape);
break;
case '\"':
sb.append(doublequoteEscape);
break;
case '\'':
sb.append(singlequoteEscape);
break;
case '>':
if (i >= 2 && ((s.charAt(i - 1) == '-' && s.charAt(i - 2) == '-') || (s.charAt(i - 1) == ']' && s.charAt(i - 2) == ']'))) {
sb.append("\\u003e");
}
 else {
sb.append(c);
}
break;
case '<':
final String END_SCRIPT="/script";
final String START_COMMENT="!--";
if (s.regionMatches(true,i + 1,END_SCRIPT,0,END_SCRIPT.length())) {
sb.append("\\u003c");
}
 else if (s.regionMatches(false,i + 1,START_COMMENT,0,START_COMMENT.length())) {
sb.append("\\u003c");
}
 else {
sb.append(c);
}
break;
default :
if (c > 0x1f && c <= 0x7f) {
sb.append(c);
}
 else {
appendHexJavaScriptRepresentation(sb,c);
}
}
}
sb.append(quote);
return sb.toString();
}

