/** 
 * Creates a new generation.
 * @param gen_no The number of the generation. The first is 0.
 */
public double evolve(int gen_no){
  ExemplarsTracker tracker=null;
  if (active) {
    Comparator comparator=gen_no == 0 ? new FindCorrectComparator() : new DisagreementComparator();
    tracker=new ExemplarsTracker(config,comparator);
  }
  if (threads == 1)   evaluateAll(tracker);
 else   evaluateAllThreaded(tracker);
  population.sort();
  double fsum=0.0;
  double lbest=-1.0;
  GeneticConfiguration best=null;
  List<GeneticConfiguration> pop=population.getConfigs();
  for (  GeneticConfiguration cfg : pop) {
    fsum+=cfg.getFNumber();
    if (cfg.getFNumber() > lbest) {
      lbest=cfg.getFNumber();
      best=cfg;
    }
  }
  if (!quiet) {
    System.out.println("BEST: " + lbest + " AVERAGE: "+ (fsum / pop.size()));
    for (    GeneticConfiguration cfg : pop)     System.out.print(cfg.getFNumber() + " ");
    System.out.println();
  }
  if (active && skipgens == 0) {
    askQuestions(tracker);
    if (sparse) {
      if (gen_no > 9)       skipgens=3;
 else       if (gen_no > 1)       skipgens=1;
    }
  }
 else   if (skipgens > 0)   skipgens--;
  if (scientific) {
    double devsum=0.0;
    fsum=0.0;
    lbest=-1.0;
    for (    GeneticConfiguration cfg : pop) {
      double real=sciencetracker.get(cfg);
      devsum+=Math.abs(cfg.getFNumber() - real);
      fsum+=real;
      if (real > lbest)       lbest=real;
    }
    if (!quiet) {
      System.out.println("ACTUAL BEST: " + sciencetracker.get(best) + " ACTUAL AVERAGE: "+ (fsum / pop.size()));
      System.out.println("AVERAGE DEVIATION: " + (devsum / pop.size()));
      System.out.println("QUESTIONS ASKED: " + used.size());
      System.out.println();
    }
    sciencetracker.clear();
  }
  if (outfile != null) {
    try {
      Configuration b=population.getBestConfiguration().getConfiguration();
      FileOutputStream fos=new FileOutputStream(outfile);
      ConfigWriter configWriter=new ConfigWriter(fos);
      configWriter.write(b);
      fos.close();
    }
 catch (    IOException e) {
      System.err.println("ERROR: Cannot write to '" + outfile + "': "+ e);
    }
  }
  if (active && population.getBestConfiguration().getFNumber() == population.getWorstConfiguration().getFNumber())   return lbest;
  produceNextGeneration();
  return lbest;
}

private Object handleGetterTrailingChain(Object result){
  for (int i=1; i < getterChain.length; i++) {
    if (result == null) {
      return null;
    }
    EventPropertyGetter getter=getterChain[i];
    if (result instanceof EventBean) {
      result=getter.get((EventBean)result);
    }
 else     if (getter instanceof BeanEventPropertyGetter) {
      result=((BeanEventPropertyGetter)getter).getBeanProp(result);
    }
 else     if (result instanceof Map && getter instanceof MapEventPropertyGetter) {
      result=((MapEventPropertyGetter)getter).getMap((Map)result);
    }
 else {
      return null;
    }
  }
  return result;
}

