/** 
 * Waits getting synchronizated from peer.
 * @param peer the id of the expected peer that synchronization message willcome from.
 * @throws InterruptedException in case of interruption.
 * @throws TimeoutException in case of timeout.
 * @throws IOException in case of IO failure.
 */
protected void waitForSync(String peer) throws InterruptedException, TimeoutException, IOException {
  LOG.debug("Waiting sync from {}.",peer);
  Log log=this.persistence.getLog();
  Zxid lastZxid=persistence.getLatestZxid();
  Zxid lastZxidPeer=null;
  Message msg=null;
  String source=null;
  while (true) {
    MessageTuple tuple=filter.getMessage(getSyncTimeoutMs());
    source=tuple.getServerId();
    msg=tuple.getMessage();
    if ((msg.getType() != MessageType.DIFF && msg.getType() != MessageType.TRUNCATE && msg.getType() != MessageType.SNAPSHOT && msg.getType() != MessageType.PULL_TXN_REQ) || !source.equals(peer)) {
      if (LOG.isDebugEnabled()) {
        LOG.debug("Got unexpected message {} from {}.",TextFormat.shortDebugString(msg),source);
      }
      continue;
    }
 else {
      break;
    }
  }
  if (msg.getType() == MessageType.PULL_TXN_REQ) {
    LOG.debug("Got pull transaction request from {}",source);
    ZabMessage.Zxid z=msg.getPullTxnReq().getLastZxid();
    lastZxidPeer=MessageBuilder.fromProtoZxid(z);
    SyncPeerTask syncTask=new SyncPeerTask(source,lastZxidPeer,lastZxid,this.persistence.getLastSeenConfig());
    syncTask.run();
    MessageTuple tuple=filter.getExpectedMessage(MessageType.DIFF,peer,getSyncTimeoutMs());
    msg=tuple.getMessage();
    ZabMessage.Diff diff=msg.getDiff();
    lastZxidPeer=MessageBuilder.fromProtoZxid(diff.getLastZxid());
    if (lastZxidPeer.compareTo(lastZxid) != 0) {
      LOG.error("The history of leader and follower are not same.");
      throw new RuntimeException("Expecting leader and follower have same" + "history.");
    }
    waitForSyncEnd(peer);
    return;
  }
  if (msg.getType() == MessageType.DIFF) {
    if (LOG.isDebugEnabled()) {
      LOG.debug("Got message {}",TextFormat.shortDebugString(msg));
    }
    ZabMessage.Diff diff=msg.getDiff();
    lastZxidPeer=MessageBuilder.fromProtoZxid(diff.getLastZxid());
    if (lastZxid.compareTo(lastZxidPeer) == 0) {
      waitForSyncEnd(peer);
      return;
    }
  }
 else   if (msg.getType() == MessageType.TRUNCATE) {
    if (LOG.isDebugEnabled()) {
      LOG.debug("Got message {}",TextFormat.shortDebugString(msg));
    }
    ZabMessage.Truncate trunc=msg.getTruncate();
    Zxid lastPrefixZxid=MessageBuilder.fromProtoZxid(trunc.getLastPrefixZxid());
    lastZxidPeer=MessageBuilder.fromProtoZxid(trunc.getLastZxid());
    if (lastZxidPeer.equals(Zxid.ZXID_NOT_EXIST)) {
      persistence.beginStateTransfer();
    }
 else {
      log.truncate(lastPrefixZxid);
    }
    if (lastZxidPeer.compareTo(lastPrefixZxid) == 0) {
      waitForSyncEnd(peer);
      return;
    }
  }
 else {
    if (LOG.isDebugEnabled()) {
      LOG.debug("Got message {}",TextFormat.shortDebugString(msg));
    }
    ZabMessage.Snapshot snap=msg.getSnapshot();
    lastZxidPeer=MessageBuilder.fromProtoZxid(snap.getLastZxid());
    Zxid snapZxid=MessageBuilder.fromProtoZxid(snap.getSnapZxid());
    msg=filter.getExpectedMessage(MessageType.FILE_RECEIVED,peer,getSyncTimeoutMs()).getMessage();
    File file=new File(msg.getFileReceived().getFullPath());
    persistence.beginStateTransfer();
    persistence.setSnapshotFile(file,snapZxid);
    log.truncate(Zxid.ZXID_NOT_EXIST);
    if (lastZxidPeer.compareTo(snapZxid) == 0) {
      waitForSyncEnd(peer);
      return;
    }
  }
  log=persistence.getLog();
  while (true) {
    MessageTuple tuple=filter.getExpectedMessage(MessageType.PROPOSAL,peer,getSyncTimeoutMs());
    msg=tuple.getMessage();
    source=tuple.getServerId();
    if (LOG.isDebugEnabled()) {
      LOG.debug("Got message {} from {}",TextFormat.shortDebugString(msg),source);
    }
    ZabMessage.Proposal prop=msg.getProposal();
    Zxid zxid=MessageBuilder.fromProtoZxid(prop.getZxid());
    log.append(MessageBuilder.fromProposal(prop));
    if (zxid.compareTo(lastZxidPeer) == 0) {
      waitForSyncEnd(peer);
      return;
    }
  }
}

private static Method findPublicMethod(Class<?> c,String methodName){
  try {
    Method method=c.getMethod(methodName);
    if (Modifier.isPublic(c.getModifiers()) || c.getName().startsWith("auto.parse")) {
      return method;
    }
    if (c.getSuperclass() != null) {
      method=findPublicMethod(c.getSuperclass(),methodName);
    }
    if (method == null) {
      for (      Class<?> intf : c.getInterfaces()) {
        method=findPublicMethod(intf,methodName);
        if (method != null) {
          break;
        }
      }
    }
    return method;
  }
 catch (  NoSuchMethodException e) {
    return null;
  }
}

/** 
 * Set a coefficient in the internal table.
 * @param n     the zero-based index of the coefficient. n=0 for the constant term.
 * @param value the new value of the coefficient.
 */
protected void set(final int n,final Rational value){
  final int nindx=n / 2;
  if (nindx < a.size()) {
    a.set(nindx,value);
  }
 else {
    while (a.size() < nindx) {
      a.add(Rational.ZERO);
    }
    a.add(value);
  }
}

