/** 
 * Write a single character.
 * @throws IOException in case of IO errors
 */
public void write(int c) throws IOException {
  ensureOpen();
  if (bufferSize == 0) {
    initOut();
    out.write(c);
  }
 else {
    if (nextChar >= bufferSize)     if (autoFlush)     flushBuffer();
 else     bufferOverflow();
    cb[nextChar++]=(char)c;
  }
}
/** 
 * Write a portion of an array of characters. <p> Ordinarily this method stores characters from the given array into this stream's buffer, flushing the buffer to the underlying stream as needed.  If the requested length is at least as large as the buffer, however, then this method will flush the buffer and write the characters directly to the underlying stream.  Thus redundant <code>DiscardableBufferedWriter</code>s will not copy data unnecessarily.
 * @param cbuf  A character array
 * @param off   Offset from which to start reading characters
 * @param len   Number of characters to write
 * @throws IOException in case of IO errors
 */
public void write(char cbuf[],int off,int len) throws IOException {
  ensureOpen();
  if (bufferSize == 0) {
    initOut();
    out.write(cbuf,off,len);
    return;
  }
  if ((off < 0) || (off > cbuf.length) || (len < 0)|| ((off + len) > cbuf.length)|| ((off + len) < 0)) {
    throw new IndexOutOfBoundsException();
  }
 else   if (len == 0) {
    return;
  }
  if (len >= bufferSize) {
    if (autoFlush)     flushBuffer();
 else     bufferOverflow();
    initOut();
    out.write(cbuf,off,len);
    return;
  }
  int b=off, t=off + len;
  while (b < t) {
    int d=min(bufferSize - nextChar,t - b);
    System.arraycopy(cbuf,b,cb,nextChar,d);
    b+=d;
    nextChar+=d;
    if (nextChar >= bufferSize)     if (autoFlush)     flushBuffer();
 else     bufferOverflow();
  }
}
/** 
 * Write an array of characters.  This method cannot be inherited from the Writer class because it must suppress I/O exceptions.
 * @throws IOException in case of IO errors
 */
public void write(char buf[]) throws IOException {
  write(buf,0,buf.length);
}
/** 
 * Write a portion of a String.
 * @param s     String to be written
 * @param off   Offset from which to start reading characters
 * @param len   Number of characters to be written
 * @throws IOException in case of IO errors
 */
public void write(String s,int off,int len) throws IOException {
  ensureOpen();
  if (bufferSize == 0) {
    initOut();
    out.write(s,off,len);
    return;
  }
  int b=off, t=off + len;
  while (b < t) {
    int d=min(bufferSize - nextChar,t - b);
    s.getChars(b,b + d,cb,nextChar);
    b+=d;
    nextChar+=d;
    if (nextChar >= bufferSize)     if (autoFlush)     flushBuffer();
 else     bufferOverflow();
  }
}
/** 
 * Write a string.  This method cannot be inherited from the Writer class because it must suppress I/O exceptions.
 * @throws IOException in case of IO errors
 */
public void write(String s) throws IOException {
  if (s == null) {
    write(s,0,0);
  }
 else {
    write(s,0,s.length());
  }
}

