private void consumeMap(){
  int code;
  bytes.readSkip(1);
  for (; ; ) {
    long pos=bytes.readPosition();
    consumeAny();
    int code2=peekCode();
    if (code2 == '}' || code2 == ']' || code2 <= 0) {
      break;
    }
 else     if (code2 == ',') {
      readCode();
    }
    if (bytes.readPosition() == pos)     throw new IllegalStateException("Stuck at pos " + pos + " "+ bytes);
  }
  consumePadding();
  code=readCode();
  if (code != '}') {
    bytes.readSkip(-1);
    throw new IllegalStateException("Expected a } was " + code);
  }
}

