 * Returns an unmodifiable view of the union of two multisets. In the returned multiset, the count of each element is the <i>maximum</i> of its counts in the two backing multisets. The iteration order of the returned multiset matches that of the element set of  {@code multiset1} followed bythe members of the element set of  {@code multiset2} that are not contained in {@code multiset1}, with repeated occurrences of the same element appearing consecutively. <p>Results are undefined if  {@code multiset1} and {@code multiset2} are based on differentequivalence relations (as  {@code HashMultiset} and {@code TreeMultiset} are).
 * @since 14.0
 */
@Beta public static <E>Multiset<E> union(final Multiset<? extends E> multiset1,final Multiset<? extends E> multiset2){
  checkNotNull(multiset1);
  checkNotNull(multiset2);
  return new ViewMultiset<E>(){
    @Override public boolean contains(    @NullableDecl Object element){
      return multiset1.contains(element) || multiset2.contains(element);
    }
    @Override public boolean isEmpty(){
      return multiset1.isEmpty() && multiset2.isEmpty();
    }
    @Override public int count(    Object element){
      return Math.max(multiset1.count(element),multiset2.count(element));
    }
    @Override Set<E> createElementSet(){
      return Sets.union(multiset1.elementSet(),multiset2.elementSet());
    }
    @Override Iterator<E> elementIterator(){
      throw new AssertionError("should never be called");
    }
    @Override Iterator<Entry<E>> entryIterator(){
      final Iterator<? extends Entry<? extends E>> iterator1=multiset1.entrySet().iterator();
      final Iterator<? extends Entry<? extends E>> iterator2=multiset2.entrySet().iterator();
      return new AbstractIterator<Entry<E>>(){
        @Override protected Entry<E> computeNext(){
          if (iterator1.hasNext()) {
            Entry<? extends E> entry1=iterator1.next();
            E element=entry1.getElement();
            int count=Math.max(entry1.getCount(),multiset2.count(element));
            return immutableEntry(element,count);
          }
          while (iterator2.hasNext()) {
            Entry<? extends E> entry2=iterator2.next();
            E element=entry2.getElement();
            if (!multiset1.contains(element)) {
              return immutableEntry(element,entry2.getCount());
            }
          }
          return endOfData();
        }
      }
;
    }
  }
;
}
