/** 
 * Returns the next character on the input. <p> <strong>Note:</strong> The character is consumed.
 * @throws IOException  Thrown if i/o error occurs.
 * @throws EOFException Thrown on end of file.
 */
public int scanChar() throws IOException {
  if (fCurrentEntity.position == fCurrentEntity.count) {
    load(0,true);
  }
  int c=fCurrentEntity.ch[fCurrentEntity.position++];
  boolean external=false;
  if (c == '\n' || (c == '\r' && (external=fCurrentEntity.isExternal()))) {
    fCurrentEntity.lineNumber++;
    fCurrentEntity.columnNumber=1;
    if (fCurrentEntity.position == fCurrentEntity.count) {
      fCurrentEntity.ch[0]=(char)c;
      load(1,false);
    }
    if (c == '\r' && external) {
      if (fCurrentEntity.ch[fCurrentEntity.position++] != '\n') {
        fCurrentEntity.position--;
      }
      c='\n';
    }
  }
  fCurrentEntity.columnNumber++;
  return c;
}

static boolean deepArraysEquals(final Object l,final Object r){
  if (l == null && r == null) {
    return true;
  }
  if (l == null || r == null) {
    return false;
  }
  if (l.getClass() != r.getClass()) {
    return false;
  }
  final int length=Array.getLength(l);
  if (length != Array.getLength(r)) {
    return false;
  }
  for (int i=0; i < length; i++) {
    final Object lv=Array.get(l,i);
    final Object rv=Array.get(r,i);
    if (lv == rv || lv == null && rv == null) {
      continue;
    }
    if (lv == null || rv == null || lv.getClass() != rv.getClass()) {
      return false;
    }
    if (lv.getClass().isArray()) {
      if (!deepArraysEquals(lv,rv)) {
        return false;
      }
    }
 else {
      if (!lv.equals(rv)) {
        return false;
      }
    }
  }
  return true;
}

