/** 
 * Gets the content of each table cell
 * @param YNum The number of non-duplicated Y axes in the table area
 * @param cc the number of the table columns
 * @param tc the object of the table candidate
 */
public void getEachCellContent(int YNum,int cc,TableCandidate tc){
  int footnoteLineIndex=tc.getFootnoteBeginRow();
  String[] contentsInRows=new String[footnoteLineIndex];
  float[] leftX_tableColumns=tc.getLeftX_tableColumns();
  float[] rightX_tableColumns=tc.getRightX_tableColumns();
  String[][] cells=new String[YNum][cc];
  boolean[][] crossCells=new boolean[YNum][cc];
  for (int tt=0; tt < tc.getRows().size(); tt++) {
    for (int qq=0; qq < cc; qq++) {
      cells[tt][qq]="";
      crossCells[tt][qq]=false;
    }
  }
  for (int tt=0; tt < footnoteLineIndex; tt++) {
    String cellsThisLine="";
    TableRow row=tc.getRows().get(tt);
    int cellThisLine=row.getCells().size();
    for (int zz=0; zz < cellThisLine; zz++) {
      for (int qq=0; qq < cc; qq++) {
        if ((row.getCells().get(zz).getX() >= leftX_tableColumns[qq]) && (row.getCells().get(zz).getEndX() <= rightX_tableColumns[qq]))         cells[tt][qq]=cells[tt][qq] + row.getCells().get(zz).getText() + " ";
        if ((row.getCells().get(zz).getX() < leftX_tableColumns[qq]) && (leftX_tableColumns[qq] <= row.getCells().get(zz).getEndX()))         cells[tt][qq]=cells[tt][qq] + row.getCells().get(zz).getText() + " ";
        if ((leftX_tableColumns[qq] >= row.getCells().get(zz).getX()) && (row.getCells().get(zz).getX() >= rightX_tableColumns[qq]) && (rightX_tableColumns[qq] < row.getCells().get(zz).getEndX()))         cells[tt][qq]=cells[tt][qq] + row.getCells().get(zz).getText() + " ";
      }
    }
    for (int zz=0; zz < cellThisLine; zz++) {
      int crossCellBegin=1000;
      int crossCellEnd=0;
      for (int qq=0; qq < cc; qq++) {
        if ((qq > 0) && (cells[tt][qq - 1].length() == 0) && (row.getCells().get(zz).getX() <= rightX_tableColumns[qq - 1])&& (row.getCells().get(zz).getX() < leftX_tableColumns[qq])&& (leftX_tableColumns[qq] <= row.getCells().get(zz).getEndX())) {
          crossCells[tt][qq]=true;
          crossCells[tt][qq - 1]=true;
          cells[tt][qq - 1]=row.getCells().get(zz).getText();
          crossCellBegin=qq - 1;
        }
        if ((qq < (cc - 1)) && (cells[tt][qq + 1].length() == 0) && (row.getCells().get(zz).getEndX() >= leftX_tableColumns[qq + 1])&& (row.getCells().get(zz).getX() <= rightX_tableColumns[qq])&& (rightX_tableColumns[qq] < row.getCells().get(zz).getEndX())) {
          crossCells[tt][qq]=true;
          crossCells[tt][qq + 1]=true;
          cells[tt][qq + 1]=row.getCells().get(zz).getText();
          crossCellEnd=qq + 1;
        }
      }
    }
    for (int qq=0; qq < cc; qq++) {
      cellsThisLine=cellsThisLine + cells[tt][qq] + "; ";
    }
    contentsInRows[tt]=cellsThisLine;
  }
  tc.setCells(cells);
  tc.setCrossCells(crossCells);
}

