private boolean reduceContainerValues(List<? extends PrismContainerValue<?>> values,ObjectSecurityConstraints securityConstraints,AuthorizationPhaseType phase,AuthorizationDecisionType itemReadDecision,AuthorizationDecisionType itemAddDecision,AuthorizationDecisionType itemModifyDecision,AuthorizationDecisionType subDefaultReadDecision,boolean applyToDefinitions){
  if (values == null) {
    return false;
  }
  boolean removedSomething=false;
  Iterator<? extends PrismContainerValue<?>> vi=values.iterator();
  while (vi.hasNext()) {
    PrismContainerValue<?> cval=vi.next();
    applySecurityConstraints(cval,securityConstraints,phase,subDefaultReadDecision,itemAddDecision,itemModifyDecision,applyToDefinitions);
    if (cval.hasNoItems() && itemReadDecision == null) {
      vi.remove();
      removedSomething=true;
    }
  }
  return removedSomething;
}

