protected boolean insideScissor(){
  needScissoringX=false;
  needScissoringY=false;
  if (prim.pxMax < scissorX1 || prim.pxMin > scissorX2) {
    if (isLogTraceEnabled) {
      log.trace(String.format("X outside scissor area %d-%d, %d-%d",prim.pxMin,prim.pxMax,scissorX1,scissorX2));
    }
    return false;
  }
  if (prim.pyMax < scissorY1 || prim.pyMin > scissorY2) {
    if (isLogTraceEnabled) {
      log.trace(String.format("Y outside scissor area %d-%d, %d-%d",prim.pyMin,prim.pyMax,scissorY1,scissorY2));
    }
    return false;
  }
  if (!transform2D) {
    if ((nearZ > 0x0000 && prim.pzMax < nearZ) || (farZ < 0xFFFF && prim.pzMin > farZ)) {
      if (isLogTraceEnabled) {
        log.trace(String.format("Z outside view area %d-%d, %d-%d",prim.pzMin,prim.pzMax,nearZ,farZ));
      }
      return false;
    }
  }
  if (prim.pxMin < scissorX1 || prim.pxMax > scissorX2) {
    needScissoringX=true;
  }
  if (prim.pyMin < scissorY1 || prim.pyMax > scissorY2) {
    needScissoringY=true;
  }
  return true;
}

@Override public String execute(String request){
  return execute(request,this.connectTimeout,this.readTimeout);
}
@Override public String execute(String request,int connectTimeout,int readTimeout){
  String response=null;
  HttpsURLConnection connection=null;
  try {
    String correctedRequest=checkSessionToken(request);
    connection=getConnection(correctedRequest,connectTimeout,readTimeout);
    if (connection != null) {
      connection.connect();
      final int responseCode=connection.getResponseCode();
      if (responseCode != HttpURLConnection.HTTP_FORBIDDEN) {
        if (responseCode == HttpURLConnection.HTTP_INTERNAL_ERROR) {
          response=IOUtils.toString(connection.getErrorStream());
        }
 else {
          response=IOUtils.toString(connection.getInputStream());
        }
        if (response != null) {
          if (!response.contains("Authentication failed")) {
            if (loginCounter > 0) {
              connectionManager.checkConnection(responseCode);
            }
            loginCounter=0;
          }
 else {
            connectionManager.checkConnection(ConnectionManager.AUTHENTIFICATION_PROBLEM);
            loginCounter++;
          }
        }
      }
      connection.disconnect();
      if (response == null && connectionManager != null && loginCounter <= MAY_A_NEW_SESSION_TOKEN_IS_NEEDED) {
        if (responseCode == HttpURLConnection.HTTP_FORBIDDEN) {
          execute(addSessionToken(correctedRequest,connectionManager.getNewSessionToken()),connectTimeout,readTimeout);
          loginCounter++;
        }
 else {
          connectionManager.checkConnection(responseCode);
          loginCounter++;
          return null;
        }
      }
      return response;
    }
  }
 catch (  SocketTimeoutException e) {
    informConnectionManager(ConnectionManager.SOCKET_TIMEOUT_EXCEPTION);
  }
catch (  java.net.ConnectException e) {
    informConnectionManager(ConnectionManager.CONNECTION_EXCEPTION);
  }
catch (  MalformedURLException e) {
    informConnectionManager(ConnectionManager.MALFORMED_URL_EXCEPTION);
  }
catch (  java.net.UnknownHostException e) {
    informConnectionManager(ConnectionManager.UNKNOWN_HOST_EXCEPTION);
  }
catch (  IOException e) {
    logger.error("An IOException occurred: ",e);
    if (connectionManager != null) {
      informConnectionManager(ConnectionManager.GENERAL_EXCEPTION);
    }
  }
 finally {
    if (connection != null) {
      connection.disconnect();
    }
  }
  return null;
}

