 */
public <U1,U2,U3,U4,U5,U6,U7>Tuple7<U1,U2,U3,U4,U5,U6,U7> map(Function7<? super T1,? super T2,? super T3,? super T4,? super T5,? super T6,? super T7,Tuple7<U1,U2,U3,U4,U5,U6,U7>> mapper){
