 * Checks whether the title of the message is valid. Validity conditions: - Not empty - No line breaks, tabs, or any other control characters. - No invalid characters. - valid UTF-8 encoding - No invalid UTF formatting (unpaired direction or annotation characters). - Not too long
 */
public static final boolean isTitleValid(String title){
  if (title == null)   return false;
  if (title.trim().length() == 0)   return false;
  if (title.length() > MAX_MESSAGE_TITLE_TEXT_LENGTH)   return false;
  try {
    if (title.getBytes("UTF-8").length > MAX_MESSAGE_TITLE_BYTE_LENGTH) {
      return false;
    }
  }
 catch (  UnsupportedEncodingException e) {
    return false;
  }
  return (StringValidityChecker.containsNoInvalidCharacters(title) && StringValidityChecker.containsNoLinebreaks(title) && StringValidityChecker.containsNoControlCharacters(title)&& StringValidityChecker.containsNoInvalidFormatting(title));
}

