private V findPath(V root){
  used.clear();
  p.clear();
  base.clear();
  for (  V i : graph.vertexSet()) {
    base.put(i,i);
  }
  used.add(root);
  q.add(root);
  while (!q.isEmpty()) {
    V v=q.remove();
    for (    E e : graph.edgesOf(v)) {
      V to=graph.getEdgeSource(e);
      if (to == v) {
        to=graph.getEdgeTarget(e);
      }
      if ((base.get(v) == base.get(to)) || (match.get(v) == to)) {
        continue;
      }
      if ((to == root) || ((match.containsKey(to)) && (p.containsKey(match.get(to))))) {
        V curbase=lca(graph,v,to);
        blossom.clear();
        markPath(v,curbase,to);
        markPath(to,curbase,v);
        for (        V i : graph.vertexSet()) {
          if (base.containsKey(i) && blossom.contains(base.get(i))) {
            base.put(i,curbase);
            if (!used.contains(i)) {
              used.add(i);
              q.add(i);
            }
          }
        }
      }
 else       if (!p.containsKey(to)) {
        p.put(to,v);
        if (!match.containsKey(to)) {
          return to;
        }
        to=match.get(to);
        used.add(to);
        q.add(to);
      }
    }
  }
  return null;
}

