/** 
 * Utility method to process the passed persistable object.
 * @param pc The PC object
 * @param ownerFieldNum Field number of owner where this is embedded
 * @param objectType Type of object (see org.datanucleus.ObjectProvider)
 * @return The processed persistable object
 */
protected Object processPersistable(Object pc,int ownerFieldNum,int objectType){
  ApiAdapter adapter=op.getExecutionContext().getApiAdapter();
  if (!adapter.isPersistent(pc) || (adapter.isPersistent(pc) && adapter.isDeleted(pc))) {
    if (objectType != ObjectProvider.PC) {
      return op.getExecutionContext().persistObjectInternal(pc,op,ownerFieldNum,objectType);
    }
    return op.getExecutionContext().persistObjectInternal(pc,null,-1,objectType);
  }
  return pc;
}

/** 
 * Check the associativity between the given two join edges. For the associativity rules, please refer to the below isAssociativeJoinType() function.
 * @param context join graph context
 * @param leftEdge left join edge
 * @param rightEdge right join edge
 * @return true if two given join edges are associative.
 */
public static boolean isAssociativeJoin(JoinGraphContext context,JoinEdge leftEdge,JoinEdge rightEdge){
  if (isAssociativeJoinType(leftEdge.getJoinType(),rightEdge.getJoinType())) {
    JoinedRelationsVertex tempLeftChild=new JoinedRelationsVertex(leftEdge);
    JoinEdge tempEdge=context.getCachedOrNewJoinEdge(rightEdge.getJoinSpec(),tempLeftChild,rightEdge.getRightVertex());
    if ((rightEdge.getJoinType() != JoinType.INNER && rightEdge.getJoinType() != JoinType.CROSS && rightEdge.getJoinType() != JoinType.LEFT_SEMI && rightEdge.getJoinType() != JoinType.LEFT_ANTI) || (leftEdge.getJoinType() != JoinType.INNER && leftEdge.getJoinType() != JoinType.CROSS && leftEdge.getJoinType() != JoinType.LEFT_SEMI && leftEdge.getJoinType() != JoinType.LEFT_ANTI)) {
      if (!findJoinConditionForJoinVertex(context.getCandidateJoinConditions(),tempEdge,true).isEmpty()) {
        return false;
      }
      if (!findJoinConditionForJoinVertex(context.getCandidateJoinFilters(),tempEdge,true).isEmpty()) {
        return false;
      }
    }
    return true;
  }
  return false;
}

private static void addToReversePostOrderListIterative(Statement root,List<? super Statement> lst){
  LinkedList<Statement> stackNode=new LinkedList<>();
  LinkedList<Integer> stackIndex=new LinkedList<>();
  HashSet<Statement> setVisited=new HashSet<>();
  stackNode.add(root);
  stackIndex.add(0);
  while (!stackNode.isEmpty()) {
    Statement node=stackNode.getLast();
    int index=stackIndex.removeLast();
    setVisited.add(node);
    List<StatEdge> lstEdges=node.getAllSuccessorEdges();
    for (; index < lstEdges.size(); index++) {
      StatEdge edge=lstEdges.get(index);
      Statement succ=edge.getDestination();
      if (!setVisited.contains(succ) && (edge.getType() == StatEdge.TYPE_REGULAR || edge.getType() == StatEdge.TYPE_EXCEPTION)) {
        stackIndex.add(index + 1);
        stackNode.add(succ);
        stackIndex.add(0);
        break;
      }
    }
    if (index == lstEdges.size()) {
      lst.add(0,node);
      stackNode.removeLast();
    }
  }
}

/** 
 * Converts the given wallet to the object representation of the protocol buffers. This can be modified, or additional data fields set, before serialization takes place.
 */
public Protos.Wallet walletToProto(Wallet wallet){
  Protos.Wallet.Builder walletBuilder=Protos.Wallet.newBuilder();
  walletBuilder.setNetworkIdentifier(wallet.getNetworkParameters().getId());
  if (wallet.getDescription() != null) {
    walletBuilder.setDescription(wallet.getDescription());
  }
  for (  WalletTransaction wtx : wallet.getWalletTransactions()) {
    Protos.Transaction txProto=makeTxProto(wtx);
    walletBuilder.addTransaction(txProto);
  }
  walletBuilder.addAllKey(wallet.serializeKeyChainGroupToProtobuf());
  for (  Script script : wallet.getWatchedScripts()) {
    Protos.Script protoScript=Protos.Script.newBuilder().setProgram(ByteString.copyFrom(script.getProgram())).setCreationTimestamp(script.getCreationTimeSeconds() * 1000).build();
    walletBuilder.addWatchedScript(protoScript);
  }
  Sha256Hash lastSeenBlockHash=wallet.getLastBlockSeenHash();
  if (lastSeenBlockHash != null) {
    walletBuilder.setLastSeenBlockHash(hashToByteString(lastSeenBlockHash));
    walletBuilder.setLastSeenBlockHeight(wallet.getLastBlockSeenHeight());
  }
  if (wallet.getLastBlockSeenTimeSecs() > 0)   walletBuilder.setLastSeenBlockTimeSecs(wallet.getLastBlockSeenTimeSecs());
  KeyCrypter keyCrypter=wallet.getKeyCrypter();
  if (keyCrypter == null) {
    walletBuilder.setEncryptionType(EncryptionType.UNENCRYPTED);
  }
 else {
    walletBuilder.setEncryptionType(keyCrypter.getUnderstoodEncryptionType());
    if (keyCrypter instanceof KeyCrypterScrypt) {
      KeyCrypterScrypt keyCrypterScrypt=(KeyCrypterScrypt)keyCrypter;
      walletBuilder.setEncryptionParameters(keyCrypterScrypt.getScryptParameters());
    }
 else {
      throw new RuntimeException("The wallet has encryption of type '" + keyCrypter.getUnderstoodEncryptionType() + "' but this WalletProtobufSerializer does not know how to persist this.");
    }
  }
  if (wallet.getKeyRotationTime() != null) {
    long timeSecs=wallet.getKeyRotationTime().getTime() / 1000;
    walletBuilder.setKeyRotationTime(timeSecs);
  }
  populateExtensions(wallet,walletBuilder);
  for (  Map.Entry<String,ByteString> entry : wallet.getTags().entrySet()) {
    Protos.Tag.Builder tag=Protos.Tag.newBuilder().setTag(entry.getKey()).setData(entry.getValue());
    walletBuilder.addTags(tag);
  }
  walletBuilder.setVersion(wallet.getVersion());
  return walletBuilder.build();
}

