private Map<String,NameValue> loadValues(ResultSet rs) throws SQLException {
  Map<String,NameValue> map=new LinkedHashMap<>();
  JsonNode node=readJson(rs,"event_values");
  Iterator<Map.Entry<String,JsonNode>> i=node.fields();
  while (i.hasNext()) {
    Map.Entry<String,JsonNode> child=i.next();
    String key=child.getKey();
    JsonNode nameValue=child.getValue();
    map.put(key,new NameValue(nameValue.path("name").asText(),nameValue.path("value").asText()));
  }
  return map;
}

public void process(Exchange exchange) throws Exception {
  Subject subject=exchange.getIn().getHeader(Exchange.AUTHENTICATION,Subject.class);
  if (subject != null && subject.getPrincipals() != null && !subject.getPrincipals().isEmpty()) {
    UsernamePasswordAuthenticationToken authToken=null;
    for (    Principal principal : subject.getPrincipals()) {
      if (principal instanceof WSUsernameTokenPrincipalImpl) {
        authToken=new UsernamePasswordAuthenticationToken(principal.getName(),((WSUsernameTokenPrincipalImpl)principal).getPassword());
        break;
      }
    }
    if (authToken != null) {
      subject.getPrincipals().clear();
      subject.getPrincipals().add(authToken);
    }
  }
}

