/** 
 * This is called when closure is initiated on the remote side. By convention we receive the close message only after we have ACKed the last data segment. <p/> We soft-close the InputStream which allows us to read data already received. <p/> We hard-close our output stream and discard all queued, unACKed data as the remote side doesn't want to receive it (the remote side has already unbound themselves, they just want our close ACK in order to clean up.)
 * @throws IOException if an I/O error occurs
 */
protected void closeFromRemote() throws IOException {
synchronized (closeLock) {
    Logging.logCheckedDebug(LOG,"Received a remote close request.",this);
    if (isBound() && (ros != null && ros.isQueueEmpty())) {
      sendCloseACK();
    }
    if (isConnected()) {
      setConnected(false);
      if (isReliable) {
        ris.softClose();
        ros.hardClose();
      }
 else {
        nonReliableInputStream.softClose();
        nonReliableOutputStream.hardClose();
      }
    }
    if (closeAckReceived) {
      closeLock.notifyAll();
    }
  }
}

