public SchemaRegistry(final ValidatedConfiguration vc){
  final ImmutableMap<String,MappingConfiguration> mappings=vc.configuration().mappings;
  final ImmutableMap<String,Optional<String>> schemaLocationsByMapping=ImmutableMap.copyOf(Maps.transformValues(mappings,config -> config.schemaFile));
  logger.debug("Loading schemas for mappings: {}",schemaLocationsByMapping.keySet());
  final ImmutableMap<Optional<String>,Schema> schemasByLocation=schemaLocationsByMapping.values().stream().distinct().collect(ImmutableMap.toImmutableMap(Function.identity(),SchemaRegistry::loadSchema));
  schemasByMappingName=ImmutableMap.copyOf(Maps.transformValues(mappings,config -> new DivolteSchema(schemasByLocation.get(config.schemaFile),config.confluentId)));
  logger.info("Loaded schemas used for mappings: {}",schemasByMappingName.keySet());
  schemasBySinkName=mappings.entrySet().stream().flatMap(mapping -> {
    final DivolteSchema divolteSchema=schemasByMappingName.get(mapping.getKey());
    return mapping.getValue().sinks.stream().map(sink -> Maps.immutableEntry(sink,divolteSchema));
  }
).distinct().collect(ImmutableMap.toImmutableMap(Map.Entry::getKey,Map.Entry::getValue));
  logger.info("Inferred schemas used for sinks: {}",schemasBySinkName.keySet());
}

public double compute(int i,int j){
  if (i == 0)   return -j * gapCost;
  if (j == 0)   return -i * gapCost;
  return max3(get(i - 1,j - 1) + charMatchScore.matchScore(sAt(i),tAt(j)),get(i - 1,j) - gapCost,get(i,j - 1) - gapCost);
}
