@Nullable @Override public V removeKey(@Nullable Object key){
  int hash=hash(key);
  int i=index(hash,this.entries.length);
  HashEntry<K,V> prev=this.entries[i];
  HashEntry<K,V> e=prev;
  while (e != null) {
    HashEntry<K,V> next=e.next;
    Object k;
    if (e.hash == hash && ((k=e.key) == key || key != null && key.equals(k))) {
      this.size--;
      if (prev == e) {
        this.entries[i]=next;
      }
 else {
        prev.next=next;
      }
      return e.value;
    }
    prev=e;
    e=next;
  }
  return null;
}

