@NotNull protected Quotes needsQuotes(@NotNull CharSequence s){
  @NotNull Quotes quotes=Quotes.NONE;
  if (s.length() == 0)   return Quotes.DOUBLE;
  if (STARTS_QUOTE_CHARS.get(s.charAt(0)) || Character.isWhitespace(s.charAt(s.length() - 1)))   return Quotes.DOUBLE;
  for (int i=0; i < s.length(); i++) {
    char ch=s.charAt(i);
    if (QUOTE_CHARS.get(ch) || ch < ' ' || ch > 127)     return Quotes.DOUBLE;
    if (ch == '"')     quotes=Quotes.SINGLE;
  }
  return quotes;
}

protected void processArgument(Object object,StringBuilder builder,List<WebElement> elements){
