/** 
 * Gets the value of the field in the given instance as String. Currently only allows primitive types, boxed types, String and Enum.
 */
private String getStringValue(Object instance,Field field) throws IllegalAccessException {
  Class<?> fieldType=field.getType();
  if (!fieldType.isPrimitive() && !Primitives.isWrapperType(fieldType) && !String.class.equals(fieldType)&& !fieldType.isEnum()) {
    throw new IllegalArgumentException(String.format("Unsupported property type %s of field %s in class %s.",fieldType.getName(),field.getName(),field.getDeclaringClass().getName()));
  }
  if (!field.isAccessible()) {
    field.setAccessible(true);
  }
  Object value=field.get(instance);
  if (value == null) {
    return null;
  }
  return fieldType.isEnum() ? ((Enum<?>)value).name() : value.toString();
}

