/** 
 * Check IP filter is valid.
 * @param filter a connection URL string indicating which sendersare allowed to cause the MIDlet to be launched
 * @exception IllegalArgumentException if the connection contains no portvalue
 */
protected void checkIIPFilter(String filter) throws IllegalArgumentException {
  int len=filter.length();
  int dotCount=0;
  boolean dotUnexpected=true;
  boolean failed=false;
  if (!"*".equals(filter)) {
    for (int i=0; i < len && !failed; i++) {
      char c=filter.charAt(i);
      if (c == '.') {
        if (dotUnexpected || i == len - 1) {
          failed=true;
        }
 else {
          dotCount++;
          if (dotCount > IP4_DELIMITER_COUNT) {
            failed=true;
          }
          dotUnexpected=true;
        }
      }
 else       if (c != '?' && c != '*' && !('0' <= c && c <= '9')) {
        failed=true;
      }
 else {
        dotUnexpected=false;
      }
    }
    if (failed || dotCount < IP4_DELIMITER_COUNT) {
      throw new IllegalArgumentException("IP Filter \"" + filter + "\" is invalid");
    }
  }
}

