@Override public boolean isValid(Condition cond,ConstraintValidatorContext context){
  if (cond == null || cond.fragmentPolicy == null) {
    return true;
  }
  if (cond instanceof ForwardNatRule) {
    return isValid((ForwardNatRule)cond,context);
  }
 else {
    if (cond.hasL4Fields() && (cond.fragmentPolicy == Condition.FragmentPolicy.any || cond.fragmentPolicy == Condition.FragmentPolicy.nonheader)) {
      context.disableDefaultConstraintViolation();
      context.buildConstraintViolationWithTemplate(getMessage(FRAG_POLICY_INVALID_FOR_L4_RULE,(Object)cond)).addConstraintViolation();
      return false;
    }
  }
  return true;
}
private boolean isValid(ForwardNatRule fnr,ConstraintValidatorContext context){
  boolean unfragmentedOnly=!fnr.isFloatingIp() || fnr.hasL4Fields();
  if (unfragmentedOnly && fnr.fragmentPolicy != Condition.FragmentPolicy.unfragmented) {
    context.disableDefaultConstraintViolation();
    context.buildConstraintViolationWithTemplate(getMessage(FRAG_POLICY_INVALID_FOR_NAT_RULE,(Object)fnr)).addConstraintViolation();
    return false;
  }
  return true;
}

