@SuppressWarnings("unchecked") public void onDrag(DraggableHandler handler,DragContext ctx,GqEvent e){
  List<SnapElement> snapElements=$(ctx.getDraggable()).data(SNAP_ELEMENTS_KEY,ArrayList.class);
  int snapTolerance=handler.getOptions().getSnapTolerance();
  SnapMode snapMode=handler.getOptions().getSnapMode();
  int helperLeft=handler.getAbsolutePosition().left;
  int helperRight=helperLeft + handler.getHelperDimension().getWidth();
  int helperTop=handler.getAbsolutePosition().top;
  int helperBottom=helperTop + handler.getHelperDimension().getHeight();
  for (  SnapElement snapElement : snapElements) {
    int snapElementLeft=snapElement.getOffset().left;
    int snapElementRight=snapElementLeft + snapElement.getWidth();
    int snapElementTop=snapElement.getOffset().top;
    int snapElementBottom=snapElementTop + snapElement.getHeight();
    if (!((snapElementLeft - snapTolerance < helperLeft && helperLeft < snapElementRight + snapTolerance && snapElementTop - snapTolerance < helperTop && helperTop < snapElementBottom + snapTolerance) || (snapElementLeft - snapTolerance < helperLeft && helperLeft < snapElementRight + snapTolerance && snapElementTop - snapTolerance < helperBottom && helperBottom < snapElementBottom + snapTolerance) || (snapElementLeft - snapTolerance < helperRight && helperRight < snapElementRight + snapTolerance && snapElementTop - snapTolerance < helperTop && helperTop < snapElementBottom + snapTolerance)|| (snapElementLeft - snapTolerance < helperRight && helperRight < snapElementRight + snapTolerance && snapElementTop - snapTolerance < helperBottom && helperBottom < snapElementBottom + snapTolerance))) {
      continue;
    }
    Offset newTopDimension=null;
    Offset newLeftDimension=null;
    if (SnapMode.INNER != snapMode) {
      boolean snapTop=Math.abs(snapElementTop - helperBottom) <= snapTolerance;
      boolean snapBottom=Math.abs(snapElementBottom - helperTop) <= snapTolerance;
      boolean snapLeft=Math.abs(snapElementLeft - helperRight) <= snapTolerance;
      boolean snapRight=Math.abs(snapElementRight - helperLeft) <= snapTolerance;
      if (snapTop) {
        newTopDimension=handler.convertPositionTo(false,new Offset(0,snapElementTop - handler.getHelperDimension().getHeight()));
      }
 else       if (snapBottom) {
        newTopDimension=handler.convertPositionTo(false,new Offset(0,snapElementBottom));
      }
      if (snapLeft) {
        newLeftDimension=handler.convertPositionTo(false,new Offset(snapElementLeft - handler.getHelperDimension().getWidth(),0));
      }
 else       if (snapRight) {
        newLeftDimension=handler.convertPositionTo(false,new Offset(snapElementRight,0));
      }
    }
    if (SnapMode.OUTER != snapMode) {
      boolean snapTop=Math.abs(snapElementTop - helperTop) <= snapTolerance;
      boolean snapBottom=Math.abs(snapElementBottom - helperBottom) <= snapTolerance;
      boolean snapLeft=Math.abs(snapElementLeft - helperLeft) <= snapTolerance;
      boolean snapRight=Math.abs(snapElementRight - helperRight) <= snapTolerance;
      if (snapTop) {
        newTopDimension=handler.convertPositionTo(false,new Offset(0,snapElementTop));
      }
 else       if (snapBottom) {
        newTopDimension=handler.convertPositionTo(false,new Offset(0,snapElementBottom - handler.getHelperDimension().getHeight()));
      }
      if (snapLeft) {
        newLeftDimension=handler.convertPositionTo(false,new Offset(snapElementLeft,0));
      }
 else       if (snapRight) {
        newLeftDimension=handler.convertPositionTo(false,new Offset(snapElementRight - handler.getHelperDimension().getWidth(),0));
      }
    }
    if (newTopDimension != null) {
      int newTop=newTopDimension.top - handler.getMargin().top;
      int newLeft=handler.getPosition().left;
      handler.setPosition(new Offset(newLeft,newTop));
    }
    if (newLeftDimension != null) {
      int newTop=handler.getPosition().top;
      int newLeft=newLeftDimension.left - handler.getMargin().left;
      handler.setPosition(new Offset(newLeft,newTop));
    }
