/** 
 * Adds a value to a subject. If the value is an array, all values in the array will be added. Note: If the value is a subject that already exists as a property of the given subject, this method makes no attempt to deeply merge properties. Instead, the value will not be added.
 * @param subject the subject to add the value to.
 * @param property the property that relates the value to the subject.
 * @param value the value to add.
 * @param [propertyIsArray] true if the property is always an array, falseif not (default: false).
 * @param [allowDuplicate] true if the property is a @list, false if not(default: false).
 */
static void addValue(Map<String,Object> subject,String property,Object value,boolean propertyIsArray,boolean allowDuplicate){
  if (isArray(value)) {
    if (((List)value).isEmpty() && propertyIsArray && !subject.containsKey(property)) {
      subject.put(property,new ArrayList<>());
    }
    for (    final Object val : (List)value) {
      addValue(subject,property,val,propertyIsArray,allowDuplicate);
    }
  }
 else   if (subject.containsKey(property)) {
    final boolean hasValue=!allowDuplicate && hasValue(subject,property,value);
    if (!isArray(subject.get(property)) && (!hasValue || propertyIsArray)) {
      final List<Object> tmp=new ArrayList<>();
      tmp.add(subject.get(property));
      subject.put(property,tmp);
    }
    if (!hasValue) {
      ((List<Object>)subject.get(property)).add(value);
    }
  }
 else {
    Object tmp;
    if (propertyIsArray) {
      tmp=new ArrayList<>();
      ((List<Object>)tmp).add(value);
    }
 else {
      tmp=value;
    }
    subject.put(property,tmp);
  }
}
static void addValue(Map<String,Object> subject,String property,Object value,boolean propertyIsArray){
  addValue(subject,property,value,propertyIsArray,true);
}
static void addValue(Map<String,Object> subject,String property,Object value){
  addValue(subject,property,value,false,true);
}

