@Override public void unmarshal(ObjectInput buffer) throws IOException, ClassNotFoundException {
  super.sourceFederate=buffer.readInt();
  super.targetFederation=buffer.readInt();
  super.timestamp=buffer.readDouble();
  this.tag=buffer.readUTF().getBytes();
  if (this.attributes == null)   this.attributes=new HashMap<Integer,byte[]>();
  int attributeCount=buffer.readInt();
  for (int i=0; i < attributeCount; i++) {
    int attributeHandle=buffer.readInt();
    int valueSize=buffer.readInt();
    byte[] attributeValue=new byte[valueSize];
    buffer.readFully(attributeValue,0,valueSize);
    this.attributes.put(attributeHandle,attributeValue);
  }
}

protected boolean applyConditions(BsonArray conditions,BsonDocument json,final RequestContext context){
  return conditions.stream().allMatch(_condition -> {
    if (_condition.isDocument()) {
      BsonDocument condition=_condition.asDocument();
      String path=null;
      BsonValue _path=condition.get("path");
      if (_path != null && _path.isString()) {
        path=_path.asString().getValue();
      }
      String type=null;
      BsonValue _type=condition.get("type");
      if (_type != null && _type.isString()) {
        type=_type.asString().getValue();
      }
      Set<Integer> counts=new HashSet<>();
      BsonValue _count=condition.get("count");
      if (_count != null) {
        if (_count.isInt32()) {
          counts.add(_count.asInt32().getValue());
        }
 else         if (_count.isArray()) {
          BsonArray countsArray=_count.asArray();
