public int distanceMap(int[] map,int width,int height){
  int xmax=width - 3;
  int ymax=height - 3;
  int max=0;
  int v;
  for (int y=0; y < height; y++) {
    for (int x=0; x < width; x++) {
      int offset=x + y * width;
      if (map[offset] > 0) {
        if (x < 2 || x > xmax || y < 2 || y > ymax)         v=setEdgeValue(x,y,map,width,offset,xmax,ymax);
 else         v=setValue(map,width,offset);
        if (v > max)         max=v;
      }
    }
  }
  for (int y=height - 1; y >= 0; y--) {
    for (int x=width - 1; x >= 0; x--) {
      int offset=x + y * width;
      if (map[offset] > 0) {
        if (x < 2 || x > xmax || y < 2 || y > ymax)         v=setEdgeValue(x,y,map,width,offset,xmax,ymax);
 else         v=setValue(map,width,offset);
        if (v > max)         max=v;
      }
    }
  }
  return max;
}

