public static void main(String[] args) throws Exception {
  Properties properties=new Properties();
  AppProps.setApplicationName(properties,"cascading hive integration demo");
  HiveTableDescriptor dualTableDescriptor=new HiveTableDescriptor("dual",new String[]{"value"},new String[]{"string"});
  HiveTap dualTap=new HiveTap(dualTableDescriptor,dualTableDescriptor.toScheme(),REPLACE,true);
  HiveFlow loadDataFlow=new HiveFlow("load data into dual",new String[]{String.format("load data local inpath '%s' overwrite into table dual",dualTableInputFile)},Arrays.<Tap>asList(new Hfs(new NullScheme(),dualTableInputFile)),dualTap);
  HiveTableDescriptor keyValueDescriptor=new HiveTableDescriptor("keyvalue",new String[]{"key","value"},new String[]{"string","string"});
  HiveTap keyvalueTap=new HiveTap(keyValueDescriptor,keyValueDescriptor.toScheme(),SinkMode.REPLACE,true);
  String queries[]={"insert overwrite table keyvalue select 'Hello' as key, 'hive!' as value from dual","insert into table keyvalue select 'Multiple' as key, 'queries' as value from dual","insert into table keyvalue select 'are' as key, 'supported' as value from dual"};
  HiveFlow selectFlow=new HiveFlow("select data from dual into keyvalue",queries,Arrays.<Tap>asList(dualTap),keyvalueTap);
  HiveTableDescriptor keyValueDescriptor2=new HiveTableDescriptor("keyvalue2",new String[]{"key","value"},new String[]{"string","string"});
  HiveTap keyvalue2Tap=new HiveTap(keyValueDescriptor2,keyValueDescriptor2.toScheme(),SinkMode.REPLACE,true);
class Upper extends BaseOperation implements Function {
    public Upper(    Fields fieldDeclaration){
      super(2,fieldDeclaration);
    }
    @Override public void operate(    FlowProcess flowProcess,    FunctionCall functionCall){
      TupleEntry argument=functionCall.getArguments();
      String key=argument.getString(0).toUpperCase();
      String value=argument.getString(1).toUpperCase();
      Tuple result=new Tuple(key,value);
      functionCall.getOutputCollector().add(result);
    }
  }
  Pipe upperPipe=new Each("uppercase kv -> kv2 ",keyvalueTap.getSinkFields(),new Upper(keyvalueTap.getSinkFields()),Fields.RESULTS);
  Flow<?> pureCascadingFlow=new Hadoop2MR1FlowConnector().connect(keyvalueTap,keyvalue2Tap,upperPipe);
  Cascade cascade=new CascadeConnector(properties).connect(pureCascadingFlow,loadDataFlow,selectFlow);
  cascade.complete();
  Class.forName("org.apache.hive.jdbc.HiveDriver");
  Connection con=DriverManager.getConnection("jdbc:hive2://","","");
  Statement stmt=con.createStatement();
  ResultSet rs=stmt.executeQuery("select key, value from keyvalue2");
  System.out.println("----------------------Hive JDBC--------------------------");
  while (rs.next())   System.out.printf("data from hive table copy: key=%s,value=%s\n",rs.getString(1),rs.getString(2));
  System.out.println("---------------------------------------------------------");
  stmt.close();
  con.close();
}

