/** 
 * Find the property that's being overridden on this type, if any. <p>Said property could be a method, field, getter, or setter. We don't distinguish between these when looking up a property type.
 */
private JSType findOverriddenProperty(ObjectType ownerType,String propName,TemplateTypeMap typeMap){
  JSType result=null;
  JSType propType=ownerType.getPropertyType(propName);
  if (propType != null && !propType.isUnknownType()) {
    result=propType;
  }
 else {
    for (    ObjectType iface : ownerType.getCtorImplementedInterfaces()) {
      propType=iface.getPropertyType(propName);
      if (propType != null && !propType.isUnknownType()) {
        result=propType;
        break;
      }
    }
  }
  if (result != null && typeMap != null && !typeMap.isEmpty()) {
    result=result.visit(TemplateTypeReplacer.forPartialReplacement(typeRegistry,typeMap));
  }
  return result;
}

private String attributeValueWithEL(boolean isTag,String tx,Class<?> expectedType,String mapName){
  if (tx == null)   return null;
  Class<?> type=expectedType;
  int size=tx.length();
  StringBuffer output=new StringBuffer(size);
  boolean el=false;
  int i=0;
  int mark=0;
  char ch;
  while (i < size) {
    ch=tx.charAt(i);
    if (!el && i + 1 < size && ch == '$' && tx.charAt(i + 1) == '{') {
      if (mark < i) {
        if (output.length() > 0) {
          output.append(" + ");
          type=String.class;
        }
        output.append(quote(tx.substring(mark,i)));
      }
      mark=i;
      el=true;
      i+=2;
    }
 else     if (ch == '\\' && i + 1 < size && (tx.charAt(i + 1) == '$' || tx.charAt(i + 1) == '}')) {
      i+=2;
    }
 else     if (el && ch == '}') {
      if (output.length() > 0) {
        output.append(" + ");
        type=String.class;
      }
      output.append(JspUtil.interpreterCall(isTag,tx.substring(mark,i + 1),type,mapName,false));
      mark=i + 1;
      el=false;
      ++i;
    }
 else {
      ++i;
    }
  }
  if (!el && mark < i) {
    if (output.length() > 0) {
      output.append(" + ");
    }
    output.append(quote(tx.substring(mark,i)));
  }
  return output.toString();
}

