void read(XMLEventReader reader,StartElement parentElement,T t,String... names) throws XMLStreamException {
  while (reader.hasNext()) {
    XMLEvent event=reader.peek();
    if (!parseAnnotations) {
      XMLEvent eventBefore=event;
      event=skipAnnotations(reader,event);
      if (eventBefore != event) {
        continue;
      }
    }
    if (!event.isStartElement() && !event.isEndElement()) {
      reader.nextEvent();
      continue;
    }
    if (parentElement != null && event.isEndElement() && ((EndElement)event).getName().equals(parentElement.getName())) {
      break;
    }
    boolean hit=false;
    for (    String name : names) {
      if (event.isStartElement()) {
        StartElement element=event.asStartElement();
        if (element.getName().getLocalPart().equals(name)) {
          reader.nextEvent();
          build(reader,element,t,name);
          hit=true;
          break;
        }
      }
      if (event.isEndElement()) {
        EndElement e=event.asEndElement();
        if (e.getName().getLocalPart().equals(name)) {
          reader.nextEvent();
          hit=true;
          break;
        }
      }
    }
    if (!hit) {
      break;
    }
  }
}

