@Override public boolean nextRow() throws DataReadException {
  if (overflow)   throw new DataReadException("Data read overflow: the limit has already been reached! No more data can be read.");
  boolean nextRow;
  try {
    nextRow=innerIt.nextRow();
    countRow++;
  }
 catch (  DataReadException ex) {
    ExceededSizeException exceedEx=getExceededSizeException(ex);
    if (exceedEx != null) {
      overflow=true;
      throw new DataReadException(exceedEx.getMessage());
    }
 else     throw ex;
  }
  if (nextRow && maxNbRows >= 0 && countRow > maxNbRows) {
    overflow=true;
    throw new DataReadException("Data read overflow: the limit of " + maxNbRows + " rows has been reached!");
  }
  return nextRow;
}

@Override public boolean addClientRoute(JID route,LocalClientSession destination){
  boolean added;
  boolean available=destination.getPresence().isAvailable();
  Log.debug("Adding client route {}",route);
  localRoutingTable.addRoute(new DomainPair("",route.toString()),destination);
  if (destination.getAuthToken().isAnonymous()) {
    Lock lockAn=CacheFactory.getLock(route.toString(),anonymousUsersCache);
    try {
      lockAn.lock();
      added=anonymousUsersCache.put(route.toString(),new ClientRoute(server.getNodeID(),available)) == null;
    }
  finally {
      lockAn.unlock();
    }
    if (route.getResource() != null && (!available || added)) {
      Lock lock=CacheFactory.getLock(route.toBareJID(),usersSessions);
      try {
        lock.lock();
        usersSessions.put(route.toBareJID(),new HashSet<>(Collections.singletonList(route.toString())));
      }
  finally {
        lock.unlock();
      }
    }
  }
 else {
    Lock lockU=CacheFactory.getLock(route.toString(),usersCache);
    try {
      lockU.lock();
      added=usersCache.put(route.toString(),new ClientRoute(server.getNodeID(),available)) == null;
    }
  finally {
      lockU.unlock();
    }
    if (route.getResource() != null && (!available || added)) {
      Lock lock=CacheFactory.getLock(route.toBareJID(),usersSessions);
      try {
        lock.lock();
        HashSet<String> jids=usersSessions.get(route.toBareJID());
        if (jids == null) {
          jids=new HashSet<>();
        }
        jids.add(route.toString());
        usersSessions.put(route.toBareJID(),jids);
      }
  finally {
        lock.unlock();
      }
    }
  }
  return added;
}

/** 
 * Parse UUID from bytes. The  {@code uuidBytes} can represent a 16-bit, 32-bit or 128-bit UUID,but the returned UUID is always in 128-bit format. Note UUID is little endian in Bluetooth.
 * @param uuidBytes Byte representation of uuid.
 * @return {@link ParcelUuid} parsed from bytes.
 * @throws IllegalArgumentException If the {@code uuidBytes} cannot be parsed.Copied from java/android/bluetooth/BluetoothUuid.java Copyright (C) 2009 The Android Open Source Project Licensed under the Apache License, Version 2.0
 */
private static ParcelUuid parseUuidFrom(byte[] uuidBytes){
  final int UUID_BYTES_16_BIT=2;
  final int UUID_BYTES_32_BIT=4;
  final int UUID_BYTES_128_BIT=16;
  final ParcelUuid BASE_UUID=ParcelUuid.fromString("00000000-0000-1000-8000-00805F9B34FB");
  if (uuidBytes == null) {
    throw new IllegalArgumentException("uuidBytes cannot be null");
  }
  int length=uuidBytes.length;
  if (length != UUID_BYTES_16_BIT && length != UUID_BYTES_32_BIT && length != UUID_BYTES_128_BIT) {
    throw new IllegalArgumentException("uuidBytes length invalid - " + length);
  }
  if (length == UUID_BYTES_128_BIT) {
    ByteBuffer buf=ByteBuffer.wrap(uuidBytes).order(ByteOrder.LITTLE_ENDIAN);
    long msb=buf.getLong(8);
    long lsb=buf.getLong(0);
    return new ParcelUuid(new UUID(msb,lsb));
  }
  long shortUuid;
  if (length == UUID_BYTES_16_BIT) {
    shortUuid=uuidBytes[0] & 0xFF;
    shortUuid+=(uuidBytes[1] & 0xFF) << 8;
  }
 else {
    shortUuid=uuidBytes[0] & 0xFF;
    shortUuid+=(uuidBytes[1] & 0xFF) << 8;
    shortUuid+=(uuidBytes[2] & 0xFF) << 16;
    shortUuid+=(uuidBytes[3] & 0xFF) << 24;
  }
  long msb=BASE_UUID.getUuid().getMostSignificantBits() + (shortUuid << 32);
  long lsb=BASE_UUID.getUuid().getLeastSignificantBits();
  return new ParcelUuid(new UUID(msb,lsb));
}

