public void endElement(String uri,String localName,String qName) throws SAXException {
  processChars();
  if (directivesOnly && !(JSP_URI.equals(uri) && localName.startsWith(DIRECTIVE_ACTION))) {
    return;
  }
  if (current instanceof Node.NamedAttribute) {
    boolean isTrim=((Node.NamedAttribute)current).isTrim();
    Node.Nodes subElems=((Node.NamedAttribute)current).getBody();
    for (int i=0; subElems != null && i < subElems.size(); i++) {
      Node subElem=subElems.getNode(i);
      if (!(subElem instanceof Node.TemplateText)) {
        continue;
      }
      if (i == 0) {
        if (isTrim) {
          ((Node.TemplateText)subElem).ltrim();
        }
      }
 else       if (i == subElems.size() - 1) {
        if (isTrim) {
          ((Node.TemplateText)subElem).rtrim();
        }
      }
 else {
        if (((Node.TemplateText)subElem).isAllSpace()) {
          subElems.remove(subElem);
        }
      }
    }
  }
 else   if (current instanceof Node.ScriptingElement) {
    checkScriptingBody((Node.ScriptingElement)current);
  }
  if (isTagDependent(current)) {
    tagDependentNesting--;
  }
  if (scriptlessBodyNode != null && current.equals(scriptlessBodyNode)) {
    scriptlessBodyNode=null;
  }
  if (current.getParent() != null) {
    current=current.getParent();
  }
}

HashMap<String,BsonValue> getPropsValues(final HttpServerExchange exchange,final RequestContext context){
  HashMap<String,BsonValue> properties=new HashMap<>();
  String _userName=ExchangeAttributes.remoteUser().readAttribute(exchange);
  BsonValue userName=_userName != null ? new BsonString(_userName) : BsonNull.VALUE;
  properties.put("userName",userName);
  if (Objects.nonNull(exchange.getSecurityContext()) && Objects.nonNull(exchange.getSecurityContext().getAuthenticatedAccount()) && Objects.nonNull(exchange.getSecurityContext().getAuthenticatedAccount().getRoles())) {
    Set<String> roles=exchange.getSecurityContext().getAuthenticatedAccount().getRoles();
    BsonArray _roles=new BsonArray();
    roles.stream().map(role -> new BsonString(role)).forEachOrdered(role -> _roles.add(role));
    properties.put("userRoles",_roles);
  }
 else {
    properties.put("userRoles",new BsonNull());
  }
  properties.put("epochTimeStamp",new BsonDateTime(Instant.now().getEpochSecond() * 1000));
  properties.put("dateTime",new BsonString(ExchangeAttributes.dateTime().readAttribute(exchange)));
  properties.put("localIp",new BsonString(ExchangeAttributes.localIp().readAttribute(exchange)));
  properties.put("localPort",new BsonString(ExchangeAttributes.localPort().readAttribute(exchange)));
  properties.put("localServerName",new BsonString(ExchangeAttributes.localServerName().readAttribute(exchange)));
  properties.put("queryString",new BsonString(ExchangeAttributes.queryString().readAttribute(exchange)));
  properties.put("relativePath",new BsonString(ExchangeAttributes.relativePath().readAttribute(exchange)));
  properties.put("remoteIp",new BsonString(ExchangeAttributes.remoteIp().readAttribute(exchange)));
  properties.put("requestMethod",new BsonString(ExchangeAttributes.requestMethod().readAttribute(exchange)));
  properties.put("requestProtocol",new BsonString(ExchangeAttributes.requestProtocol().readAttribute(exchange)));
  return properties;
}

