/** 
 * Validate and extract the SAML protocol message from the artifact response.
 * @param artifactResponse the response to process
 * @return the SAML protocol message
 * @throws MessageDecodingException if the protocol message was not sent or there was a non-success status response
 */
@Nonnull private SAMLObject validateAndExtractResponseMessage(@Nonnull final ArtifactResponse artifactResponse) throws MessageDecodingException {
  if (artifactResponse.getStatus() == null || artifactResponse.getStatus().getStatusCode() == null || artifactResponse.getStatus().getStatusCode().getValue() == null) {
    throw new MessageDecodingException("ArtifactResponse included no StatusCode, could not validate");
  }
 else   if (!StatusCode.SUCCESS.equals(artifactResponse.getStatus().getStatusCode().getValue())) {
    throw new MessageDecodingException("ArtifactResponse carried non-success StatusCode: " + artifactResponse.getStatus().getStatusCode().getValue());
  }
  if (artifactResponse.getMessage() == null) {
    throw new MessageDecodingException("ArtifactResponse carried an empty message payload");
  }
  return artifactResponse.getMessage();
}

@Override public void detectAndSendChanges(){
  super.detectAndSendChanges();
  for (int i=0; i < tile.getInsertDirection().length; i++) {
    if (tile.getInsertDirection()[i] != lastInsertDirection[i] || initialUpdate) {
      sendSyncMessage(new MessageGUIByte(MessageGUI.DIRECTIONS_START + i,tile.getInsertDirection()[i]));
      lastInsertDirection[i]=tile.getInsertDirection()[i];
    }
  }
  if (tile.getMaxStackSize() != lastMaxStackSize || initialUpdate) {
    sendSyncMessage(new MessageGUIByte(MessageGUI.MAX_STACK_SIZE,tile.getMaxStackSize()));
    lastMaxStackSize=tile.getMaxStackSize();
  }
  if (tile.getSpreadItems() != lastSpreadItems || initialUpdate) {
    sendSyncMessage(new MessageGUIBoolean(MessageGUI.SPREAD_ITEMS,tile.getSpreadItems()));
    lastSpreadItems=tile.getSpreadItems();
  }
  if (tile instanceof TileBlockExtender) {
    boolean redstoneTransmissionEnabled=((TileBlockExtender)tile).isRedstoneTransmissionEnabled();
    if (tile instanceof TileBlockExtender && (redstoneTransmissionEnabled != lastRedstoneTransmission) || initialUpdate) {
      sendSyncMessage(new MessageGUIBoolean(MessageGUI.REDSTONE_ENABLED,redstoneTransmissionEnabled));
      lastRedstoneTransmission=redstoneTransmissionEnabled;
    }
  }
  if (initialUpdate) {
    initialUpdate=false;
  }
}

/** 
 * Combines runtime measurements with identical class names and method names into one measurement, assuming that they originate from a loop or a similar construct where a summary measurement has been intended.
 */
protected void combineRuntimeMeasurements(){
  RuntimeNode preceding=null;
  for (Iterator<RuntimeNode> iterator=children.iterator(); iterator.hasNext(); ) {
    final RuntimeNode child=iterator.next();
    if (preceding != null && preceding.timeStopped != 0 && child.timeStopped != 0 && preceding.timeStopped <= child.timeStarted && preceding.children.isEmpty() && child.children.isEmpty() && preceding.methodName.equals(child.methodName) && preceding.className.equals(child.className)) {
      preceding.timeStarted=child.timeStarted - (preceding.timeStopped - preceding.timeStarted);
      preceding.timeStopped=child.timeStopped;
      iterator.remove();
    }
 else {
      preceding=child;
      child.combineRuntimeMeasurements();
    }
  }
}

public void jdbcCreateView(Table tbl) throws AlreadyExistsException, InvalidObjectException, MetaException {
  LOG.debug("first, check the name is valid or not");
  if (!MetaStoreUtils.validateName(tbl.getTableName()) || !MetaStoreUtils.validateColNames(tbl.getSd().getCols()) || (tbl.getPriPartition() != null && !MetaStoreUtils.validateName(tbl.getPriPartition().getParKey().getName()))|| (tbl.getSubPartition() != null && !MetaStoreUtils.validateName(tbl.getSubPartition().getParKey().getName()))) {
    LOG.error("create view error db=" + tbl.getDbName() + ", view="+ tbl.getTableName());
    throw new InvalidObjectException(tbl.getTableName() + " is not a valid object name");
  }
  boolean success=false;
  Connection con;
  PreparedStatement ps=null;
  tbl.setDbName(tbl.getDbName().toLowerCase());
  tbl.setTableName(tbl.getTableName().toLowerCase());
  long tblID=genTblID(tbl.getDbName(),tbl.getTableName());
  try {
    con=getSegmentConnection(tbl.getDbName());
  }
 catch (  MetaStoreConnectException e1) {
    LOG.error("create view error db=" + tbl.getDbName() + ", view="+ tbl.getTableName()+ ",msg="+ e1.getMessage());
    throw new MetaException(e1.getMessage());
  }
catch (  SQLException e1) {
    LOG.error("create view error db=" + tbl.getDbName() + ", view="+ tbl.getTableName()+ ",msg="+ e1.getMessage());
    throw new MetaException(e1.getMessage());
  }
  try {
    con.setAutoCommit(false);
    con.setTransactionIsolation(Connection.TRANSACTION_REPEATABLE_READ);
    ps=con.prepareStatement("select tbl_id, tbl_type from TBLS where db_name=? and tbl_name=?");
    ps.setString(1,tbl.getDbName());
    ps.setString(2,tbl.getTableName());
    boolean isViewFind=false;
    String tblType=null;
    ResultSet tblSet=ps.executeQuery();
    while (tblSet.next()) {
      isViewFind=true;
      tblID=tblSet.getLong(1);
      tblType=tblSet.getString(2);
      break;
    }
    tblSet.close();
    ps.close();
    if (isViewFind && !tbl.isIsReplaceOnExit()) {
      LOG.error("view " + tbl.getDbName() + ":"+ tbl.getTableName()+ " has exist");
      throw new AlreadyExistsException("view " + tbl.getDbName() + ":"+ tbl.getTableName()+ " has exist");
    }
    if (isViewFind && tbl.isIsReplaceOnExit()) {
      if (tblType != null && !tblType.equalsIgnoreCase("VIRTUAL_VIEW")) {
        LOG.error("name conflict " + tbl.getDbName() + ":"+ tbl.getTableName()+ " already exist, and it is not a view");
        throw new MetaException("name conflict " + tbl.getDbName() + ":"+ tbl.getTableName()+ " already exist, and it is not a view");
      }
      ps=con.prepareStatement("update TBLS  set tbl_comment=? where tbl_id=? ");
      ps.setString(1,tbl.getParameters().get("comment"));
      ps.setLong(2,tblID);
      ps.executeUpdate();
      ps.close();
      ps=con.prepareStatement("update tdwview  set view_original_text=?, view_expanded_text=?, " + "vtables=? where tbl_id=? ");
      ps.setString(1,tbl.getViewOriginalText());
      ps.setString(2,tbl.getViewExpandedText());
      ps.setString(3,tbl.getVtables().toLowerCase());
      ps.setLong(4,tblID);
      ps.executeUpdate();
      ps.close();
      ps=con.prepareStatement("delete from COLUMNS where tbl_id=?");
      ps.setLong(1,tblID);
      ps.executeUpdate();
      ps.close();
      ps=con.prepareStatement("insert into COLUMNS(column_index, tbl_id, column_name, " + "type_name, comment) values(?,?,?,?,?)");
      List<FieldSchema> fieldSchemas=tbl.getSd().getCols();
      int size=fieldSchemas.size();
      for (int i=0; i < size; i++) {
        ps.setLong(1,i);
        ps.setLong(2,tblID);
        ps.setString(3,fieldSchemas.get(i).getName().toLowerCase());
        ps.setString(4,fieldSchemas.get(i).getType());
        ps.setString(5,fieldSchemas.get(i).getComment());
        ps.addBatch();
      }
      ps.executeBatch();
      ps.close();
      Map<String,String> tblPram=new HashMap<String,String>();
      ps=con.prepareStatement("select param_key, param_value from TABLE_PARAMS where tbl_id=? and param_type='TBL'");
      ps.setLong(1,tblID);
      ResultSet paramSet=ps.executeQuery();
      while (paramSet.next()) {
        tblPram.put(paramSet.getString(1),paramSet.getString(2));
      }
      paramSet.close();
      ps.close();
      ps=con.prepareStatement("delete from TABLE_PARAMS where tbl_id=? and param_type='TBL'");
      ps.setLong(1,tblID);
      ps.executeUpdate();
      ps.close();
      tblPram.putAll(tbl.getParameters());
      ps=con.prepareStatement("insert into TABLE_PARAMS(tbl_id, param_type, param_key, param_value) values(?,?,?,?)");
      for (      Entry<String,String> entry : tblPram.entrySet()) {
        ps.setLong(1,tblID);
        ps.setString(2,"TBL");
        ps.setString(3,entry.getKey());
        ps.setString(4,entry.getValue());
        ps.addBatch();
      }
      ps.executeBatch();
      ps.close();
      con.commit();
      success=true;
    }
 else {
      ps=con.prepareStatement("INSERT INTO TBLS(tbl_id, retention, tbl_type, db_name, " + "tbl_name, tbl_owner, tbl_comment)" + " values(?,?,?,?,?,?,?)");
      StorageDescriptor sd=tbl.getSd();
      if (sd == null || sd.getSerdeInfo() == null) {
        throw new MetaException("storage descriptor of table " + tbl.getTableName() + " is null");
      }
      ps.setLong(1,tblID);
      ps.setLong(2,tbl.getRetention());
      ps.setString(3,tbl.getTableType());
      ps.setString(4,tbl.getDbName());
      ps.setString(5,tbl.getTableName());
      ps.setString(6,tbl.getOwner().toLowerCase());
      ps.setString(7,tbl.getParameters().get("comment"));
      ps.executeUpdate();
      ps.close();
      ps=con.prepareStatement("INSERT INTO COLUMNS(column_index, tbl_id, column_name, type_name, comment) " + " values(?,?,?,?,?)");
      List<FieldSchema> fieldList=sd.getCols();
      int fieldSize=fieldList.size();
      for (int i=0; i < fieldSize; i++) {
        FieldSchema field=fieldList.get(i);
        ps.setInt(1,i);
        ps.setLong(2,tblID);
        ps.setString(3,field.getName());
        ps.setString(4,field.getType());
        ps.setString(5,field.getComment());
        ps.addBatch();
      }
      ps.executeBatch();
      ps.close();
      if (tbl.getParametersSize() > 0 || sd.getParametersSize() > 0 || sd.getSerdeInfo().getParametersSize() > 0) {
        ps=con.prepareStatement("insert into table_params(tbl_id, param_type, param_key, param_value) " + " values(?,?,?,?)");
        if (tbl.getParametersSize() > 0) {
          for (          Map.Entry<String,String> entry : tbl.getParameters().entrySet()) {
            if (entry.getKey().equalsIgnoreCase("type") || entry.getKey().equalsIgnoreCase("comment"))             break;
            ps.setLong(1,tblID);
            ps.setString(2,"TBL");
            ps.setString(3,entry.getKey());
            ps.setString(4,entry.getValue());
            ps.addBatch();
          }
        }
        if (sd.getParametersSize() > 0) {
          for (          Map.Entry<String,String> entry : sd.getParameters().entrySet()) {
            ps.setLong(1,tblID);
            ps.setString(2,"SD");
            ps.setString(3,entry.getKey());
            ps.setString(4,entry.getValue());
            ps.addBatch();
          }
        }
        if (sd.getSerdeInfo().getParametersSize() > 0) {
          for (          Map.Entry<String,String> entry : sd.getSerdeInfo().getParameters().entrySet()) {
            ps.setLong(1,tblID);
            ps.setString(2,"SERDE");
            ps.setString(3,entry.getKey());
            ps.setString(4,entry.getValue());
            ps.addBatch();
          }
        }
        ps.executeBatch();
        ps.close();
      }
      ps=con.prepareStatement("insert into tdwview(tbl_id, view_original_text, view_expanded_text, vtables) values(?,?,?,?)");
      ps.setLong(1,tblID);
      ps.setString(2,tbl.getViewOriginalText());
      ps.setString(3,tbl.getViewExpandedText());
      ps.setString(4,tbl.getVtables().toLowerCase());
      ps.executeUpdate();
      ps.close();
      con.commit();
      success=true;
    }
  }
 catch (  SQLException sqlex) {
    sqlex.printStackTrace();
    LOG.error("create view error db=" + tbl.getDbName() + ", view="+ tbl.getTableName()+ ", msg="+ sqlex.getMessage());
    throw new MetaException(sqlex.getMessage());
  }
 finally {
    if (!success) {
      try {
        con.rollback();
      }
 catch (      SQLException e) {
      }
    }
    closeStatement(ps);
    closeConnection(con);
  }
  return;
}

private List<FileNode> createNodeList(int numNodes){
  List<FileNode> nodes=new ArrayList<>();
  for (int i=0; i < numNodes; ++i) {
    Path file=basePath.resolve(RandomStringUtils.randomAlphabetic(12));
    boolean isFile=i % 2 == 0;
    byte[] hash=null;
    if (isFile) {
      hash=String.format("hash%d",i).getBytes();
    }
    FileNode node=createFileNode(file,isFile,hash);
    nodes.add(node);
  }
  return nodes;
}

