private static void moveToFirst(List<Pair> list,String keyName){
  Pair pair=null;
  Iterator<Pair> iterator=list.iterator();
  while (iterator.hasNext()) {
    Pair item=iterator.next();
    if (keyName.equals(item.key)) {
      pair=item;
      iterator.remove();
      break;
    }
  }
  if (pair != null) {
    list.add(0,pair);
  }
}

