/** 
 * Returns a function that converts the ResultSet column values into parameters to the constructor (with number of parameters equals the number of columns) of type <code>cls</code> then returns an instance of type <code>cls</code>. See  {@link Builder#autoMap(Class)}.
 * @param cls
 * @return
 */
static <T>ResultSetMapper<T> autoMap(final Class<T> cls){
  return new ResultSetMapper<T>(){
    @Override public T call(    ResultSet rs){
      return autoMap(rs,cls);
    }
  }
;
}
/** 
 * Converts the ResultSet column values into parameters to the constructor (with number of parameters equals the number of columns) of type <code>T</code> then returns an instance of type <code>T</code>. See See {@link Builder#autoMap(Class)}.
 * @param cls the class of the resultant instance
 * @return an automapped instance
 */
@SuppressWarnings("unchecked") static <T>T autoMap(ResultSet rs,Class<T> cls){
  try {
    if (cls.isInterface()) {
      return autoMapInterface(rs,cls);
    }
 else {
      int n=rs.getMetaData().getColumnCount();
      for (      Constructor<?> c : cls.getDeclaredConstructors()) {
        if (n == c.getParameterTypes().length) {
          return autoMap(rs,(Constructor<T>)c);
        }
      }
      throw new RuntimeException("constructor with number of parameters=" + n + "  not found in "+ cls);
    }
  }
 catch (  SQLException e) {
    throw new SQLRuntimeException(e);
  }
}
/** 
 * Converts the ResultSet column values into parameters to the given constructor (with number of parameters equals the number of columns) of type <code>T</code> then returns an instance of type <code>T</code>. See See  {@link Builder#autoMap(Class)}.
 * @param rs the result set row
 * @param c constructor to use for instantiation
 * @return automapped instance
 */
private static <T>T autoMap(ResultSet rs,Constructor<T> c){
  Class<?>[] types=c.getParameterTypes();
  List<Object> list=new ArrayList<Object>();
  for (int i=0; i < types.length; i++) {
    list.add(autoMap(getObject(rs,types[i],i + 1),types[i]));
  }
  try {
    return newInstance(c,list);
  }
 catch (  RuntimeException e) {
    throw new RuntimeException("problem with parameters=" + getTypeInfo(list) + ", rs types="+ getRowInfo(rs)+ ". Be sure not to use primitives in a constructor when calling autoMap().",e);
  }
}
/** 
 * Converts from java.sql Types to common java types like java.util.Date and numeric types. See  {@link Builder#autoMap(Class)}.
 * @param o
 * @param cls
 * @return
 */
public static Object autoMap(Object o,Class<?> cls){
  if (o == null)   return o;
 else   if (cls.isAssignableFrom(o.getClass())) {
    return o;
  }
 else {
    if (o instanceof java.sql.Date) {
      java.sql.Date d=(java.sql.Date)o;
      if (cls.isAssignableFrom(Long.class))       return d.getTime();
 else       if (cls.isAssignableFrom(BigInteger.class))       return BigInteger.valueOf(d.getTime());
 else       return o;
    }
 else     if (o instanceof java.sql.Timestamp) {
      Timestamp t=(java.sql.Timestamp)o;
      if (cls.isAssignableFrom(Long.class))       return t.getTime();
 else       if (cls.isAssignableFrom(BigInteger.class))       return BigInteger.valueOf(t.getTime());
 else       return o;
    }
 else     if (o instanceof java.sql.Time) {
      Time t=(java.sql.Time)o;
      if (cls.isAssignableFrom(Long.class))       return t.getTime();
 else       if (cls.isAssignableFrom(BigInteger.class))       return BigInteger.valueOf(t.getTime());
 else       return o;
    }
 else     if (o instanceof Blob && cls.isAssignableFrom(byte[].class)) {
      return toBytes((Blob)o);
    }
 else     if (o instanceof Clob && cls.isAssignableFrom(String.class)) {
      return toString((Clob)o);
    }
 else     if (o instanceof BigInteger && cls.isAssignableFrom(Long.class)) {
      return ((BigInteger)o).longValue();
    }
 else     if (o instanceof BigInteger && cls.isAssignableFrom(Integer.class)) {
      return ((BigInteger)o).intValue();
    }
 else     if (o instanceof BigInteger && cls.isAssignableFrom(Double.class)) {
      return ((BigInteger)o).doubleValue();
    }
 else     if (o instanceof BigInteger && cls.isAssignableFrom(Float.class)) {
      return ((BigInteger)o).floatValue();
    }
 else     if (o instanceof BigInteger && cls.isAssignableFrom(Short.class)) {
      return ((BigInteger)o).shortValue();
    }
 else     if (o instanceof BigInteger && cls.isAssignableFrom(BigDecimal.class)) {
      return new BigDecimal((BigInteger)o);
    }
 else     if (o instanceof BigDecimal && cls.isAssignableFrom(Double.class)) {
      return ((BigDecimal)o).doubleValue();
    }
 else     if (o instanceof BigDecimal && cls.isAssignableFrom(Integer.class)) {
      return ((BigDecimal)o).toBigInteger().intValue();
    }
 else     if (o instanceof BigDecimal && cls.isAssignableFrom(Float.class)) {
      return ((BigDecimal)o).floatValue();
    }
 else     if (o instanceof BigDecimal && cls.isAssignableFrom(Short.class)) {
      return ((BigDecimal)o).toBigInteger().shortValue();
    }
 else     if (o instanceof BigDecimal && cls.isAssignableFrom(Long.class)) {
      return ((BigDecimal)o).toBigInteger().longValue();
    }
 else     if (o instanceof BigDecimal && cls.isAssignableFrom(BigInteger.class)) {
      return ((BigDecimal)o).toBigInteger();
    }
 else     if ((o instanceof Short || o instanceof Integer || o instanceof Long) && cls.isAssignableFrom(BigInteger.class)) {
      return new BigInteger(o.toString());
    }
 else     if (o instanceof Number && cls.isAssignableFrom(BigDecimal.class)) {
      return new BigDecimal(o.toString());
    }
 else     if (o instanceof Number && cls.isAssignableFrom(Short.class))     return ((Number)o).shortValue();
 else     if (o instanceof Number && cls.isAssignableFrom(Integer.class))     return ((Number)o).intValue();
 else     if (o instanceof Number && cls.isAssignableFrom(Integer.class))     return ((Number)o).intValue();
 else     if (o instanceof Number && cls.isAssignableFrom(Long.class))     return ((Number)o).longValue();
 else     if (o instanceof Number && cls.isAssignableFrom(Float.class))     return ((Number)o).floatValue();
 else     if (o instanceof Number && cls.isAssignableFrom(Double.class))     return ((Number)o).doubleValue();
 else     return o;
  }
}

