private void processHistory(Code code,StockHistoryServer stockHistoryServer){
  Set<Code> _failedCodes=null;
  RealTimeStockMonitor _realTimeStockMonitor=null;
  reader.lock();
  try {
    _failedCodes=this.failedCodes;
    _realTimeStockMonitor=this.realTimeStockMonitor;
    if (this.stop_button_pressed) {
      return;
    }
  }
  finally {
    reader.unlock();
  }
  final JStock m=JStock.instance();
  List<OperatorIndicator> indicators=this.operatorIndicators.get(code);
  if (indicators == null) {
    return;
  }
  if (stockHistoryServer == null) {
    _failedCodes.add(code);
    Symbol symbol=m.getStockInfoDatabase().codeToSymbol(code);
    final String template=GUIBundle.getString("IndicatorScannerJPanel_IndicatorScannerFoundHistory_template");
    final ScannedResult scannedResult=this.getScannedResult();
    final String message=MessageFormat.format(template,symbol != null ? symbol : code,scannedResult.getTotal(),scannedResult.expected,getCompleteScannedStocksPercentage(scannedResult));
    this.updateStatusBarIfStopButtonIsNotPressed(message);
    return;
  }
  _failedCodes.remove(code);
  Symbol symbol=m.getStockInfoDatabase().codeToSymbol(code);
  final String template=GUIBundle.getString("IndicatorScannerJPanel_IndicatorScannerFoundHistory_template");
  final ScannedResult scannedResult=this.getScannedResult();
  final String message=MessageFormat.format(template,symbol != null ? symbol : code,scannedResult.getTotal(),scannedResult.expected,getCompleteScannedStocksPercentage(scannedResult));
  this.updateStatusBarIfStopButtonIsNotPressed(message);
  for (  OperatorIndicator operatorIndicator : indicators) {
    if (operatorIndicator.isStockHistoryServerNeeded()) {
      operatorIndicator.setStockHistoryServer(stockHistoryServer);
    }
    operatorIndicator.preCalculate();
  }
  _realTimeStockMonitor.addStockCode(code);
  _realTimeStockMonitor.startNewThreadsIfNecessary();
  _realTimeStockMonitor.refresh();
}

private void processInstance(BlockInstanceOf block){
  Map<BlockInstanceOf,Instance> blockToInstance=new LinkedHashMap<>();
  blockToInstance.put(block,new Instance());
  this.allBlocksToInstances.putAll(blockToInstance);
  Map<Instance,List<Instance>> instanceToChildrenInstances=new HashMap<>();
  while (!blockToInstance.isEmpty()) {
    Map.Entry<BlockInstanceOf,Instance> entry=blockToInstance.entrySet().iterator().next();
    blockToInstance.remove(entry.getKey());
    BlockInstanceOf currentBlock=entry.getKey();
    String countAsString=ModelUtils.getPropertyValue(currentBlock,ParsingConstants.PROPERTY_INSTANCE_COUNT);
    Instance instance=entry.getValue();
    instance.setName(ModelUtils.getPropertyValue(currentBlock,ParsingConstants.PROPERTY_INSTANCE_NAME));
    instance.channels.addAll(ModelUtils.getPropertyValues(currentBlock,ParsingConstants.PROPERTY_INSTANCE_CHANNELS));
    instance.setComponent(ComponentHelpers.findComponent(this.graphs,currentBlock.getName()));
    if (instance.getComponent() == null) {
      ParsingError error=new ParsingError(ErrorCode.CO_INEXISTING_COMPONENT,block.getDeclaringFile().getEditedFile(),currentBlock.getLine());
      error.setDetails(component(currentBlock.getName()));
      this.errors.add(error);
      continue;
    }
    String state=ModelUtils.getPropertyValue(currentBlock,ParsingConstants.PROPERTY_INSTANCE_STATE);
    if (state != null)     instance.setStatus(InstanceStatus.whichStatus(state));
    for (    Map.Entry<String,String> dataEntry : ModelUtils.getData(currentBlock).entrySet()) {
      instance.data.put(dataEntry.getKey(),dataEntry.getValue());
    }
    instance.data.put(INST_COUNT,countAsString);
    for (    AbstractBlock innerBlock : currentBlock.getInnerBlocks()) {
      if (innerBlock.getInstructionType() == AbstractBlock.PROPERTY) {
        String pName=((BlockProperty)innerBlock).getName();
        if (ParsingConstants.PROPERTY_INSTANCE_NAME.equals(pName) || ParsingConstants.PROPERTY_INSTANCE_CHANNELS.equals(pName) || ParsingConstants.PROPERTY_INSTANCE_DATA.equals(pName)|| ParsingConstants.PROPERTY_INSTANCE_STATE.equals(pName)|| ParsingConstants.PROPERTY_INSTANCE_COUNT.equals(pName))         continue;
        String pValue=((BlockProperty)innerBlock).getValue();
        if (pName.toLowerCase().startsWith(ParsingConstants.PROPERTY_INSTANCE_DATA_PREFIX))         instance.data.put(pName.substring(5),pValue);
 else         if (pValue.matches("\\s*\".*\"\\s*"))         instance.overriddenExports.put(pName,pValue.trim().substring(1,pValue.trim().length() - 1));
 else         instance.overriddenExports.put(pName,pValue);
        continue;
      }
      if (innerBlock.getInstructionType() != AbstractBlock.INSTANCEOF)       continue;
      List<Instance> childrenInstances=instanceToChildrenInstances.get(instance);
      if (childrenInstances == null)       childrenInstances=new ArrayList<>();
      Instance newInstance=new Instance();
      childrenInstances.add(newInstance);
      instanceToChildrenInstances.put(instance,childrenInstances);
      blockToInstance.put((BlockInstanceOf)innerBlock,newInstance);
      this.allBlocksToInstances.put((BlockInstanceOf)innerBlock,newInstance);
    }
  }
  for (  Map.Entry<Instance,List<Instance>> entry : instanceToChildrenInstances.entrySet()) {
    for (    Instance childInstance : entry.getValue())     InstanceHelpers.insertChild(entry.getKey(),childInstance);
  }
}

