        if (operatorCount == 0) {
          result=writeOperator((OperatorExprToken)token,returnValue,writeOpcode);
        }
 else         result=writeOperator((OperatorExprToken)token,true,writeOpcode);
        if (!writeOpcode && result == null) {
          invalid=true;
          break;
        }
