public SpreadsheetDate(final int day,final int month,final int year){
  if ((year >= 1900) && (year <= 9999)) {
    this.year=year;
  }
 else {
    throw new IllegalArgumentException("The 'year' argument must be in range 1900 to 9999.");
  }
  if ((month >= MonthConstants.JANUARY) && (month <= MonthConstants.DECEMBER)) {
    this.month=month;
  }
 else {
    throw new IllegalArgumentException("The 'month' argument must be in the range 1 to 12.");
  }
  if ((day >= 1) && (day <= SerialDate.lastDayOfMonth(month,year))) {
    this.day=day;
  }
 else {
    throw new IllegalArgumentException("Invalid 'day' argument.");
  }
  this.serial=calcSerial(day,month,year);
}
public SpreadsheetDate(final int serial){
  if ((serial >= SERIAL_LOWER_BOUND) && (serial <= SERIAL_UPPER_BOUND)) {
    this.serial=serial;
  }
 else {
    throw new IllegalArgumentException("SpreadsheetDate: Serial must be in range 2 to 2958465.");
  }
  final int days=this.serial - SERIAL_LOWER_BOUND;
  final int overestimatedYYYY=1900 + (days / 365);
  final int leaps=SerialDate.leapYearCount(overestimatedYYYY);
  final int nonleapdays=days - leaps;
  int underestimatedYYYY=1900 + (nonleapdays / 365);
  if (underestimatedYYYY == overestimatedYYYY) {
    this.year=underestimatedYYYY;
  }
 else {
    int ss1=calcSerial(1,1,underestimatedYYYY);
    while (ss1 <= this.serial) {
      underestimatedYYYY=underestimatedYYYY + 1;
      ss1=calcSerial(1,1,underestimatedYYYY);
    }
    this.year=underestimatedYYYY - 1;
  }
  final int ss2=calcSerial(1,1,this.year);
  int[] daysToEndOfPrecedingMonth=AGGREGATE_DAYS_TO_END_OF_PRECEDING_MONTH;
  if (isLeapYear(this.year)) {
    daysToEndOfPrecedingMonth=LEAP_YEAR_AGGREGATE_DAYS_TO_END_OF_PRECEDING_MONTH;
  }
  int mm=1;
  int sss=ss2 + daysToEndOfPrecedingMonth[mm] - 1;
  while (sss < this.serial) {
    mm=mm + 1;
    sss=ss2 + daysToEndOfPrecedingMonth[mm] - 1;
  }
  this.month=mm - 1;
  this.day=this.serial - ss2 - daysToEndOfPrecedingMonth[this.month] + 1;
}

private IExecutable analyse(CompilerContext context,int startAddress,boolean recursive,int instanceIndex) throws ClassFormatError {
  if (log.isTraceEnabled()) {
    log.trace(String.format("Compiler.analyse Block 0x%08X",startAddress));
  }
  int maxBranchInstructions=Integer.MAX_VALUE;
  MemorySections memorySections=MemorySections.getInstance();
  CodeBlock codeBlock=new CodeBlock(startAddress,instanceIndex);
  Stack<Integer> pendingBlockAddresses=new Stack<Integer>();
  pendingBlockAddresses.clear();
  pendingBlockAddresses.push(startAddress);
  Set<Integer> branchingToAddresses=new HashSet<Integer>();
  Set<Integer> pendingEndBlockAddresses=new HashSet<Integer>();
  while (!pendingBlockAddresses.isEmpty()) {
    int pc=pendingBlockAddresses.pop();
    if (!isAddressGood(pc)) {
      if (isIgnoreInvalidMemory()) {
        log.warn(String.format("IGNORING: Trying to compile an invalid address 0x%08X while compiling from 0x%08X",pc,startAddress));
      }
 else {
        log.error(String.format("Trying to compile an invalid address 0x%08X while compiling from 0x%08X",pc,startAddress));
      }
      return null;
    }
    boolean isBranchTarget=true;
    int endPc=MemoryMap.END_RAM;
    if (context.analysedAddresses.contains(pc) && !context.analysedAddresses.contains(pc + 4)) {
      pc+=4;
    }
    if (context.analysedAddresses.contains(pc) && isBranchTarget) {
      codeBlock.setIsBranchTarget(pc);
    }
 else {
      IMemoryReader memoryReader=MemoryReader.getMemoryReader(pc,4);
      while (!context.analysedAddresses.contains(pc) && pc <= endPc) {
        int opcode=memoryReader.readNext();
        Common.Instruction insn=Decoder.instruction(opcode);
        context.analysedAddresses.add(pc);
        int npc=pc + 4;
        int branchingTo=0;
        boolean isBranching=false;
        boolean checkDynamicBranching=false;
        if (insn.hasFlags(Instruction.FLAG_IS_BRANCHING)) {
          branchingTo=branchTarget(npc,opcode);
          isBranching=true;
        }
 else         if (insn.hasFlags(Instruction.FLAG_IS_JUMPING)) {
          branchingTo=jumpTarget(npc,opcode);
          isBranching=true;
          checkDynamicBranching=true;
        }
        if (isEndBlockInsn(pc,opcode,insn)) {
          endPc=npc;
        }
 else         if (pc == startAddress && insn.hasFlags(Instruction.FLAG_SYSCALL)) {
          endPc=pc;
        }
        if (insn.hasFlags(Instruction.FLAG_STARTS_NEW_BLOCK)) {
          if (recursive) {
            context.blocksToBeAnalysed.push(branchingTo);
          }
          if (endPc != pc && (branchingTo & Memory.addressMask) != 0 && Emulator.getMemory(branchingTo).read32(branchingTo) == opcodeBreak0) {
            endPc=npc;
            int pendingEndBlockAddress=npc + 4;
            pendingEndBlockAddresses.add(pendingEndBlockAddress);
          }
        }
 else         if (isBranching) {
          if ((branchingTo & Memory.addressMask) != 0) {
            boolean analyseBranch=true;
            if (maxBranchInstructions < 0) {
              analyseBranch=false;
            }
 else {
              maxBranchInstructions--;
              if (checkDynamicBranching && memorySections.canWrite(branchingTo,false)) {
                analyseBranch=false;
              }
            }
            if (analyseBranch) {
              pendingBlockAddresses.push(branchingTo);
            }
 else {
              branchingToAddresses.add(branchingTo);
            }
          }
        }
        boolean useMMIO=isUsingMMIO(pc);
        codeBlock.addInstruction(pc,opcode,insn,isBranchTarget,isBranching,branchingTo,useMMIO);
        pc=npc;
        isBranchTarget=false;
      }
    }
    for (    int branchingTo : branchingToAddresses) {
      codeBlock.setIsBranchTarget(branchingTo);
    }
  }
  if (!pendingEndBlockAddresses.isEmpty()) {
    for (    int pendingEndBlockAddress : pendingEndBlockAddresses) {
      if (codeBlock.getCodeInstruction(pendingEndBlockAddress) == null) {
        codeBlock.addEndBlockInstruction(pendingEndBlockAddress);
      }
    }
  }
  codeBlock.addCodeBlock();
  IExecutable executable;
  if (RuntimeContext.isCompilerEnabled() || codeBlock.hasFlags(FLAG_SYSCALL)) {
    executable=codeBlock.getExecutable(context);
  }
 else {
    executable=null;
  }
  if (log.isTraceEnabled()) {
    log.trace("Executable: " + executable);
  }
  return executable;
}

/** 
 * Parses a single ANVLRecord from passed InputStream. Read as a single-byte stream until we get to a CRLFCRLF which signifies End-of-ANVLRecord. Then parse all read as a UTF-8 Stream. Doing it this way, while requiring a double-scan, it  makes it so do not need to be passed a RepositionableStream or a Stream that supports marking.  Also no danger of over-reading which can happen when we wrap passed Stream with an InputStreamReader for doing UTF-8 character conversion (See the ISR class comment).
 * @param is InputStream
 * @return An ANVLRecord instance.
 * @throws IOException
 */
public static ANVLRecord load(final InputStream is) throws IOException {
  boolean isCRLF=false;
  boolean recordStart=false;
  ByteArrayOutputStream baos=new ByteArrayOutputStream(1024);
  boolean done=false;
  int read=0;
  for (int c=-1, previousCharacter; !done; ) {
    if (read++ >= MAXIMUM_SIZE) {
      throw new IOException("Read " + MAXIMUM_SIZE + " bytes without finding  \\r\\n\\r\\n "+ "End-Of-ANVLRecord");
    }
    previousCharacter=c;
    c=is.read();
    if (c == -1) {
      throw new IOException("End-Of-Stream before \\r\\n\\r\\n " + "End-Of-ANVLRecord:\n" + new String(baos.toByteArray(),UTF8));
    }
    if (isLF((char)c) && isCR((char)previousCharacter)) {
      if (isCRLF) {
        done=true;
      }
 else {
        isCRLF=true;
      }
    }
 else     if (!recordStart && Character.isWhitespace(c)) {
      continue;
    }
 else {
      if (isCRLF && !isCR((char)c)) {
        isCRLF=false;
      }
      if (!recordStart) {
        recordStart=true;
      }
    }
    baos.write(c);
  }
  return load(new String(baos.toByteArray(),UTF8));
}
/** 
 * Parse passed String for an ANVL Record. Looked at writing javacc grammer but preprocessing is required to handle folding: See https://javacc.dev.java.net/servlets/BrowseList?list=users&by=thread&from=56173. Looked at Terence Parr's ANTLR.  More capable.  Can set lookahead count. A value of 3 would help with folding.  But its a pain defining UNICODE grammers -- needed by ANVL -- and support seems incomplete anyways: http://www.doc.ic.ac.uk/lab/secondyear/Antlr/lexer.html#unicode. For now, go with the below hand-rolled parser.
 * @param s String with an ANVLRecord.
 * @return ANVLRecord parsed from passed String.
 * @throws IOException 
 */
public static ANVLRecord load(final String s) throws IOException {
  ANVLRecord record=new ANVLRecord();
  boolean inValue=false, inLabel=false, inComment=false, inNewLine=false;
  String label=null;
  StringBuilder sb=new StringBuilder(s.length());
  for (int i=0; i < s.length(); i++) {
    char c=s.charAt(i);
    if ((i + 1) > s.length()) {
      throw new IOException("Premature End-of-ANVLRecord:\n" + s.substring(i));
    }
    if (inNewLine && isLF(c)) {
      continue;
    }
    if (inNewLine && isCR(c) && isLF(s.charAt(i + 1))) {
      break;
    }
    if (inNewLine && inValue && Character.isWhitespace(c)) {
      continue;
    }
    inNewLine=isCR(c) && isLF(s.charAt(i + 1));
    if (inNewLine) {
      if (inComment) {
        inComment=false;
      }
 else       if (label != null && !inValue) {
        record.addLabel(label);
        label=null;
        sb.setLength(0);
      }
 else       if (inValue) {
        if ((i + 3) > s.length()) {
          throw new IOException("Premature End-of-ANVLRecord " + "(2):\n" + s.substring(i));
        }
        if (!isCR(s.charAt(i + 2)) && !isLF(s.charAt(i + 3)) && Character.isWhitespace(s.charAt(i + 2))) {
          sb.append(CRLF);
          sb.append(' ');
        }
 else {
          record.addLabelValue(label,sb.toString());
          sb.setLength(0);
          label=null;
          inValue=false;
        }
      }
 else {
      }
      continue;
    }
    if (inComment) {
      continue;
    }
 else     if (inLabel) {
      if (c == Label.COLON) {
        label=sb.toString();
        sb.setLength(0);
        inLabel=false;
        continue;
      }
    }
 else {
      if (!inLabel && !inValue && !inComment) {
        if (Character.isWhitespace(c)) {
          continue;
        }
 else         if (label == null && c == '#') {
          inComment=true;
          continue;
        }
 else         if (label == null) {
          inLabel=true;
        }
 else {
          inValue=true;
        }
      }
    }
    sb.append(c);
  }
  return record;
}

