float correctTo01(float a){
  float min=(float)0.0;
  float max=(float)1.0;
  float min_epsilon=min - EPSILON;
  float max_epsilon=max + EPSILON;
  if ((a <= min && a >= min_epsilon) || (a >= min && a <= min_epsilon)) {
    return min;
  }
 else   if ((a >= max && a <= max_epsilon) || (a <= max && a >= max_epsilon)) {
    return max;
  }
 else {
    return a;
  }
}

