@Override protected void reconnect(){
  RetryTimer retryTimer=new RetryTimer();
  boolean connected=false;
  while (!connected) {
    try {
      long interval=retryTimer.getNextInterval();
      log.info(String.format("Topic subscriber will try to reconnect in %d seconds: [topic-name] %s",(interval / 1000),topicName));
      Thread.sleep(interval);
    }
 catch (    InterruptedException ignore) {
    }
    try {
      disconnect();
      create();
      connect();
      subscribe();
      connected=true;
      log.info(String.format("Topic subscriber reconnected: [topic-name] %s",topicName));
    }
 catch (    Exception e) {
      String message="Could not reconnect to message broker";
      log.warn(message,e);
    }
  }
}

