/** 
 * Adds an initial request listener to this  {@link Checkout} if the initial request hasn'tfinished yet or calls appropriate methods of the passed listener if some/all data has already been loaded. Depending on the current state of  {@link Checkout} some methods of the passed listener mightbe called synchronously while other - asynchronously.
 * @param listener listener which is notified about the initial request's results
 */
public void whenReady(@Nonnull final Listener listener){
  Check.isMainThread();
synchronized (mLock) {
    Check.isNotNull(mRequests);
    final Billing.Requests requests=mRequests;
    @Nonnull final Set<String> loadingProducts=new HashSet<>(ProductTypes.ALL);
    for (    final String product : ProductTypes.ALL) {
      requests.isBillingSupported(product,new RequestListener<Object>(){
        private void onBillingSupported(        boolean supported){
          listener.onReady(requests,product,supported);
          loadingProducts.remove(product);
          if (loadingProducts.isEmpty()) {
            listener.onReady(requests);
          }
        }
        @Override public void onSuccess(        @Nonnull Object result){
          onBillingSupported(true);
        }
        @Override public void onError(        int response,        @Nonnull Exception e){
          onBillingSupported(false);
        }
      }
);
    }
  }
