private void addAtomElement(final InputStream content,final XMLEventWriter writer) throws Exception {
  final XMLEventReader reader=getEventReader(content);
  final XMLEventFactory eventFactory=XMLEventFactory.newInstance();
  XMLEvent newLine=eventFactory.createSpace("\n");
  try {
    writer.add(newLine);
    while (reader.hasNext()) {
      final XMLEvent event=reader.nextEvent();
      if (event.getEventType() != XMLStreamConstants.START_DOCUMENT && event.getEventType() != XMLStreamConstants.END_DOCUMENT && event.getEventType() != XMLStreamConstants.COMMENT) {
        writer.add(event);
      }
    }
    writer.add(newLine);
  }
  finally {
    reader.close();
    IOUtils.closeQuietly(content);
  }
}

