/** 
 * Similar to  {@link #write(byte[])} but allows a portion of the alreadywritten buffer to be re-written. <p> Equivalent to <code>writeAt(position, buffer, 0, buffer.length);</code>. </p>
 * @param position The position to write at. This location should have already been written.
 * @param buffer the data.
 */
public void writeAt(final long position,final byte buffer[]){
  writeAt(position,buffer,0,buffer.length);
}
/** 
 * Similar to  {@link #write(byte[],int,int)} but allows a portion of thealready written buffer to be re-written.
 * @param position The position to write at. This location should have already been written.
 * @param buffer the data.
 * @param offset the start offset in the data.
 * @param length the number of bytes to write.
 */
public void writeAt(final long position,final byte buffer[],final int offset,final int length){
  if (buffer == null) {
    throw new NullPointerException();
  }
 else   if ((offset < 0) || (offset > buffer.length) || (length < 0)|| ((offset + length) > buffer.length)|| ((offset + length) < 0)|| ((position + length) > getSize())) {
    throw new IndexOutOfBoundsException();
  }
 else   if (length == 0) {
    return;
  }
  final long start=position & BUFFER_SIZE_MASK;
  int bufferIndex=(int)(position >> BUFFER_SIZE_SHIFT);
  byte[] internalBuffer=myBuffers.get(bufferIndex);
  int wrote=0;
  int internalOffset=(int)start;
  while (wrote < length) {
    if (internalBuffer.length <= internalOffset) {
      bufferIndex+=1;
      internalBuffer=myBuffers.get(bufferIndex);
      internalOffset=0;
    }
    final int available=internalBuffer.length - internalOffset;
    final int toWrite=Math.min(length - wrote,available);
    System.arraycopy(buffer,offset + wrote,internalBuffer,internalOffset,toWrite);
    internalOffset+=toWrite;
    wrote+=toWrite;
  }
}
/** 
 * Similar to  {@link #write(int)} but allows a portion of the alreadywritten buffer to be re-written.
 * @param position The position to write at. This location should have already been written.
 * @param b The byte value to write.
 */
public void writeAt(final long position,final int b){
  final long start=position & BUFFER_SIZE_MASK;
  final int bufferIndex=(int)(position >> BUFFER_SIZE_SHIFT);
  final byte[] internalBuffer=myBuffers.get(bufferIndex);
  internalBuffer[(int)start]=(byte)b;
}

