public void recoverKeyValue(){
  key=new ArrayList<String>();
  List<Integer> val1=new ArrayList<Integer>();
  HashMap<Integer,List<Integer>> childIdxMap=new HashMap<Integer,List<Integer>>();
  for (int i=0; i < check.length; i++) {
    if (check[i] <= 0)     continue;
    if (!childIdxMap.containsKey(check[i])) {
      List<Integer> childList=new ArrayList<Integer>();
      childIdxMap.put(check[i],childList);
    }
    childIdxMap.get(check[i]).add(i);
  }
  Stack<Integer[]> s=new Stack<Integer[]>();
  s.add(new Integer[]{1,-1});
  List<Integer> charBuf=new ArrayList<Integer>();
  while (true) {
    Integer[] pair=s.peek();
    List<Integer> childList=childIdxMap.get(pair[0]);
    if (childList == null || (childList.size() - 1) == pair[1]) {
      s.pop();
      if (s.empty()) {
        break;
      }
 else {
        if (!charBuf.isEmpty()) {
          charBuf.remove(charBuf.size() - 1);
        }
        continue;
      }
    }
 else {
      pair[1]++;
    }
    int c=(int)childList.get(pair[1]);
    int code=(c - 1 - pair[0]);
    if (base[c] > 0) {
      s.add(new Integer[]{base[c],-1});
      charBuf.add(code);
      continue;
    }
 else     if (base[c] < 0) {
      if (check[c] == c) {
        char[] chars=new char[charBuf.size()];
        for (int i=0; i < charBuf.size(); i++) {
          chars[i]=(char)(int)charBuf.get(i);
        }
        key.add(new String(chars));
        val1.add(-base[c] - 1);
      }
      continue;
    }
  }
  if (!val1.isEmpty()) {
    value=new int[val1.size()];
    for (int i=0; i < val1.size(); i++) {
      value[i]=val1.get(i);
    }
  }
}

/** 
 * Partially rewrites a declaration as an assignment. <p>In the post traversal, all global, cross-module names and extern name references will become property accesses. They will then be invalid as the lhs of a declaration, so we need to convert them to assignments. We also convert any other names or destructuring patterns in the same declaration to assignments and add an earlier declaration.
 */
private void rewriteNameDeclaration(NodeTraversal t,Node declaration,List<Node> allLhsNodes,boolean isGlobalDeclaration){
  CompilerInput input=t.getInput();
  for (  Node lhs : allLhsNodes) {
    String name=lhs.getString();
    if (!(isGlobalDeclaration && isCrossModuleName(name)) && !isExternVar(name,t)) {
      preDeclarations.add(new ModuleGlobal(input.getAstRoot(compiler),IR.name(name).srcref(lhs)));
    }
  }
  for (  Node child : declaration.children()) {
    if (child.isName() && child.hasChildren()) {
      Node assign=IR.assign(child.cloneNode(),child.removeFirstChild());
      child.replaceWith(assign);
      assign.setJSDocInfo(declaration.getJSDocInfo());
    }
 else     if (child.isDestructuringLhs()) {
      if (child.hasOneChild()) {
        checkState(NodeUtil.isEnhancedFor(declaration.getParent()),"DESTRUCTURING_LHS should have two children: %s",declaration.toStringTree());
        child.replaceWith(child.removeFirstChild());
      }
 else {
        Node assign=IR.assign(child.removeFirstChild(),child.removeFirstChild());
        child.replaceWith(assign);
        assign.setJSDocInfo(declaration.getJSDocInfo());
      }
    }
  }
  compiler.reportChangeToEnclosingScope(declaration);
}

private static void prunePatterns() throws IOException {
  int length=5;
  int matches=0;
  Node domain, source, target;
  String lodDSName="ds29";
  boolean chain=false;
  boolean timespan=false;
  boolean duplicate=false;
  boolean removeUris=false;
  boolean twoAggregatedCHOs=true;
  File f=new File(Params.SOURCE_DIR);
  File[] files=f.listFiles();
  String sourcename, filename;
  List<String> removeUriList=new LinkedList<String>();
  removeUriList.add("http://purl.org/ontology/mo/Playlist");
  removeUriList.add("http://www.w3.org/TR/owl-time/Interval");
  for (int i=0; i < files.length; i++) {
    if (lodDSName.equals("ds29")) {
      File file=files[i];
      filename=file.getName();
      System.out.println("processing " + filename + " ...");
      sourcename=filename.substring(0,filename.lastIndexOf("."));
    }
 else {
      System.out.println("processing " + lodDSName + " ...");
      sourcename=lodDSName;
      i=files.length;
    }
    matches=0;
    for (int j=1; j <= length; j++) {
      System.out.println("reading patterns with length " + j);
      File f1=new File(Params.LOD_DIR + sourcename + "/"+ Params.PATTERNS_OUTPUT_DIR+ "/"+ j);
      File[] patternFiles=f1.listFiles();
      if (files != null)       for (      File f2 : patternFiles) {
        Pattern p=Pattern.readJson(f2.getAbsolutePath());
        if (chain) {
          for (          Node n : p.getGraph().vertexSet()) {
            if (p.getGraph().outDegreeOf(n) > 1) {
              matches++;
              break;
            }
          }
        }
        if (twoAggregatedCHOs) {
          boolean existAggregatedCHO=false;
          for (          LabeledLink l : p.getGraph().edgeSet()) {
            source=l.getSource();
            target=l.getTarget();
            if (!existAggregatedCHO && target.getUri().equalsIgnoreCase("http://www.americanartcollaborative.org/ontology/CulturalHeritageObject") && l.getUri().equalsIgnoreCase("http://www.europeana.eu/schemas/edm/aggregatedCHO")) {
              existAggregatedCHO=true;
            }
 else             if (target.getUri().equalsIgnoreCase("http://www.americanartcollaborative.org/ontology/CulturalHeritageObject") && l.getUri().equalsIgnoreCase("http://www.europeana.eu/schemas/edm/aggregatedCHO")) {
              matches++;
              if (!f2.delete())               System.out.println("error in deleting the file " + f2.getAbsolutePath());
            }
          }
        }
        if (timespan) {
          domain=null;
          for (          LabeledLink l : p.getGraph().edgeSet()) {
            source=l.getSource();
            target=l.getTarget();
            if (target.getUri().equalsIgnoreCase("http://erlangen-crm.org/current/E52_Time-Span")) {
              if (domain == null) {
                domain=source;
              }
 else               if (source.equals(domain)) {
                matches++;
              }
            }
          }
        }
        if (removeUris) {
          for (          Node n : p.getGraph().vertexSet()) {
            for (            String uri : removeUriList) {
              if (n.getUri().equalsIgnoreCase(uri)) {
                matches++;
                if (!f2.delete())                 System.out.println("error in deleting the file " + f2.getAbsolutePath());
                break;
              }
            }
          }
        }
        boolean visited=false;
        if (duplicate) {
          for (          Node n : p.getGraph().vertexSet()) {
            if (!visited && n.getUri().equals("http://erlangen-crm.org/current/E12_Production")) {
              visited=true;
            }
 else             if (n.getUri().equals("http://erlangen-crm.org/current/E12_Production")) {
