/** 
 * Updates all trust trees which are affected by the given modified score. For understanding how score calculation works you should first read  {@link #computeAllScoresWithoutCommit()}This function does neither lock the database nor commit the transaction. You have to surround it with synchronized(this) { synchronized(mFetcher) { synchronized(mSubscriptionManager) { synchronized(Persistent.transactionLock(mDB)) { try { ... updateScoreWithoutCommit(...); Persistent.checkedCommit(mDB, this); } catch(RuntimeException e) { Persistent.checkedRollbackAndThrow(mDB, this, e);; } }}}}
 */
private void updateScoresWithoutCommit(final Trust oldTrust,final Trust newTrust){
  if (logMINOR)   Logger.minor(this,"Doing an incremental computation of all Scores...");
  if (mFullScoreComputationNeeded) {
    if (logMINOR)     Logger.minor(this,"Full score computation scheduled, not doing incremental one!");
    if (!mTrustListImportInProgress) {
      computeAllScoresWithoutCommit();
      assert (computeAllScoresWithoutCommit());
    }
    return;
  }
  StopWatch time=new StopWatch();
  final boolean trustWasCreated=(oldTrust == null);
  final boolean trustWasDeleted=(newTrust == null);
  final boolean trustWasModified=!trustWasCreated && !trustWasDeleted;
  if (trustWasCreated && trustWasDeleted)   throw new NullPointerException("No old/new trust specified.");
  if (trustWasModified && !oldTrust.getTruster().getID().equals(newTrust.getTruster().getID()))   throw new IllegalArgumentException("oldTrust has different truster, oldTrust:" + oldTrust + "; newTrust: "+ newTrust);
  if (trustWasModified && !oldTrust.getTrustee().getID().equals(newTrust.getTrustee().getID()))   throw new IllegalArgumentException("oldTrust has different trustee, oldTrust:" + oldTrust + "; newTrust: "+ newTrust);
  if (trustWasDeleted) {
    mFullScoreComputationNeeded=true;
  }
  if (!mFullScoreComputationNeeded && (trustWasCreated || trustWasModified)) {
    for (    OwnIdentity treeOwner : getAllOwnIdentities()) {
      try {
        if (getScore(treeOwner,newTrust.getTruster()).getCapacity() == 0)         continue;
      }
 catch (      NotInTrustTreeException e) {
        continue;
      }
      if (trustWasModified && oldTrust.getValue() > 0 && newTrust.getValue() <= 0) {
        mFullScoreComputationNeeded=true;
        break;
      }
      final LinkedList<Trust> unprocessedEdges=new LinkedList<Trust>();
      unprocessedEdges.add(newTrust);
      while (!unprocessedEdges.isEmpty()) {
        final Trust trust=unprocessedEdges.removeFirst();
        final Identity trustee=trust.getTrustee();
        if (trustee == treeOwner)         continue;
        Score currentStoredTrusteeScore;
        boolean scoreExistedBefore;
        try {
          currentStoredTrusteeScore=getScore(treeOwner,trustee);
          scoreExistedBefore=true;
        }
 catch (        NotInTrustTreeException e) {
          scoreExistedBefore=false;
          currentStoredTrusteeScore=new Score(this,treeOwner,trustee,0,-1,0);
        }
        final Score oldScore=currentStoredTrusteeScore.clone();
        boolean oldShouldFetch=shouldFetchIdentity(trustee);
        final int newScoreValue=computeScoreValue(treeOwner,trustee);
        final int newRank=computeRank(treeOwner,trustee);
        final int newCapacity=computeCapacity(treeOwner,trustee,newRank);
        final Score newScore=new Score(this,treeOwner,trustee,newScoreValue,newRank,newCapacity);
        if ((oldScore.getRank() >= 0 && oldScore.getRank() < Integer.MAX_VALUE) && (newScore.getRank() == -1 || newScore.getRank() == Integer.MAX_VALUE)) {
          mFullScoreComputationNeeded=true;
          break;
        }
        if (oldScore.getCapacity() > 0 && newScore.getCapacity() == 0) {
          mFullScoreComputationNeeded=true;
          break;
        }
        currentStoredTrusteeScore.setValue(newScore.getScore());
        currentStoredTrusteeScore.setRank(newScore.getRank());
        currentStoredTrusteeScore.setCapacity(newScore.getCapacity());
        assert (currentStoredTrusteeScore.getRank() >= 0);
        if (currentStoredTrusteeScore.getRank() >= 0) {
          currentStoredTrusteeScore.storeWithoutCommit();
          if (!scoreExistedBefore || !oldScore.equals(currentStoredTrusteeScore))           mSubscriptionManager.storeScoreChangedNotificationWithoutCommit(scoreExistedBefore ? oldScore : null,currentStoredTrusteeScore);
        }
        if ((!oldShouldFetch || (oldScore.getCapacity() == 0 && newScore.getCapacity() > 0)) && shouldFetchIdentity(trustee)) {
          if (logMINOR) {
            if (!oldShouldFetch)             Logger.minor(this,"Fetch status changed from false to true, refetching " + trustee);
 else             Logger.minor(this,"Capacity changed from 0 to " + newScore.getCapacity() + ", refetching"+ trustee);
          }
          final Identity oldTrustee=trustee.clone();
          trustee.markForRefetch();
          trustee.storeWithoutCommit();
          if (!oldTrustee.equals(trustee))           mSubscriptionManager.storeIdentityChangedNotificationWithoutCommit(oldTrustee,trustee);
          mFetcher.storeStartFetchCommandWithoutCommit(trustee);
        }
 else         if (oldShouldFetch && !shouldFetchIdentity(trustee)) {
          if (logMINOR)           Logger.minor(this,"Fetch status changed from true to false, aborting fetch of " + trustee);
          mFetcher.storeAbortFetchCommandWithoutCommit(trustee);
        }
        if (oldScore.getRank() != newScore.getRank() || oldScore.getCapacity() != newScore.getCapacity()) {
          if (newScore.getCapacity() > 0 || (newScore.getRank() >= 0 && newScore.getRank() < Integer.MAX_VALUE)) {
            for (            Trust givenTrust : getGivenTrusts(trustee)) {
              unprocessedEdges.add(givenTrust);
            }
          }
        }
      }
      if (mFullScoreComputationNeeded)       break;
    }
  }
  if (!mFullScoreComputationNeeded) {
    ++mIncrementalScoreRecomputationDueToTrustCount;
    mIncrementalScoreRecomputationDueToTrustNanos+=time.getNanos();
  }
 else {
    time=new StopWatch();
    Identity distrusted;
    if (newTrust != null) {
      distrusted=newTrust.getTrustee();
    }
 else {
      try {
        distrusted=getIdentityByID(oldTrust.getTrustee().getID());
      }
 catch (      UnknownIdentityException e) {
        throw new RuntimeException(e);
      }
    }
    updateScoresAfterDistrustWithoutCommit(distrusted);
    time.stop();
    mFullScoreComputationNeeded=false;
    ++mIncrementalScoreRecomputationDueToDistrustCount;
    mIncrementalScoreRecomputationDueToDistrustNanos+=time.getNanos();
    if (time.getNanos() > TimeUnit.SECONDS.toNanos(10)) {
      ++mIncrementalScoreRecomputationDueToDistrustCountSlow;
      mIncrementalScoreRecomputationDueToDistrustNanosSlow+=time.getNanos();
    }
  }
  if (logMINOR) {
    if (!mFullScoreComputationNeeded)     Logger.minor(this,"Incremental computation of all Scores finished.");
 else     Logger.minor(this,"Incremental computation of all Scores not possible, full computation is needed.");
  }
  if (!mTrustListImportInProgress) {
    if (mFullScoreComputationNeeded) {
      computeAllScoresWithoutCommit();
      assert (computeAllScoresWithoutCommit());
    }
 else {
      assert (computeAllScoresWithoutCommit());
    }
  }
 else {
  }
}

/** 
 * Parse a From header and extract the first address.  (This does not fully parse the header, so it will accept strings that are not actually valid mailing addresses.)
 */
public static Mailbox parseHeader(String hdr){
  HeaderTokenizer tokenizer=new HeaderTokenizer(hdr);
  String name=null, local=null, domain=null;
  StringBuilder current=new StringBuilder();
  boolean inDomain=false, inAngles=false;
  while (tokenizer.tokensRemaining()) {
    int c=tokenizer.getToken();
    if (c == '@') {
      if (inDomain)       return null;
      local=current.toString();
      inDomain=true;
      current.setLength(0);
    }
 else     if (c == '.') {
      current.append('.');
    }
 else     if (c == 0) {
      String word=tokenizer.getTokenText();
      current.append(word);
    }
 else     if (c == '<') {
      if (inAngles || inDomain)       return null;
      name=current.toString();
      inAngles=true;
      current=new StringBuilder();
    }
 else     if (inDomain && c == '>') {
      inAngles=false;
      break;
    }
 else     if (inDomain && (c == ',' || c == ';')) {
      break;
    }
 else {
      name=local=domain=null;
      inDomain=inAngles=false;
      current=new StringBuilder();
    }
  }
  if (inDomain && !inAngles) {
    domain=current.toString();
    return new Mailbox(name,local,domain);
  }
 else   return null;
}

