@Override public SortedSet<DegreeCurricularPlan> getPossibleScope(){
  SortedSet<DegreeCurricularPlan> possible=new TreeSet<DegreeCurricularPlan>(DegreeCurricularPlan.COMPARATOR_BY_PRESENTATION_NAME);
  if (degreeType != null && type != null && semester != null) {
    if (degreeType.isEmpty() && EmptyDegreeCurricularPlan.getInstance() != null) {
      addIfNotUsedInPeriod(possible,EmptyDegreeCurricularPlan.getInstance());
    }
 else     if (degreeType.isBolonhaType()) {
      for (      ExecutionDegree execution : semester.getExecutionYear().getExecutionDegreesByType(degreeType)) {
        DegreeCurricularPlan dcp=execution.getDegreeCurricularPlan();
        addIfNotUsedInPeriod(possible,dcp);
      }
      if (EnrolmentPeriodType.ENROLMENT_PERIOD_IN_IMPROVEMENT_OF_APPROVED_ENROLMENT.equals(type) && semester.getPreviousExecutionPeriod().getExecutionYear() != semester.getExecutionYear()) {
        for (        ExecutionDegree execution : semester.getPreviousExecutionPeriod().getExecutionYear().getExecutionDegreesByType(degreeType)) {
          DegreeCurricularPlan dcp=execution.getDegreeCurricularPlan();
          if (!possible.contains(dcp)) {
            addIfNotUsedInPeriod(possible,dcp);
          }
        }
      }
      if (EnrolmentPeriodType.REINGRESSION.equals(type)) {
        Bennu.getInstance().getDegreeCurricularPlansSet().stream().filter(dcp -> dcp.getDegreeType().equals(degreeType)).filter(dcp -> !possible.contains(dcp)).forEach(dcp -> addIfNotUsedInPeriod(possible,dcp));
      }
    }
 else {
      for (      DegreeCurricularPlan dcp : DegreeCurricularPlan.readPreBolonhaDegreeCurricularPlans()) {
        addIfNotUsedInPeriod(possible,dcp);
      }
    }
  }
  return possible;
}
