 else {
      PictogramElement finishPE=YangModelUIUtil.getBusinessObjectShape(fp,ref);
      if (null != finishPE) {
        Anchor finish=YangModelUIUtil.getChopboxAnchor((AnchorContainer)finishPE);
        if (null != con && con.getEnd().equals(finish)) {
