/** 
 * Splits a text-number combination such as "hello 10.0" into <code>{"hello", "10.0"}</code>.
 * @param s The string to split. Not <code>null</code>. Needs be be reasonably formatted since the method only finds the first 0-9 or . and cuts the string in half there.
 * @return Always length 2 and no <code>null</code> elements. Elements are"" if no part found.
 */
private static String[] getNumTextParts(String s){
  for (int i=0, iSz=s.length(); i < iSz; i++) {
    char c=s.charAt(i);
    if (c == ' ')     throw new IllegalArgumentException("Space in UnitValue: '" + s + "'");
    if ((c < '0' || c > '9') && c != '.' && c != '-')     return new String[]{s.substring(0,i).trim(),s.substring(i).trim()};
  }
  return new String[]{s,""};
}

