public int sample(float x,float y){
  int srcX=(int)Math.floor(x);
  int srcY=(int)Math.floor(y);
  float xWeight=x - srcX;
  float yWeight=y - srcY;
  int nw, ne, sw, se;
  if (srcX >= 0 && srcX < width - 1 && srcY >= 0 && srcY < height - 1) {
    int i=width * srcY + srcX;
    nw=inPixels[i];
    ne=inPixels[i + 1];
    sw=inPixels[i + width];
    se=inPixels[i + width + 1];
  }
 else {
    nw=getPixel(inPixels,srcX,srcY,width,height);
    ne=getPixel(inPixels,srcX + 1,srcY,width,height);
    sw=getPixel(inPixels,srcX,srcY + 1,width,height);
    se=getPixel(inPixels,srcX + 1,srcY + 1,width,height);
  }
  return ImageMath.bilinearInterpolate(xWeight,yWeight,nw,ne,sw,se);
}

public List<DbPriv> getAuthOnDbsByDistributeTransaction(String who) throws MetaException {
  boolean success=false;
  List<DbPriv> dbPrivs=new ArrayList<DbPriv>();
  Set<String> slaveURLSet=getAllSegments();
  int size=slaveURLSet.size();
  who=who.toLowerCase();
  PGXADataSource[] slaveDSArray=new PGXADataSource[size];
  XAConnection[] slaveDSXaConnArray=new XAConnection[size];
  XAResource[] slaveSaResArray=new XAResource[size];
  Connection[] slaveConArray=new Connection[size];
  Statement[] slaveStmtArray=new Statement[size];
  Xid[] slaveXidArray=new Xid[size];
  int index=0;
  for (  String slaveURL : slaveURLSet) {
    slaveDSArray[index]=getXADataSource(slaveURL,user,passwd);
    index++;
  }
  int formatID=genFormatID();
  try {
    for (int i=0; i < size; i++) {
      slaveDSXaConnArray[i]=slaveDSArray[i].getXAConnection();
      slaveSaResArray[i]=slaveDSXaConnArray[i].getXAResource();
      slaveConArray[i]=slaveDSXaConnArray[i].getConnection();
      slaveStmtArray[i]=slaveConArray[i].createStatement();
      byte id1=(byte)((i + 2) * 2);
      byte id2=(byte)(id1 + 1);
      slaveXidArray[i]=new MyXid(formatID,new byte[]{id1},new byte[]{id2});
    }
    try {
      for (int i=0; i < size; i++) {
        slaveSaResArray[i].start(slaveXidArray[i],XAResource.TMNOFLAGS);
        ResultSet dbPrivSet=slaveStmtArray[i].executeQuery("select alter_priv, create_priv, createview_priv, " + "delete_priv, drop_priv, index_priv, insert_priv, select_priv, " + "showview_priv, update_priv, db_name from dbpriv where user_name='" + who.toLowerCase() + "'");
        while (dbPrivSet.next()) {
          DbPriv dbPriv=new DbPriv();
          dbPriv.setAlterPriv(dbPrivSet.getBoolean(1));
          dbPriv.setCreatePriv(dbPrivSet.getBoolean(2));
          dbPriv.setCreateviewPriv(dbPrivSet.getBoolean(3));
          dbPriv.setDeletePriv(dbPrivSet.getBoolean(4));
          dbPriv.setDropPriv(dbPrivSet.getBoolean(5));
          dbPriv.setIndexPriv(dbPrivSet.getBoolean(6));
          dbPriv.setInsertPriv(dbPrivSet.getBoolean(7));
          dbPriv.setSelectPriv(dbPrivSet.getBoolean(8));
          dbPriv.setShowviewPriv(dbPrivSet.getBoolean(9));
          dbPriv.setUpdatePriv(dbPrivSet.getBoolean(10));
          dbPriv.setDb(dbPrivSet.getString(11));
          dbPriv.setUser(who);
          dbPrivs.add(dbPriv);
        }
        slaveSaResArray[i].end(slaveXidArray[i],XAResource.TMSUCCESS);
      }
      boolean isAllPred=true;
      int[] slaveRetArray=new int[size];
      for (int i=0; i < size; i++) {
        slaveRetArray[i]=slaveSaResArray[i].prepare(slaveXidArray[i]);
        if (slaveRetArray[i] == XAResource.XA_OK) {
          continue;
        }
 else {
          isAllPred=false;
          break;
        }
      }
      if (isAllPred) {
        for (int i=0; i < size; i++) {
          slaveSaResArray[i].commit(slaveXidArray[i],false);
        }
        success=true;
      }
    }
 catch (    XAException e) {
      LOG.error("get user auth on dbs error, user=" + who + ", msg="+ e.getMessage());
      throw new MetaException(e.getMessage());
    }
  }
 catch (  SQLException e) {
    LOG.error("get user auth on dbs error, user=" + who + ", msg="+ e.getMessage());
    throw new MetaException(e.getMessage());
  }
 finally {
    for (int i=0; i < size; i++) {
      closeConnection(slaveConArray[i]);
      closeXAConnection(slaveDSXaConnArray[i]);
    }
  }
  if (success) {
    return dbPrivs;
  }
 else {
    return null;
  }
}

public Text evaluate(Text s,IntWritable n,Text pad){
  if (s == null || n == null || pad == null) {
    return null;
  }
  int len=n.get();
  byte[] data=result.getBytes();
  if (data.length < len) {
    data=new byte[len];
  }
  byte[] txt=s.getBytes();
  byte[] padTxt=pad.getBytes();
  int pos;
  for (pos=0; pos < s.getLength() && pos < len; pos++) {
    data[pos]=txt[pos];
  }
  while (pos < len) {
    for (int i=0; i < pad.getLength() && i < len - pos; i++) {
      data[pos + i]=padTxt[i];
    }
    pos+=pad.getLength();
  }
  result.set(data,0,len);
  return result;
}

public static TestSuite buildDetail(Class<? extends TestCase> clazz,Iterable<?> params,Filter filter,boolean includeSuperClassMethods){
  TestSuite suite=new TestSuite();
  List<String> testMethods=new ArrayList<String>();
  Method[] methods=(includeSuperClassMethods) ? clazz.getMethods() : clazz.getDeclaredMethods();
  for (  Method method : methods) {
    Class<?>[] paramType=method.getParameterTypes();
    Class<?> returnType=method.getReturnType();
    String name=method.getName();
    int modifiers=method.getModifiers();
    if (Modifier.isPublic(modifiers) && !Modifier.isStatic(modifiers) && (paramType.length == 0)&& name.startsWith("test")&& returnType.equals(void.class)) {
      if (filter == null || filter.filter(method)) {
        testMethods.add(method.getName());
      }
    }
  }
  Constructor<?> parameterizedConstructor=null;
  try {
    parameterizedConstructor=clazz.getConstructor(ParameterizedTestArgs.class);
  }
 catch (  NoSuchMethodException e) {
  }
  if (parameterizedConstructor != null) {
    for (    String method : testMethods) {
      if (params != null) {
        for (        Object param : params) {
          addParametarizedTest(suite,parameterizedConstructor,method,param);
        }
      }
 else {
        addParametarizedTest(suite,parameterizedConstructor,method,null);
      }
    }
  }
 else {
    suite.addTestSuite(clazz);
  }
  return suite;
}

/** 
 * Read the next token.  If we are at the end of the input, returns -1.  If the next token is a special character, returns that character as an integer.  If the next token is a quoted or unquoted word, returns 0 (call getTokenText() to read the contents.)
 */
public int getToken(){
  lastTokenText=null;
  if (!tokensRemaining())   return -1;
  char c=text.charAt(position);
  position++;
  if (specials.indexOf(c) != -1 || c < ' ' || c == 127)   return c;
  if (useQuotes && c == '"') {
    StringBuilder result=new StringBuilder();
    while (position < text.length()) {
      c=text.charAt(position);
      position++;
      if (c == '\\') {
        if (position < text.length()) {
          c=text.charAt(position);
          position++;
          result.append(c);
        }
      }
 else       if (c == '"')       break;
 else       result.append(c);
    }
    lastTokenText=result.toString();
    return 0;
  }
  int start=position - 1;
  while (position < text.length()) {
    c=text.charAt(position);
    if (c <= ' ' || c == 127 || (useQuotes && c == '"') || specials.indexOf(c) != -1)     break;
    position++;
  }
  lastTokenText=text.substring(start,position);
  return 0;
}

