/** 
 * Tries to resolve the folder: first as absolute (external) file, second as workspace (internal) file, third as project file. Returns null if the file does not exist. The name may contain variables.
 * @param project the project, may be null
 * @param name the name of the file
 * @return the file
 */
public static File resolveFolder(IProject project,String name){
  if (name == null) {
    return null;
  }
  name=JettyPluginUtils.resolveVariables(name);
  File file=new File(name);
  if ((file.isAbsolute()) && (file.exists() && (file.isDirectory()))) {
    return file;
  }
  try {
    IFolder resource=ResourcesPlugin.getWorkspace().getRoot().getFolder(new Path(name));
    if (resource.exists()) {
      IPath location=resource.getLocation();
      if (location != null) {
        return location.toFile().getAbsoluteFile();
      }
    }
  }
 catch (  IllegalArgumentException e) {
  }
  if (project == null) {
    return null;
  }
  try {
    IFolder resource=project.getFolder(name);
    if (resource.exists()) {
      IPath location=resource.getLocation();
      if (location != null) {
        return location.toFile().getAbsoluteFile();
      }
    }
  }
 catch (  IllegalArgumentException e) {
  }
  return null;
}

