private void upsertTaskProperties(Connection connection,Optional<StringMap> jobProperties,TaskExecutionInfoArray taskExecutions) throws SQLException {
  Optional<PreparedStatement> upsertStatement=Optional.absent();
  int batchSize=0;
  for (  TaskExecutionInfo taskExecution : taskExecutions) {
    if (taskExecution.hasTaskProperties()) {
      for (      Map.Entry<String,String> property : taskExecution.getTaskProperties().entrySet()) {
        if (!jobProperties.isPresent() || !jobProperties.get().containsKey(property.getKey()) || !jobProperties.get().get(property.getKey()).equals(property.getValue())) {
          if (!upsertStatement.isPresent()) {
            upsertStatement=Optional.of(connection.prepareStatement(TASK_PROPERTY_UPSERT_STATEMENT_TEMPLATE));
          }
          addPropertyToBatch(upsertStatement.get(),property.getKey(),property.getValue(),taskExecution.getTaskId());
          if (batchSize++ > 1000) {
            executeBatches(upsertStatement);
            upsertStatement=Optional.absent();
            batchSize=0;
          }
        }
      }
    }
  }
  executeBatches(upsertStatement);
}

@Override protected CouchbaseResponse decodeResponse(final ChannelHandlerContext ctx,final HttpObject msg) throws Exception {
  CouchbaseResponse response=null;
  if (msg instanceof HttpResponse) {
    responseHeader=(HttpResponse)msg;
    if (responseContent != null) {
      responseContent.clear();
    }
 else {
      responseContent=ctx.alloc().buffer();
    }
  }
  if (currentRequest() instanceof KeepAliveRequest) {
    if (msg instanceof LastHttpContent) {
      response=new KeepAliveResponse(ResponseStatusConverter.fromHttp(responseHeader.getStatus().code()),currentRequest());
      responseContent.clear();
      responseContent.discardReadBytes();
      finishedDecoding();
    }
  }
 else   if (currentRequest() instanceof PingRequest) {
    if (msg instanceof LastHttpContent) {
      response=new PingResponse(ResponseStatusConverter.fromHttp(responseHeader.getStatus().code()),currentRequest());
      responseContent.clear();
      responseContent.discardReadBytes();
      finishedDecoding();
    }
  }
 else   if (msg instanceof HttpContent) {
    responseContent.writeBytes(((HttpContent)msg).content());
    boolean lastChunk=msg instanceof LastHttpContent;
    if (currentRequest() instanceof RawAnalyticsRequest) {
      response=handleRawAnalyticsResponse(lastChunk,ctx);
    }
 else     if (currentRequest() instanceof GenericAnalyticsRequest) {
      if (queryRowObservable == null) {
        response=handleGenericAnalyticsResponse(lastChunk);
        if (response != null) {
          parseQueryResponse(lastChunk);
        }
      }
 else {
        parseQueryResponse(lastChunk);
      }
    }
  }
  return response;
}

