 * @param ys
 * @return
 */
public static long dotProductLong(List<Integer> xs,List<Integer> ys){
  long result=0;
  int n=xs.size();
  if (ys.size() != n)   throw new IllegalArgumentException("Different array sizes");
  for (int i=0; i < n; i++) {
    result+=(long)xs.get(i) * ys.get(i);
  }
  return result;
}
