 */
public static long dotProductLong(int[] xs,int[] ys){
  long result=0;
  int n=xs.length;
  if (ys.length != n)   throw new IllegalArgumentException("Different array sizes");
  for (int i=0; i < n; i++) {
    result+=(long)xs[i] * ys[i];
  }
  return result;
}

