@Parameters(name="{index}: higher priority event = {0}, lower priority event = {1}") @NonNull public static Iterable<Object[]> getDifferentParametersPermutations() throws ParseException {
  final List<Object[]> data=new ArrayList<>();
  final Version[] newVersionsSet=new Version[]{getVersionOffset(2),getVersionOffset(1),null};
  final Date[] lastSupportedDatesSet=new Date[]{new Date(DEFAULT_TIME),new Date(DEFAULT_TIME + 1),null};
  final boolean[] isUnsupportedValuesSet=new boolean[]{true,false};
  for (  final Date lastSupportedDate : lastSupportedDatesSet) {
    for (    final boolean isUnsupported : isUnsupportedValuesSet) {
      for (int newVersionIndex=0; newVersionIndex < newVersionsSet.length - 1; newVersionIndex++) {
        if (isUnsupported || lastSupportedDate != null || (newVersionsSet[newVersionIndex] != null && newVersionsSet[newVersionIndex + 1] != null)) {
          data.add(new Object[]{new NewVersionAvailableEvent(newVersionsSet[newVersionIndex],lastSupportedDate == null ? null : (Date)lastSupportedDate.clone(),isUnsupported),new NewVersionAvailableEvent(newVersionsSet[newVersionIndex + 1],lastSupportedDate == null ? null : (Date)lastSupportedDate.clone(),isUnsupported)});
        }
      }
    }
  }
  for (  final boolean isUnsupported : isUnsupportedValuesSet) {
    for (int lastSupportedDateIndex=0; lastSupportedDateIndex < lastSupportedDatesSet.length - 1; lastSupportedDateIndex++) {
      for (int newVersionIndex=0; newVersionIndex < newVersionsSet.length - 1; newVersionIndex++) {
        if (isUnsupported || (lastSupportedDatesSet[lastSupportedDateIndex] != null && lastSupportedDatesSet[lastSupportedDateIndex + 1] != null) || (newVersionsSet[newVersionIndex] != null && newVersionsSet[newVersionIndex + 1] != null)) {
          for (          final boolean reverseNewVersionIndexComparison : new boolean[]{false,true}) {
            data.add(new Object[]{new NewVersionAvailableEvent(newVersionsSet[reverseNewVersionIndexComparison ? newVersionIndex + 1 : newVersionIndex],lastSupportedDatesSet[lastSupportedDateIndex] == null ? null : (Date)lastSupportedDatesSet[lastSupportedDateIndex].clone(),isUnsupported),new NewVersionAvailableEvent(newVersionsSet[reverseNewVersionIndexComparison ? newVersionIndex : newVersionIndex + 1],lastSupportedDatesSet[lastSupportedDateIndex + 1] == null ? null : (Date)lastSupportedDatesSet[lastSupportedDateIndex + 1].clone(),isUnsupported)});
          }
        }
      }
    }
  }
  for (int isUnsupportedIndex=0; isUnsupportedIndex < isUnsupportedValuesSet.length - 1; isUnsupportedIndex++) {
    for (int lastSupportedDateIndex=0; lastSupportedDateIndex < lastSupportedDatesSet.length - 1; lastSupportedDateIndex++) {
      for (int newVersionIndex=0; newVersionIndex < newVersionsSet.length - 1; newVersionIndex++) {
        if ((isUnsupportedValuesSet[isUnsupportedIndex] && isUnsupportedValuesSet[isUnsupportedIndex + 1]) || (lastSupportedDatesSet[lastSupportedDateIndex] != null && lastSupportedDatesSet[lastSupportedDateIndex + 1] != null) || (newVersionsSet[newVersionIndex] != null && newVersionsSet[newVersionIndex + 1] != null)) {
          for (          final boolean reverseLastSupportedDateComparison : new boolean[]{false,true}) {
            for (            final boolean reverseNewVersionComparison : new boolean[]{false,true}) {
              data.add(new Object[]{new NewVersionAvailableEvent(newVersionsSet[reverseNewVersionComparison ? newVersionIndex + 1 : newVersionIndex],lastSupportedDatesSet[reverseLastSupportedDateComparison ? lastSupportedDateIndex + 1 : lastSupportedDateIndex] == null ? null : (Date)lastSupportedDatesSet[reverseLastSupportedDateComparison ? lastSupportedDateIndex + 1 : lastSupportedDateIndex].clone(),isUnsupportedValuesSet[isUnsupportedIndex]),new NewVersionAvailableEvent(newVersionsSet[reverseNewVersionComparison ? newVersionIndex : newVersionIndex + 1],lastSupportedDatesSet[reverseLastSupportedDateComparison ? lastSupportedDateIndex : lastSupportedDateIndex + 1] == null ? null : (Date)lastSupportedDatesSet[reverseLastSupportedDateComparison ? lastSupportedDateIndex : lastSupportedDateIndex + 1].clone(),isUnsupportedValuesSet[isUnsupportedIndex + 1])});
            }
          }
        }
      }
    }
  }
  return data;
}

/** 
 * Adds the sentence final token indices as <code>Integer</code> instances to the specified collection, only considering tokens between index <code>start</code> and <code>end-1</code> inclusive.
 * @param tokens Array of tokens to annotate.
 * @param whitespaces Array of whitespaces to annotate.
 * @param start Index of first token to annotate.
 * @param length Number of tokens to annotate.
 * @param indices Collection into which to write the boundaryindices.
 */
@Override public void boundaryIndices(String[] tokens,String[] whitespaces,int start,int length,Collection<Integer> indices){
  if (length == 0)   return;
  if (length == 1) {
    if (mForceFinalStop || isPossibleStop(start,tokens,whitespaces)) {
      indices.add(Integer.valueOf(start));
    }
    return;
  }
  boolean inParens=false;
  if (tokens[start].equals("("))   inParens=true;
  boolean inBrackets=false;
  if (tokens[start].equals("["))   inBrackets=true;
  int end=start + length - 1;
  for (int i=start + 1; i < end; ++i) {
    if (mBalanceParens) {
      if (tokens[i].equals("(")) {
        inParens=true;
        continue;
      }
      if (tokens[i].equals(")")) {
        inParens=false;
        continue;
      }
      if (tokens[i].equals("[")) {
        inBrackets=true;
        continue;
      }
      if (tokens[i].equals("]")) {
        inBrackets=false;
        continue;
      }
      if (inParens || inBrackets)       continue;
    }
    if (!isPossibleStop(i,tokens,whitespaces))     continue;
    if (whitespaces[i + 1].length() == 0)     continue;
    if (mBadPrevious.contains(tokens[i - 1].toLowerCase()))     continue;
    if (mBadFollowing.contains(tokens[i + 1].toLowerCase()))     continue;
    if (!possibleStart(tokens,whitespaces,i + 1,end))     continue;
    indices.add(Integer.valueOf(i));
  }
  if (mForceFinalStop || (isPossibleStop(end,tokens,whitespaces) && !mBadPrevious.contains(tokens[end - 1].toLowerCase())))   indices.add(Integer.valueOf(end));
}

