/** 
 * <p>Maps the specified <code>key</code> to the specified <code>value</code> in this hashtable. The key cannot be <code>null</code>. </p> <p/> <p>The value can be retrieved by calling the <code>get</code> method with a key that is equal to the original key.</p>
 * @param key   the hashtable key.
 * @param value the value.
 * @return the previous value of the specified key in this hashtable,or <code>null</code> if it did not have one.
 * @throws NullPointerException if the key is <code>null</code>.
 * @see #get(int)
 */
public Object put(int key,Object value){
  Entry tab[]=table;
  int hash=key;
  int index=(hash & 0x7FFFFFFF) % tab.length;
  for (Entry e=tab[index]; e != null; e=e.next) {
    if (e.hash == hash) {
      Object old=e.value;
      e.value=value;
      return old;
    }
  }
  if (count >= threshold) {
    rehash();
    tab=table;
    index=(hash & 0x7FFFFFFF) % tab.length;
  }
  Entry e=new Entry(hash,key,value,tab[index]);
  tab[index]=e;
  count++;
  return null;
}

