@Override @Transactional public void queryEach(Visitor<Object[]> handler,int batchSize,String queryStr,Object... params){
  try {
    Query query=entityManager.get().createQuery(queryStr);
    if (params != null) {
      for (int i=0; i < params.length; i++) {
        Object param=params[i];
        query.setParameter(i + 1,param);
      }
    }
    query.setMaxResults(batchSize);
    for (int start=0; ; start+=batchSize) {
      query.setFirstResult(start);
      List list=query.getResultList();
      if (list.isEmpty())       return;
      for (      Object row : list) {
        if (row.getClass().isArray() && !handler.handleItem((Object[])row) || !row.getClass().isArray() && !handler.handleItem(new Object[]{row}))         return;
      }
    }
  }
 catch (  Exception|Error ex) {
    log.error("Unable to perform request in " + this.getClass().getSimpleName() + ":queryEach, full stack trace follows:",ex);
    throw ex;
  }
}
