 * Deserialize the fixed file trailer from the given stream. The version needs to already be specified. Make sure this is consistent with {@link #serialize(DataOutputStream)}.
 * @param inputStream
 * @throws IOException
 */
void deserialize(DataInputStream inputStream) throws IOException {
  HFile.checkFormatVersion(majorVersion);
  BlockType.TRAILER.readAndCheck(inputStream);
  if (majorVersion > 2 || (majorVersion == 2 && minorVersion >= PBUF_TRAILER_MINOR_VERSION)) {
    deserializeFromPB(inputStream);
  }
 else {
    deserializeFromWritable(inputStream);
  }
  int version=inputStream.readInt();
  expectMajorVersion(extractMajorVersion(version));
  expectMinorVersion(extractMinorVersion(version));
}

private org.apache.olingo.fit.metadata.Container getContainer(final StartElement start,final XMLEventReader reader) throws XMLStreamException {
  final org.apache.olingo.fit.metadata.Container container=new org.apache.olingo.fit.metadata.Container(start.getAttributeByName(new QName("Name")).getValue());
  boolean completed=false;
  while (!completed && reader.hasNext()) {
    XMLEvent event=reader.nextEvent();
    if (event.isStartElement() && (event.asStartElement().getName().equals(new QName(DEF_NS,"EntitySet")) || event.asStartElement().getName().equals(new QName(DEF_NS,"Singleton")))) {
      final EntitySet entitySet=getEntitySet(event.asStartElement(),reader);
      container.addEntitySet(entitySet.getName(),entitySet);
    }
 else     if (event.isEndElement() && event.asEndElement().getName().equals(start.getName())) {
      completed=true;
    }
  }
  return container;
}

