/** 
 * Checks to see if a particular day is valid for certain strict repeat types
 * @param date the date
 * @param freq the frequency
 * @param daylist the daylist (for repeat with a list of days)
 * @return true, if the daye is compatible with the repeat frequency
 */
static public boolean isCompatible(Calendar date,String freq,Collection<Integer> daylist){
  String f=freqToEnglish(freq);
  int day=date.get(Calendar.DAY_OF_WEEK);
  if (f.equals(WEEKDAYS) && (day == Calendar.SATURDAY || day == Calendar.SUNDAY))   return false;
 else   if (f.equals(WEEKENDS) && (day != Calendar.SATURDAY && day != Calendar.SUNDAY))   return false;
 else   if (f.equals(MWF) && (day != Calendar.MONDAY && day != Calendar.WEDNESDAY && day != Calendar.FRIDAY))   return false;
 else   if (f.equals(TTH) && (day != Calendar.TUESDAY && day != Calendar.THURSDAY))   return false;
 else   if (f.equals(DAYLIST) && !daylist.contains(Integer.valueOf(day)))   return false;
 else   if (f.equals(MONTHLY_DAY_LAST)) {
    Calendar copy=new GregorianCalendar();
    copy.setTime(date.getTime());
    int doy=date.get(Calendar.DAY_OF_YEAR);
    copy.set(Calendar.DAY_OF_WEEK_IN_MONTH,-1);
    if (doy != copy.get(Calendar.DAY_OF_YEAR))     return false;
  }
  return true;
}

/** 
 * Method to add an element to the HashSet.
 * @param element The new element
 * @return Whether it was added ok.
 */
public boolean add(E element){
  if (!allowNulls && element == null) {
    throw new NullPointerException("Nulls not allowed for collection at field " + ownerMmd.getName() + " but element is null");
  }
  if (useCache) {
    loadFromStore();
  }
  if (contains(element)) {
    return false;
  }
  if (ownerOP != null && ownerOP.getExecutionContext().getManageRelations() && !initialising) {
    ownerOP.getExecutionContext().getRelationshipManager(ownerOP).relationAdd(ownerMmd.getAbsoluteFieldNumber(),element);
  }
  boolean backingSuccess=true;
  if (backingStore != null) {
    if (SCOUtils.useQueuedUpdate(ownerOP)) {
      ownerOP.getExecutionContext().addOperationToQueue(new CollectionAddOperation(ownerOP,backingStore,element));
    }
 else {
      try {
        backingSuccess=backingStore.add(ownerOP,element,useCache ? delegate.size() : -1);
      }
 catch (      NucleusDataStoreException dse) {
        throw new IllegalArgumentException(Localiser.msg("023013","add",ownerMmd.getName(),dse),dse);
      }
    }
  }
  makeDirty();
  boolean delegateSuccess=delegate.add(element);
  if (ownerOP != null && !ownerOP.getExecutionContext().getTransaction().isActive()) {
    ownerOP.getExecutionContext().processNontransactionalUpdate();
  }
  return backingStore != null ? backingSuccess : delegateSuccess;
}

