/** 
 * Post the provided data by passing the appropriate headers and status code in a request chain through an  {@link NewVersionBroadcastInterceptor}, then remove the sticky event from the event bus.
 * @param newVersion The new version.
 * @param lastSupportedDate The last supported date.
 * @param isUnsupported Whether the current version is unsupported.
 * @return The event that was posted. This can be null if the data does not constitute a validevent.
 */
@Nullable private static NewVersionAvailableEvent postAndRemoveEventFromInterceptor(@Nullable final Version newVersion,@Nullable final Date lastSupportedDate,final boolean isUnsupported) throws IOException {
  final EventBus eventBus=getEventBus();
  eventBus.removeStickyEvent(NewVersionAvailableEvent.class);
  final NewVersionAvailableEvent event=postEventFromInterceptor(new NewVersionBroadcastInterceptor(),newVersion,lastSupportedDate,isUnsupported);
  if (event != null) {
    assertTrue(eventBus.removeStickyEvent(event));
  }
  return event;
}

