@SuppressWarnings("unchecked") public static StormTopology buildWordCountAndSourceTopology(LocalDRPC drpc){
  LOG.info("Building topology.");
  TridentTopology topology=new TridentTopology();
  String source1="spout1";
  String source2="spout2";
  FixedBatchSpout spout1=new FixedBatchSpout(new Fields("sentence","source"),3,new Values("the cow jumped over the moon",source1),new Values("the man went to the store and bought some candy",source1),new Values("four score and four years ago",source2),new Values("how much wood can a wood chuck chuck",source2));
  spout1.setCycle(true);
  TridentState wordCounts=topology.newStream("spout1",spout1).each(new Fields("sentence"),new Split(),new Fields("word")).groupBy(new Fields("word","source")).persistentAggregate(CassandraCqlMapState.nonTransactional(new WordCountAndSourceMapper()),new IntegerCount(),new Fields("count")).parallelismHint(6);
  topology.newDRPCStream("words",drpc).each(new Fields("args"),new Split(),new Fields("word")).groupBy(new Fields("word")).stateQuery(wordCounts,new Fields("word"),new MapGet(),new Fields("count")).each(new Fields("count"),new FilterNull()).aggregate(new Fields("count"),new Sum(),new Fields("sum"));
  return topology.build();
}

