public Map<String,Object> objectToMap(Object obj) throws Exception {
  if (obj == null)   return null;
  Map<String,Object> map=new HashMap<String,Object>();
  BeanInfo beanInfo=Introspector.getBeanInfo(obj.getClass());
  PropertyDescriptor[] propertyDescriptors=beanInfo.getPropertyDescriptors();
  for (  PropertyDescriptor property : propertyDescriptors) {
    String key=property.getName();
    if (key.compareToIgnoreCase("class") == 0) {
      continue;
    }
    Method getter=property.getReadMethod();
    Object value=getter != null ? getter.invoke(obj) : null;
    map.put(key,value);
  }
  return map;
}

/** 
 * Returns a memoizing version of this function, which computes the return value for given arguments only one time. On subsequent calls given the same arguments the memoized value is returned. <p> Please note that memoizing functions do not permit  {@code null} as single argument or return value.
 * @return a memoizing function equivalent to this.
 */
default Function6<T1,T2,T3,T4,T5,T6,R> memoized(){
  if (isMemoized()) {
    return this;
  }
 else {
    final Map<Tuple6<T1,T2,T3,T4,T5,T6>,R> cache=new HashMap<>();
    return (Function6<T1,T2,T3,T4,T5,T6,R> & Memoized)(t1,t2,t3,t4,t5,t6) -> {
      final Tuple6<T1,T2,T3,T4,T5,T6> key=Tuple.of(t1,t2,t3,t4,t5,t6);
synchronized (cache) {
        if (cache.containsKey(key)) {
          return cache.get(key);
        }
 else {
          final R value=tupled().apply(key);
          cache.put(key,value);
          return value;
        }
      }
    }
;
  }
}

