public String matchString(String search,Collection<String> in,boolean ignoreCase,int firstEditDistance,double firstMinPercentCorrect,int maxIndex,double indexMinPercentCorrect,int secondEditDistance,double secondMinPercentCorrect){
  if (search == null || in == null || in.isEmpty()) {
    return null;
  }
  if (in.contains(search)) {
    return search;
  }
  Map<String,Integer> firstEditDistanceCheck=this.getMatches(search,in,firstEditDistance,ignoreCase);
  int searchStringLength=search.length();
  if (!firstEditDistanceCheck.isEmpty()) {
    for (    Map.Entry<String,Integer> entry : firstEditDistanceCheck.entrySet()) {
      double curPercentage=(entry.getKey().length() - entry.getValue()) * 100 / entry.getKey().length();
      if (curPercentage >= firstMinPercentCorrect) {
        logger.debug("1stDist FOUND: {} for {} (D:{}|{}%)",firstEditDistanceCheck.keySet().iterator().next(),search,firstEditDistanceCheck.values().iterator().next(),curPercentage);
        return entry.getKey();
      }
      logger.debug("1stDist TO WEAK: {} for {} (D:{}|{}%)",firstEditDistanceCheck.keySet().iterator().next(),search,firstEditDistanceCheck.values().iterator().next(),curPercentage);
    }
  }
  String bestMatch=null;
  if (ignoreCase) {
    search=search.toLowerCase();
  }
  if (maxIndex >= 0) {
    int bestIndex=maxIndex;
    int currentIndex;
    double bestPercentCorrect=indexMinPercentCorrect;
    for (    String inList : in) {
      if (ignoreCase) {
        currentIndex=inList.toLowerCase(Locale.ENGLISH).indexOf(search);
      }
 else {
        currentIndex=inList.indexOf(search);
      }
      if (currentIndex != -1) {
        double curPercentCorrect=searchStringLength * 100 / inList.length();
        if (currentIndex < bestIndex && curPercentCorrect >= indexMinPercentCorrect) {
          logger.debug("Index: FOUND {} for {} (I:{}|{}%)",inList,search,currentIndex,curPercentCorrect);
          bestIndex=currentIndex;
          bestPercentCorrect=curPercentCorrect;
          bestMatch=inList;
        }
 else         if (currentIndex == bestIndex && curPercentCorrect >= bestPercentCorrect) {
          logger.debug("Index: FOUND {} for {} (I:{}|{}%)",inList,search,currentIndex,curPercentCorrect);
          bestPercentCorrect=curPercentCorrect;
          bestMatch=inList;
        }
      }
    }
  }
  if (bestMatch != null || secondEditDistance < 1 || searchStringLength < 3) {
    return bestMatch;
  }
  int bestDistance=secondEditDistance + 1;
  double bestPercentCorrect=secondMinPercentCorrect;
  for (  String inList : in) {
    if (inList.length() >= searchStringLength + secondEditDistance) {
      String subString=inList.substring(0,searchStringLength + secondEditDistance);
      if (ignoreCase) {
        subString=subString.toLowerCase(Locale.ENGLISH);
      }
      int currentDistance=this.editDistance.execute(search,subString);
      double curPercentCorrect=(searchStringLength - currentDistance) * 100 / inList.length();
      if (currentDistance < bestDistance && curPercentCorrect >= secondMinPercentCorrect) {
        logger.debug("2nDist: Found {}|{} for {} (D:{}|{}%)",inList,subString,search,currentDistance,(int)curPercentCorrect);
        bestDistance=currentDistance;
        bestMatch=inList;
        bestPercentCorrect=curPercentCorrect;
      }
 else       if (currentDistance == bestDistance && bestPercentCorrect <= curPercentCorrect) {
        logger.debug("2nDist: Found {}|{} for {} (D:{}|{}%)",inList,subString,search,currentDistance,(int)curPercentCorrect);
        bestMatch=inList;
        bestPercentCorrect=curPercentCorrect;
      }
    }
  }
  return bestMatch;
}
