    return new WebSocketResourceProvider(this.environment.getJerseyServletContainer(),this.environment.getRequestLog(),authenticated,this.environment.getMessageFactory(),Optional.ofNullable(this.environment.getConnectListener()),this.environment.getIdleTimeoutMillis());
