 */
public void midletUpdated(MIDletProxy midlet,int reason){
  boolean amsMidlet=(MIDletSuiteUtils.getAmsIsolateId() == midlet.getIsolateId());
  if (reason == MIDletProxyListListener.RESOURCES_SUSPENDED) {
    if (!amsMidlet) {
      midletPaused=true;
    }
    removeSuspendDependency(midlet);
  }
 else   if (reason == MIDletProxyListListener.MIDLET_STATE && amsMidlet && midlet.getMidletState() == MIDletProxy.MIDLET_ACTIVE) {
    alertIfAllMidletsKilled();
  }
}

