/** 
 * Unsigned division of  {@code d1} by {@code d2}. See "Division by Invariant Integers using Multiplication", by Torbjorn Granlund and Peter L. Montgomery, 1994. <a href= "http://gmplib.org/~tege/divcnst-pldi94.pdf">http://gmplib.org/~tege/divcnst-pldi94.pdf</a>
 * @throws ArithmeticException when c equals zero.
 */
static public final long divide(final long d1,final long d2){
  if (d2 < 0) {
    if (Long.compareUnsigned(d1,d2) < 0) {
      return 0;
    }
 else {
      return 1;
    }
  }
  if (d1 < 0) {
    final long quotient=((d1 >>> 1) / d2) << 1;
    final long reminder=d1 - quotient * d2;
    return quotient + (Long.compareUnsigned(d2,reminder) < 0 ? 0 : 1);
  }
  return d1 / d2;
}

