  if (taskRunResult == null || taskRunResult.getOperationResult() == null) {
    return eventStatusType == EventStatusType.SUCCESS || eventStatusType == EventStatusType.ALSO_SUCCESS || eventStatusType == EventStatusType.IN_PROGRESS;
  }
  OperationResult result=taskRunResult.getOperationResult();
switch (eventStatusType) {
case SUCCESS:
case ALSO_SUCCESS:
    return result.isSuccess() || result.isHandledError() || result.isWarning();
case IN_PROGRESS:
  return false;
case FAILURE:
return result.isError();
case ONLY_FAILURE:
return result.isFatalError();
default :
throw new IllegalStateException("Invalid eventStatusType: " + eventStatusType);
}
}

