static <K,V>ImmutableBiMap<K,V> fromEntryArray(int n,Entry<K,V>[] entryArray){
  checkPositionIndex(n,entryArray.length);
  int tableSize=Hashing.closedTableSize(n,MAX_LOAD_FACTOR);
  int mask=tableSize - 1;
  ImmutableMapEntry<K,V>[] keyTable=createEntryArray(tableSize);
  ImmutableMapEntry<K,V>[] valueTable=createEntryArray(tableSize);
  Entry<K,V>[] entries;
  if (n == entryArray.length) {
    entries=entryArray;
  }
 else {
    entries=createEntryArray(n);
  }
  int hashCode=0;
  for (int i=0; i < n; i++) {
    @SuppressWarnings("unchecked") Entry<K,V> entry=entryArray[i];
    K key=entry.getKey();
    V value=entry.getValue();
    checkEntryNotNull(key,value);
    int keyHash=key.hashCode();
    int valueHash=value.hashCode();
    int keyBucket=Hashing.smear(keyHash) & mask;
    int valueBucket=Hashing.smear(valueHash) & mask;
    ImmutableMapEntry<K,V> nextInKeyBucket=keyTable[keyBucket];
    int keyBucketLength=checkNoConflictInKeyBucket(key,entry,nextInKeyBucket);
    ImmutableMapEntry<K,V> nextInValueBucket=valueTable[valueBucket];
    int valueBucketLength=checkNoConflictInValueBucket(value,entry,nextInValueBucket);
    if (keyBucketLength > RegularImmutableMap.MAX_HASH_BUCKET_LENGTH || valueBucketLength > RegularImmutableMap.MAX_HASH_BUCKET_LENGTH) {
      return JdkBackedImmutableBiMap.create(n,entryArray);
    }
    ImmutableMapEntry<K,V> newEntry=(nextInValueBucket == null && nextInKeyBucket == null) ? RegularImmutableMap.makeImmutable(entry,key,value) : new NonTerminalImmutableBiMapEntry<>(key,value,nextInKeyBucket,nextInValueBucket);
    keyTable[keyBucket]=newEntry;
    valueTable[valueBucket]=newEntry;
    entries[i]=newEntry;
    hashCode+=keyHash ^ valueHash;
  }
  return new RegularImmutableBiMap<>(keyTable,valueTable,entries,mask,hashCode);
}

private static void formatSetter(IMethod setter,String prefix,StringBuilder buffer){
  final String indent=Formatting.getIndent("property.setter.indent",prefix);
  final IValue value=setter.getValue();
  final Name setterParameterName=setter.getParameters().get(0).getName();
  buffer.append('\n').append(indent);
  setter.getAttributes().toInlineString(indent,buffer);
  buffer.append("set");
  if (setterParameterName != Names.newValue) {
    Formatting.appendSeparator(buffer,"property.setter.parameter.open_paren",'(');
    buffer.append(setterParameterName);
    Formatting.appendSeparator(buffer,"property.setter.parameter.close_paren",')');
  }
  if (value != null) {
    if (Util.formatStatementList(indent,buffer,value)) {
      return;
    }
    if (Formatting.getBoolean("property.setter.separator.space_before")) {
      buffer.append(' ');
    }
    buffer.append(':');
    if (Formatting.getBoolean("property.setter.separator.newline_after")) {
      buffer.append('\n').append(indent);
    }
 else     if (Formatting.getBoolean("property.setter.separator.space_after")) {
      buffer.append(' ');
    }
    value.toString(indent,buffer);
  }
  if (Formatting.getBoolean("property.setter.semicolon")) {
    buffer.append(';');
  }
}

