private Gate binary(CircuitDetermination aret,CircuitDetermination bret,ComponentFactory factory){
  if (aret instanceof Gate) {
    Gate a=(Gate)aret;
    if (a.factory == factory) {
      if (bret instanceof Gate) {
        Gate b=(Gate)bret;
        if (b.factory == factory) {
          a.inputs.addAll(b.inputs);
          return a;
        }
      }
      a.inputs.add(bret);
      return a;
    }
  }
  if (bret instanceof Gate) {
    Gate b=(Gate)bret;
    if (b.factory == factory) {
      b.inputs.add(aret);
      return b;
    }
  }
  Gate ret=new Gate(factory);
  ret.inputs.add(aret);
  ret.inputs.add(bret);
  return ret;
}

@Override public byte markTokensImpl(byte token,Segment line,int lineIndex){
  char[] array=line.array;
  byte cmdState=0;
  int offset=line.offset;
  int lastOffset=offset;
  int length=line.count + offset;
  if (token == Token.LITERAL1 && lineIndex != 0 && lineInfo[lineIndex - 1].obj != null) {
    String str=(String)lineInfo[lineIndex - 1].obj;
    if (str != null && str.length() == line.count && SyntaxUtilities.regionMatches(false,line,offset,str)) {
      addToken(line.count,Token.LITERAL1);
      return Token.NULL;
    }
 else {
      addToken(line.count,Token.LITERAL1);
      lineInfo[lineIndex].obj=str;
      return Token.LITERAL1;
    }
  }
  boolean backslash=false;
  loop:   for (int i=offset; i < length; i++) {
    int i1=(i + 1);
    char c=array[i];
    if (c == '\\') {
      backslash=!backslash;
      continue;
    }
switch (token) {
case Token.NULL:
switch (c) {
case ' ':
case '\t':
case '(':
case ')':
        backslash=false;
      if (cmdState == 1) {
        addToken(i - lastOffset,Token.KEYWORD1);
        lastOffset=i;
        cmdState=2;
      }
    break;
case '=':
  backslash=false;
if (cmdState == 1) {
  addToken(i - lastOffset,token);
  lastOffset=i;
  cmdState=2;
}
break;
case '&':
case '|':
case ';':
if (backslash) backslash=false;
 else cmdState=0;
break;
case '#':
if (backslash) backslash=false;
 else {
addToken(i - lastOffset,token);
addToken(length - i,Token.COMMENT1);
lastOffset=length;
break loop;
}
break;
case '$':
if (backslash) backslash=false;
 else {
addToken(i - lastOffset,token);
cmdState=2;
lastOffset=i;
if (length - i >= 2) {
switch (array[i1]) {
case '(':
continue;
case '{':
token=LVARIABLE;
break;
default :
token=Token.KEYWORD2;
break;
}
}
 else token=Token.KEYWORD2;
}
break;
case '"':
if (backslash) backslash=false;
 else {
addToken(i - lastOffset,token);
token=Token.LITERAL1;
lineInfo[lineIndex].obj=null;
cmdState=2;
lastOffset=i;
}
break;
case '\'':
if (backslash) backslash=false;
 else {
addToken(i - lastOffset,token);
token=Token.LITERAL2;
cmdState=2;
lastOffset=i;
}
break;
case '<':
if (backslash) backslash=false;
 else {
if (length - i > 1 && array[i1] == '<') {
addToken(i - lastOffset,token);
token=Token.LITERAL1;
lastOffset=i;
lineInfo[lineIndex].obj=new String(array,i + 2,length - (i + 2));
}
}
break;
default :
backslash=false;
if (Character.isLetter(c)) {
if (cmdState == 0) {
addToken(i - lastOffset,token);
lastOffset=i;
cmdState++;
}
}
break;
}
break;
case Token.KEYWORD2:
backslash=false;
if (!Character.isLetterOrDigit(c) && c != '_') {
if (i != offset && array[i - 1] == '$') {
addToken(i1 - lastOffset,token);
lastOffset=i1;
token=Token.NULL;
continue;
}
 else {
addToken(i - lastOffset,token);
lastOffset=i;
token=Token.NULL;
}
}
break;
case Token.LITERAL1:
if (backslash) backslash=false;
 else if (c == '"') {
addToken(i1 - lastOffset,token);
cmdState=2;
lastOffset=i1;
token=Token.NULL;
}
 else backslash=false;
break;
case Token.LITERAL2:
if (backslash) backslash=false;
 else if (c == '\'') {
addToken(i1 - lastOffset,Token.LITERAL1);
cmdState=2;
lastOffset=i1;
token=Token.NULL;
}
 else backslash=false;
break;
case LVARIABLE:
backslash=false;
if (c == '}') {
addToken(i1 - lastOffset,Token.KEYWORD2);
lastOffset=i1;
token=Token.NULL;
}
break;
default :
throw new InternalError("Invalid state: " + token);
}
}
switch (token) {
case Token.NULL:
if (cmdState == 1) addToken(length - lastOffset,Token.KEYWORD1);
 else addToken(length - lastOffset,token);
break;
case Token.LITERAL2:
addToken(length - lastOffset,Token.LITERAL1);
break;
case Token.KEYWORD2:
addToken(length - lastOffset,token);
token=Token.NULL;
break;
case LVARIABLE:
addToken(length - lastOffset,Token.INVALID);
token=Token.NULL;
break;
default :
addToken(length - lastOffset,token);
break;
}
return token;
}

@Override protected void executeImpl() throws MojoExecutionException {
  final ClassLoader contextClassLoader=currentThread().getContextClassLoader();
  try {
    Log log=getLog();
    if (log.isDebugEnabled()) {
      log.debug(format("Setting System property \"user.dir\" to [%s]",workingDirectory.getAbsolutePath()));
    }
    System.setProperty("user.dir",workingDirectory.getAbsolutePath());
    ClassLoader testClassLoader=createTestClassLoader();
    RobotServer server=new RobotServer(getControl(),verbose,testClassLoader);
    Map<?,?> pluginsAsMap=project.getBuild().getPluginsAsMap();
    Plugin plugin=(Plugin)pluginsAsMap.get("org.kaazing:k3po-maven-plugin");
    if (plugin != null) {
      for (      Dependency dependency : plugin.getDependencies()) {
        if (project.getGroupId().equals(dependency.getGroupId()) && project.getArtifactId().equals(dependency.getArtifactId()) && project.getVersion().equals(dependency.getVersion())) {
          currentThread().setContextClassLoader(testClassLoader);
        }
      }
    }
    setDefaultFactory(new MavenLoggerFactory(log));
    long checkpoint=currentTimeMillis();
    server.start();
    float duration=(currentTimeMillis() - checkpoint) / 1000.0f;
    if (log.isDebugEnabled()) {
      String version=(plugin != null) ? plugin.getVersion() : "unknown";
      if (!daemon) {
        log.debug(format("K3PO [%s] started in %.3fsec (CTRL+C to stop)",version,duration));
      }
 else {
        log.debug(format("K3PO [%s] started in %.3fsec",version,duration));
      }
    }
 else {
      if (!daemon) {
        log.info("K3PO started (CTRL+C to stop)");
      }
 else {
        log.info("K3PO started");
      }
    }
    setServer(server);
    if (!daemon) {
      server.join();
    }
  }
 catch (  Exception e) {
    throw new MojoExecutionException("K3PO failed to start",e);
  }
 finally {
    currentThread().setContextClassLoader(contextClassLoader);
  }
}

