@Override public synchronized void deleteTab(int id){
  if (mViewIsAnimating) {
    return;
  }
  mTabLayout.clearDisappearingChildren();
  int position=mIdList.indexOf(id);
  if (position >= mWebViewList.size()) {
    return;
  }
  if (position == -1) {
    return;
  }
  int current=mIdList.indexOf(mCurrentView.getId());
  if (current == -1) {
    return;
  }
  LightningView reference=mWebViewList.get(position);
  if (reference == null) {
    return;
  }
  if (reference.getUrl() != null && !reference.getUrl().startsWith(Constants.FILE)) {
    mEditPrefs.putString(PreferenceConstants.SAVE_URL,reference.getUrl()).apply();
  }
  mTabScrollView.smoothScrollTo(mCurrentView.getTitleView().getLeft(),0);
  final boolean isShown=reference.isShown();
  if (current > position) {
    if (reference.isShown()) {
      showTab(mWebViewList.get(position - 1));
    }
    animateTabRemoval(mWebViewList.get(position).getTitleView(),position,reference,isShown);
    reference.onDestroy();
    mWebViewList.remove(position);
    mIdList.remove(position);
  }
 else   if (mWebViewList.size() > position + 1) {
    if (reference.isShown()) {
      showTab(mWebViewList.get(position + 1));
    }
    animateTabRemoval(mWebViewList.get(position).getTitleView(),position,reference,isShown);
    reference.onDestroy();
    mWebViewList.remove(position);
    mIdList.remove(position);
  }
 else   if (mWebViewList.size() > 1) {
    if (reference.isShown()) {
      showTab(mWebViewList.get(position - 1));
    }
    animateTabRemoval(mWebViewList.get(position).getTitleView(),position,reference,isShown);
    reference.onDestroy();
    mWebViewList.remove(position);
    mIdList.remove(position);
  }
 else {
    if (mCurrentView.getUrl() == null || mCurrentView.getUrl().startsWith(Constants.FILE) || mCurrentView.getUrl().equals(mHomepage)) {
      closeActivity();
    }
 else {
      mWebViewList.remove(position);
      mIdList.remove(position);
      if (mPreferences.getBoolean(PreferenceConstants.CLEAR_CACHE_EXIT,false) && mCurrentView != null) {
        mCurrentView.clearCache(true);
      }
      if (mPreferences.getBoolean(PreferenceConstants.CLEAR_HISTORY_EXIT,false) && !isIncognito()) {
        clearHistory();
        Log.i(Constants.TAG,"History Cleared");
      }
      if (mPreferences.getBoolean(PreferenceConstants.CLEAR_COOKIES_EXIT,false) && !isIncognito()) {
        clearCookies();
        Log.i(Constants.TAG,"Cookies Cleared");
      }
      if (reference != null) {
        reference.pauseTimers();
        reference.onDestroy();
      }
      mCurrentView=null;
      finish();
    }
  }
  Log.i(Constants.TAG,"Tab Deleted");
}

