/** 
 * Gathers all namespaces created by goog.provide and any definitions in code. <p>This method does not actually declare anything in the scope. In order to accurately report redefinition warnings, wait to declare implicit names until the actual goog.provide call.
 * @param root The global ROOT or a SCRIPT
 */
private void gatherAllProvides(Node root){
  if (!processClosurePrimitives) {
    return;
  }
  Node externs=root.getFirstChild();
  Node js=root.getSecondChild();
  Map<String,ProvidedName> providedNames=new ProcessClosureProvidesAndRequires(compiler,null,CheckLevel.OFF,true).collectProvidedNames(externs,js);
  for (  ProvidedName name : providedNames.values()) {
    ModuleMetadata metadata=metadataMap.getModulesByGoogNamespace().get(name.getNamespace());
    if (name.getCandidateDefinition() != null) {
      Node firstDefinitionNode=name.getCandidateDefinition();
      if (NodeUtil.isExprAssign(firstDefinitionNode) && firstDefinitionNode.getFirstFirstChild().isName()) {
        undeclaredNamesForClosure.add(firstDefinitionNode.getFirstFirstChild());
      }
    }
 else     if (name.getFirstProvideCall() != null && NodeUtil.isExprCall(name.getFirstProvideCall()) && (metadata == null || !metadata.isLegacyGoogModule())) {
      providedNamesFromCall.put(name.getFirstProvideCall(),name);
    }
    if (metadata != null && metadata.isGoogProvide()) {
      typeRegistry.registerLegacyClosureModule(name.getNamespace());
    }
  }
}

