@Override public SRResult similarity(String phrase1,String phrase2,boolean explanations) throws DaoException {
  if (phraseMode == PhraseMode.NONE) {
    return super.similarity(phrase1,phrase2,explanations);
  }
  TIntFloatMap vector1=null;
  TIntFloatMap vector2=null;
  if (phraseMode == PhraseMode.BOTH || phraseMode == PhraseMode.GENERATOR) {
    try {
      vector1=generator.getVector(phrase1);
      vector2=generator.getVector(phrase2);
    }
 catch (    UnsupportedOperationException e) {
    }
  }
  if ((vector1 == null || vector2 == null) && (phraseMode == PhraseMode.BOTH || phraseMode == PhraseMode.CREATOR)) {
    if (phraseVectorCreator == null) {
      throw new IllegalStateException("phraseMode is " + phraseMode + " but phraseVectorCreator is null");
    }
    TIntFloatMap vectors[]=phraseVectorCreator.getPhraseVectors(phrase1,phrase2);
    if (vectors != null) {
      vector1=vectors[0];
      vector2=vectors[1];
    }
  }
  if (vector1 == null || vector2 == null) {
    return super.similarity(phrase1,phrase2,explanations);
  }
 else {
    SRResult result=new SRResult(similarity.similarity(vector1,vector2));
    if (explanations) {
      result.setExplanations(generator.getExplanations(phrase1,phrase2,vector1,vector2,result));
    }
    return normalize(result);
  }
}

public void OrdersCountForCustomer(HttpServletRequest request,HttpServletResponse response){
  EntityQuery eq=this.extractEntityQuery(request);
  Map parameterMap=eq.getParameters();
  String companyName=(String)parameterMap.get("companyName");
  eq=eq.where(new BinaryPredicate(Operator.StartsWith,"companyName",companyName));
  eq=eq.expand("orders");
  eq=eq.take(1);
  QueryResult qr=this.executeQuery(Customer.class,eq);
  List<Customer> custResults=qr.getResults();
  List<Integer> results=new ArrayList<Integer>();
  if (custResults.size() > 0) {
    Customer cust=(Customer)qr.getResults().get(0);
    results.add(cust.getOrders().size());
  }
 else {
    results.add(0);
  }
  qr=new QueryResult(results);
  writeQueryResponse(response,qr);
}

/** 
 * Process an object literal and all the types on it.
 * @param objLit The OBJECTLIT node.
 * @param objLitType The type of the OBJECTLIT node. This might be a namedtype, because of the lends annotation.
 * @param declareOnOwner If true, declare properties on the objLitType aswell. If false, the caller should take care of this.
 */
void processObjectLitProperties(Node objLit,ObjectType objLitType,boolean declareOnOwner){
  for (Node keyNode=objLit.getFirstChild(); keyNode != null; keyNode=keyNode.getNext()) {
    if (keyNode.isComputedProp() || keyNode.isSpread()) {
      continue;
    }
    Node value=keyNode.getFirstChild();
    String memberName=NodeUtil.getObjectLitKeyName(keyNode);
    JSDocInfo info=keyNode.getJSDocInfo();
    JSType valueType=getDeclaredType(info,keyNode,value,null);
    JSType keyType=objLitType.isEnumType() ? objLitType.toMaybeEnumType().getElementsType() : TypeCheck.getObjectLitKeyTypeFromValueType(keyNode,valueType);
    String qualifiedName=NodeUtil.getBestLValueName(keyNode);
    if (qualifiedName != null) {
      new SlotDefiner().forDeclarationNode(keyNode).forVariableName(qualifiedName).inScope(getLValueRootScope(keyNode)).withType(keyType).allowLaterTypeInference(keyType == null).defineSlot();
    }
 else     if (keyType != null) {
      setDeferredType(keyNode,keyType);
    }
    if (keyType != null && objLitType != null && declareOnOwner) {
      objLitType.defineDeclaredProperty(memberName,keyType,keyNode);
    }
  }
}

