@Transient public Amount getShortAvgStopPrice(){
  if (shortAvgStopPrice != null)   return shortAvgStopPrice;
  shortCumVolume=DecimalAmount.ZERO;
  Amount shortAvgStopPriceTmp=null;
  Iterator<Fill> itf=getFills().iterator();
  while (itf.hasNext() && shortAvgStopPrice == null) {
    Fill pos=itf.next();
    if (pos.isShort()) {
      if (pos.getFillChildOrders() != null) synchronized (pos.getFillChildOrders()) {
        for (        Order childOrder : pos.getFillChildOrders()) {
          if (childOrder.getStopPrice() != null && !childOrder.getStopPrice().isZero()) {
            if (childOrder.isBid() && childOrder.getStopPrice() != null && !childOrder.getStopPrice().isZero() && !(shortCumVolume.plus(childOrder.getUnfilledVolume()).isZero())) {
              shortAvgStopPriceTmp=shortAvgStopPriceTmp == null ? childOrder.getStopPrice() : ((shortAvgStopPriceTmp.times(shortCumVolume,Remainder.ROUND_EVEN)).plus(childOrder.getUnfilledVolume().times(childOrder.getStopPrice(),Remainder.ROUND_EVEN))).divide(shortCumVolume.plus(childOrder.getUnfilledVolume()),Remainder.ROUND_EVEN);
              shortCumVolume=shortCumVolume.plus(childOrder.getUnfilledVolume());
            }
          }
        }
      }
    }
  }
  if (shortAvgStopPriceTmp == null && shortAvgStopPrice == null)   shortAvgStopPrice=DecimalAmount.ZERO;
 else   if (shortAvgStopPriceTmp != null && shortAvgStopPrice == null)   shortAvgStopPrice=shortAvgStopPriceTmp;
  return shortAvgStopPrice;
}

