public void releaseTicket(Event event,TicketReservation ticketReservation,final Ticket ticket){
  var messageSource=messageSourceManager.getMessageSourceForEvent(event);
  var category=ticketCategoryRepository.getByIdAndActive(ticket.getCategoryId(),event.getId());
  var isFree=ticket.getFinalPriceCts() == 0;
  var configurationLevel=ticket.getCategoryId() != null ? ConfigurationLevel.ticketCategory(event,ticket.getCategoryId()) : ConfigurationLevel.event(event);
  var enableFreeCancellation=configurationManager.getFor(ALLOW_FREE_TICKETS_CANCELLATION,configurationLevel).getValueAsBooleanOrDefault(false);
  var conditionsMet=CategoryEvaluator.isTicketCancellationAvailable(ticketCategoryRepository,ticket);
  if (!(isFree && enableFreeCancellation && conditionsMet)) {
    throw new IllegalStateException("Cannot release reserved tickets");
  }
  String reservationId=ticketReservation.getId();
  int result=ticketRepository.releaseTicket(reservationId,UUID.randomUUID().toString(),event.getId(),ticket.getId());
  Validate.isTrue(result == 1,String.format("Expected 1 row to be updated, got %d",result));
  if (category.isAccessRestricted() || !category.isBounded()) {
    ticketRepository.unbindTicketsFromCategory(event.getId(),category.getId(),singletonList(ticket.getId()));
  }
  Organization organization=organizationRepository.getById(event.getOrganizationId());
  Map<String,Object> model=TemplateResource.buildModelForTicketHasBeenCancelled(organization,event,ticket);
  Locale locale=LocaleUtil.forLanguageTag(Optional.ofNullable(ticket.getUserLanguage()).orElse("en"));
  notificationManager.sendSimpleEmail(event,reservationId,ticket.getEmail(),messageSource.getMessage("email-ticket-released.subject",new Object[]{event.getDisplayName()},locale),() -> templateManager.renderTemplate(event,TemplateResource.TICKET_HAS_BEEN_CANCELLED,model,locale));
  String ticketCategoryDescription=ticketCategoryDescriptionRepository.findByTicketCategoryIdAndLocale(category.getId(),ticket.getUserLanguage()).orElse("");
  List<AdditionalServiceItem> additionalServiceItems=additionalServiceItemRepository.findByReservationUuid(reservationId);
  Map<String,Object> adminModel=TemplateResource.buildModelForTicketHasBeenCancelledAdmin(organization,event,ticket,ticketCategoryDescription,additionalServiceItems,asi -> additionalServiceTextRepository.findByLocaleAndType(asi.getAdditionalServiceId(),locale.getLanguage(),AdditionalServiceText.TextType.TITLE));
  notificationManager.sendSimpleEmail(event,null,organization.getEmail(),messageSource.getMessage("email-ticket-released.admin.subject",new Object[]{ticket.getId(),event.getDisplayName()},locale),() -> templateManager.renderTemplate(event,TemplateResource.TICKET_HAS_BEEN_CANCELLED_ADMIN,adminModel,locale));
  int deletedValues=ticketFieldRepository.deleteAllValuesForTicket(ticket.getId());
  log.debug("deleting {} field values for ticket {}",deletedValues,ticket.getId());
  auditingRepository.insert(reservationId,null,event.getId(),Audit.EventType.CANCEL_TICKET,new Date(),Audit.EntityType.TICKET,Integer.toString(ticket.getId()));
  if (ticketRepository.countTicketsInReservation(reservationId) == 0 && transactionRepository.loadOptionalByReservationId(reservationId).isEmpty()) {
    removeReservation(event,ticketReservation,false,null);
    auditingRepository.insert(reservationId,null,event.getId(),Audit.EventType.CANCEL_RESERVATION,new Date(),Audit.EntityType.RESERVATION,reservationId);
  }
 else {
    extensionManager.handleTicketCancelledForEvent(event,Collections.singletonList(ticket.getUuid()));
  }
}

private void checkImport(NodeTraversal t,Node call,Node parent,ModuleMetadata currentModule,ClosureImport importType){
  boolean atTopLevelScope=t.inGlobalHoistScope() || t.inModuleScope();
  boolean isNonModule=currentModule.isGoogProvide() || currentModule.isScript();
  boolean validAssignment=!isNonModule || parent.isExprResult();
  if (!atTopLevelScope || !validAssignment) {
    t.report(call,INVALID_CLOSURE_CALL_SCOPE_ERROR);
    return;
  }
  if (!call.hasTwoChildren() || !call.getSecondChild().isString()) {
    t.report(call,INVALID_CLOSURE_IMPORT_CALL,importType.callName());
    return;
  }
  if (!isNonModule && NodeUtil.isNameDeclaration(parent.getParent())) {
    Node declaration=parent.getParent();
    if (!declaration.hasOneChild()) {
      t.report(call,ONE_CLOSURE_IMPORT_PER_DECLARATION,importType.callName());
      return;
    }
    if (importType.aliasMustBeConstant()) {
      if (declaration.isLet()) {
        t.report(call,LET_CLOSURE_IMPORT,importType.callName());
      }
 else       if (!declaration.isConst() && currentModule.isEs6Module()) {
        t.report(call,LHS_OF_CLOSURE_IMPORT_MUST_BE_CONST_IN_ES_MODULE,importType.callName());
      }
    }
    Node lhs=declaration.getFirstChild();
    if (lhs.isDestructuringLhs()) {
      if (importType.allowDestructuring()) {
        if (!isValidDestructuringImport(lhs)) {
          t.report(declaration,INVALID_CLOSURE_IMPORT_DESTRUCTURING,importType.callName());
        }
      }
 else {
        t.report(declaration,NO_CLOSURE_IMPORT_DESTRUCTURING,importType.callName());
      }
    }
 else {
      checkShortName(t,lhs,call.getLastChild().getString());
    }
  }
  String namespace=call.getSecondChild().getString();
  ModuleMetadata requiredModule=moduleMetadataMap.getModulesByGoogNamespace().get(namespace);
  if (requiredModule == null) {
    if (importType == ClosureImport.FORWARD_DECLARE && isNonModule) {
      return;
    }
    t.report(call,MISSING_MODULE_OR_PROVIDE,namespace);
  }
 else   if (importType.mustBeOrdered() && !namespacesSeen.contains(namespace)) {
    t.report(call,LATE_PROVIDE_ERROR,namespace);
  }
  if (importType == ClosureImport.REQUIRE && requiredModule != null && currentModule.isEs6Module() && requiredModule.isEs6Module()) {
    t.report(call,Es6RewriteModules.SHOULD_IMPORT_ES6_MODULE);
  }
}

public int read(final char cbuf[],final int off,final int len) throws IOException {
  if ((pos < 0) || ((pos >= blocksCount) && (current == null))) {
    return -1;
  }
  int l=len;
  int o=off;
  while (l > 0) {
    if (current == null) {
      if (pos < blocksCount) {
        current=content.get(pos).open();
        pos++;
      }
 else {
        return ((len - l) <= 0) ? (-1) : (len - l);
      }
    }
 else {
      final int r=current.read(cbuf,o,l);
      if (r <= 0) {
        current.close();
        current=null;
      }
 else       if (r <= l) {
        l-=r;
        o+=r;
      }
    }
  }
  return len - l;
}

