/** 
 * Skips contiguous spaces, tabs, and newlines from the source starting at startPosition and continuing until the end of the spaces/tabs.
 * @param startPosition starting position in source
 */
private int getFirstNonspacePositionOnNextLine(int startPosition){
  int position;
  for (position=startPosition; true; ++position) {
    int currChar=getSourceCharAt(position);
    if (!(currChar == ' ' || currChar == '\t' || currChar == '\r' || currChar == '\n'))     break;
  }
  return position;
}

