  IIcon canisterIcon=canister.getIconFromDamage(0);
  GL11.glPushMatrix();
  GL11.glEnable(GL11.GL_ALPHA_TEST);
  if (type.equals(ItemRenderType.EQUIPPED)) {
    GL11.glRotated(180,0,0,1);
    GL11.glTranslated(-1,-1,0);
