  }
  Minecraft.getMinecraft().renderEngine.bindTexture(RenderUtils.MC_ITEM_SHEET);
  if (type.equals(ItemRenderType.INVENTORY))   renderIcon(canisterIcon,0);
 else   ItemRenderer.renderItemIn2D(Tessellator.instance,canisterIcon.getMinU(),canisterIcon.getMaxV(),canisterIcon.getMaxU(),canisterIcon.getMinV(),canisterIcon.getIconWidth(),canisterIcon.getIconHeight(),0.0625F);
