 */
@Override public void handleRequest(HttpServerExchange exchange,RequestContext context) throws Exception {
  if (context.isInError() || context.isTxn() || context.isTxns()) {
    next(exchange,context);
    return;
  }
  String dbName=context.getDBName();
  String collName=context.getCollectionName();
  if (dbName != null && collName != null && !context.isDbMeta()) {
    BsonDocument collProps;
    if (!LocalCachesSingleton.isEnabled() || context.getClientSession() != null) {
      collProps=getDatabase().getCollectionProperties(context.getClientSession(),dbName,collName);
    }
 else {
      collProps=LocalCachesSingleton.getInstance().getCollectionProperties(dbName,collName);
    }
    if (collProps == null && checkCollection(context)) {
      doesNotExists(context,exchange);
      return;
    }
    if (collProps == null && context.getMethod() == RequestContext.METHOD.GET) {
      collProps=new BsonDocument("_id",new BsonString(collName));
    }
    context.setCollectionProps(collProps);
  }
  getNext().handleRequest(exchange,context);
}

/** 
 * Checks if the question contains a predicate that can be labeled.
 * @param qn normalized question string
 * @return <code>true</code> iff the question contains a predicate
 */
private static boolean containsPredicate(String qn){
  String[] tokens=OpenNLP.tokenize(qn);
  String[] pos=OpenNLP.tagPos(tokens);
  String[] chunks=OpenNLP.tagChunks(tokens,pos);
  for (int i=0; i < tokens.length; i++)   if ((pos[i].startsWith("VB") || chunks[i].endsWith("-VP")) && !(tokens[i].matches(BE_P) || tokens[i].matches(DO_P) || tokens[i].matches(HAVE_P)|| tokens[i].matches(IGNORE_P)))   return true;
  return false;
}

