public boolean isInternalAPI(){
  if (_internalAPI == null) {
    if (ILanguageLevel.Util.STANDARD_GOSU() || Arrays.stream(notInternalNs).noneMatch(ns -> getOwnersType() != null && getOwnersType().getNamespace() != null && getOwnersType().getNamespace().startsWith(ns)) && Arrays.stream(notInternalNs).noneMatch(ns -> getOwnersType() != null && getOwnersType().getNamespace() != null && getOwnersType().getNamespace().startsWith(IGosuClass.PROXY_PREFIX + '.' + ns))) {
      return _internalAPI=false;
    }
    TypeSystem.lock();
    try {
      if (_internalAPI == null) {
        _internalAPI=!getAnnotationsOfType(JavaTypes.INTERNAL_API()).isEmpty();
      }
      assert _internalAPI != null;
    }
  finally {
      TypeSystem.unlock();
    }
  }
  return _internalAPI;
}

