/** 
 * Create the appropriate object for JSON output. This needs to be a Boolean, Integer or Double for those data types so that the ObjectMapper knows how to format the JSON text. For objects implementing stringValue we use that string. for XPathExpressions use the Path. Otherwise default to using toString.
 * @param obj
 * @return
 */
private static Object jsonOutputObject(Object obj,AttributeValue<?> attrValue) throws JSONStructureException {
  if (obj instanceof String || obj instanceof Boolean || obj instanceof BigInteger) {
    return obj;
  }
 else   if (obj instanceof Double) {
    Double d=(Double)obj;
    if (d == Double.NaN) {
      return "NaN";
    }
 else     if (d == Double.POSITIVE_INFINITY) {
      return "INF";
    }
 else     if (d == Double.NEGATIVE_INFINITY) {
      return "-INF";
