/** 
 * Blur and transpose a block of ARGB pixels.
 * @param kernel the blur kernel
 * @param inPixels the input pixels
 * @param outPixels the output pixels
 * @param width the width of the pixel array
 * @param height the height of the pixel array
 * @param alpha whether to blur the alpha channel
 * @param edgeAction what to do at the edges
 */
public static void convolveAndTranspose(Kernel kernel,int[] inPixels,int[] outPixels,int width,int height,boolean alpha,boolean premultiply,boolean unpremultiply,int edgeAction){
  float[] matrix=kernel.getKernelData(null);
  int cols=kernel.getWidth();
  int cols2=cols / 2;
  for (int y=0; y < height; y++) {
    int index=y;
    int ioffset=y * width;
    for (int x=0; x < width; x++) {
      float r=0, g=0, b=0, a=0;
      int moffset=cols2;
      for (int col=-cols2; col <= cols2; col++) {
        float f=matrix[moffset + col];
        if (f != 0) {
          int ix=x + col;
          if (ix < 0) {
            if (edgeAction == CLAMP_EDGES)             ix=0;
 else             if (edgeAction == WRAP_EDGES)             ix=(x + width) % width;
          }
 else           if (ix >= width) {
            if (edgeAction == CLAMP_EDGES)             ix=width - 1;
 else             if (edgeAction == WRAP_EDGES)             ix=(x + width) % width;
          }
          int rgb=inPixels[ioffset + ix];
          int pa=(rgb >> 24) & 0xff;
          int pr=(rgb >> 16) & 0xff;
          int pg=(rgb >> 8) & 0xff;
          int pb=rgb & 0xff;
          if (premultiply) {
            float a255=pa * (1.0f / 255.0f);
            pr*=a255;
            pg*=a255;
            pb*=a255;
          }
          a+=f * pa;
          r+=f * pr;
          g+=f * pg;
          b+=f * pb;
        }
      }
      if (unpremultiply && a != 0 && a != 255) {
        float f=255.0f / a;
        r*=f;
        g*=f;
        b*=f;
      }
      int ia=alpha ? PixelUtils.clamp((int)(a + 0.5)) : 0xff;
      int ir=PixelUtils.clamp((int)(r + 0.5));
      int ig=PixelUtils.clamp((int)(g + 0.5));
      int ib=PixelUtils.clamp((int)(b + 0.5));
      outPixels[index]=(ia << 24) | (ir << 16) | (ig << 8)| ib;
      index+=height;
    }
  }
}

/** 
 * @param attrs - comma separated attr=value pairs. If specified attr= then attr will be removed.
 */
public static void setAttributes(Element elt,String attrs){
  if (elt == null || attrs == null || attrs.isEmpty())   return;
  String[] arr=attrs.split(",");
  for (  String i : arr) {
    String s=i.trim();
    if (s.isEmpty())     continue;
    int p=s.indexOf('=');
    if (p == -1)     continue;
    String attr=s.substring(0,p).trim();
    if (attr.isEmpty())     continue;
    String val=s.substring(p + 1).trim();
    if (val.isEmpty())     elt.removeAttribute(attr);
 else     elt.setAttribute(attr,val);
  }
}

