public static int getPrimitiveTypeForNewArray(IRType atomicType){
  if (atomicType.isByte()) {
    return Opcodes.T_BYTE;
  }
  if (atomicType.isChar()) {
    return Opcodes.T_CHAR;
  }
  if (atomicType.isBoolean()) {
    return Opcodes.T_BOOLEAN;
  }
  if (atomicType.isShort()) {
    return Opcodes.T_SHORT;
  }
  if (atomicType.isInt()) {
    return Opcodes.T_INT;
  }
  if (atomicType.isLong()) {
    return Opcodes.T_LONG;
  }
  if (atomicType.isFloat()) {
    return Opcodes.T_FLOAT;
  }
  if (atomicType.isDouble()) {
    return Opcodes.T_DOUBLE;
  }
  throw new IllegalStateException("Unhandled primitive type: " + atomicType.getName());
}

/** 
 * Import xml.
 * @param is the input stream containing the XML
 * @throws Exception the exception
 */
@Override public void importXml(InputStream is) throws Exception {
  JAXBContext jc=JAXBContext.newInstance(XmlContainer.class);
  Unmarshaller u=jc.createUnmarshaller();
  XmlContainer container=(XmlContainer)u.unmarshal(is);
  if (container.Appointment == null)   return;
  try {
    int nextkey=db_.nextkey();
    boolean use_keys=(nextkey == 1) ? true : false;
    for (    Appointment appt : container.Appointment) {
      if (!use_keys)       appt.setKey(nextkey++);
      if (appt.getPriority() != null && (appt.getPriority() > 10 || appt.getPriority() < 1)) {
        appt.setPriority(null);
        log.warning("XML Import: Ignoring invalid priority for appointment: " + appt.getKey() + ":"+ appt.getClearText());
      }
      if (appt.getCreateTime() == null)       appt.setCreateTime(new Date());
      if (appt.getLastMod() == null)       appt.setLastMod(new Date());
      db_.addObj(appt);
    }
  }
 catch (  Exception e) {
    Errmsg.getErrorHandler().notice(e + "\n" + Resource.getResourceString("Import_XML_error"));
    e.printStackTrace();
  }
  buildMap();
  CategoryModel.getReference().sync();
  refreshListeners();
}

