public void handleFill(Fill fill){
  log.debug(this.getClass().getSimpleName() + " : handleFill " + fill+ " to called from stack "+ Thread.currentThread().getStackTrace()[2]);
  SpecificOrder order=fill.getOrder();
  log.debug("handleFill: Updating position for fill" + fill);
  try {
    fill.getPortfolio().merge(fill);
  }
 catch (  Throwable t) {
    fill.persit();
    log.debug("error",t);
    throw t;
  }
  if (fill.getPositionEffect() == PositionEffect.CLOSE)   if (log.isInfoEnabled())   log.info("Received Fill " + fill);
  OrderState state=orderStateMap.get(order);
  if (state == null) {
    log.warn("Untracked order " + order);
    state=OrderState.PLACED;
  }
  if (state == (OrderState.NEW))   log.warn("Fill received for Order in NEW state: skipping PLACED state");
  if (state.isOpen()) {
    OrderState newState;
    if (order.isFilled()) {
      PositionType newFillState=((fill.getVolumeCount() == 0 ? PositionType.FLAT : (fill.getVolumeCount() > 0 ? PositionType.LONG : PositionType.SHORT)));
      fill.setPositionType(newFillState);
      if (order.getParentFill() != null && (order.getVolume().compareTo(order.getParentFill().getVolume().negate()) == 0))       order.getParentFill().setPositionType(PositionType.FLAT);
      newState=OrderState.FILLED;
    }
 else     newState=OrderState.PARTFILLED;
    updateOrderState(order,newState,true);
  }
  log.debug("handleFill: Updated position for fill " + fill);
  FillType fillType=null;
  ContingencyType contingencyType=null;
  List<Order> allChildOrders=new ArrayList<Order>();
  if (order.getParentOrder() != null || (order.getOrderChildren() != null && !order.getOrderChildren().isEmpty())) {
    fillType=order.getFillType();
    if (fillType == null)     fillType=(order.getParentOrder() != null) ? order.getParentOrder().getFillType() : order.getFillType();
switch (fillType) {
case GOOD_TIL_CANCELLED:
      break;
case GTC_OR_MARGIN_CAP:
    break;
case CANCEL_REMAINDER:
  break;
case LIMIT:
break;
case TRAILING_STOP_LIMIT:
case TRAILING_UNREALISED_STOP_LIMIT:
case STOP_LIMIT:
break;
case STOP_LOSS:
break;
case TRAILING_STOP_LOSS:
break;
default :
break;
}
contingencyType=order.getContingencyType();
if (contingencyType == null) contingencyType=(order.getParentOrder() != null) ? order.getParentOrder().getContingencyType() : order.getContingencyType();
switch (contingencyType) {
case ONE_CANCELS_OTHER:
SpecificOrder otherOrder;
GeneralOrder otherGeneralOrder;
if (order.getParentOrder() != null) for (Order pairOrder : order.getParentOrder().getOrderChildren()) {
if (pairOrder instanceof SpecificOrder && !pairOrder.equals(order)) {
otherOrder=(SpecificOrder)pairOrder;
if (getOrderState(otherOrder).isOpen()) try {
if (handleCancelSpecificOrder(otherOrder)) log.info("handleFill cancelled Specific otherOrder:" + otherOrder + " parent order: "+ order.getParentOrder());
 else log.info("handleFill ubale to cancel Specific otherOrder:" + otherOrder + " parent order: "+ order.getParentOrder());
}
 catch (OrderNotFoundException onfe) {
log.info("Order Not Found:" + otherOrder);
}
catch (Exception|Error e) {
log.info("cancel specifc order " + otherOrder + ". Full stack trace",e);
throw e;
}
}
if (pairOrder instanceof GeneralOrder && !pairOrder.equals(order)) {
otherGeneralOrder=(GeneralOrder)pairOrder;
if (getOrderState(otherGeneralOrder).isOpen()) try {
if (handleCancelGeneralOrder(otherGeneralOrder)) log.info("handleFill cancelled otherGeneralOrder: " + otherGeneralOrder + " parent order: "+ order.getParentOrder());
 else log.info("handleFill ubale to otherGeneralOrder: " + otherGeneralOrder + " parent order: "+ order.getParentOrder());
}
 catch (OrderNotFoundException onfe) {
log.info("Order Not Found:" + otherGeneralOrder);
}
catch (IllegalStateException onfe) {
log.info("Order Not Placed:" + otherGeneralOrder);
}
catch (Exception|Error e) {
log.info("cancel general order " + otherGeneralOrder + ". Full stack trace",e);
throw e;
}
}
if (order.getParentOrder().getParentOrder() != null) for (Order childPairOrder : order.getParentOrder().getParentOrder().getOrderChildren()) {
if (childPairOrder instanceof SpecificOrder && childPairOrder != order) {
otherOrder=(SpecificOrder)childPairOrder;
if (getOrderState(otherOrder).isOpen()) try {
if (handleCancelSpecificOrder(otherOrder)) log.info("handleFill cancelled specific otherOrder Order: " + otherOrder + " parent order: "+ order.getParentOrder().getParentOrder());
 else log.info("handleFill ubale to cancel specific otherOrder Order: " + otherOrder + " parent order: "+ order.getParentOrder().getParentOrder());
}
 catch (OrderNotFoundException onfe) {
log.info("Order Not Found:" + otherOrder);
}
catch (Exception|Error e) {
log.info("cancel spceific order " + otherOrder + ". Full stack trace",e);
throw e;
}
}
if (childPairOrder instanceof GeneralOrder && childPairOrder != order.getParentOrder()) {
otherGeneralOrder=(GeneralOrder)childPairOrder;
if (getOrderState(childPairOrder).isOpen()) try {
if (handleCancelGeneralOrder(otherGeneralOrder)) log.info("handleFill cancelled general otherGeneralOrder Order: " + otherGeneralOrder + ".");
 else log.info("handleFill ubale to cancel general otherGeneralOrder Order: " + otherGeneralOrder + ".");
}
 catch (OrderNotFoundException onfe) {
log.info("Order Not Found:" + otherGeneralOrder);
}
catch (Exception|Error e) {
log.info("cancel general order " + otherGeneralOrder + ". Full stack trace",e);
throw e;
}
}
}
break;
}
break;
default :
break;
}
}
GeneralOrder stopOrder=buildStopLimitOrder(fill);
GeneralOrder targetOrder=buildReentrantLimitOrder(fill);
if (stopOrder != null && order.getPositionEffect() == (PositionEffect.OPEN)) {
try {
placeOrder(stopOrder);
log.info("Placed Stop order " + stopOrder);
}
 catch (Throwable e) {
log.info("Unable to place Stop order " + stopOrder + ". Full stack trace",e);
}
}
if (targetOrder != null && order.getPositionEffect() == (PositionEffect.CLOSE)) {
try {
placeOrder(targetOrder);
log.info("Placed Target order " + targetOrder);
}
 catch (Throwable e) {
log.info("Unable to place Target order " + targetOrder + ". Full stack trace",e);
}
}
context.route(fill);
CreateTransaction(fill,true);
}

