@Test public void testEqualsObject(){
  final List<Element> objs1=new ArrayList<Element>();
  final List<Element> objs2=new ArrayList<Element>();
  for (  final String name : Arrays.asList("1","foo","bar","baz","2")) {
    for (    final String code : Arrays.asList("1","foo","bar","baz","2")) {
      objs1.add(new RegularExpressionElement(name,code,OPTIONS_1.toLowerCase()));
      objs2.add(new RegularExpressionElement(name,code,OPTIONS_1.toUpperCase()));
      objs1.add(new RegularExpressionElement(name,code,OPTIONS_2.toLowerCase()));
      objs2.add(new RegularExpressionElement(name,code,OPTIONS_2.toUpperCase()));
      objs1.add(new RegularExpressionElement(name,code,14));
      objs2.add(new RegularExpressionElement(name,code,14));
      objs1.add(new RegularExpressionElement(name,code,null));
      objs2.add(new RegularExpressionElement(name,code,null));
    }
  }
  assertEquals(objs1.size(),objs2.size());
  for (int i=0; i < objs1.size(); ++i) {
    final Element obj1=objs1.get(i);
    Element obj2=objs2.get(i);
    assertTrue(obj1.equals(obj1));
    assertNotSame(obj1,obj2);
    assertEquals(obj1,obj2);
    assertEquals(obj1.hashCode(),obj2.hashCode());
    for (int j=i + 1; j < objs1.size(); ++j) {
      obj2=objs2.get(j);
      assertFalse(obj1.equals(obj2));
      assertFalse(obj1.hashCode() == obj2.hashCode());
    }
    assertFalse(obj1.equals("foo"));
    assertFalse(obj1.equals(null));
    assertFalse(obj1.equals(new MaxKeyElement(obj1.getName())));
  }
}

public abstract boolean nextScript(String message);
public void nextScript(){
synchronized (synch) {
    if (command != null && !isClose() && running) {
      for (; isRunning=command.next(); ) {
        String result=command.doExecute();
        if (result == null) {
          continue;
        }
        if (!nextScript(result)) {
          break;
        }
        List<?> commands=Command.splitToList(result," ");
        int size=commands.size();
        String cmdFlag=(String)commands.get(0);
        String mesFlag=null, orderFlag=null, lastFlag=null;
        if (size == 2) {
          mesFlag=(String)commands.get(1);
        }
 else         if (size == 3) {
          mesFlag=(String)commands.get(1);
          orderFlag=(String)commands.get(2);
        }
 else         if (size == 4) {
          mesFlag=(String)commands.get(1);
          orderFlag=(String)commands.get(2);
          lastFlag=(String)commands.get(3);
        }
        if (cmdFlag.equalsIgnoreCase(CommandType.L_WAIT)) {
          scrFlag=true;
          break;
        }
        if (cmdFlag.equalsIgnoreCase(CommandType.L_SNOWSTOP) || cmdFlag.equalsIgnoreCase(CommandType.L_RAINSTOP) || cmdFlag.equalsIgnoreCase(CommandType.L_PETALSTOP)) {
