/** 
 * Returns whether the given  {@link MaterialData} and the given {@link BlockStateData} are validfor the given block type and describe the same state.
 * @param type the block type, or null
 * @param data the block state that's a {@link MaterialData}, or null
 * @param state the block state that's a {@link BlockStateData}, or null
 * @return true if all parameters are non-null, {@code data} is valid for {@code type}, and {@code state} is empty or matches {@code data}; false otherwise
 * @throws InvalidBlockStateException if {@code type} is not null but isn't a block type with a{@link BlockStateReader}
 */
public static boolean matches(Material type,MaterialData data,BlockStateData state) throws InvalidBlockStateException {
  if (state == null || data == null || data.getItemType() != type) {
    return false;
  }
  if (state.isEmpty()) {
    return true;
  }
  BlockStateReader reader=getReader(type);
  if (reader == null) {
    return false;
  }
  return reader.matches(state,data);
}

