@Override public Object invoke(final Object proxy,final Method method,final Object[] args) throws Throwable {
  if (method.getName().startsWith("get")) {
    return structuredHandler.invoke(proxy,method,args);
  }
 else   if (method.getName().startsWith("set")) {
    return structuredHandler.invoke(proxy,method,args);
  }
 else   if ("filter".equals(method.getName()) || "orderBy".equals(method.getName()) || "top".equals(method.getName())|| "skip".equals(method.getName())|| "expand".equals(method.getName())|| "select".equals(method.getName())) {
    return super.invoke(proxy,method,args);
  }
 else   if ("operations".equals(method.getName()) && ArrayUtils.isEmpty(args)) {
    return super.invoke(proxy,method,args);
  }
 else   if (isSelfMethod(method)) {
    return invokeSelfMethod(method,args);
  }
 else {
    throw new NoSuchMethodException(method.getName());
  }
}

