 * @throws UWSException	If the given user is not allowed to read the contentof this jobs list or to read the specified job.
 */
public UWSJob getJob(String jobID,JobOwner user) throws UWSException {
  if (user != null && !user.hasReadPermission(this))   throw new UWSException(UWSException.PERMISSION_DENIED,UWSExceptionFactory.readPermissionDenied(user,true,getName()));
  UWSJob job=jobsList.get(jobID);
  if (user != null && job != null && job.getOwner() != null) {
    JobOwner owner=job.getOwner();
    if (!owner.equals(user) && !user.hasReadPermission(job))     throw new UWSException(UWSException.PERMISSION_DENIED,UWSExceptionFactory.readPermissionDenied(user,false,job.getJobId()));
  }
  return job;
}

