public static Double toDouble(Object o){
  if (o == null) {
    return null;
  }
  Class<?> cls=o.getClass();
  if (isFloatingPoint(cls) || isInteger(cls)) {
    return ((Number)o).doubleValue();
  }
  if (Color.class.isInstance(o)) {
    int i=((Color)o).getRGB();
    return (double)i;
  }
  if (Boolean.class.isInstance(o)) {
    return ((Boolean)o) ? 1.0 : 0.0;
  }
  if (Number.class.isInstance(o)) {
    return ((Number)o).doubleValue();
  }
  if (LocalDate.class.isInstance(o)) {
    return (double)((LocalDate)o).toEpochDay();
  }
  String s=o.toString().toLowerCase().trim();
  if (s.equals("true") || s.equals("yes") || s.equals("vrai")) {
    return 1.0;
  }
  if (s.equals("false") || s.equals("no") || s.equals("faux")) {
    return 0.0;
  }
  if (Strings.isNumber(s)) {
    try {
      return Double.parseDouble(s);
    }
 catch (    Throwable e) {
    }
  }
  return null;
}

private boolean appliesToElementType(IGosuAnnotation anno,ElementType elemType){
  IAnnotationInfo annotation=anno.getType().getTypeInfo().getAnnotation(JavaTypes.TARGET());
  if (annotation == null) {
    return true;
  }
  Object targetValue=annotation.getFieldValue("value");
  if (targetValue == elemType || targetValue instanceof String && targetValue.equals(elemType.name())) {
    return true;
  }
 else   if (targetValue instanceof Object[]) {
    Object[] values=(Object[])targetValue;
    if (values == null || values.length == 0) {
      return true;
    }
    for (    Object value : values) {
      if (value == elemType || value.equals(elemType.name())) {
        return true;
      }
    }
  }
  return false;
}

public IImportFragment parseImportFragment() throws OperationCancellation {
  ProtoDefSymbol aliasId=null;
  IImportFragment fragment;
  if (lookAhead() == DeeTokens.IDENTIFIER && lookAhead(1) == DeeTokens.ASSIGN || lookAhead() == DeeTokens.ASSIGN) {
    aliasId=parseDefId();
    ParseHelper parse=new ParseHelper(aliasId.getStartPos());
    consumeLookAhead(DeeTokens.ASSIGN);
    RefModule refModule=parseRefModule();
    fragment=parse.conclude(new ImportAlias(aliasId.createDefId(),refModule));
  }
 else {
    RefModule refModule=parseRefModule();
    fragment=conclude(srOf(refModule,new ImportContent(refModule)));
  }
  if (tryConsume(DeeTokens.COLON)) {
    return parseSelectiveModuleImport(fragment);
  }
  return fragment;
}

