@Nullable private static ExternalLintAnnotationInput collectInformation(@NotNull PsiFile psiFile,@Nullable Editor editor){
  if (psiFile.getContext() != null) {
    return null;
  }
  VirtualFile virtualFile=psiFile.getVirtualFile();
  if (virtualFile == null || !virtualFile.isInLocalFileSystem()) {
    return null;
  }
  if (psiFile.getViewProvider() instanceof MultiplePsiFilesPerDocumentFileViewProvider) {
    return null;
  }
  Project project=psiFile.getProject();
  ESLintProjectComponent component=project.getComponent(ESLintProjectComponent.class);
  if (!component.isSettingsValid() || !component.isEnabled() || !isJavaScriptFile(psiFile,component.ext)) {
    return null;
  }
  Document document=PsiDocumentManager.getInstance(project).getDocument(psiFile);
  if (document == null) {
    return null;
  }
  String fileContent=document.getText();
  if (StringUtil.isEmptyOrSpaces(fileContent)) {
    return null;
  }
  EditorColorsScheme colorsScheme=editor == null ? null : editor.getColorsScheme();
  return new ExternalLintAnnotationInput(project,psiFile,fileContent,colorsScheme);
}

@Override protected void service(HttpServletRequest req,HttpServletResponse resp) throws ServletException, IOException {
  String t=req.getParameter("timeout");
  if (t != null && t.matches("\\d+")) {
    try {
      int ms=Integer.parseInt(t);
      System.out.println(name + "sleeping: " + ms);
      Thread.sleep(ms);
    }
 catch (    Exception e) {
    }
    return;
  }
  String data="";
  if (req.getMethod().equalsIgnoreCase("get")) {
    data=req.getParameter("data") != null ? req.getParameter("data") : "";
    if (req.getParameter("callback") != null) {
      data=req.getParameter("callback") + "(" + data+ ");";
    }
  }
 else   if (req.getMethod().equalsIgnoreCase("post") && req.getContentType() != null && req.getContentType().toLowerCase().startsWith(Ajax.JSON_CONTENT_TYPE)) {
    BufferedReader reader=req.getReader();
    String line;
    while ((line=reader.readLine()) != null) {
      data+=line;
    }
  }
  String origin=req.getHeader("Origin");
  if ("true".equals(req.getParameter("cors")) && origin != null) {
    resp.addHeader("Access-Control-Allow-Origin",origin);
    if ("true".equals(req.getParameter("credentials"))) {
      resp.addHeader("Access-Control-Allow-Credentials","true");
    }
    String method=req.getHeader("Access-Control-Request-Method");
    if (method != null) {
      resp.addHeader("Access-Control-Allow-Methods",method);
      resp.setHeader("Allow","GET, HEAD, POST, PUT, DELETE, TRACE, OPTIONS");
    }
    String headers=req.getHeader("Access-Control-Request-Headers");
    if (headers != null) {
      resp.addHeader("Access-Control-Allow-Headers",headers);
    }
  }
  PrintWriter p=resp.getWriter();
  p.print(data);
  p.flush();
  p.close();
  System.out.println(name + "returns: " + data);
}

