/** 
 * Checks if a characters transition with the given parameters would be valid.
 */
public ValidationResult checkCharacters(String characters,ViolationCollector v){
  if (characters == null) {
    return nullCharacters(v);
  }
  if (characters.length() == 0) {
    return emptyCharacters(v);
  }
  if (topOfStackIsDeletion()) {
    return insertInsideDelete(v);
  }
  String enclosingTag=effectiveEnclosingElementTag();
  if (!tagAllowsText(enclosingTag)) {
    return textNotAllowedInElement(v,enclosingTag);
  }
  if (!canIncreaseLength(characters.length())) {
    return tooLong(v);
  }
  return valid();
}

