/** 
 * Accessor for the absolute positions of fields/properties that are considered basic. This category includes members of all basic (primitive and immutable object class) types as defined in section 6.4 of the specification, including String, Date and its jdbc subtypes, Locale, Currency, and Enum types. Includes all inherited multivalued positions. WARNING : this includes transient fields. DO NOT USE as a way of getting the persistent fields in the class.
 * @param clr ClassLoader resolver
 * @return The absolute positions
 */
public int[] getBasicMemberPositions(ClassLoaderResolver clr){
  Iterator<AbstractMemberMetaData> iter=members.iterator();
  int numBasics=0;
  while (iter.hasNext()) {
    AbstractMemberMetaData mmd=iter.next();
    if (mmd.getRelationType(clr) == RelationType.NONE && !mmd.isPersistentInterface(clr) && !Collection.class.isAssignableFrom(mmd.getType()) && !Map.class.isAssignableFrom(mmd.getType()) && !mmd.getType().isArray()) {
      numBasics++;
    }
  }
  int[] inheritedBasicPositions=null;
  if (pcSuperclassMetaData != null) {
    inheritedBasicPositions=pcSuperclassMetaData.getBasicMemberPositions(clr);
  }
  int[] basicPositions=new int[numBasics + (inheritedBasicPositions != null ? inheritedBasicPositions.length : 0)];
  int number=0;
  if (inheritedBasicPositions != null) {
    for (int i=0; i < inheritedBasicPositions.length; i++) {
      basicPositions[number++]=inheritedBasicPositions[i];
    }
  }
  iter=members.iterator();
  while (iter.hasNext()) {
    AbstractMemberMetaData mmd=iter.next();
    if (mmd.getRelationType(clr) == RelationType.NONE && !mmd.isPersistentInterface(clr) && !Collection.class.isAssignableFrom(mmd.getType()) && !Map.class.isAssignableFrom(mmd.getType()) && !mmd.getType().isArray()) {
      basicPositions[number++]=mmd.getAbsoluteFieldNumber();
    }
  }
  return basicPositions;
}

