public byte process(APDU apdu) throws ISOException {
  byte bProcessed=0;
  byte[] apduBuffer=apdu.getBuffer();
  if (apduBuffer[ISO7816.OFFSET_CLA] == Consts.CLA_CARD_ALGTEST) {
    bProcessed=1;
switch (apduBuffer[ISO7816.OFFSET_INS]) {
case Consts.INS_PREPARE_CIPHERENGINE:
      PrepareRSAEngine(apdu);
    break;
case Consts.INS_CARD_GETRSAKEY:
  GetRSAKey(apdu);
break;
case Consts.INS_CARD_GETRANDOMDATA:
GetRandomData(apdu);
break;
default :
{
bProcessed=0;
break;
}
}
}
return bProcessed;
}

