public static void checkMethod(IMethod method,MarkerList markers,IClass checkedClass,ITypeContext typeContext){
  if (method.hasModifier(Modifiers.STATIC_FINAL)) {
    return;
  }
  if (checkedClass.checkImplements(method,typeContext)) {
    return;
  }
  if (method.isAbstract() && !checkedClass.isAbstract() && !checkedClass.hasModifier(Modifiers.EXTENSION)) {
    markers.add(Markers.semantic(checkedClass.getPosition(),"class.method.abstract",checkedClass.getName(),method.getName(),method.getEnclosingClass().getName()));
  }
}

/** 
