static protected void copyFiles(Path srcf,Path destf,FileSystem fs) throws HiveException {
  if (!checkPathDomain(srcf,fs)) {
    throw new HiveException("Invalid path: srcf=" + srcf + ", fs="+ (fs == null ? null : fs.getUri()));
  }
  try {
    if (!fs.exists(destf))     fs.mkdirs(destf);
  }
 catch (  IOException e) {
    throw new HiveException("copyFiles: error while checking/creating destination directory!!!",e);
  }
  FileStatus[] srcs;
  try {
    srcs=fs.globStatus(srcf);
  }
 catch (  IOException e) {
    LOG.error(StringUtils.stringifyException(e));
    throw new HiveException("addFiles: filesystem error in check phase",e);
  }
  if (srcs == null) {
    LOG.info("No sources specified to move: " + srcf);
    if (SessionState.get() != null)     SessionState.get().ssLog("No sources specified to move: " + srcf);
    return;
  }
  checkPaths(fs,srcs,destf,false);
  try {
    for (int i=0; i < srcs.length; i++) {
      copyDir(srcs[i].getPath(),destf,fs);
    }
  }
 catch (  IOException e) {
    throw new HiveException("copyFiles: error while moving files!!!",e);
  }
  Connection cc=null;
  SessionState ss=SessionState.get();
  try {
    if (ss != null && ss.getBIStore() != null && ss.getTdw_query_info() != null) {
      cc=ss.getBIStore().openConnect();
      if (cc != null) {
        ss.getBIStore().insertMoveInfo(cc,ss.getTdw_query_info().getQueryId(),srcf.toString(),destf.toString(),ss.getTbName(),ss.getDbName(),ss.getTdw_query_info().getTaskid());
        ss.getBIStore().closeConnect(cc);
      }
 else {
        LOG.error("record move operation into BI failed: " + ss.getTdw_query_info().getQueryId());
      }
    }
  }
 catch (  Exception e) {
    ss.getBIStore().closeConnect(cc);
    LOG.error("record move operation into BI failed: " + ss.getCurrnetQueryId());
    e.printStackTrace();
  }
}

