/** 
 * An operator for mapping multiple table names in the Encryption Context to a new table name. If the table name for a given EncryptionContext is missing, then it returns the original EncryptionContext. Similarly, it returns the original EncryptionContext if the value it is overridden to is null, or if the original table name is null.
 * @param tableNameOverrideMap a map specifying the names of tables that should be overridden,and the values to which they should be overridden. If the given table name corresponds to null, or isn't in the map, then the table name won't be overridden.
 * @return A UnaryOperator that produces a new EncryptionContext with the supplied table name
 */
public static UnaryOperator<EncryptionContext> overrideEncryptionContextTableNameUsingMap(Map<String,String> tableNameOverrideMap){
  return encryptionContext -> {
    if (tableNameOverrideMap == null || encryptionContext == null || encryptionContext.getTableName() == null) {
      return encryptionContext;
    }
    String newTableName=tableNameOverrideMap.get(encryptionContext.getTableName());
    if (newTableName != null) {
      return new EncryptionContext.Builder(encryptionContext).withTableName(newTableName).build();
    }
 else {
      return encryptionContext;
    }
  }
;
}

