public static String getVersionControlRoot(File dir){
  while (dir != null) {
    for (    final File entry : dir.listFiles()) {
      String name=entry.getName();
      if (name.equals(".git") || name.equals(".hg") || name.equals(".svn")) {
        return dir.getPath();
      }
    }
    dir=dir.getParentFile();
  }
  return null;
}

