@Override public List<Polygon> toPolygons(){
  final Vector3d s=getStart();
  Vector3d e=getEnd();
  final Vector3d ray=e.minus(s);
  final Vector3d axisZ=ray.normalized();
  boolean isY=(Math.abs(axisZ.y()) > 0.5);
  final Vector3d axisX=Vector3d.xyz(isY ? 1 : 0,!isY ? 1 : 0,0).crossed(axisZ).normalized();
  final Vector3d axisY=axisX.crossed(axisZ).normalized();
  Vertex startV=new Vertex(s,axisZ.negated());
  Vertex endV=new Vertex(e,axisZ.normalized());
  List<Polygon> polygons=new ArrayList<>();
  for (int i=0; i < numSlices; i++) {
    double t0=i / (double)numSlices, t1=(i + 1) / (double)numSlices;
    polygons.add(new Polygon(Arrays.asList(startV,cylPoint(axisX,axisY,axisZ,ray,s,startRadius,0,t0,-1),cylPoint(axisX,axisY,axisZ,ray,s,startRadius,0,t1,-1)),properties));
    polygons.add(new Polygon(Arrays.asList(cylPoint(axisX,axisY,axisZ,ray,s,startRadius,0,t1,0),cylPoint(axisX,axisY,axisZ,ray,s,startRadius,0,t0,0),cylPoint(axisX,axisY,axisZ,ray,s,endRadius,1,t0,0),cylPoint(axisX,axisY,axisZ,ray,s,endRadius,1,t1,0)),properties));
    polygons.add(new Polygon(Arrays.asList(endV,cylPoint(axisX,axisY,axisZ,ray,s,endRadius,1,t1,1),cylPoint(axisX,axisY,axisZ,ray,s,endRadius,1,t0,1)),properties));
  }
  return polygons;
}

/** 
 * Produce a copy of a string in which the characters '+', '%', '=', ';' and control characters are replaced with "%hh". This is a gentle form of URL encoding, attempting to cause as little distortion to the string as possible. The characters '=' and ';' are meta characters in cookies. By convention, they are escaped using the URL-encoding. This is only a convention, not a standard. Often, cookies are expected to have encoded values. We encode '=' and ';' because we must. We encode '%' and '+' because they are meta characters in URL encoding.
 * @param string The source string.
 * @return       The escaped result.
 */
public static String escape(String string){
  char c;
  String s=string.trim();
  StringBuffer sb=new StringBuffer();
  int length=s.length();
  for (int i=0; i < length; i+=1) {
    c=s.charAt(i);
    if (c < ' ' || c == '+' || c == '%' || c == '=' || c == ';') {
      sb.append('%');
      sb.append(Character.forDigit((char)((c >>> 4) & 0x0f),16));
      sb.append(Character.forDigit((char)(c & 0x0f),16));
    }
 else {
      sb.append(c);
    }
  }
  return sb.toString();
}

