private int getMatchLevel(MapEntity entity){
  String name=entity.getName();
  if (name != null)   name=name.toLowerCase();
  if (name != null && name.equals(searchPattern))   return 1;
  if (currMatchLevel >= 2) {
    for (    EntityAttribute att : entity.getAttributes())     if (att.getValue().toLowerCase().equals(searchPattern))     return 2;
  }
  if (currMatchLevel >= 3) {
    for (    EntityAttribute att : entity.getAttributes())     if (att.getKey().toLowerCase().equals(searchPattern))     return 3;
  }
  if (name != null && currMatchLevel >= 4 && name.contains(searchPattern))   return 4;
  return 5;
}

