/** 
 * Compares this block to the input block. Only static blocks that are not directly related to each other (neither ancestors nor descendants) can be compared. All other blocks return false (conflation of false and bottom).
 * @param that The block to compare.
 * @return Boolean indicating whether the input precedes this block.
 */
public boolean before(Block that){
  if (this.isSubblockOf(that) || that.isSubblockOf(this) || this.randomize|| that.randomize)   return false;
  for (int i=0; i < Math.min(this.id.length,that.id.length); i++)   if (this.id[i] != that.id[i])   return this.id[0] < that.getBlockId()[0];
  return false;
}

