/** 
 * Combines words into lines in a document page except the table area
 * @param wordsOfAPage a list of words of one page
 * @return a list of lines of one page
 */
private ArrayList<TextPiece> combineLines(ArrayList<TextPiece> wordsOfAPage){
  ArrayList<TextPiece> linesOfAPage=new ArrayList<TextPiece>();
  TextPiece line=null;
  for (int i=0; i < wordsOfAPage.size(); i++) {
    TextPiece prevWord=(i == 0) ? null : wordsOfAPage.get(i - 1);
    TextPiece currentWord=wordsOfAPage.get(i);
    TextPiece nextWord=(i == wordsOfAPage.size() - 1) ? null : wordsOfAPage.get(i + 1);
    float gapToPrevWord=(prevWord == null) ? Integer.MAX_VALUE : currentWord.getX() - prevWord.getX() - prevWord.getWidth();
    float gapToNextWord=(nextWord == null) ? Integer.MAX_VALUE : nextWord.getX() - currentWord.getX() - currentWord.getWidth();
    boolean isNewLine;
    if (prevWord != null && (Math.abs(currentWord.getY() - prevWord.getY()) <= Math.max(prevWord.getYScale(),prevWord.getFontSize())) && (currentWord.getX() > prevWord.getX()) && ((gapToPrevWord < m_docInfo.getAverageCharWidth() * 1.5) || (gapToPrevWord < 5.0f))) {
      isNewLine=false;
    }
 else     isNewLine=true;
    boolean isSpaceOrEmpty=currentWord.getText() == " " || currentWord.getText() == "";
    if (isNewLine || line == null) {
      if (isSpaceOrEmpty) {
      }
 else {
        line=new TextPiece();
        linesOfAPage.add(line);
        line.setX(currentWord.getX());
        line.setY(currentWord.getY());
        line.setEndX(currentWord.getX() + currentWord.getWidth());
        line.setEndY(currentWord.getY() + Math.max(currentWord.getYScale(),currentWord.getFontSize()));
        line.setXScale(currentWord.getXScale());
        line.setWidth(currentWord.getWidth());
        line.setHeight(Math.max(currentWord.getFontSize(),currentWord.getYScale()));
        line.setText(currentWord.getText());
        line.setFontSize(currentWord.getFontSize());
      }
    }
 else {
      if (line.getText().length() == 1 && currentWord.getXScale() > prevWord.getXScale() && currentWord.getX() > prevWord.getX() && currentWord.getY() > prevWord.getY() && prevWord.getY() + prevWord.getXScale() > currentWord.getY()) {
        line.setSuperScriptBeginning(true);
      }
      if (currentWord.getX() - line.getEndX() > 1.5) {
        line.setText(line.getText() + " " + currentWord.getText());
      }
 else       line.setText(line.getText() + currentWord.getText());
      line.setWidth(line.getWidth() + currentWord.getWidth());
      line.setEndX(currentWord.getX() + currentWord.getWidth());
      if (currentWord.getXScale() > line.getXScale())       line.setXScale(currentWord.getXScale());
      line.setY(currentWord.getY());
      line.setEndY(currentWord.getY() + Math.max(currentWord.getYScale(),currentWord.getFontSize()));
    }
  }
  return linesOfAPage;
}

private void waitForSsh(String user,String host){
  int timeout=120000;
  long startTime=System.currentTimeMillis();
  while (true) {
    logger.info(String.format("Making sure sshd is up on host: %s ",host));
    try {
      if (System.currentTimeMillis() - startTime > timeout) {
        throw new RuntimeException(String.format("ssh failed to work within %s seconds.",timeout / 1000));
      }
      try (Ssh ssh=new Ssh(host)){
        authenticator().authenticate(ssh.getConnection());
        logger.info("sshd is ready on host: " + host);
      }
       return;
    }
 catch (    IOException e) {
      try {
        Thread.sleep(10000);
      }
 catch (      InterruptedException e1) {
        logger.error(e.getMessage(),e);
        return;
      }
    }
  }
}

@Override public void onSensorChanged(SensorEvent event){
  double now=(double)System.currentTimeMillis();
  if (this.shouldProcessEvent(event) == false)   return;
  if (this.passesThreshold(event)) {
synchronized (this) {
      sensorTimeBuffer[bufferIndex]=event.timestamp;
      timeBuffer[bufferIndex]=now / 1000;
      accuracyBuffer[bufferIndex]=event.accuracy;
      for (int i=0; i < event.values.length; i++) {
        valueBuffer[i][bufferIndex]=event.values[i];
      }
      double[] plotValues={timeBuffer[0] / 1000,valueBuffer[0][bufferIndex],valueBuffer[1][bufferIndex],valueBuffer[2][bufferIndex]};
      RealTimeProbeViewActivity.plotIfVisible(this.getTitleResource(),plotValues);
      bufferIndex+=1;
      if (bufferIndex >= timeBuffer.length) {
        Sensor sensor=event.sensor;
        Bundle data=new Bundle();
        Bundle sensorBundle=new Bundle();
        sensorBundle.putFloat(ContinuousProbe.SENSOR_MAXIMUM_RANGE,sensor.getMaximumRange());
        sensorBundle.putString(ContinuousProbe.SENSOR_NAME,sensor.getName());
        sensorBundle.putFloat(ContinuousProbe.SENSOR_POWER,sensor.getPower());
        sensorBundle.putFloat(ContinuousProbe.SENSOR_RESOLUTION,sensor.getResolution());
        sensorBundle.putInt(ContinuousProbe.SENSOR_TYPE,sensor.getType());
        sensorBundle.putString(ContinuousProbe.SENSOR_VENDOR,sensor.getVendor());
        sensorBundle.putInt(ContinuousProbe.SENSOR_VERSION,sensor.getVersion());
        data.putDouble(Probe.BUNDLE_TIMESTAMP,now / 1000);
        data.putString(Probe.BUNDLE_PROBE,this.name(this._context));
        data.putBundle(ContinuousProbe.BUNDLE_SENSOR,sensorBundle);
        data.putDoubleArray(ContinuousProbe.EVENT_TIMESTAMP,timeBuffer);
        data.putDoubleArray(ContinuousProbe.SENSOR_TIMESTAMP,sensorTimeBuffer);
        data.putIntArray(ContinuousProbe.SENSOR_ACCURACY,accuracyBuffer);
        for (int i=0; i < fieldNames.length; i++) {
          data.putFloatArray(fieldNames[i],valueBuffer[i]);
        }
        this.transmitData(this._context,data);
        if (timeBuffer.length > 0) {
          double x=Double.NaN;
          double y=Double.NaN;
          double z=Double.NaN;
          for (int i=0; i < fieldNames.length; i++) {
            if (fieldNames[i].equals(Continuous3DProbe.X_KEY))             x=valueBuffer[i][0];
 else             if (fieldNames[i].equals(Continuous3DProbe.Y_KEY))             y=valueBuffer[i][0];
 else             if (fieldNames[i].equals(Continuous3DProbe.Z_KEY))             z=valueBuffer[i][0];
          }
          if (Double.isNaN(x) == false && Double.isNaN(y) == false && Double.isNaN(z) == false) {
            Map<String,Object> values=new HashMap<>(4);
            values.put(Continuous3DProbe.X_KEY,x);
            values.put(Continuous3DProbe.Y_KEY,y);
            values.put(Continuous3DProbe.Z_KEY,z);
            values.put(ProbeValuesProvider.TIMESTAMP,timeBuffer[0] / 1000);
            ProbeValuesProvider.getProvider(this._context).insertValue(this._context,MagneticFieldProbe.DB_TABLE,this.databaseSchema(),values);
          }
        }
