/** 
 * Checks if this certificate was signed using the private key corresponding to the specified public key.
 * @param k public key to be used for verifying certificate signature
 * @exception CertificateException if there is an error
 */
public void verify(PublicKey k) throws CertificateException {
  RSAPublicKey pk;
  if (!(k instanceof RSAPublicKey)) {
    throw new CertificateException("Issuer key not a public RSA",this,CertificateException.VERIFICATION_FAILED);
  }
  pk=(RSAPublicKey)k;
  if (selfSigned) {
    if (pubKey.equals(pk)) {
      return;
    }
    throw new CertificateException("Bad self signed cert",this,CertificateException.VERIFICATION_FAILED);
  }
  if (signature == null) {
    throw new CertificateException(this,CertificateException.MISSING_SIGNATURE);
  }
  if (TBSCertHash == null) {
    throw new CertificateException(this,CertificateException.UNSUPPORTED_SIGALG);
  }
  int modLen=pk.getModulusLen();
  byte[] result=new byte[modLen];
  int val;
  try {
    Cipher rsa=Cipher.getInstance("RSA");
    rsa.init(Cipher.DECRYPT_MODE,pk);
    val=rsa.doFinal(signature,0,signature.length,result,0);
  }
 catch (  Exception e) {
    throw new CertificateException(this,CertificateException.VERIFICATION_FAILED);
  }
  if ((sigAlg == MD2_RSA) && (val == (PREFIX_MD2.length + TBSCertHash.length)) && Utils.byteMatch(result,0,PREFIX_MD2,0,PREFIX_MD2.length)&& Utils.byteMatch(result,PREFIX_MD2.length,TBSCertHash,0,TBSCertHash.length)) {
    return;
  }
  if ((sigAlg == MD5_RSA) && (val == (PREFIX_MD5.length + TBSCertHash.length)) && Utils.byteMatch(result,0,PREFIX_MD5,0,PREFIX_MD5.length)&& Utils.byteMatch(result,PREFIX_MD5.length,TBSCertHash,0,TBSCertHash.length)) {
    return;
  }
  if ((sigAlg == SHA1_RSA) && (val == (PREFIX_SHA1.length + TBSCertHash.length)) && Utils.byteMatch(result,0,PREFIX_SHA1,0,PREFIX_SHA1.length)&& Utils.byteMatch(result,PREFIX_SHA1.length,TBSCertHash,0,TBSCertHash.length)) {
    return;
  }
  throw new CertificateException(this,CertificateException.VERIFICATION_FAILED);
}

/** 
 * Divides this RRB-Tree such that every index less-than the given index ends up in the left-hand tree and the indexed item and all subsequent ones end up in the right-hand tree.
 * @param splitIndex the split point (excluded from the left-tree, included in the right one)
 * @return two new sub-trees as determined by the split point.  If the point is 0 orthis.size() one tree will be empty (but never null).
 */
public Tuple2<MutableRrbt<E>,MutableRrbt<E>> split(int splitIndex){
  if (splitIndex < 1) {
    if (splitIndex == 0) {
      return Tuple2.of(emptyMutable(),this);
    }
 else {
      throw new IndexOutOfBoundsException("Constraint violation failed: 1 <= splitIndex <= size");
    }
  }
 else   if (splitIndex >= size) {
    if (splitIndex == size) {
      return Tuple2.of(this,emptyMutable());
    }
 else {
      throw new IndexOutOfBoundsException("Constraint violation failed: 1 <= splitIndex <= size");
    }
  }
  Node<E> newRoot=pushFocus();
  SplitNode<E> split=newRoot.splitAt(splitIndex);
  E[] lFocus=split.leftFocus();
  Node<E> left=eliminateUnnecessaryAncestors(split.left());
  E[] rFocus=split.rightFocus();
  Node<E> right=eliminateUnnecessaryAncestors(split.right());
  return Tuple2.of(new MutableRrbt<>(lFocus,left.size(),lFocus.length,left,left.size() + lFocus.length),new MutableRrbt<>(rFocus,0,rFocus.length,right,right.size() + rFocus.length));
}
