/** 
 * Builds a criteria query equal to the JPQL <code>SELECT _testEntity FROM TestEntity _testEntity WHERE _testEntity.value :value</code>
 */
private TypedQuery<TestEntity> buildGetByValue(){
  CriteriaBuilder criteriaBuilder=entityManager.getCriteriaBuilder();
  CriteriaQuery<TestEntity> criteriaQuery=criteriaBuilder.createQuery(TestEntity.class);
  Root<TestEntity> root=criteriaQuery.from(TestEntity.class);
  ParameterExpression<String> valueParameter=criteriaBuilder.parameter(String.class,TestEntity_.value.getName());
  criteriaQuery.select(root).where(criteriaBuilder.equal(root.get(TestEntity_.value),valueParameter));
  return entityManager.createQuery(criteriaQuery);
}

/** 
 * Transforms an object (runtime representation) to a SoyExpression (compile time representation). This never happens during normal compilation. (ExpressionCompiler outputs SoyExpressions, but its input is a Soy AST.) For unit tests we pretend that runtime objects exist as compile time representations.
 */
private SoyExpression transform(Object value){
  if (value == null || value instanceof UndefinedData || value instanceof NullData) {
    return SoyExpression.NULL;
  }
 else   if (value instanceof Integer) {
    return SoyExpression.forInt(BytecodeUtils.constant(((Integer)value).longValue()));
  }
 else   if (value instanceof Long) {
    return SoyExpression.forInt(BytecodeUtils.constant(((Long)value).longValue()));
  }
 else   if (value instanceof IntegerData) {
    return SoyExpression.forInt(BytecodeUtils.constant(((IntegerData)value).longValue())).box();
  }
 else   if (value instanceof Double) {
    return SoyExpression.forFloat(BytecodeUtils.constant(((Double)value).doubleValue()));
  }
 else   if (value instanceof FloatData) {
    return SoyExpression.forFloat(BytecodeUtils.constant(((FloatData)value).numberValue())).box();
  }
 else   if (value instanceof String) {
    return SoyExpression.forString(BytecodeUtils.constant(((String)value)));
  }
 else   if (value instanceof StringData) {
    return SoyExpression.forString(BytecodeUtils.constant(((StringData)value).toString())).box();
  }
 else   if (value instanceof Boolean) {
    return SoyExpression.forBool(BytecodeUtils.constant(((Boolean)value)));
  }
 else   if (value instanceof BooleanData) {
    return SoyExpression.forBool(BytecodeUtils.constant(((BooleanData)value).booleanValue())).box();
  }
 else   if (value instanceof SanitizedContent) {
    SanitizedContent content=(SanitizedContent)value;
    Expression sanitizedExpr=MethodRef.ORDAIN_AS_SAFE_DIR.invoke(BytecodeUtils.constant(content.toString()),BytecodeUtils.constant(content.getContentKind()),BytecodeUtils.constant(content.getContentDirection()));
    SoyType type=SanitizedType.getTypeForContentKind(SanitizedContentKind.valueOf(content.getContentKind().name()));
    return SoyExpression.forSoyValue(type,sanitizedExpr);
  }
 else   if (value instanceof SoyDict) {
    List<Expression> keys=new ArrayList<>();
    List<Expression> values=new ArrayList<>();
    SoyDict dict=(SoyDict)value;
    for (    Map.Entry<String,? extends SoyValue> entry : dict.asResolvedJavaStringMap().entrySet()) {
      keys.add(transform(entry.getKey()));
      values.add(transform(entry.getValue()));
    }
    return SoyExpression.forSoyValue(UnknownType.getInstance(),MethodRef.DICT_IMPL_FOR_PROVIDER_MAP.invoke(BytecodeUtils.newLinkedHashMap(keys,values),FieldRef.enumReference(RuntimeMapTypeTracker.Type.LEGACY_OBJECT_MAP_OR_RECORD).accessor()));
  }
 else   if (value instanceof SoyMap) {
    List<Expression> keys=new ArrayList<>();
    List<Expression> values=new ArrayList<>();
    SoyMap map=(SoyMap)value;
    for (    Map.Entry<? extends SoyValue,? extends SoyValueProvider> entry : map.asJavaMap().entrySet()) {
      keys.add(transform(entry.getKey()));
      values.add(transform(entry.getValue().resolve()));
    }
    return SoyExpression.forSoyValue(UnknownType.getInstance(),MethodRef.MAP_IMPL_FOR_PROVIDER_MAP.invoke(BytecodeUtils.newLinkedHashMap(keys,values)));
  }
 else   if (value instanceof SoyList) {
    List<Expression> items=new ArrayList<>();
    for (    SoyValue item : ((SoyList)value).asResolvedJavaList()) {
      items.add(transform(item));
    }
    return SoyExpression.forList(ListType.of(UnknownType.getInstance()),BytecodeUtils.asList(items));
  }
  throw new UnsupportedOperationException("Values of type: " + value.getClass() + " not supported yet");
}

