 * @param count data ã�®æœ‰åŠ¹ãƒ“ãƒƒãƒˆæ•°
 * @param data ãƒ“ãƒƒãƒˆãƒ‡ãƒ¼ã‚¿
 * @exception IOException å…¥å‡ºåŠ›ã‚¨ãƒ©ãƒ¼ã�Œç™ºç”Ÿã�—ã�Ÿå ´å�ˆ
 */
public void writeBits(int count,final int data) throws IOException {
  while (0 < count) {
    final int available=32 - bitCount;
    if (count < available) {
      bitBuffer|=(data & 0xFFFFFFFF >>> 32 - count) << available - count;
      bitCount+=count;
      count=0;
    }
 else {
      count-=available;
      bitBuffer|=data >> count & 0xFFFFFFFF >>> 32 - available;
      writeOutBitBuffer();
    }
  }
}

