@Override public void inspect(final LineInspectorListener listener,final char[] data,final int begin,final int length,final EngineRequest request,final CompositeNut.CompositeInput cis,final ConvertibleNut originalNut) throws WuicException {
  Range dataRange;
  int start=begin;
  while ((dataRange=findInspectRange(data,start,length - 1)) != null) {
    if (Range.Delimiter.CONTINUE == dataRange.getDelimiter()) {
      start=dataRange.getStart();
      continue;
    }
    int offset=dataRange.getStart();
    Range range;
    int len;
    while ((len=dataRange.getEnd() - offset + 1) > 0 && (range=doFind(data,offset,len,request,cis,originalNut,dataRange.getDelimiter())) != null) {
      final int findLen=range.getEnd() - range.getStart();
      final List<AppendedTransformation> transformations=appendTransformation(data,range.getStart(),findLen,request,cis,originalNut);
      if (transformations != null) {
        for (        final AppendedTransformation t : transformations) {
          listener.onMatch(data,t.getStart(),t.getEnd() - t.getStart(),t.getReplacement(),t.getResult());
        }
      }
      offset=range.getEnd();
    }
    start=dataRange.getEnd() + 1;
  }
}

public static boolean requiresNewImageDownload(MagicCardDefinition card,Date lastDownloadDate){
  if (!card.hasImageUrl()) {
