/** 
 * <p>Ensures that the given table MUST be inside the upload schema in ADQL.</p> <p>Thus, the following cases are taken into account:</p> <ul> <li> The schema name of the given table MUST be  {@link STDSchema#UPLOADSCHEMA} ("TAP_UPLOAD") in ADQL.If it has another ADQL name, an exception will be thrown. Of course, the DB name of this schema MAY be different. </li> <li> If schemas are not supported by this connection, this function will prefix the table DB name by the schema DB name directly inside the given  {@link TAPTable} object. Then the DB name of the schema will be set to NULL.</li> </ul>
 * @param tableDef	Definition of the table to create/drop.
 * @throws DBException	If the given table is not in a schemaor if the ADQL name of this schema is not  {@link STDSchema#UPLOADSCHEMA} ("TAP_UPLOAD").
 */
protected void checkUploadedTableDef(final TAPTable tableDef) throws DBException {
  if (tableDef.getSchema() == null || !tableDef.getSchema().getADQLName().equals(STDSchema.UPLOADSCHEMA.label))   throw new DBException("Missing upload schema! An uploaded table must be inside a schema whose the ADQL name is strictly equals to \"" + STDSchema.UPLOADSCHEMA.label + "\" (but the DB name may be different).");
  if (!supportsSchema) {
    if (tableDef.getADQLSchemaName() != null && tableDef.getADQLSchemaName().trim().length() > 0 && !tableDef.getDBName().startsWith(tableDef.getADQLSchemaName() + "_"))     tableDef.setDBName(tableDef.getADQLSchemaName() + "_" + tableDef.getDBName());
    if (tableDef.getSchema() != null)     tableDef.getSchema().setDBName(null);
  }
}

