/** 
 * reload from the model and re-apply filter criteria
 */
public void refresh(){
  TableSorter tm=(TableSorter)taskTable.getModel();
  tm.setRowCount(0);
  tm.tableChanged(new TableModelEvent(tm));
  Integer projfiltid=null;
  if (!projectName.equals(Resource.getResourceString("All"))) {
    try {
      projfiltid=TaskView.getProjectId(projectName);
    }
 catch (    Exception e) {
      Errmsg.getErrorHandler().errmsg(e);
      return;
    }
  }
  String subtaskString=Resource.getResourceString("subtask");
  try {
    TaskTypes tasktypes=TaskModel.getReference().getTaskTypes();
    Collection<Task> tasks=TaskModel.getReference().getTasks();
    int totalItems=0;
    for (    Task task : tasks) {
      String st=task.getState();
      if (taskStatus.equals(Resource.getResourceString("All_Open"))) {
        if (TaskModel.isClosed(task)) {
          continue;
        }
      }
 else       if (!taskStatus.equals(Resource.getResourceString("All")) && !taskStatus.equals(st))       continue;
      if (showClosedTasksCheckBox != null && !showClosedTasksCheckBox.isSelected() && TaskModel.isClosed(task))       continue;
      Integer pid=task.getProject();
      if (projfiltid != null) {
        if (pid == null || pid.intValue() != projfiltid.intValue())         continue;
      }
      if (!CategoryModel.getReference().isShown(task.getCategory()))       continue;
      if (filterString.length() != 0) {
        String s=task.getSummary();
        String d=task.getDescription();
        String r=task.getResolution();
        if (r == null)         r="";
        if (s == null)         s="";
        if (d == null)         d="";
        if (filterCaseSensitive) {
          if (d.indexOf(filterString) == -1 && r.indexOf(filterString) == -1 && s.indexOf(filterString) == -1)           continue;
        }
 else {
          String lfilt=filterString.toLowerCase();
          String ld=d.toLowerCase();
          String lr=r.toLowerCase();
          String ls=s.toLowerCase();
          if (ld.indexOf(lfilt) == -1 && lr.indexOf(lfilt) == -1 && ls.indexOf(lfilt) == -1)           continue;
        }
      }
      Object[] ro=new Object[13];
      ro[0]=Integer.valueOf(task.getKey());
      ro[1]=task.getState();
      ro[2]=task.getType();
      ro[12]=task.getCategory();
      ro[3]=task.getPriority();
      ro[6]=task.getStartDate();
      ro[7]=task.getDueDate();
      ro[8]=task.getCompletionDate();
      if (task.getDueDate() != null) {
        ro[9]=Integer.valueOf(TaskModel.daysBetween(task.getStartDate(),task.getDueDate()));
      }
 else {
        ro[9]=null;
      }
      Date end=null;
      if (task.getState().equals(tasktypes.getFinalState(task.getType()))) {
        end=task.getCompletionDate();
      }
 else {
        end=new Date();
      }
      if (end == null) {
        ro[10]=null;
      }
 else {
        ro[10]=Integer.valueOf(TaskModel.daysBetween(task.getStartDate(),end));
      }
      if (ro[7] == null || TaskModel.isClosed(task))       ro[4]=null;
 else {
        Date dd=(Date)ro[7];
        ro[4]=Integer.valueOf(TaskModel.daysLeft(dd));
      }
      ro[5]=task.getSummary();
      StringBuffer ps=new StringBuffer();
      if (pid != null) {
        Project p=TaskModel.getReference().getProject(pid.intValue());
        if (p != null) {
          String tt=p.getDescription();
          for (int i=0; tt != null && i < tt.length(); i++) {
            char c=tt.charAt(i);
            if (c == '\n' || c == '\r') {
              ps.append(' ');
              continue;
            }
            ps.append(c);
          }
        }
      }
      ro[11]=ps;
      tm.addRow(ro);
      totalItems++;
      if (showSubTasksBox.isSelected()) {
        Collection<Subtask> subtasks=TaskModel.getReference().getSubTasks(task.getKey());
        for (        Subtask subtask : subtasks) {
          if ((taskStatus.equals(Resource.getResourceString("All_Open")) || taskStatus.equals(Resource.getResourceString("OPEN"))) && subtask.getCloseDate() != null)           continue;
          if (showClosedTasksCheckBox != null && !showClosedTasksCheckBox.isSelected() && subtask.getCloseDate() != null)           continue;
          ro=new Object[12];
          ro[0]=null;
          ro[1]=(subtask.getCloseDate() == null) ? Resource.getResourceString("OPEN") : Resource.getResourceString("CLOSED");
          ro[2]=subtaskString;
          ro[11]=task.getCategory();
          ro[3]=task.getPriority();
          ro[6]=subtask.getStartDate();
          ro[7]=subtask.getDueDate();
          if (subtask.getDueDate() != null) {
            ro[8]=Integer.valueOf(TaskModel.daysBetween(subtask.getStartDate(),subtask.getDueDate()));
          }
 else {
            ro[8]=null;
          }
          end=null;
          if (subtask.getCloseDate() != null) {
            end=subtask.getCloseDate();
          }
 else {
            end=new Date();
          }
          if (end == null) {
            ro[9]=null;
          }
 else {
            ro[9]=Integer.valueOf(TaskModel.daysBetween(subtask.getStartDate(),end));
          }
          if (ro[7] == null || subtask.getCloseDate() != null)           ro[4]=null;
 else {
            Date dd=(Date)ro[7];
            ro[4]=Integer.valueOf(TaskModel.daysLeft(dd));
          }
          ro[5]=subtask.getDescription();
          ro[10]=ps;
          tm.addRow(ro);
        }
      }
      tm.tableChanged(new TableModelEvent(tm));
    }
    getTotalLabel().setText(totalItems + " items");
  }
 catch (  Exception e) {
    Errmsg.getErrorHandler().errmsg(e);
  }
  if (!tm.isSorted())   tm.sortByColumn(6);
 else   tm.sort();
}

