@Override public List<PlotConfigurationError> getEngineWarnings(){
  List<PlotConfigurationError> warnings=new LinkedList<PlotConfigurationError>();
  PlotConfiguration plotConfiguration=plotInstance.getCurrentPlotConfigurationClone();
  if (plotConfiguration.getDomainConfigManager().isNominal()) {
    for (    ValueSource valueSource : plotConfiguration.getAllValueSources()) {
      if (valueSource.getSeriesFormat().getSeriesType() == VisualizationType.LINES_AND_SHAPES && valueSource.getSeriesFormat().getLineStyle() != LineStyle.NONE && !valueSource.isUsingDomainGrouping()) {
        warnings.add(new PlotConfigurationError("plot_does_not_support_lines","categorical scatter plot with ungrouped domain axis",valueSource.toString()));
      }
    }
  }
  for (  ValueSource valueSource : plotConfiguration.getAllValueSources()) {
    SeriesFormat format=valueSource.getSeriesFormat();
    if (format.getSeriesType() == VisualizationType.LINES_AND_SHAPES) {
      if (format.getUtilityUsage() == IndicatorType.DIFFERENCE) {
        if (format.getItemShape() != ItemShape.NONE) {
          warnings.add(new PlotConfigurationError("difference_plot_with_items_not_supported",valueSource.toString()));
        }
      }
    }
  }
  return warnings;
}

private Status beginTX(SoaContext context){
  Status s=new Status();
  Integer txType=(Integer)context.getAttr("transactionType");
  context.removeAttr("transactionType");
  if (txType == null) {
    s.isCanTX=false;
    return s;
  }
  logger.info("**SoaManage Call by TxType[{}]",txType);
  PlatformTransactionManager txMgr=SpringContextHolder.getBean(PlatformTransactionManager.class);
  s.txManager=txMgr;
  s.defaultTransactionDefinition=new DefaultTransactionDefinition(txType.intValue());
  s.defaultTransactionDefinition.setIsolationLevel(TransactionDefinition.PROPAGATION_MANDATORY);
  s.isCanTX=true;
  if (txMgr != null) {
    try {
      s.tx=txMgr.getTransaction(s.defaultTransactionDefinition);
      logger.info("**SoaManage Get New Transaction Success!");
    }
 catch (    Exception e) {
      s.isCanTX=false;
      logger.error("**SoaManage Get New Transaction Fail!",e);
    }
  }
 else {
    logger.error("**SoaManage Get New Transaction Fail!");
    s.isCanTX=false;
  }
  return s;
}

