/** 
 * Subscribes to the source and calls the Observer methods on the current thread. <p>
 * @param o the source ObservableSourceThe call to dispose() is composed through.
 * @param observer the subscriber to forward events and calls to in the current thread
 * @param < T > the value type
 */
public static <T>void subscribe(ObservableSource<? extends T> o,Observer<? super T> observer){
  final BlockingQueue<Object> queue=new LinkedBlockingQueue<Object>();
  BlockingObserver<T> bs=new BlockingObserver<T>(queue);
  observer.onSubscribe(bs);
  o.subscribe(bs);
  for (; ; ) {
    if (bs.isDisposed()) {
      break;
    }
    Object v=queue.poll();
    if (v == null) {
      try {
        v=queue.take();
      }
 catch (      InterruptedException ex) {
        bs.dispose();
        observer.onError(ex);
        return;
      }
    }
    if (bs.isDisposed() || v == BlockingObserver.TERMINATED || NotificationLite.acceptFull(v,observer)) {
      break;
    }
  }
}
/** 
 * Runs the source observable to a terminal event, ignoring any values and rethrowing any exception.
 * @param o the source ObservableSource
 * @param < T > the value type
 */
public static <T>void subscribe(ObservableSource<? extends T> o){
  BlockingIgnoringReceiver callback=new BlockingIgnoringReceiver();
  LambdaObserver<T> ls=new LambdaObserver<T>(Functions.emptyConsumer(),callback,callback,Functions.emptyConsumer());
  o.subscribe(ls);
  BlockingHelper.awaitForComplete(callback,ls);
  Throwable e=callback.error;
  if (e != null) {
    throw ExceptionHelper.wrapOrThrow(e);
  }
}
/** 
 * Subscribes to the source and calls the given actions on the current thread.
 * @param o the source ObservableSource
 * @param onNext the callback action for each source value
 * @param onError the callback action for an error event
 * @param onComplete the callback action for the completion event.
 * @param < T > the value type
 */
public static <T>void subscribe(ObservableSource<? extends T> o,final Consumer<? super T> onNext,final Consumer<? super Throwable> onError,final Action onComplete){
  ObjectHelper.requireNonNull(onNext,"onNext is null");
  ObjectHelper.requireNonNull(onError,"onError is null");
  ObjectHelper.requireNonNull(onComplete,"onComplete is null");
  subscribe(o,new LambdaObserver<T>(onNext,onError,onComplete,Functions.emptyConsumer()));
}

