public void guessValueTypes(File originalDataFile,String commentString,String columnSeparators,char decimalPointCharacter,boolean useQuotes,boolean firstLineAsNames){
  Pattern separatorPattern=Pattern.compile(columnSeparators);
  BufferedReader in=null;
  try {
    in=new BufferedReader(new FileReader(originalDataFile));
    String line=null;
    boolean first=true;
    boolean[] hasToCheck=null;
    boolean[] onlyMissing=null;
    int rowCounter=1;
    while ((line=in.readLine()) != null) {
      if ((commentString != null) && (commentString.trim().length() > 0) && (line.startsWith(commentString)))       continue;
      if (line.trim().length() == 0)       continue;
      String[] row=null;
      if (useQuotes)       row=Tools.quotedSplit(line,separatorPattern);
 else       row=line.trim().split(columnSeparators);
      if (first) {
        hasToCheck=new boolean[row.length];
        onlyMissing=new boolean[row.length];
        for (int i=0; i < hasToCheck.length; i++) {
          onlyMissing[i]=hasToCheck[i]=true;
        }
        if (!firstLineAsNames) {
          updateValueTypes(row,hasToCheck,onlyMissing,decimalPointCharacter);
        }
        first=false;
      }
 else {
        if (row.length != hasToCheck.length)         throw new IOException("Line " + rowCounter + " has a number of columns ("+ row.length+ ") different from preceding lines ("+ hasToCheck.length+ ").");
        updateValueTypes(row,hasToCheck,onlyMissing,decimalPointCharacter);
      }
      rowCounter++;
    }
    for (int m=0; m < onlyMissing.length; m++) {
      if (onlyMissing[m])       setValueAt(Ontology.VALUE_TYPE_NAMES[Ontology.NOMINAL],0,m);
    }
  }
 catch (  IOException e) {
    SwingTools.showSimpleErrorMessage("cannot_guess_value_types",e);
  }
 finally {
    if (in != null) {
      try {
        in.close();
      }
 catch (      IOException e) {
        SwingTools.showSimpleErrorMessage("cannot_close_stream_to_data_file",e);
      }
    }
  }
}
