/** 
 * Reads enough of the input stream to convert to/from Base64 and returns the next byte.
 * @return next byte
 * @since 1.3
 */
@Override public int read() throws java.io.IOException {
  if (position < 0) {
    if (encode) {
      byte[] b3=new byte[3];
      int numBinaryBytes=0;
      for (int i=0; i < 3; i++) {
        int b=in.read();
        if (b >= 0) {
          b3[i]=(byte)b;
          numBinaryBytes++;
        }
 else {
          break;
        }
      }
      if (numBinaryBytes > 0) {
        encode3to4(b3,0,numBinaryBytes,buffer,0,options);
        position=0;
        numSigBytes=4;
      }
 else {
        return -1;
      }
    }
 else {
      byte[] b4=new byte[4];
      int i=0;
      for (i=0; i < 4; i++) {
        int b=0;
        do {
          b=in.read();
        }
 while (b >= 0 && decodabet[b & 0x7f] <= WHITE_SPACE_ENC);
        if (b < 0) {
          break;
        }
        b4[i]=(byte)b;
      }
      if (i == 4) {
        numSigBytes=decode4to3(b4,0,buffer,0,options);
        position=0;
      }
 else       if (i == 0) {
        return -1;
      }
 else {
        throw new java.io.IOException("Improperly padded Base64 input.");
      }
    }
  }
  if (position >= 0) {
    if (position >= numSigBytes) {
      return -1;
    }
    if (encode && breakLines && lineLength >= MAX_LINE_LENGTH) {
      lineLength=0;
      return '\n';
    }
 else {
      lineLength++;
      int b=buffer[position++];
      if (position >= bufferLength) {
        position=-1;
      }
      return b & 0xFF;
    }
  }
 else {
    throw new java.io.IOException("Error in Base64 code reading stream.");
  }
}
/** 
 * Calls  {@link #read()} repeatedly until the end of streamis reached or <var>len</var> bytes are read. Returns number of bytes read into array or -1 if end of stream is encountered.
 * @param dest array to hold values
 * @param off offset for array
 * @param len max number of bytes to read into array
 * @return bytes read into array or -1 if end of stream is encountered.
 * @since 1.3
 */
@Override public int read(byte[] dest,int off,int len) throws java.io.IOException {
  int i;
  int b;
  for (i=0; i < len; i++) {
    b=read();
    if (b >= 0) {
      dest[off + i]=(byte)b;
    }
 else     if (i == 0) {
      return -1;
    }
 else {
      break;
    }
  }
  return i;
}

/** 
 * Mouse events bubble up until finding a component with a relative listener. That's why in case we get an event that needs to initiate its default behavior, we just bubble it up to the parent component of the JTextArea.  
 */
public void mouseWheelMoved(MouseWheelEvent e){
  boolean isCtrlPressed=(e.getModifiers() & KeyEvent.CTRL_MASK) != 0;
  if (isCtrlPressed) {
    Font currentFont=textArea.getFont();
    int currentFontSize=currentFont.getSize();
    boolean rotationUp=e.getWheelRotation() < 0;
    if ((!rotationUp && currentFontSize > 1) || rotationUp) {
      Font newFont=new Font(currentFont.getName(),currentFont.getStyle(),currentFontSize + (rotationUp ? 1 : -1));
      textArea.setFont(newFont);
    }
  }
 else {
    textArea.getParent().dispatchEvent(e);
  }
}

