private char randomChar(Random r){
  int mode=r.nextInt(3);
  if (mode == 0)   return (char)(32 + r.nextInt(95));
 else   if (mode == 1)   return invalidCharsForSFS.charAt(r.nextInt(invalidCharsForSFS.length()));
 else {
    while (true) {
      char ch=(char)(128 + r.nextInt(0xF000 - 128));
      if (Character.isDefined(ch) && (!Character.isHighSurrogate(ch)) && (!Character.isISOControl(ch))&& !Character.isSupplementaryCodePoint(ch)) {
        return ch;
      }
    }
  }
}

/** 
 * Synchronously send the request and receive a response. This relies on the transport correctly connecting the response InputStream!
 * @param msgContext the request MessageContext to send.
 * @return Returns MessageContext.
 * @throws AxisFault Sends the message using a two way transport and waits for a response
 */
protected MessageContext send(final MessageContext msgContext) throws AxisFault {
  final MessageContext responseMessageContext=msgContext.getConfigurationContext().createMessageContext();
  responseMessageContext.setServerSide(false);
  responseMessageContext.setOperationContext(msgContext.getOperationContext());
  responseMessageContext.setOptions(new Options(options));
  responseMessageContext.setMessageID(msgContext.getMessageID());
  addMessageContext(responseMessageContext);
  responseMessageContext.setServiceContext(msgContext.getServiceContext());
  responseMessageContext.setAxisMessage(axisOp.getMessage(WSDLConstants.MESSAGE_LABEL_IN_VALUE));
  AxisEngine.send(msgContext);
  responseMessageContext.setDoingREST(msgContext.isDoingREST());
  MessageProcessingContext hb2bMsgProcCtx=MessageProcessingContext.getFromMessageContext(msgContext);
  hb2bMsgProcCtx.setParentContext(responseMessageContext);
  responseMessageContext.setProperty(MessageContext.TRANSPORT_HEADERS,msgContext.getProperty(MessageContext.TRANSPORT_HEADERS));
  responseMessageContext.setProperty(HTTPConstants.MC_HTTP_STATUS_CODE,msgContext.getProperty(HTTPConstants.MC_HTTP_STATUS_CODE));
  responseMessageContext.setProperty(MessageContext.TRANSPORT_IN,msgContext.getProperty(MessageContext.TRANSPORT_IN));
  responseMessageContext.setTransportIn(msgContext.getTransportIn());
  responseMessageContext.setTransportOut(msgContext.getTransportOut());
  handleResponse(responseMessageContext);
  return responseMessageContext;
}

