public ListenableFuture<Event> publish(Client client,ConfigUpdate update){
  WorkItem item=new WorkItem(client,update);
  if (update.getData() == null || update.getData().getItems().size() == 0) {
    reply(item,null,null);
  }
 else {
    log.debug("\t\tStaring work item {} [{}]",item.key,item.hashCode());
    requests.add(item);
  }
  return item.future;
}
protected void publish(){
  Map<String,List<WorkItem>> newWaiters=new HashMap<>();
  for (  Map.Entry<String,List<WorkItem>> entry : waiters.entrySet()) {
    List<WorkItem> remaining=new ArrayList<>();
    if (inFlight.contains(entry.getKey())) {
      newWaiters.put(entry.getKey(),entry.getValue());
      continue;
    }
    ConfigUpdate update=null;
    WorkItem lastItem=null;
    Client client=null;
    Map<String,ItemVersion> applied=null;
    Set<String> items=new HashSet<>();
    for (    WorkItem item : entry.getValue()) {
      if (item.isExpired()) {
        reply(item,null,new TimeoutException());
        continue;
      }
      if (applied == null) {
        applied=getApplied(item.client);
      }
      if (satisfies(true,item.request,applied)) {
        reply(item,null,null);
        continue;
      }
      if (update == null) {
        ConfigUpdateData data=item.request.getData();
        update=new ConfigUpdate(item.request.getName(),data.getConfigUrl(),new ArrayList<ConfigUpdateItem>());
        update.setResourceId(item.request.getResourceId());
        update.setResourceType(item.request.getResourceType());
        client=item.client;
      }
      for (      ConfigUpdateItem itemUpdate : item.request.getData().getItems()) {
        if (items.contains(itemUpdate.getName())) {
          continue;
        }
        items.add(itemUpdate.getName());
        ConfigItemStatusManagerImpl.addToList(update.getData().getItems(),itemUpdate);
      }
      remaining.add(item);
      lastItem=item;
    }
    if (update != null) {
      inFlight.add(lastItem.key);
      publishUpdate(lastItem,client,update);
    }
    if (remaining.size() > 0) {
      newWaiters.put(entry.getKey(),remaining);
    }
  }
  this.waiters=newWaiters;
}

/** 
 * Returns the row gaps in pixel sizes. One more than there are <code>specs</code> sent in.
 * @param specs
 * @param refSize
 * @param isHor
 * @param fillInPushGaps If the gaps are pushing. <b>NOTE!</b> this argument will be filled in and thus changed!
 * @return The row gaps in pixel sizes. One more than there are<code>specs</code> sent in.
 */
private int[][] getRowGaps(DimConstraint[] specs,int refSize,boolean isHor,boolean[] fillInPushGaps){
  BoundSize defGap=isHor ? lc.getGridGapX() : lc.getGridGapY();
  if (defGap == null)   defGap=isHor ? PlatformDefaults.getGridGapX() : PlatformDefaults.getGridGapY();
  int[] defGapArr=defGap.getPixelSizes(refSize,container,null);
  boolean defIns=!hasDocks();
  UnitValue firstGap=LayoutUtil.getInsets(lc,isHor ? 1 : 0,defIns);
  UnitValue lastGap=LayoutUtil.getInsets(lc,isHor ? 3 : 2,defIns);
  int[][] retValues=new int[specs.length + 1][];
  for (int i=0, wgIx=0; i < retValues.length; i++) {
    DimConstraint specBefore=i > 0 ? specs[i - 1] : null;
    DimConstraint specAfter=i < specs.length ? specs[i] : null;
    boolean edgeBefore=(specBefore == DOCK_DIM_CONSTRAINT || specBefore == null);
    boolean edgeAfter=(specAfter == DOCK_DIM_CONSTRAINT || specAfter == null);
    if (edgeBefore && edgeAfter)     continue;
    BoundSize wrapGapSize=(wrapGapMap == null || isHor == lc.isFlowX() ? null : wrapGapMap.get(Integer.valueOf(wgIx++)));
    if (wrapGapSize == null) {
      int[] gapBefore=specBefore != null ? specBefore.getRowGaps(container,null,refSize,false) : null;
      int[] gapAfter=specAfter != null ? specAfter.getRowGaps(container,null,refSize,true) : null;
      if (edgeBefore && gapAfter == null && firstGap != null) {
        int bef=firstGap.getPixels(refSize,container,null);
        retValues[i]=new int[]{bef,bef,bef};
      }
 else       if (edgeAfter && gapBefore == null && firstGap != null) {
        int aft=lastGap.getPixels(refSize,container,null);
        retValues[i]=new int[]{aft,aft,aft};
      }
 else {
        retValues[i]=gapAfter != gapBefore ? mergeSizes(gapAfter,gapBefore) : new int[]{defGapArr[0],defGapArr[1],defGapArr[2]};
      }
      if (specBefore != null && specBefore.isGapAfterPush() || specAfter != null && specAfter.isGapBeforePush())       fillInPushGaps[i]=true;
    }
 else {
      if (wrapGapSize.isUnset()) {
        retValues[i]=new int[]{defGapArr[0],defGapArr[1],defGapArr[2]};
      }
 else {
        retValues[i]=wrapGapSize.getPixelSizes(refSize,container,null);
      }
      fillInPushGaps[i]=wrapGapSize.getGapPush();
    }
  }
  return retValues;
}

