@Signature public Memory merge(String[] refs,ArrayMemory settings) throws IOException, GitAPIException {
  MergeCommand command=getWrappedObject().merge();
  for (  String ref : refs) {
    Repository repository=getWrappedObject().getRepository();
    ObjectId objectId=repository.resolve(ref);
    command.include(objectId);
  }
  if (settings != null) {
    command.setCommit(settings.valueOfIndex("commit").toBoolean());
    command.setMessage(settings.valueOfIndex("message").toString());
    command.setSquash(settings.valueOfIndex("squash").toBoolean());
    Memory fastForward=settings.valueOfIndex("fastForward");
    if (fastForward.isNumber()) {
      command.setFastForward(MergeCommand.FastForwardMode.valueOf(fastForward.toString()));
    }
    Memory strategy=settings.valueOfIndex("strategy");
    if (strategy.isNotNull()) {
      command.setStrategy(MergeStrategy.get(strategy.toString()));
    }
  }
  MergeResult call=command.call();
  return GitUtils.valueOf(call);
}

@GET @Path("/{subject}/subscribers/{id}") @Produces(MediaType.TEXT_PLAIN) public void nextSession(@PathParam("subject") String subject,@PathParam("id") String id,@Context EventManager events,@Suspended AsyncResponse response){
  EventLog<Consumer<String>,String> eventLog=events.getEventLog(ClusterEventService.class,getEventLogName(subject,id));
  if (eventLog == null) {
    LOGGER.warn("Unknown subscriber {}",id);
    response.resume(Response.status(Status.NOT_FOUND).build());
    return;
  }
  eventLog.nextEvent().whenComplete((event,error) -> {
    if (error == null) {
      response.resume(Response.ok(event).build());
    }
 else {
      LOGGER.warn("Subscriber {} closed",id);
      response.resume(Response.noContent().build());
    }
  }
);
}

