public Memory tryWritePushVariable(VariableExprToken value,boolean heavyObjects){
  if (methodStatement.isUnstableVariable(value))   return null;
  if (compiler.getScope().superGlobals.contains(value.getName()))   return null;
  LocalVariable variable=method.getLocalVariable(value.getName());
  if (variable == null || variable.getClazz() == null || methodStatement.isUnusedVariable(value)) {
    return Memory.NULL;
  }
 else {
    if (methodStatement.variable(value).isPassed())     return null;
    Memory mem=variable.getValue();
    if (mem != null) {
      if (!heavyObjects) {
        if (mem.isArray() || mem.toString().length() > 100) {
          return null;
        }
      }
      return mem;
    }
  }
  return null;
}

public void checkIfCanDistributeStudentsByRooms(){
  if (this.getWrittenEvaluationSpaceOccupationsSet().isEmpty()) {
    throw new DomainException("error.no.roms.associated");
  }
  final Date todayDate=Calendar.getInstance().getTime();
  final Date evaluationDateAndTime;
  try {
    evaluationDateAndTime=DateFormatUtil.parse("yyyy/MM/dd HH:mm",DateFormatUtil.format("yyyy/MM/dd ",this.getDayDate()) + DateFormatUtil.format("HH:mm",this.getBeginningDate()));
  }
 catch (  ParseException e) {
    throw new Error(e);
  }
  DateTime enrolmentEndDate=null;
  if (this.getEnrollmentEndDayDate() != null && this.getEnrollmentEndTimeDate() != null) {
    enrolmentEndDate=createDate(this.getEnrollmentEndDayDate(),this.getEnrollmentEndTimeDate());
  }
  if (DateFormatUtil.isBefore("yyyy/MM/dd HH:mm",evaluationDateAndTime,todayDate) || (enrolmentEndDate != null && enrolmentEndDate.isAfterNow())) {
    throw new DomainException("error.out.of.period.enrollment.period");
  }
}

