@Override public void removeEdge(int source,int target){
  Iterator<Edge> iter=graph[source].iterator();
  if (digraph) {
    while (iter.hasNext()) {
      Edge e=iter.next();
      if (e.v2 == target) {
        iter.remove();
      }
    }
  }
 else {
    while (iter.hasNext()) {
      Edge e=iter.next();
      if ((e.v1 == source && e.v2 == target) || (e.v2 == source && e.v1 == target)) {
        iter.remove();
      }
    }
    iter=graph[target].iterator();
    while (iter.hasNext()) {
      Edge e=iter.next();
      if ((e.v1 == source && e.v2 == target) || (e.v2 == source && e.v1 == target)) {
        iter.remove();
      }
    }
  }
}
@Override public void removeEdge(Edge edge){
  Iterator<Edge> iter=graph[edge.v1].iterator();
  while (iter.hasNext()) {
    if (iter.next() == edge) {
      iter.remove();
      break;
    }
  }
  if (!digraph) {
    iter=graph[edge.v2].iterator();
    while (iter.hasNext()) {
      if (iter.next() == edge) {
        iter.remove();
        break;
      }
    }
  }
}

