/** 
 * The spec says that HLAinteractionSubList should be a HLAvariableArray of  HLAinteractionSubscription, however HLAinteractionSubscription doesn't implement the DataElement  interface. Thus we can't create/decode the list using the encoder factory :(
 */
private Set<InteractionClassHandle> decodeHLAinteractionSubList(RTIambassador rtiamb,byte[] data) throws DecoderException, RTIinternalError, NotConnected, FederateNotExecutionMember, CouldNotDecode {
  HLAinteger32BE hlaSize=encoders.createHLAinteger32BE();
  hlaSize.decode(data);
  int size=hlaSize.getValue();
  int offset=hlaSize.getEncodedLength();
  Set<InteractionClassHandle> results=new HashSet<>(size);
  for (int i=0; i < size; ++i) {
    InteractionClassHandle handle=rtiamb.getInteractionClassHandleFactory().decode(data,offset);
    offset+=handle.encodedLength();
    offset+=4;
    results.add(handle);
  }
  return results;
}

