/** 
 * flips a bit. The index should be less than the OpenBitSet size.
 */
public void fastFlip(int index){
  int wordNum=index >> 6;
  int bit=index & 0x3f;
  long bitmask=1L << bit;
  bits[wordNum]^=bitmask;
}
/** 
 * flips a bit. The index should be less than the OpenBitSet size.
 */
public void fastFlip(long index){
  int wordNum=(int)(index >> 6);
  int bit=(int)index & 0x3f;
  long bitmask=1L << bit;
  bits[wordNum]^=bitmask;
}

/** 
 * Returns whether the given code point is acceptable for blip content. This definition is based on RFC5198 (section 2 in particular) and a few internal discussions. It may turn out to be overly restrictive, but relaxing it in the future is easy.
 */
public static BlipCodePointResult isCodePointGoodForBlip(int c){
  if (!isCodePoint(c)) {
    Preconditions.illegalArgument("Not a code point: 0x" + Integer.toHexString(c));
  }
  if (isSurrogate(c)) {
    Preconditions.illegalArgument("Code point is a surrogate: 0x" + Integer.toHexString(c));
  }
  if (!isCodePointValid(c)) {
    return BlipCodePointResult.NONCHARACTER;
  }
  if (0 <= c && c <= 0x1f || 0x7f <= c && c <= 0x9f) {
    return BlipCodePointResult.CONTROL;
  }
  if (0x206A <= c && c <= 0x206F) {
    return BlipCodePointResult.DEPRECATED;
  }
  if (c == 0x200E || c == 0x200F) {
    return BlipCodePointResult.BIDI;
  }
  if (0x202A <= c && c <= 0x202E) {
    return BlipCodePointResult.BIDI;
  }
  if (0xE0000 <= c && c <= 0xE007F) {
    return BlipCodePointResult.TAG;
  }
  return BlipCodePointResult.OK;
}

