 catch (  Exception e) {
    JOptionPane.showMessageDialog(Administrator.getDesktop(),"Check out the new, web-based Fedora Administrator.\n" + "\n       http://localhost:8080/fedora/admin\n\n" + "NOTE: The web-based Fedora Admin GUI will completely\n"+ "replace this one in future releases of Fedora.","Try the *New* Fedora Admin GUI!",JOptionPane.INFORMATION_MESSAGE);
  }
  m_serverComboBox.addItem(m_lastServer);
  Iterator<String> sIter=m_servers.keySet().iterator();
  while (sIter.hasNext()) {
    String a=sIter.next();
    if (!a.equals(m_lastServer)) {
      m_serverComboBox.addItem(a);
    }
  }
  m_servers.put(m_lastServer,"");
  m_protocolComboBox.addItem(m_lastProtocol);
  Iterator<String> protocolIter=m_protocols.keySet().iterator();
  while (protocolIter.hasNext()) {
    String a=protocolIter.next();
    if (!a.equals(m_lastProtocol)) {
