private void processFile(Path file) throws IOException {
  if (verbose)   System.out.println("Scanning -> " + file);
  FileSystem fs=file.getFileSystem(conf);
  if (!fs.exists(file)) {
    System.err.println("ERROR, file doesnt exist: " + file);
  }
  HFile.Reader reader=HFile.createReader(fs,file,new CacheConfig(conf));
  Map<byte[],byte[]> fileInfo=reader.loadFileInfo();
  KeyValueStatsCollector fileStats=null;
  if (verbose || printKey || checkRow|| checkFamily|| printStats) {
    HFileScanner scanner=reader.getScanner(false,false,false);
    fileStats=new KeyValueStatsCollector();
    boolean shouldScanKeysValues=false;
    if (this.isSeekToRow) {
      shouldScanKeysValues=(scanner.seekTo(KeyValue.createFirstOnRow(this.row).getKey()) != -1);
    }
 else {
      shouldScanKeysValues=scanner.seekTo();
    }
    if (shouldScanKeysValues)     scanKeysValues(file,fileStats,scanner,row);
  }
  if (shouldPrintMeta) {
    printMeta(reader,fileInfo);
  }
  if (printBlocks) {
    System.out.println("Block Index:");
    System.out.println(reader.getDataBlockIndexReader());
  }
  if (printStats) {
    fileStats.finish();
    System.out.println("Stats:\n" + fileStats);
  }
  reader.close();
}

private <D>D readPrimitiveValue(final String json,final Class<D> paramClass){
  Assertion.checkNotNull(json);
  if (paramClass.isPrimitive()) {
    return jsonReaderEngine.fromJson(json,paramClass);
  }
 else   if (String.class.isAssignableFrom(paramClass)) {
    return paramClass.cast(json);
  }
 else   if (Integer.class.isAssignableFrom(paramClass)) {
    return paramClass.cast(Integer.valueOf(json));
  }
 else   if (Long.class.isAssignableFrom(paramClass)) {
    return paramClass.cast(Long.valueOf(json));
  }
 else   if (Float.class.isAssignableFrom(paramClass)) {
    return paramClass.cast(Float.valueOf(json));
  }
 else   if (Double.class.isAssignableFrom(paramClass)) {
    return paramClass.cast(Double.valueOf(json));
  }
 else   if (Date.class.isAssignableFrom(paramClass) || LocalDate.class.isAssignableFrom(paramClass) || ZonedDateTime.class.isAssignableFrom(paramClass)|| Instant.class.isAssignableFrom(paramClass)) {
    return jsonReaderEngine.fromJson(escapeJsonValue(json),paramClass);
  }
 else {
    throw new IllegalArgumentException("Unsupported type " + paramClass.getSimpleName());
  }
}

private void startPlayer(Player player){
  try {
    if (player != null) {
      if (player.getState() == Player.STARTED) {
        player.stop();
        return;
      }
      if (player.getState() == Player.UNREALIZED) {
        player.prefetch();
        player.realize();
      }
      if (player.getState() != Player.CLOSED) {
        Thread.sleep(latency);
        player.start();
      }
    }
    Thread.sleep(latency);
  }
 catch (  InterruptedException e) {
  }
catch (  MediaException e) {
    discardPlayer(player);
    midlet.alertError("MediaException: " + e.getMessage());
  }
}

