/** 
 * Read all the blocks, encode them according to their supposed keys and check that they are in fact the blocks that they should be. If the metadata is inaccurate, update it and  writeMetadata(). If we have enough blocks to decode, and we don't have all the blocks, then  schedule a decode on the FEC thread. 
 * @return True if we scheduled a decode or are already finished. False if we do not have enough blocks to decode and need to fetch more blocks. 
 */
public boolean tryStartDecode(){
synchronized (this) {
    if (succeeded || failed || finished)     return false;
    if (!corruptMetadata && blockChooser.successCount() < blocksForDecode())     return false;
    if (tryDecode)     return true;
    tryDecode=true;
  }
  long limit=totalBlocks() * CHKBlock.DATA_LENGTH + Math.max(parent.fecCodec.maxMemoryOverheadDecode(blocksForDecode(),checkBlocks),parent.fecCodec.maxMemoryOverheadEncode(blocksForDecode(),checkBlocks));
  final int prio=parent.getPriorityClass();
  parent.memoryLimitedJobRunner.queueJob(new MemoryLimitedJob(limit){
    @Override public int getPriority(){
      return prio;
    }
    @Override public boolean start(    MemoryLimitedChunk chunk){
      boolean shutdown=false;
      CheckpointLock lock=null;
      try {
        lock=parent.jobRunner.lock();
        innerDecode(chunk);
      }
 catch (      IOException e) {
        Logger.error(this,"Failed to decode " + this + " because of disk error: "+ e,e);
        parent.failOnDiskError(e);
      }
catch (      PersistenceDisabledException e) {
        shutdown=true;
      }
catch (      Throwable e) {
        Logger.error(this,"Failed to decode " + this + " because of internal error: "+ e,e);
        parent.fail(new FetchException(FetchExceptionMode.INTERNAL_ERROR,e));
      }
 finally {
        chunk.release();
synchronized (SplitFileFetcherSegmentStorage.this) {
          tryDecode=false;
        }
        try {
          if (!shutdown)           parent.finishedEncoding(SplitFileFetcherSegmentStorage.this);
        }
  finally {
          if (lock != null)           lock.unlock(false,MemoryLimitedJobRunner.THREAD_PRIORITY);
        }
      }
      return true;
    }
  }
);
  return true;
}

