@Test public void testInsertMulti() throws IOException {
  final byte[] helloWorld=new byte[]{0x16,0x00,0x00,0x00,0x02,(byte)'h',(byte)'e',(byte)'l',(byte)'l',(byte)'o',0x00,0x06,0x00,0x00,0x00,(byte)'w',(byte)'o',(byte)'r',(byte)'l',(byte)'d',0x00,0x00};
  connect();
  assertTrue("Should have connected to the server.",ourServer.waitForClient(TimeUnit.SECONDS.toMillis(10)));
  final DocumentBuilder builder=BuilderFactory.start();
  builder.addString("hello","world");
  final Document doc=builder.build();
  final List<Document> multi=Arrays.asList(doc,doc);
  final Insert insert=new Insert("foo","bar",multi,true);
  myTestConnection.send(insert,null);
  assertTrue("Should receive the request after flush.",ourServer.waitForRequest(1,TimeUnit.SECONDS.toMillis(10)));
  final byte[] request=ourServer.getRequests().get(0);
  final int expectedLength=(5 * 4) + 8 + helloWorld.length+ helloWorld.length;
  assertEquals("Request length is wrong.",expectedLength,request.length);
  final IntBuffer asInts=ByteBuffer.wrap(request).asIntBuffer();
  assertEquals("Message size is wrong.",expectedLength,EndianUtils.swap(asInts.get(0)));
  assertTrue("Request id should not be one.",asInts.get(1) != 1);
  assertEquals("Response id should be zero.",0,asInts.get(2));
  assertEquals("Wrong OP code.",Operation.INSERT.getCode(),EndianUtils.swap(asInts.get(3)));
  assertEquals("Flags should be one.",1,EndianUtils.swap(asInts.get(4)));
  assertArrayEquals("Collection name is wrong.",new byte[]{'f','o','o','.','b','a','r',0},Arrays.copyOfRange(request,20,28));
  assertArrayEquals("The end of the request should be the hello world document.",helloWorld,Arrays.copyOfRange(request,(request.length - helloWorld.length) - helloWorld.length,request.length - helloWorld.length));
  assertArrayEquals("The end of the request should be the hello world document.",helloWorld,Arrays.copyOfRange(request,request.length - helloWorld.length,request.length));
}

